// Persian question fields translated with Google Translate; English remains the exam language.
const questionBank = [
{"id":"az802-q-001","domain":"Deploy and manage AD DS","text":"Which FSMO role allocates RID pools to domain controllers?","options":["RID Master","Schema Master","Infrastructure Master","PDC Emulator"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"نقش RID Master مجموعه‌های شناسه نسبی (RID pools) را تخصیص می‌دهد تا کنترل‌کننده‌های دامنه بتوانند SIDهای (شناسه امنیتی) منحصربه‌فردی برای عناصر امنیتی (Security Principals) ایجاد کنند.","en":"The RID Master allocates relative identifier pools so domain controllers can create unique security principal SIDs.","de":"Die richtige Antwort ist „RID Master“; sie passt zum Bereich Deploy and manage AD DS und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام نقش FSMO وظیفه تخصیص مجموعه‌های RID (شناسه نسبی) به کنترل‌کننده‌های دامنه را بر عهده دارد؟","optionsFa":["RID Master","Schema Master","Infrastructure Master","PDC Emulator"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-fsmo-roles","https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/fsmo-roles"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage and troubleshoot Flexible Single-Master Operations (FSMO) roles","objectiveId":"adds-fsmo-roles","topic":"FSMO roles","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-fsmo-roles","https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/fsmo-roles"],"keyPoints":["Every domain has three domain-wide operations master roles: RID Master, PDC Emulator, and Infrastructure Master.","Schema Master and Domain Naming Master are forest-wide, so they exist once per forest rather than once per domain.","The RID Master hands out a pool of relative IDs to each domain controller so new security principals such as users, groups, and computers receive unique SIDs.","A domain controller keeps creating objects from the pool it already holds while the RID Master is unreachable, and requests another block as that pool is consumed."],"whyOthers":["","Schema Master is the forest-wide role that governs writes to the schema naming context, which defines object classes and attributes. It would be the correct answer if the question asked which role must update the schema, but it never allocates relative ID pools.","Infrastructure Master keeps references from objects in its own domain pointing at objects in other domains, including group-to-user references after a rename. It would be the correct answer for stale cross-domain group membership, not for allocating identifiers.","PDC Emulator receives priority replication of password changes, processes account lockouts, and acts as the preferred time source for the domain. It would be the correct answer for an urgent password-change check, not for RID allocation."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 Active Directory Domain Services. FSMO roles are single-master: each role is held by exactly one domain controller at a time. Reading the role holders needs the ActiveDirectory PowerShell module or the netdom/Ntdsutil command-line tools.","commandPath":[{"label":"Show all five FSMO role holders from a domain-joined server","command":"netdom query fsmo"},{"label":"Read the three domain-wide role holders with PowerShell","command":"Get-ADDomain | Select-Object RIDMaster, PDCEmulator, InfrastructureMaster"},{"label":"Read the two forest-wide role holders with PowerShell","command":"Get-ADForest | Select-Object SchemaMaster, DomainNamingMaster"}],"translations":"runtime-google"},
{"id":"az802-q-002","domain":"Deploy and manage AD DS","text":"Which FSMO role is required to make forest-wide schema changes?","options":["Schema Master","RID Master","Domain Naming Master","PDC Emulator"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"نقش Schema Master به‌روزرسانی‌های Schema مربوط به Forest را کنترل می‌کند؛ Schema تعیین‌کننده کلاس‌های شیء (Object Classes) و ویژگی‌ها (Attributes) است.","en":"The Schema Master controls updates to the forest schema, which defines object classes and attributes.","de":"Die richtige Antwort ist „Schema Master“; sie passt zum Bereich Deploy and manage AD DS und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"برای اعمال تغییرات در Schema (طرح‌واره) در سطح کل Forest (جنگل)، به کدام نقش FSMO نیاز است؟","optionsFa":["Schema Master","RID Master","Domain Naming Master","PDC Emulator"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-fsmo-roles","https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/transfer-or-seize-operation-master-roles-in-ad-ds"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage and troubleshoot Flexible Single-Master Operations (FSMO) roles","objectiveId":"adds-fsmo-roles","topic":"FSMO roles","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-fsmo-roles","https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/transfer-or-seize-operation-master-roles-in-ad-ds"],"keyPoints":["Schema Master is a forest-wide role: one domain controller in the forest holds it.","It governs writes to the schema naming context, which defines which object classes and attributes can exist.","A schema change affects every domain in the forest, which is why only a single role holder accepts the write."],"whyOthers":["","RID Master is a domain-wide role that allocates pools of relative IDs to domain controllers. It would be correct for creating security principals, never for writing schema definitions.","Domain Naming Master adds and removes domain and application directory partitions and keeps names unique in the forest. It controls the forest namespace, not the schema contents.","PDC Emulator handles priority replication of password changes, account lockouts, and the preferred time source. It does not write the schema."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 AD DS. Writing the schema requires membership of Schema Admins in the forest root domain. The change replicates to the other domain controllers afterwards, so the whole forest is affected.","commandPath":[{"label":"Read the forest Schema Master with PowerShell","command":"Get-ADForest | Select-Object SchemaMaster"},{"label":"Read the current schema version on a domain controller","command":"Get-ADObject (Get-ADRootDSE).schemaNamingContext -Property objectVersion"}],"translations":"runtime-google"},
{"id":"az802-q-003","domain":"Deploy and manage AD DS","text":"Which FSMO role approves adding or removing domains in a forest?","options":["RID Master","Domain Naming Master","Infrastructure Master","PDC Emulator"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"en":"Domain Naming Master manages forest domain additions and removals. Windows Server 2025 does not require its holder to be a global catalog.","fa":"Domain Naming Master افزودن و حذف دامین‌های جنگل را مدیریت می‌کند. در Windows Server 2025 لازم نیست دارندهٔ این نقش سرور Global Catalog باشد.","de":"Der Domain Naming Master verwaltet das Hinzufügen und Entfernen von Domänen im Forest. Unter Windows Server 2025 muss sein Besitzer kein Global Catalog sein."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام نقش FSMO افزودن یا حذف دامنه‌ها در یک Forest را تأیید می‌کند؟","optionsFa":["RID Master","Domain Naming Master","Infrastructure Master","PDC Emulator"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-fsmo-roles","https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/fsmo-placement-and-optimization-on-ad-dcs"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"Official Microsoft technical and guide review for Windows Server 2025; prior originality, translation and distractor audit statuses retained","reviewedAt":"2026-10-09T19:11:36.000Z"},"objective":"Manage and troubleshoot Flexible Single-Master Operations (FSMO) roles","objectiveId":"adds-fsmo-roles","topic":"FSMO roles","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-fsmo-roles","https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/fsmo-placement-and-optimization-on-ad-dcs"],"keyPoints":["Domain Naming Master is a forest-wide role, so one domain controller in the forest holds it.","It adds and removes domain directory partitions and application directory partitions.","It also guarantees that domain names remain unique across the forest."],"whyOthers":["RID Master allocates relative ID pools so domain controllers can create unique SIDs for new security principals. Forest namespace changes are not its task.","","Infrastructure Master maintains references from objects in its own domain to objects in other domains, including group-to-user references after a rename.","PDC Emulator receives priority replication of password changes, processes lockouts, and provides the preferred time source."],"requirements":"For Windows Server 2025 AD DS, the Domain Naming Master must be available for forest namespace changes. It does not have to be a global catalog server; that requirement applied to Windows 2000. Verify replication and deliberate role placement before changing ownership.","commandPath":[{"label":"Read the forest Domain Naming Master","command":"Get-ADForest | Select-Object DomainNamingMaster"}],"translations":"runtime-google"},
{"id":"az802-q-004","domain":"Deploy and manage AD DS","text":"Which FSMO role is the preferred target for urgent password-change checks?","options":["Schema Master","PDC Emulator","Domain Naming Master","Infrastructure Master"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"en":"The PDC Emulator receives preferential password updates and helps other controllers check recently changed passwords.","fa":"PDC Emulator به‌روزرسانی‌های رمز عبور را با اولویت دریافت می‌کند و به کنترل‌کننده‌های دیگر برای بررسی رمزهای تازه‌تغییریافته کمک می‌کند.","de":"Der PDC-Emulator erhält Kennwortänderungen bevorzugt und hilft anderen Domänencontrollern, kürzlich geänderte Kennwörter zu prüfen."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام نقش FSMO گزینه ارجح برای بررسی‌های فوری تغییر رمز عبور است؟","optionsFa":["Schema Master","PDC Emulator","Domain Naming Master","Infrastructure Master"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-fsmo-roles","https://learn.microsoft.com/en-us/windows-server/networking/windows-time-service/windows-time-service-tools-and-settings"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"Official Microsoft technical and guide review for Windows Server 2025; prior originality, translation and distractor audit statuses retained","reviewedAt":"2026-10-09T19:11:36.000Z"},"objective":"Manage and troubleshoot Flexible Single-Master Operations (FSMO) roles","objectiveId":"adds-fsmo-roles","topic":"FSMO roles","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-fsmo-roles","https://learn.microsoft.com/en-us/windows-server/networking/windows-time-service/windows-time-service-tools-and-settings"],"keyPoints":["The PDC Emulator receives preferential replication of password changes made on other domain controllers.","When a sign-in fails because of a bad password, the PDC Emulator is the source of the latest password information.","It also processes account lockouts, so a just-changed password or a lockout is checked there first."],"whyOthers":["Schema Master governs writes to the schema naming context. It has no role in password replication.","","Domain Naming Master manages domain and application directory partitions. It does not hold password state.","Infrastructure Master maintains cross-domain object references and group membership references. It does not hold the newest password copy."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 AD DS. The PDC Emulator role creates the greatest workload of the five roles, and the PDC Emulator in the forest root domain is the authoritative Windows Time source for the forest.","commandPath":[{"label":"Read the domain PDC Emulator","command":"Get-ADDomain | Select-Object PDCEmulator"},{"label":"Read this computer's configured time source (not necessarily the PDC)","command":"w32tm /query /source"}],"translations":"runtime-google"},
{"id":"az802-q-005","domain":"Deploy and manage AD DS","text":"What is the primary purpose of the Infrastructure Master?","options":["Update references to objects in other domains","Generate DNS zones","Assign IP addresses","Allocate user logon hours"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"en":"Infrastructure Master maintains references to objects in other domains. With all DCs acting as GCs or Recycle Bin enabled, that maintenance does not require this role.","fa":"Infrastructure Master ارجاع به اشیای دامین‌های دیگر را نگه‌داری می‌کند. اگر همهٔ DCها نقش GC داشته باشند یا Recycle Bin فعال باشد، این نگه‌داری به این نقش نیاز ندارد.","de":"Der Infrastructure Master pflegt Verweise auf Objekte anderer Domänen. Sind alle DCs Global Catalogs oder ist der Papierkorb aktiviert, ist diese Pflege nicht auf die Rolle angewiesen."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"هدف اصلی نقش Infrastructure Master چیست؟","optionsFa":["به‌روزرسانی ارجاعات به اشیاء (Objects) در دامین‌های دیگر","ایجاد زون‌های DNS","تخصیص آدرس‌های IP","تعیین ساعات مجاز ورود (Logon) کاربران"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-fsmo-roles","https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/fsmo-placement-and-optimization-on-ad-dcs","https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/transfer-or-seize-operation-master-roles-in-ad-ds"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"Official Microsoft technical and guide review for Windows Server 2025; prior originality, translation and distractor audit statuses retained","reviewedAt":"2026-10-09T19:11:36.000Z"},"objective":"Manage and troubleshoot Flexible Single-Master Operations (FSMO) roles","objectiveId":"adds-fsmo-roles","topic":"FSMO roles","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-fsmo-roles","https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/fsmo-placement-and-optimization-on-ad-dcs","https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/transfer-or-seize-operation-master-roles-in-ad-ds"],"keyPoints":["Infrastructure Master manages references from objects in its own domain to objects in other domains.","It also updates group-to-user references when the members of a group are renamed or changed.","It represents those references by GUID, SID, or distinguished name of the referenced object."],"whyOthers":["","DNS zones are created and managed by the DNS Server role, including Active Directory-integrated zones. No FSMO role generates zones.","IP addresses are assigned by the DHCP Server role. Address assignment is unrelated to directory references.","Logon hours are an attribute of a user account, evaluated during authentication. No FSMO role assigns them."],"requirements":"For Windows Server 2025 AD DS, the Infrastructure Master maintains cross-domain references where that work is needed. It can be on any DC if all domain DCs are global catalogs or AD Recycle Bin is enabled. Otherwise, in a multidomain forest, place it on a non-GC DC. A single-domain forest has no cross-domain reference maintenance to perform.","commandPath":[{"label":"Read the Infrastructure Master","command":"Get-ADDomain | Select-Object InfrastructureMaster"},{"label":"Confirm whether a controller is a global catalog","command":"Get-ADDomainController -Filter * | Select-Object Name, IsGlobalCatalog"}],"translations":"runtime-google"},
{"id":"az802-q-006","domain":"Deploy and manage AD DS","text":"A domain controller cannot contact the current RID Master. What is the immediate consequence?","options":["The controller can use its remaining RID pool but eventually cannot create new security principals","DNS stops resolving every name","Existing users cannot log on","The domain schema becomes read-only"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"کنترلر می‌تواند از RIDهای از پیش تخصیص‌یافته استفاده کند، اما برای دریافت استخر (Pool) جدید، به RID Master نیاز دارد.","en":"A controller can consume already allocated RIDs, but it needs the RID Master to obtain another pool.","de":"Die richtige Antwort ist „The controller can use its remaining RID pool but eventually cannot create new security principals“; sie passt zum Bereich Deploy and manage AD DS und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"یک دامین کنترلر نمی‌تواند با RID Master فعلی ارتباط برقرار کند. پیامد فوری آن چیست؟","optionsFa":["کنترلر می‌تواند از استخر (Pool) RID باقی‌مانده خود استفاده کند، اما در نهایت قادر به ایجاد Security Principalهای جدید نخواهد بود.","سرویس DNS دیگر هیچ نامی را ترجمه (Resolve) نمی‌کند.","کاربران موجود نمی‌توانند وارد سیستم (Log on) شوند.","شمای دامین (Domain Schema) به حالت فقط‌خواندنی (Read-only) درمی‌آید."],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-fsmo-roles","https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/fsmo-roles"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage and troubleshoot Flexible Single-Master Operations (FSMO) roles","objectiveId":"adds-fsmo-roles","topic":"FSMO roles","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-fsmo-roles","https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/fsmo-roles"],"keyPoints":["Each domain controller draws new security identifiers from the RID pool it already holds.","When the pool is consumed, the controller requests another block from the RID Master.","The symptom is delayed: existing objects and logons keep working until a controller exhausts its pool and can no longer create new security principals."],"whyOthers":["","DNS resolution is provided by the DNS Server service and does not depend on RID allocation.","Existing users can still sign in, because authentication does not require a new RID.","The schema is governed by Schema Master. RID Master availability has no effect on whether the schema can be written."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 AD DS. Losing the RID Master is not immediately visible; monitor event log entries about RID pool allocation and use dcdiag to confirm the role holder's health.","commandPath":[{"label":"Confirm the current RID Master","command":"Get-ADDomain | Select-Object RIDMaster"},{"label":"Review replication and role health","command":"dcdiag /test:ridmanager /v"}],"translations":"runtime-google"},
{"id":"az802-q-007","domain":"Deploy and manage AD DS","text":"Which command is designed to display the current FSMO role owners?","options":["gpresult /r","dcdiag /test:dns","netdom query fsmo","repadmin /showrepl"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"دستور netdom query fsmo دارندگان پنج نقش FSMO را برای دامین (Domain) و فارست (Forest) گزارش می‌دهد.","en":"netdom query fsmo reports the five FSMO role holders for the domain and forest.","de":"Die richtige Antwort ist „netdom query fsmo“; sie passt zum Bereich Deploy and manage AD DS und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام دستور برای نمایش دارندگان فعلی نقش‌های FSMO طراحی شده است؟","optionsFa":["gpresult /r","dcdiag /test:dns","netdom query fsmo","repadmin /showrepl"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/netdom-query","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-fsmo-roles"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage and troubleshoot Flexible Single-Master Operations (FSMO) roles","objectiveId":"adds-fsmo-roles","topic":"FSMO roles","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/netdom-query","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-fsmo-roles"],"keyPoints":["netdom query fsmo reports all five role holders in a single command.","It runs from a domain-joined server and needs the netdom tool, which ships with Remote Server Administration Tools.","Ntdsutil is the tool that can both display and move the roles when a transfer or seizure is required."],"whyOthers":["gpresult /r reports the Resultant Set of Policy applied to a user or computer. It does not list FSMO owners.","dcdiag /test:dns verifies DNS health for domain controllers. It does not list FSMO owners.","","repadmin /showrepl shows inbound replication status and the result of the last replication attempt between directory partitions. It does not name the FSMO owners."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 AD DS. Reading the role holders is a read-only operation. The PowerShell alternative needs the ActiveDirectory module, which is installed with RSAT.","commandPath":[{"label":"List all five FSMO role holders","command":"netdom query fsmo"},{"label":"Compare the domain-wide role holders","command":"Get-ADDomain | Select-Object RIDMaster, PDCEmulator, InfrastructureMaster"},{"label":"Compare the forest-wide role holders","command":"Get-ADForest | Select-Object SchemaMaster, DomainNamingMaster"}],"translations":"runtime-google"},
{"id":"az802-q-008","domain":"Deploy and manage AD DS","text":"A forest-wide role holder has failed permanently. Which operation moves the role to a new controller without expecting the old controller to return?","options":["Replication","Seizing the role","Delegating DNS","Promoting a member server"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"en":"Seize the role when the failed holder cannot transfer it. Clean up the former controller before reusing it.","fa":"وقتی دارندهٔ خراب نقش نمی‌تواند آن را منتقل کند، نقش را تصاحب کنید. پیش از استفادهٔ دوباره، کنترل‌کنندهٔ قبلی را پاک‌سازی کنید.","de":"Übernehmen Sie die Rolle zwangsweise, wenn der ausgefallene Besitzer sie nicht übertragen kann. Bereinigen Sie den früheren Controller vor seiner Wiederverwendung."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"یک سرورِ دارنده نقش در سطح فارست (forest-wide role holder) دچار خرابی دائمی شده است. کدام عملیات نقش را به یک کنترلر جدید منتقل می‌کند، بدون آنکه انتظار بازگشت کنترلر قدیمی وجود داشته باشد؟","optionsFa":["Replication (همگام‌سازی/تکثیر)","Seizing the role (تصاحب نقش)","Delegating DNS (تفویض DNS)","Promoting a member server (ارتقای یک سرور عضو)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/transfer-or-seize-operation-master-roles-in-ad-ds","https://learn.microsoft.com/en-us/powershell/module/activedirectory/move-addirectoryserveroperationmasterrole?view=windowsserver2025-ps"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"Official Microsoft technical and guide review for Windows Server 2025; prior originality, translation and distractor audit statuses retained","reviewedAt":"2026-10-09T19:11:36.000Z"},"objective":"Manage and troubleshoot Flexible Single-Master Operations (FSMO) roles","objectiveId":"adds-fsmo-roles","topic":"FSMO roles","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/transfer-or-seize-operation-master-roles-in-ad-ds","https://learn.microsoft.com/en-us/powershell/module/activedirectory/move-addirectoryserveroperationmasterrole?view=windowsserver2025-ps"],"keyPoints":["Seizure is recovery when a role cannot be transferred and the previous holder is permanently unavailable in this scenario.","Move-ADDirectoryServerOperationMasterRole with -Force attempts a graceful transfer first and seizes only if transfer fails.","Before reusing a former holder as a DC, rebuild it or forcibly demote it and clean up its metadata; do not reconnect its original DC state as a recovery shortcut."],"whyOthers":["Replication copies directory data between domain controllers. It never transfers ownership of a single-master role.","","Delegating DNS changes who administers DNS zones. It has no effect on FSMO role ownership.","Promoting a member server adds another domain controller to the domain, but the role stays where it is until it is moved."],"requirements":"For Windows Server 2025 AD DS, choose a healthy writable DC with an up-to-date role partition. Use appropriate Enterprise Admin rights for forest roles or Domain Admin rights for domain roles. Verify ownership and replication afterwards. Seizing RID Master consumes additional RIDs, so it is not a routine transfer technique.","commandPath":[{"label":"Preview Schema Master seizure for a permanently failed forest-role holder","command":"Move-ADDirectoryServerOperationMasterRole -Identity DC02 -OperationMasterRole SchemaMaster -Force -WhatIf"},{"label":"Verify current forest-role owners","command":"Get-ADForest | Select-Object SchemaMaster, DomainNamingMaster"}],"translations":"runtime-google"},
{"id":"az802-q-009","domain":"Deploy and manage AD DS","text":"What is the normal purpose of transferring an FSMO role?","options":["Rebuild SYSVOL","Convert a member server into an RODC","Change a domain functional level","Move it gracefully while the current owner is available"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"en":"Transfer gracefully changes ownership while the current role holder is reachable; seizure is a separate recovery path.","fa":"انتقال عادی، وقتی دارندهٔ فعلی نقش در دسترس است، مالکیت را هماهنگ تغییر می‌دهد؛ تصاحب نقش مسیر جداگانهٔ بازیابی است.","de":"Eine Übertragung wechselt den Besitzer geordnet, solange der bisherige Rolleninhaber erreichbar ist; eine erzwungene Übernahme dient der Wiederherstellung."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"هدف معمول از انتقال (Transfer) یک نقش FSMO چیست؟","optionsFa":["بازسازی SYSVOL","تبدیل یک سرور عضو (Member Server) به RODC","تغییر سطح عملکردی دامنه (Domain Functional Level)","انتقال آن به روشی ایمن و منظم (Graceful) در حالی که مالک فعلی در دسترس است"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/transfer-or-seize-operation-master-roles-in-ad-ds","https://learn.microsoft.com/en-us/powershell/module/activedirectory/move-addirectoryserveroperationmasterrole?view=windowsserver2025-ps"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"Official Microsoft technical and guide review for Windows Server 2025; prior originality, translation and distractor audit statuses retained","reviewedAt":"2026-10-09T19:11:36.000Z"},"objective":"Manage and troubleshoot Flexible Single-Master Operations (FSMO) roles","objectiveId":"adds-fsmo-roles","topic":"FSMO roles","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/transfer-or-seize-operation-master-roles-in-ad-ds","https://learn.microsoft.com/en-us/powershell/module/activedirectory/move-addirectoryserveroperationmasterrole?view=windowsserver2025-ps"],"keyPoints":["A transfer moves a role between domain controllers while the current holder is online and reachable.","A seizure is the recovery path when the holder cannot be contacted and will not return.","Plan a transfer before you patch or decommission the controller that holds a role, so the role is never lost with the hardware."],"whyOthers":["SYSVOL repair uses its own replication and recovery procedures; a role transfer does not rebuild SYSVOL.","Promoting a member server as an RODC is a deployment operation, not a graceful handoff of an existing FSMO role.","Raising a domain functional level changes supported directory behavior; transferring a role only changes its owner.",""],"requirements":"For Windows Server 2025 AD DS, use the ActiveDirectory PowerShell module or the GUI tool for the specific role. The current owner must be reachable and the destination must be an appropriate writable DC. Use Domain Admin rights for domain roles or Enterprise Admin rights for forest roles. Preview a planned move with -WhatIf.","commandPath":[{"label":"Preview a graceful RID Master transfer to DC02","command":"Move-ADDirectoryServerOperationMasterRole -Identity DC02 -OperationMasterRole RIDMaster -WhatIf"},{"label":"Verify domain-wide role owners","command":"Get-ADDomain | Select-Object RIDMaster, PDCEmulator, InfrastructureMaster"}],"translations":"runtime-google"},
{"id":"az802-q-010","domain":"Deploy and manage AD DS","text":"Which AD DS database file stores the directory database?","options":["pagefile.sys","winload.efi","bootmgr","ntds.dit"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"فایل ntds.dit حاوی پایگاه داده AD DS، شامل اشیاء دایرکتوری و ویژگی‌های (Attributes) آن‌هاست.","en":"ntds.dit contains the AD DS database, including directory objects and attributes.","de":"Die richtige Antwort ist „ntds.dit“; sie passt zum Bereich Deploy and manage AD DS und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام فایل پایگاه داده AD DS، پایگاه داده دایرکتوری را در خود جای داده است؟","optionsFa":["pagefile.sys","winload.efi","bootmgr","ntds.dit"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/training/modules/understand-active-directory-database/","https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/diagnose-replication-failures"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Deploy and manage AD DS domain controllers","objectiveId":"adds-domain-controllers","topic":"AD DS database and SYSVOL","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/0xc00002e1-error-start-domain-controller","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/deploy/rodc/install-a-windows-server-2012-active-directory-read-only-domain-controller--rodc---level-200-"],"keyPoints":["ntds.dit stores AD DS objects and their attributes.","Writable controllers can originate directory changes; an RODC keeps a read-only directory replica updated through inbound replication.","The directory database and SYSVOL use different replication mechanisms and health checks."],"whyOthers":["pagefile.sys is the Windows paging file used for virtual memory. It holds no directory data.","winload.efi is the Windows boot loader for UEFI firmware. It is unrelated to the directory database.","bootmgr is the Windows Boot Manager. It only selects and starts an operating system.",""],"requirements":"Use the installed AD DS management tools. Inspecting database files with ntdsutil requires AD DS to be stopped or Directory Services Restore Mode; do not interrupt a production controller just to answer this question.","commandPath":[{"label":"Inspect database and log paths only in an approved offline/DSRM lab session","command":"ntdsutil \"activate instance ntds\" files info quit quit"}],"translations":"runtime-google"},
{"id":"az802-q-011","domain":"Deploy and manage AD DS","text":"Which folder contains the SYSVOL share and domain Group Policy templates?","options":["C:\\ProgramData","C:\\Windows\\System32\\DNS","C:\\Windows\\NTDS","C:\\Windows\\SYSVOL"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"پوشه SYSVOL فایل‌های دامنه که بین سرورها همگام‌سازی (Replicate) می‌شوند، از جمله الگوهای Group Policy و اسکریپت‌های ورود (Logon Scripts) را ذخیره می‌کند.","en":"SYSVOL stores replicated domain files, including Group Policy templates and logon scripts.","de":"Die richtige Antwort ist „C:\\Windows\\SYSVOL“; sie passt zum Bereich Deploy and manage AD DS und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام پوشه شامل اشتراک SYSVOL و الگوهای «خط‌مشی گروهی» (Group Policy) دامنه است؟","optionsFa":["C:\\ProgramData","C:\\Windows\\System32\\DNS","C:\\Windows\\NTDS","C:\\Windows\\SYSVOL"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/group-policy/force-authoritative-non-authoritative-synchronization","https://learn.microsoft.com/en-us/training/modules/understand-active-directory-database/"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Deploy and manage AD DS domain controllers","objectiveId":"adds-domain-controllers","topic":"AD DS database and SYSVOL","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/group-policy/force-authoritative-non-authoritative-synchronization","https://learn.microsoft.com/en-us/training/modules/understand-active-directory-database/"],"keyPoints":["SYSVOL is a replicated share that holds domain Group Policy templates and logon scripts.","Every domain controller hosts it, and clients read policy through the SYSVOL share.","SYSVOL replicates separately from the directory database, so its health is diagnosed on its own."],"whyOthers":["C:\\ProgramData holds local application data. It does not hold the replicated domain policy share.","C:\\Windows\\System32\\DNS holds DNS data for the DNS Server role. It is unrelated to SYSVOL.","C:\\Windows\\NTDS holds the directory database and its transaction logs, not the Group Policy templates.",""],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 AD DS. SYSVOL must be shared on every domain controller; a controller whose SYSVOL is not shared cannot serve Group Policy correctly.","commandPath":[{"label":"Confirm the SYSVOL share is advertised","command":"net share"},{"label":"Check SYSVOL replication state with DFSR","command":"dfsrmig /getglobalstate"}],"translations":"runtime-google"},
{"id":"az802-q-012","domain":"Deploy and manage AD DS","text":"Which service is responsible for replicating SYSVOL on a modern domain?","options":["DFS Replication","Print Spooler","Windows Update","Server"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"سرویس DFS Replication (DFSR) وظیفه تکثیر SYSVOL را در پیاده‌سازی‌های فعلی AD DS بر عهده دارد؛ دامین‌های قدیمی‌تر ممکن است از FRS استفاده کرده باشند.","en":"DFS Replication (DFSR) replicates SYSVOL in current AD DS deployments; older domains may have used FRS.","de":"Die richtige Antwort ist „DFS Replication“; sie passt zum Bereich Deploy and manage AD DS und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام سرویس مسئول تکثیر (Replication) پوشه SYSVOL در یک دامین (Domain) مدرن است؟","optionsFa":["DFS Replication","Print Spooler","Windows Update","Server"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/dfsrmig"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"AD operations: Microsoft source and technical answer review; other audit flags retained from prior review","reviewedAt":"2026-10-09T00:00:00.000Z"},"objective":"Deploy and manage AD DS domain controllers","objectiveId":"adds-domain-controllers","topic":"AD DS database and SYSVOL","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/dfsrmig"],"keyPoints":["Current AD DS deployments replicate SYSVOL with DFS Replication (DFSR).","Older domains may have used File Replication Service (FRS), which is deprecated.","A SYSVOL disagreement is repaired with an authoritative or non-authoritative DFSR synchronisation, not by restarting the directory service."],"whyOthers":["","Print Spooler manages print jobs and printer drivers. It does not replicate SYSVOL.","Windows Update installs operating system and driver updates. It does not replicate SYSVOL.","The Server service publishes shared resources over SMB. It does not replicate file content between controllers."],"requirements":"Windows Server 2025/2022/2019/2016. These read-only commands report FRS-to-DFSR migration state, not complete replication health. Eliminated (3) is the final DFSR migration state; verify all DCs and inspect the DFS Replication event log before any repair.","commandPath":[{"label":"Read the SYSVOL migration global state","command":"dfsrmig /getglobalstate"},{"label":"Check whether all DCs reached the migration state","command":"dfsrmig /getmigrationstate"}],"translations":"runtime-google"},
{"id":"az802-q-013","domain":"Deploy and manage AD DS","text":"What is the main security benefit of a read-only domain controller (RODC)?","options":["It limits changes made locally and can restrict credential caching","It removes the need for DNS","It replaces every writable domain controller","It accepts unrestricted directory writes from branch users"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"استفاده از RODC در مکان‌هایی با امنیت پایین‌تر مفید است، زیرا مدیران محلی نمی‌توانند مستقیماً در دایرکتوری بنویسند و فرآیند تکثیر رمز عبور نیز قابل کنترل است.","en":"An RODC is useful in less-secure locations because local administrators cannot directly write the directory and password replication can be controlled.","de":"Die richtige Antwort ist „It limits changes made locally and can restrict credential caching“; sie passt zum Bereich Deploy and manage AD DS und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"مزیت امنیتی اصلی یک کنترل‌کننده دامین فقط‌خواندنی (RODC) چیست؟","optionsFa":["تغییرات محلی را محدود می‌کند و می‌تواند کش کردن (ذخیره‌سازی موقت) اطلاعات احراز هویت را محدود سازد.","نیاز به DNS را از بین می‌برد.","جایگزین تمام کنترل‌کننده‌های دامین با قابلیت نوشتن (Writable) می‌شود.","عملیات نوشتن نامحدود در دایرکتوری را از سوی کاربران شعب می‌پذیرد."],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/rodc-replicates-passwords-grant-incorrect-permissions","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-security-groups"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Deploy Read-Only Domain Controllers (RODCs)","objectiveId":"adds-rodc","topic":"RODC and password replication","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/rodc-replicates-passwords-grant-incorrect-permissions","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-security-groups"],"keyPoints":["An RODC holds a read-only copy of the directory partition and accepts no local directory writes.","A local administrator can administer the RODC without holding domain-wide administrator rights, which limits the damage a branch compromise can cause.","Credential caching is not automatic: it is controlled by the Password Replication Policy."],"whyOthers":["","An RODC still depends on DNS for name resolution. It does not remove the need for DNS.","An RODC is an addition to the domain. At least one writable domain controller is still required.","An RODC refuses local directory writes and forwards supported changes to a writable controller, so it never accepts unrestricted writes."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 AD DS. Deploying an RODC requires the forest functional level to support it and a writable Windows Server domain controller as its replication partner.","commandPath":[{"label":"Review an RODC Password Replication Policy","command":"Get-ADDomainControllerPasswordReplicationPolicy -Identity BRANCH-DC -Allowed"}],"translations":"runtime-google"},
{"id":"az802-q-014","domain":"Deploy and manage AD DS","text":"Which object controls which user credentials may be cached on an RODC?","options":["Default Domain Policy","DNS scavenging policy","Password Replication Policy","Fine-Grained Password Policy"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"en":"Password Replication Policy controls credential caching per RODC; deny entries override allow entries.","fa":"سیاست Password Replication Policy مشخص می‌کند اعتبارنامهٔ چه حساب‌هایی در هر RODC قابل ذخیره است؛ ورودی Deny بر Allow اولویت دارد.","de":"Die Password Replication Policy steuert den Kennwortcache je RODC; Deny hat Vorrang vor Allow."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام شیء (Object) تعیین می‌کند که اطلاعات احراز هویت کدام کاربران می‌تواند روی یک RODC کش (ذخیره موقت) شود؟","optionsFa":["خط‌مشی پیش‌فرض دامنه (Default Domain Policy)","خط‌مشی پاکسازی (Scavenging) در DNS","خط‌مشی تکثیر رمز عبور (Password Replication Policy)","خط‌مشی رمز عبور با جزئیات دقیق (Fine-Grained Password Policy)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/activedirectory/add-addomaincontrollerpasswordreplicationpolicy?view=windowsserver2025-ps","https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/rodc-replicates-passwords-grant-incorrect-permissions","https://learn.microsoft.com/en-us/powershell/module/activedirectory/get-addomaincontrollerpasswordreplicationpolicyusage?view=windowsserver2025-ps"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"AD operations: Microsoft source and technical answer review; other audit flags retained from prior review","reviewedAt":"2026-10-09T00:00:00.000Z"},"objective":"Manage account security on an RODC","objectiveId":"adds-rodc-account-security","topic":"RODC and password replication","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/activedirectory/add-addomaincontrollerpasswordreplicationpolicy?view=windowsserver2025-ps","https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/rodc-replicates-passwords-grant-incorrect-permissions","https://learn.microsoft.com/en-us/powershell/module/activedirectory/get-addomaincontrollerpasswordreplicationpolicyusage?view=windowsserver2025-ps"],"keyPoints":["Each RODC has an effective Password Replication Policy with allowed and denied accounts/groups.","The policy references are AD attributes on that RODC's computer object, including msDS-RevealOnDemandGroup and msDS-NeverRevealGroup; they are not a policy stored exclusively on its writable partner.","Deny takes priority. Permission to cache does not mean a password has already been cached; inspect revealed accounts separately."],"whyOthers":["Default Domain Policy is a Group Policy object. It configures settings, not which credentials an RODC may cache.","DNS scavenging removes stale DNS records on a schedule. It has no effect on credential caching.","","Fine-Grained Password Policy applies different password and lockout settings to selected users. It does not control caching."],"requirements":"Windows Server 2025 RODC administration. Make policy changes through a writable DC with appropriate rights and verify the policy for the specific RODC. Default groups are policy inputs; accounts can also be allowed or denied directly.","commandPath":[{"label":"List allowed and denied accounts for an RODC","command":"Get-ADDomainControllerPasswordReplicationPolicy -Identity BRANCH-DC -Allowed; Get-ADDomainControllerPasswordReplicationPolicy -Identity BRANCH-DC -Denied"}],"translations":"runtime-google"},
{"id":"az802-q-015","domain":"Deploy and manage AD DS","text":"A branch RODC must cache credentials only for branch employees. What should you configure?","options":["Move the users to the local Administrators group","Allow a branch-only security group in this RODC's Password Replication Policy","Disable Kerberos","Make the RODC a Global Catalog only"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"en":"Allow only the branch group on the specific RODC. A broad group containing all employees would permit caching outside the intended branch population.","fa":"فقط گروه مختص شعبه را در سیاست همان RODC مجاز کنید؛ گروه همهٔ کارکنان، ذخیرهٔ اعتبارنامهٔ افراد خارج از شعبه را نیز مجاز می‌کند.","de":"Erlauben Sie nur die Gruppe dieser Niederlassung auf dem betreffenden RODC. Eine Gruppe aller Beschäftigten erweitert den Cache über den gewünschten Personenkreis hinaus."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"یک RODC در شعبه باید اعتبارنامه‌ها را تنها برای کارکنان همان شعبه ذخیره (کش) کند. چه چیزی را باید پیکربندی کنید؟","optionsFa":["کاربران را به گروه Administrators محلی منتقل کنید","در Password Replication Policy این RODC، گروه امنیتی مختص همان شعبه را مجاز کنید","Kerberos را غیرفعال کنید","RODC را فقط Global Catalog کنید"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/activedirectory/add-addomaincontrollerpasswordreplicationpolicy?view=windowsserver2025-ps","https://learn.microsoft.com/en-us/powershell/module/activedirectory/get-addomaincontrollerpasswordreplicationpolicyusage?view=windowsserver2025-ps"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"AD operations: Microsoft source and technical answer review; other audit flags retained from prior review","reviewedAt":"2026-10-09T00:00:00.000Z"},"objective":"Manage account security on an RODC","objectiveId":"adds-rodc-account-security","topic":"RODC and password replication","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/activedirectory/add-addomaincontrollerpasswordreplicationpolicy?view=windowsserver2025-ps","https://learn.microsoft.com/en-us/powershell/module/activedirectory/get-addomaincontrollerpasswordreplicationpolicyusage?view=windowsserver2025-ps"],"keyPoints":["PRP is evaluated per RODC, so a branch-only group can be allowed without allowing every employee.","A deny entry overrides an allow entry.","Allowing an account and prepopulating its credential are different operations; check RevealedAccounts to confirm storage."],"whyOthers":["Local Administrators membership changes local administration, not which domain credentials PRP permits caching.","","Disabling Kerberos does not configure a branch-only password cache.","Global Catalog placement does not define PRP cache eligibility."],"requirements":"Windows Server 2025. Use an appropriately privileged account and a writable DC for PRP changes. Only approved branch identities should be allowed; verify caching separately before a WAN outage.","commandPath":[{"label":"LAB WRITE: allow only the branch group on this RODC","command":"Add-ADDomainControllerPasswordReplicationPolicy -Identity BRANCH-RODC -AllowedList 'Branch-Employees'"},{"label":"Read which approved credentials are actually cached","command":"Get-ADDomainControllerPasswordReplicationPolicyUsage -Identity BRANCH-RODC -RevealedAccounts"}],"translations":"runtime-google"},
{"id":"az802-q-016","domain":"Deploy and manage AD DS","text":"Which AD DS object represents a logical collection of users, computers, and other objects?","options":["Site link","Organizational unit (OU)","Replication connection","DNS resolver"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"واحدهای سازمانی (OUها) اشیاء دایرکتوری را سازماندهی کرده و دامنه‌ای برای تفویض اختیارات مدیریتی و پیوند دادن Group Policy فراهم می‌کنند.","en":"OUs organize directory objects and provide a scope for delegated administration and Group Policy linking.","de":"Die richtige Antwort ist „Organizational unit (OU)“; sie passt zum Bereich Deploy and manage AD DS und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام‌یک از اشیاء AD DS نشان‌دهنده مجموعه‌ای منطقی از کاربران، رایانه‌ها و سایر اشیاء است؟","optionsFa":["Site link (پیوند سایت)","واحد سازمانی (OU)","اتصال تکثیر (Replication connection)","حل‌کننده DNS (DNS resolver)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-security-groups","https://learn.microsoft.com/en-us/training/modules/understand-active-directory-database/"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Create and manage AD DS security principals","objectiveId":"adds-security-principals","topic":"OUs and group scope","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-security-groups","https://learn.microsoft.com/en-us/training/modules/understand-active-directory-database/"],"keyPoints":["An organizational unit is a container used to organise objects inside a domain.","OUs are the scope for delegating administration and for linking Group Policy.","Moving an object between OUs keeps its identity and SID; it changes where policy and delegation apply."],"whyOthers":["A site link describes replication scheduling and cost between sites. It is a replication object, not a container for users.","","A replication connection defines inbound replication between two domain controllers. It holds no user objects.","A DNS resolver is a client component that resolves names to addresses. It is not a directory object."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 AD DS. An OU is a delegation and policy boundary, not a security boundary: it does not prevent a user from being granted rights elsewhere in the domain.","commandPath":[{"label":"Create an OU","command":"New-ADOrganizationalUnit -Name 'Branch Users' -Path 'OU=Branches,DC=contoso,DC=com'"},{"label":"List the OUs in a domain","command":"Get-ADOrganizationalUnit -Filter * | Select-Object Name, DistinguishedName"}],"translations":"runtime-google"},
{"id":"az802-q-017","domain":"Deploy and manage AD DS","text":"Which group scope can contain members from trusted domains and be assigned permissions in its own domain?","options":["Global","Universal","Local computer","Domain Local"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"گروه‌های «محلیِ دامین» (Domain Local) می‌توانند شامل حساب‌های کاربری و گروه‌هایی از دامین‌های مورد اعتماد باشند و برای اختصاص مجوزهای دسترسی به منابع در دامین خودشان در نظر گرفته شده‌اند.","en":"Domain local groups can contain accounts and groups from trusted domains and are intended for assigning resource permissions in their domain.","de":"Die richtige Antwort ist „Domain Local“; sie passt zum Bereich Deploy and manage AD DS und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام دامنه (Scope) گروه می‌تواند شامل اعضایی از دامین‌های مورد اعتماد (Trusted Domains) باشد و در دامین خود مجوزهایی به آن اختصاص یابد؟","optionsFa":["Global (سراسری)","Universal (جامع)","Local computer (محلیِ رایانه)","Domain Local (محلیِ دامین)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-security-groups"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Create and manage AD DS users and groups","objectiveId":"adds-users-groups","topic":"OUs and group scope","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-security-groups"],"keyPoints":["Domain local groups are intended for assigning permissions to resources in the domain where the group is created.","They can contain accounts plus global and universal groups from trusted domains.","The classic nesting pattern is accounts into global groups, global groups into domain local groups, and permissions on the domain local group."],"whyOthers":["Global groups hold accounts from their own domain and are used to group users by role. They cannot contain members from trusted domains.","Universal groups can contain members from any domain in the forest and are stored in the global catalog. They are used for forest-wide grouping rather than for assigning permissions on a resource in one domain.","There is no Active Directory group scope named local computer. The fourth scope is domain local; a local group on a member server is not a domain group scope.",""],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 AD DS. Group nesting across domains requires a trust, and universal group membership changes replicate to every global catalog server in the forest.","commandPath":[{"label":"Create a domain local group for a resource","command":"New-ADGroup -Name 'FS-Finance-Read' -GroupScope DomainLocal -Path 'OU=Groups,DC=contoso,DC=com'"},{"label":"Nest a global group inside it","command":"Add-ADGroupMember -Identity 'FS-Finance-Read' -Members 'GG-Finance'"}],"translations":"runtime-google"},
{"id":"az802-q-018","domain":"Deploy and manage AD DS","text":"Which group scope is normally used to group users from the same domain by job function?","options":["Universal only","Resource","Global","Domain Local"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"en":"Global groups collect accounts from their own domain and commonly represent a department or job role.","fa":"گروه‌های Global حساب‌های دامین خود را جمع می‌کنند و معمولاً یک بخش یا نقش شغلی را نشان می‌دهند.","de":"Globale Gruppen fassen Konten ihrer eigenen Domäne zusammen und bilden typischerweise eine Abteilung oder berufliche Rolle ab."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام دامنه گروه معمولاً برای دسته‌بندی کاربرانِ یک دامین واحد بر اساس وظایف شغلی استفاده می‌شود؟","optionsFa":["فقط Universal","Resource (مربوط به منابع)","Global","Domain Local"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-security-groups"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"Official Microsoft technical and guide review for Windows Server 2025; prior originality, translation and distractor audit statuses retained","reviewedAt":"2026-10-09T19:11:36.000Z"},"objective":"Create and manage AD DS users and groups","objectiveId":"adds-users-groups","topic":"Group scope and AGDLP","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-security-groups"],"keyPoints":["Global groups contain accounts from their own domain and are the usual way to group users by job function or department.","In the AGDLP model, accounts go into global groups, global groups are nested into domain local groups, and permissions are assigned to the domain local group.","Because global group membership is not replicated forest-wide, grouping users by role with global groups is cheaper than using universal groups."],"whyOthers":["Universal groups can contain members from any domain in the forest and their membership is replicated to every global catalog, which is more scope and more replication cost than grouping a single domain's users by role.","There is no Active Directory group scope named Resource. A resource is what receives the permission; the scope that carries that permission is domain local.","","Domain local groups are designed to receive permissions on resources in the domain, not to organise users by job function, so they are the end of the AGDLP chain rather than the beginning."],"requirements":"For Windows Server 2025 AD DS, a Global group can convert to Universal if it is not a member of another Global group. This restriction concerns membership in other groups, not whether the group contains a Global group. Review all scope-conversion constraints before changing scope."},
{"id":"az802-q-019","domain":"Deploy and manage AD DS","text":"Which group scope is most suitable for membership spanning multiple domains in a forest?","options":["Built-in local","Global","Universal","Domain Local only"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"گروه‌های «جامع» (Universal) می‌توانند شامل اعضایی از چندین دامین در یک فارست باشند؛ اگرچه اطلاعات عضویت آن‌ها در «کاتالوگ سراسری» (Global Catalog) تکثیر (Replicate) می‌شود.","en":"Universal groups can contain members from multiple domains in the forest, though their membership is replicated to the Global Catalog.","de":"Die richtige Antwort ist „Universal“; sie passt zum Bereich Deploy and manage AD DS und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام دامنه گروه برای عضویت‌هایی که چندین دامین را در یک فارست (Forest) پوشش می‌دهند، مناسب‌تر است؟","optionsFa":["Built-in local (محلیِ پیش‌فرض/داخلی)","Global","Universal","فقط Domain Local"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-security-groups"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Create and manage AD DS users and groups","objectiveId":"adds-users-groups","topic":"Group scope and AGDLP","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-security-groups","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/get-started/replication/active-directory-replication-concepts"],"keyPoints":["Universal groups can contain members from any domain in the forest, which is what makes them suitable for membership that spans multiple domains.","Their membership is stored in the global catalog and replicated forest-wide, so changes are more expensive than global or domain local membership changes.","A common pattern is to nest global groups from several domains into one universal group instead of adding individual accounts."],"whyOthers":["A built-in local group lives in the Builtin container of one domain, manages local server roles, and cannot hold members from another domain.","A global group can only contain members from its own domain, so it cannot span the forest on its own.","","A domain local group of another domain can appear in the membership of a domain local group, but a domain local group is scoped to resources in its own domain and its membership is not the forest-wide grouping the scenario needs."],"requirements":"Universal group membership is forest-wide directory information used during authorization. Multidomain logon normally needs a global catalog to retrieve universal membership, but configured Universal Group Membership Caching can serve previously cached membership locally. A local GC is not universally mandatory at every site."},
{"id":"az802-q-020","domain":"Deploy and manage AD DS","text":"In the AGDLP model, what does the final DLP represent?","options":["Local users and passwords","Domain Local groups assigned Permissions","LDAP providers","Logon policies"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"en":"AGDLP places Accounts in Global groups, then Domain Local groups, to which resource Permissions are assigned.","fa":"در AGDLP، حساب‌ها عضو گروه‌های Global می‌شوند، این گروه‌ها در گروه‌های Domain Local قرار می‌گیرند و مجوزهای منابع به گروه‌های Domain Local داده می‌شود.","de":"Bei AGDLP werden Konten in globale Gruppen und diese in domänenlokale Gruppen aufgenommen; die Ressource weist den domänenlokalen Gruppen Berechtigungen zu."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"در مدل AGDLP، بخش پایانی DLP چه مفهومی دارد؟","optionsFa":["کاربران محلی و رمزهای عبور","گروه‌های Domain Local که مجوزها به آن‌ها اختصاص می‌یابند","ارائه‌دهندگان LDAP","سیاست‌های ورود"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-security-groups"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"Official Microsoft technical and guide review for Windows Server 2025; prior originality, translation and distractor audit statuses retained","reviewedAt":"2026-10-09T19:11:36.000Z"},"objective":"Create and manage AD DS users and groups","objectiveId":"adds-users-groups","topic":"Group scope and AGDLP","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-security-groups"],"keyPoints":["AGDLP stands for Accounts, Global groups, Domain Local groups, Permissions, read left to right.","The final LP is the Domain Local group that receives the Permissions on the resource.","Keeping the permission on the domain local group means access is granted and revoked by changing group membership, not by editing resource ACLs."],"whyOthers":["Local users and passwords is a misreading; the A at the start of the model already stands for the user accounts, and passwords play no part in the acronym.","","LDAP is the directory access protocol clients use to query AD DS; it is not one of the four steps in the permission model.","Logon policies constrain when and where a user may sign in and are configured by policy; they are separate from how resource permissions are assigned."],"requirements":"For Windows Server 2025 AD DS, use eligible security-group nesting. Domain Local resource groups can contain Global groups from trusted domains, so crossing a domain does not automatically require a Universal group. Universal groups can aggregate roles across domains when that extra layer is appropriate."},
{"id":"az802-q-021","domain":"Deploy and manage AD DS","text":"A user needs access to a shared folder but should not receive direct ACL entries. What is the best approach?","options":["Add the user to a role group and assign that group to a resource-permission group","Make the user a domain administrator","Disable inheritance on the folder","Add the user directly to the folder ACL"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"مدیریت دسترسی مبتنی بر گروه، نسبت به مجوزهای مستقیم کاربر، برای حسابرسی، استانداردسازی و حذف آسان‌تر است.","en":"Group-based access is easier to audit, standardize, and remove than direct user permissions.","de":"Die richtige Antwort ist „Add the user to a role group and assign that group to a resource-permission group“; sie passt zum Bereich Deploy and manage AD DS und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کاربری نیاز به دسترسی به یک پوشه اشتراکی دارد اما نباید ورودی‌های ACL (لیست کنترل دسترسی) مستقیمی دریافت کند. بهترین رویکرد چیست؟","optionsFa":["افزودن کاربر به یک گروه نقش (role group) و اختصاص آن گروه به یک گروهِ دارای مجوز دسترسی به منابع (resource-permission group)","تبدیل کاربر به مدیر دامنه (Domain Administrator)","غیرفعال کردن وراثت (inheritance) برای آن پوشه","افزودن مستقیم کاربر به ACL پوشه"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-security-groups","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/delegating-administration-by-using-ou-objects"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Create and manage AD DS security principals","objectiveId":"adds-security-principals","topic":"Role-based access with groups","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-security-groups","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/delegating-administration-by-using-ou-objects"],"keyPoints":["Putting the user in a role group and nesting that group into a resource-permission group keeps the ACL free of per-user entries.","Access is audited and revoked by changing one group membership instead of editing every resource ACL.","This is the practical form of least privilege: the user gets exactly the role that is needed and nothing broader."],"whyOthers":["","Making the user a domain administrator grants full control of the domain, which is far more privilege than one shared folder requires.","Disabling inheritance changes which permissions the folder receives from its parent; it does not grant the user access and can silently remove permissions other users rely on.","Adding the user directly to the folder ACL is exactly the pattern the scenario wants to avoid, because a direct entry is hard to audit and easy to forget when the user changes roles."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 AD DS. Group nesting across domains requires a trust, and the resource-permission group must have the access type (Allow) set on the resource itself."},
{"id":"az802-q-022","domain":"Deploy and manage AD DS","text":"Which service account type automatically manages its password and is usable by multiple servers?","options":["Guest account","Temporary profile","Standard local user","Group Managed Service Account (gMSA)"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"en":"A gMSA lets Windows manage the password for a compatible service running on multiple authorized hosts.","fa":"gMSA به ویندوز اجازه می‌دهد رمز عبور سرویس سازگاری را که روی چند میزبان مجاز اجرا می‌شود مدیریت کند.","de":"Mit einem gMSA verwaltet Windows das Kennwort eines kompatiblen Dienstes, der auf mehreren berechtigten Hosts läuft."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام نوع حساب سرویس (Service Account) رمز عبور خود را به‌طور خودکار مدیریت می‌کند و توسط چندین سرور قابل استفاده است؟","optionsFa":["حساب مهمان (Guest account)","پروفایل موقت","کاربر محلی استاندارد","حساب سرویس مدیریت‌شده گروهی (gMSA)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/group-managed-service-accounts/group-managed-service-accounts/group-managed-service-accounts-overview","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-service-accounts","https://learn.microsoft.com/en-us/powershell/module/activedirectory/new-adserviceaccount?view=windowsserver2025-ps","https://learn.microsoft.com/en-us/windows-server/security/group-managed-service-accounts/create-the-key-distribution-services-kds-root-key"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"Official Microsoft technical and guide review for Windows Server 2025; prior originality, translation and distractor audit statuses retained","reviewedAt":"2026-10-09T19:11:36.000Z"},"objective":"Create and manage managed service accounts","objectiveId":"adds-service-accounts","topic":"Managed service accounts","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/group-managed-service-accounts/group-managed-service-accounts/group-managed-service-accounts-overview","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-service-accounts","https://learn.microsoft.com/en-us/powershell/module/activedirectory/new-adserviceaccount?view=windowsserver2025-ps","https://learn.microsoft.com/en-us/windows-server/security/group-managed-service-accounts/create-the-key-distribution-services-kds-root-key"],"keyPoints":["Windows manages a gMSA password; domain controllers compute it and authorized hosts retrieve it automatically.","One gMSA can support a compatible service on multiple authorized computers.","The default password rotation interval is 30 days; a different interval is selected at account creation. Password retrieval is controlled separately from application resource permissions."],"whyOthers":["Guest provides neither managed service passwords nor a shared managed identity for authorized hosts.","A temporary profile is a profile-loading fallback, not a service-account type.","A standard local user does not provide AD-managed password rotation and a shared domain service identity across authorized hosts.",""],"commandPath":[{"label":"Create a gMSA for a service that runs on several servers","command":"New-ADServiceAccount -Name svc-app -DNSHostName svc-app.contoso.com -PrincipalsAllowedToRetrieveManagedPassword 'APP-HOSTS'"},{"label":"Install and test the account on a host","command":"Install-ADServiceAccount svc-app; Test-ADServiceAccount svc-app"}],"requirements":"For Windows Server 2025 AD DS, verify gMSA application support, suitable DCs and an existing replicated KDS root key. If a key is first created, allow the documented replication delay of up to ten hours; do not backdate a key in production. Limit PrincipalsAllowedToRetrieveManagedPassword to the intended hosts."},
{"id":"az802-q-023","domain":"Deploy and manage AD DS","text":"A service runs on one server and supports sMSAs but cannot use a gMSA. Which account is preferable to a manually managed domain user?","options":["Built-in Administrator","Local System with unrestricted network access","Standalone Managed Service Account","Guest"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"en":"An sMSA provides managed credentials on one computer when the service supports that account type.","fa":"اگر سرویس از این نوع حساب پشتیبانی کند، sMSA اعتبارنامه‌های مدیریت‌شده را روی یک رایانه فراهم می‌کند.","de":"Ein sMSA stellt auf einem Computer verwaltete Anmeldedaten bereit, wenn der Dienst diesen Kontotyp unterstützt."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"سرویسی روی یک سرور اجرا می‌شود و از sMSA پشتیبانی می‌کند، اما نمی‌تواند از gMSA استفاده کند. کدام حساب نسبت به کاربر دامین با مدیریت دستی رمز عبور مناسب‌تر است؟","optionsFa":["حساب Administrator پیش‌فرض (Built-in)","حساب Local System با دسترسی نامحدود به شبکه","حساب سرویس مدیریت‌شده مستقل (sMSA)","حساب مهمان (Guest)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/group-managed-service-accounts/group-managed-service-accounts/group-managed-service-accounts-overview","https://learn.microsoft.com/en-us/powershell/module/activedirectory/new-adserviceaccount?view=windowsserver2025-ps","https://learn.microsoft.com/en-us/powershell/module/activedirectory/add-adcomputerserviceaccount?view=windowsserver2025-ps","https://learn.microsoft.com/en-us/powershell/module/activedirectory/install-adserviceaccount?view=windowsserver2025-ps","https://learn.microsoft.com/en-us/powershell/module/activedirectory/test-adserviceaccount?view=windowsserver2025-ps"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"Official Microsoft technical and guide review for Windows Server 2025; prior originality, translation and distractor audit statuses retained","reviewedAt":"2026-10-09T19:11:36.000Z"},"objective":"Create and manage managed service accounts","objectiveId":"adds-service-accounts","topic":"Managed service accounts","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/group-managed-service-accounts/group-managed-service-accounts/group-managed-service-accounts-overview","https://learn.microsoft.com/en-us/powershell/module/activedirectory/new-adserviceaccount?view=windowsserver2025-ps","https://learn.microsoft.com/en-us/powershell/module/activedirectory/add-adcomputerserviceaccount?view=windowsserver2025-ps","https://learn.microsoft.com/en-us/powershell/module/activedirectory/install-adserviceaccount?view=windowsserver2025-ps","https://learn.microsoft.com/en-us/powershell/module/activedirectory/test-adserviceaccount?view=windowsserver2025-ps"],"keyPoints":["An sMSA supplies Windows-managed credentials to a compatible service on a single computer.","The application must support sMSAs; lack of gMSA support alone does not prove this.","Create the account with -RestrictToSingleComputer, associate its computer, then install and test it on that host."],"whyOthers":["Built-in Administrator grants broad privileges and does not provide a dedicated managed service identity.","Local System is highly privileged locally and uses the computer identity on the network; it is not the dedicated sMSA described here.","","Guest does not supply automatically managed service credentials."],"commandPath":[{"label":"Preview standalone managed service-account creation","command":"New-ADServiceAccount -Name svc-legacy -RestrictToSingleComputer -WhatIf"},{"label":"After account creation, preview association with APP01","command":"Add-ADComputerServiceAccount -Identity APP01 -ServiceAccount svc-legacy -WhatIf"},{"label":"After provisioning and association, install and test locally on APP01","command":"Install-ADServiceAccount -Identity svc-legacy\nTest-ADServiceAccount -Identity svc-legacy"}],"requirements":"For Windows Server 2025 AD DS, verify sMSA support and associate the account with its one intended computer. -ManagedPasswordIntervalInDays is not part of New-ADServiceAccount's RestrictToSingleComputer parameter set. Run installation on the associated host."},
{"id":"az802-q-024","domain":"Deploy and manage AD DS","text":"What is the main reason to avoid using a domain administrator account for an application service?","options":["Domain administrators cannot run services","It creates excessive privilege and increases credential exposure","Services require local accounts only","Kerberos does not support services"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"در صورت به خطر افتادن (Compromise) چنین سرویسی، کنترل گسترده‌ای بر دایرکتوری و زیرساخت در معرض خطر قرار می‌گیرد.","en":"A compromised service would expose broad directory and infrastructure control.","de":"Die richtige Antwort ist „It creates excessive privilege and increases credential exposure“; sie passt zum Bereich Deploy and manage AD DS und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"دلیل اصلی برای پرهیز از استفاده از حساب مدیر دامنه (Domain Administrator) برای یک سرویسِ برنامه کاربردی چیست؟","optionsFa":["مدیران دامنه نمی‌توانند سرویس‌ها را اجرا کنند","این کار باعث ایجاد امتیازات بیش از حد (Excessive privilege) و افزایش احتمال افشای اعتبارنامه‌ها می‌شود","سرویس‌ها فقط به حساب‌های محلی نیاز دارند","پروتکل Kerberos از سرویس‌ها پشتیبانی نمی‌کند"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/security/group-managed-service-accounts/group-managed-service-accounts-overview","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-security-groups"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Create and manage managed service accounts","objectiveId":"adds-service-accounts","topic":"Service account security","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/security/group-managed-service-accounts/group-managed-service-accounts-overview","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-security-groups"],"keyPoints":["Running a service as a domain administrator exposes the whole directory and infrastructure to anything that compromises that service.","Least privilege limits the blast radius: a service should hold only the rights its function needs.","Managed service accounts exist to give services a scoped identity without a human-managed password."],"whyOthers":["Domain administrators can run services; the risk is the excessive privilege, not a technical limitation.","","Services can run under domain service identities, so local-only accounts are not required.","Kerberos supports service accounts and is used to authenticate services; it has no bearing on the privilege-exposure problem described."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 AD DS. The same least-privilege reasoning applies to Scheduled Tasks, IIS application pools, cluster service accounts, and SQL Server service accounts."},
{"id":"az802-q-025","domain":"Deploy and manage AD DS","text":"Which AD DS feature allows different password and lockout settings for selected users?","options":["DNS Policy","Loopback processing","DFS namespace","Fine-Grained Password Policy"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"سیاست‌های رمز عبور با جزئیات دقیق (Fine-grained password policies)، اشیاء PSO را برای کاربران خاص یا گروه‌های امنیتی سراسری (global security groups) در یک دامنه اعمال می‌کنند.","en":"Fine-grained password policies apply PSOs to specific users or global security groups within a domain.","de":"Die richtige Antwort ist „Fine-Grained Password Policy“; sie passt zum Bereich Deploy and manage AD DS und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام ویژگی AD DS امکان اعمال تنظیمات متفاوت برای رمز عبور و قفل‌شدن حساب (lockout) را برای کاربران منتخب فراهم می‌کند؟","optionsFa":["سیاست DNS (DNS Policy)","پردازش Loopback","فضای نام DFS (DFS namespace)","سیاست رمز عبور با جزئیات دقیق (Fine-Grained Password Policy)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/get-started/adac/fine-grained-password-policies","https://learn.microsoft.com/en-us/openspecs/windows_protocols/ms-adts/ad735d45-ba6a-42fc-a41c-e91ced8e72d9"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"AD operations: Microsoft source and technical answer review; other audit flags retained from prior review","reviewedAt":"2026-10-09T00:00:00.000Z"},"objective":"Configure and manage fine-grained password policies","objectiveId":"adds-fgpp","topic":"Fine-grained password policy","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/get-started/adac/fine-grained-password-policies","https://learn.microsoft.com/en-us/openspecs/windows_protocols/ms-adts/ad735d45-ba6a-42fc-a41c-e91ced8e72d9"],"keyPoints":["A Fine-Grained Password Policy is defined by a Password Settings Object (PSO) in AD DS.","A PSO applies to a single user or to a global security group within one domain, and it can set stricter password and lockout settings than the domain default.","PSOs are created and managed in Active Directory Administrative Center or with the ActiveDirectory PowerShell module."],"whyOthers":["DNS Policy controls name-resolution behaviour such as split-brain DNS and does not set password or lockout requirements.","Loopback processing changes how user Group Policy is applied on a computer; it has nothing to do with password settings.","A DFS namespace is a logical view of file shares and is unrelated to account passwords.",""],"commandPath":[{"label":"Create a PSO that enforces a longer password for administrators","command":"New-ADFineGrainedPasswordPolicy -Name AdminsPSO -Precedence 1 -MinPasswordLength 14 -ComplexityEnabled $true -LockoutThreshold 5 -LockoutDuration 00:30:00 -LockoutObservationWindow 00:30:00"},{"label":"Apply the PSO to an administrative group","command":"Add-ADFineGrainedPasswordPolicySubject -Identity AdminsPSO -Subjects 'Tier0-Admins'"}],"requirements":"Windows Server 2025 GUI guidance assumes domain functional level Windows Server 2012 or later; the underlying FGPP feature originated at Windows Server 2008 domain functional level. Distinct precedence values are recommended, not an AD invariant: the resultant-PSO algorithm resolves equal values with objectGUID. PSOs target domain users/global security groups, not OUs or computer accounts."},
{"id":"az802-q-026","domain":"Deploy and manage AD DS","text":"A password policy linked to an OU does not change a user's domain password requirements. Why?","options":["OUs cannot contain users","Kerberos ignores password policies","Domain password policy is normally defined at the domain level","Passwords are stored in DNS"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"en":"Domain account policy is defined at the domain root. Fine-grained PSOs provide user/group exceptions, independently of an OU-linked password GPO.","fa":"سیاست رمز عبور حساب‌های دامنه در ریشهٔ دامنه تعریف می‌شود؛ PSO برای کاربران یا گروه‌ها استثنا ایجاد می‌کند، نه GPO متصل به OU.","de":"Die Kennwortrichtlinie für Domänenkonten wird an der Domänenwurzel festgelegt. PSOs ermöglichen Ausnahmen für Benutzer oder Gruppen."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"سیاست رمز عبوری که به یک OU (واحد سازمانی) متصل شده است، الزامات رمز عبور دامنه کاربر را تغییر نمی‌دهد. چرا؟","optionsFa":["واحدهای سازمانی (OUها) نمی‌توانند شامل کاربر باشند","پروتکل Kerberos سیاست‌های رمز عبور را نادیده می‌گیرد","سیاست رمز عبور دامنه معمولاً در سطح دامنه تعریف می‌شود","رمزهای عبور در DNS ذخیره می‌شوند"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-10/security/threat-protection/security-policy-settings/account-policies","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/get-started/adac/fine-grained-password-policies","https://learn.microsoft.com/en-us/openspecs/windows_protocols/ms-adts/ad735d45-ba6a-42fc-a41c-e91ced8e72d9"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"AD operations: Microsoft source and technical answer review; other audit flags retained from prior review","reviewedAt":"2026-10-09T00:00:00.000Z"},"objective":"Configure and manage fine-grained password policies","objectiveId":"adds-fgpp","topic":"Fine-grained password policy","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-10/security/threat-protection/security-policy-settings/account-policies","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/get-started/adac/fine-grained-password-policies","https://learn.microsoft.com/en-us/openspecs/windows_protocols/ms-adts/ad735d45-ba6a-42fc-a41c-e91ced8e72d9"],"keyPoints":["The domain-wide account policy is defined by domain-root-linked GPOs and their applicable precedence; Default Domain Policy is the usual location, not the only possible GPO.","An OU-linked password policy cannot give a selected subset of domain users different domain password requirements; use PSOs for those exceptions.","Get-ADUserResultantPasswordPolicy returns a user's resultant PSO. If no PSO applies, the domain default policy is used; read it with Get-ADDefaultDomainPasswordPolicy."],"whyOthers":["OUs do contain users; the limitation is that account password policy is scoped to the domain rather than to the OU.","Kerberos enforces the resulting policy at sign-in; it does not ignore password policies.","","Passwords are stored as hashes in the directory database ntds.dit, never in DNS."],"commandPath":[{"label":"Read the user's effective PSO","command":"Get-ADUserResultantPasswordPolicy -Identity a.smith"},{"label":"Read the default policy when no PSO applies","command":"Get-ADDefaultDomainPasswordPolicy -Identity corp.contoso.com"}],"requirements":"Windows Server 2025. Keep domain account policy at the domain root and account for GPO precedence. A separate domain-root-linked GPO can take precedence over Default Domain Policy; a DC-OU link does not define separate domain-user password policy."},
{"id":"az802-q-027","domain":"Deploy and manage AD DS","text":"Which object is required for a computer to authenticate as a domain member?","options":["Local user profile","Computer account in AD DS","DNS forwarder only","DHCP reservation only"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"en":"The AD computer account supplies the machine's domain identity and the secret used to establish its secure channel.","fa":"حساب رایانه در AD هویت دامین دستگاه و راز موردنیاز برای برقراری کانال امن آن را فراهم می‌کند.","de":"Das AD-Computerkonto stellt die Domänenidentität des Geräts und das Geheimnis für seinen sicheren Kanal bereit."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"برای اینکه یک کامپیوتر بتواند به عنوان عضوی از دامنه احراز هویت شود، به کدام شیء (object) نیاز است؟","optionsFa":["پروفایل کاربری محلی (Local user profile)","حساب کامپیوتر در AD DS","فقط DNS forwarder","فقط رزرو DHCP"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/windows-security/broken-trust-relationship-domain-joined-device-its-domain-secure-channel-issues"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"Official Microsoft technical and guide review for Windows Server 2025; prior originality, translation and distractor audit statuses retained","reviewedAt":"2026-10-09T19:11:36.000Z"},"objective":"Manage AD DS computer accounts and secure channels","objectiveId":"adds-computer-accounts","topic":"Computer accounts and secure channel","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/windows-security/broken-trust-relationship-domain-joined-device-its-domain-secure-channel-issues"],"keyPoints":["An AD computer account provides a domain member's machine identity and the password used for its Netlogon secure channel.","A mismatch between local and AD machine-account secrets, an absent account or an unavailable DC can prevent machine authentication.","Cached interactive user sign-in may still succeed during a trust or connectivity failure; it does not prove machine trust is healthy."],"whyOthers":["A local user profile stores a user's environment settings and does not establish a machine's identity or trust with the domain.","","A DNS forwarder resolves names outside the domain and plays no part in machine authentication.","A DHCP reservation gives the machine a stable address but does not authenticate it to the domain."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 AD DS. Computer account passwords are managed by the Netlogon service and are stored in the local LSA secret rather than in the registry in clear text."},
{"id":"az802-q-028","domain":"Deploy and manage AD DS","text":"Which command tests whether a domain member computer's secure channel is healthy?","options":["Test-ComputerSecureChannel","Get-DnsServerZone","Get-Volume","Get-WindowsFeature"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"en":"Test-ComputerSecureChannel checks trust on the local domain member; it is not suitable for checking a domain controller.","fa":"Test-ComputerSecureChannel اعتماد رایانهٔ محلی عضو دامین را بررسی می‌کند؛ برای بررسی کنترل‌کنندهٔ دامین مناسب نیست.","de":"Test-ComputerSecureChannel prüft das Vertrauen des lokalen Domänenmitglieds; für die Prüfung eines Domänencontrollers ist das Cmdlet ungeeignet."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام دستور سالم بودن کانال امن رایانهٔ عضو دامین را آزمایش می‌کند؟","optionsFa":["Test-ComputerSecureChannel","Get-DnsServerZone","Get-Volume","Get-WindowsFeature"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.management/test-computersecurechannel?view=powershell-5.1","https://learn.microsoft.com/en-us/troubleshoot/windows-server/windows-security/broken-trust-relationship-domain-joined-device-its-domain-secure-channel-issues"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"Official Microsoft technical and guide review for Windows Server 2025; prior originality, translation and distractor audit statuses retained","reviewedAt":"2026-10-09T19:11:36.000Z"},"objective":"Manage AD DS computer accounts and secure channels","objectiveId":"adds-computer-accounts","topic":"Computer accounts and secure channel","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.management/test-computersecurechannel?view=powershell-5.1","https://learn.microsoft.com/en-us/troubleshoot/windows-server/windows-security/broken-trust-relationship-domain-joined-device-its-domain-secure-channel-issues"],"keyPoints":["Test-ComputerSecureChannel checks the local domain member's trust and returns True or False.","The -Repair option can restore a broken channel with a credential authorized to reset that computer account.","This cmdlet is for domain members, not domain controllers; on a DC it can report misleading errors. Use the documented netdom or nltest DC procedure."],"whyOthers":["","Get-DnsServerZone reports DNS zones hosted on a DNS server and says nothing about machine trust.","Get-Volume reports disk volumes and file-system information, which is unrelated to the secure channel.","Get-WindowsFeature lists installed Windows roles and features and does not test domain trust."],"commandPath":[{"label":"Check the secure channel","command":"Test-ComputerSecureChannel -Verbose"},{"label":"Reset the secure channel with a credential that can reset the account","command":"Test-ComputerSecureChannel -Repair -Credential (Get-Credential)"}],"requirements":"For Windows Server 2025 member servers and domain-joined Windows clients, run locally with appropriate administrator access. Confirm internal DNS/DC connectivity. The repairing domain credential must be authorized for the computer account. This cmdlet is not a DC secure-channel diagnostic."},
{"id":"az802-q-029","domain":"Deploy and manage AD DS","text":"A member computer reports that its trust relationship failed. What is the most direct repair?","options":["Delete every domain controller","Change the DNS suffix to a public domain","Disable Kerberos on the client","Repair the secure channel with a domain credential"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"en":"After verifying connectivity and the account, restore this domain member's secure channel with an authorized domain credential.","fa":"پس از بررسی اتصال و حساب، کانال امن این رایانهٔ عضو دامین را با اعتبارنامهٔ مجاز دامین بازیابی کنید.","de":"Stellen Sie nach Prüfung von Verbindung und Konto den sicheren Kanal dieses Domänenmitglieds mit berechtigten Domänenanmeldedaten wieder her."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"رایانه‌ای که عضو دامین است، گزارش می‌دهد که رابطه اعتماد آن دچار مشکل شده است. مستقیم‌ترین روش برای رفع این مشکل چیست؟","optionsFa":["حذف تمام کنترل‌کننده‌های دامین (Domain Controllers)","تغییر پسوند DNS به یک دامین عمومی (public domain)","غیرفعال کردن Kerberos در کلاینت","تعمیر کانال امن با استفاده از اعتبارنامه‌های دامین (domain credential)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/windows-security/broken-trust-relationship-domain-joined-device-its-domain-secure-channel-issues","https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.management/test-computersecurechannel?view=powershell-5.1"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"Official Microsoft technical and guide review for Windows Server 2025; prior originality, translation and distractor audit statuses retained","reviewedAt":"2026-10-09T19:11:36.000Z"},"objective":"Manage AD DS computer accounts and secure channels","objectiveId":"adds-computer-accounts","topic":"Computer accounts and secure channel","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/windows-security/broken-trust-relationship-domain-joined-device-its-domain-secure-channel-issues","https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.management/test-computersecurechannel?view=powershell-5.1"],"keyPoints":["Trust failure can result from a machine-account password mismatch, a missing account or failure to reach a suitable DC.","After checking DNS, connectivity and the computer object, repair a domain member's secure channel using an authorized domain credential.","Deleting the computer account is not a mandatory prerequisite for repair or rejoin. A missing account requires recreation or a suitable domain-join procedure."],"whyOthers":["Deleting domain controllers damages the directory instead of repairing the member computer's trust.","A public DNS suffix does not restore the machine-account secret or AD DNS/DC connectivity.","Disabling Kerberos does not repair machine-account trust and disrupts authentication that relies on Kerberos.",""],"requirements":"For Windows Server 2025 domain members, use local administrator access and an authorized domain credential. Preserve the existing account where possible. Test-ComputerSecureChannel is not intended for domain controllers; follow their separate recovery procedure."},
{"id":"az802-q-030","domain":"Deploy and manage AD DS","text":"Which AD DS component lets clients query a partial, forest-wide copy of directory objects?","options":["SYSVOL","Site link","Global Catalog","RID pool"],"correct":2,"source":"https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/get-started/replication/active-directory-replication-concepts","rationale":{"en":"A global catalog supports forest-wide searches. A writable GC holds its own domain in full and partial, read-only replicas of the other domains, containing all their objects but only selected attributes.","fa":"کاتالوگ سراسری جست‌وجو در کل جنگل را ممکن می‌کند. GC قابل‌نوشتن، دامنهٔ خودش را کامل و دامنه‌های دیگر را به‌صورت نسخهٔ جزئی و فقط‌خواندنی نگه می‌دارد؛ همهٔ اشیا ولی تنها بعضی ویژگی‌ها موجودند.","de":"Ein Global Catalog ermöglicht forestweite Suchen. Ein beschreibbarer GC hält seine eigene Domäne vollständig und andere Domänen als schreibgeschützte Teilreplikate mit allen Objekten, aber ausgewählten Attributen."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام مؤلفه AD DS به کلاینت‌ها اجازه می‌دهد تا در مورد نسخه‌ای جزئی از اشیاء دایرکتوری (directory objects) که در سطح کل فارست (forest-wide) موجود است، پرس‌وجو (query) کنند؟","optionsFa":["SYSVOL","Site link (پیوند سایت)","Global Catalog (کاتالوگ سراسری)","RID pool (مخزن RID)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/get-started/replication/active-directory-replication-concepts","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/planning-global-catalog-server-placement","https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/fsmo-placement-and-optimization-on-ad-dcs"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"Microsoft source and answer verification; original originality, translation and distractor audit flags preserved","reviewedAt":"2026-10-09T19:09:53Z"},"objective":"Manage the Active Directory global catalog","objectiveId":"adds-global-catalog","topic":"Global catalog","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/get-started/replication/active-directory-replication-concepts","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/planning-global-catalog-server-placement","https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/fsmo-placement-and-optimization-on-ad-dcs"],"keyPoints":["A GC supports searches across all domains in its forest.","A writable GC has a full own-domain replica and partial, read-only replicas of other domains.","The partial attribute set controls which attributes appear in partial domain replicas."],"whyOthers":["SYSVOL stores policy and script files, not the forest-wide directory catalog.","A site link defines replication policy between sites.","","RID pools provide identifiers for new security principals."],"requirements":"Applies to Windows Server 2025 AD DS and supported earlier releases. A GC is a capability of a DC; an RODC can also be a GC while its own-domain replica remains read-only. The Domain Naming Master has not required GC placement since Windows Server 2003.","commandPath":[{"label":"List designated GC servers","command":"Get-ADForest | Select-Object -ExpandProperty GlobalCatalogs"}]},
{"id":"az802-q-031","domain":"Deploy and manage AD DS","text":"Why is a Global Catalog often important for user logon in a multidomain forest?","options":["It hosts all DHCP scopes","It stores every file share","It can locate universal group memberships","It leases IP addresses"],"correct":2,"source":"https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/planning-global-catalog-server-placement","rationale":{"en":"In a multidomain forest, the authenticating DC obtains forest-wide universal group membership information from a GC, or uses an available universal group membership cache, to build the user's logon token.","fa":"در جنگل چنددامنه‌ای، کنترل‌کنندهٔ احراز هویت اطلاعات عضویت گروه‌های Universal را از GC یا کش معتبر این عضویت دریافت می‌کند تا توکن ورود کاربر ساخته شود.","de":"In einem Forest mit mehreren Domänen verwendet der authentifizierende DC einen GC oder einen vorhandenen Universal-Group-Membership-Cache, um die universellen Gruppen im Anmeldetoken zu berücksichtigen."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"چرا Global Catalog اغلب برای ورود کاربر در یک فارستِ چنددامنه‌ای (multidomain forest) اهمیت دارد؟","optionsFa":["تمام دامنه‌های (scopes) سرویس DHCP را میزبانی می‌کند","تمام فایل‌های اشتراک‌گذاری‌شده را ذخیره می‌کند","می‌تواند موقعیت عضویت در گروه‌های Universal را تعیین کند","آدرس‌های IP را اجاره می‌دهد (اختصاص می‌دهد)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/planning-global-catalog-server-placement","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/get-started/replication/active-directory-replication-concepts"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"Microsoft source and answer verification; original originality, translation and distractor audit flags preserved","reviewedAt":"2026-10-09T19:09:53Z"},"objective":"Manage the Active Directory global catalog","objectiveId":"adds-global-catalog","topic":"Global catalog","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/planning-global-catalog-server-placement","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/get-started/replication/active-directory-replication-concepts"],"keyPoints":["GC information supports universal group membership evaluation at logon.","Universal group objects and membership also exist in their owning domain; they are not stored only on GCs.","UGMC can reduce repeated GC lookups, but initial lookup and refresh still require GC connectivity."],"whyOthers":["DHCP scope hosting is unrelated to GC membership lookup.","A GC does not store every file share.","","Address leasing is DHCP's task."],"requirements":"Windows Server 2025 AD DS. Plan multidomain logon availability around GC reachability or valid cached membership; do not assume that the dependency exists only when an administrator knowingly uses universal groups."},
{"id":"az802-q-032","domain":"Deploy and manage AD DS","text":"What is the primary purpose of an AD DS site?","options":["Represent network topology for replication and client referral","Replace all OUs","Store user passwords in plaintext","Define a file-share quota"],"correct":0,"source":"https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/get-started/replication/active-directory-replication-concepts","rationale":{"en":"An AD site models well-connected IP subnets. AD DS uses site information for network-aware DC discovery and replication topology, independently of the OU and domain hierarchy.","fa":"سایت AD زیرشبکه‌های IP با ارتباط مناسب را مدل می‌کند. AD DS از سایت برای یافتن کنترل‌کننده‌های مناسب و طراحی توپولوژی تکثیر استفاده می‌کند؛ سایت مستقل از ساختار OU و دامنه است.","de":"Ein AD-Site modelliert gut verbundene IP-Subnetze. AD DS nutzt Sites für standortbezogene DC-Suche und Replikation, unabhängig von OU- und Domänenhierarchien."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"هدف اصلی یک Site در AD DS چیست؟","optionsFa":["نمایش توپولوژی شبکه برای همگام‌سازی (Replication) و ارجاع کلاینت‌ها","جایگزینی تمام واحدهای سازمانی (OUها)","ذخیره رمزهای عبور کاربران به صورت متن ساده (Plaintext)","تعیین سهمیه (Quota) برای اشتراک‌گذاری فایل"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/get-started/replication/active-directory-replication-concepts"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"Microsoft source and answer verification; original originality, translation and distractor audit flags preserved","reviewedAt":"2026-10-09T19:09:53Z"},"objective":"Manage AD DS sites and replication","objectiveId":"adds-sites-replication","topic":"AD DS sites","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/get-started/replication/active-directory-replication-concepts"],"keyPoints":["A site represents one or more well-connected IP subnets.","A site can contain DCs from multiple domains, and a domain can span multiple sites.","Subnet objects associate address ranges with a site for client discovery."],"whyOthers":["","OUs organize directory objects and delegated administration; sites model connectivity.","Sites do not store passwords in plaintext.","Share quotas belong to file-service configuration."],"requirements":"Windows Server 2025 AD DS. Each subnet object references one site. Missing or incorrectly overlapping subnet definitions can impair client site identification; a subnet object cannot be assigned simultaneously to two sites."},
{"id":"az802-q-033","domain":"Deploy and manage AD DS","text":"A new branch subnet is not associated with the branch site. What problem is most likely?","options":["Users lose all NTFS permissions","The schema becomes invalid","RID allocation stops immediately","Clients may authenticate against a distant domain controller"],"correct":3,"source":"https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/get-started/replication/active-directory-replication-concepts","rationale":{"en":"If the branch address range is not mapped to its AD site, clients may fail to select the intended local DC and use a distant one. Check the subnet mapping and the client's reported site before diagnosing other causes.","fa":"اگر محدودهٔ آدرس شعبه به سایت درست نگاشت نشده باشد، ممکن است کلاینت به‌جای کنترل‌کنندهٔ محلی از کنترل‌کنندهٔ دور استفاده کند. نگاشت زیرشبکه و سایت گزارش‌شدهٔ کلاینت را بررسی کنید.","de":"Fehlt die Zuordnung des Zweigstellen-Subnetzes, können Clients einen entfernten statt des vorgesehenen lokalen DC auswählen. Prüfe Subnetzzuteilung und gemeldeten Client-Site."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"یک زیرشبکه (Subnet) جدیدِ مربوط به شعبه، به سایتِ آن شعبه متصل نشده است. احتمال بروز چه مشکلی بیشتر است؟","optionsFa":["کاربران تمام مجوزهای NTFS خود را از دست می‌دهند","طرح‌واره (Schema) نامعتبر می‌شود","تخصیص RID بلافاصله متوقف می‌شود","کلاینت‌ها ممکن است در برابر یک کنترل‌کننده دامنه (Domain Controller) دوردست احراز هویت شوند"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/get-started/replication/active-directory-replication-concepts","https://learn.microsoft.com/en-us/powershell/module/activedirectory/get-adreplicationsubnet?view=windowsserver2025-ps"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"Microsoft source and answer verification; original originality, translation and distractor audit flags preserved","reviewedAt":"2026-10-09T19:09:53Z"},"objective":"Manage AD DS sites and replication","objectiveId":"adds-sites-replication","topic":"AD DS sites","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/get-started/replication/active-directory-replication-concepts","https://learn.microsoft.com/en-us/powershell/module/activedirectory/get-adreplicationsubnet?view=windowsserver2025-ps"],"keyPoints":["Subnet-to-site mapping helps DC Locator identify the client site.","A missing mapping can cause remote-DC selection and extra WAN traffic.","DC server-site placement and site-link policies should be checked separately from client subnet mapping."],"whyOthers":["Subnet mapping does not erase NTFS permissions.","A missing client subnet does not invalidate the AD schema.","It does not immediately stop RID allocation.",""],"commandPath":[{"label":"Read client site","command":"nltest /dsgetsite"},{"label":"Read subnet-to-site mappings","command":"Get-ADReplicationSubnet -Filter * | Select-Object Name,Site"}],"requirements":"Windows Server 2025 AD DS. Missing subnet mapping can explain distant-controller use; the exact DC selection also depends on DNS, discovery state and available controllers."},
{"id":"az802-q-034","domain":"Deploy and manage AD DS","text":"What is the purpose of an AD DS site link?","options":["Create a DHCP reservation","Encrypt an SMB share","Define the logical path and cost between sites","Assign user home folders"],"correct":2,"source":"https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/get-started/replication/active-directory-replication-concepts","rationale":{"en":"A site link defines a logical replication relationship among sites, including cost, permitted schedule and replication interval. The KCC uses these policies to build connections between DCs.","fa":"پیوند سایت رابطهٔ منطقی تکثیر بین سایت‌ها را با هزینه، زمان‌بندی مجاز و فاصلهٔ تکثیر مشخص می‌کند. KCC از این سیاست‌ها برای ساخت اتصال بین کنترل‌کننده‌ها استفاده می‌کند.","de":"Ein Site-Link beschreibt eine logische Replikationsbeziehung zwischen Sites mit Kosten, Zeitplan und Intervall. Daraus erstellt der KCC Verbindungen zwischen DCs."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"هدف از یک Site Link در AD DS چیست؟","optionsFa":["ایجاد یک رزرو DHCP","رمزنگاری یک اشتراک SMB","تعیین مسیر منطقی و هزینه (cost) بین سایت‌ها","اختصاص پوشه‌های خانگی (home folders) کاربران"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/get-started/replication/active-directory-replication-concepts","https://learn.microsoft.com/en-us/powershell/module/activedirectory/get-adreplicationsitelink?view=windowsserver2025-ps"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"Microsoft source and answer verification; original originality, translation and distractor audit flags preserved","reviewedAt":"2026-10-09T19:09:53Z"},"objective":"Manage AD DS sites and replication","objectiveId":"adds-sites-replication","topic":"Site links","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/get-started/replication/active-directory-replication-concepts","https://learn.microsoft.com/en-us/powershell/module/activedirectory/get-adreplicationsitelink?view=windowsserver2025-ps"],"keyPoints":["Site links include two or more sites and influence intersite topology.","Cost and schedule express replication policy, not a physical network route.","Bridge all site links gives implicit transitivity by default; explicit bridge objects are not mandatory on a fully routed network."],"whyOthers":["DHCP reservations assign addresses, not replication topology.","SMB encryption is unrelated to site-link policy.","","Home folders are configured on user accounts or through policy."],"requirements":"Windows Server 2025 AD DS. Default automatic bridging has no corresponding explicit AD bridge object. A site link does not create network connectivity.","commandPath":[{"label":"Inspect link policy","command":"Get-ADReplicationSiteLink -Filter * | Select-Object Name,SitesIncluded,Cost,ReplicationFrequencyInMinutes"}]},
{"id":"az802-q-035","domain":"Deploy and manage AD DS","text":"Which replication model is normally used within a well-connected AD site?","options":["DNS zone transfer only","Intrasite replication with change notification","Manual export only","Tape-based replication"],"correct":1,"source":"https://learn.microsoft.com/en-us/troubleshoot/windows-server/identity/modify-default-intra-site-dc-replication-interval","rationale":{"en":"Intrasite replication normally uses change notification. After notification, partners request changes. The usual initial delay is 15 seconds, with 3 seconds between subsequent partner notifications.","fa":"تکثیر داخل سایت معمولاً از اعلان تغییر استفاده می‌کند و شریک پس از اعلان تغییرات را درخواست می‌کند. تأخیر اولیهٔ عادی ۱۵ ثانیه و فاصلهٔ اعلان به شریک‌های بعدی ۳ ثانیه است.","de":"Replikation innerhalb eines Sites nutzt normalerweise Änderungsbenachrichtigungen; Partner rufen anschließend die Änderungen ab. Üblich sind 15 Sekunden bis zur ersten und 3 Sekunden zwischen weiteren Benachrichtigungen."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام مدل همگام‌سازی معمولاً در یک سایت AD با اتصال مناسب (well-connected) استفاده می‌شود؟","optionsFa":["فقط انتقال ناحیه DNS (DNS zone transfer)","همگام‌سازی درون‌سایتی (Intrasite) همراه با اعلان تغییرات","فقط خروجی‌گیری (export) دستی","همگام‌سازی مبتنی بر نوار (Tape-based)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/identity/modify-default-intra-site-dc-replication-interval","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/get-started/replication/active-directory-replication-concepts"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"Microsoft source and answer verification; original originality, translation and distractor audit flags preserved","reviewedAt":"2026-10-09T19:09:53Z"},"objective":"Manage AD DS sites and replication","objectiveId":"adds-sites-replication","topic":"Replication model","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/identity/modify-default-intra-site-dc-replication-interval","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/get-started/replication/active-directory-replication-concepts"],"keyPoints":["Change notification reduces normal intrasite propagation latency.","The initial default notification delay is 15 seconds; subsequent partner notifications are spaced 3 seconds apart.","Normal intersite replication uses its separate schedule and interval; notification can be configured there too."],"whyOthers":["DNS zone transfers are not the AD directory replication model.","","Manual export is not normal intrasite replication.","Tape transfer is unrelated to normal AD replication."],"requirements":"Windows Server 2025 AD DS. These are normal configurable notification delays, not a guarantee that all replication completes in 15 seconds; urgent replication has different behavior.","commandPath":[{"label":"Read notification settings without changing them","command":"repadmin /notifyopt DC01 dc=corp,dc=contoso,dc=com"}]},
{"id":"az802-q-036","domain":"Deploy and manage AD DS","text":"Which tool is most useful for displaying AD replication partners and last-successful replication?","options":["repadmin","diskpart","ipconfig","wevtutil only"],"correct":0,"source":"https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/diagnose-replication-failures","rationale":{"en":"repadmin /showrepl displays inbound partners and per-partition replication results, including the last successful replication. /replsummary provides a summary of failures and deltas.","fa":"دستور repadmin /showrepl شریک‌های ورودی و نتیجهٔ تکثیر هر پارتیشن، از جمله آخرین تکثیر موفق، را نشان می‌دهد. ‎/replsummary خلاصهٔ خطاها و فاصلهٔ تکثیر را ارائه می‌کند.","de":"repadmin /showrepl zeigt eingehende Partner und Replikationsergebnisse je Partition einschließlich des letzten Erfolgs. /replsummary fasst Fehler und Zeitdifferenzen zusammen."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام ابزار برای نمایش شرکای همگام‌سازی AD و آخرین همگام‌سازی موفق، بیشترین کاربرد را دارد؟","optionsFa":["repadmin","diskpart","ipconfig","فقط wevtutil"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/diagnose-replication-failures"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"Microsoft source and answer verification; original originality, translation and distractor audit flags preserved","reviewedAt":"2026-10-09T19:09:53Z"},"objective":"Manage AD DS sites and replication","objectiveId":"adds-sites-replication","topic":"Replication monitoring","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/diagnose-replication-failures"],"keyPoints":["/showrepl reports inbound replication by naming context.","/replsummary helps locate failures and large deltas.","Reporting commands provide evidence; they do not repair replication."],"whyOthers":["","diskpart manages disks and partitions, not AD replication partners.","ipconfig displays network configuration, not per-partition replication results.","Event logs can help, but wevtutil alone is not the dedicated replication-partner tool."],"commandPath":[{"label":"Read inbound replication results","command":"repadmin /showrepl"},{"label":"Summarize replication health","command":"repadmin /replsummary"}],"requirements":"Windows Server 2025 AD DS. Install AD DS RSAT tools and use appropriate access to query target controllers."},
{"id":"az802-q-037","domain":"Deploy and manage AD DS","text":"Which command summarizes domain-controller health checks?","options":["nslookup","robocopy","mstsc","dcdiag"],"correct":3,"source":"https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/dcdiag","rationale":{"en":"dcdiag runs diagnostic tests against domain controllers. /v adds detail; DNS testing must be requested with /test:DNS or included using /c rather than assumed in the default test set.","fa":"dcdiag آزمون‌های تشخیصی کنترل‌کنندهٔ دامنه را اجرا می‌کند. ‎/v جزئیات را افزایش می‌دهد؛ برای آزمون DNS باید ‎/test:DNS یا ‎/c را مشخص کرد و نباید آن را جزء همهٔ اجراهای پیش‌فرض فرض کرد.","de":"dcdiag führt DC-Diagnosetests aus. /v liefert Details; DNS-Tests müssen mit /test:DNS oder /c angefordert werden und gehören nicht zum üblichen Standardsatz."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام دستور، نتایج بررسی سلامت کنترل‌کننده دامنه (domain controller) را خلاصه می‌کند؟","optionsFa":["nslookup","robocopy","mstsc","dcdiag"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/dcdiag"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"Microsoft source and answer verification; original originality, translation and distractor audit flags preserved","reviewedAt":"2026-10-09T19:09:53Z"},"objective":"Manage AD DS sites and replication","objectiveId":"adds-sites-replication","topic":"Replication monitoring","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/dcdiag"],"keyPoints":["dcdiag reports DC health through named tests.","/s selects a target server and /v enables detailed output.","DNS tests are explicitly selected with /test:DNS or /c."],"whyOthers":["nslookup queries DNS rather than running broad DC diagnostics.","robocopy copies files.","mstsc opens Remote Desktop sessions.",""],"commandPath":[{"label":"Run detailed default tests on a lab DC","command":"dcdiag /s:DC01 /v"},{"label":"Run DNS diagnostics explicitly","command":"dcdiag /s:DC01 /test:DNS /v"}],"requirements":"Windows Server 2025 AD DS. Use RSAT AD DS tools and appropriate permissions. Avoid repair options while collecting diagnostic evidence."},
{"id":"az802-q-038","domain":"Deploy and manage AD DS","text":"An AD replication queue grows because a WAN link is available only at night. Which setting should you review first?","options":["NTFS compression","DHCP lease duration only","Site-link replication schedule","User logon script"],"correct":2,"source":"https://learn.microsoft.com/en-us/powershell/module/activedirectory/get-adreplicationsitelink?view=windowsserver2025-ps","rationale":{"en":"The site-link schedule must overlap the hours when the WAN is usable. The replication interval specifies frequency within the permitted window; inspect both rather than reading interval alone as the schedule.","fa":"زمان‌بندی پیوند سایت باید با ساعات دسترسی WAN هم‌پوشانی داشته باشد. فاصلهٔ تکثیر تعداد دفعات اجرا در پنجرهٔ مجاز را تعیین می‌کند؛ هر دو تنظیم را بررسی کنید.","de":"Der Site-Link-Zeitplan muss sich mit der WAN-Verfügbarkeit überschneiden. Das Intervall bestimmt die Häufigkeit innerhalb dieses Fensters; beide Einstellungen sind getrennt zu prüfen."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"صفِ همگام‌سازی (Replication) سرویس دایرکتوری اکتیو (AD) به این دلیل بزرگ می‌شود که لینک WAN تنها در طول شب در دسترس است. کدام تنظیم را باید ابتدا بررسی کنید؟","optionsFa":["فشرده‌سازی NTFS","فقط مدت زمان اجاره (lease duration) در DHCP","زمان‌بندی همگام‌سازی Site-link","اسکریپت ورود (logon script) کاربر"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/activedirectory/get-adreplicationsitelink?view=windowsserver2025-ps","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/determining-the-interval"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"Microsoft source and answer verification; original originality, translation and distractor audit flags preserved","reviewedAt":"2026-10-09T19:09:53Z"},"objective":"Manage AD DS sites and replication","objectiveId":"adds-sites-replication","topic":"Replication schedule","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/activedirectory/get-adreplicationsitelink?view=windowsserver2025-ps","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/determining-the-interval"],"keyPoints":["The schedule determines permitted replication windows.","The interval applies while the window is open; default is 180 minutes and minimum is 15.","Closed windows can explain delayed changes, but replication errors and connectivity must also be checked."],"whyOthers":["NTFS compression does not set the replication window.","DHCP lease duration does not configure replication hours.","","A logon script does not determine site-link replication timing."],"commandPath":[{"label":"Read the actual schedule as well as interval","command":"Get-ADReplicationSiteLink -Identity 'HQ-Branch' -Properties ReplicationSchedule | Select-Object Name,ReplicationFrequencyInMinutes,ReplicationSchedule"}],"requirements":"Windows Server 2025 AD DS. Retrieve the extended ReplicationSchedule property explicitly, or inspect Change Schedule in the site-link properties."},
{"id":"az802-q-039","domain":"Deploy and manage AD DS","text":"Which trust is automatically created between a parent domain and a child domain in the same forest?","options":["No trust","Two-way transitive trust","One-way external trust","Realm trust only"],"correct":1,"source":"https://learn.microsoft.com/en-us/project/supported-active-directory-topologies-for-project-server-2013-enterprise-resourc","rationale":{"en":"Adding a child domain creates a two-way transitive parent-child trust inside the forest. Transitivity follows the forest trust path, while resource authorization remains separate.","fa":"با افزودن دامنهٔ فرزند، اعتماد دوطرفه و انتقال‌پذیر میان والد و فرزند در جنگل ایجاد می‌شود. مجوز استفاده از منابع همچنان جداگانه بررسی می‌شود.","de":"Eine neue untergeordnete Domäne erhält automatisch einen bidirektionalen, transitiven Parent-Child-Trust. Ressourcenberechtigungen bleiben eine separate Prüfung."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"چه نوع رابطه‌ی اعتماد (trust) به‌طور خودکار بین یک دامنه والد (parent domain) و یک دامنه فرزند (child domain) در یک فارست (forest) واحد ایجاد می‌شود؟","optionsFa":["هیچ رابطه‌ی اعتمادی ایجاد نمی‌شود","اعتماد انتقالی (transitive) دوطرفه","اعتماد خارجی یک‌طرفه","فقط اعتماد Realm"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/project/supported-active-directory-topologies-for-project-server-2013-enterprise-resourc","https://learn.microsoft.com/en-us/openspecs/windows_protocols/ms-pac/55fc19f2-55ba-4251-8a6a-103dd7c66280"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"Microsoft source and answer verification; original originality, translation and distractor audit flags preserved","reviewedAt":"2026-10-09T19:09:53Z"},"objective":"Create and manage Active Directory trusts","objectiveId":"adds-trusts","topic":"Trusts","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/project/supported-active-directory-topologies-for-project-server-2013-enterprise-resourc","https://learn.microsoft.com/en-us/openspecs/windows_protocols/ms-pac/55fc19f2-55ba-4251-8a6a-103dd7c66280"],"keyPoints":["Parent-child trusts are automatically created within a forest.","They are two-way and transitive by default.","A trust enables an authentication path, not automatic permission to resources."],"whyOthers":["A child domain does receive an automatic trust.","","An external trust joins named domains across a forest boundary.","Realm trusts serve interoperable Kerberos realms."],"requirements":"Windows Server 2025 AD DS. SID filtering rules vary by trust boundary and quarantine settings; it is incorrect to claim that filtering applies only across forests.","commandPath":[{"label":"Inspect trust properties","command":"Get-ADTrust -Filter * | Select-Object Name,Direction,IntraForest,ForestTransitive"}]},
{"id":"az802-q-040","domain":"Deploy and manage AD DS","text":"Which trust type connects only two specified domains in different forests without extending to their other domains?","options":["External trust","Parent-child trust","Intrasite trust","Local trust"],"correct":0,"source":"https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/netdom-trust","rationale":{"en":"An external trust is non-transitive and connects the specified domains in different forests. Select it for domain-scoped access, not simply because a relationship is temporary. /Realm creates a different, non-Windows Kerberos trust.","fa":"اعتماد خارجی فقط دامنه‌های مشخص در جنگل‌های متفاوت را به‌صورت غیرانتقال‌پذیر متصل می‌کند. معیار انتخاب، محدودبودن دامنهٔ دسترسی است، نه صرفاً مدت رابطه. ‎/Realm نوع دیگری از اعتماد Kerberos را می‌سازد.","de":"Ein externer Trust verbindet die benannten Domänen verschiedener Forests nichttransitiv. Entscheidend ist der begrenzte Domänenumfang, nicht die Dauer. /Realm erstellt einen anderen Kerberos-Realm-Trust."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام نوع اعتماد فقط دو دامنهٔ مشخص در جنگل‌های متفاوت را متصل می‌کند و به دامنه‌های دیگر آن‌ها گسترش نمی‌یابد؟","optionsFa":["اعتماد خارجی (External trust)","اعتماد والد-فرزند","اعتماد درون‌سایتی (Intrasite trust)","اعتماد محلی (Local trust)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/netdom-trust","https://learn.microsoft.com/en-us/project/supported-active-directory-topologies-for-project-server-2013-enterprise-resourc"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"Microsoft source and answer verification; original originality, translation and distractor audit flags preserved","reviewedAt":"2026-10-09T19:09:53Z"},"objective":"Create and manage Active Directory trusts","objectiveId":"adds-trusts","topic":"Trusts","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/netdom-trust","https://learn.microsoft.com/en-us/project/supported-active-directory-topologies-for-project-server-2013-enterprise-resourc"],"keyPoints":["An external trust is scoped to the two named domains.","It does not automatically include other domains in either forest.","Use prompted credentials for an authorized lab change; do not embed passwords."],"whyOthers":["","A parent-child trust connects domains in the same forest.","Intrasite is a replication scope, not a trust type.","Local trust is not the appropriate AD cross-forest trust type."],"commandPath":[{"label":"Create an authorized lab external trust with credential prompts","command":"netdom trust resources.contoso.com /Domain:accounts.fabrikam.com /Add /UserO:admin@resources.contoso.com /PasswordO:* /UserD:admin@accounts.fabrikam.com /PasswordD:*"},{"label":"Read trust properties","command":"Get-ADTrust -Filter *"}],"requirements":"Windows Server 2025 AD DS. Plan DNS, network connectivity, trust direction and resource permissions. This example creates an external domain trust; it does not create an AD forest trust."},
{"id":"az802-q-041","domain":"Deploy and manage AD DS","text":"What does a forest trust provide?","options":["A replacement for all DNS records","A local group on every workstation","Automatic file replication","A trust relationship between two forests"],"correct":3,"source":"https://learn.microsoft.com/en-us/project/supported-active-directory-topologies-for-project-server-2013-enterprise-resourc","rationale":{"en":"A forest trust connects the roots of two forests and provides an authentication path for their domains in the configured direction. It does not automatically extend through a third forest or grant resource access.","fa":"اعتماد جنگل ریشه‌های دو جنگل را متصل و در جهت تنظیم‌شده مسیر احراز هویت دامنه‌های آن‌ها را فراهم می‌کند. این اعتماد خودکار به جنگل سوم گسترش نمی‌یابد و مجوز منابع نمی‌دهد.","de":"Ein Forest-Trust verbindet zwei Forest-Wurzeln und ermöglicht Authentifizierung zwischen deren Domänen in der festgelegten Richtung. Er erweitert sich nicht automatisch auf einen dritten Forest und erteilt keine Ressourcenrechte."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"Forest Trust (اعتماد بین فارست‌ها) چه امکانی را فراهم می‌کند؟","optionsFa":["جایگزینی برای تمام رکوردهای DNS","یک گروه محلی (Local Group) روی هر ایستگاه کاری","تکثیر (Replication) خودکار فایل‌ها","یک رابطه اعتماد (Trust Relationship) بین دو فارست"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/project/supported-active-directory-topologies-for-project-server-2013-enterprise-resourc","https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/netdom-trust"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"Microsoft source and answer verification; original originality, translation and distractor audit flags preserved","reviewedAt":"2026-10-09T19:09:53Z"},"objective":"Create and manage Active Directory trusts","objectiveId":"adds-trusts","topic":"Trusts","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/project/supported-active-directory-topologies-for-project-server-2013-enterprise-resourc","https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/netdom-trust"],"keyPoints":["The relationship is established between forest root domains.","It covers domains inside the two participating forests in the configured direction.","Authentication mode and resource permissions remain separate controls."],"whyOthers":["DNS resolution is still required.","A trust is not a local workstation group.","A trust does not replicate file contents.",""],"requirements":"Windows Server 2025 AD DS. Both forests need forest-trust support, working DNS and connectivity. Use Active Directory Domains and Trusts to create an AD forest trust; netdom trust cannot create one."},
{"id":"az802-q-042","domain":"Deploy and manage AD DS","text":"An administrator must allow authentication across forests only for explicitly approved servers. Which trust option is relevant?","options":["Guest-only access","Automatic logon","Selective authentication","Anonymous authentication"],"correct":2,"source":"https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/netdom-trust","rationale":{"en":"Selective authentication requires approved partner users or groups to have Allowed to authenticate on the intended target computer. They must separately hold the permissions needed for the resource or application.","fa":"احراز هویت انتخابی نیازمند مجوز Allowed to authenticate برای کاربران یا گروه‌های شریک روی رایانهٔ هدف است. مجوز استفاده از منبع یا برنامه نیز جداگانه لازم است.","de":"Bei selektiver Authentifizierung benötigen zugelassene Partnerbenutzer Allowed to authenticate am Zielcomputer. Zusätzlich müssen die Ressourcen- oder Anwendungsrechte vorliegen."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"مدیر شبکه باید امکان احراز هویت بین فارست‌ها را تنها برای سرورهایی که صراحتاً تأیید شده‌اند، فراهم کند. کدام گزینه مربوط به این نوع اعتماد است؟","optionsFa":["دسترسی صرفاً برای کاربر مهمان (Guest)","ورود (Logon) خودکار","احراز هویت انتخابی (Selective Authentication)","احراز هویت ناشناس (Anonymous)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/netdom-trust"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"Microsoft source and answer verification; original originality, translation and distractor audit flags preserved","reviewedAt":"2026-10-09T19:09:53Z"},"objective":"Create and manage Active Directory trusts","objectiveId":"adds-trusts","topic":"Trusts","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/netdom-trust"],"keyPoints":["Selective authentication limits which computers partner identities can authenticate to.","Allowed to authenticate is granted on the intended computer objects.","Authentication approval does not grant file, application or administrative permissions."],"whyOthers":["Guest-only access is unrelated to approved cross-forest authentication.","Automatic logon does not implement this trust gate.","","Anonymous access does not approve trusted identities."],"commandPath":[{"label":"Configure an authorized lab outbound trust","command":"netdom trust resources.contoso.com /Domain:accounts.fabrikam.com /SelectiveAuth:yes"}],"requirements":"Windows Server 2025 AD DS. Configure selective authentication on the outbound forest or external trust viewed from the resource domain. Then approve target computers and grant resource access separately."},
{"id":"az802-q-043","domain":"Deploy and manage AD DS","text":"Which operation pre-creates a delegated RODC account in AD DS without promoting the target server?","options":["Format-Volume","Add-ADDSReadOnlyDomainControllerAccount","Enable-DhcpServer","ConvertTo-MsolDomain"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"en":"Add-ADDSReadOnlyDomainControllerAccount stages an RODC account and can delegate later installation. The target server is promoted separately; Install-ADDSDomainController has no -PrepareOnly parameter.","fa":"Add-ADDSReadOnlyDomainControllerAccount حساب RODC را از پیش ایجاد می‌کند و می‌تواند نصب بعدی را واگذار کند؛ ارتقای سرور جداگانه انجام می‌شود و پارامتر -PrepareOnly وجود ندارد.","de":"Add-ADDSReadOnlyDomainControllerAccount erstellt das RODC-Konto vorab und kann die spätere Installation delegieren. Die Serverheraufstufung erfolgt separat; -PrepareOnly ist kein gültiger Parameter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام عملیات، حساب RODC را با امکان واگذاری نصب در AD DS از پیش ایجاد می‌کند، بدون اینکه سرور مقصد را به Domain Controller ارتقا دهد؟","optionsFa":["Format-Volume","Add-ADDSReadOnlyDomainControllerAccount","Enable-DhcpServer","ConvertTo-MsolDomain"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/addsdeployment/add-addsreadonlydomaincontrolleraccount?view=windowsserver2025-ps","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/deploy/ad-ds-installation-and-removal-wizard-page-descriptions","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/active-directory-functional-levels"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"AD operations: Microsoft source and technical answer review; other audit flags retained from prior review","reviewedAt":"2026-10-09T00:00:00.000Z"},"objective":"Deploy and manage AD DS domain controllers","objectiveId":"adds-domain-controllers","topic":"Domain controller deployment","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/addsdeployment/add-addsreadonlydomaincontrolleraccount?view=windowsserver2025-ps","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/deploy/ad-ds-installation-and-removal-wizard-page-descriptions","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/active-directory-functional-levels"],"keyPoints":["Staged RODC deployment pre-creates a named RODC account in AD DS.","DelegatedAdministratorAccountName specifies who can later attach/promote the matching server.","This is distinct from forest/domain adprep and virtual DC cloning."],"whyOthers":["Format-Volume formats storage; it does not stage an AD DS RODC account.","","DHCP configuration does not pre-create an RODC account.","ConvertTo-MsolDomain is unrelated to staged on-premises RODC deployment."],"commandPath":[{"label":"LAB WRITE: stage a named RODC account with a delegated installer","command":"Add-ADDSReadOnlyDomainControllerAccount -DomainControllerAccountName BRANCH-RODC -DomainName corp.contoso.com -SiteName Branch -DelegatedAdministratorAccountName 'CONTOSO\\RODC-Installers'"}],"requirements":"Windows Server 2025 ADDSDeployment tools. An administrator stages the account against the intended domain/site and delegates installation. Installing the matching Windows Server 2025 DC requires forest and domain functional levels of at least Windows Server 2016, the AD DS role, and normal RODC promotion prerequisites."},
{"id":"az802-q-044","domain":"Deploy and manage AD DS","text":"Which prerequisite is essential before promoting a new domain controller?","options":["It must use reliable DNS resolution for the domain","It must be in a workgroup forever","It must have a public IP address","It must disable the Windows Firewall"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"AD DS به شدت به رکوردهای DNS SRV و وضوح نام برای کشف، احراز هویت و تکرار بستگی دارد.","en":"AD DS depends heavily on DNS SRV records and name resolution for discovery, authentication, and replication.","de":"Die richtige Antwort ist „It must use reliable DNS resolution for the domain“; sie passt zum Bereich Deploy and manage AD DS und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام پیش نیاز قبل از تبلیغ یک کنترل کننده دامنه جدید ضروری است؟","optionsFa":["باید از وضوح DNS قابل اعتماد برای دامنه استفاده کند","باید برای همیشه در یک گروه کاری باشد","باید یک آدرس IP عمومی داشته باشد","باید فایروال ویندوز را غیرفعال کند"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/dns-and-ad-ds","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/deploy/install-active-directory-domain-services--level-100-"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Deploy and manage AD DS domain controllers","objectiveId":"adds-domain-controllers","topic":"Domain controller deployment","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/networking/best-practices-for-dns-client-settings"],"keyPoints":["AD DS uses DNS service records to locate directory controllers and services.","An additional controller must resolve the existing domain through its internal DNS before promotion.","For a first controller in a new forest, plan the namespace and authoritative DNS; existing domain-controller SRV records do not exist yet."],"whyOthers":["","A domain controller is a domain member by definition; the workgroup state exists only before promotion.","Domain controllers use private addressing and should not be exposed with a public IP address.","The Windows Firewall should stay enabled; the required AD DS ports are allowed rather than the firewall being turned off."],"requirements":"Set DNS client addresses appropriate to the deployment. For an existing domain, validate its internal domain-controller locator records. The first controller of a new forest creates the domain DNS records during deployment; do not require nonexistent pre-promotion SRV records."},
{"id":"az802-q-045","domain":"Deploy and manage AD DS","text":"Why should a domain controller generally point its DNS client settings to internal AD-integrated DNS?","options":["Public DNS creates user accounts","DHCP requires public DNS","Kerberos uses only IP addresses","AD DS service discovery depends on internal DNS records"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"کنترل‌کننده‌های دامنه و کلاینت‌ها LDAP، Kerberos و سایر خدمات را از طریق سوابق DNS مخصوص AD تعیین می‌کنند.","en":"Domain controllers and clients locate LDAP, Kerberos, and other services through AD-specific DNS records.","de":"Die richtige Antwort ist „AD DS service discovery depends on internal DNS records“; sie passt zum Bereich Deploy and manage AD DS und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"چرا یک کنترل کننده دامنه معمولاً باید تنظیمات سرویس گیرنده DNS خود را به DNS داخلی AD یکپارچه کند؟","optionsFa":["عمومی DNS حساب های کاربری ایجاد می کند","DHCP به DNS عمومی نیاز دارد","Kerberos فقط از آدرس های IP استفاده می کند","کشف سرویس AD DS به سوابق DNS داخلی بستگی دارد"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/networking/verify-srv-dns-records-have-been-created","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/dns-and-ad-ds"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Deploy and manage AD DS domain controllers","objectiveId":"adds-domain-controllers","topic":"DNS for AD DS","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/networking/best-practices-for-dns-client-settings"],"keyPoints":["Internal authoritative DNS resolves the AD-specific host and service records needed for discovery and authentication.","Public resolvers do not normally know a private AD namespace; using them as AD client DNS can break discovery and correct registration.","Configure external resolution through the internal DNS server's forwarders or root hints, not by adding public client DNS as a supposed backup."],"whyOthers":["Public DNS has no part in creating user accounts in a domain.","DHCP can hand out any DNS server address; it does not require public DNS.","Kerberos ticket requests are addressed to services located by DNS name, so name resolution is essential, not optional.",""],"requirements":"Use DNS servers that can resolve the AD namespace. For a first/only controller running DNS, the client can point to its own address; additional controllers should use suitable internal AD DNS. A public resolver's presence does not automatically publish AD records to a public zone."},
{"id":"az802-q-046","domain":"Deploy and manage AD DS","text":"What is the safest way to remove a healthy, reachable domain controller?","options":["Turn off its network adapter permanently","Remove its DNS zone only","Demote it gracefully","Delete its computer object first"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"تنزل دلپذیر فهرست راهنمای کنترلر و ارجاعات سرویس را کاملاً حذف می کند.","en":"Graceful demotion removes the controller’s directory and service references cleanly.","de":"Die richtige Antwort ist „Demote it gracefully“; sie passt zum Bereich Deploy and manage AD DS und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"ایمن ترین راه برای حذف یک کنترل کننده دامنه سالم و قابل دسترس چیست؟","optionsFa":["آداپتور شبکه آن را برای همیشه خاموش کنید","فقط ناحیه DNS آن را حذف کنید","آن را با ظرافت تنزل دهید","ابتدا شیء کامپیوتر آن را حذف کنید"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/deploy/demoting-domain-controllers-and-domains--level-200-","https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/dcpromo"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Deploy and manage AD DS domain controllers","objectiveId":"adds-domain-controllers","topic":"Domain controller demotion","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/addsdeployment/uninstall-addsdomaincontroller?view=windowsserver2025-ps","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/deploy/demoting-domain-controllers-and-domains--level-200-"],"keyPoints":["Graceful demotion coordinates directory removal with reachable controllers; check remaining services and replication afterwards.","Ensure another healthy controller can provide DNS, global catalog and other required services before removing an extra controller.","Transfer held FSMO roles while their owner is healthy. Seizure is a recovery action for an unavailable owner, not the normal removal procedure for a healthy controller."],"whyOthers":["Turning off the network adapter leaves stale metadata in the directory and DNS and produces the same cleanup work as a crash.","Removing only the DNS zone leaves the server object and its directory metadata behind.","","Deleting the computer object does not clean up the NTDS settings, connection objects, or replication agreements."],"commandPath":[{"label":"Preview demotion without changing the controller","command":"Uninstall-ADDSDomainController -WhatIf"}],"requirements":"Demotion requires authorized domain credentials and appropriate remaining services. Review warnings and role ownership in the wizard. Removing the last controller deletes the domain; forced removal of an unreachable controller is a different recovery procedure requiring metadata cleanup."},
{"id":"az802-q-047","domain":"Deploy and manage AD DS","text":"What should be considered after an unplanned controller removal?","options":["Every workstation must be reimaged","Metadata cleanup may be required","All users must be recreated","The forest schema must be deleted"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"یک کنترلر ناموفق می تواند تنظیمات NTDS، اشیاء اتصال و سوابق DNS را که باید پاکسازی کنند، باقی می گذارد.","en":"A failed controller can leave stale NTDS settings, connection objects, and DNS records that must be cleaned up.","de":"Die richtige Antwort ist „Metadata cleanup may be required“; sie passt zum Bereich Deploy and manage AD DS und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"بعد از حذف ناخواسته کنترلر چه نکاتی را باید در نظر گرفت؟","optionsFa":["هر ایستگاه کاری باید دوباره تصویرسازی شود","ممکن است به پاکسازی ابرداده نیاز باشد","همه کاربران باید دوباره ایجاد شوند","طرح جنگل باید حذف شود"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/deploy/ad-ds-metadata-cleanup"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"AD operations: Microsoft source and technical answer review; other audit flags retained from prior review","reviewedAt":"2026-10-09T00:00:00.000Z"},"objective":"Manage AD DS backup, restore, and recovery","objectiveId":"adds-recovery","topic":"Domain controller metadata cleanup","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/deploy/ad-ds-metadata-cleanup"],"keyPoints":["Forced removal/permanent controller loss can leave directory replication metadata behind.","Modern ADUC performs metadata cleanup when the DC computer object is deleted through its permanent-offline confirmation.","Verify remaining replication, Sites and Services, FSMO roles and stale DNS records; metadata cleanup does not imply every DNS reference has vanished."],"whyOthers":["Workstations are unaffected by the loss of one domain controller, so they do not need to be reimaged.","","User objects live in the domain partition and are replicated; they are not tied to the failed controller.","Deleting the forest schema would destroy the forest, which is the opposite of cleanup."],"commandPath":[{"label":"LAB DELETE: use the DC-specific GUI after permanent failure is confirmed","command":"AD Users and Computers → Change Domain Controller (surviving partner) → Domain Controllers → failed DC → Delete → confirm exact name → This Domain Controller is permanently offline"}],"requirements":"Windows Server 2025. Domain Admins or equivalent is the minimum documented permission. Connect modern ADUC/RSAT to a surviving replication partner in the failed controller's domain. The failed DC must be permanently offline; healthy controllers should be gracefully demoted. Review DNS/GC/FSMO impact and never return the retired installation unchanged."},
{"id":"az802-q-048","domain":"Deploy and manage AD DS","text":"Which directory partition contains forest-wide configuration data?","options":["Configuration partition","Domain partition only","Application cache","Local SAM"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"پارتیشن پیکربندی، تنظیمات مربوط به کل فارست مانند سایت‌ها، سرویس‌ها و توپولوژی هم‌رسانی (Replication) را ذخیره می‌کند.","en":"The Configuration partition stores forest-wide configuration such as sites, services, and replication topology.","de":"Die richtige Antwort ist „Configuration partition“; sie passt zum Bereich Deploy and manage AD DS und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام پارتیشن دایرکتوری حاوی داده‌های پیکربندیِ مربوط به کل فارست (Forest) است؟","optionsFa":["پارتیشن پیکربندی (Configuration partition)","فقط پارتیشن دامنه","کش (حافظه موقت) برنامه","پایگاه داده SAM محلی"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows/win32/ad/naming-contexts-and-partitions","https://learn.microsoft.com/en-us/windows/win32/ad/about-application-directory-partitions"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Deploy and manage AD DS domain controllers","objectiveId":"adds-domain-controllers","topic":"Directory partitions","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows/win32/ad/naming-contexts-and-partitions","https://learn.microsoft.com/en-us/windows/win32/ad/about-application-directory-partitions"],"keyPoints":["The Configuration partition stores forest-wide configuration such as sites, services, and replication topology.","It is replicated to every domain controller in the forest, so all controllers hold the same copy.","It is separate from the Schema partition, which defines object classes and attributes, and from each domain partition."],"whyOthers":["","The domain partition holds objects for one domain only and does not contain forest-wide configuration.","There is no directory partition named application cache; an application partition holds application-specific data, not cached configuration.","The local SAM is the local account database on a member server, not a directory partition."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 AD DS. A forest has exactly one configuration partition and one schema partition, plus one domain partition per domain and any application partitions that have been created."},
{"id":"az802-q-049","domain":"Deploy and manage AD DS","text":"What is the purpose of an application partition?","options":["Replace the domain partition","Store Windows event logs","Allocate IP addresses","Store application-specific directory data replicated to selected domain controllers"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"en":"An application directory partition stores service-specific data with a selected replica set, rather than replacing the domain partition.","fa":"پارتیشن دایرکتوری برنامه، داده‌های مخصوص سرویس را با مجموعهٔ منتخب نسخه‌ها ذخیره می‌کند و جایگزین پارتیشن دامین نمی‌شود.","de":"Eine Anwendungsverzeichnispartition speichert dienstspezifische Daten auf ausgewählten Replikaten, ohne die Domänenpartition zu ersetzen."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"هدف از پارتیشن برنامه (Application partition) چیست؟","optionsFa":["جایگزینی پارتیشن دامنه","ذخیره لاگ‌های رویداد (Event logs) ویندوز","تخصیص آدرس‌های IP","ذخیره داده‌های دایرکتوریِ مختصِ برنامه که به کنترلرهای دامنه منتخب هم‌رسانی (Replicate) می‌شوند"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows/win32/ad/about-application-directory-partitions","https://learn.microsoft.com/en-us/windows/win32/ad/enumerating-application-directory-partitions-in-a-forest","https://learn.microsoft.com/en-us/powershell/module/activedirectory/get-adrootdse?view=windowsserver2025-ps"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"Official Microsoft technical and guide review for Windows Server 2025; prior originality, translation and distractor audit statuses retained","reviewedAt":"2026-10-09T19:11:36.000Z"},"objective":"Deploy and manage AD DS domain controllers","objectiveId":"adds-domain-controllers","topic":"Directory partitions","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows/win32/ad/about-application-directory-partitions","https://learn.microsoft.com/en-us/windows/win32/ad/enumerating-application-directory-partitions-in-a-forest","https://learn.microsoft.com/en-us/powershell/module/activedirectory/get-adrootdse?view=windowsserver2025-ps"],"keyPoints":["An application directory partition stores application or service data and can be replicated to a chosen subset of domain controllers.","The replication scope can be a specific domain, selected controllers, or all controllers in the forest, so a service can control where its data lives.","AD-integrated DNS zones are a common example, because a DNS zone can be stored in an application partition and replicated only to DNS servers."],"whyOthers":["An application partition is additional storage and does not replace the domain partition.","Windows event logs are files managed by the Event Log service, not directory partitions.","Allocating IP addresses is a DHCP function, unrelated to directory partitions.",""],"commandPath":[{"label":"Read naming contexts hosted by DC01, including its application replicas","command":"Get-ADRootDSE -Server DC01 | Select-Object -ExpandProperty namingContexts"}],"requirements":"For Windows Server 2025 AD DS, application partitions replicate to their configured DC replica set and are separate from global catalog data. RootDSE lists partitions hosted by the selected server, not all application partitions in the forest. Forest-wide enumeration examines crossRef objects under CN=Partitions and filters systemFlags and nCName."},
{"id":"az802-q-050","domain":"Deploy and manage AD DS","text":"Which AD DS operation restores a deleted user while preserving its original object identity when supported?","options":["New user creation with the same display name","DHCP reconciliation","Authoritative restore of the deleted object","DNS scavenging"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"en":"A supported authoritative restore recovers the original backed-up object and marks it authoritative for replication. A new account with the same name has a different identity; Recycle Bin is a separate eligible-object recovery method.","fa":"بازیابی معتبرِ پشتیبانی‌شده، شیء اصلی موجود در پشتیبان را بازیابی و برای تکثیر معتبر می‌کند؛ ساخت حساب هم‌نام هویت جدیدی می‌دهد. Recycle Bin روش جداگانه‌ای است.","de":"Eine unterstützte autoritative Wiederherstellung stellt das ursprüngliche Objekt aus der Sicherung wieder her und markiert es für die Replikation als maßgeblich. Ein neu erstelltes Konto erhält eine andere Identität."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام عملیات AD DS، در صورت پشتیبانی، کاربر حذف‌شده را بازیابی کرده و در عین حال هویت اصلی شیء (Object identity) آن را حفظ می‌کند؟","optionsFa":["ایجاد کاربر جدید با همان نام نمایشی (Display name)","تطبیق‌سازی (Reconciliation) در DHCP","بازیابی معتبر (Authoritative restore) شیء حذف‌شده","پاکسازی (Scavenging) در DNS"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/retore-deleted-accounts-and-groups-in-ad","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/forest-recovery-guide/ad-forest-recovery-perform-initial-recovery"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"AD operations: Microsoft source and technical answer review; other audit flags retained from prior review","reviewedAt":"2026-10-09T00:00:00.000Z"},"objective":"Manage AD DS backup, restore, and recovery","objectiveId":"adds-recovery","topic":"Object recovery","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/retore-deleted-accounts-and-groups-in-ad","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/forest-recovery-guide/ad-forest-recovery-perform-initial-recovery"],"keyPoints":["Authoritative restore starts from a suitable directory/system-state backup containing the original object.","After restoration in DSRM, ntdsutil can mark a selected object authoritative; group-link/membership recovery can require additional generated LDIF steps.","Recreating the user produces a different SID/GUID. Recycle Bin recovery is a separate workflow for eligible deletions."],"whyOthers":["A recreated account has a new SID and does not inherit the original object's identity, group memberships, or permissions.","DHCP reconciliation compares leases with the DHCP database and has nothing to do with directory objects.","","DNS scavenging deletes stale DNS records on a schedule and does not recover directory objects."],"commandPath":[{"label":"LAB RESTORE: only after directory backup restore in DSRM; substitute the exact test DN","command":"ntdsutil\nactivate instance ntds\nauthoritative restore\nrestore object \"CN=LabUser,OU=Lab,DC=corp,DC=contoso,DC=com\"\nquit\nquit"}],"requirements":"Windows Server 2025 recovery planning. Isolated-lab reference only: use verified pre-deletion backups, DSRM credentials and a supported restore/isolation/reconnection plan. Marking one object authoritative is not automatically a forest-wide restore. Backup-time passwords and attributes may roll back; restore missing parents and verify memberships."},
{"id":"az802-q-051","domain":"Deploy and manage AD DS","text":"What must generally be enabled before the AD Recycle Bin can restore deleted objects through its normal workflow?","options":["BitLocker","AD Recycle Bin feature in the forest","DHCP failover","Hyper-V Replica"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"en":"The forest feature must already be enabled before deletion so the attributes needed for Recycle Bin recovery are retained. Activation is irreversible.","fa":"قابلیت Recycle Bin باید پیش از حذف در Forest فعال شده باشد تا ویژگی‌های لازم برای بازیابی حفظ شوند؛ فعال‌سازی برگشت‌پذیر نیست.","de":"Die Forest-Funktion muss vor der Löschung aktiviert sein, damit die nötigen Attribute erhalten bleiben. Die Aktivierung lässt sich nicht rückgängig machen."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"به‌طور کلی، پیش از آنکه AD Recycle Bin بتواند اشیاء حذف‌شده را از طریق گردش‌کار (workflow) عادی خود بازیابی کند، چه چیزی باید فعال شده باشد؟","optionsFa":["BitLocker","قابلیت AD Recycle Bin در سطح Forest","قابلیت Failover در DHCP","قابلیت Hyper-V Replica"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/get-started/adac/active-directory-recycle-bin"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"AD operations: Microsoft source and technical answer review; other audit flags retained from prior review","reviewedAt":"2026-10-09T00:00:00.000Z"},"objective":"Manage AD DS backup, restore, and recovery","objectiveId":"adds-recovery","topic":"Object recovery","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/get-started/adac/active-directory-recycle-bin"],"keyPoints":["Enable the AD Recycle Bin forest feature before the relevant deletion; activation cannot recover objects already deleted before it was enabled.","Activation is irreversible: Microsoft documents that it cannot be disabled.","The required forest/domain functional levels must already be Windows Server 2008 R2 or later. Enabling the feature does not automatically raise them."],"whyOthers":["BitLocker encrypts volumes and plays no part in directory restore.","","DHCP failover provides redundancy for the DHCP service, not for directory objects.","Hyper-V Replica replicates virtual machines, not individual directory objects."],"requirements":"Windows Server 2025. Verify functional levels and appropriate forest-wide enablement rights first, then allow configuration replication to complete. Recover only eligible objects within their deleted-object lifetime. Recycle Bin does not replace AD DS backups or forest recovery planning."},
{"id":"az802-q-052","domain":"Deploy and manage AD DS","text":"Which action is required before increasing a domain functional level?","options":["Verify all domain controllers meet the required Windows Server version","Delete all global catalogs","Disable replication","Remove every trust"],"correct":0,"source":"https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/raise-domain-forest-functional-levels","rationale":{"en":"Every DC in the domain must support the target domain functional level. Check OS inventory, replication and backups first. Supported lowering exists, but only within Microsoft's OS and enabled-feature restrictions.","fa":"همهٔ کنترل‌کننده‌های دامنه باید سطح عملکردی هدف را پشتیبانی کنند. ابتدا نسخهٔ سیستم‌عامل، تکثیر و پشتیبان‌ها را بررسی کنید. پایین‌آوردن سطح فقط تحت محدودیت‌های مستند Microsoft ممکن است.","de":"Jeder DC der Domäne muss die Ziel-Funktionsebene unterstützen. Prüfe Betriebssysteme, Replikation und Sicherungen. Ein Absenken ist nur unter Microsofts Versions- und Funktionsbedingungen möglich."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"پیش از ارتقای سطح عملکردی دامنه (domain functional level)، انجام چه اقدامی ضروری است؟","optionsFa":["اطمینان از اینکه تمام کنترل‌کننده‌های دامنه (Domain Controllers) دارای نسخه مورد نیاز ویندوز سرور هستند","حذف تمام Global Catalogها","غیرفعال کردن Replication (همگام‌سازی داده‌ها)","حذف تمام روابط اعتماد (Trustها)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/raise-domain-forest-functional-levels","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/active-directory-functional-levels","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/lower-domain-forest-functional-levels"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"Microsoft source and answer verification; original originality, translation and distractor audit flags preserved","reviewedAt":"2026-10-09T19:09:53Z"},"objective":"Manage AD DS functional levels","objectiveId":"adds-functional-levels","topic":"Functional levels","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/raise-domain-forest-functional-levels","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/active-directory-functional-levels","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/lower-domain-forest-functional-levels"],"keyPoints":["Inventory all controllers in the domain against the target level.","Verify healthy replication and backups before changing the level.","Do not describe level changes as universally irreversible or freely reversible."],"whyOthers":["","Deleting GCs is not a prerequisite.","Replication must be healthy, not disabled.","Existing trusts need not all be removed."],"commandPath":[{"label":"Inventory controllers across domains","command":"(Get-ADForest).Domains | ForEach-Object { Get-ADDomainController -Filter * -Server $_ } | Select-Object HostName,Domain,OperatingSystem,OperatingSystemVersion"},{"label":"Read levels","command":"Get-ADDomain | Select-Object DomainMode; Get-ADForest | Select-Object ForestMode"}],"requirements":"Windows Server 2025 DCs support the 2016 and 2025 levels, not 2012 R2. A forest level cannot exceed its domain levels; raising an all-2025 forest to 2025 also raises its domains automatically."},
{"id":"az802-q-053","domain":"Deploy and manage AD DS","text":"What is the difference between a domain functional level and a forest functional level?","options":["Domain level controls DHCP; forest level controls DNS","Domain level is for clients only; forest level is for printers","They are identical settings","Domain level applies to a domain; forest level applies to the forest"],"correct":3,"source":"https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/active-directory-functional-levels","rationale":{"en":"Domain functional level governs capabilities in one domain; forest functional level governs forest-wide capabilities. A domain level may be higher than its forest level but cannot be lower.","fa":"سطح عملکردی دامنه قابلیت‌های یک دامنه و سطح عملکردی جنگل قابلیت‌های کل جنگل را تعیین می‌کند. سطح دامنه می‌تواند از سطح جنگل بالاتر باشد ولی نمی‌تواند پایین‌تر باشد.","de":"Die Domänen-Funktionsebene steuert Fähigkeiten einer Domäne, die Forest-Funktionsebene forestweite Fähigkeiten. Eine Domänenebene darf höher, aber nicht niedriger als die Forest-Ebene sein."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"تفاوت بین «سطح عملکردی دامنه» (Domain Functional Level) و «سطح عملکردی فارست» (Forest Functional Level) چیست؟","optionsFa":["سطح دامنه DHCP را کنترل می‌کند؛ سطح فارست DNS را کنترل می‌کند","سطح دامنه فقط برای کلاینت‌هاست؛ سطح فارست برای چاپگرهاست","آن‌ها تنظیماتی یکسان هستند","سطح دامنه برای یک دامنه اعمال می‌شود؛ سطح فارست برای کل فارست اعمال می‌شود"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/active-directory-functional-levels","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/raise-domain-forest-functional-levels"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"Microsoft source and answer verification; original originality, translation and distractor audit flags preserved","reviewedAt":"2026-10-09T19:09:53Z"},"objective":"Manage AD DS functional levels","objectiveId":"adds-functional-levels","topic":"Functional levels","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/active-directory-functional-levels","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/raise-domain-forest-functional-levels"],"keyPoints":["Domain and forest levels have different feature scopes.","Both affect supported DC operating systems, not member-server or workstation OS requirements.","The forest level cannot exceed the lowest domain level."],"whyOthers":["These levels are not DHCP versus DNS settings.","They are not client versus printer settings.","They are separate settings with different scopes.",""],"requirements":"Windows Server 2025 AD DS. Server 2019 and 2022 use the 2016 functional level; Server 2025 adds a 2025 level.","commandPath":[{"label":"Compare current level scopes","command":"Get-ADDomain | Select-Object Name,DomainMode; Get-ADForest | Select-Object Name,ForestMode"}]},
{"id":"az802-q-054","domain":"Deploy and manage AD DS","text":"Which permission model is best for delegating password resets in one OU without granting domain-wide administration?","options":["Give the group Schema Admins","Disable inheritance on the domain root","Delegate the Reset Password task on that OU","Add the help-desk group to Domain Admins"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"تفویض اختیار (Delegation) می‌تواند امکان انجام وظیفه‌ای با دامنه عملیاتی محدود را در یک OU خاص فراهم کند.","en":"Delegation can grant a narrowly scoped task on a selected OU.","de":"Die richtige Antwort ist „Delegate the Reset Password task on that OU“; sie passt zum Bereich Deploy and manage AD DS und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام مدل مجوز برای تفویض اختیارِ بازنشانی رمز عبور در یک OU (واحد سازمانی) بدون اعطای دسترسی مدیریتی در سطح کل دامنه، مناسب‌تر است؟","optionsFa":["دادن دسترسی به گروه Schema Admins","غیرفعال کردن ارث‌بری (Inheritance) در ریشه دامنه","تفویض وظیفه بازنشانی رمز عبور (Reset Password) برای آن OU","افزودن گروه Help-desk به گروه Domain Admins"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/delegation-control-wizard"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"AD operations: Microsoft source and technical answer review; other audit flags retained from prior review","reviewedAt":"2026-10-09T00:00:00.000Z"},"objective":"Delegate administration of AD DS objects","objectiveId":"adds-delegation","topic":"Delegation of administration","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/delegation-control-wizard"],"keyPoints":["The Delegation of Control Wizard grants a principal specific rights on an OU and its child objects.","Delegating the Reset Password task on one OU gives help-desk staff exactly that task without domain-wide rights.","If a delegated task does not work, check for a denied ACE or a conflicting inherited permission on the affected objects."],"whyOthers":["Schema Admins can change the forest schema, which is far beyond resetting passwords in one OU.","Disabling inheritance at the domain root breaks normal permission flow and can cause wide outages.","","Adding the help-desk group to Domain Admins grants full control of the domain and violates least privilege."],"commandPath":[{"label":"LAB ACCESS CHANGE: delegate only the reset task","command":"AD Users and Computers → target OU → Delegate Control → help-desk group → Reset user passwords and force password change at next logon → Finish"}],"requirements":"Windows Server 2025. Use OU-scoped task delegation, a help-desk group and unprivileged test accounts. Inheritance and deny entries affect the result; protected administrator accounts may not inherit ordinary OU delegation. Review actual ACLs rather than assuming moving any account automatically changes its effective rights."},
{"id":"az802-q-055","domain":"Deploy and manage AD DS","text":"What is the main risk of linking a GPO at the domain root?","options":["It disables DNS automatically","It can affect many users and computers in the domain","It cannot process on domain controllers","It only affects one user"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"لینک‌های متصل به ریشه دامنه (Domain-root links) دامنه اثرگذاری گسترده‌ای دارند، بنابراین تنظیمات باید با دقت و به‌صورت هدفمند آزمایش و فیلتر شوند.","en":"Domain-root links have broad scope, so settings should be tested and filtered deliberately.","de":"Die richtige Antwort ist „It can affect many users and computers in the domain“; sie passt zum Bereich Deploy and manage AD DS und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"ریسک اصلیِ اعمال (لینک کردن) یک GPO در ریشه دامنه چیست؟","optionsFa":["DNS را به‌طور خودکار غیرفعال می‌کند","می‌تواند بر بسیاری از کاربران و رایانه‌های موجود در دامنه تأثیر بگذارد","نمی‌تواند روی کنترل‌کننده‌های دامنه (Domain Controllers) پردازش شود","تنها بر یک کاربر تأثیر می‌گذارد"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/group-policy/group-policy-scope","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/group-policy/group-policy-processing"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"AD operations: Microsoft source and technical answer review; other audit flags retained from prior review","reviewedAt":"2026-10-09T00:00:00.000Z"},"objective":"Manage Group Policy processing and precedence","objectiveId":"gpo-processing","topic":"Group Policy scope","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/group-policy/group-policy-scope","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/group-policy/group-policy-processing"],"keyPoints":["A domain-root GPO link can affect many descendant users and computers.","Security/WMI filters, disabled sections, inheritance and enforcement determine actual applicability.","Test a restricted OU/user/computer scenario before deploying a broad root link."],"whyOthers":["A GPO does not disable DNS; no Group Policy setting turns off DNS automatically.","","Domain-root GPOs do process on domain controllers; they are commonly used to configure controller settings.","A domain-root link affects the whole domain, not just a single user."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 AD DS. Settings in computer configuration apply at boot and on refresh; user configuration applies at sign-in and on refresh."},
{"id":"az802-q-056","domain":"Deploy and manage AD DS","text":"Which order describes normal Group Policy processing from broad to specific?","options":["Local, Site, Domain, OU","OU, Domain, Site, Local","Domain, Local, OU, Site","Site, OU, Local, Domain"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"ترتیب LSDOU باعث می‌شود تنظیماتِ به‌مراتب جزئی‌تر در مراحل بعدی اعمال شوند؛ بنابراین، تنظیمات OU معمولاً می‌توانند بر تنظیمات دامنه اولویت داشته و آن‌ها را لغو (Override) کنند.","en":"The LSDOU order applies increasingly specific settings later, so an OU setting can normally override a domain setting.","de":"Die richtige Antwort ist „Local, Site, Domain, OU“; sie passt zum Bereich Deploy and manage AD DS und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام ترتیب، روند عادی پردازش «خط‌مشی گروهی» (Group Policy) را از سطح کلی به جزئی توصیف می‌کند؟","optionsFa":["Local (محلی)، Site (سایت)، Domain (دامنه)، OU (واحد سازمانی)","OU، Domain، Site، Local","Domain، Local، OU، Site","Site، OU، Local، Domain"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/group-policy/group-policy-processing"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"AD operations: Microsoft source and technical answer review; other audit flags retained from prior review","reviewedAt":"2026-10-09T00:00:00.000Z"},"objective":"Manage Group Policy processing and precedence","objectiveId":"gpo-processing","topic":"Group Policy processing","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/group-policy/group-policy-processing"],"keyPoints":["Normal processing order is Local, Site, Domain, then parent-to-child OUs.","Later applicable settings normally take precedence for conflicts; at the same container, link order 1 has highest priority.","Block Inheritance changes which ancestor links apply; enforcement preserves ancestor precedence. These are exceptions to normal scope/conflict rules, not a reversal of every processing step."],"whyOthers":["","OU, Domain, Site, Local reverses the broad-to-specific order and would make local policy win, which is not how processing works.","Domain, Local, OU, Site puts local policy after domain policy, but local policy is processed first.","Site, OU, Local, Domain puts site policy first, but local policy always processes before site policy."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 AD DS. A maximum of 999 GPOs can apply to a single user or computer, and LSDOU is the order in which their settings are processed."},
{"id":"az802-q-057","domain":"Deploy and manage AD DS","text":"A child OU GPO and a parent OU GPO configure the same setting. Which normally has precedence?","options":["The parent OU GPO","The local policy always","The default domain policy always","The child OU GPO"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"لینک‌های OU که جزئی‌تر (خاص‌تر) هستند، در مراحل بعدی پردازش می‌شوند و عموماً تنظیمات متناقضِ والد را لغو می‌کنند.","en":"More-specific OU links process later and generally override conflicting parent settings.","de":"Die richtige Antwort ist „The child OU GPO“; sie passt zum Bereich Deploy and manage AD DS und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"یک GPO مربوط به OU فرزند و یک GPO مربوط به OU والد، تنظیم یکسانی را پیکربندی می‌کنند. کدام‌یک معمولاً اولویت دارد؟","optionsFa":["GPO مربوط به OU والد","همیشه خط‌مشی محلی (Local policy)","همیشه خط‌مشی پیش‌فرض دامنه (Default domain policy)","GPO مربوط به OU فرزند"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/group-policy/group-policy-processing"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage Group Policy processing and precedence","objectiveId":"gpo-processing","topic":"Group Policy processing","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/group-policy/group-policy-processing"],"keyPoints":["A more specific child-OU GPO processes later than a parent-OU GPO and normally overrides the same setting from the parent.","This is the last-writer-wins behaviour of normal Group Policy processing.","An enforced link on the parent reverses this precedence and wins over the child."],"whyOthers":["A parent-OU link is less specific and processes earlier than the child, so it does not normally win.","Local policy is the least specific and is applied first, so it loses to a conflicting OU setting.","The Default Domain Policy is linked at the domain root and is less specific than an OU link.",""],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 AD DS. The precedence rule applies to conflicting settings of the same kind; settings in different policy areas do not override each other."},
{"id":"az802-q-058","domain":"Deploy and manage AD DS","text":"What does Block Inheritance do on an OU?","options":["Prevents users from logging on","Deletes linked GPOs","Prevents inherited GPO settings from parent containers unless enforced","Blocks all local policies"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"قابلیت Block Inheritance مانع از وراثت عادی از کانتینرهای والد می‌شود؛ با این حال، لینکِ دارای وضعیت Enforced همچنان می‌تواند اعمال شود.","en":"Block Inheritance stops normal inheritance from parent containers; an enforced link can still apply.","de":"Die richtige Antwort ist „Prevents inherited GPO settings from parent containers unless enforced“; sie passt zum Bereich Deploy and manage AD DS und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"قابلیت «Block Inheritance» (مسدودسازی وراثت) در یک OU چه کاری انجام می‌دهد؟","optionsFa":["از ورود (Log on) کاربران جلوگیری می‌کند","اشیاء GPO لینک‌شده را حذف می‌کند","از اعمال تنظیمات GPO که از کانتینرهای والد به ارث می‌رسند جلوگیری می‌کند (مگر اینکه گزینه Enforced فعال باشد)","تمام پالیسی‌های محلی (Local Policies) را مسدود می‌کند"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/group-policy/group-policy-processing"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"AD operations: Microsoft source and technical answer review; other audit flags retained from prior review","reviewedAt":"2026-10-09T00:00:00.000Z"},"objective":"Manage Group Policy processing and precedence","objectiveId":"gpo-processing","topic":"Group Policy inheritance","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/group-policy/group-policy-processing"],"keyPoints":["Block Inheritance stops parent-container GPOs from applying to that container.","It does not remove links or delete GPOs; it only stops inheritance at that point.","A GPO with the Enforced link setting still applies through Block Inheritance."],"whyOthers":["Block Inheritance does not affect logon rights or prevent users from signing in.","It changes how policy is processed; it does not delete any GPO.","","Local Group Policy is processed separately from the domain and is not blocked."],"requirements":"Windows Server 2025 GPMC. Set Block Inheritance on a domain or OU, not an AD site. It blocks ordinary ancestor links, leaves links on the selected container intact, and does not override an enforced ancestor link or delete GPOs."},
{"id":"az802-q-059","domain":"Deploy and manage AD DS","text":"What does an enforced GPO link do?","options":["Converts the GPO into a starter GPO","Prevents lower-level containers from overriding that GPO’s settings in normal processing","Disables security filtering","Applies only to local users"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"وضعیت Enforced باعث می‌شود GPO لینک‌شده در زنجیره وراثت، اولویت بالاتری داشته باشد.","en":"Enforcement gives the linked GPO higher precedence through the inheritance chain.","de":"Die richtige Antwort ist „Prevents lower-level containers from overriding that GPO’s settings in normal processing“; sie passt zum Bereich Deploy and manage AD DS und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"لینک GPO با وضعیت Enforced (اجباری) چه کاری انجام می‌دهد؟","optionsFa":["آن GPO را به یک Starter GPO تبدیل می‌کند","مانع از آن می‌شود که کانتینرهای سطوح پایین‌تر، تنظیمات آن GPO را در پردازش عادی لغو (Override) کنند","فیلترینگ امنیتی (Security Filtering) را غیرفعال می‌کند","فقط برای کاربران محلی اعمال می‌شود"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/group-policy/group-policy-processing"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"AD operations: Microsoft source and technical answer review; other audit flags retained from prior review","reviewedAt":"2026-10-09T00:00:00.000Z"},"objective":"Manage Group Policy processing and precedence","objectiveId":"gpo-processing","topic":"Group Policy inheritance","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/group-policy/group-policy-processing"],"keyPoints":["Enforced is a GPO-link property that prevents descendant links from overriding conflicting ancestor settings.","An enforced ancestor link applies through Block Inheritance.","Enforced does not bypass security/WMI filtering, enable disabled GPO sections or create a PSO Enforced property."],"whyOthers":["Starter GPOs are templates used when creating new GPOs; enforcement is unrelated.","","Security filtering is a separate mechanism and is not disabled by enforcement.","Enforcement applies to the scope of the linked container, not only to local users."],"requirements":"Windows Server 2025. Review Group Policy Inheritance and the applicable link priorities. Do not describe enforcement as every GPO always processing last; it changes precedence and inheritance behavior for that link."},
{"id":"az802-q-060","domain":"Deploy and manage AD DS","text":"Which tool shows the effective Group Policy settings for a particular computer and user?","options":["gpresult","diskpart","repadmin","nslookup"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"ابزار gpresult اطلاعات مربوط به مجموعه نهایی پالیسی‌ها (Resultant Set of Policy) را گزارش می‌دهد که شامل GPOهای اعمال‌شده و ردشده (Denied) است.","en":"gpresult reports Resultant Set of Policy information, including applied and denied GPOs.","de":"Die richtige Antwort ist „gpresult“; sie passt zum Bereich Deploy and manage AD DS und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام ابزار تنظیمات مؤثر (Effective) پالیسی گروهی (Group Policy) را برای یک کامپیوتر و کاربر خاص نمایش می‌دهد؟","optionsFa":["gpresult","diskpart","repadmin","nslookup"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/group-policy/group-policy-modeling-results"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage Group Policy application and filtering","objectiveId":"gpo-application","topic":"Group Policy diagnosis","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/group-policy/group-policy-modeling-results"],"keyPoints":["gpresult reports the Resultant Set of Policy for a user and computer, including which GPOs applied and which were denied.","gpresult /h produces an HTML report, and gpresult /r prints a summary.","It is read-only and runs on the target computer."],"whyOthers":["","Diskpart manages disks and volumes, not policy.","Repadmin reports directory replication, not effective Group Policy.","Nslookup queries DNS records and does not report policy results."],"commandPath":[{"label":"Summarise the applied policy for the current user and computer","command":"gpresult /r"},{"label":"Write a full HTML policy report","command":"gpresult /h C:\\Reports\\policy-results.html"}],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 AD DS and to domain-joined clients. Reporting another user or computer requires the appropriate permissions, and the target must be reachable."},
{"id":"az802-q-061","domain":"Deploy and manage AD DS","text":"Which graphical tool simulates the effect of Group Policy for a proposed user and computer scenario?","options":["Disk Management","DNS Manager","Hyper-V Manager","Group Policy Modeling in GPMC"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"en":"Group Policy Modeling in GPMC simulates the planned scenario. Group Policy Results instead retrieves actual RSoP data from the target computer.","fa":"Group Policy Modeling در GPMC سناریوی پیشنهادی را شبیه‌سازی می‌کند؛ Group Policy Results نتیجهٔ واقعی رایانهٔ مقصد را می‌گیرد.","de":"Group Policy Modeling in der GPMC simuliert das geplante Szenario. Group Policy Results ermittelt dagegen die tatsächlich angewendeten Einstellungen."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام ابزار گرافیکی اثر Group Policy را برای سناریوی پیشنهادیِ یک کاربر و رایانه شبیه‌سازی می‌کند؟","optionsFa":["Disk Management","DNS Manager","Hyper-V Manager","Group Policy Modeling در GPMC"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/group-policy/group-policy-modeling-results"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"AD operations: Microsoft source and technical answer review; other audit flags retained from prior review","reviewedAt":"2026-10-09T00:00:00.000Z"},"objective":"Manage Group Policy application and filtering","objectiveId":"gpo-application","topic":"Group Policy diagnosis","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/group-policy/group-policy-modeling-results"],"keyPoints":["Group Policy Modeling in GPMC simulates the effect of policy for a chosen user and computer combination before it is applied.","Group Policy Results reports what actually happened on a real computer rather than a simulation.","Modeling needs a suitable domain controller and may use a saved plan; Results needs the target computer to be reachable and logged on."],"whyOthers":["Disk Management configures volumes and has no policy modeling.","DNS Manager administers DNS zones and does not model policy.","Hyper-V Manager administers virtual machines and does not model Group Policy.",""],"requirements":"Windows Server 2025 GPMC and appropriate Modeling permissions. A suitable DC performs the simulation; the simulated client need not be online. Modeling excludes local GPO evaluation, so validate actual behavior with Results/gpresult on the target."},
{"id":"az802-q-062","domain":"Deploy and manage AD DS","text":"A GPO is linked correctly but does not apply to a security group. What should you check first?","options":["The DHCP lease pool","The printer driver version","Security filtering and the group’s Read and Apply Group Policy permissions","The server’s disk partition style"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"فیلترینگ امنیتی تعیین می‌کند که کدام موجودیت‌ها (principals) می‌توانند یک GPO را بخوانند و اعمال کنند.","en":"Security filtering controls which principals can read and apply a GPO.","de":"Die richtige Antwort ist „Security filtering and the group’s Read and Apply Group Policy permissions“; sie passt zum Bereich Deploy and manage AD DS und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"یک GPO به درستی لینک (متصل) شده است اما روی یک گروه امنیتی اعمال نمی‌شود. ابتدا چه چیزی را باید بررسی کنید؟","optionsFa":["استخر (pool) اجاره‌دهی آدرس‌های DHCP","نسخه درایور چاپگر","فیلترینگ امنیتی (Security filtering) و مجوزهای Read و Apply Group Policy مربوط به گروه","سبک پارتیشن‌بندی دیسک سرور"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/group-policy/cannot-apply-user-gpo-when-computer-objects-dont-have-read-permissions","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/group-policy/group-policy-scope"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"AD operations: Microsoft source and technical answer review; other audit flags retained from prior review","reviewedAt":"2026-10-09T00:00:00.000Z"},"objective":"Manage Group Policy application and filtering","objectiveId":"gpo-application","topic":"Group Policy filtering","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/group-policy/cannot-apply-user-gpo-when-computer-objects-dont-have-read-permissions","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/group-policy/group-policy-scope"],"keyPoints":["Security filtering controls which principals can read and apply a GPO.","The group or user must have both Read and Apply Group Policy permissions for the GPO to affect them.","For user settings, the computer object also needs Read permission on the GPO, which is a common cause of user policy not applying."],"whyOthers":["DHCP scope settings do not affect whether a GPO applies.","Printer drivers are unrelated to Group Policy scope.","","The disk partition style of a server has no bearing on policy application."],"commandPath":[{"label":"Show which GPOs were denied for a computer","command":"gpresult /scope computer /v"}],"requirements":"Windows Server 2025. Authenticated Users normally has both Read and Apply Group Policy. Since MS16-072, the computer retrieves user GPOs in its own security context and needs Read. Removing Authenticated Users from Security Filtering removes both permissions; grant necessary computer Read separately while retaining the intended user Apply scope."},
{"id":"az802-q-063","domain":"Deploy and manage AD DS","text":"What is the purpose of Group Policy loopback processing?","options":["Create an AD trust","Apply user settings based on the computer’s location or role","Replicate SYSVOL faster","Reset a user password"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"قابلیت Loopback برای کامپیوترهای اشتراکی، کیوسک‌ها، میزبان‌های RDS و سایر مواردی که در آن‌ها زمینه (کانتکست) کامپیوتر باید بر سیاست‌های کاربر تأثیر بگذارد، مفید است.","en":"Loopback is useful for shared computers, kiosks, RDS hosts, and other cases where computer context should influence user policy.","de":"Die richtige Antwort ist „Apply user settings based on the computer’s location or role“; sie passt zum Bereich Deploy and manage AD DS und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"هدف از پردازش Loopback در Group Policy چیست؟","optionsFa":["ایجاد یک رابطه اعتماد (Trust) در AD","اعمال تنظیمات کاربر بر اساس موقعیت مکانی یا نقش کامپیوتر","تکثیر (Replicate) سریع‌تر SYSVOL","بازنشانی رمز عبور کاربر"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/group-policy/loopback-processing-of-group-policy","https://learn.microsoft.com/en-us/troubleshoot/windows-server/group-policy/apply-group-policy-objects-rds"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage Group Policy application and filtering","objectiveId":"gpo-application","topic":"Group Policy loopback","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/group-policy/loopback-processing-of-group-policy","https://learn.microsoft.com/en-us/troubleshoot/windows-server/group-policy/apply-group-policy-objects-rds"],"keyPoints":["Loopback processing applies user settings based on the computer's location or role, regardless of who logs on.","It is used for shared computers, kiosks, and Remote Desktop session hosts.","It has two modes, Merge and Replace."],"whyOthers":["Loopback is a Group Policy setting and does not create an AD trust.","","SYSVOL replication is governed by DFSR, not by loopback processing.","Resetting a user password is a directory operation that loopback does not perform."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 AD DS. Loopback is configured under Computer Configuration, Administrative Templates, System, Group Policy, and requires a restart or a policy refresh to take effect."},
{"id":"az802-q-064","domain":"Deploy and manage AD DS","text":"Which loopback mode replaces the user’s normal user-policy list with the computer’s user-policy list?","options":["Merge","Replace","Append","Redirect"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"حالت Replace تنها از تنظیمات کاربریِ موجود در GPOهایی استفاده می‌کند که برای کامپیوتر تعریف شده‌اند؛ اما حالت Merge آن‌ها را با لیست سیاست‌های معمول کاربر ترکیب می‌کند.","en":"Replace uses only the user settings from GPOs scoped to the computer; Merge combines them with the user’s normal policy list.","de":"Die richtige Antwort ist „Replace“; sie passt zum Bereich Deploy and manage AD DS und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام حالت Loopback، لیست سیاست‌های کاربریِ معمولِ کاربر را با لیست سیاست‌های کاربریِ مربوط به کامپیوتر جایگزین می‌کند؟","optionsFa":["Merge (ادغام)","Replace (جایگزینی)","Append (افزودن به انتها)","Redirect (تغییر مسیر)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/group-policy/loopback-processing-of-group-policy","https://learn.microsoft.com/en-us/troubleshoot/windows-server/group-policy/apply-group-policy-objects-rds"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage Group Policy application and filtering","objectiveId":"gpo-application","topic":"Group Policy loopback","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/group-policy/loopback-processing-of-group-policy","https://learn.microsoft.com/en-us/troubleshoot/windows-server/group-policy/apply-group-policy-objects-rds"],"keyPoints":["In Replace mode, the user settings from GPOs scoped to the computer replace the user's normal user-policy list.","In Merge mode, the computer's user settings are combined with the user's normal user settings instead of replacing them.","Replace gives strict control over a shared or kiosk computer, while Merge is less disruptive."],"whyOthers":["Merge combines the computer's user settings with the user's normal settings rather than replacing them.","","There is no loopback mode named Append.","Redirect is not a loopback mode."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 AD DS. The loopback setting is per-computer, and in Replace mode the user's normal user-side GPOs do not apply on that computer."},
{"id":"az802-q-065","domain":"Deploy and manage AD DS","text":"A Group Policy Preference item should apply only if a registry value exists. Which feature is appropriate?","options":["Schema extension","RID allocation","DNS delegation","Item-level targeting"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"قابلیت Group Policy Preferences می‌تواند از شرایط هدف‌گذاری در سطح آیتم، مانند مقادیر رجیستری، گروه‌های امنیتی، محدوده‌های IP یا نام‌های رایانه استفاده کند.","en":"Group Policy Preferences can use item-level targeting conditions such as registry values, security groups, IP ranges, or computer names.","de":"Die richtige Antwort ist „Item-level targeting“; sie passt zum Bereich Deploy and manage AD DS und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"یک مورد (Item) از نوع Group Policy Preference باید تنها در صورتی اعمال شود که یک مقدار خاص در رجیستری وجود داشته باشد. کدام ویژگی برای این کار مناسب است؟","optionsFa":["توسعه طرح‌واره (Schema extension)","تخصیص RID","تفویض اختیار DNS (DNS delegation)","هدف‌گذاری در سطح آیتم (Item-level targeting)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/group-policy/group-policy-preferences","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/group-policy/group-policy-processing"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage Group Policy application and filtering","objectiveId":"gpo-application","topic":"Group Policy preferences","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/group-policy/group-policy-preferences","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/group-policy/group-policy-processing"],"keyPoints":["Item-level targeting applies a single preference item only when its conditions match, such as a registry value, security group, IP range, or computer name.","Conditions can be combined with AND/OR, and a false result means the item is skipped.","It is a property of the preference item, not of the whole GPO."],"whyOthers":["A schema extension adds object classes and attributes to the directory and has nothing to do with preference filtering.","RID allocation assigns identifiers to new security principals and is unrelated to Group Policy.","DNS delegation hands a DNS zone to another server and does not filter preference items.",""],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 AD DS. Group Policy Preferences are available only in domain-based GPOs, and each preference item can carry its own item-level targeting conditions."},
{"id":"az802-q-066","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"What is the primary role of Windows Admin Center?","options":["A DNS root server","A disk-encryption algorithm","Browser-based management of Windows Server and related infrastructure","Replacement for Active Directory"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"ابزار Windows Admin Center یک رابط مدیریتی مبتنی بر وب برای سرورها، کلاسترها، ماشین‌های مجازی (VMs)، فضای ذخیره‌سازی، شبکه و یکپارچه‌سازی‌های ترکیبی (هیبریدی) فراهم می‌کند.","en":"Windows Admin Center provides a web-based management interface for servers, clusters, VMs, storage, networking, and hybrid integrations.","de":"Die richtige Antwort ist „Browser-based management of Windows Server and related infrastructure“; sie passt zum Bereich Manage Windows Server instances and workloads in a hybrid environment und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"نقش اصلی Windows Admin Center چیست؟","optionsFa":["یک سرور ریشه DNS","یک الگوریتم رمزنگاری دیسک","مدیریت مبتنی بر مرورگرِ Windows Server و زیرساخت‌های مرتبط","جایگزینی برای Active Directory"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/manage/windows-admin-center/understand/what-is","https://learn.microsoft.com/en-us/windows-server/manage/windows-admin-center/deploy/install"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage Windows Server by using Windows Admin Center","objectiveId":"hybrid-windows-admin-center","topic":"Windows Admin Center","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/manage/windows-admin-center/understand/what-is","https://learn.microsoft.com/en-us/windows-server/manage/windows-admin-center/deploy/install"],"keyPoints":["Windows Admin Center is a browser-based management tool for Windows Server, clusters, virtual machines, storage, and networking.","It is installed locally and runs a gateway that manages servers through Remote PowerShell and WMI over WinRM.","It replaces the need to open a Remote Desktop session for many day-to-day management tasks, and it can extend to Azure and Azure Arc scenarios."],"whyOthers":["Windows Admin Center is not a DNS root server; it is a management console, and DNS service is a separate server role.","Windows Admin Center is not a disk-encryption algorithm; disk encryption is provided by BitLocker.","","Windows Admin Center is not a replacement for Active Directory; it manages servers and does not provide directory services."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 and to Windows client machines. A gateway is installed and then managed servers are added by name; the managed node needs Remote Management (WinRM) and the required firewall rules enabled."},
{"id":"az802-q-067","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"Which Windows Admin Center deployment is installed on an organization’s own server?","options":["Hyper-V replica broker","On-premises gateway","Azure DNS resolver","Entra Connect cloud sync"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"دروازه محلی (On-premises gateway) در محیط سازمان میزبانی می‌شود و منابع قابل‌دسترسی را مدیریت می‌کند.","en":"An on-premises gateway is hosted in the organization’s environment and manages reachable resources.","de":"Die richtige Antwort ist „On-premises gateway“; sie passt zum Bereich Manage Windows Server instances and workloads in a hybrid environment und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام‌یک از انواع پیاده‌سازی Windows Admin Center روی سرور خودِ سازمان نصب می‌شود؟","optionsFa":["کارگزار کپی‌برداری (Replica broker) در Hyper-V","دروازه محلی (On-premises gateway)","حل‌کننده (Resolver) DNS در Azure","همگام‌سازی ابری Entra Connect"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/manage/windows-admin-center/understand/what-is","https://learn.microsoft.com/en-us/windows-server/manage/windows-admin-center/plan/installation-options"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage Windows Server by using Windows Admin Center","objectiveId":"hybrid-windows-admin-center","topic":"Windows Admin Center","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/manage/windows-admin-center/understand/what-is","https://learn.microsoft.com/en-us/windows-server/manage/windows-admin-center/plan/installation-options"],"keyPoints":["An on-premises gateway is installed in the organization's own environment and manages the resources it can reach.","The gateway is the web server plus management service that serves the browser session and forwards actions to managed nodes.","The alternative installation option is a per-user local installation on a Windows PC, which is not shared by other administrators."],"whyOthers":["A Hyper-V Replica broker is a failover-clustering role for replica coordination, not a Windows Admin Center deployment.","","Azure DNS resolver is an Azure DNS service and has nothing to do with where the gateway is hosted.","Microsoft Entra Connect cloud sync synchronises identities to Microsoft Entra ID and is not a Windows Admin Center deployment type."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. A shared gateway installation lets multiple administrators connect through one gateway; a per-user installation on a Windows client is limited to that user."},
{"id":"az802-q-068","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"Which port is the default HTTPS port commonly used by a Windows Admin Center gateway?","options":["22","80","443","3389"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"«Windows Admin Center» به‌طور پیش‌فرض از HTTPS برای برقراری ارتباط امن بین مرورگر و دروازه استفاده می‌کند، هرچند امکان تغییر این پورت وجود دارد.","en":"Windows Admin Center uses HTTPS for secure browser-to-gateway communication by default, though the port can be changed.","de":"Die richtige Antwort ist „443“; sie passt zum Bereich Manage Windows Server instances and workloads in a hybrid environment und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"پورت پیش‌فرض HTTPS که معمولاً توسط دروازه (Gateway) «Windows Admin Center» استفاده می‌شود، کدام است؟","optionsFa":["22","80","443","3389"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/manage/windows-admin-center/deploy/install"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage Windows Server by using Windows Admin Center","objectiveId":"hybrid-windows-admin-center","topic":"Windows Admin Center","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/manage/windows-admin-center/deploy/install"],"keyPoints":["Windows Admin Center communicates with the browser over HTTPS by default on port 443.","The port is chosen during installation and can be changed if 443 is already in use.","Because the gateway is browser-based, the HTTPS port must be reachable from the administrator's browser, not from the managed servers."],"whyOthers":["Port 22 is the default port for SSH, used for remote shell access rather than Windows Admin Center's web interface.","Port 80 is plain HTTP and is not the secure default for the gateway.","","Port 3389 is Remote Desktop Protocol, used by Remote Desktop sessions rather than by the Windows Admin Center web interface."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. If the default port conflicts with another service, choose an alternate HTTPS port during installation and open it in the gateway's firewall."},
{"id":"az802-q-069","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"What is the main purpose of Azure Arc-enabled servers?","options":["Convert every server into an Azure VM","Replace domain controllers with Linux","Provide local DHCP leases","Project on-premises servers into Azure for management and governance"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"سرویس «Azure Arc» قابلیت‌های صفحه کنترل (Control-plane) Azure نظیر مدیریت موجودی (Inventory)، سیاست‌ها (Policies)، افزونه‌ها و پایش (Monitoring) را به سرورهای غیر Azure گسترش می‌دهد.","en":"Azure Arc extends Azure control-plane capabilities such as inventory, policy, extensions, and monitoring to non-Azure servers.","de":"Die richtige Antwort ist „Project on-premises servers into Azure for management and governance“; sie passt zum Bereich Manage Windows Server instances and workloads in a hybrid environment und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"هدف اصلی سرورهای مجهز به «Azure Arc» چیست؟","optionsFa":["تبدیل هر سرور به یک ماشین مجازی (VM) در Azure","جایگزینی کنترل‌کننده‌های دامنه (Domain Controllers) با لینوکس","ارائه اجاره‌های (Leases) محلی DHCP","انتقال (Project) سرورهای درون‌سازمانی (On-premises) به Azure جهت مدیریت و حاکمیت (Governance)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-arc/servers/overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Connect servers to Azure with Azure Arc","objectiveId":"hybrid-arc","topic":"Azure Arc-enabled servers","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-arc/servers/overview"],"keyPoints":["Azure Arc-enabled servers project on-premises or other-cloud servers into Azure so they can be managed with Azure control-plane tools.","It enables inventory, tags, Azure Policy, extensions, monitoring, and update management for machines that are not Azure virtual machines.","The server keeps running where it is; Arc adds a management representation of it in Azure rather than moving it."],"whyOthers":["Converting every server into an Azure VM describes a migration, whereas Arc extends management without moving the workload.","Replacing domain controllers with Linux is unrelated to Azure Arc.","Providing local DHCP leases is a networking role; Arc does not assign addresses.",""],"requirements":"Applies to Windows Server 2025, 2022, 2019, 2016, and to supported Linux distributions. Arc-enabled servers must be able to reach the required Azure endpoints, directly or through a proxy."},
{"id":"az802-q-070","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"Which component connects a Windows Server to Azure Arc?","options":["Hyper-V integration service","SMB redirector","Azure Connected Machine agent","DHCP relay agent"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"عامل ماشین متصل (Connected Machine agent)، اتصال Arc سرور را برقرار کرده و امکان استفاده از افزونه‌ها و قابلیت‌های مدیریتیِ پشتیبانی‌شده را فراهم می‌کند.","en":"The Connected Machine agent establishes the server’s Arc connection and enables supported extensions and management features.","de":"Die richtige Antwort ist „Azure Connected Machine agent“; sie passt zum Bereich Manage Windows Server instances and workloads in a hybrid environment und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام مؤلفه، یک «Windows Server» را به «Azure Arc» متصل می‌کند؟","optionsFa":["سرویس یکپارچه‌سازی Hyper-V","تغییرمسیردهنده (Redirector) پروتکل SMB","عامل (Agent) ماشین متصل به Azure","عامل واسط (Relay agent) پروتکل DHCP"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-arc/servers/agent-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Connect servers to Azure with Azure Arc","objectiveId":"hybrid-arc","topic":"Azure Arc-enabled servers","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-arc/servers/agent-overview"],"keyPoints":["The Azure Connected Machine agent connects a Windows or Linux machine to Azure Arc.","It creates the machine's metadata representation in Azure and enables supported extensions and management features.","Agent health is the first thing to check when an Arc resource is offline or an extension does not deploy."],"whyOthers":["A Hyper-V integration service runs inside a guest to provide host-to-guest services and does not connect a server to Azure.","The SMB redirector is the client component that accesses SMB file shares and is unrelated to Arc.","","A DHCP relay agent forwards DHCP requests between subnets and does not connect a machine to Azure Arc."],"commandPath":[{"label":"Run the connection script with the service principal","command":"& \"$env:ProgramFiles\\AzureConnectedMachineAgent\\azcmagent.exe\" connect --service-principal-id <appId> --service-principal-secret <secret> --tenant-id <tenantId> --location <region> --resource-group <rg>"},{"label":"Show the agent's connection and extension status","command":"azcmagent show"}],"requirements":"Applies to Windows Server 2025, 2022, 2019, 2016, and supported Linux distributions. The Connected Machine agent service runs as a local service and needs outbound HTTPS to the Arc endpoints."},
{"id":"az802-q-071","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"A server is connected to Azure Arc but an extension deployment remains pending. What should you verify first?","options":["The server’s wallpaper","Agent health, outbound connectivity, and extension prerequisites","The local printer queue","The forest schema version only"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"عملکرد افزونه‌های Arc به سلامت عامل، در دسترس بودن نقاط پایانی (Endpoints) سرویس Azure و پیکربندی سیستم‌عاملِ پشتیبانی‌شده وابسته است.","en":"Arc extensions depend on a healthy agent, reachable Azure endpoints, and a supported operating-system configuration.","de":"Die richtige Antwort ist „Agent health, outbound connectivity, and extension prerequisites“; sie passt zum Bereich Manage Windows Server instances and workloads in a hybrid environment und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"سروری به Azure Arc متصل است، اما استقرار یک افزونه همچنان در وضعیت «در انتظار» (pending) باقی مانده است. ابتدا چه چیزی را باید بررسی کنید؟","optionsFa":["تصویر پس‌زمینه (Wallpaper) سرور","سلامت عامل (Agent)، قابلیت اتصال خروجی و پیش‌نیازهای افزونه","صف چاپگر محلی","فقط نسخه طرح‌واره (Schema) فارست (Forest)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-arc/servers/agent-overview","https://learn.microsoft.com/en-us/azure/azure-arc/servers/network-requirements"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Connect servers to Azure with Azure Arc","objectiveId":"hybrid-arc","topic":"Azure Arc extensions","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-arc/servers/agent-overview","https://learn.microsoft.com/en-us/azure/azure-arc/servers/network-requirements"],"keyPoints":["Arc extension deployment depends on a healthy agent reporting to Azure.","The server also needs outbound connectivity to the extension's own endpoints, which may differ from the core Arc endpoints.","Extension prerequisites vary by extension, so check the operating-system support and any required platform components."],"whyOthers":["The server's wallpaper is a cosmetic desktop setting and has no effect on extension deployment.","","The local printer queue is unrelated to Azure Arc extensions.","The forest schema version concerns Active Directory and does not affect Arc extension deployment."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Extension installation and upgrade run as SYSTEM on the machine, so a restrictive proxy or egress firewall is a common cause of a pending extension."},
{"id":"az802-q-072","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"What is a key benefit of Azure Update Manager for Arc-enabled servers?","options":["Centralized assessment and scheduling of updates across hybrid machines","Automatic creation of AD trusts","Replacement of all backup systems","Local DNS zone hosting"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"سرویس Update Manager امکاناتی نظیر ارزیابی به‌روزرسانی، مشاهده وضعیت انطباق (Compliance) و زمان‌بندی عملیات نگهداری را برای ماشین‌های Azure و ماشین‌های مجهز به Arc فراهم می‌کند.","en":"Update Manager provides update assessment, compliance views, and maintenance scheduling for Azure and Arc-enabled machines.","de":"Die richtige Antwort ist „Centralized assessment and scheduling of updates across hybrid machines“; sie passt zum Bereich Manage Windows Server instances and workloads in a hybrid environment und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"یکی از مزایای کلیدی Azure Update Manager برای سرورهای مجهز به Arc چیست؟","optionsFa":["ارزیابی و زمان‌بندی متمرکز به‌روزرسانی‌ها برای ماشین‌های هیبریدی","ایجاد خودکار روابط اعتماد (Trusts) در Active Directory","جایگزینی تمام سیستم‌های پشتیبان‌گیری (Backup)","میزبانی ناحیه (Zone) محلی DNS"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/update-manager/overview","https://learn.microsoft.com/en-us/azure/azure-arc/servers/overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage updates for hybrid servers","objectiveId":"hybrid-updates","topic":"Azure Update Manager","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/azure/update-manager/overview","https://learn.microsoft.com/en-us/azure/azure-arc/servers/overview"],"keyPoints":["Azure Update Manager provides update assessment, compliance reporting, and maintenance scheduling for Azure and Arc-enabled machines.","It gives a single view of update state across machines that live in different places.","For non-Azure machines, it relies on the server being connected through Azure Arc."],"whyOthers":["","Automatically creating AD trusts is a directory operation and has nothing to do with update management.","Update Manager does not replace backup systems; backup is a separate service.","Local DNS zone hosting is a DNS Server role function, not an update management feature."],"requirements":"Applies to supported Windows Server and Linux machines. Update Manager is a cloud service, so an Arc-connected machine needs outbound access, and a maintenance configuration is used to schedule patching."},
{"id":"az802-q-073","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"Which Azure service lets you run PowerShell or Python automation on a schedule?","options":["Azure DNS","Azure Files","Azure Bastion only","Azure Automation"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"ران‌بوک‌های (Runbooks) سرویس Azure Automation، گردش‌کارهای مدیریتی را به‌صورت درخواستی (on-demand) یا طبق زمان‌بندی اجرا می‌کنند.","en":"Azure Automation runbooks execute administrative workflows on demand or on schedules.","de":"Die richtige Antwort ist „Azure Automation“; sie passt zum Bereich Manage Windows Server instances and workloads in a hybrid environment und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام سرویس Azure به شما امکان می‌دهد تا عملیات خودکارسازی (اتوماسیون) مبتنی بر PowerShell یا Python را طبق یک زمان‌بندی مشخص اجرا کنید؟","optionsFa":["Azure DNS","Azure Files","فقط Azure Bastion","Azure Automation"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/automation/overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Automate administration with runbooks and managed identities","objectiveId":"hybrid-automation","topic":"Azure Automation","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/azure/automation/overview"],"keyPoints":["Azure Automation runbooks execute administrative workflows, on demand or on a schedule.","Runbooks can be written in PowerShell or Python and can target Azure resources or hybrid machines through Hybrid Runbook Worker.","The service can be used for scheduled tasks that do not need a dedicated server to host them."],"whyOthers":["Azure DNS hosts DNS zones and does not run administrative scripts.","Azure Files provides SMB and REST file shares and does not execute automation.","Azure Bastion provides browser-based RDP and SSH access and does not run scheduled automation.",""],"requirements":"Applies to the Azure Automation service. To run scripts against on-premises machines, a Hybrid Runbook Worker is registered, and the worker needs network access to those machines."},
{"id":"az802-q-074","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"A runbook must change resources in Azure. What should it use instead of embedding a personal password?","options":["A shared domain administrator password in plain text","A disabled service account","Managed identity with least-privilege permissions","The Guest account"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"هویت‌های مدیریت‌شده نیاز به ذخیره‌سازی اطلاعات حساس (مانند رمز عبور) را از بین می‌برند و می‌توان تنها مجوزهای مورد نیاز ران‌بوک را به آن‌ها اختصاص داد.","en":"Managed identities avoid stored secrets and can be granted only the permissions required by the runbook.","de":"Die richtige Antwort ist „Managed identity with least-privilege permissions“; sie passt zum Bereich Manage Windows Server instances and workloads in a hybrid environment und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"یک ران‌بوک (Runbook) باید منابعی را در Azure تغییر دهد. به‌جای گنجاندن (hard-coding) یک رمز عبور شخصی در آن، از چه چیزی باید استفاده کند؟","optionsFa":["رمز عبور مشترک مدیر دامنه (Domain Administrator) به‌صورت متن ساده (Plain text)","یک حساب کاربری سرویس (Service Account) غیرفعال‌شده","هویت مدیریت‌شده (Managed Identity) با حداقل سطح دسترسی (Least-privilege)","حساب کاربری مهمان (Guest account)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/entra/identity/managed-identities-azure-resources/overview","https://learn.microsoft.com/en-us/azure/automation/overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Automate administration with runbooks and managed identities","objectiveId":"hybrid-automation","topic":"Automation security","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/entra/identity/managed-identities-azure-resources/overview","https://learn.microsoft.com/en-us/azure/automation/overview"],"keyPoints":["A managed identity gives an Azure resource an identity in Microsoft Entra ID without a stored secret.","The identity can be granted only the permissions the runbook needs, which is least privilege for automation.","Because there is no password to store or rotate, the runbook avoids secret sprawl and the exposure that comes with embedded credentials."],"whyOthers":["A shared domain administrator password in plain text is the opposite of the requirement and exposes a high-privilege credential.","A disabled service account cannot authenticate, so the runbook would simply fail.","","The Guest account is disabled by default and is not an automation identity."],"requirements":"Applies to Azure Automation and other Azure resources. A system-assigned identity is tied to the resource's lifecycle, while a user-assigned identity can be shared across resources and granted role assignments explicitly."},
{"id":"az802-q-075","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"What is PowerShell Remoting primarily used for?","options":["Format a virtual disk","Execute PowerShell commands on remote computers","Replicate DNS zones","Encrypt a volume"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"قابلیت PowerShell Remoting که مبتنی بر WinRM است، امکان مدیریت از راه دور را از طریق دستورات، نشست‌ها (Sessions) و اسکریپت‌ها فراهم می‌کند.","en":"WinRM-based PowerShell remoting enables remote administration through commands, sessions, and scripts.","de":"Die richtige Antwort ist „Execute PowerShell commands on remote computers“; sie passt zum Bereich Manage Windows Server instances and workloads in a hybrid environment und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"قابلیت PowerShell Remoting عمدتاً برای چه کاری استفاده می‌شود؟","optionsFa":["فرمت کردن یک دیسک مجازی","اجرای دستورات PowerShell روی کامپیوترهای راه دور","تکثیر (Replicate) زون‌های DNS","رمزنگاری یک Volume (پارتیشن یا درایو)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/powershell/scripting/learn/ps101/08-powershell-remoting?view=powershell-7.6"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage servers remotely with PowerShell remoting","objectiveId":"hybrid-remoting","topic":"PowerShell remoting","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/powershell/scripting/learn/ps101/08-powershell-remoting?view=powershell-7.6"],"keyPoints":["PowerShell remoting runs commands and scripts on remote computers using WS-Management and WinRM.","It supports one-to-one sessions and one-to-many execution through Invoke-Command.","Remoting must be enabled on the target, normally with Enable-PSRemoting, before a connection is accepted."],"whyOthers":["Formatting a virtual disk is done locally with Disk Management or diskpart, not through PowerShell remoting.","","Replicating DNS zones is a DNS Server function and is not what remoting does.","Encrypting a volume is BitLocker's job and is unrelated to remoting."],"commandPath":[{"label":"Enable remoting on the target computer","command":"Enable-PSRemoting -Force"},{"label":"Run a command on a remote computer","command":"Invoke-Command -ComputerName SRV01 -ScriptBlock { Get-Service }"}],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 and to supported PowerShell versions. WinRM needs the service running and the firewall rules for the management protocols enabled on the target."},
{"id":"az802-q-076","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"Which command tests whether WinRM is configured for a remote host?","options":["Test-WSMan","Test-NetConnection -Port 53 only","Get-Volume","Get-ADUser"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"دستور Test-WSMan اتصال WS-Management به مقصد را بررسی و تأیید می‌کند.","en":"Test-WSMan verifies WS-Management connectivity to the target.","de":"Die richtige Antwort ist „Test-WSMan“; sie passt zum Bereich Manage Windows Server instances and workloads in a hybrid environment und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام دستور بررسی می‌کند که آیا WinRM برای یک میزبان (Host) راه دور پیکربندی شده است یا خیر؟","optionsFa":["Test-WSMan","Test-NetConnection -Port 53 only","Get-Volume","Get-ADUser"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.core/about/about_remote_troubleshooting?view=powershell-7.6","https://learn.microsoft.com/en-us/powershell/scripting/security/remoting/winrm-security?view=powershell-7.6"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage servers remotely with PowerShell remoting","objectiveId":"hybrid-remoting","topic":"PowerShell remoting","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.core/about/about_remote_troubleshooting?view=powershell-7.6","https://learn.microsoft.com/en-us/powershell/scripting/security/remoting/winrm-security?view=powershell-7.6"],"keyPoints":["Test-WSMan verifies WS-Management connectivity to a target, which is the transport PowerShell remoting uses.","A successful response confirms the WS-Management service is reachable and responding.","When Test-WSMan fails, the problem is normally the WinRM service, the firewall rule, or name resolution rather than the PowerShell command itself."],"whyOthers":["","Test-NetConnection against port 53 tests DNS connectivity, not the remoting transport.","Get-Volume reports local disk volumes and does not test remoting.","Get-ADUser queries Active Directory and does not test WinRM configuration."],"commandPath":[{"label":"Test WS-Management connectivity to a target","command":"Test-WSMan -ComputerName SRV01"},{"label":"Check the WinRM service state locally","command":"Get-Service WinRM | Select-Object Status, StartType"}],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Test-WSMan confirms the transport only; a subsequent failure to create a session can still be an authentication problem."},
{"id":"az802-q-077","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"A remoting session must cross from Server A to Server B while accessing a resource from Server C. What issue is likely?","options":["DHCP scope exhaustion only","NTFS compression","Hyper-V checkpoint merge","Kerberos double-hop delegation"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"مرحله دوم انتقال شبکه (Network hop) نیازمند تفویض اختیار مناسب یا روش‌های جایگزینی مانند CredSSP، JEA یا انتقال بااحتیاط اعتبارنامه‌ها (Credential passing) است.","en":"The second network hop requires appropriate delegation or an alternative such as CredSSP, JEA, or credential passing with care.","de":"Die richtige Antwort ist „Kerberos double-hop delegation“; sie passt zum Bereich Manage Windows Server instances and workloads in a hybrid environment und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"یک نشست (Session) ارتباط از راه دور باید از سرور A به سرور B منتقل شود و هم‌زمان به منبعی در سرور C دسترسی پیدا کند. چه مشکلی محتمل است؟","optionsFa":["اتمام محدوده (Scope) آدرس‌های DHCP","فشرده‌سازی NTFS","ادغام (Merge) نقاط بازرسی (Checkpoint) در Hyper-V","تفویض اختیار (Delegation) دو مرحله‌ای (Double-hop) در Kerberos"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/powershell/scripting/security/remoting/ps-remoting-second-hop?view=powershell-7.6","https://learn.microsoft.com/en-us/powershell/scripting/security/remoting/winrm-security?view=powershell-7.6"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage servers remotely with PowerShell remoting","objectiveId":"hybrid-remoting","topic":"PowerShell remoting","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/powershell/scripting/security/remoting/ps-remoting-second-hop?view=powershell-7.6","https://learn.microsoft.com/en-us/powershell/scripting/security/remoting/winrm-security?view=powershell-7.6"],"keyPoints":["The remote machine does not hold the user's credentials, so a second network hop fails by default with an access-denied error.","This is the Kerberos double-hop problem: the credential is not delegated to the intermediate server.","Supported options include constrained delegation, resource-based constrained delegation, CredSSP, and running as a virtual account or System on the intermediate server."],"whyOthers":["DHCP scope exhaustion is an addressing problem and would not produce the pattern described.","NTFS compression affects file storage and has no bearing on authentication between servers.","A Hyper-V checkpoint merge is a virtualisation operation unrelated to remoting.",""],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. CredSSP delegates credentials and raises risk, so constrained delegation or resource-based constrained delegation is generally preferred where the service supports it."},
{"id":"az802-q-078","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"What is the purpose of Just Enough Administration (JEA)?","options":["Disable PowerShell logging","Replace the Windows Firewall","Constrain administrators to approved commands and parameters","Grant every administrator Domain Admins membership"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"قابلیت JEA از «قابلیت‌های نقش» (role capabilities) و «نقاط پایانی محدودشده» (constrained endpoints) برای کاهش سطح دسترسی (privilege) و محدود کردن دامنه تأثیر عملیات مدیریتی (blast radius) استفاده می‌کند.","en":"JEA uses role capabilities and constrained endpoints to reduce privilege and administrative blast radius.","de":"Die richtige Antwort ist „Constrain administrators to approved commands and parameters“; sie passt zum Bereich Manage Windows Server instances and workloads in a hybrid environment und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"هدف از قابلیت Just Enough Administration (JEA) چیست؟","optionsFa":["غیرفعال کردن ثبت وقایع (logging) در PowerShell","جایگزینی فایروال ویندوز","محدود کردن مدیران به دستورات و پارامترهای تأییدشده","اعطای عضویت در گروه Domain Admins به تمام مدیران"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/powershell/scripting/security/remoting/jea/role-capabilities","https://learn.microsoft.com/en-us/powershell/scripting/security/remoting/jea/overview?view=powershell-7.6"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Constrain administrative access with Just Enough Administration","objectiveId":"hybrid-jea","topic":"Just Enough Administration","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/powershell/scripting/security/remoting/jea/role-capabilities","https://learn.microsoft.com/en-us/powershell/scripting/security/remoting/jea/overview?view=powershell-7.6"],"keyPoints":["JEA constrains administrators to an approved set of commands and parameters through a scoped endpoint.","It uses role capabilities to define exactly what a delegated role may do, and NoLanguage mode limits sessions to command invocation.","It reduces the blast radius of administrative mistakes and misuse by removing general-purpose administrative access."],"whyOthers":["JEA does not disable PowerShell logging; it works with logging and transcription to record what was done.","JEA does not replace the Windows Firewall; firewall rules are managed separately.","","JEA is the opposite of granting every administrator Domain Admins membership, which would remove the constraint."],"commandPath":[{"label":"Create a JEA role capability","command":"New-PSRoleCapabilityFile -Path .\\DNSOps.psrc -VisibleCmdlets 'Get-DnsServer*','Restart-DnsServer'"},{"label":"Register the constrained endpoint","command":"Register-PSSessionConfiguration -Name DNSOps -Path .\\DNSOps.pssc -RunAsCredential (Get-Credential)"}],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 and to PowerShell 5.1 and later. JEA endpoints can run under a virtual account so the delegated work uses a scoped identity rather than the operator's own rights."},
{"id":"az802-q-079","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"Which protocol is commonly used for secure remote shell access to Windows Server?","options":["TFTP","SSH","FTP","Telnet"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"ویندوز سرور از OpenSSH برای سناریوهای شل از راه دورِ رمزنگاری‌شده و انتقال فایل پشتیبانی می‌کند.","en":"Windows Server supports OpenSSH for encrypted remote shell and file-transfer scenarios.","de":"Die richtige Antwort ist „SSH“; sie passt zum Bereich Manage Windows Server instances and workloads in a hybrid environment und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام پروتکل معمولاً برای دسترسی امن و از راه دور به شل (shell) در ویندوز سرور استفاده می‌شود؟","optionsFa":["TFTP","SSH","FTP","Telnet"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/openssh/openssh-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage remote access with SSH and Remote Desktop Services","objectiveId":"hybrid-remote-access","topic":"OpenSSH","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/openssh/openssh-overview"],"keyPoints":["Windows Server supports OpenSSH for encrypted remote shell and file-transfer scenarios.","The OpenSSH Server feature provides an SSH server, and the OpenSSH Client feature provides the ssh client.","It allows administration and scripting workflows that are common in mixed Windows and Linux environments."],"whyOthers":["TFTP is a trivial, unauthenticated file-transfer protocol and is not used for interactive remote shells.","","FTP is an unencrypted file-transfer protocol and does not provide an interactive encrypted shell.","Telnet sends data in clear text and offers no encryption or modern authentication."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. OpenSSH Server is installed as a Windows optional feature and can be configured through the sshd_config file."},
{"id":"az802-q-080","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"What is the main security advantage of SSH keys over passwords?","options":["They can provide strong key-based authentication without transmitting a reusable password","They disable encryption","They bypass authorization","They create DHCP reservations"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"در روش احراز هویت با کلید عمومی (public-key authentication)، از یک کلید خصوصی که نزد کلاینت است و یک کلید عمومی که در سرور مجاز شناخته شده، استفاده می‌شود.","en":"Public-key authentication uses a private key held by the client and a public key authorized on the server.","de":"Die richtige Antwort ist „They can provide strong key-based authentication without transmitting a reusable password“; sie passt zum Bereich Manage Windows Server instances and workloads in a hybrid environment und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"مزیت امنیتی اصلی کلیدهای SSH نسبت به رمزهای عبور چیست؟","optionsFa":["آن‌ها امکان احراز هویت قوی مبتنی بر کلید را بدون انتقال رمز عبوری که قابل استفاده مجدد باشد، فراهم می‌کنند.","آن‌ها رمزنگاری را غیرفعال می‌کنند.","آن‌ها مرحله مجوزدهی (authorization) را دور می‌زنند.","آن‌ها رزروهای DHCP ایجاد می‌کنند."],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/openssh/openssh_keymanagement","https://learn.microsoft.com/en-us/windows-server/administration/openssh/openssh_install_firstuse"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage remote access with SSH and Remote Desktop Services","objectiveId":"hybrid-remote-access","topic":"OpenSSH","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/openssh/openssh_keymanagement","https://learn.microsoft.com/en-us/windows-server/administration/openssh/openssh_install_firstuse"],"keyPoints":["Key-based authentication uses a private key held by the client and a public key authorised on the server.","No reusable password is transmitted during authentication, which removes password guessing and credential reuse as an attack path.","The private key can also be protected by a passphrase and is never sent to the server."],"whyOthers":["","Key-based authentication does not disable encryption; the session remains encrypted.","Keys do not bypass authorisation; the server still decides what the authenticated user may do.","SSH keys do not create DHCP reservations, which are an addressing feature."],"commandPath":[{"label":"Generate a key pair","command":"ssh-keygen -t ed25519"},{"label":"Install the public key for an administrator account","command":"Add-WindowsCapability -Online -Name OpenSSH.Server~~~~0.0.1.0"}],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. On Windows, an administrator's key is placed in the administrators_authorized_keys file with restricted permissions, while a standard user's key goes in the user's .ssh folder."},
{"id":"az802-q-081","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"Which Windows Server feature provides graphical remote desktop sessions?","options":["DFS Replication","Storage Replica","DNSSEC","Remote Desktop Services"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"سرویس Remote Desktop Services قابلیت‌های دسترسی از راه دور مبتنی بر نشست (session-based) و تحویل برنامه (application delivery) را فراهم می‌کند.","en":"Remote Desktop Services provides session-based remote access and application delivery capabilities.","de":"Die richtige Antwort ist „Remote Desktop Services“; sie passt zum Bereich Manage Windows Server instances and workloads in a hybrid environment und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام قابلیت ویندوز سرور، نشست‌های (sessions) گرافیکی دسکتاپ از راه دور را فراهم می‌کند؟","optionsFa":["DFS Replication","Storage Replica","DNSSEC","Remote Desktop Services"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/remote/remote-desktop-services/overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage remote access with SSH and Remote Desktop Services","objectiveId":"hybrid-remote-access","topic":"Remote Desktop Services","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/remote/remote-desktop-services/overview"],"keyPoints":["Remote Desktop Services provides session-based remote desktop access to Windows Server.","It also supports publishing applications so users can run them remotely without a full desktop.","It is the built-in Windows Server platform for delivering managed desktops and applications."],"whyOthers":["DFS Replication replicates file data between servers and does not provide remote desktop sessions.","Storage Replica replicates volumes between servers and has no graphical session capability.","DNSSEC extends DNS with cryptographic validation and is unrelated to remote sessions.",""],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Remote Desktop Services requires an RDS deployment with session hosts and, depending on the design, other roles such as connection broker and gateway."},
{"id":"az802-q-082","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"What should be used to protect an RDS deployment exposed to the internet?","options":["Disable auditing","Use the Guest account","A secure gateway such as RD Gateway with strong authentication and restricted access","Directly expose every RDP port to the internet"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"استفاده از دروازه (Gateway) باعث متمرکز شدن سیاست‌ها می‌شود و از قرار گرفتن مستقیم هر Session Host در معرض خطر جلوگیری می‌کند.","en":"A gateway centralizes policy and avoids exposing every session host directly.","de":"Die richtige Antwort ist „A secure gateway such as RD Gateway with strong authentication and restricted access“; sie passt zum Bereich Manage Windows Server instances and workloads in a hybrid environment und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"برای محافظت از یک پیاده‌سازی RDS که در معرض اینترنت قرار دارد، از چه چیزی باید استفاده کرد؟","optionsFa":["غیرفعال کردن قابلیت Auditing (حسابرسی/ثبت وقایع)","استفاده از حساب کاربری Guest","یک دروازه (Gateway) امن مانند RD Gateway با احراز هویت قوی و دسترسی محدود","قرار دادن مستقیم تمام پورت‌های RDP در معرض اینترنت"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/remote/remote-desktop-services/rds-roles","https://learn.microsoft.com/en-us/windows-server/remote/remote-desktop-services/remote-desktop-gateway-role"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage remote access with SSH and Remote Desktop Services","objectiveId":"hybrid-remote-access","topic":"Remote Desktop Services","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/remote/remote-desktop-services/rds-roles","https://learn.microsoft.com/en-us/windows-server/remote/remote-desktop-services/remote-desktop-gateway-role"],"keyPoints":["An RD Gateway centralises remote access policy and authenticates users before they reach a session host.","It lets clients reach internal session hosts without exposing every RDP port directly to the internet.","It should be combined with strong authentication and restricted authorisation policy."],"whyOthers":["Disabling auditing removes the evidence administrators need and weakens security rather than protecting the deployment.","Using the Guest account gives unauthenticated, low-trust access and is not a protection measure.","","Exposing every RDP port directly to the internet is exactly the exposure a gateway is meant to avoid."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. RD Gateway uses HTTPS (normally port 443) and can use Remote Desktop connection authorisation policies to control who may connect where."},
{"id":"az802-q-083","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"Which Azure feature provides browser-based RDP/SSH access to VMs without a public IP on each VM?","options":["Azure Migrate appliance","Azure Bastion","Azure File Sync","Azure DNS Private Resolver"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"سرویس Bastion دسترسی مدیریت‌شده از طریق مرورگر را در بستر شبکه مجازی و از طریق پورتال Azure فراهم می‌کند.","en":"Bastion provides managed browser access through the Azure portal over the virtual network.","de":"Die richtige Antwort ist „Azure Bastion“; sie passt zum Bereich Manage Windows Server instances and workloads in a hybrid environment und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام قابلیت Azure امکان دسترسی RDP/SSH مبتنی بر مرورگر را به ماشین‌های مجازی (VMs) فراهم می‌کند، بدون اینکه نیازی به اختصاص IP عمومی به هر ماشین مجازی باشد؟","optionsFa":["Azure Migrate appliance","Azure Bastion","Azure File Sync","Azure DNS Private Resolver"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/bastion/bastion-overview","https://learn.microsoft.com/en-us/azure/bastion/bastion-connect-vm-rdp-windows"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage remote access with SSH and Remote Desktop Services","objectiveId":"hybrid-remote-access","topic":"Azure Bastion","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/bastion/bastion-overview","https://learn.microsoft.com/en-us/azure/bastion/bastion-connect-vm-rdp-windows"],"keyPoints":["Azure Bastion is a managed service that provides RDP and SSH access to virtual machines through the Azure portal over TLS.","Virtual machines do not need public IP addresses or exposed RDP/SSH ports, which removes that exposure.","It removes the need to run and secure a separate jump host."],"whyOthers":["The Azure Migrate appliance performs discovery and assessment for migration, not interactive remote access.","","Azure File Sync caches file shares locally and has no remote-desktop capability.","Azure DNS Private Resolver resolves names in private DNS zones and does not provide RDP or SSH access."],"requirements":"Applies to the Azure Bastion service. It is deployed into a virtual network, and access can be granted with role-based access control rather than by distributing local credentials."},
{"id":"az802-q-084","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"An organization needs inventory and policy on servers outside Azure. Which pairing is most appropriate?","options":["Azure Arc-enabled servers and Azure Policy","DHCP and print services","Hyper-V Replica and SMB signing","DNSSEC and FSRM"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"سرویس Arc سرور را به محدوده مدیریتی Azure وارد می‌کند و Policy الزامات پیکربندی را ارزیابی یا اعمال می‌نماید.","en":"Arc brings the server into Azure management scope and Policy evaluates or enforces configuration requirements.","de":"Die richtige Antwort ist „Azure Arc-enabled servers and Azure Policy“; sie passt zum Bereich Manage Windows Server instances and workloads in a hybrid environment und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"سازمانی نیاز به مدیریت موجودی (inventory) و اعمال سیاست‌ها (policy) برای سرورهای خارج از محیط Azure دارد. کدام ترکیب مناسب‌ترین گزینه است؟","optionsFa":["سرورهای مجهز به Azure Arc و Azure Policy","سرویس‌های DHCP و چاپ (print services)","قابلیت Hyper-V Replica و امضای SMB (SMB signing)","پروتکل DNSSEC و سرویس FSRM"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-arc/servers/overview","https://learn.microsoft.com/en-us/azure/governance/policy/overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Centrally manage hybrid resources with Azure Policy","objectiveId":"hybrid-policy","topic":"Azure Arc and Azure Policy","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-arc/servers/overview","https://learn.microsoft.com/en-us/azure/governance/policy/overview"],"keyPoints":["Arc-enabled servers bring non-Azure machines into Azure management scope, which is what makes them subject to Azure Policy.","Azure Policy evaluates resources against definitions and can audit or enforce configuration requirements.","Together they give inventory and policy coverage across on-premises and cloud servers."],"whyOthers":["","DHCP and print services are local network services and provide neither inventory nor policy for cloud management.","Hyper-V Replica and SMB signing are replication and file-transfer settings, not a governance pairing.","DNSSEC and FSRM are DNS validation and file-screening features and are unrelated to policy."],"requirements":"Applies to Azure Arc-enabled servers. A policy assignment can audit configuration or, through guest configuration, evaluate settings inside the machine, and remediation can be applied where the effect supports it."},
{"id":"az802-q-085","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"What does an Azure Policy initiative contain?","options":["A virtual hard disk","A DHCP failover relationship","A DNS zone transfer key","A collection of related policy definitions"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"یک Initiative سیاست‌ها را گروه‌بندی می‌کند تا بتوان یک هدف کلی‌تر برای انطباق (compliance) را تعیین و به‌صورت یکپارچه پیگیری کرد.","en":"An initiative groups policies so a broader compliance objective can be assigned and tracked together.","de":"Die richtige Antwort ist „A collection of related policy definitions“; sie passt zum Bereich Manage Windows Server instances and workloads in a hybrid environment und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"یک «ابتکار عمل» (Initiative) در Azure Policy شامل چه مواردی است؟","optionsFa":["یک دیسک سخت مجازی (VHD)","یک رابطه Failover برای DHCP","یک کلید انتقال ناحیه DNS (DNS zone transfer key)","مجموعه‌ای از تعاریف سیاست‌های مرتبط"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/governance/policy/concepts/initiative-definition-structure","https://learn.microsoft.com/en-us/azure/governance/policy/overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Centrally manage hybrid resources with Azure Policy","objectiveId":"hybrid-policy","topic":"Azure Policy","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/governance/policy/concepts/initiative-definition-structure","https://learn.microsoft.com/en-us/azure/governance/policy/overview"],"keyPoints":["An initiative, also called a policy set, is a collection of related policy definitions grouped for assignment and compliance tracking.","Assigning one initiative reports compliance across all of its member policies, which is how a broad objective such as a regulatory baseline is tracked.","Parameters can be passed to an initiative so one definition can be reused across assignments."],"whyOthers":["A virtual hard disk is a storage artefact and is not an initiative.","A DHCP failover relationship provides address-service redundancy and is unrelated.","A DNS zone transfer key secures zone transfers and is not part of an initiative.",""],"requirements":"Applies to Azure Policy. An initiative can be assigned at management-group, subscription, or resource-group scope, and compliance is evaluated per policy within the initiative."},
{"id":"az802-q-086","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"Which Azure service is designed to collect and analyze logs and metrics from hybrid machines?","options":["Azure Load Testing only","Azure Files","Azure Monitor","Azure DNS"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"سرویس Azure Monitor داده‌های تلمتری (telemetry) را جمع‌آوری کرده و از معیارها، لاگ‌ها، هشدارها (alerts)، ورک‌بوک‌ها (workbooks) و قابلیت‌های یکپارچه‌سازی پشتیبانی می‌کند.","en":"Azure Monitor collects telemetry and supports metrics, logs, alerts, workbooks, and integrations.","de":"Die richtige Antwort ist „Azure Monitor“; sie passt zum Bereich Manage Windows Server instances and workloads in a hybrid environment und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام سرویس Azure برای جمع‌آوری و تحلیل لاگ‌ها (logs) و معیارها (metrics) از ماشین‌های هیبریدی طراحی شده است؟","optionsFa":["فقط Azure Load Testing","Azure Files","Azure Monitor","Azure DNS"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-monitor/overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Monitor hybrid servers with Azure Monitor","objectiveId":"hybrid-monitoring","topic":"Azure Monitor","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-monitor/overview"],"keyPoints":["Azure Monitor collects telemetry from Azure resources and, with Arc, from hybrid machines.","It provides metrics, logs, alerts, dashboards, and workbooks from one platform.","Hybrid servers send data through the Azure Monitor Agent rather than a legacy log-analytics agent."],"whyOthers":["Azure Load Testing is a load-testing service and does not collect machine telemetry.","Azure Files provides file shares and does not analyse logs or metrics.","","Azure DNS hosts DNS zones and does not monitor servers."],"requirements":"Applies to Azure Monitor. Hybrid machines must first be connected through Azure Arc, and a data collection rule defines what data is gathered and where it is sent."},
{"id":"az802-q-087","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"A hybrid server must send Windows event logs to a central Log Analytics workspace. Which agent direction is appropriate?","options":["Create a Hyper-V checkpoint","Configure Azure Monitor Agent and a data collection rule","Install a DHCP relay","Enable SMB Direct"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"سرویس Azure Monitor Agent از قوانین جمع‌آوری داده استفاده می‌کند تا مشخص کند چه داده‌هایی جمع‌آوری شده و به کجا ارسال شوند.","en":"Azure Monitor Agent uses data collection rules to define what data is collected and where it is sent.","de":"Die richtige Antwort ist „Configure Azure Monitor Agent and a data collection rule“; sie passt zum Bereich Manage Windows Server instances and workloads in a hybrid environment und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"یک سرور هیبریدی باید لاگ‌های رویداد ویندوز (Windows event logs) را به یک فضای کاری (workspace) مرکزی Log Analytics ارسال کند. کدام اقدام مناسب است؟","optionsFa":["ایجاد یک Checkpoint در Hyper-V","پیکربندی Azure Monitor Agent و یک قانون جمع‌آوری داده (data collection rule)","نصب یک DHCP relay","فعال‌سازی SMB Direct"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-monitor/vm/data-collection","https://learn.microsoft.com/en-us/azure/azure-monitor/agents/azure-monitor-agent-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Monitor hybrid servers with Azure Monitor","objectiveId":"hybrid-monitoring","topic":"Azure Monitor Agent","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-monitor/vm/data-collection","https://learn.microsoft.com/en-us/azure/azure-monitor/agents/azure-monitor-agent-overview"],"keyPoints":["The Azure Monitor Agent collects data from virtual machines and Arc-enabled servers according to data collection rules.","A data collection rule specifies the data sources, any transformations, and the destination workspace.","Windows event logs are a supported data source, so a rule can be scoped to the channels the organization needs."],"whyOthers":["Creating a Hyper-V checkpoint affects one virtual machine's state and does not send logs anywhere.","","Installing a DHCP relay is a networking change and does not collect event logs.","Enabling SMB Direct improves SMB performance and is unrelated to log collection."],"requirements":"Applies to Azure Monitor Agent on supported operating systems. The legacy Microsoft Monitoring Agent is being retired in favour of Azure Monitor Agent and data collection rules."},
{"id":"az802-q-088","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"What is a data collection rule (DCR) used for?","options":["Define telemetry sources, destinations, and collection settings","Define NTFS ACL inheritance","Define AD trust direction","Define a VM boot disk layout"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"قوانین DCR پیکربندی‌هایی با قابلیت استفاده مجدد و دارای محدوده مشخص (scoped) برای دریافت داده‌ها در Azure Monitor فراهم می‌کنند.","en":"DCRs provide a reusable, scoped configuration for Azure Monitor data ingestion.","de":"Die richtige Antwort ist „Define telemetry sources, destinations, and collection settings“; sie passt zum Bereich Manage Windows Server instances and workloads in a hybrid environment und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کاربرد قانون جمع‌آوری داده (DCR) چیست؟","optionsFa":["تعریف منابع، مقاصد و تنظیمات جمع‌آوری تلمتری (داده‌های دورسنجی)","تعریف وراثت ACL در NTFS","تعریف جهت اعتماد (Trust direction) در AD","تعریف چیدمان دیسک بوت ماشین مجازی (VM)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-monitor/data-collection/data-collection-rule-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Monitor hybrid servers with Azure Monitor","objectiveId":"hybrid-monitoring","topic":"Data collection rules","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-monitor/data-collection/data-collection-rule-overview"],"keyPoints":["A data collection rule defines the data sources to collect, how the data is processed, and the destination where it is sent.","Rules are reusable and can be scoped so that many machines share one consistent collection policy.","A single rule can include several data sources, such as performance counters and Windows event logs."],"whyOthers":["","NTFS ACL inheritance is a file-permission setting and is unrelated to telemetry.","AD trust direction is a directory setting and is not defined by a data collection rule.","A virtual machine's boot disk layout is a storage configuration, not a collection definition."],"requirements":"Applies to Azure Monitor. A data collection rule is associated with machines through a data collection rule association, and edits to the rule change collection for every associated machine."},
{"id":"az802-q-089","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"Which administrative principle should apply to Azure Arc extensions?","options":["Install every available extension","Use shared administrator passwords","Disable agent health checks","Deploy only needed extensions with least-privilege access"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"افزونه‌ها می‌توانند کد اجرا کنند یا پیکربندی را تغییر دهند، بنابراین محدود کردن آن‌ها ریسک را کاهش می‌دهد.","en":"Extensions can execute code or change configuration, so limiting them reduces risk.","de":"Die richtige Antwort ist „Deploy only needed extensions with least-privilege access“; sie passt zum Bereich Manage Windows Server instances and workloads in a hybrid environment und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام اصل مدیریتی باید برای افزونه‌های Azure Arc اعمال شود؟","optionsFa":["نصب تمام افزونه‌های موجود","استفاده از رمزهای عبور مشترک برای مدیران","غیرفعال کردن بررسی‌های سلامت عامل (Agent)","استقرار تنها افزونه‌های مورد نیاز با سطح دسترسی «حداقل امتیاز» (least-privilege)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-arc/servers/agent-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Connect servers to Azure with Azure Arc","objectiveId":"hybrid-arc","topic":"Azure Arc extensions","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-arc/servers/agent-overview"],"keyPoints":["Extensions can execute code or change configuration on the machine, so each one expands the trusted computing base.","Deploying only the extensions that are needed keeps the attack surface and the maintenance burden smaller.","Granting least-privilege access to manage extensions limits who can change the machine's configuration."],"whyOthers":["Installing every available extension maximises the code running on the server and contradicts least privilege.","Shared administrator passwords are the opposite of a least-privilege practice.","Disabling agent health checks removes the signal that would detect a problem and is not a security improvement.",""],"requirements":"Applies to Azure Arc-enabled servers. Extension management should be restricted with role-based access control so only authorised operators can deploy or remove extensions."},
{"id":"az802-q-090","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"What is the purpose of Windows Server remote management firewall rules?","options":["Disable authentication","Replace DNS","Permit only the required management traffic to the intended profiles and hosts","Allow all inbound traffic"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"پروتکل‌های مدیریتی باید به صراحت مجاز شوند و در صورت امکان، بر اساس موقعیت شبکه و منبع، محدود گردند.","en":"Management protocols should be explicitly allowed and restricted by network location and source where possible.","de":"Die richtige Antwort ist „Permit only the required management traffic to the intended profiles and hosts“; sie passt zum Bereich Manage Windows Server instances and workloads in a hybrid environment und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"هدف از قوانین فایروال مربوط به مدیریت از راه دور ویندوز سرور چیست؟","optionsFa":["غیرفعال کردن احراز هویت","جایگزینی DNS","مجاز کردن تنها ترافیک مدیریتی مورد نیاز برای پروفایل‌ها و میزبان‌های (hosts) مربوطه","مجاز کردن تمام ترافیک ورودی"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/powershell/scripting/security/remoting/winrm-security?view=powershell-7.6","https://learn.microsoft.com/en-us/powershell/scripting/learn/ps101/08-powershell-remoting?view=powershell-7.6"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage servers remotely with PowerShell remoting","objectiveId":"hybrid-remoting","topic":"Remote management firewall","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/powershell/scripting/security/remoting/winrm-security?view=powershell-7.6","https://learn.microsoft.com/en-us/powershell/scripting/learn/ps101/08-powershell-remoting?view=powershell-7.6"],"keyPoints":["Remote management firewall rules should allow only the management protocols that are actually used.","Rules are scoped to the required network profiles and, where possible, to specific source hosts or subnets.","Enabling a rule for a management protocol should be deliberate, not part of a broad allow-all change."],"whyOthers":["Firewall rules do not disable authentication; they filter traffic.","Firewall rules do not replace DNS; name resolution is a separate service.","","Allowing all inbound traffic removes the protection the firewall provides and is not a management rule."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. The built-in Remote Management firewall group contains the rules for WinRM, WMI, and the Windows Remote Shell; scope them rather than enabling every rule."},
{"id":"az802-q-091","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"A PowerShell remoting connection works by IP address but not by hostname. What should be checked first?","options":["VM checkpoints","DNS resolution and SPN/name-based authentication requirements","Disk parity","File-screening templates"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"ارتباط از راه دور مبتنی بر نام میزبان به وضوح صحیح نام و هویت احراز هویت وابسته است؛ اتصالات مبتنی بر IP ممکن است رفتار متفاوتی داشته باشند.","en":"Hostname-based remoting depends on correct name resolution and authentication identity; IP connections can behave differently.","de":"Die richtige Antwort ist „DNS resolution and SPN/name-based authentication requirements“; sie passt zum Bereich Manage Windows Server instances and workloads in a hybrid environment und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"اتصال از راه دور PowerShell با استفاده از آدرس IP کار می‌کند اما با نام میزبان (hostname) خیر. ابتدا چه چیزی باید بررسی شود؟","optionsFa":["نقاط بازرسی (Checkpoint) ماشین مجازی","وضوح نام DNS و الزامات احراز هویت مبتنی بر SPN یا نام","توازن (Parity) دیسک","الگوهای غربالگری فایل (File-screening templates)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.core/about/about_remote_troubleshooting?view=powershell-7.6","https://learn.microsoft.com/en-us/powershell/scripting/security/remoting/winrm-security?view=powershell-7.6"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage servers remotely with PowerShell remoting","objectiveId":"hybrid-remoting","topic":"PowerShell remoting","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.core/about/about_remote_troubleshooting?view=powershell-7.6","https://learn.microsoft.com/en-us/powershell/scripting/security/remoting/winrm-security?view=powershell-7.6"],"keyPoints":["Remoting by hostname uses Kerberos, which requires correct name resolution and a service principal name.","An IP address cannot be authenticated by Kerberos in the same way, so it can succeed with NTLM or fail differently.","The first checks are DNS resolution of the name and the authentication requirement the target enforces."],"whyOthers":["VM checkpoints are virtual-machine state objects and do not affect name-based authentication.","","Disk parity is a storage property and is unrelated.","File-screening templates are an FSRM feature and have no role in remoting."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. If Kerberos cannot be used, a TrustedHosts entry or HTTPS listener may be required, and both should be configured deliberately because they weaken the default trust model."},
{"id":"az802-q-092","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"Which option best describes a hybrid Windows Server workload?","options":["It uses on-premises and cloud services as part of one operational design","It must run only on a physical server","It cannot use identity services","It excludes monitoring"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"مدیریت ترکیبی، منابع محلی و ابری را از طریق یکپارچه‌سازی هویت، مدیریت، شبکه، ذخیره‌سازی یا بار کاری به هم پیوند می‌دهد.","en":"Hybrid administration joins local and cloud resources through identity, management, networking, storage, or workload integration.","de":"Die richtige Antwort ist „It uses on-premises and cloud services as part of one operational design“; sie passt zum Bereich Manage Windows Server instances and workloads in a hybrid environment und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام گزینه بار کاری (workload) ترکیبی (هیبریدی) ویندوز سرور را به بهترین شکل توصیف می‌کند؟","optionsFa":["از سرویس‌های درون‌سازمانی (on-premises) و ابری به عنوان بخشی از یک طرح عملیاتی واحد استفاده می‌کند","باید فقط روی یک سرور فیزیکی اجرا شود","نمی‌تواند از سرویس‌های هویت استفاده کند","شامل نظارت (مانیتورینگ) نمی‌شود"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-arc/servers/overview","https://learn.microsoft.com/en-us/windows-server/manage/windows-admin-center/understand/what-is"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage hybrid workloads and connectivity","objectiveId":"hybrid-workloads","topic":"Hybrid operations","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-arc/servers/overview","https://learn.microsoft.com/en-us/windows-server/manage/windows-admin-center/understand/what-is"],"keyPoints":["A hybrid workload uses on-premises and cloud services as part of one operational design.","Identity, management, networking, storage, and monitoring can each be the joined element.","The workload is not simply moved to the cloud; the design deliberately spans both environments."],"whyOthers":["","A hybrid workload is not restricted to physical servers; it can run on virtual machines in either environment.","Hybrid workloads commonly use identity services such as Active Directory or Microsoft Entra ID.","Monitoring is usually a core part of a hybrid design rather than something excluded from it."],"requirements":"Applies to hybrid designs on Windows Server 2025, 2022, 2019, and 2016. Hybrid scenarios depend on reliable network connectivity and consistent identity between the on-premises and cloud sides."},
{"id":"az802-q-093","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"What does Azure Update Manager’s periodic assessment provide?","options":["A new AD forest","A file-share namespace","A virtual switch","An inventory of update compliance and missing updates"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"ارزیابی، وضعیت به‌روزرسانی را مشخص می‌کند تا مدیران بتوانند برای اقدامات اصلاحی برنامه‌ریزی یا زمان‌بندی کنند.","en":"Assessment identifies update state so administrators can plan or schedule remediation.","de":"Die richtige Antwort ist „An inventory of update compliance and missing updates“; sie passt zum Bereich Manage Windows Server instances and workloads in a hybrid environment und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"ارزیابی دوره‌ای Azure Update Manager چه چیزی را فراهم می‌کند؟","optionsFa":["یک فارست (Forest) جدید در Active Directory","یک فضای نام (namespace) برای اشتراک‌گذاری فایل","یک سوئیچ مجازی","فهرستی از وضعیت انطباق با به‌روزرسانی‌ها و به‌روزرسانی‌های مفقود (نصب‌نشده)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/update-manager/overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage updates for hybrid servers","objectiveId":"hybrid-updates","topic":"Azure Update Manager","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/update-manager/overview"],"keyPoints":["Periodic assessment produces a current inventory of update compliance and the updates a machine is missing.","Assessment is separate from deployment, so administrators can plan remediation based on accurate state.","Compliance data can be reviewed per machine or across a set of machines to prioritise work."],"whyOthers":["A new AD forest is created by domain deployment and is unrelated to update assessment.","A file-share namespace is a DFS construct, not an update report.","A virtual switch is a Hyper-V networking component and is unrelated.",""],"requirements":"Applies to Azure Update Manager for Azure and Arc-enabled machines. Assessment requires the machine to be connected and the Update Manager extensions or prerequisites to be in place."},
{"id":"az802-q-094","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"Which practice reduces disruption when applying updates to production servers?","options":["Disable backups before updating","Ignore application dependencies","Use maintenance windows, phased deployment, and health validation","Reboot all servers simultaneously"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"عرضه (Rollout) کنترل‌شده و اعتبارسنجی، احتمال تأثیرگذاری یک تغییر بر کل سرویس را کاهش می‌دهند.","en":"Controlled rollout and validation reduce the chance that one change affects the entire service.","de":"Die richtige Antwort ist „Use maintenance windows, phased deployment, and health validation“; sie passt zum Bereich Manage Windows Server instances and workloads in a hybrid environment und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام روش هنگام اعمال به‌روزرسانی‌ها روی سرورهای عملیاتی (Production)، میزان اختلال را کاهش می‌دهد؟","optionsFa":["غیرفعال کردن پشتیبان‌گیری‌ها پیش از به‌روزرسانی","نادیده گرفتن وابستگی‌های برنامه (Application dependencies)","استفاده از بازه‌های زمانی نگهداری (Maintenance windows)، استقرار مرحله‌ای و اعتبارسنجی سلامت","راه‌اندازی مجدد (Reboot) هم‌زمان تمام سرورها"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/update-manager/scheduled-patching","https://learn.microsoft.com/en-us/azure/update-manager/overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage updates for hybrid servers","objectiveId":"hybrid-updates","topic":"Update rollout","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/update-manager/scheduled-patching","https://learn.microsoft.com/en-us/azure/update-manager/overview"],"keyPoints":["Maintenance windows confine the work to an agreed time so it does not collide with peak usage.","Phased deployment updates a subset first so a problem is caught before it reaches every server.","Health validation after each phase confirms the service is working before the rollout continues."],"whyOthers":["Disabling backups before updating removes the safety net that makes a failed update recoverable.","Ignoring application dependencies risks updating a tier out of order and breaking the service.","","Rebooting all servers at once removes the ability to detect a problem early and can take the whole service down."],"requirements":"Applies to update management on Windows Server 2025, 2022, 2019, and 2016. A maintenance configuration in Azure Update Manager defines the schedule and scope used for phased patching."},
{"id":"az802-q-095","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"A server is Arc-connected but appears as offline in Azure. What local check is most useful first?","options":["Disable the Windows Firewall permanently","Check the Connected Machine agent service and its recent logs","Delete the AD forest","Repartition the system disk"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"سلامت سرویس ایجنت و لاگ‌ها معمولاً مشکلات مربوط به اتصال، هویت یا افزونه‌ها (Extensions) را آشکار می‌کنند.","en":"Agent service health and logs usually reveal connectivity, identity, or extension issues.","de":"Die richtige Antwort ist „Check the Connected Machine agent service and its recent logs“; sie passt zum Bereich Manage Windows Server instances and workloads in a hybrid environment und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"سروری از طریق Arc متصل شده است اما در Azure به صورت آفلاین نمایش داده می‌شود. کدام بررسی محلی در وهله اول مفیدتر است؟","optionsFa":["غیرفعال کردن دائمی فایروال ویندوز","بررسی سرویس ایجنت Connected Machine و لاگ‌های (گزارش‌های) اخیر آن","حذف فارست Active Directory","پارتیشن‌بندی مجدد دیسک سیستم"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-arc/servers/agent-overview","https://learn.microsoft.com/en-us/azure/azure-arc/servers/network-requirements"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Connect servers to Azure with Azure Arc","objectiveId":"hybrid-arc","topic":"Azure Arc-enabled servers","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-arc/servers/agent-overview","https://learn.microsoft.com/en-us/azure/azure-arc/servers/network-requirements"],"keyPoints":["An Arc resource that shows as offline usually means the Connected Machine agent service is stopped or cannot reach Azure.","The agent's own service state and recent logs are the fastest local source of the reason.","Common causes are a stopped service, expired or blocked credentials, and outbound connectivity to the Arc endpoints being blocked."],"whyOthers":["Disabling the Windows Firewall permanently weakens the server and is not a diagnosis.","","Deleting the AD forest would destroy the directory and has nothing to do with Arc connectivity.","Repartitioning the system disk is a destructive change with no relationship to the agent."],"commandPath":[{"label":"Show agent connection state and metadata","command":"azcmagent show"},{"label":"Review the agent service state","command":"Get-Service himds"}],"requirements":"Applies to Azure Arc-enabled servers. The agent service is named himds on Windows, and agent logs are the authoritative local evidence for an offline status."},
{"id":"az802-q-096","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"Which feature helps enforce a desired configuration across Arc-enabled servers?","options":["Azure Policy","DHCP reservations","Hyper-V Enhanced Session Mode","FSRM quotas"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"سرویس Azure Policy منابع را بر اساس تعاریف ارزیابی می‌کند و می‌تواند برای تنظیمات سرور از قابلیت Guest Configuration یا مکانیزم‌های مرتبط استفاده نماید.","en":"Azure Policy evaluates resources against definitions and can use guest configuration or related mechanisms for server settings.","de":"Die richtige Antwort ist „Azure Policy“; sie passt zum Bereich Manage Windows Server instances and workloads in a hybrid environment und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام قابلیت به اعمال پیکربندی مطلوب در سرورهای مجهز به Arc کمک می‌کند؟","optionsFa":["Azure Policy","رزروهای DHCP","حالت Enhanced Session در Hyper-V","سهمیه‌های FSRM"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/governance/policy/overview","https://learn.microsoft.com/en-us/azure/azure-arc/servers/overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Centrally manage hybrid resources with Azure Policy","objectiveId":"hybrid-policy","topic":"Azure Policy","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/governance/policy/overview","https://learn.microsoft.com/en-us/azure/azure-arc/servers/overview"],"keyPoints":["Azure Policy evaluates resources against policy definitions and reports compliance.","Through guest configuration, it can evaluate and enforce settings inside Arc-enabled servers, not only resource metadata.","Assignments can be scoped to management groups, subscriptions, or resource groups to cover many servers consistently."],"whyOthers":["","DHCP reservations assign addresses and do not enforce configuration.","Hyper-V Enhanced Session Mode improves the console experience and does not enforce configuration.","FSRM quotas limit file storage and are not a compliance mechanism."],"requirements":"Applies to Azure Policy. Enforcement behaviour depends on the policy effect, such as Audit or DeployIfNotExists, and some guest-configuration policies require a managed identity on the assignment for remediation."},
{"id":"az802-q-097","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"What is a safe way to grant a help-desk operator only one remote-management function?","options":["Add the operator to Enterprise Admins","Share the domain administrator password","Give unrestricted local administrator access on every server","Use a JEA endpoint or narrowly delegated role"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"تفویض اختیارات محدود، اصل «کمترین سطح دسترسی» (Least Privilege) را اعمال کرده و تغییرات ناخواسته یا مخرب را محدود می‌سازد.","en":"Narrow delegation enforces least privilege and limits accidental or malicious changes.","de":"Die richtige Antwort ist „Use a JEA endpoint or narrowly delegated role“; sie passt zum Bereich Manage Windows Server instances and workloads in a hybrid environment und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"روشی ایمن برای اعطای تنها یک قابلیت مدیریت از راه دور به اپراتور میز کمک (Help-desk) چیست؟","optionsFa":["افزودن اپراتور به گروه Enterprise Admins","به اشتراک‌گذاری رمز عبور مدیر دامنه (Domain Administrator)","اعطای دسترسی کامل و بدون محدودیت مدیر محلی (Local Administrator) در تمام سرورها","استفاده از یک نقطه پایانی JEA یا نقشی با تفویض اختیارات محدود"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/powershell/scripting/security/remoting/jea/overview?view=powershell-7.6"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Constrain administrative access with Just Enough Administration","objectiveId":"hybrid-jea","topic":"Delegated administration","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/powershell/scripting/security/remoting/jea/overview?view=powershell-7.6"],"keyPoints":["A JEA endpoint exposes only the commands and parameters a role needs, so the operator cannot do more than that task.","A narrowly delegated role achieves the same result without JEA when the task maps to a specific directory right.","Either way, least privilege limits accidental and malicious changes."],"whyOthers":["Adding the operator to Enterprise Admins grants forest-wide control, which is far beyond one management function.","Sharing the domain administrator password defeats accountability and grants broad access.","Unrestricted local administrator access on every server is more privilege than one function requires.",""],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. JEA endpoints are registered on the target and can run with a virtual account or a gMSA so the delegated work has its own scoped identity."},
{"id":"az802-q-098","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"What is the primary purpose of Windows Admin Center’s Azure integration?","options":["Convert NTFS to ReFS automatically","Host a public DNS root","Connect local management workflows with Azure services and hybrid resources","Replace all PowerShell scripts"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"این یکپارچه‌سازی می‌تواند از ثبت‌نام در Azure، سرویس Arc، پایش (مانیتورینگ)، مدیریت به‌روزرسانی‌ها و سایر عملیات ترکیبی پشتیبانی کند.","en":"The integration can support Azure registration, Arc, monitoring, update management, and other hybrid operations.","de":"Die richtige Antwort ist „Connect local management workflows with Azure services and hybrid resources“; sie passt zum Bereich Manage Windows Server instances and workloads in a hybrid environment und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"هدف اصلی یکپارچه‌سازی Windows Admin Center با Azure چیست؟","optionsFa":["تبدیل خودکار NTFS به ReFS","میزبانی یک ریشه (root) عمومی DNS","اتصال گردش‌کارهای مدیریتی محلی به سرویس‌های Azure و منابع ترکیبی (هیبریدی)","جایگزینی تمام اسکریپت‌های PowerShell"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/manage/windows-admin-center/understand/what-is","https://learn.microsoft.com/en-us/azure/azure-arc/servers/overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage Windows Server by using Windows Admin Center","objectiveId":"hybrid-windows-admin-center","topic":"Windows Admin Center","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/manage/windows-admin-center/understand/what-is","https://learn.microsoft.com/en-us/azure/azure-arc/servers/overview"],"keyPoints":["Windows Admin Center's Azure integration connects local management workflows with Azure services.","It can support registration with Azure, Arc onboarding, monitoring, and update management from the same console.","The goal is a single management surface for hybrid resources rather than a separate tool per environment."],"whyOthers":["Windows Admin Center does not automatically convert NTFS to ReFS; the file system is chosen when a volume is created.","It does not host a public DNS root server; that is a DNS role.","","It does not replace all PowerShell scripts; it is a management surface that complements scripting."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Azure integration requires the gateway to be able to authenticate to Azure and, for Arc scenarios, the server to be onboarded."},
{"id":"az802-q-099","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"A remote management design must support auditing and separation of duties. Which combination is strongest?","options":["Direct internet exposure of WinRM","Role-based access, JEA where appropriate, centralized logs, and secure transport","Shared local Administrator credentials","Telnet and anonymous access"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"این ترکیب باعث محدود شدن سطح دسترسی (امتیازات)، ثبت فعالیت‌ها و محافظت از ترافیک مدیریتی می‌شود.","en":"This combination limits privilege, records activity, and protects administrative traffic.","de":"Die richtige Antwort ist „Role-based access, JEA where appropriate, centralized logs, and secure transport“; sie passt zum Bereich Manage Windows Server instances and workloads in a hybrid environment und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"طراحی یک سیستم مدیریت از راه دور باید از قابلیت حسابرسی (auditing) و تفکیک وظایف پشتیبانی کند. کدام ترکیب بهترین گزینه است؟","optionsFa":["قرار دادن مستقیم WinRM در معرض اینترنت","دسترسی مبتنی بر نقش (RBAC)، استفاده از JEA در موارد مناسب، لاگ‌های متمرکز و انتقال امن داده‌ها","استفاده از اعتبارنامه‌های (credentials) مشترک برای حساب Administrator محلی","استفاده از Telnet و دسترسی ناشناس (anonymous)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/powershell/scripting/security/remoting/winrm-security?view=powershell-7.6","https://learn.microsoft.com/en-us/powershell/scripting/security/remoting/jea/overview?view=powershell-7.6"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage servers remotely with PowerShell remoting","objectiveId":"hybrid-remoting","topic":"Remote management design","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/powershell/scripting/security/remoting/winrm-security?view=powershell-7.6","https://learn.microsoft.com/en-us/powershell/scripting/security/remoting/jea/overview?view=powershell-7.6"],"keyPoints":["Role-based access limits what each operator may do, which is the foundation of separation of duties.","JEA constrains session content where a narrower scope than a full administrative role is needed.","Centralised logging records administrative activity, and secure transport protects the traffic in transit."],"whyOthers":["Direct internet exposure of WinRM removes the network protections and is not a strong design.","","Shared local Administrator credentials destroy individual accountability and auditing.","Telnet and anonymous access are unencrypted and unauthenticated and provide no separation of duties."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. A complete design also covers certificate and key management for the transport, plus retention and review of the collected logs."},
{"id":"az802-q-100","domain":"Manage virtual machines","text":"Which Hyper-V component provides switching between virtual machines and physical networks?","options":["Virtual switch","Virtual hard disk controller only","Checkpoint manager","Integration Services"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"یک سوئیچ مجازی Hyper-V، آداپتورهای شبکه ماشین‌های مجازی (VM) را به یکدیگر، به میزبان (Host) یا به یک شبکه فیزیکی خارجی متصل می‌کند.","en":"A Hyper-V virtual switch connects VM network adapters to each other, the host, or an external physical network.","de":"Die richtige Antwort ist „Virtual switch“; sie passt zum Bereich Manage virtual machines und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام مؤلفه Hyper-V امکان برقراری ارتباط (سوئیچینگ) بین ماشین‌های مجازی و شبکه‌های فیزیکی را فراهم می‌کند؟","optionsFa":["سوئیچ مجازی","فقط کنترلر هارد دیسک مجازی","مدیریت‌کننده نقاط بازگشت (Checkpoint manager)","سرویس‌های یکپارچه‌سازی (Integration Services)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/get-started/create-a-virtual-switch-for-hyper-v-virtual-machines","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/plan/plan-hyper-v-networking-in-windows-server"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure virtual machine networking","objectiveId":"vm-networking","topic":"Hyper-V virtual switch","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/get-started/create-a-virtual-switch-for-hyper-v-virtual-machines","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/plan/plan-hyper-v-networking-in-windows-server"],"keyPoints":["A Hyper-V virtual switch connects virtual network adapters to each other, to the host, or to a physical network.","It is a software layer that performs the switching that a physical switch would perform for the virtual machines.","The switch type determines which of those connections are possible."],"whyOthers":["","A virtual hard disk controller attaches storage to a virtual machine and provides no network connectivity.","Checkpoint manager creates and manages virtual machine checkpoints, which capture state rather than carrying network traffic.","Integration Services provide host-to-guest services such as heartbeat and time synchronisation, not packet switching."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 with the Hyper-V role installed. A virtual switch is bound at the host level and is then attached to virtual machine network adapters."},
{"id":"az802-q-101","domain":"Manage virtual machines","text":"Which Hyper-V virtual switch type connects VMs to the physical network?","options":["Internal","Private","Isolated storage","External"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"سوئیچ خارجی به یک آداپتور شبکه فیزیکی متصل می‌شود و امکان ارتباط با خارج را فراهم می‌کند.","en":"An external switch binds to a physical network adapter and provides external connectivity.","de":"Die richtige Antwort ist „External“; sie passt zum Bereich Manage virtual machines und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام نوع سوئیچ مجازی Hyper-V، ماشین‌های مجازی را به شبکه فیزیکی متصل می‌کند؟","optionsFa":["داخلی (Internal)","خصوصی (Private)","فضای ذخیره‌سازی ایزوله","خارجی (External)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/get-started/create-a-virtual-switch-for-hyper-v-virtual-machines"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure virtual machine networking","objectiveId":"vm-networking","topic":"Hyper-V virtual switch","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/get-started/create-a-virtual-switch-for-hyper-v-virtual-machines"],"keyPoints":["An external virtual switch binds to a physical network adapter and provides connectivity to the physical network.","It is the switch type used when virtual machines must reach physical hosts, the internet, or other networks.","The host can still use the physical adapter through the switch, and a virtual adapter is created on the host for that purpose."],"whyOthers":["An internal switch connects virtual machines and the host but has no binding to a physical adapter, so there is no physical network path.","A private switch connects only the virtual machines attached to it and excludes both the host and the physical network.","An isolated storage switch is not a Hyper-V switch type; storage isolation is a separate concept.",""],"commandPath":[{"label":"Create an external virtual switch on a physical adapter","command":"New-VMSwitch -Name External-Switch -NetAdapterName 'Ethernet' -AllowManagementOS $true"}],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Binding an external switch to a physical adapter briefly interrupts host networking, so plan the change for a maintenance window."},
{"id":"az802-q-102","domain":"Manage virtual machines","text":"Which switch type permits communication between VMs and the host but not directly to the physical network?","options":["Private","Public","Internal","External"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"سوئیچ داخلی شامل میزبان و ماشین‌های مجازی می‌شود اما اتصال مستقیمی به شبکه فیزیکی ندارد.","en":"An internal switch includes the host and VMs but has no direct physical network binding.","de":"Die richtige Antwort ist „Internal“; sie passt zum Bereich Manage virtual machines und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام نوع سوئیچ امکان ارتباط بین ماشین‌های مجازی و میزبان را فراهم می‌کند، اما اجازه ارتباط مستقیم با شبکه فیزیکی را نمی‌دهد؟","optionsFa":["خصوصی (Private)","عمومی (Public)","داخلی (Internal)","خارجی (External)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/get-started/create-a-virtual-switch-for-hyper-v-virtual-machines"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure virtual machine networking","objectiveId":"vm-networking","topic":"Hyper-V virtual switch","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/get-started/create-a-virtual-switch-for-hyper-v-virtual-machines"],"keyPoints":["An internal switch allows communication between virtual machines and the management host operating system.","It has no binding to a physical network adapter, so virtual machines cannot reach the physical network directly through it.","It is often used for host-to-guest management or for traffic that should not leave the host."],"whyOthers":["A private switch excludes the host, so it does not permit communication with the host.","There is no Public switch type in Hyper-V; public connectivity is provided by an external switch.","","An external switch does bind to the physical network, so it does not match the scenario."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. An internal switch creates a virtual adapter on the host, which is how the host takes part in that network."},
{"id":"az802-q-103","domain":"Manage virtual machines","text":"Which switch type permits communication only among attached VMs?","options":["NAT","Private","Internal","External"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"یک سوئیچ خصوصی، ترافیک خود را به ماشین‌های مجازی متصل‌شده محدود (ایزوله) می‌کند.","en":"A private switch isolates its traffic to the connected virtual machines.","de":"Die richtige Antwort ist „Private“; sie passt zum Bereich Manage virtual machines und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام نوع سوئیچ تنها اجازه ارتباط میان ماشین‌های مجازی متصل به خود را می‌دهد؟","optionsFa":["NAT","خصوصی (Private)","داخلی (Internal)","خارجی (External)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/get-started/create-a-virtual-switch-for-hyper-v-virtual-machines"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure virtual machine networking","objectiveId":"vm-networking","topic":"Hyper-V virtual switch","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/get-started/create-a-virtual-switch-for-hyper-v-virtual-machines"],"keyPoints":["A private switch carries traffic only between the virtual machines attached to it.","Neither the host nor the physical network can participate, which makes it useful for isolated test traffic.","It is the most restrictive of the three Hyper-V switch types."],"whyOthers":["NAT is a configuration that shares an address through a virtual adapter; it is not the switch type that isolates traffic to attached virtual machines.","","An internal switch includes the host, so it is not restricted to the virtual machines only.","An external switch connects to the physical network, which is the opposite of isolation."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Because the host has no adapter on a private switch, virtual machines on it cannot be managed over the network without another adapter."},
{"id":"az802-q-104","domain":"Manage virtual machines","text":"What is the purpose of a Hyper-V checkpoint?","options":["Capture a VM’s state and virtual-disk configuration for a point-in-time rollback","Create an AD backup","Assign an IP address","Replicate a DNS zone"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"چک‌پوینت‌ها برای بازگردانی تغییرات کوتاه‌مدت مفید هستند، اما جایگزینی برای نسخه‌های پشتیبانِ سازگار با برنامه (application-consistent backups) محسوب نمی‌شوند.","en":"Checkpoints are useful for short-term change rollback, but they are not a substitute for application-consistent backups.","de":"Die richtige Antwort ist „Capture a VM’s state and virtual-disk configuration for a point-in-time rollback“; sie passt zum Bereich Manage virtual machines und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"هدف از ایجاد یک Checkpoint در Hyper-V چیست؟","optionsFa":["ثبت وضعیت ماشین مجازی (VM) و پیکربندی دیسک مجازی برای بازگردانی به یک مقطع زمانی خاص","ایجاد نسخه پشتیبان از AD (Active Directory)","اختصاص یک آدرس IP","تکثیر (Replicate) یک ناحیه DNS"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/checkpoints","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/features-terminology"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage virtual machine storage and checkpoints","objectiveId":"vm-storage-checkpoints","topic":"Hyper-V checkpoints","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/checkpoints","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/features-terminology"],"keyPoints":["A checkpoint captures a virtual machine's state and its virtual disk configuration so the machine can be reverted to that point.","The virtual disks referenced by the checkpoint are switched to differencing disks so later changes accumulate separately.","Checkpoints are intended for short-term rollback and are not a substitute for an application-consistent backup."],"whyOthers":["","An AD backup protects directory data and is a different mechanism from a Hyper-V checkpoint.","Assigning an IP address is a network configuration action and is unrelated to checkpoints.","Replicating a DNS zone is a DNS operation and is not what a checkpoint does."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. A checkpoint stores data in .avhdx differencing files alongside the original .vhdx, so it consumes additional storage over time."},
{"id":"az802-q-105","domain":"Manage virtual machines","text":"Which checkpoint type is generally safer for a production application when supported?","options":["Standard checkpoint with saved memory only","Network checkpoint","DNS checkpoint","Production checkpoint"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"چک‌پوینت‌های عملیاتی (Production checkpoints) به جای ذخیره حافظه در حال اجرا، از فناوری پشتیبان‌گیری در داخل سیستم‌عامل مهمان (Guest) برای ایجاد وضعیتی سازگار با برنامه استفاده می‌کنند.","en":"Production checkpoints use backup technology inside the guest to create an application-consistent state rather than saving running memory.","de":"Die richtige Antwort ist „Production checkpoint“; sie passt zum Bereich Manage virtual machines und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"در صورت پشتیبانی، کدام نوع چک‌پوینت برای یک برنامه عملیاتی (Production) معمولاً ایمن‌تر است؟","optionsFa":["چک‌پوینت استاندارد (Standard) که فقط حافظه را ذخیره می‌کند","چک‌پوینت شبکه (Network)","چک‌پوینت DNS","چک‌پوینت عملیاتی (Production)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/manage/choose-between-standard-or-production-checkpoints-in-hyper-v","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/checkpoints"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage virtual machine storage and checkpoints","objectiveId":"vm-storage-checkpoints","topic":"Hyper-V checkpoints","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/manage/choose-between-standard-or-production-checkpoints-in-hyper-v","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/checkpoints"],"keyPoints":["A production checkpoint uses backup technology inside the guest to create an application-consistent state rather than saving running memory.","Because it does not capture memory, restoring it is like recovering from a clean shutdown rather than resuming a running session.","Standard checkpoints are used when a saved run-time state is required, such as for development and testing."],"whyOthers":["A standard checkpoint with saved memory is used for development and testing; it is not application-consistent, which is why production checkpoints are safer for a running application.","There is no Hyper-V checkpoint type named network checkpoint.","There is no Hyper-V checkpoint type named DNS checkpoint.",""],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Production checkpoints are the default on Windows Server 2016 and later, and they require the guest to support the backup technology being used."},
{"id":"az802-q-106","domain":"Manage virtual machines","text":"Why should long-lived checkpoints be avoided?","options":["They delete the parent VHDX immediately","They prevent any guest logon","They can consume storage and create complex differencing-disk chains","They disable all VM networking"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"حجم Checkpointها افزایش می‌یابد و ممکن است مدیریت عملکرد، ظرفیت و بازیابی را پیچیده کند.","en":"Checkpoints grow and may complicate performance, capacity, and recovery management.","de":"Die richtige Antwort ist „They can consume storage and create complex differencing-disk chains“; sie passt zum Bereich Manage virtual machines und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"چرا باید از ایجاد چک‌پوینت‌هایی با عمر طولانی (ماندگاری زیاد) اجتناب کرد؟","optionsFa":["آن‌ها فایل VHDX والد را بلافاصله حذف می‌کنند","آن‌ها از ورود (logon) هرگونه کاربر مهمان (guest) جلوگیری می‌کنند","آن‌ها می‌توانند فضای ذخیره‌سازی را اشغال کرده و زنجیره‌های پیچیده‌ای از دیسک‌های تفاضلی (differencing-disk) ایجاد کنند","آن‌ها تمام قابلیت‌های شبکه ماشین مجازی (VM) را غیرفعال می‌کنند"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/checkpoints","https://learn.microsoft.com/en-us/troubleshoot/windows-server/virtualization/hyper-v-virtual-machine-backup-checkpoint-storage"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage virtual machine storage and checkpoints","objectiveId":"vm-storage-checkpoints","topic":"Hyper-V checkpoints","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/checkpoints","https://learn.microsoft.com/en-us/troubleshoot/windows-server/virtualization/hyper-v-virtual-machine-backup-checkpoint-storage"],"keyPoints":["Checkpoints grow as the virtual machine writes changes, so a long-lived checkpoint consumes increasing host storage.","Each checkpoint adds a link in a chain of differencing disks, and a deep chain complicates capacity and recovery management.","Merging a checkpoint requires enough free space to write the merged result, so filling the volume can block the merge."],"whyOthers":["A checkpoint does not delete the parent virtual disk; it creates a differencing disk and keeps the parent.","Checkpoints do not prevent guest sign-in; the guest continues to run normally.","","Checkpoints do not disable virtual machine networking."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. A checkpoint should be removed or applied as soon as its purpose is served, and the volume should keep free space for the merge."},
{"id":"az802-q-107","domain":"Manage virtual machines","text":"Which virtual disk format supports features such as larger capacity and resiliency improvements compared with VHD?","options":["IMG only","VHDX","ISO","VFD"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"فرمت VHDX از دیسک‌های بزرگ‌تر و قابلیت‌هایی که برای بارهای کاری مدرن Hyper-V طراحی شده‌اند، پشتیبانی می‌کند.","en":"VHDX supports larger disks and features designed for modern Hyper-V workloads.","de":"Die richtige Antwort ist „VHDX“; sie passt zum Bereich Manage virtual machines und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام فرمت دیسک مجازی در مقایسه با VHD، از قابلیت‌هایی مانند ظرفیت بیشتر و بهبودهای تاب‌آوری (resiliency) پشتیبانی می‌کند؟","optionsFa":["فقط IMG","VHDX","ISO","VFD"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/features-terminology","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/checkpoints"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage virtual machine storage and checkpoints","objectiveId":"vm-storage-checkpoints","topic":"Virtual hard disk formats","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/features-terminology","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/checkpoints"],"keyPoints":["VHDX is the newer virtual hard disk format and supports larger disk sizes than the legacy VHD format.","VHDX also adds features such as larger block sizes and better resilience against power failure.","The legacy VHD format is limited to 2 TB and is retained mainly for compatibility."],"whyOthers":["IMG is a disk image format used elsewhere and is not a Hyper-V virtual hard disk format.","","ISO is an optical disc image, not a virtual hard disk format.","VFD is a virtual floppy disk format and does not provide modern capacity or resiliency features."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 with Hyper-V. VHDX supports virtual disks up to 64 TB, while the legacy VHD format is limited to 2 TB."},
{"id":"az802-q-108","domain":"Manage virtual machines","text":"What is the main advantage of a dynamically expanding VHDX?","options":["It starts small and grows as data is written","It always has the best write performance","It cannot run out of host storage","It is automatically replicated to Azure"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"دیسک‌های پویا در مصرف ظرفیت اولیه صرفه‌جویی می‌کنند، اما نیاز به نظارت دارند زیرا با گسترش آن‌ها، ممکن است فضای ذخیره‌سازی میزبان به اتمام برسد.","en":"Dynamic disks conserve initial capacity but require monitoring because host storage can be exhausted as they expand.","de":"Die richtige Antwort ist „It starts small and grows as data is written“; sie passt zum Bereich Manage virtual machines und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"مزیت اصلی یک فایل VHDX با قابلیت گسترش پویا (dynamically expanding) چیست؟","optionsFa":["با حجم کم شروع می‌شود و هم‌زمان با نوشتن داده‌ها، حجم آن افزایش می‌یابد","همیشه بهترین عملکرد نوشتن را دارد","فضای ذخیره‌سازی میزبان (host) برای آن تمام نمی‌شود","به‌طور خودکار در Azure تکثیر (replicate) می‌شود"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/features-terminology"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage virtual machine storage and checkpoints","objectiveId":"vm-storage-checkpoints","topic":"Virtual hard disk formats","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/features-terminology"],"keyPoints":["A dynamically expanding VHDX starts small and grows as data is written to it.","It conserves host storage at first but can exhaust the volume as the guest fills the disk.","Because of the growth, monitoring free space on the host volume is essential."],"whyOthers":["","Dynamic disks do not always have the best write performance; a fixed disk often performs more consistently because the space is allocated up front.","A dynamic disk can absolutely run out of host storage as it expands.","Dynamic VHDX files are not automatically replicated to Azure; replication is a separate configuration."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. A dynamically expanding disk is the default in many workflows, which is why host free-space monitoring matters."},
{"id":"az802-q-109","domain":"Manage virtual machines","text":"When is a fixed-size VHDX often preferred?","options":["When the host has no storage","When a VM must use a private switch","When no backup is needed","When predictable capacity and consistent performance are more important than fast provisioning"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"دیسک های ثابت فضا را در جلو اختصاص می دهند و می توانند تغییرات عملکرد مرتبط با گسترش را کاهش دهند.","en":"Fixed disks allocate space up front and can reduce expansion-related performance variation.","de":"Die richtige Antwort ist „When predictable capacity and consistent performance are more important than fast provisioning“; sie passt zum Bereich Manage virtual machines und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"چه زمانی یک VHDX با اندازه ثابت اغلب ترجیح داده می شود؟","optionsFa":["وقتی هاست فضای ذخیره سازی ندارد","وقتی یک ماشین مجازی باید از سوئیچ خصوصی استفاده کند","زمانی که نیازی به پشتیبان گیری نیست","وقتی ظرفیت قابل پیش بینی و عملکرد ثابت مهم تر از تدارک سریع است"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/openspecs/windows_protocols/ms-vhdx/83f6b700-6216-40f0-aa99-9fcb421206e2","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/features-terminology"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage virtual machine storage and checkpoints","objectiveId":"vm-storage-checkpoints","topic":"Virtual hard disk formats","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/openspecs/windows_protocols/ms-vhdx/83f6b700-6216-40f0-aa99-9fcb421206e2","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/features-terminology"],"keyPoints":["A fixed-size VHDX allocates all of its space up front, so capacity is predictable and cannot grow unexpectedly.","Because the blocks are already allocated, write behaviour is more consistent than with a dynamic disk.","The trade-off is that provisioning takes longer and consumes the full capacity immediately."],"whyOthers":["A fixed disk requires more host storage than a dynamic disk at creation, so it is not chosen when the host has no storage.","The switch type a virtual machine uses is unrelated to the disk format.","Backup requirements do not determine the disk format; both formats need backup.",""],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Converting between dynamic and fixed is possible with the Hyper-V tools, but conversion of a dynamic disk to fixed is not always allowed while a checkpoint chain exists."},
{"id":"az802-q-110","domain":"Manage virtual machines","text":"What does PowerShell Direct allow an administrator to do?","options":["Replace an external virtual switch","Replicate a VM across forests","Manage a supported Windows guest from the Hyper-V host without guest network connectivity","Connect to any internet server without credentials"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"PowerShell Direct از کانال ادغام میزبان به مهمان استفاده می کند و به شرایط میزبان و مهمان مناسب نیاز دارد.","en":"PowerShell Direct uses the host-to-guest integration channel and requires suitable host and guest conditions.","de":"Die richtige Antwort ist „Manage a supported Windows guest from the Hyper-V host without guest network connectivity“; sie passt zum Bereich Manage virtual machines und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"PowerShell Direct به یک مدیر اجازه انجام چه کاری را می دهد؟","optionsFa":["یک سوئیچ مجازی خارجی را جایگزین کنید","یک VM را در سراسر جنگل ها تکرار کنید","مدیریت یک مهمان ویندوز پشتیبانی شده از میزبان Hyper-V بدون اتصال به شبکه مهمان","اتصال به هر سرور اینترنتی بدون اعتبار"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/powershell-direct","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/features-terminology"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage virtual machine compute and integration services","objectiveId":"vm-compute","topic":"PowerShell Direct","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/powershell-direct","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/features-terminology"],"keyPoints":["PowerShell Direct lets an administrator manage a supported Windows guest from the Hyper-V host without guest network connectivity.","It uses the host-to-guest integration channel, so it works even when the guest has no network adapter.","It is useful for initial configuration, troubleshooting, and automation on a host that is already trusted."],"whyOthers":["PowerShell Direct does not replace an external virtual switch; switching is a separate function.","It does not replicate a virtual machine across forests; replication is a Hyper-V Replica function.","","It connects only to a guest running on the same host, not to arbitrary internet servers."],"commandPath":[{"label":"Open an interactive session to a guest by name","command":"Enter-PSSession -VMName Web01 -Credential (Get-Credential)"},{"label":"Run a command in a guest without network access","command":"Invoke-Command -VMName Web01 -Credential (Get-Credential) -ScriptBlock { Get-Service }"}],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 hosts with Windows Server 2016 or later guests. The guest must be running, and the credentials used must exist inside the guest operating system."},
{"id":"az802-q-111","domain":"Manage virtual machines","text":"What is required for a Linux guest to be managed through SSH Direct from a Hyper-V host?","options":["A DNSSEC key","A supported guest, configured OpenSSH service, and appropriate host integration","A writable domain controller","A DHCP failover cluster"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"SSH Direct به قابلیت های Hyper-V پشتیبانی شده و یک سرویس SSH کارآمد در مهمان بستگی دارد.","en":"SSH Direct depends on supported Hyper-V capabilities and a functioning SSH service in the guest.","de":"Die richtige Antwort ist „A supported guest, configured OpenSSH service, and appropriate host integration“; sie passt zum Bereich Manage virtual machines und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"برای مدیریت یک مهمان لینوکس از طریق SSH Direct از هاست Hyper-V چه چیزی لازم است؟","optionsFa":["یک کلید DNSSEC","یک مهمان پشتیبانی شده، سرویس OpenSSH پیکربندی شده و یکپارچه سازی میزبان مناسب","یک کنترل کننده دامنه قابل نوشتن","یک خوشه شکست DHCP"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/powershell-direct","https://learn.microsoft.com/en-us/windows-server/administration/openssh/openssh-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage virtual machine compute and integration services","objectiveId":"vm-compute","topic":"SSH Direct","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/powershell-direct","https://learn.microsoft.com/en-us/windows-server/administration/openssh/openssh-overview"],"keyPoints":["SSH Direct extends the same host-to-guest idea to supported Linux guests over SSH.","It requires a supported guest, a working OpenSSH service in the guest, and appropriate host integration.","Like PowerShell Direct, it removes the dependency on guest network connectivity."],"whyOthers":["A DNSSEC key is used to sign DNS data and has no role in guest management.","","A writable domain controller is not required for SSH Direct.","A DHCP failover cluster provides address-service redundancy and is irrelevant to guest access."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 hosts with supported Linux guests. The guest needs the Hyper-V integration components (or the KVP daemon) and the SSH server running."},
{"id":"az802-q-112","domain":"Manage virtual machines","text":"What does nested virtualization enable?","options":["Running a hypervisor inside a virtual machine","Running a VM without a host","Running DNS inside a switch","Converting a VM to a physical server"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"مجازی‌سازی تودرتو، افزونه‌های مجازی‌سازی را در معرض دید مهمان قرار می‌دهد تا بتواند VM‌های اضافی یا بارهای کاری مجازی‌سازی را میزبانی کند.","en":"Nested virtualization exposes virtualization extensions to a guest so it can host additional VMs or virtualization workloads.","de":"Die richtige Antwort ist „Running a hypervisor inside a virtual machine“; sie passt zum Bereich Manage virtual machines und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"مجازی سازی تودرتو چه چیزی را فعال می کند؟","optionsFa":["اجرای هایپروایزر در داخل ماشین مجازی","اجرای VM بدون هاست","اجرای DNS در داخل سوئیچ","تبدیل ماشین مجازی به سرور فیزیکی"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/virtualization/hyper-v-on-windows/user-guide/nested-virtualization","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/features-terminology"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage virtual machine compute and integration services","objectiveId":"vm-compute","topic":"Nested virtualization","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/virtualization/hyper-v-on-windows/user-guide/nested-virtualization","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/features-terminology"],"keyPoints":["Nested virtualization exposes hardware virtualization extensions to a virtual machine so it can run its own hypervisor.","It lets a guest host additional virtual machines, which is common for development, testing, and some container or training scenarios.","The host must support the required virtualization extensions and, where required, explicit enablement."],"whyOthers":["","A virtual machine cannot run without a host; nested virtualization still depends on the physical host.","Running DNS inside a switch is not a supported concept and is unrelated to nested virtualization.","Converting a virtual machine to a physical server describes a migration, not nested virtualization."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 with Hyper-V. The guest operating system must support the exposed extensions, and performance of the nested workload is lower than on a physical host."},
{"id":"az802-q-113","domain":"Manage virtual machines","text":"Which Hyper-V memory feature allows a VM’s memory allocation to change within configured limits?","options":["Storage QoS","NUMA spanning only","Memory checkpoint","Dynamic Memory"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"حافظه پویا راه اندازی، حداقل و حداکثر حافظه را بر اساس تقاضا و در دسترس بودن تنظیم می کند.","en":"Dynamic Memory adjusts startup, minimum, and maximum memory according to demand and availability.","de":"Die richtige Antwort ist „Dynamic Memory“; sie passt zum Bereich Manage virtual machines und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام ویژگی حافظه Hyper-V اجازه می دهد تخصیص حافظه VM در محدوده های پیکربندی شده تغییر کند؟","optionsFa":["کیفیت سرویس ذخیره سازی","فقط شامل NUMA","ایست بازرسی حافظه","حافظه پویا"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/features-terminology"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage virtual machine compute and integration services","objectiveId":"vm-compute","topic":"Dynamic memory","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/features-terminology"],"keyPoints":["Dynamic Memory lets the memory assigned to a virtual machine change between configured limits as demand changes.","The configuration includes startup memory, minimum memory, and maximum memory values.","It allows a host to run more virtual machines by reclaiming memory that other guests are not using."],"whyOthers":["Storage QoS manages storage throughput rather than memory allocation.","NUMA spanning controls how a virtual machine's memory maps across physical NUMA nodes; it does not itself change the memory allocation within limits.","There is no Hyper-V feature named memory checkpoint.",""],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Dynamic Memory requires supported guest integration services, and the minimum and maximum values should reflect what the workload truly needs."},
{"id":"az802-q-114","domain":"Manage virtual machines","text":"What is a risk of setting a VM’s minimum memory too low?","options":["The VM becomes a domain controller","DNS records are deleted","The guest may experience memory pressure and paging","The host automatically gains more CPU"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"مهمان همچنان برای عملکرد قابل قبول سیستم عامل و حجم کاری خود به حافظه کافی نیاز دارد.","en":"The guest still needs enough memory for its operating system and workload to function acceptably.","de":"Die richtige Antwort ist „The guest may experience memory pressure and paging“; sie passt zum Bereich Manage virtual machines und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"خطر تنظیم بیش از حد حداقل حافظه VM چیست؟","optionsFa":["VM به یک کنترل کننده دامنه تبدیل می شود","رکوردهای DNS حذف می شوند","مهمان ممکن است فشار حافظه و صفحه بندی را تجربه کند","میزبان به طور خودکار CPU بیشتری به دست می آورد"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/features-terminology"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage virtual machine compute and integration services","objectiveId":"vm-compute","topic":"Dynamic memory","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/features-terminology"],"keyPoints":["The minimum memory value is the floor the host will not take memory below, so it must cover what the guest needs to run acceptably.","If the minimum is too low, the guest experiences memory pressure and pages heavily, which harms performance.","The guest operating system still needs enough memory for its own components plus the application workload."],"whyOthers":["A memory setting cannot turn a virtual machine into a domain controller; that role is installed in the guest operating system.","Memory allocation does not delete DNS records.","","Reducing a virtual machine's minimum memory does not give the host more CPU; CPU is a separate resource."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. The maximum memory should also be checked against the workload ceiling so the guest is not starved at peak demand."},
{"id":"az802-q-115","domain":"Manage virtual machines","text":"Which setting can control how many virtual processors a VM receives?","options":["NTFS quota","Virtual processor count","DHCP reservation","DNS TTL"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"پیکربندی پردازنده مجازی VM تعداد پردازنده های منطقی ارائه شده به مهمان را کنترل می کند.","en":"The VM’s virtual processor configuration controls the number of logical processors presented to the guest.","de":"Die richtige Antwort ist „Virtual processor count“; sie passt zum Bereich Manage virtual machines und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام تنظیمات می تواند تعداد پردازنده های مجازی را که یک VM دریافت می کند کنترل کند؟","optionsFa":["سهمیه NTFS","تعداد پردازنده مجازی","رزرو DHCP","DNS TTL"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/features-terminology"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage virtual machine compute and integration services","objectiveId":"vm-compute","topic":"Virtual processors","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/features-terminology"],"keyPoints":["The virtual processor count controls how many logical processors the guest sees.","The value can be changed while the guest is running when the guest operating system supports it.","Over-assigning processors to guests does not create CPU capacity and can increase contention on the host."],"whyOthers":["An NTFS quota limits disk space for a user or folder and does not control processors.","","A DHCP reservation assigns a stable IP address and is unrelated to processor allocation.","DNS TTL affects how long a DNS record may be cached, not how many processors a virtual machine receives."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Guest support matters: the processor count must be within what the guest operating system licence and edition allow."},
{"id":"az802-q-116","domain":"Manage virtual machines","text":"What is the purpose of Hyper-V Integration Services?","options":["Improve host-guest integration such as time synchronization, shutdown, heartbeat, and data exchange","Provide internet DNS","Store AD objects","Encrypt every VHDX automatically"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"خدمات یکپارچه سازی ارتباطات کنترل شده و ویژگی های مدیریتی بین میزبان و مهمان را ارائه می دهد.","en":"Integration services provide controlled communication and management features between host and guest.","de":"Die richtige Antwort ist „Improve host-guest integration such as time synchronization, shutdown, heartbeat, and data exchange“; sie passt zum Bereich Manage virtual machines und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"هدف از خدمات یکپارچه سازی Hyper-V چیست؟","optionsFa":["ادغام میزبان و مهمان مانند همگام سازی زمان، خاموش کردن، ضربان قلب و تبادل داده را بهبود می بخشد.","ارائه DNS اینترنت","اشیاء AD را ذخیره کنید","هر VHDX را به صورت خودکار رمزگذاری کنید"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/manage/manage-hyper-v-integration-services","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/features-terminology"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage virtual machine compute and integration services","objectiveId":"vm-compute","topic":"Integration Services","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/manage/manage-hyper-v-integration-services","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/features-terminology"],"keyPoints":["Integration Services provide controlled communication and management features between the host and the guest.","These include time synchronisation, heartbeat, guest shutdown, and data exchange.","They can be enabled or disabled individually, and their state is visible in the virtual machine's settings."],"whyOthers":["","Integration Services do not provide internet DNS; DNS is a network service.","They do not store AD objects; the directory database does.","They do not encrypt virtual hard disks; disk encryption is provided by BitLocker or another encryption mechanism."],"commandPath":[{"label":"List the integration services on a virtual machine","command":"Get-VMIntegrationService -VMName Web01 | Select-Object Name, Enabled"}],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Guest operating systems receive integration components through Windows Update or a supported package, and a guest without them may not expose all services."},
{"id":"az802-q-117","domain":"Manage virtual machines","text":"What does NIC teaming provide on a Hyper-V host?","options":["Automatic AD replication","File-level deduplication","VM memory encryption only","Redundancy and sometimes increased aggregate network capacity"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Teaming آداپتورهای فیزیکی را برای بهبود در دسترس بودن ترکیب می کند و می تواند ترافیک را بسته به حالت توزیع کند.","en":"Teaming combines physical adapters to improve availability and can distribute traffic depending on the mode.","de":"Die richtige Antwort ist „Redundancy and sometimes increased aggregate network capacity“; sie passt zum Bereich Manage virtual machines und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"تیم NIC در هاست Hyper-V چه چیزی را ارائه می دهد؟","optionsFa":["تکرار خودکار AD","حذف تکراری در سطح فایل","فقط رمزگذاری حافظه VM","افزونگی و گاهی اوقات افزایش ظرفیت کل شبکه"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/plan/plan-hyper-v-networking-in-windows-server","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/features-terminology"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure virtual machine networking","objectiveId":"vm-networking","topic":"NIC teaming","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/plan/plan-hyper-v-networking-in-windows-server","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/features-terminology"],"keyPoints":["NIC teaming combines multiple physical adapters into one logical adapter so that traffic survives a single adapter failure.","Depending on the teaming mode, traffic can also be distributed across the adapters to increase aggregate throughput.","Switch Embedded Teaming (SET) is the teaming option designed to work with Hyper-V virtual switches."],"whyOthers":["NIC teaming does not replicate Active Directory; directory replication is a separate service.","File-level deduplication reduces stored file data and is unrelated to network adapters.","Teaming does not provide virtual machine memory encryption.",""],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Teaming modes differ in whether the physical switch must be configured to support the team, so the switch must match the chosen mode."},
{"id":"az802-q-118","domain":"Manage virtual machines","text":"Which Hyper-V feature can expose a physical PCIe device directly to a VM?","options":["VMQ only","Checkpoint merge","Discrete Device Assignment","Dynamic Memory"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"قابلیت DDA سخت‌افزارهای پشتیبانی‌شده (مانند دستگاه شبکه یا ذخیره‌سازی) را با کاهش دخالت میزبان (Host)، مستقیماً به ماشین مجازی منتقل می‌کند.","en":"DDA passes supported hardware such as a network or storage device through to a VM, with reduced host mediation.","de":"Die richtige Antwort ist „Discrete Device Assignment“; sie passt zum Bereich Manage virtual machines und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام قابلیت Hyper-V امکان در دسترس قرار دادن مستقیم یک دستگاه فیزیکی PCIe برای ماشین مجازی (VM) را فراهم می‌کند؟","optionsFa":["فقط VMQ","ادغام Checkpoint","Discrete Device Assignment (DDA)","Dynamic Memory"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/plan/plan-for-deploying-devices-using-discrete-device-assignment"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage virtual machine compute and integration services","objectiveId":"vm-compute","topic":"Discrete Device Assignment","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/plan/plan-for-deploying-devices-using-discrete-device-assignment"],"keyPoints":["Discrete Device Assignment (DDA) passes a supported physical PCIe device directly to a virtual machine.","The device is then owned by the guest, with reduced host mediation, which can improve performance for specialised workloads.","Because the device is assigned away from the host, it cannot be shared with other virtual machines at the same time."],"whyOthers":["VMQ offloads certain packet processing to the adapter; it does not hand a device to a guest.","Merging a checkpoint is a storage operation and does not assign hardware.","","Dynamic Memory changes memory allocation and does not pass through PCIe devices."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. DDA requires server hardware with the right firmware support, and the device must be dismounted from the host before it can be assigned."},
{"id":"az802-q-119","domain":"Manage virtual machines","text":"What is GPU partitioning intended to do?","options":["Create a VM checkpoint","Share a supported physical GPU among multiple VMs","Convert a GPU into a DNS server","Encrypt a hard disk"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"قابلیت GPU partitioning بخش‌هایی از یک GPU پشتیبانی‌شده را به ماشین‌های مجازی مجزا اختصاص می‌دهد.","en":"GPU partitioning allocates portions of a supported GPU to separate virtual machines.","de":"Die richtige Antwort ist „Share a supported physical GPU among multiple VMs“; sie passt zum Bereich Manage virtual machines und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"هدف از قابلیت GPU partitioning (بخش‌بندی GPU) چیست؟","optionsFa":["ایجاد یک Checkpoint برای ماشین مجازی","اشتراک‌گذاری یک GPU فیزیکی پشتیبانی‌شده بین چندین ماشین مجازی","تبدیل GPU به یک سرور DNS","رمزنگاری هارد دیسک"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/gpu-partitioning"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage virtual machine compute and integration services","objectiveId":"vm-compute","topic":"GPU partitioning","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/gpu-partitioning"],"keyPoints":["GPU partitioning divides a supported physical GPU so its resources can be shared among multiple virtual machines.","It lets several virtual machines use graphics or compute acceleration without dedicating a whole GPU to each.","It requires a GPU and host platform that support partitioning."],"whyOthers":["GPU partitioning does not create a checkpoint; checkpoints capture virtual machine state.","","It does not turn a GPU into a DNS server.","It does not encrypt a hard disk."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 with supported GPU hardware and drivers. GPU partitioning support depends on the specific GPU model and the host firmware configuration."},
{"id":"az802-q-120","domain":"Manage virtual machines","text":"What does Hyper-V Replica provide?","options":["Asynchronous replication of VMs to another Hyper-V host","Synchronous replication of every file share","DNS load balancing","Group Policy inheritance"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"قابلیت Hyper-V Replica با نگهداری یک نسخه تکثیرشده از ماشین مجازی روی میزبانی دیگر، از بازیابی پس از فاجعه (Disaster Recovery) پشتیبانی می‌کند.","en":"Hyper-V Replica supports disaster recovery by maintaining a replicated VM copy on a different host.","de":"Die richtige Antwort ist „Asynchronous replication of VMs to another Hyper-V host“; sie passt zum Bereich Manage virtual machines und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"قابلیت Hyper-V Replica چه امکانی را فراهم می‌کند؟","optionsFa":["تکثیر (Replication) ناهمگام (Asynchronous) ماشین‌های مجازی به یک میزبان Hyper-V دیگر","تکثیر همگام (Synchronous) تمام اشتراک‌گذاری‌های فایل (File Shares)","متعادل‌سازی بار (Load Balancing) در DNS","ارث‌بری Group Policy"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/replication-overview","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/manage/set-up-hyper-v-replica"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure high availability and replication for virtual machines","objectiveId":"vm-ha-replication","topic":"Hyper-V Replica","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/replication-overview","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/manage/set-up-hyper-v-replica"],"keyPoints":["Hyper-V Replica maintains an asynchronous copy of a virtual machine on another Hyper-V host.","Replication happens over the network, so it does not require shared storage between the two hosts.","It is a disaster-recovery mechanism, and the replica can be started through a failover operation when needed."],"whyOthers":["","Hyper-V Replica is asynchronous and specific to virtual machines; it does not synchronously replicate every file share.","It does not perform DNS load balancing.","It has nothing to do with Group Policy inheritance."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Replication can be over Kerberos or certificate-based authentication, and the replica host must be configured to accept replication."},
{"id":"az802-q-121","domain":"Manage virtual machines","text":"Which Hyper-V Replica operation validates that a replica can start without affecting production?","options":["Planned failover","Reverse replication only","Live migration","Test failover"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"عملیات Test failover یک ماشین مجازی آزمایشی موقت از روی نسخه کپی ایجاد می‌کند تا بدون ایجاد وقفه در بار کاری اصلی، عملیات اعتبارسنجی انجام شود.","en":"Test failover creates a temporary test VM from the replica for validation without interrupting the primary workload.","de":"Die richtige Antwort ist „Test failover“; sie passt zum Bereich Manage virtual machines und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام عملیات Hyper-V Replica تأیید می‌کند که یک نسخه کپی (replica) می‌تواند بدون تأثیرگذاری بر محیط عملیاتی (production) اجرا شود؟","optionsFa":["Planned failover (جابه‌جایی برنامه‌ریزی‌شده)","فقط Reverse replication (همگام‌سازی معکوس)","Live migration (مهاجرت زنده)","Test failover (جابه‌جایی آزمایشی)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/replication-failover","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/replication-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure high availability and replication for virtual machines","objectiveId":"vm-ha-replication","topic":"Hyper-V Replica","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/replication-failover","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/replication-overview"],"keyPoints":["A test failover creates a temporary test virtual machine from the replica so the recovery plan can be validated.","It does not interrupt the primary virtual machine, so it can be run as a recovery drill.","The test virtual machine is isolated from the production network so it does not interfere with live services."],"whyOthers":["A planned failover is an orderly move of production to the replica, which does affect the primary.","Reverse replication changes the direction of replication after a failover and is not a validation step.","Live migration moves a running virtual machine between hosts and is unrelated to replica validation.",""],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. A test failover should be cleaned up afterwards so the replica continues to receive changes from the primary."},
{"id":"az802-q-122","domain":"Manage virtual machines","text":"Which operation is appropriate when the primary VM is healthy and you want an orderly move to the replica?","options":["Delete replica","Emergency restore only","Planned failover","Test failover"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"عملیات Planned failover تغییرات باقی‌مانده را همگام‌سازی کرده و ماشین مجازی اصلی را به شیوه‌ای منظم خاموش می‌کند.","en":"Planned failover synchronizes remaining changes and shuts down the primary in an orderly way.","de":"Die richtige Antwort ist „Planned failover“; sie passt zum Bereich Manage virtual machines und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"زمانی که ماشین مجازی اصلی سالم است و می‌خواهید انتقالی منظم به نسخه کپی (replica) انجام دهید، کدام عملیات مناسب است؟","optionsFa":["حذف نسخه کپی","فقط بازیابی اضطراری","Planned failover (جابه‌جایی برنامه‌ریزی‌شده)","Test failover (جابه‌جایی آزمایشی)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/replication-failover","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/replication-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure high availability and replication for virtual machines","objectiveId":"vm-ha-replication","topic":"Hyper-V Replica","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/replication-failover","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/replication-overview"],"keyPoints":["A planned failover synchronises the remaining changes and shuts down the primary virtual machine in an orderly way.","It is used when the primary is still healthy, for example before planned maintenance.","After the failover, replication can be reversed so the original host becomes the replica."],"whyOthers":["Deleting the replica discards the recovery copy rather than failing over to it.","An emergency restore is used when the primary is lost, not when it is healthy.","","A test failover validates the replica without moving production."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. A planned failover is the cleanest option because no replication data is lost, and it can be performed from the primary host."},
{"id":"az802-q-123","domain":"Manage virtual machines","text":"What is live migration designed to do?","options":["Move a DNS zone","Move a running VM between compatible hosts with minimal downtime","Restore a deleted AD object","Convert a VHDX to an ISO"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"قابلیت Live Migration امکان انجام عملیات نگهداری و توزیع بار (Load Balancing) را در حالی که ماشین مجازی همچنان در حال اجراست، فراهم می‌کند.","en":"Live migration supports maintenance and load balancing while keeping the VM running.","de":"Die richtige Antwort ist „Move a running VM between compatible hosts with minimal downtime“; sie passt zum Bereich Manage virtual machines und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"هدف از طراحی قابلیت Live Migration (مهاجرت زنده) چیست؟","optionsFa":["انتقال یک ناحیه (Zone) در DNS","انتقال یک ماشین مجازی (VM) در حال اجرا بین میزبان‌های (Host) سازگار با حداقل زمان توقف (Downtime)","بازیابی یک شیء حذف‌شده در Active Directory","تبدیل فایل VHDX به ISO"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/manage/live-migration-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure high availability and replication for virtual machines","objectiveId":"vm-ha-replication","topic":"Live migration","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/manage/live-migration-overview"],"keyPoints":["Live migration moves a running virtual machine from one host to another with minimal downtime.","It is used for host maintenance and load balancing without stopping the workload.","It requires compatible hosts and accessible storage or live migration without shared storage."],"whyOthers":["Moving a DNS zone is a DNS operation and is not live migration.","","Restoring a deleted AD object is a directory recovery operation.","Converting a VHDX to an ISO changes a disk format and is not a migration."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Live migration can use shared storage or storage migration, and the source and destination hosts must satisfy the processor and version compatibility requirements."},
{"id":"az802-q-124","domain":"Manage virtual machines","text":"What is a prerequisite for highly available Hyper-V VMs in a failover cluster?","options":["The VM must be configured as a clustered role and use accessible storage or storage abstraction","The VM must use a private switch only","The cluster must have one node","Checkpoints must be permanent"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"گره‌های کلاستر نیازمند مالکیت و دسترسی هماهنگ به پیکربندی و دیسک‌های مجازی ماشین مجازی هستند.","en":"Cluster nodes need coordinated ownership and access to the VM’s configuration and virtual disks.","de":"Die richtige Antwort ist „The VM must be configured as a clustered role and use accessible storage or storage abstraction“; sie passt zum Bereich Manage virtual machines und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"پیش‌نیاز داشتن ماشین‌های مجازی Hyper-V با قابلیت دسترسی بالا (Highly Available) در یک کلاستر Failover چیست؟","optionsFa":["ماشین مجازی باید به عنوان یک نقش کلاستری (Clustered Role) پیکربندی شده و از فضای ذخیره‌سازی قابل‌دسترسی یا انتزاع فضای ذخیره‌سازی (Storage Abstraction) استفاده کند.","ماشین مجازی باید صرفاً از یک سوئیچ خصوصی (Private Switch) استفاده کند.","کلاستر باید تنها یک گره (Node) داشته باشد.","نقاط بازگشت (Checkpointها) باید دائمی باشند."],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/manage/live-migration-overview","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/features-terminology"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure high availability and replication for virtual machines","objectiveId":"vm-ha-replication","topic":"Failover clustering","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/manage/live-migration-overview","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/features-terminology"],"keyPoints":["For a virtual machine to be highly available, it must be configured as a clustered role in the failover cluster.","The cluster nodes must have coordinated access to the virtual machine's configuration and its virtual disks, either through shared storage or a storage abstraction.","A cluster requires more than one node before it provides availability."],"whyOthers":["","A private switch restricts connectivity and is not an availability requirement.","A single-node cluster provides no failover capability.","Checkpoints are not required to be permanent, and long-lived checkpoints are discouraged."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. The Failover Clustering feature and the Hyper-V role are both required, and shared storage is often provided by a CSV (cluster shared volume)."},
{"id":"az802-q-125","domain":"Manage virtual machines","text":"Which Azure VM feature helps distribute instances across separate fault and update domains?","options":["Azure File Sync","DNSSEC","Azure Policy initiative only","Availability set"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"مجموعه‌های در دسترس‌پذیری (Availability sets)، ماشین‌های مجازی را در دامنه‌های خطا (fault domains) و دامنه‌های به‌روزرسانی (update domains) در ساختار یک مرکز داده توزیع می‌کنند.","en":"Availability sets place VMs across fault and update domains within a datacenter construct.","de":"Die richtige Antwort ist „Availability set“; sie passt zum Bereich Manage virtual machines und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام ویژگی ماشین مجازی Azure به توزیع نمونه‌ها (Instances) در دامنه‌های مجزای خطا (Fault Domains) و به‌روزرسانی (Update Domains) کمک می‌کند؟","optionsFa":["Azure File Sync","DNSSEC","فقط Azure Policy initiative","Availability set"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/virtual-machines/availability-set-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage virtual machines in Azure","objectiveId":"vm-azure","topic":"Azure availability","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/virtual-machines/availability-set-overview"],"keyPoints":["An availability set distributes virtual machines across fault domains and update domains within an Azure datacenter construct.","Fault domains separate machines onto different physical hardware so a hardware failure does not take all of them down.","Update domains allow the platform to patch hosts in stages rather than rebooting every machine at once."],"whyOthers":["Azure File Sync caches file shares and does not distribute virtual machines.","DNSSEC signs DNS data and is unrelated to virtual machine placement.","An Azure Policy initiative groups policy definitions and does not affect fault or update domains.",""],"requirements":"Applies to Azure virtual machines. An availability set is scoped to a single datacenter within a region, so it protects against hardware faults but not against a datacenter-level outage."},
{"id":"az802-q-126","domain":"Manage virtual machines","text":"When are availability zones preferable to an availability set?","options":["When no network exists","When only local testing is needed","When protection across physically separate datacenter zones in a region is required","When all VMs must share one host"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"مناطق (Zones) نسبت به مجموعه در دسترس‌پذیری، جداسازی قوی‌تری را در سطح مرکز داده فراهم می‌کنند.","en":"Zones provide stronger datacenter-level separation than an availability set.","de":"Die richtige Antwort ist „When protection across physically separate datacenter zones in a region is required“; sie passt zum Bereich Manage virtual machines und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"چه زمانی مناطق در دسترس‌پذیری (Availability zones) نسبت به مجموعه در دسترس‌پذیری (Availability set) ارجحیت دارند؟","optionsFa":["زمانی که شبکه‌ای وجود ندارد","زمانی که تنها به تست محلی نیاز است","زمانی که به حفاظت در میان مناطق مرکز داده که از نظر فیزیکی در یک ناحیه (Region) جدا هستند، نیاز است","زمانی که همه ماشین‌های مجازی باید از یک میزبان (Host) مشترک استفاده کنند"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/reliability/availability-zones-overview","https://learn.microsoft.com/en-us/azure/virtual-machines/availability-set-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage virtual machines in Azure","objectiveId":"vm-azure","topic":"Azure availability","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/reliability/availability-zones-overview","https://learn.microsoft.com/en-us/azure/virtual-machines/availability-set-overview"],"keyPoints":["Availability zones are physically separate datacenters within a region, each with independent power, cooling, and networking.","Placing virtual machines in different zones protects against a whole datacenter failing.","Zones therefore provide stronger separation than an availability set, which is confined to one datacenter."],"whyOthers":["Zones are used when networking exists; the absence of a network is not a reason to choose them.","Local testing does not need zone-level separation.","","Sharing one host is the opposite of what zones provide."],"requirements":"Applies to Azure regions that support availability zones. Not every region or virtual machine size supports zones, so the region and SKU must be checked before relying on them."},
{"id":"az802-q-127","domain":"Manage virtual machines","text":"What is the usual first scaling action when an Azure VM is CPU-constrained and its workload can use more resources?","options":["Disable monitoring","Resize the VM to a suitable larger SKU","Change the DNS TTL","Delete the OS disk"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"تغییر اندازه ظرفیت محاسباتی اختصاص داده شده را تغییر می دهد. انتخاب باید در دسترس بودن، هزینه و نیازهای حجم کار را نیز در نظر بگیرد.","en":"Resizing changes the allocated compute capacity; the choice should also consider availability, cost, and workload requirements.","de":"Die richtige Antwort ist „Resize the VM to a suitable larger SKU“; sie passt zum Bereich Manage virtual machines und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"وقتی یک ماشین مجازی Azure محدود به CPU است و حجم کاری آن می تواند از منابع بیشتری استفاده کند، اولین اقدام معمول مقیاس بندی چیست؟","optionsFa":["نظارت را غیرفعال کنید","تغییر اندازه ماشین مجازی به یک SKU بزرگتر مناسب","DNS TTL را تغییر دهید","دیسک سیستم عامل را حذف کنید"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/virtual-machines/resize-vm"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage virtual machines in Azure","objectiveId":"vm-azure","topic":"Azure VM scaling","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/azure/virtual-machines/resize-vm"],"keyPoints":["Resizing changes the compute capacity allocated to a virtual machine, which is the direct response to a CPU constraint.","The new SKU must be supported by the host hardware and available in the region and zone.","The resize decision must also consider availability, memory, networking limits, and cost, not CPU alone."],"whyOthers":["Disabling monitoring removes the data needed to make a good sizing decision.","","Changing the DNS TTL affects name caching and does not add compute capacity.","Deleting the OS disk destroys the virtual machine."],"requirements":"Applies to Azure virtual machines. Depending on the change, resizing may require a restart, and some SKU families can only be reached by deallocating the virtual machine first."},
{"id":"az802-q-128","domain":"Manage virtual machines","text":"What is a virtual machine scale set designed for?","options":["Managing a group of similar VMs that can scale out or in","Storing DNS records","Hosting a single AD database","Replacing a file server"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"مجموعه های مقیاس، استقرار مداوم و مقیاس افقی نمونه های VM را خودکار می کند.","en":"Scale sets automate consistent deployment and horizontal scaling of VM instances.","de":"Die richtige Antwort ist „Managing a group of similar VMs that can scale out or in“; sie passt zum Bereich Manage virtual machines und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"مجموعه ترازو ماشین مجازی برای چه طراحی شده است؟","optionsFa":["مدیریت گروهی از ماشین های مجازی مشابه که می توانند کوچک یا کوچک شوند","ذخیره سوابق DNS","میزبانی یک پایگاه داده واحد AD","جایگزینی سرور فایل"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/virtual-machine-scale-sets/overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage virtual machines in Azure","objectiveId":"vm-azure","topic":"Virtual machine scale sets","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/virtual-machine-scale-sets/overview"],"keyPoints":["A virtual machine scale set manages a group of similar virtual machines that can scale out and in.","All instances are created from the same configuration, which keeps them consistent.","It can scale manually or automatically based on metrics or a schedule."],"whyOthers":["","DNS records are stored in Azure DNS or an on-premises DNS zone, not in a scale set.","A scale set is not used to host a single AD database instance.","It is not a replacement for a file server."],"requirements":"Applies to Azure virtual machine scale sets. Flexible orchestration gives more control over instance management, while uniform orchestration keeps all instances identical."},
{"id":"az802-q-129","domain":"Manage virtual machines","text":"Which Azure feature limits management access to a VM to a short authorized period?","options":["Azure Storage lifecycle","Availability set","Private DNS zone only","Just-in-time VM access"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"JIT پورت های مدیریتی انتخاب شده را به جای اینکه به طور مداوم در معرض دید قرار دهد، برای یک پنجره زمانی تایید شده باز می کند.","en":"JIT opens selected management ports for an approved time window instead of leaving them continuously exposed.","de":"Die richtige Antwort ist „Just-in-time VM access“; sie passt zum Bereich Manage virtual machines und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام ویژگی Azure دسترسی مدیریت به VM را به یک دوره مجاز کوتاه محدود می کند؟","optionsFa":["چرخه عمر Azure Storage","مجموعه موجودی","فقط منطقه DNS خصوصی","دسترسی به موقع به VM"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/defender-for-cloud/just-in-time-access-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage virtual machines in Azure","objectiveId":"vm-azure","topic":"Just-in-time access","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/defender-for-cloud/just-in-time-access-overview"],"keyPoints":["Just-in-time (JIT) virtual machine access opens selected management ports only for an approved time window.","Outside that window the ports stay closed, so the exposure to scanning and brute-force attempts is greatly reduced.","Requests are subject to role-based approvals and are recorded for auditing."],"whyOthers":["Azure Storage lifecycle management moves or deletes blobs and does not control access ports.","An availability set distributes virtual machines across fault and update domains and does not limit management access.","A private DNS zone resolves names inside a virtual network and does not open or close management ports.",""],"requirements":"Applies to Microsoft Defender for Cloud. JIT access is configured with a policy that lists the allowed source addresses and the maximum request duration per port."},
{"id":"az802-q-130","domain":"Manage virtual machines","text":"A Windows VM cannot access an Azure data disk after a resize operation. What should be checked first?","options":["Group Policy loopback","DNSSEC signing","Disk attachment, OS recognition, initialization, and online state","The forest functional level"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"پیوست Azure و حالت دیسک مهمان باید قبل از استفاده از یک حجم، صحیح باشند.","en":"Azure attachment and guest disk state must both be correct before a volume is usable.","de":"Die richtige Antwort ist „Disk attachment, OS recognition, initialization, and online state“; sie passt zum Bereich Manage virtual machines und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"یک Windows VM نمی تواند پس از عملیات تغییر اندازه به دیسک داده Azure دسترسی پیدا کند. ابتدا چه چیزی را باید بررسی کرد؟","optionsFa":["Loopback Group Policy","امضای DNSSEC","پیوست دیسک، تشخیص سیستم عامل، مقداردهی اولیه و وضعیت آنلاین","سطح عملکردی جنگل"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/virtual-machines/windows/attach-managed-disk-portal","https://learn.microsoft.com/en-us/azure/virtual-machines/managed-disks-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage virtual machines in Azure","objectiveId":"vm-azure","topic":"Azure data disks","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/azure/virtual-machines/windows/attach-managed-disk-portal","https://learn.microsoft.com/en-us/azure/virtual-machines/managed-disks-overview"],"keyPoints":["A data disk must first be attached to the virtual machine in Azure, and then recognised and initialised by the guest operating system.","In Windows the disk must be initialised, partitioned, formatted, and brought online before a drive letter appears.","If the disk is read-only or offline, or the attachment failed, the guest cannot use it regardless of guest configuration."],"whyOthers":["Group Policy loopback affects user policy on a computer and does not attach disks.","DNSSEC signing secures DNS answers and is unrelated to disk access.","","The forest functional level concerns Active Directory capabilities and does not affect Azure data disks."],"requirements":"Applies to Azure Windows virtual machines. A disk cannot be attached to two virtual machines at once as a data disk, and only the guest's own instance sees it as local storage."},
{"id":"az802-q-131","domain":"Manage virtual machines","text":"Which Azure managed disk option is intended for lower-latency, high-performance workloads?","options":["A DNS cache","A disk SKU designed for the workload’s required IOPS and latency, such as Premium SSD or Ultra Disk where supported","A basic text file","A DHCP lease"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"انتخاب دیسک باید با الزامات عملکرد، در دسترس بودن و هزینه مطابقت داشته باشد، نه اینکه صرفاً به طور پیش‌فرض یک سطح (Tier) خاص انتخاب شود.","en":"Disk selection should match performance, availability, and cost requirements rather than defaulting to one tier.","de":"Die richtige Antwort ist „A disk SKU designed for the workload’s required IOPS and latency, such as Premium SSD or Ultra Disk where supported“; sie passt zum Bereich Manage virtual machines und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام گزینه دیسک مدیریت‌شده (Managed Disk) در Azure برای بارهای کاری با تأخیر (Latency) کمتر و عملکرد بالا در نظر گرفته شده است؟","optionsFa":["یک کش DNS","یک SKU دیسک که متناسب با میزان IOPS و تأخیر مورد نیاز بار کاری طراحی شده باشد، مانند Premium SSD یا Ultra Disk (در صورت پشتیبانی)","یک فایل متنی ساده","یک اجاره‌نامه (lease) DHCP"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/virtual-machines/disks-types","https://learn.microsoft.com/en-us/azure/virtual-machines/managed-disks-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage virtual machines in Azure","objectiveId":"vm-azure","topic":"Azure managed disks","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/virtual-machines/disks-types","https://learn.microsoft.com/en-us/azure/virtual-machines/managed-disks-overview"],"keyPoints":["Azure offers several managed disk types, including Standard HDD, Standard SSD, Premium SSD, and Ultra Disk, each with a different performance and cost profile.","Lower-latency, higher-performance workloads are matched to Premium SSD or Ultra Disk where the region, virtual machine size, and availability requirements support it.","Choosing a disk type should follow the workload's IOPS, throughput, and latency needs rather than a default."],"whyOthers":["A DNS cache is a name-resolution feature and not a disk option.","","A basic text file is data, not a storage SKU.","A DHCP lease is an IP address assignment and is unrelated to disk selection."],"requirements":"Applies to Azure managed disks. Not every disk type is available in every region or with every virtual machine size, and Ultra Disk support depends on the virtual machine family and the zone."},
{"id":"az802-q-132","domain":"Manage virtual machines","text":"What does Azure Bastion require for browser-based access to a VM?","options":["A Bastion resource connected to the VM’s virtual network and appropriate subnet configuration","An internet-facing RDP port on every VM","A public DNS root","A local tape drive"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"سرویس Bastion به عنوان مسیر دسترسی مدیریت‌شده از طریق شبکه مجازی عمل می‌کند.","en":"Bastion acts as the managed access path through the virtual network.","de":"Die richtige Antwort ist „A Bastion resource connected to the VM’s virtual network and appropriate subnet configuration“; sie passt zum Bereich Manage virtual machines und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"سرویس Azure Bastion برای دسترسی مبتنی بر مرورگر به یک ماشین مجازی (VM) به چه چیزی نیاز دارد؟","optionsFa":["یک منبع (Resource) Bastion متصل به شبکه مجازی ماشین مجازی و پیکربندی مناسب زیرشبکه (Subnet)","یک پورت RDP رو به اینترنت روی هر ماشین مجازی","یک ریشه (Root) DNS عمومی","یک درایو نوار (Tape drive) محلی"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/bastion/bastion-overview","https://learn.microsoft.com/en-us/azure/bastion/bastion-connect-vm-rdp-windows"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage virtual machines in Azure","objectiveId":"vm-azure","topic":"Azure Bastion","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/bastion/bastion-overview","https://learn.microsoft.com/en-us/azure/bastion/bastion-connect-vm-rdp-windows"],"keyPoints":["Azure Bastion requires a Bastion resource deployed into the virtual network that contains the target virtual machines.","It uses a dedicated subnet named AzureBastionSubnet, and no public IP address is needed on the virtual machines themselves.","It provides browser-based RDP and SSH over TLS through the Azure portal."],"whyOthers":["","An internet-facing RDP port on every virtual machine is the exposure Bastion is designed to eliminate.","A public DNS root is not required for Bastion.","A local tape drive is a backup device and is unrelated."],"requirements":"Applies to Azure Bastion. The dedicated subnet must be correctly sized, and Bastion access can be granted with role-based access control instead of distributing local credentials."},
{"id":"az802-q-133","domain":"Manage virtual machines","text":"Which Hyper-V network feature can reduce packet-processing overhead for supported workloads?","options":["Loopback processing","DNS scavenging","FSRM screening","SR-IOV"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"فناوری مجازی‌سازی ورودی/خروجی تک‌ریشه (SR-IOV) به یک ماشین مجازی (VM) امکان می‌دهد تا از یک تابع مجازی روی آداپتور فیزیکی با سربار سوئیچینگ کمتر در میزبان (Host) استفاده کند.","en":"Single-root I/O virtualization can allow a VM to use a virtual function on a physical adapter with less host switching overhead.","de":"Die richtige Antwort ist „SR-IOV“; sie passt zum Bereich Manage virtual machines und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام ویژگی شبکه Hyper-V می‌تواند سربار پردازش بسته (Packet-processing overhead) را برای بارهای کاری پشتیبانی‌شده کاهش دهد؟","optionsFa":["پردازش Loopback","پاک‌سازی (Scavenging) در DNS","فیلترینگ (Screening) در FSRM","SR-IOV"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/technologies/hpn/hpn-software-hardware-features","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/plan/plan-hyper-v-networking-in-windows-server"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure virtual machine networking","objectiveId":"vm-networking","topic":"SR-IOV","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/technologies/hpn/hpn-software-hardware-features","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/plan/plan-hyper-v-networking-in-windows-server"],"keyPoints":["Single-Root I/O Virtualization (SR-IOV) lets a virtual machine use a virtual function on a physical adapter directly.","Because traffic bypasses part of the host's software switching path, packet-processing overhead is reduced.","It requires an SR-IOV-capable adapter and support on the host and in the guest."],"whyOthers":["Loopback processing is a Group Policy feature and is unrelated to network performance.","DNS scavenging removes stale DNS records and does not affect packet processing.","FSRM screening restricts file types on a file server and is unrelated to network adapters.",""],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. SR-IOV must be enabled on the virtual switch and the adapter must support it, and some advanced features are unavailable when SR-IOV is in use."},
{"id":"az802-q-134","domain":"Implement and manage on-premises and hybrid networking","text":"A branch server publishes only its IPv4 address and clients must resolve it by name. Which DNS record type provides that mapping?","options":["MX","PTR","A","AAAA"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"رکورد A یک نام را به آدرس IPv4 نگاشت می‌کند؛ رکورد AAAA برای IPv6 استفاده می‌شود.","en":"An A record maps a name to an IPv4 address; AAAA is used for IPv6.","de":"Die richtige Antwort ist „A“; sie passt zum Bereich Implement and manage on-premises and hybrid networking und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام رکورد DNS نام میزبان را به یک آدرس IPv4 نگاشت می‌کند؟","optionsFa":["MX","PTR","A","AAAA"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/dns/dns-architecture","https://learn.microsoft.com/en-us/windows-server/networking/dns/zone-types"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Implement and manage DNS for Windows Server","objectiveId":"net-dns","topic":"DNS record types","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/dns/dns-architecture","https://learn.microsoft.com/en-us/windows-server/networking/dns/zone-types"],"keyPoints":["An A record maps a host name to an IPv4 address.","It is the most common forward-lookup record, and clients and DHCP register it dynamically in internal zones.","A host that also has IPv6 publishes a second record type alongside the A record rather than replacing it."],"whyOthers":["An MX record identifies the mail servers that accept email for a domain.","A PTR record performs reverse lookup, mapping an address back to a name.","","An AAAA record maps a name to an IPv6 address, not an IPv4 address."],"requirements":"Applies to the DNS Server role on Windows Server 2025, 2022, 2019, and 2016. A records can be entered manually or registered dynamically by clients and by DHCP."},
{"id":"az802-q-135","domain":"Implement and manage on-premises and hybrid networking","text":"A dual-stack server publishes both an IPv4 and an IPv6 address. Which record type carries the IPv6 address?","options":["SRV","PTR","AAAA","CNAME"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"رکوردهای AAAA حاوی آدرس‌های IPv6 هستند.","en":"AAAA records contain IPv6 addresses.","de":"Die richtige Antwort ist „AAAA“; sie passt zum Bereich Implement and manage on-premises and hybrid networking und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام رکورد DNS نام میزبان را به یک آدرس IPv6 نگاشت می‌کند؟","optionsFa":["SRV","PTR","AAAA","CNAME"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/dns/dns-architecture","https://learn.microsoft.com/en-us/windows-server/networking/dns/zone-types"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Implement and manage DNS for Windows Server","objectiveId":"net-dns","topic":"DNS record types","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/dns/dns-architecture","https://learn.microsoft.com/en-us/windows-server/networking/dns/zone-types"],"keyPoints":["An AAAA record maps a host name to an IPv6 address.","The type name is conventionally read as quad-A, reflecting the four 32-bit groups of a 128-bit IPv6 address.","Dual-stack hosts normally publish an A record and an AAAA record side by side so clients of either family can resolve the name."],"whyOthers":["An SRV record identifies a service host and port, such as LDAP or Kerberos, and carries no address.","A PTR record performs reverse lookup from an address to a name and cannot publish a forward mapping.","","A CNAME record aliases one name to another name; it never carries an IPv6 address directly."],"requirements":"Applies to the DNS Server role on Windows Server 2025, 2022, 2019, and 2016. Windows clients register AAAA records for their IPv6 addresses when IPv6 is enabled and dynamic update is permitted."},
{"id":"az802-q-136","domain":"Implement and manage on-premises and hybrid networking","text":"Which DNS record supports reverse lookup from an IPv4 address to a name?","options":["PTR","A","NS","TXT"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"رکوردهای PTR در زون‌های جستجوی معکوس قرار دارند و آدرس‌ها را به نام‌ها نگاشت (map) می‌کنند.","en":"PTR records reside in reverse lookup zones and map addresses back to names.","de":"Die richtige Antwort ist „PTR“; sie passt zum Bereich Implement and manage on-premises and hybrid networking und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام رکورد DNS از جستجوی معکوس (reverse lookup) از یک آدرس IPv4 به یک نام پشتیبانی می‌کند؟","optionsFa":["PTR","A","NS","TXT"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/dns/dns-architecture","https://learn.microsoft.com/en-us/windows-server/networking/dns/manage-dns-zones"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Implement and manage DNS for Windows Server","objectiveId":"net-dns","topic":"DNS record types","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/dns/dns-architecture","https://learn.microsoft.com/en-us/windows-server/networking/dns/manage-dns-zones"],"keyPoints":["A PTR record maps an IP address back to a host name and lives in a reverse lookup zone.","Reverse lookup zones use the in-addr.arpa namespace for IPv4 and ip6.arpa for IPv6.","PTR records matter for tools and services that log or verify names from addresses."],"whyOthers":["","An A record is a forward-lookup record that maps a name to an IPv4 address, not the reverse.","An NS record lists the authoritative name servers for a zone.","A TXT record carries arbitrary text such as sender policy information, not an address-to-name mapping."],"requirements":"Applies to the DNS Server role on Windows Server 2025, 2022, 2019, and 2016. A reverse lookup zone must exist before PTR records can be created, and clients register them dynamically when the zone permits it."},
{"id":"az802-q-137","domain":"Implement and manage on-premises and hybrid networking","text":"Which DNS record identifies a service’s host and port, such as LDAP or Kerberos?","options":["PTR","SOA only","CNAME only","SRV"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"سرویس AD DS رکوردهای SRV را منتشر می‌کند تا کلاینت‌ها بتوانند سرویس‌هایی مانند LDAP و Kerberos را پیدا کنند.","en":"AD DS publishes SRV records so clients can locate services such as LDAP and Kerberos.","de":"Die richtige Antwort ist „SRV“; sie passt zum Bereich Implement and manage on-premises and hybrid networking und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام رکورد DNS میزبان (host) و پورت یک سرویس، مانند LDAP یا Kerberos را مشخص می‌کند؟","optionsFa":["PTR","فقط SOA","فقط CNAME","SRV"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/dns-and-ad-ds","https://learn.microsoft.com/en-us/windows-server/networking/dns/dns-architecture"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Implement and manage DNS for Windows Server","objectiveId":"net-dns","topic":"DNS record types","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/dns-and-ad-ds","https://learn.microsoft.com/en-us/windows-server/networking/dns/dns-architecture"],"keyPoints":["An SRV record publishes the host and port of a service so clients can locate it.","AD DS publishes SRV records under _msdcs so clients can find LDAP and Kerberos services.","The record also carries a priority and weight, which allows clients to prefer one server over another."],"whyOthers":["A PTR record maps an address to a name and does not name a service or port.","An SOA record describes the zone's authority and serial number but does not locate a service.","A CNAME record aliases one name to another and does not carry a port or service definition.",""],"commandPath":[{"label":"Query the LDAP service records for the domain","command":"nslookup -type=SRV _ldap._tcp.dc._msdcs.contoso.com"}],"requirements":"Applies to DNS Server on Windows Server 2025, 2022, 2019, and 2016. AD DS service records are registered automatically by the Netlogon service on each domain controller."},
{"id":"az802-q-138","domain":"Implement and manage on-premises and hybrid networking","text":"What is an AD-integrated DNS zone?","options":["A zone that cannot support secure updates","A zone used only for public internet names","A zone stored in AD DS and replicated through directory replication","A zone stored only in a text file on one server"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"زون‌های یکپارچه با AD از قابلیت همانندسازی AD استفاده می‌کنند و می‌توانند از به‌روزرسانی‌های پویای امن (secure dynamic updates) پشتیبانی کنند.","en":"AD-integrated zones use AD replication and can support secure dynamic updates.","de":"Die richtige Antwort ist „A zone stored in AD DS and replicated through directory replication“; sie passt zum Bereich Implement and manage on-premises and hybrid networking und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"زون DNS یکپارچه با AD (AD-integrated DNS zone) چیست؟","optionsFa":["زونی که نمی‌تواند از به‌روزرسانی‌های امن پشتیبانی کند","زونی که فقط برای نام‌های اینترنت عمومی استفاده می‌شود","زونی که در AD DS ذخیره شده و از طریق مکانیزم همانندسازی دایرکتوری (directory replication) تکثیر می‌شود","زونی که فقط در یک فایل متنی روی یک سرور ذخیره شده است"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/dns/zone-types","https://learn.microsoft.com/en-us/windows-server/networking/dns/manage-dns-zones"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Implement and manage DNS for Windows Server","objectiveId":"net-dns","topic":"DNS zones","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/dns/zone-types","https://learn.microsoft.com/en-us/windows-server/networking/dns/manage-dns-zones"],"keyPoints":["An AD-integrated zone stores its records in Active Directory and replicates them through directory replication rather than zone transfers.","Because the data is in AD DS, the zone benefits from AD security and can support secure dynamic updates.","Integration is available only on domain controllers that also run DNS."],"whyOthers":["AD-integrated zones do support secure dynamic updates, so the opposite statement is incorrect.","The zone type concerns where the records are stored, not whether the names are public or internal.","","Storing the zone only in a text file on one server describes a standard primary zone, not an AD-integrated zone."],"requirements":"Applies to DNS Server on Windows Server 2025, 2022, 2019, and 2016. An AD-integrated zone can be replicated to all DNS servers in the domain, the forest, or a chosen application partition."},
{"id":"az802-q-139","domain":"Implement and manage on-premises and hybrid networking","text":"Which zone type is commonly used to delegate a DNS namespace to another DNS server?","options":["DHCP zone","Stub zone","Reverse-only zone","Cache zone"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"یک ناحیه Stub حاوی رکوردهایی است که سرورهای نام معتبر (Authoritative Name Servers) را برای فضای نام واگذار شده، مشخص می‌کنند.","en":"A stub zone contains records that identify authoritative name servers for the delegated namespace.","de":"Die richtige Antwort ist „Stub zone“; sie passt zum Bereich Implement and manage on-premises and hybrid networking und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام نوع Zone (ناحیه) معمولاً برای واگذاری (Delegate کردن) یک فضای نام DNS به یک سرور DNS دیگر استفاده می‌شود؟","optionsFa":["ناحیه DHCP","ناحیه Stub","ناحیه فقط معکوس (Reverse-only)","ناحیه Cache"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/dns/zone-types","https://learn.microsoft.com/en-us/windows-server/networking/dns/manage-dns-zones"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Implement and manage DNS for Windows Server","objectiveId":"net-dns","topic":"DNS zones","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/dns/zone-types","https://learn.microsoft.com/en-us/windows-server/networking/dns/manage-dns-zones"],"keyPoints":["A stub zone holds only the records needed to identify the authoritative name servers for another zone.","It is used to keep a server's knowledge of a delegated namespace current without hosting the whole zone.","An AD-integrated stub zone replicates through AD DS so all DNS servers share the same delegation information."],"whyOthers":["There is no DNS zone type named DHCP zone; DHCP allocates addresses and is a separate service.","","A reverse-only zone is not a standard zone type; reverse lookup is a purpose, and a reverse zone is still primary, secondary, stub, or AD-integrated.","A cache is not a zone type; a caching-only server has no zone of its own."],"requirements":"Applies to DNS Server on Windows Server 2025, 2022, 2019, and 2016. A stub zone needs at least one authoritative server for the target zone to be specified so it can be populated."},
{"id":"az802-q-140","domain":"Implement and manage on-premises and hybrid networking","text":"What is the purpose of a DNS conditional forwarder?","options":["Forward queries for a specific namespace to designated DNS servers","Forward every query to the root only","Allocate IP addresses","Replicate SYSVOL"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"ارسال مشروط (Conditional Forwarding) برای فضاهای نام ترکیبی (Hybrid) یا فضاهای نام متعلق به شرکا که دارای Resolverهای معتبر (Authoritative Resolvers) شناخته‌شده هستند، مفید است.","en":"Conditional forwarding is useful for hybrid or partner namespaces with known authoritative resolvers.","de":"Die richtige Antwort ist „Forward queries for a specific namespace to designated DNS servers“; sie passt zum Bereich Implement and manage on-premises and hybrid networking und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"هدف از Conditional Forwarder (ارسال‌کننده مشروط) در DNS چیست؟","optionsFa":["ارسال درخواست‌ها (Queryها) برای یک فضای نام خاص به سرورهای DNS تعیین‌شده","ارسال تمام درخواست‌ها فقط به سرور ریشه (Root)","تخصیص آدرس‌های IP","تکثیر (Replicate) کردن SYSVOL"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/dns/dns-top","https://learn.microsoft.com/en-us/windows-server/networking/dns/zone-types"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Implement and manage DNS for Windows Server","objectiveId":"net-dns","topic":"DNS resolution","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/dns/dns-top","https://learn.microsoft.com/en-us/windows-server/networking/dns/zone-types"],"keyPoints":["A conditional forwarder sends queries for one specific namespace to designated DNS servers.","It is used for hybrid or partner namespaces where the authoritative resolvers are known in advance.","It is more precise than a general forwarder, which handles all unresolved queries."],"whyOthers":["","Forwarding every query to the root describes normal recursion, not a conditional forwarder.","Allocating IP addresses is a DHCP function, not DNS forwarding.","Replicating SYSVOL is a directory replication task and is unrelated to DNS forwarding."],"commandPath":[{"label":"Create a conditional forwarder for a partner domain","command":"Add-DnsServerConditionalForwarderZone -Name 'fabrikam.com' -MasterServers 10.20.0.10,10.20.0.11"}],"requirements":"Applies to DNS Server on Windows Server 2025, 2022, 2019, and 2016. A conditional forwarder can be stored in AD DS so it is shared across DNS servers in the domain or forest."},
{"id":"az802-q-141","domain":"Implement and manage on-premises and hybrid networking","text":"What is a DNS forwarder?","options":["An AD group scope","A file-server quota","A DHCP reservation","A DNS server to which unresolved queries are sent"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"فورواردرها (Forwarders) به سرور DNS اجازه می‌دهند تا به‌جای انجام تمام عملیات بازگشتی (Recursion) توسط خود، به ریزالورهای (Resolver) بالادستی تکیه کند.","en":"Forwarders allow a DNS server to rely on upstream resolvers rather than performing all recursion itself.","de":"Die richtige Antwort ist „A DNS server to which unresolved queries are sent“; sie passt zum Bereich Implement and manage on-premises and hybrid networking und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"DNS Forwarder چیست؟","optionsFa":["محدوده (Scope) یک گروه در AD","سهمیه (Quota) فایل‌سرور","رزرو DHCP","سرور DNSای که درخواست‌های (Query) حل‌نشده به آن ارسال می‌شوند"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/dns/dns-top"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Implement and manage DNS for Windows Server","objectiveId":"net-dns","topic":"DNS resolution","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/dns/dns-top"],"keyPoints":["A forwarder is a DNS server to which a DNS server sends queries it cannot resolve itself.","Using a forwarder lets an internal DNS server rely on an upstream resolver instead of performing full recursion.","Forwarders are commonly used to reach the internet while keeping internal resolution local."],"whyOthers":["An AD group scope is a directory concept and is not a DNS resolver.","A file-server quota limits storage usage and is unrelated to DNS.","A DHCP reservation assigns a fixed address to a client and is not a DNS forwarder.",""],"requirements":"Applies to DNS Server on Windows Server 2025, 2022, 2019, and 2016. If forwarders are unavailable, the server can fall back to recursion depending on its configuration."},
{"id":"az802-q-142","domain":"Implement and manage on-premises and hybrid networking","text":"A domain client can resolve public names but cannot locate a domain controller. What should be checked first?","options":["Storage Spaces parity","Hyper-V checkpoints","Internal DNS configuration and AD SRV records","The user’s desktop wallpaper"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"کشف دامین کنترلر به تنظیمات صحیح DNS داخلی و رکوردهای سرویسِ منتشرشده بستگی دارد.","en":"Domain controller discovery depends on correct internal DNS and published service records.","de":"Die richtige Antwort ist „Internal DNS configuration and AD SRV records“; sie passt zum Bereich Implement and manage on-premises and hybrid networking und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"یک کلاینت دامین می‌تواند نام‌های عمومی را Resolve کند اما قادر به یافتن دامین کنترلر (Domain Controller) نیست. ابتدا چه چیزی باید بررسی شود؟","optionsFa":["وضعیت Parity در Storage Spaces","چک‌پوینت‌های Hyper-V","پیکربندی DNS داخلی و رکوردهای SRV در AD","تصویر پس‌زمینه دسکتاپ کاربر"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/dns-and-ad-ds","https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/nslookup"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Troubleshoot name resolution and network connectivity","objectiveId":"net-troubleshoot","topic":"DNS troubleshooting","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/dns-and-ad-ds","https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/nslookup"],"keyPoints":["Domain controller discovery depends on the client using DNS that hosts the AD namespace and its SRV records.","A client that can resolve public names is likely pointed at a public resolver, which cannot answer for the internal AD namespace.","The check is therefore the client's DNS server addresses plus whether the AD SRV records exist and resolve."],"whyOthers":["Storage Spaces parity is a storage configuration and has no bearing on directory discovery.","Hyper-V checkpoints capture virtual machine state and do not affect name resolution.","","The user's desktop wallpaper is a cosmetic setting and is irrelevant."],"commandPath":[{"label":"Confirm which DNS server the client uses","command":"Get-DnsClientServerAddress -AddressFamily IPv4"},{"label":"Verify the domain's SRV records resolve","command":"Resolve-DnsName -Type SRV _ldap._tcp.dc._msdcs.contoso.com"}],"requirements":"Applies to domain-joined Windows Server 2025, 2022, 2019, and 2016 and to clients. A common cause is a client whose DNS settings were changed to a public resolver, often by an incorrect DHCP option."},
{"id":"az802-q-143","domain":"Implement and manage on-premises and hybrid networking","text":"Which command clears the local DNS resolver cache?","options":["gpupdate /force","ipconfig /flushdns","ipconfig /release","netsh dhcp show"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"این دستور ورودی‌های کش‌شده‌ی Resolver را حذف می‌کند تا درخواست‌های بعدی مجدداً Resolve شوند.","en":"It removes cached resolver entries so subsequent queries are resolved again.","de":"Die richtige Antwort ist „ipconfig /flushdns“; sie passt zum Bereich Implement and manage on-premises and hybrid networking und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام دستور کش (Cache) محلی DNS Resolver را پاک می‌کند؟","optionsFa":["gpupdate /force","ipconfig /flushdns","ipconfig /release","netsh dhcp show"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/ipconfig","https://learn.microsoft.com/en-us/windows-server/networking/dns/dns-top"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Troubleshoot name resolution and network connectivity","objectiveId":"net-troubleshoot","topic":"DNS troubleshooting","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/ipconfig","https://learn.microsoft.com/en-us/windows-server/networking/dns/dns-top"],"keyPoints":["ipconfig /flushdns clears the local DNS resolver cache so later queries are resolved again.","It is used after a DNS change to make the client pick up the new answer rather than a cached one.","It affects only the local resolver cache, not the DNS server's own cache."],"whyOthers":["gpupdate /force refreshes Group Policy and does not clear the DNS cache.","","ipconfig /release gives up the DHCP lease rather than clearing the DNS cache.","netsh dhcp show displays DHCP configuration and does not clear the DNS cache."],"commandPath":[{"label":"Clear the local resolver cache","command":"ipconfig /flushdns"},{"label":"Confirm the cache is empty","command":"ipconfig /displaydns"}],"requirements":"Applies to Windows Server 2025, 2022, 2019, 2016 and to clients. The DNS Client service caches positive and negative answers, so a negative cache entry can also cause a stale failure."},
{"id":"az802-q-144","domain":"Implement and manage on-premises and hybrid networking","text":"Which command queries DNS records interactively?","options":["nslookup","diskpart","dcdiag /fix","route print only"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"دستور nslookup می‌تواند از یک سرور DNS خاص پرس‌وجو کرده و فرآیند حل (Resolution) رکوردها را بررسی کند.","en":"nslookup can query a selected DNS server and inspect record resolution.","de":"Die richtige Antwort ist „nslookup“; sie passt zum Bereich Implement and manage on-premises and hybrid networking und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام دستور برای پرس‌وجوی تعاملی (Interactive) رکوردهای DNS استفاده می‌شود؟","optionsFa":["nslookup","diskpart","dcdiag /fix","route print only"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/nslookup"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Troubleshoot name resolution and network connectivity","objectiveId":"net-troubleshoot","topic":"DNS troubleshooting","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/nslookup"],"keyPoints":["nslookup queries DNS interactively and can target a specific DNS server.","It can request a specific record type, which makes it useful for verifying A, SRV, and PTR records.","Interactive mode lets successive queries be run without re-entering the server."],"whyOthers":["","Diskpart manages disks and volumes and performs no DNS queries.","dcdiag /fix runs domain controller diagnostics and repair and is not an interactive DNS query tool.","route print displays the local routing table rather than querying DNS."],"commandPath":[{"label":"Query a specific DNS server interactively","command":"nslookup - 10.10.0.10"},{"label":"Query an SRV record from the command line","command":"nslookup -type=SRV _ldap._tcp.dc._msdcs.contoso.com"}],"requirements":"Applies to Windows Server 2025, 2022, 2019, 2016 and to clients. On servers without the optional nslookup feature, the equivalent is Resolve-DnsName."},
{"id":"az802-q-145","domain":"Implement and manage on-premises and hybrid networking","text":"What is DNS scavenging designed to remove?","options":["Active directory users","Encrypted disks","DHCP server certificates","Stale dynamic records"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"عملیات Scavenging رکوردهایی را که در بازه‌های زمانی تعیین‌شده برای عمر رکورد (Aging intervals) به‌روزرسانی نشده‌اند، پاک‌سازی می‌کند.","en":"Scavenging cleans records that have not refreshed within configured aging intervals.","de":"Die richtige Antwort ist „Stale dynamic records“; sie passt zum Bereich Implement and manage on-premises and hybrid networking und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"هدف از قابلیت DNS Scavenging (پاک‌سازی) حذف چه چیزی است؟","optionsFa":["کاربران Active Directory","دیسک‌های رمزنگاری‌شده","گواهی‌های سرور DHCP","رکوردهای دینامیک قدیمی (Stale)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/networking/troubleshoot-dns-scavenging-issues","https://learn.microsoft.com/en-us/troubleshoot/windows-server/networking/configure-dns-dynamic-updates-windows-server-2003"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Implement and manage DNS for Windows Server","objectiveId":"net-dns","topic":"DNS scavenging","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/networking/troubleshoot-dns-scavenging-issues","https://learn.microsoft.com/en-us/troubleshoot/windows-server/networking/configure-dns-dynamic-updates-windows-server-2003"],"keyPoints":["Scavenging removes stale dynamic records that have not refreshed within the configured aging intervals.","A record becomes stale through the combination of its timestamp, the no-refresh interval, and the refresh interval.","It keeps zones accurate when clients are retired or move and never refresh their old records."],"whyOthers":["Active Directory users are objects in the directory database and are not removed by DNS scavenging.","Encrypted disks are not affected by DNS scavenging.","DHCP server certificates are not managed by DNS scavenging.",""],"commandPath":[{"label":"Trigger scavenging immediately on a DNS server","command":"Start-DnsServerScavenging -ComputerName DNS01"}],"requirements":"Applies to DNS Server on Windows Server 2025, 2022, 2019, and 2016. Scavenging must be enabled on both the zone and the server, and the intervals must allow enough time before stale records are removed."},
{"id":"az802-q-146","domain":"Implement and manage on-premises and hybrid networking","text":"What is a major risk of enabling DNS scavenging without correct aging settings?","options":["DHCP stops leasing addresses","Kerberos changes to NTLM","Valid records may be removed","DNS becomes encrypted"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"برای جلوگیری از حذف سوابق فعال، قابلیت Scavenging باید در زون‌ها (zones) و سرورها فعال شده و زمان‌بندی آن به صورت هماهنگ تنظیم شود.","en":"Scavenging must be enabled and timed consistently on zones and servers to avoid deleting active records.","de":"Die richtige Antwort ist „Valid records may be removed“; sie passt zum Bereich Implement and manage on-premises and hybrid networking und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"فعال‌سازی قابلیت DNS Scavenging (پاک‌سازی سوابق قدیمی DNS) بدون تنظیمات صحیح مربوط به عمر سوابق (aging)، چه ریسک عمده‌ای به همراه دارد؟","optionsFa":["سرویس DHCP دیگر آدرس‌ها را اجاره نمی‌دهد (تخصیص نمی‌دهد)","پروتکل Kerberos به NTLM تغییر می‌یابد","ممکن است سوابق (رکوردهای) معتبر حذف شوند","ترافیک DNS رمزنگاری می‌شود"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/networking/troubleshoot-dns-scavenging-issues","https://learn.microsoft.com/en-us/windows-server/networking/dns/manage-dns-zones"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Implement and manage DNS for Windows Server","objectiveId":"net-dns","topic":"DNS scavenging","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/networking/troubleshoot-dns-scavenging-issues","https://learn.microsoft.com/en-us/windows-server/networking/dns/manage-dns-zones"],"keyPoints":["If the refresh plus no-refresh interval is too short, records can be removed while they are still in use.","Scavenging must be enabled and configured consistently on the zones and the DNS servers.","The safe approach is to set generous intervals and enable scavenging everywhere before relying on it."],"whyOthers":["DNS scavenging does not stop DHCP from leasing addresses.","Scavenging does not change the authentication protocol used for Kerberos.","","Scavenging does not encrypt DNS traffic."],"requirements":"Applies to DNS Server on Windows Server 2025, 2022, 2019, and 2016. Default no-refresh and refresh intervals are measured in days, and a combination shorter than 24 hours is a known cause of premature deletion."},
{"id":"az802-q-147","domain":"Implement and manage on-premises and hybrid networking","text":"Which DNS feature provides cryptographic validation of DNS data?","options":["Conditional forwarding","DNSSEC","DNS round robin","DNS scavenging"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"پروتکل DNSSEC برای تأیید اصالت و یکپارچگی داده‌ها، از سوابق امضاشده و زنجیره اعتماد (chain of trust) استفاده می‌کند.","en":"DNSSEC uses signed records and a chain of trust to validate authenticity and integrity.","de":"Die richtige Antwort ist „DNSSEC“; sie passt zum Bereich Implement and manage on-premises and hybrid networking und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام قابلیت DNS امکان اعتبارسنجی رمزنگارانه (cryptographic validation) داده‌های DNS را فراهم می‌کند؟","optionsFa":["Conditional forwarding (ارسال مشروط درخواست‌ها)","DNSSEC","DNS round robin","DNS scavenging"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/dns/sign-dnssec-zone","https://learn.microsoft.com/en-us/windows-server/networking/dns/dns-top"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Implement and manage DNS for Windows Server","objectiveId":"net-dns","topic":"DNSSEC","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/dns/sign-dnssec-zone","https://learn.microsoft.com/en-us/windows-server/networking/dns/dns-top"],"keyPoints":["DNSSEC signs DNS records so a resolver can validate their authenticity and integrity.","Validation relies on a chain of trust from the root down to the signed zone.","It protects against forged or tampered DNS answers; it does not encrypt the query itself."],"whyOthers":["Conditional forwarding directs queries to other servers and provides no validation.","","DNS round robin rotates multiple address records and does not sign data.","DNS scavenging removes stale records and does not validate them."],"requirements":"Applies to DNS Server on Windows Server 2025, 2022, 2019, and 2016. Signing requires a zone signing key and, for validation, the parent zone must publish the delegation of trust."},
{"id":"az802-q-148","domain":"Implement and manage on-premises and hybrid networking","text":"What is the purpose of a DHCP scope?","options":["Define the pool of addresses and options available to clients on a subnet","Define an AD trust","Define a storage pool","Define a VM checkpoint"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"یک Scope شامل محدوده آدرس‌ها، موارد استثنا (exclusions)، تنظیمات دوره اجاره (lease settings) و گزینه‌هایی مانند دروازه شبکه (gateway) و سرورهای DNS است.","en":"A scope contains an address range, exclusions, lease settings, and options such as gateway and DNS servers.","de":"Die richtige Antwort ist „Define the pool of addresses and options available to clients on a subnet“; sie passt zum Bereich Implement and manage on-premises and hybrid networking und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"هدف از تعریف یک DHCP Scope (محدوده DHCP) چیست؟","optionsFa":["تعیین مجموعه آدرس‌ها و گزینه‌های در دسترس برای کلاینت‌ها در یک زیرشبکه (subnet)","تعریف یک رابطه اعتماد (trust) در Active Directory","تعریف یک استخر ذخیره‌سازی (storage pool)","ایجاد یک نقطه بازگشت (checkpoint) برای ماشین مجازی"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/technologies/dhcp/dhcp-top","https://learn.microsoft.com/en-us/windows-server/networking/technologies/dhcp/quickstart-install-configure-dhcp-server"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Implement and manage DHCP for Windows Server","objectiveId":"net-dhcp","topic":"DHCP scopes","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/technologies/dhcp/dhcp-top","https://learn.microsoft.com/en-us/windows-server/networking/technologies/dhcp/quickstart-install-configure-dhcp-server"],"keyPoints":["A DHCP scope defines the range of addresses the server may lease to clients on a subnet.","It also holds exclusions, lease duration, and options such as the default gateway and DNS servers.","A scope must be activated before it will serve clients."],"whyOthers":["","An AD trust is a directory relationship and is not a DHCP scope.","A storage pool is a storage concept and has nothing to do with address allocation.","A virtual machine checkpoint captures virtual machine state and is not a DHCP scope."],"requirements":"Applies to the DHCP Server role on Windows Server 2025, 2022, 2019, and 2016. A scope is tied to a subnet, and a server that is an AD member must be authorised in AD DS before it will serve clients."},
{"id":"az802-q-149","domain":"Implement and manage on-premises and hybrid networking","text":"What is a DHCP reservation?","options":["A DNS zone transfer","A domain password policy","A storage replica","A fixed address assignment based on a client identifier such as MAC address"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"رزروها به یک کلاینتِ شناخته‌شده اجازه می‌دهند تا ضمن استفاده از DHCP، آدرسی قابل‌پیش‌بینی دریافت کند.","en":"Reservations let a known client receive a predictable address while still using DHCP.","de":"Die richtige Antwort ist „A fixed address assignment based on a client identifier such as MAC address“; sie passt zum Bereich Implement and manage on-premises and hybrid networking und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"رزرو DHCP (DHCP reservation) چیست؟","optionsFa":["انتقال ناحیه DNS (DNS zone transfer)","سیاست رمز عبور دامنه","یک نسخه کپی (Replica) از فضای ذخیره‌سازی","تخصیص آدرس ثابت بر اساس شناسه کلاینت، مانند آدرس MAC"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/technologies/dhcp/dhcp-top","https://learn.microsoft.com/en-us/windows-server/networking/technologies/dhcp/quickstart-install-configure-dhcp-server"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Implement and manage DHCP for Windows Server","objectiveId":"net-dhcp","topic":"DHCP scopes","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/technologies/dhcp/dhcp-top","https://learn.microsoft.com/en-us/windows-server/networking/technologies/dhcp/quickstart-install-configure-dhcp-server"],"keyPoints":["A DHCP reservation assigns a specific address to a client identified by its MAC address or client identifier.","The client still obtains its configuration through DHCP, but the address is predictable.","Reservations are useful for devices that need a stable address without static configuration."],"whyOthers":["A DNS zone transfer copies zone data and is not an address reservation.","A domain password policy governs passwords and lockouts and is unrelated.","A storage replica maintains a copy of a volume and does not assign addresses.",""],"commandPath":[{"label":"Create a reservation for a known client","command":"Add-DhcpServerv4Reservation -ScopeId 10.10.10.0 -IPAddress 10.10.10.50 -ClientId '00-15-5D-11-22-33' -Description 'Print server'"}],"requirements":"Applies to DHCP Server on Windows Server 2025, 2022, 2019, and 2016. The reserved address must fall inside the scope's address range and must not be excluded."},
{"id":"az802-q-150","domain":"Implement and manage on-premises and hybrid networking","text":"Which DHCP option specifies the client’s default gateway?","options":["Option 015","Option 066","Option 003","Option 006"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"گزینه 003 در DHCP آدرس‌های روتر/دروازه پیش‌فرض را ارائه می‌دهد؛ گزینه 006 سرورهای DNS را مشخص می‌کند.","en":"DHCP option 003 supplies router/default-gateway addresses; option 006 supplies DNS servers.","de":"Die richtige Antwort ist „Option 003“; sie passt zum Bereich Implement and manage on-premises and hybrid networking und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام گزینه DHCP، دروازه پیش‌فرض (Default Gateway) کلاینت را مشخص می‌کند؟","optionsFa":["گزینه 015","گزینه 066","گزینه 003","گزینه 006"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/technologies/dhcp/dhcp-top"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Implement and manage DHCP for Windows Server","objectiveId":"net-dhcp","topic":"DHCP options","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/technologies/dhcp/dhcp-top"],"keyPoints":["DHCP option 003 supplies the router (default gateway) addresses to clients.","Options are configured at the server, scope, or class level and are inherited by clients.","Getting the gateway option right is essential because it determines the client's path off the local subnet."],"whyOthers":["Option 015 is the DNS domain name, not the default gateway.","Option 066 is the boot server host name used for PXE-style booting.","","Option 006 supplies DNS server addresses, not the default gateway."],"requirements":"Applies to DHCP Server on Windows Server 2025, 2022, 2019, and 2016. A common number-to-purpose mapping worth remembering is 003 for the router, 006 for DNS servers, and 015 for the DNS domain name."},
{"id":"az802-q-151","domain":"Implement and manage on-premises and hybrid networking","text":"Which DHCP option commonly supplies DNS server addresses?","options":["060","006","003","044"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"گزینه 006 در DHCP، سرورهای DNSای را مشخص می‌کند که کلاینت‌ها باید از آن‌ها استفاده کنند.","en":"DHCP option 006 identifies DNS servers that clients should use.","de":"Die richtige Antwort ist „006“; sie passt zum Bereich Implement and manage on-premises and hybrid networking und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام گزینه (Option) در DHCP معمولاً آدرس‌های سرور DNS را ارائه می‌دهد؟","optionsFa":["060","006","003","044"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/technologies/dhcp/dhcp-top"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Implement and manage DHCP for Windows Server","objectiveId":"net-dhcp","topic":"DHCP options","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/technologies/dhcp/dhcp-top"],"keyPoints":["DHCP option 006 supplies the DNS server addresses clients should use.","It is one of the most important options for a domain environment, because clients must reach internal DNS to find domain services.","It can be set at scope level so each subnet points at the nearest DNS servers."],"whyOthers":["Option 060 is the vendor class identifier, used to distinguish client types.","","Option 003 supplies the default gateway, not DNS servers.","Option 044 is commonly used for WINS servers, not DNS servers."],"requirements":"Applies to DHCP Server on Windows Server 2025, 2022, 2019, and 2016. For domain clients the DNS option should list internal DNS servers, never public resolvers."},
{"id":"az802-q-152","domain":"Implement and manage on-premises and hybrid networking","text":"What is DHCP failover designed to provide?","options":["Address-service continuity between two DHCP servers","DNSSEC signing","VM live migration","AD schema replication"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"قابلیت DHCP Failover اطلاعات مربوط به اجاره آدرس (Lease) را همگام‌سازی کرده و از عملکرد تعادل بار (Load-balance) یا حالت آماده‌به‌کار فعال (Hot-standby) پشتیبانی می‌کند.","en":"DHCP failover synchronizes lease information and supports load-balance or hot-standby operation.","de":"Die richtige Antwort ist „Address-service continuity between two DHCP servers“; sie passt zum Bereich Implement and manage on-premises and hybrid networking und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"قابلیت DHCP Failover برای فراهم کردن چه چیزی طراحی شده است؟","optionsFa":["تداوم سرویس‌دهی آدرس‌دهی بین دو سرور DHCP","امضای DNSSEC","انتقال زنده (Live Migration) ماشین مجازی","هم‌رسانی (Replication) طرح‌واره (Schema) سرویس AD"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-server-2012-r2-and-2012/hh831385(v=ws.11)","https://learn.microsoft.com/en-us/windows-server/networking/technologies/dhcp/dhcp-top"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Implement and manage DHCP for Windows Server","objectiveId":"net-dhcp","topic":"DHCP failover","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-server-2012-r2-and-2012/hh831385(v=ws.11)","https://learn.microsoft.com/en-us/windows-server/networking/technologies/dhcp/dhcp-top"],"keyPoints":["DHCP failover keeps address service available by synchronising lease information between two DHCP servers.","It supports load-balance and hot-standby modes.","Clients keep receiving addresses even if one server becomes unavailable."],"whyOthers":["","DHCP failover does not sign DNS data; DNSSEC does that.","It does not perform virtual machine live migration.","It does not replicate the AD schema."],"requirements":"Applies to DHCP Server on Windows Server 2025, 2022, 2019, and 2016. A failover relationship is limited to two servers and applies to IPv4 scopes, so IPv6 and some configurations need a different approach."},
{"id":"az802-q-153","domain":"Implement and manage on-premises and hybrid networking","text":"A DHCP server is authorized in AD DS but clients receive no lease. What should you inspect first?","options":["The forest functional level only","The VM checkpoint tree","The NTFS compression ratio","Scope activation, available addresses, network reachability, and relay configuration"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"سرویس DHCP به یک Scope قابل استفاده و مسیری برای بسته‌های Broadcast یا درخواست‌های ارسالی از طریق Relay نیاز دارد.","en":"DHCP requires a usable scope and a path for broadcasts or relay-forwarded requests.","de":"Die richtige Antwort ist „Scope activation, available addresses, network reachability, and relay configuration“; sie passt zum Bereich Implement and manage on-premises and hybrid networking und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"یک سرور DHCP در AD DS مجاز (Authorized) شده است، اما کلاینت‌ها هیچ‌گونه اجاره آدرسی (Lease) دریافت نمی‌کنند. ابتدا چه چیزی را باید بررسی کنید؟","optionsFa":["فقط سطح عملکردی فارست (Forest Functional Level)","درخت نقاط بازگشت (Checkpoint Tree) ماشین مجازی","نسبت فشرده‌سازی NTFS","فعال بودن Scope، آدرس‌های موجود، قابلیت دسترسی به شبکه و پیکربندی Relay"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/networking/troubleshooting-guide-dhcp-authorization-failures","https://learn.microsoft.com/en-us/windows-server/networking/technologies/dhcp/dhcp-top"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Troubleshoot name resolution and network connectivity","objectiveId":"net-troubleshoot","topic":"DHCP troubleshooting","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/networking/troubleshooting-guide-dhcp-authorization-failures","https://learn.microsoft.com/en-us/windows-server/networking/technologies/dhcp/dhcp-top"],"keyPoints":["Authorization in AD DS is only one requirement; the scope must also be active and have free addresses.","There must be a network path for the client's broadcast or a relay agent on the remote subnet.","Checking scope state, available addresses, reachability, and relay configuration covers the common causes."],"whyOthers":["The forest functional level is not the first thing to inspect for a lease failure.","A virtual machine checkpoint tree is a Hyper-V concept and unrelated to DHCP leases.","The NTFS compression ratio is a file-storage measure and has no bearing on DHCP.",""],"commandPath":[{"label":"Check scope state and available addresses","command":"Get-DhcpServerv4ScopeStatistics"},{"label":"Review current leases for a scope","command":"Get-DhcpServerv4Lease -ScopeId 10.10.10.0"}],"requirements":"Applies to DHCP Server on Windows Server 2025, 2022, 2019, and 2016. A deactivated scope, an exhausted address range, or a missing relay agent are the most common reasons a client receives no lease."},
{"id":"az802-q-154","domain":"Implement and manage on-premises and hybrid networking","text":"What is a DHCP relay used for?","options":["Encrypt SMB traffic","Move a VM","Forward DHCP client broadcasts across routed networks","Replicate DNS records"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"روترها معمولاً پیام‌های Broadcast را ارسال (Forward) نمی‌کنند، بنابراین یک عامل Relay پیام‌های DHCP را به سرور می‌رساند.","en":"Routers generally do not forward broadcasts, so a relay agent forwards DHCP messages to a server.","de":"Die richtige Antwort ist „Forward DHCP client broadcasts across routed networks“; sie passt zum Bereich Implement and manage on-premises and hybrid networking und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کاربرد DHCP relay چیست؟","optionsFa":["رمزنگاری ترافیک SMB","انتقال یک ماشین مجازی (VM)","ارسال پیام‌های Broadcast کلاینت DHCP در شبکه‌های دارای مسیریابی (Routed networks)","تکثیر (Replicate) رکوردهای DNS"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/technologies/dhcp/dhcp-top"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Implement and manage DHCP for Windows Server","objectiveId":"net-dhcp","topic":"DHCP relay","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/technologies/dhcp/dhcp-top"],"keyPoints":["A DHCP relay agent forwards DHCP messages between clients on one subnet and a DHCP server on another.","It is needed because routers normally do not forward the broadcast a DHCP client sends.","The relay forwards to the server and returns the reply to the client, which allows one central DHCP server to serve many subnets."],"whyOthers":["Encrypting SMB traffic is a file-server security setting and does not relay DHCP.","Moving a virtual machine is a Hyper-V operation and is unrelated.","","Replicating DNS records is a DNS task, not a DHCP relay function."],"requirements":"Applies to DHCP Server and routing devices on Windows Server 2025, 2022, 2019, and 2016. A relay must be configured with the DHCP server addresses or be able to discover the server."},
{"id":"az802-q-155","domain":"Implement and manage on-premises and hybrid networking","text":"A client has an APIPA address beginning with 169.254. What does this usually indicate?","options":["It is using DNSSEC","It failed to obtain a DHCP lease","It successfully contacted a domain controller","It has a valid public address"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"زمانی که فرآیند مذاکره DHCP منجر به دریافت آدرس قابل‌استفاده‌ای نشود، ویندوز به‌طور خودکار یک آدرس APIPA به سیستم اختصاص می‌دهد.","en":"Windows self-assigns an APIPA address when DHCP negotiation does not provide a usable address.","de":"Die richtige Antwort ist „It failed to obtain a DHCP lease“; sie passt zum Bereich Implement and manage on-premises and hybrid networking und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"یک کلاینت دارای آدرس APIPA است که با 169.254 شروع می‌شود. این وضعیت معمولاً نشان‌دهنده چیست؟","optionsFa":["استفاده از DNSSEC","عدم موفقیت در دریافت DHCP lease (اجاره‌نامه آدرس DHCP)","برقراری ارتباط موفق با Domain Controller","داشتن یک آدرس عمومی (Public address) معتبر"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/technologies/dhcp/dhcp-top","https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/ipconfig"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Troubleshoot name resolution and network connectivity","objectiveId":"net-troubleshoot","topic":"DHCP troubleshooting","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/technologies/dhcp/dhcp-top","https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/ipconfig"],"keyPoints":["Automatic Private IP Addressing (APIPA) uses the 169.254.0.0/16 range, which Windows self-assigns.","It appears when a client fails to obtain a usable address from DHCP.","APIPA hosts can communicate only on the local link, so the symptom is no address-service response."],"whyOthers":["APIPA has nothing to do with DNSSEC; it is an address self-assignment behaviour.","","A successful domain controller contact would come from valid addressing, not from an APIPA address.","169.254.0.0/16 is a link-local private range, never a valid public address."],"commandPath":[{"label":"Release and renew the lease","command":"ipconfig /release; ipconfig /renew"}],"requirements":"Applies to Windows Server 2025, 2022, 2019, 2016 and to clients. A client can also receive APIPA when the DHCP server exists but has no free addresses in the scope."},
{"id":"az802-q-156","domain":"Implement and manage on-premises and hybrid networking","text":"Which command renews a DHCP lease?","options":["ipconfig /renew","ipconfig /displaydns","nslookup /renew","route /lease"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"این دستور درخواست تمدید اجاره DHCP را به سرویس DHCP پیکربندی‌شده ارسال می‌کند.","en":"It requests a renewed DHCP lease from the configured DHCP service.","de":"Die richtige Antwort ist „ipconfig /renew“; sie passt zum Bereich Implement and manage on-premises and hybrid networking und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام دستور اجاره (lease) مربوط به DHCP را تمدید می‌کند؟","optionsFa":["ipconfig /renew","ipconfig /displaydns","nslookup /renew","route /lease"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/ipconfig","https://learn.microsoft.com/en-us/windows-server/networking/technologies/dhcp/dhcp-top"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Troubleshoot name resolution and network connectivity","objectiveId":"net-troubleshoot","topic":"DHCP troubleshooting","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/ipconfig","https://learn.microsoft.com/en-us/windows-server/networking/technologies/dhcp/dhcp-top"],"keyPoints":["ipconfig /renew requests a renewed DHCP lease from the configured DHCP service.","Running ipconfig /release first gives up the current lease so a fresh address is requested.","It is the standard first step when a client shows an APIPA address or stale configuration."],"whyOthers":["","ipconfig /displaydns shows the local DNS cache and does not renew a lease.","nslookup /renew is not a valid command; nslookup queries DNS.","route /lease is not a valid command; route print displays the routing table."],"commandPath":[{"label":"Renew the DHCP lease for all adapters","command":"ipconfig /renew"},{"label":"Renew the lease for one adapter","command":"ipconfig /renew \"Ethernet\""}],"requirements":"Applies to Windows Server 2025, 2022, 2019, 2016 and to clients. Renewal requires a reachable DHCP server and free addresses in the scope."},
{"id":"az802-q-157","domain":"Implement and manage on-premises and hybrid networking","text":"What is the first address-resolution protocol to check when a host can resolve names but cannot reach an IPv4 peer on the local subnet?","options":["LDAP","Kerberos","SMB","ARP"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"پروتکل ARP پیش از تحویل در لایه اترنت، یک آدرس IPv4 محلی را به آدرس MAC نگاشت می‌کند.","en":"ARP maps a local IPv4 address to a MAC address before Ethernet delivery.","de":"Die richtige Antwort ist „ARP“; sie passt zum Bereich Implement and manage on-premises and hybrid networking und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"وقتی یک میزبان (host) می‌تواند نام‌ها را ترجمه (resolve) کند اما قادر به برقراری ارتباط با یک همتا (peer) دارای IPv4 در زیرشبکه محلی نیست، اولین پروتکل ترجمه آدرس که باید بررسی شود کدام است؟","optionsFa":["LDAP","Kerberos","SMB","ARP"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/arp","https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/route_ws2008"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Troubleshoot name resolution and network connectivity","objectiveId":"net-troubleshoot","topic":"Address resolution","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/arp","https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/route_ws2008"],"keyPoints":["ARP resolves a local IPv4 address to the MAC address that Ethernet delivery needs.","If ARP fails, the packet cannot be framed for the local segment even though the address is correct.","Checking the ARP cache shows whether the host learned the peer's MAC address."],"whyOthers":["LDAP is a directory access protocol and is used after connectivity, not for local address resolution.","Kerberos authenticates identities and does not map addresses to MAC addresses.","SMB is a file-sharing protocol and is not used to resolve addresses.",""],"commandPath":[{"label":"Show the local ARP cache","command":"arp -a"}],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Name resolution succeeding while local delivery fails is a strong sign that the problem is at the link layer, such as ARP, VLAN, or switch port configuration."},
{"id":"az802-q-158","domain":"Implement and manage on-premises and hybrid networking","text":"Which command displays the local routing table?","options":["repadmin /replsummary","manage-bde -status","route print","gpresult /h"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"دستور route print مسیرهای IPv4 و IPv6 مورد استفاده توسط میزبان را نمایش می‌دهد.","en":"route print displays IPv4 and IPv6 routes used by the host.","de":"Die richtige Antwort ist „route print“; sie passt zum Bereich Implement and manage on-premises and hybrid networking und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام دستور جدول مسیریابی محلی را نمایش می‌دهد؟","optionsFa":["repadmin /replsummary","manage-bde -status","route print","gpresult /h"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/route_ws2008"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Troubleshoot name resolution and network connectivity","objectiveId":"net-troubleshoot","topic":"Routing","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/route_ws2008"],"keyPoints":["route print displays the host's IPv4 and IPv6 routing tables.","It shows the destination networks, the gateway used for each, and the interface and metric.","It is the first check when a host can reach the local subnet but not a remote one."],"whyOthers":["repadmin /replsummary summarises directory replication and does not show routing.","manage-bde -status reports BitLocker status on volumes.","","gpresult /h writes a Group Policy report."],"commandPath":[{"label":"Show the routing table","command":"route print"},{"label":"Show the effective IP configuration and routes","command":"Get-NetRoute | Sort-Object DestinationPrefix"}],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. When more than one route matches, the longest prefix wins and then the lowest metric, which explains many unexpected path selections."},
{"id":"az802-q-159","domain":"Implement and manage on-premises and hybrid networking","text":"Which command tests reachability and can show the path to a destination?","options":["diskshadow","tracert","gpupdate","dfsutil"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"دستور tracert گام‌های میانی (hops) را شناسایی می‌کند و می‌تواند به تعیین موقعیت مرزهای مسیریابی یا فیلترینگ کمک کند.","en":"tracert identifies intermediate hops and can help locate routing or filtering boundaries.","de":"Die richtige Antwort ist „tracert“; sie passt zum Bereich Implement and manage on-premises and hybrid networking und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام دستور قابلیت دسترسی را آزمایش کرده و می‌تواند مسیر رسیدن به مقصد را نشان دهد؟","optionsFa":["diskshadow","tracert","gpupdate","dfsutil"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/tracert"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Troubleshoot name resolution and network connectivity","objectiveId":"net-troubleshoot","topic":"Connectivity testing","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/tracert"],"keyPoints":["tracert shows each hop along the path to a destination by using increasing time-to-live values.","It can reveal where traffic stops, which helps locate a routing or filtering boundary.","A hop that does not answer does not prove a break, because some routers drop the probes."],"whyOthers":["diskshadow manages volume shadow copies and does not test connectivity.","","gpupdate refreshes Group Policy and does not trace a path.","dfsutil manages DFS namespaces and replication and is unrelated to path testing."],"commandPath":[{"label":"Trace the path to a host","command":"tracert -d 10.20.0.5"}],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. For a more detailed PowerShell option, Test-NetConnection -TraceRoute combines reachability and path information."},
{"id":"az802-q-160","domain":"Implement and manage on-premises and hybrid networking","text":"Which command tests whether a TCP port is reachable from PowerShell?","options":["Test-NetConnection","Get-NetIPConfiguration only","Resolve-DnsName only","Get-DhcpServerv4Lease"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"دستور Test-NetConnection می‌تواند وضعیت میزبان (host)، پورت، مسیر و ویژگی‌های مرتبط با اتصال را آزمایش کند.","en":"Test-NetConnection can test a host, port, route, and related connectivity properties.","de":"Die richtige Antwort ist „Test-NetConnection“; sie passt zum Bereich Implement and manage on-premises and hybrid networking und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام دستور در PowerShell بررسی می‌کند که آیا یک پورت TCP قابل دسترسی است یا خیر؟","optionsFa":["Test-NetConnection","فقط Get-NetIPConfiguration","فقط Resolve-DnsName","Get-DhcpServerv4Lease"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/nettcpip/test-netconnection","https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/tracert"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Troubleshoot name resolution and network connectivity","objectiveId":"net-troubleshoot","topic":"Connectivity testing","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/nettcpip/test-netconnection","https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/tracert"],"keyPoints":["Test-NetConnection can test reachability to a host and to a specific TCP port.","It also reports details such as the resolved address, the route used, and the interface.","Testing a port is often more useful than a ping because many servers block ICMP while still serving TCP."],"whyOthers":["","Get-NetIPConfiguration shows local addressing but does not test a remote port.","Resolve-DnsName resolves names but does not test port reachability.","Get-DhcpServerv4Lease lists DHCP leases and does not test connectivity."],"commandPath":[{"label":"Test TCP port 443 on a server","command":"Test-NetConnection -ComputerName srv01.contoso.com -Port 443 -InformationLevel Detailed"},{"label":"Test reachability and trace the route","command":"Test-NetConnection -ComputerName srv01.contoso.com -TraceRoute"}],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 and to supported PowerShell versions. A failed TCP test can be caused by a firewall, a stopped service, or a routing problem, so the result should be combined with other evidence."},
{"id":"az802-q-161","domain":"Implement and manage on-premises and hybrid networking","text":"In a hybrid design, what does a private DNS zone primarily provide?","options":["Public certificate signing","DHCP failover","AD schema changes","Name resolution for private addresses within linked virtual networks"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"نواحی DNS خصوصی، نام‌های داخلی را بدون افشای آن‌ها در DNS عمومی، ترجمه می‌کنند.","en":"Private DNS zones resolve internal names without exposing them to public DNS.","de":"Die richtige Antwort ist „Name resolution for private addresses within linked virtual networks“; sie passt zum Bereich Implement and manage on-premises and hybrid networking und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"در یک طراحی ترکیبی (هیبریدی)، یک ناحیه DNS خصوصی (Private DNS zone) عمدتاً چه امکانی را فراهم می‌کند؟","optionsFa":["امضای گواهی‌های عمومی","قابلیت Failover برای DHCP","تغییرات در طرح‌واره (Schema) سرویس AD","ترجمه نام (Name resolution) برای آدرس‌های خصوصی در شبکه‌های مجازی متصل‌به‌هم"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/dns/private-dns-overview","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/dns-and-ad-ds"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Implement hybrid network connectivity and security","objectiveId":"net-hybrid","topic":"Private DNS","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/dns/private-dns-overview","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/dns-and-ad-ds"],"keyPoints":["A private DNS zone resolves names for private addresses inside linked virtual networks.","It is not published to the public DNS namespace, so internal names stay internal.","Automatic registration can keep records current as virtual machines are added and removed."],"whyOthers":["Public certificate signing is a public key infrastructure task and is not what a private DNS zone does.","DHCP failover provides address-service redundancy and is unrelated.","AD schema changes are directory operations and are not provided by a private DNS zone.",""],"requirements":"Applies to Azure Private DNS. A private zone is linked to one or more virtual networks, and resolution works only for clients in the linked networks."},
{"id":"az802-q-162","domain":"Implement and manage on-premises and hybrid networking","text":"What is split-brain DNS?","options":["A duplicate DHCP lease","A replicated file share","Different DNS answers are returned for the same name depending on the client’s network or view","A DNS server with two CPUs"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"در Split DNS، می‌توان آدرس‌های خصوصی داخلی ارائه داد، در حالی که کلاینت‌های عمومی، نقاط پایانی (endpoints) عمومی دریافت می‌کنند.","en":"Split DNS can provide internal private addresses while public clients receive public endpoints.","de":"Die richtige Antwort ist „Different DNS answers are returned for the same name depending on the client’s network or view“; sie passt zum Bereich Implement and manage on-premises and hybrid networking und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"DNS از نوع Split-brain (یا Split DNS) چیست؟","optionsFa":["یک اجاره (lease) تکراری DHCP","یک اشتراک‌گذاری فایل (file share) که تکثیر شده است","بسته به شبکه یا نمای (view) کلاینت، پاسخ‌های DNS متفاوتی برای یک نام واحد بازگردانده می‌شود","یک سرور DNS با دو پردازنده (CPU)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/dns/manage-dns-zones","https://learn.microsoft.com/en-us/azure/dns/private-dns-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Implement hybrid network connectivity and security","objectiveId":"net-hybrid","topic":"Split-brain DNS","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/dns/manage-dns-zones","https://learn.microsoft.com/en-us/azure/dns/private-dns-overview"],"keyPoints":["Split-brain (split-horizon) DNS returns different answers for the same name depending on the client's network or view.","Internal clients receive a private address while external clients receive a public endpoint.","It is common when a service must be reachable both inside and outside the organization."],"whyOthers":["A duplicate DHCP lease is an addressing problem and is not split-brain DNS.","A replicated file share is a storage topic and is unrelated.","","The number of CPUs on a DNS server has nothing to do with split-brain DNS."],"requirements":"Applies to DNS Server on Windows Server 2025, 2022, 2019, and 2016 and to Azure Private DNS. The internal and public zones must be maintained separately, so records can drift if the process is manual."},
{"id":"az802-q-163","domain":"Implement and manage on-premises and hybrid networking","text":"A DNS client uses the wrong DNS server. What symptom is likely on a domain-joined computer?","options":["BitLocker decrypts the disk","AD service discovery and domain logon may fail","NTFS permissions are automatically removed","The computer receives two CPUs"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"کلاینت‌های دامین باید از DNSای استفاده کنند که قادر به حل (resolve) فضای نام AD و رکوردهای SRV آن باشد.","en":"Domain clients must use DNS that can resolve the AD namespace and its SRV records.","de":"Die richtige Antwort ist „AD service discovery and domain logon may fail“; sie passt zum Bereich Implement and manage on-premises and hybrid networking und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"یک کلاینت DNS از سرور DNS اشتباهی استفاده می‌کند. چه علائمی احتمالاً در رایانه‌ای که عضو دامین (domain-joined) است، مشاهده می‌شود؟","optionsFa":["بیت‌لاکر (BitLocker) دیسک را رمزگشایی می‌کند","کشف سرویس AD و ورود به دامین (logon) ممکن است با شکست مواجه شود","مجوزهای NTFS به‌طور خودکار حذف می‌شوند","رایانه دو پردازنده دریافت می‌کند"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/windows-security/troubleshoot-domain-controller-location-issues","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/dc-locator"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Troubleshoot name resolution and network connectivity","objectiveId":"net-troubleshoot","topic":"DNS troubleshooting","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/windows-security/troubleshoot-domain-controller-location-issues","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/dc-locator"],"keyPoints":["Domain clients must use DNS that can resolve the AD namespace and its SRV records.","If the client uses an external DNS server, AD service discovery and domain logon can fail even though internet name resolution works.","This is one of the most common causes of a domain-joined computer failing to find a domain controller."],"whyOthers":["BitLocker does not decrypt a disk because of a DNS server change.","","NTFS permissions are stored on the file system and are not removed by a DNS change.","A computer is not given extra CPUs by a DNS change."],"requirements":"Applies to domain-joined Windows Server 2025, 2022, 2019, and 2016 and to clients. Setting the correct DNS server through DHCP option 006 rather than local overrides keeps clients consistent."},
{"id":"az802-q-164","domain":"Implement and manage on-premises and hybrid networking","text":"What does DNS round robin provide?","options":["Multiple address records returned in rotation for simple distribution","Stateful load balancing with health checks","DNSSEC signing","DHCP lease replication"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"روش Round-robin می‌تواند انتخاب کلاینت‌ها را توزیع کند، اما سلامت برنامه را به شکلی قابل‌اطمینان تشخیص نمی‌دهد.","en":"Round robin can distribute client selection but does not reliably detect application health.","de":"Die richtige Antwort ist „Multiple address records returned in rotation for simple distribution“; sie passt zum Bereich Implement and manage on-premises and hybrid networking und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"قابلیت DNS Round Robin چه امکانی را فراهم می‌کند؟","optionsFa":["بازگرداندن رکوردهای آدرس متعدد به صورت چرخشی (Round-robin) برای توزیع ساده","متعادل‌سازی بار (Load Balancing) با حفظ وضعیت (Stateful) و همراه با بررسی سلامت (Health Checks)","امضای DNSSEC","تکثیر (Replication) اجاره‌نامه‌های DHCP"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/dns/dns-top","https://learn.microsoft.com/en-us/windows-server/networking/dns/dns-architecture"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Implement and manage DNS for Windows Server","objectiveId":"net-dns","topic":"DNS load distribution","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/dns/dns-top","https://learn.microsoft.com/en-us/windows-server/networking/dns/dns-architecture"],"keyPoints":["DNS round robin returns the address records for a name in a rotating order.","It provides simple distribution of client connections without any health awareness.","Because there is no health check, a failed host can still be offered to clients until its record is removed."],"whyOthers":["","Round robin is not stateful load balancing and does not perform health checks.","Round robin does not sign DNS data; that is DNSSEC.","Round robin does not replicate DHCP leases."],"requirements":"Applies to DNS Server on Windows Server 2025, 2022, 2019, and 2016. Round robin is enabled by default on Windows DNS, and priority or weight values are not used in the way SRV records use them."},
{"id":"az802-q-165","domain":"Implement and manage on-premises and hybrid networking","text":"Which networking control is most appropriate for allowing only HTTPS to a server subnet?","options":["A DNS CNAME record","A DHCP reservation","A Group Policy drive map","A firewall or network security rule allowing TCP 443 and denying unneeded inbound ports"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"دسترسی به پورت توسط قوانین فایروال شبکه و میزبان (Host) کنترل می‌شود، نه توسط مکانیزم حل نام (Name Resolution).","en":"Port access is controlled by network and host firewall rules, not by name resolution.","de":"Die richtige Antwort ist „A firewall or network security rule allowing TCP 443 and denying unneeded inbound ports“; sie passt zum Bereich Implement and manage on-premises and hybrid networking und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام کنترل شبکه برای مجاز کردن دسترسی HTTPS به یک زیرشبکه (subnet) سرور مناسب‌تر است؟","optionsFa":["یک رکورد CNAME در DNS","یک رزرو DHCP","نگاشت درایو (Drive Map) در Group Policy","یک فایروال یا قانون امنیتی شبکه که پورت TCP 443 را مجاز و پورت‌های ورودی غیرضروری را مسدود می‌کند"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview","https://learn.microsoft.com/en-us/windows-server/networking/technologies/dhcp/dhcp-top"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Implement hybrid network connectivity and security","objectiveId":"net-hybrid","topic":"Network security rules","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview","https://learn.microsoft.com/en-us/windows-server/networking/technologies/dhcp/dhcp-top"],"keyPoints":["Access by port is controlled by firewall and network security rules, on the host or in the network.","Allowing TCP 443 and denying unneeded inbound ports is the standard least-privilege approach for a server subnet.","Rules should be explicit and reviewed so that a temporary allowance does not become permanent."],"whyOthers":["A DNS CNAME record is an alias and does not control access.","A DHCP reservation assigns an address and does not filter traffic.","A Group Policy drive map connects a drive letter and does not control ports.",""],"requirements":"Applies to Windows Firewall on Windows Server 2025, 2022, 2019, and 2016 and to Azure network security groups. Effective access is the combination of the network rule set and the host firewall rule set."},
{"id":"az802-q-166","domain":"Implement and manage on-premises and hybrid networking","text":"Which Azure control filters inbound and outbound traffic at the subnet or network-interface level?","options":["Azure Automation","Microsoft Entra Connect","Network Security Group","Azure File Sync"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"گروه‌های امنیت شبکه (NSG) شامل قوانین مرتب‌شده‌ای برای اجازه دادن (allow) یا رد کردن (deny) ترافیکِ مرتبط با زیرشبکه‌ها و رابط‌های شبکه هستند.","en":"NSGs contain ordered allow and deny rules for traffic associated with subnets and network interfaces.","de":"Die richtige Antwort ist „Network Security Group“; sie passt zum Bereich Implement and manage on-premises and hybrid networking und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام کنترل Azure ترافیک ورودی و خروجی را در سطح زیرشبکه (subnet) یا رابط شبکه (network interface) فیلتر می‌کند؟","optionsFa":["Azure Automation","Microsoft Entra Connect","Network Security Group (گروه امنیت شبکه)","Azure File Sync"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Implement hybrid network connectivity and security","objectiveId":"net-hybrid","topic":"Network security groups","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview"],"keyPoints":["A network security group (NSG) contains ordered allow and deny rules for inbound and outbound traffic.","It can be associated with a subnet or a network interface, and it filters traffic in both directions.","Because rules are evaluated by priority, the lowest-numbered matching rule decides the outcome."],"whyOthers":["Azure Automation runs runbooks and does not filter network traffic.","Microsoft Entra Connect synchronises identities and does not filter traffic.","","Azure File Sync caches file shares and does not filter network traffic."],"requirements":"Applies to Azure network security groups. Every NSG has default rules that allow virtual network and load-balancer traffic and deny the rest, and default rules have the lowest priority."},
{"id":"az802-q-167","domain":"Implement and manage on-premises and hybrid networking","text":"A new deny NSG rule appears to have no effect. What should you verify first?","options":["The DHCP reservation name","Rule priority, direction, protocol, source, destination, and effective security rules","The VM’s NTFS ACL","The domain password policy"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"قوانین NSG بر اساس اولویت ارزیابی می‌شوند و باید با مشخصات (تاپل) ترافیک واقعی مطابقت داشته باشند.","en":"NSG rules are evaluated by priority and must match the actual traffic tuple.","de":"Die richtige Antwort ist „Rule priority, direction, protocol, source, destination, and effective security rules“; sie passt zum Bereich Implement and manage on-premises and hybrid networking und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"به نظر می‌رسد یک قانون جدید NSG برای رد کردن ترافیک (deny)، هیچ تأثیری ندارد. ابتدا چه چیزی را باید بررسی کنید؟","optionsFa":["نام رزرو DHCP","اولویت قانون، جهت، پروتکل، مبدأ، مقصد و قوانین امنیتی مؤثر (effective security rules)","لیست کنترل دسترسی (ACL) سیستم فایل NTFS ماشین مجازی","سیاست رمز عبور دامنه (domain password policy)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Implement hybrid network connectivity and security","objectiveId":"net-hybrid","topic":"Network security groups","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview"],"keyPoints":["NSG rules are evaluated in priority order, and a lower-numbered rule takes precedence.","The rule must match the actual traffic: direction, protocol, source, destination, and port.","The most likely explanation for a deny rule that seems to do nothing is a higher-priority allow rule that matches first."],"whyOthers":["The DHCP reservation name has no bearing on NSG rule evaluation.","","NTFS ACLs control file access on the guest and do not override an NSG rule.","The domain password policy is unrelated to network rule evaluation."],"commandPath":[{"label":"Show the effective security rules for a network interface","command":"Get-AzEffectiveNetworkSecurityGroup -NetworkInterfaceName nic-web01 -ResourceGroupName rg-app"}],"requirements":"Applies to Azure network security groups. Effective security rules combine subnet-level and interface-level NSGs, so both must be checked when a rule appears ineffective."},
{"id":"az802-q-168","domain":"Manage storage and file services","text":"Which file system is generally preferred for modern Windows system volumes?","options":["NTFS","FAT12","ISO 9660","UDF only"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"سیستم فایل NTFS از لیست‌های کنترل دسترسی (ACL) امنیتی، ژورنال‌سازی (journaling)، سهمیه‌بندی (quotas)، فشرده‌سازی، رمزنگاری و سایر قابلیت‌های ویندوز پشتیبانی می‌کند.","en":"NTFS supports security ACLs, journaling, quotas, compression, encryption, and other Windows capabilities.","de":"Die richtige Antwort ist „NTFS“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام سیستم فایل معمولاً برای درایوهای سیستمی (system volumes) ویندوزهای مدرن ترجیح داده می‌شود؟","optionsFa":["NTFS","FAT12","ISO 9660","فقط UDF"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/file-server/ntfs-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure file systems and NTFS permissions","objectiveId":"storage-file-systems","topic":"File systems","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/file-server/ntfs-overview"],"keyPoints":["NTFS is the default file system for Windows system volumes and supports per-object security.","It provides ACL-based permissions, journaling, quotas, compression, and encryption through EFS.","It is the file system that all Windows management tooling assumes for a system volume."],"whyOthers":["","FAT12 is an obsolete file system with no ACLs, journaling, or support for large volumes.","ISO 9660 is an optical-disc file system, not a system-volume file system.","UDF is used for optical and removable media and is not the modern Windows system-volume choice."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. NTFS is required for volumes that must hold Active Directory data, SYSVOL, and the operating system itself."},
{"id":"az802-q-169","domain":"Manage storage and file services","text":"Which file system is designed for resiliency and large-scale storage workloads?","options":["FAT32","exFAT only","CDFS","ReFS"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"سیستم فایل ReFS ویژگی‌های یکپارچگی و تاب‌آوری را برای بارهای کاری داده‌ایِ پشتیبانی‌شده فراهم می‌کند، هرچند همه قابلیت‌های ویندوز در ReFS در دسترس نیستند.","en":"ReFS provides integrity and resiliency features for supported data workloads, though not every Windows feature is available on ReFS.","de":"Die richtige Antwort ist „ReFS“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام سیستم فایل برای تاب‌آوری و بارهای کاری ذخیره‌سازی در مقیاس بزرگ طراحی شده است؟","optionsFa":["FAT32","فقط exFAT","CDFS","ReFS"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/refs/refs-overview","https://learn.microsoft.com/en-us/windows-server/storage/file-server/ntfs-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure file systems and NTFS permissions","objectiveId":"storage-file-systems","topic":"File systems","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/refs/refs-overview","https://learn.microsoft.com/en-us/windows-server/storage/file-server/ntfs-overview"],"keyPoints":["ReFS is designed for resiliency and large-scale data workloads, with integrity streams and automatic integrity checking.","It works with Storage Spaces and Storage Spaces Direct to detect and repair corruption where redundancy exists.","Not every Windows feature is available on ReFS, so it is used for data volumes rather than system volumes."],"whyOthers":["FAT32 lacks per-object security and integrity features, and it is limited in volume and file size.","exFAT is designed for removable media interchange and does not provide integrity streams.","CDFS is an optical-disc file system and is not used for server data volumes.",""],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. ReFS cannot host the operating system or Active Directory data, and features such as data deduplication and some quota behaviour differ from NTFS."},
{"id":"az802-q-170","domain":"Manage storage and file services","text":"What is the purpose of an NTFS access control list?","options":["Define DHCP lease duration","Define a VM’s CPU count","Define which security principals can access a file or folder and how","Define DNS recursion"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"فهرست‌های کنترل دسترسی (ACL) در NTFS شامل ورودی‌های کنترل دسترسی هستند که انجام عملیات‌ها را مجاز یا ممنوع می‌کنند.","en":"NTFS ACLs contain access control entries that allow or deny operations.","de":"Die richtige Antwort ist „Define which security principals can access a file or folder and how“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"هدف از «فهرست کنترل دسترسی» (ACL) در NTFS چیست؟","optionsFa":["تعیین مدت زمان اجاره (lease) در DHCP","تعیین تعداد پردازنده‌های (CPU) یک ماشین مجازی (VM)","تعیین اینکه کدام موجودیت‌های امنیتی (security principals) و با چه شرایطی می‌توانند به یک فایل یا پوشه دسترسی داشته باشند","تعیین بازگشت (recursion) در DNS"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows/win32/secauthz/access-control-lists","https://learn.microsoft.com/en-us/windows-server/storage/file-server/ntfs-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure file systems and NTFS permissions","objectiveId":"storage-file-systems","topic":"NTFS permissions","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows/win32/secauthz/access-control-lists","https://learn.microsoft.com/en-us/windows-server/storage/file-server/ntfs-overview"],"keyPoints":["An NTFS access control list is the ordered collection of access control entries on a file or folder.","Each entry names a security principal and either allows or denies specific operations.","The effective permission is the result of evaluating explicit and inherited entries together."],"whyOthers":["DHCP lease duration is set in a DHCP scope and is not part of an ACL.","A virtual machine's CPU count is a Hyper-V setting and is unrelated to file permissions.","","DNS recursion is a resolver behaviour and is not defined by an ACL."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Object ownership is separate from the ACL, and an owner always retains the ability to change the ACL on the object it owns."},
{"id":"az802-q-171","domain":"Manage storage and file services","text":"Which permission is normally required to read a file’s contents?","options":["Change owner only","Read","Delete child","Take ownership only"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"مجوز Read (خواندن) امکان مشاهده داده‌های فایل و ویژگی‌های مرتبط با آن را فراهم می‌کند (مشروط بر اینکه دسترسی مؤثر برقرار باشد).","en":"Read permits viewing file data and related attributes subject to effective access.","de":"Die richtige Antwort ist „Read“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"برای خواندن محتوای یک فایل، معمولاً به چه مجوزی نیاز است؟","optionsFa":["فقط تغییر مالک (Change owner)","خواندن (Read)","حذف مورد فرزند (Delete child)","فقط تصاحب مالکیت (Take ownership)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows/win32/secauthz/access-control-lists","https://learn.microsoft.com/en-us/windows-server/storage/file-server/ntfs-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure file systems and NTFS permissions","objectiveId":"storage-file-systems","topic":"NTFS permissions","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows/win32/secauthz/access-control-lists","https://learn.microsoft.com/en-us/windows-server/storage/file-server/ntfs-overview"],"keyPoints":["The Read permission allows a user to view a file's data and its attributes.","For a folder it also allows listing the folder's contents and reading the properties of the files in it.","Read is the minimum permission needed to open a file for viewing."],"whyOthers":["Change owner is a specific right that transfers ownership and is not the permission that reads contents.","","Delete child authorises deleting subobjects and does not grant read access.","Take ownership is a right used in recovery scenarios and does not by itself allow reading the contents."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. The advanced permission set also includes Read attributes, Read extended attributes, and Read permissions, which together make up the Read basic permission."},
{"id":"az802-q-172","domain":"Manage storage and file services","text":"Which permission allows a user to modify existing data in a file?","options":["Write","List folder only","Read permissions only","Synchronize only"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"مجوز Write (نوشتن) امکان تغییر داده‌ها یا ویژگی‌های فایل را (طبق آنچه در ACL کامل تعیین شده است) فراهم می‌کند.","en":"Write permits changing file data or attributes as allowed by the complete ACL.","de":"Die richtige Antwort ist „Write“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام مجوز به کاربر اجازه می‌دهد داده‌های موجود در یک فایل را تغییر دهد؟","optionsFa":["نوشتن (Write)","فقط فهرست کردن محتویات پوشه (List folder)","فقط خواندن مجوزها (Read permissions)","فقط همگام‌سازی (Synchronize)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows/win32/secauthz/access-control-lists","https://learn.microsoft.com/en-us/windows-server/storage/file-server/ntfs-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure file systems and NTFS permissions","objectiveId":"storage-file-systems","topic":"NTFS permissions","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows/win32/secauthz/access-control-lists","https://learn.microsoft.com/en-us/windows-server/storage/file-server/ntfs-overview"],"keyPoints":["The Write permission allows a user to change a file's data and attributes.","It is the permission that lets an existing file be modified rather than only read.","Modify combines Read and Write with delete, which is why it is used for documents that users edit."],"whyOthers":["","List folder only allows browsing a directory and not modifying file data.","Read permissions only allows viewing the security descriptor and does not permit writing.","Synchronize only is a low-level right used for thread synchronisation and does not allow changing data."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Write does not include delete; Delete requires its own permission or the Modify basic permission."},
{"id":"az802-q-173","domain":"Manage storage and file services","text":"What is the effective NTFS permission when a user is granted Allow Read through one group and denied Read through another?","options":["Allow always takes precedence","The first ACE created always wins","The user is automatically an owner","Deny normally takes precedence"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"ورودی‌های صریح Deny (رد دسترسی) معمولاً بر مجوزهای Allow (اجازه دسترسی) مقدم هستند؛ بنابراین، تخصیص‌های Deny باید با احتیاط و آگاهانه استفاده شوند.","en":"Explicit deny entries generally override allows, so deny assignments should be used sparingly and deliberately.","de":"Die richtige Antwort ist „Deny normally takes precedence“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"وقتی به کاربری از طریق یک گروه مجوز Read (خواندن) داده می‌شود و از طریق گروهی دیگر دسترسی Read برای او Deny (رد) می‌شود، مجوز مؤثر NTFS چیست؟","optionsFa":["مجوز Allow (اجازه) همیشه اولویت دارد","اولین ACE ایجاد شده همیشه ملاک عمل است","کاربر به‌طور خودکار مالک می‌شود","مجوز Deny (رد) معمولاً اولویت دارد"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows/win32/secauthz/dacls-and-aces","https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/icacls"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure file systems and NTFS permissions","objectiveId":"storage-file-systems","topic":"NTFS permissions","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows/win32/secauthz/dacls-and-aces","https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/icacls"],"keyPoints":["Explicit Deny entries generally override Allow entries for the same permission.","That is why deny assignments are used sparingly: they can silently block access that allows would otherwise grant.","Inherited denies also apply, and an explicit Allow does not override an inherited explicit Deny."],"whyOthers":["Allow does not always take precedence; the normal rule is that Deny wins for the same right.","The creation order of ACEs does not decide permission outcomes; type, inheritance, and the permission itself do.","Being granted Read does not make a user the owner of the object.",""],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. The practical advice is to grant access through group membership instead of denying it, and to use denial only for narrow exceptions."},
{"id":"az802-q-174","domain":"Manage storage and file services","text":"A user copies a file from one NTFS folder to another on the same volume. What typically happens to permissions?","options":["All permissions are removed","The file becomes encrypted automatically","The destination folder’s inherited permissions apply to the new file","The source permissions always remain unchanged"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"عملیات کپی، فایل جدیدی ایجاد می‌کند که معمولاً مجوزها را از مقصد خود به ارث می‌برد.","en":"Copy creates a new file, which normally inherits permissions from its destination.","de":"Die richtige Antwort ist „The destination folder’s inherited permissions apply to the new file“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کاربری فایلی را از یک پوشه NTFS به پوشه دیگری در همان Volume (پارتیشن) کپی می‌کند. معمولاً چه اتفاقی برای مجوزها (Permissions) می‌افتد؟","optionsFa":["تمام مجوزها حذف می‌شوند","فایل به‌طور خودکار رمزنگاری می‌شود","مجوزهای ارث‌بری‌شده (Inherited permissions) از پوشه مقصد، برای فایل جدید اعمال می‌شوند","مجوزهای فایل مبدأ همیشه بدون تغییر باقی می‌مانند"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/icacls","https://learn.microsoft.com/en-us/windows-server/storage/file-server/ntfs-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure file systems and NTFS permissions","objectiveId":"storage-file-systems","topic":"NTFS permissions","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/icacls","https://learn.microsoft.com/en-us/windows-server/storage/file-server/ntfs-overview"],"keyPoints":["A copy creates a new file at the destination, so the new file inherits the destination folder's permissions.","The original file is left untouched and keeps its own ACL.","This is why copying a file between folders can change who can access the new copy."],"whyOthers":["Permissions are not all removed; the new file receives inherited permissions from the destination.","Copying a file does not encrypt it automatically; encryption is a separate action.","","The source permissions are retained only on the source file, not on the new copy."],"commandPath":[{"label":"Copy a file and preserve its ACL where required","command":"robocopy C:\\Source C:\\Dest report.docx /COPY:DATS /SEC"}],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. A copy is treated as a new object, and inherit-only ACEs on the destination folder apply to it."},
{"id":"az802-q-175","domain":"Manage storage and file services","text":"A user moves a file within the same NTFS volume. What typically happens to its ACL?","options":["The file loses its owner","The existing ACL is retained","The destination ACL always replaces it","The file becomes read-only"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"جابه‌جایی در یک Volume واحد، به جای ایجاد یک فایل جدید، تنها ورودی دایرکتوری (Directory entry) را تغییر می‌دهد.","en":"A same-volume move changes the directory entry rather than creating a new file.","de":"Die richtige Antwort ist „The existing ACL is retained“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کاربری فایلی را در داخل همان Volume (پارتیشن) با فرمت NTFS جابه‌جا می‌کند. معمولاً چه اتفاقی برای ACL آن می‌افتد؟","optionsFa":["فایل مالک خود را از دست می‌دهد","ACL موجود حفظ می‌شود","ACL مقصد همیشه جایگزین آن می‌شود","فایل به حالت «فقط‌خواندنی» (Read-only) درمی‌آید"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/file-server/ntfs-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure file systems and NTFS permissions","objectiveId":"storage-file-systems","topic":"NTFS permissions","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/file-server/ntfs-overview"],"keyPoints":["A move within the same NTFS volume changes the directory entry rather than creating a new file.","Because the file object is unchanged, it keeps its existing explicit ACL.","This is the key difference between a same-volume move and a copy."],"whyOthers":["A move does not remove ownership; the owner persists with the object.","","The destination permissions are not forced on the file for a same-volume move.","Moving a file does not set the read-only attribute."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. A move across volumes is handled as a copy followed by a delete, so the ACL outcome differs and may need explicit preservation."},
{"id":"az802-q-176","domain":"Manage storage and file services","text":"What is the difference between share permissions and NTFS permissions on a shared folder?","options":["Share permissions apply over the share; NTFS permissions apply to the file system","Share permissions apply only locally","NTFS permissions apply only to DNS","They are unrelated to access"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"دسترسی شبکه از طریق هر دو لایه ارزیابی می‌شود و محدودکننده‌ترین نتیجه نهایی، ملاک عمل قرار می‌گیرد.","en":"Network access is evaluated through both layers, and the most restrictive effective result governs.","de":"Die richtige Antwort ist „Share permissions apply over the share; NTFS permissions apply to the file system“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"تفاوت بین مجوزهای Share (اشتراک‌گذاری) و مجوزهای NTFS در یک پوشه اشتراک‌گذاری‌شده چیست؟","optionsFa":["مجوزهای Share بر روی اشتراک اعمال می‌شوند؛ مجوزهای NTFS بر روی سیستم فایل اعمال می‌شوند","مجوزهای Share فقط به صورت محلی (Local) اعمال می‌شوند","مجوزهای NTFS فقط برای DNS اعمال می‌شوند","آن‌ها ارتباطی با دسترسی ندارند"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/file-server/smb-security","https://learn.microsoft.com/en-us/windows-server/storage/file-server/ntfs-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure and manage file shares and SMB","objectiveId":"storage-shares","topic":"Share and NTFS permissions","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/file-server/smb-security","https://learn.microsoft.com/en-us/windows-server/storage/file-server/ntfs-overview"],"keyPoints":["Share permissions apply to access over the network share and are evaluated when a client connects to the share.","NTFS permissions apply to the file system itself and are evaluated for both local and network access.","When both apply, the most restrictive result is the effective permission the user receives."],"whyOthers":["","Share permissions apply over the network share rather than only locally.","NTFS permissions have nothing to do with DNS; they govern file-system objects.","Both permission layers are directly related to access, so the last option is incorrect."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Local access on the server is governed by NTFS alone, which is why a share-level Deny does not affect a user logged on locally."},
{"id":"az802-q-177","domain":"Manage storage and file services","text":"Which share permission model is commonly recommended when detailed access control is managed with NTFS?","options":["Grant Everyone Full Control and ignore NTFS","Deny all share access and use local access","Use DNS permissions","Set broad share access and use NTFS ACLs for granular control"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"یک لایه اشتراک‌گذاری یکدست از هم‌پوشانی‌های گیج‌کننده جلوگیری می‌کند، در حالی که NTFS مجوزهای دقیق در سطح فایل را فراهم می‌آورد.","en":"A consistent share layer avoids confusing overlaps while NTFS provides detailed file-level authorization.","de":"Die richtige Antwort ist „Set broad share access and use NTFS ACLs for granular control“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"هنگامی که کنترل دقیق دسترسی توسط NTFS مدیریت می‌شود، معمولاً کدام مدل مجوز Share توصیه می‌شود؟","optionsFa":["اعطای دسترسی کامل (Full Control) به همه و نادیده گرفتن NTFS","مسدود کردن (Deny) تمام دسترسی‌های اشتراکی و استفاده از دسترسی محلی","استفاده از مجوزهای DNS","تعیین دسترسی اشتراکی گسترده و استفاده از ACLهای NTFS برای کنترل دقیق و جزئی"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/file-server/smb-security","https://learn.microsoft.com/en-us/windows-server/storage/file-server/ntfs-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure and manage file shares and SMB","objectiveId":"storage-shares","topic":"Share and NTFS permissions","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/file-server/smb-security","https://learn.microsoft.com/en-us/windows-server/storage/file-server/ntfs-overview"],"keyPoints":["A common pattern is to grant broad share access and enforce the real control with NTFS ACLs.","This keeps one authoritative place for granular permissions instead of two layers that can conflict.","It also avoids confusion when share and NTFS permissions disagree, since the restrictive result wins."],"whyOthers":["Granting Everyone Full Control and relying only on the share ignores NTFS entirely and is not the recommended model.","Denying all share access stops file access over the network rather than providing control.","DNS permissions are a name-resolution concept and do not control file access.",""],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. On modern Windows Server the default share permission for new shares is Read for Everyone, which is why NTFS must carry the real design."},
{"id":"az802-q-178","domain":"Manage storage and file services","text":"What is the purpose of SMB signing?","options":["Allocate IP addresses","Create a DNS record","Help authenticate messages and detect tampering in SMB traffic","Compress every file"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"قابلیت SMB signing از یکپارچگی پیام محافظت کرده و به جلوگیری از برخی حملات «مرد میانی» (man-in-the-middle) کمک می‌کند.","en":"SMB signing protects message integrity and helps prevent certain man-in-the-middle attacks.","de":"Die richtige Antwort ist „Help authenticate messages and detect tampering in SMB traffic“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"هدف از SMB signing چیست؟","optionsFa":["تخصیص آدرس‌های IP","ایجاد یک رکورد DNS","کمک به احراز هویت پیام‌ها و تشخیص دستکاری در ترافیک SMB","فشرده‌سازی تمام فایل‌ها"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/file-server/smb-security"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure and manage file shares and SMB","objectiveId":"storage-shares","topic":"SMB security","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/file-server/smb-security"],"keyPoints":["SMB signing adds a cryptographic signature to SMB messages so the receiver can verify authenticity and detect tampering.","It helps prevent man-in-the-middle attacks that would otherwise relay or alter SMB traffic.","It can be required or optional, and requiring it is a common hardening step."],"whyOthers":["SMB signing does not allocate IP addresses; DHCP does that.","It does not create DNS records.","","It does not compress files."],"commandPath":[{"label":"Check SMB signing configuration on the server","command":"Get-SmbServerConfiguration | Select-Object RequireSecuritySignature, EnableSecuritySignature"},{"label":"Require SMB signing on the server","command":"Set-SmbServerConfiguration -RequireSecuritySignature $true -Force"}],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Requiring signing can reduce throughput slightly because of the extra cryptographic work, and every client must support it."},
{"id":"az802-q-179","domain":"Manage storage and file services","text":"What is the purpose of SMB encryption?","options":["Create a DFS namespace","Protect SMB data in transit from eavesdropping","Encrypt the disk at rest","Replace NTFS ACLs"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"رمزنگاری SMB نشست (session) شبکه را ایمن می‌کند؛ این روش با BitLocker که از داده‌های ساکن (ذخیره‌شده) محافظت می‌کند، متفاوت است.","en":"SMB encryption secures the network session; it is different from BitLocker, which protects data at rest.","de":"Die richtige Antwort ist „Protect SMB data in transit from eavesdropping“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"هدف از رمزنگاری SMB چیست؟","optionsFa":["ایجاد یک فضای نام (namespace) DFS","محافظت از داده‌های SMB در حال انتقال در برابر استراق سمع","رمزنگاری دیسک در حالت سکون (at rest)","جایگزینی ACLهای NTFS"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/file-server/smb-security"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure and manage file shares and SMB","objectiveId":"storage-shares","topic":"SMB security","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/file-server/smb-security"],"keyPoints":["SMB encryption protects SMB data while it travels across the network.","It is different from BitLocker, which encrypts data at rest on the disk.","Encryption can be enabled per share or for the whole server."],"whyOthers":["SMB encryption does not create a DFS namespace; namespaces are a separate feature.","","It does not encrypt the disk at rest; that is BitLocker or another volume encryption technology.","It does not replace NTFS ACLs, which still govern authorization."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. SMB encryption requires clients that support SMB 3.0 or later, so older clients cannot connect to an encrypted share."},
{"id":"az802-q-180","domain":"Manage storage and file services","text":"Which newer SMB transport can operate over QUIC for secure access across untrusted networks?","options":["SMB over QUIC","SMB over FTP","SMB over DNS","SMB over Telnet"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"پروتکل SMB بر بستر QUIC از لایه انتقال QUIC/TLS استفاده می‌کند تا دسترسی ایمن به فایل‌ها را بدون نیاز به در معرض قرار دادن پورت سنتی TCP 445 فراهم آورد.","en":"SMB over QUIC uses QUIC/TLS transport to provide secure file access without relying on traditional TCP 445 exposure.","de":"Die richtige Antwort ist „SMB over QUIC“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام روش انتقال جدیدتر SMB می‌تواند برای دسترسی ایمن در شبکه‌های غیرقابل‌اعتماد، بر بستر QUIC عمل کند؟","optionsFa":["SMB بر بستر QUIC","SMB بر بستر FTP","SMB بر بستر DNS","SMB بر بستر Telnet"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/file-server/smb-over-quic","https://learn.microsoft.com/en-us/windows-server/storage/file-server/smb-security"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure and manage file shares and SMB","objectiveId":"storage-shares","topic":"SMB security","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/file-server/smb-over-quic","https://learn.microsoft.com/en-us/windows-server/storage/file-server/smb-security"],"keyPoints":["SMB over QUIC carries SMB inside a QUIC/TLS session, which is designed for secure access across untrusted networks such as the internet.","It removes the need to expose the traditional TCP 445 port to the internet.","It relies on certificates to establish trust for the server."],"whyOthers":["","SMB over FTP is not a Windows Server capability; FTP is a separate file-transfer protocol.","SMB over DNS is not a protocol option; DNS is a name-resolution service.","SMB over Telnet is not a capability, and Telnet is unencrypted and unsuitable for file access."],"requirements":"Applies to Windows Server 2022 and later releases that support SMB over QUIC. The feature requires a certificate on the server and a client that supports the QUIC transport."},
{"id":"az802-q-181","domain":"Manage storage and file services","text":"What is a DFS namespace?","options":["A DNS reverse zone","A DHCP scope","A VM storage controller","A logical path that presents shared folders from one or more file servers"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"فضاهای نام DFS ضمن پنهان کردن موقعیت مکانی سرورهای پشتیبان (backend)، یک مسیر دسترسی یکپارچه و ثابت فراهم می‌کنند.","en":"DFS namespaces provide a consistent access path while hiding backend server locations.","de":"Die richtige Antwort ist „A logical path that presents shared folders from one or more file servers“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"فضای نام (namespace) DFS چیست؟","optionsFa":["یک ناحیه معکوس (reverse zone) در DNS","یک محدوده (scope) در DHCP","یک کنترل‌کننده ذخیره‌سازی ماشین مجازی (VM)","یک مسیر منطقی که پوشه‌های اشتراک‌گذاری‌شده از یک یا چند سرور فایل را نمایش می‌دهد"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/dfs-namespaces/dfs-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure DFS namespaces and replication","objectiveId":"storage-dfs","topic":"DFS namespaces","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/dfs-namespaces/dfs-overview"],"keyPoints":["A DFS namespace presents a logical path such as \\\\contoso.com\\Shares\\Finance\\Reports.","Behind that path, the namespace maps folders to targets on one or more file servers.","Users keep a stable path even when the underlying servers change."],"whyOthers":["A DNS reverse zone maps addresses back to names and is not a file-access path.","A DHCP scope defines addresses for a subnet and is unrelated.","A virtual machine storage controller attaches disks to a guest and is not a namespace.",""],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. A namespace can be domain-based, which stores its configuration in AD DS, or standalone, which stores it on the namespace server."},
{"id":"az802-q-182","domain":"Manage storage and file services","text":"What does DFS Replication do?","options":["Replicate DHCP leases only","Encrypt every SMB session","Replicate files between selected folders on multiple servers","Replicate all AD objects"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"سرویس DFSR قابلیت تکثیر فایل به روش چند-میزبان (multi-master) را برای پوشه‌ها و فضاهای نام (namespaces) پشتیبانی‌شده فراهم می‌کند.","en":"DFSR provides multi-master file replication for supported folders and namespaces.","de":"Die richtige Antwort ist „Replicate files between selected folders on multiple servers“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"عملکرد DFS Replication چیست؟","optionsFa":["فقط تکثیر (Replicate) اجاره‌های DHCP","رمزنگاری تمام نشست‌های (sessions) SMB","تکثیر فایل‌ها بین پوشه‌های انتخاب‌شده در چندین سرور","تکثیر تمام اشیاء AD (Active Directory)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/dfs-replication/dfsr-overview","https://learn.microsoft.com/en-us/windows-server/storage/dfs-namespaces/dfs-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure DFS namespaces and replication","objectiveId":"storage-dfs","topic":"DFS Replication","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/dfs-replication/dfsr-overview","https://learn.microsoft.com/en-us/windows-server/storage/dfs-namespaces/dfs-overview"],"keyPoints":["DFS Replication (DFSR) replicates files between selected folders on multiple servers using a multi-master model.","It also replicates SYSVOL in modern AD DS domains.","It uses remote differential compression so only the changed parts of a file are transferred."],"whyOthers":["DFSR does not replicate DHCP leases; DHCP failover does that.","It does not encrypt SMB sessions; SMB encryption does that.","","It does not replicate all AD objects; directory replication handles those."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. DFSR is the current SYSVOL replication engine, and it must be configured with replication groups and members before data moves."},
{"id":"az802-q-183","domain":"Manage storage and file services","text":"A DFS namespace has targets in two sites. Which feature helps direct clients to a nearby target?","options":["DHCP reservations","Site costing and referral ordering","DNSSEC only","NTFS compression"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"ارجاعات DFS می‌توانند از توپولوژی سایت‌های AD برای اولویت دادن به مقصدهای محلی و کاهش ترافیک WAN استفاده کنند.","en":"DFS referrals can use AD site topology to prefer local targets and reduce WAN traffic.","de":"Die richtige Antwort ist „Site costing and referral ordering“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"یک فضای نام DFS دارای مقصدهایی (targets) در دو سایت است. کدام ویژگی به هدایت کلاینت‌ها به سمت نزدیک‌ترین مقصد کمک می‌کند؟","optionsFa":["رزروهای DHCP","تعیین هزینه سایت (Site costing) و ترتیب ارجاع (referral ordering)","فقط DNSSEC","فشرده‌سازی NTFS"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/dfs-namespaces/dfs-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure DFS namespaces and replication","objectiveId":"storage-dfs","topic":"DFS namespaces","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/dfs-namespaces/dfs-overview"],"keyPoints":["DFS referrals can use AD site topology to prefer namespace targets that are in the client's own site.","This keeps clients reading from a nearby server and reduces traffic across the WAN.","Referral ordering depends on target priority, site costing, and whether a local target exists."],"whyOthers":["DHCP reservations assign addresses and do not influence DFS target selection.","","DNSSEC signs DNS data and has no role in referral ordering.","NTFS compression reduces file size on disk and does not direct clients to a nearby target."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Site-aware referrals require the client's subnet to be mapped to the correct AD site, otherwise the client has no local target to prefer."},
{"id":"az802-q-184","domain":"Manage storage and file services","text":"Which DFS namespace type requires domain-based AD DS integration?","options":["Domain-based namespace","Standalone namespace","FAT namespace","DHCP namespace"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"فضاهای نام مبتنی بر دامنه، پیکربندی خود را در AD DS ذخیره می‌کنند و امکان مدیریت یکپارچه با دامنه را فراهم می‌سازند.","en":"Domain-based namespaces store configuration in AD DS and provide domain-integrated management.","de":"Die richtige Antwort ist „Domain-based namespace“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام نوع فضای نام (namespace) در DFS نیازمند یکپارچه‌سازی با AD DS مبتنی بر دامنه است؟","optionsFa":["فضای نام مبتنی بر دامنه (Domain-based namespace)","فضای نام مستقل (Standalone namespace)","فضای نام FAT","فضای نام DHCP"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/dfs-namespaces/dfs-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure DFS namespaces and replication","objectiveId":"storage-dfs","topic":"DFS namespaces","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/dfs-namespaces/dfs-overview"],"keyPoints":["A domain-based namespace stores its configuration in AD DS and uses the domain name in its path.","It supports multiple namespace servers, which provides fault tolerance for the namespace itself.","A standalone namespace stores its configuration on one server and does not use AD DS."],"whyOthers":["","A standalone namespace stores configuration locally and is not AD-integrated.","There is no FAT namespace type.","There is no DHCP namespace type."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. A domain-based namespace requires the domain functional level to support Windows Server 2008 mode to use the newer namespace features."},
{"id":"az802-q-185","domain":"Manage storage and file services","text":"What is an FSRM quota?","options":["A DNS request limit","A DHCP lease limit","A VM CPU limit","A limit on the amount of data that can be stored in a folder or volume"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"سهمیه‌های FSRM میزان مصرف ظرفیت را کنترل می‌کنند و می‌توانند در صورت رسیدن به آستانه‌های تعیین‌شده، اعلان‌ها یا اقداماتی را فعال نمایند.","en":"FSRM quotas control capacity usage and can trigger notifications or actions at thresholds.","de":"Die richtige Antwort ist „A limit on the amount of data that can be stored in a folder or volume“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"سهمیه (Quota) در FSRM چیست؟","optionsFa":["محدودیت درخواست‌های DNS","محدودیت اجاره (lease) در DHCP","محدودیت پردازنده (CPU) برای ماشین مجازی (VM)","محدودیت در حجم داده‌های قابل ذخیره‌سازی در یک پوشه یا حجم (volume)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/fsrm/fsrm-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage file-server resource manager and deduplication","objectiveId":"storage-fsrm","topic":"FSRM quotas","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/fsrm/fsrm-overview"],"keyPoints":["An FSRM quota limits how much data a folder or volume may hold.","A quota can be hard, which blocks writes beyond the limit, or soft, which only notifies.","Threshold notifications can warn at percentages before the limit is reached."],"whyOthers":["A DNS request limit is not a thing that FSRM quotas control.","A DHCP lease limit is not an FSRM quota.","A virtual machine CPU limit is a Hyper-V setting and is unrelated to storage quotas.",""],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 with the File Server Resource Manager role service installed. Quotas are applied to a path, and inheritance to subfolders can be enabled."},
{"id":"az802-q-186","domain":"Manage storage and file services","text":"What is file screening in FSRM used for?","options":["Allocate IP addresses","Replicate SYSVOL","Block or monitor files based on file groups or extensions","Encrypt file names"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"قابلیت File Screening به جلوگیری از ذخیره‌سازی انواع فایل‌های ناخواسته در مکان‌های تحت کنترل کمک می‌کند.","en":"File screens help prevent unwanted file types from being stored in controlled locations.","de":"Die richtige Antwort ist „Block or monitor files based on file groups or extensions“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"قابلیت File Screening (غربالگری فایل) در FSRM چه کاربردی دارد؟","optionsFa":["تخصیص آدرس‌های IP","تکثیر (Replicate) پوشه SYSVOL","مسدودسازی یا نظارت بر فایل‌ها بر اساس گروه‌های فایل یا پسوندها","رمزنگاری نام فایل‌ها"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/fsrm/create-file-screen-template","https://learn.microsoft.com/en-us/windows-server/storage/fsrm/fsrm-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage file-server resource manager and deduplication","objectiveId":"storage-fsrm","topic":"File screening","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/fsrm/create-file-screen-template","https://learn.microsoft.com/en-us/windows-server/storage/fsrm/fsrm-overview"],"keyPoints":["File screening blocks or monitors files based on file groups and extensions.","An active screen prevents the unwanted files from being saved; a passive screen only reports them.","It is commonly used to keep media files, executables, or other unwanted types off controlled shares."],"whyOthers":["File screening does not allocate IP addresses.","It does not replicate SYSVOL.","","It does not encrypt file names."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 with FSRM installed. File groups define which extensions belong together, and screens are applied to specific paths."},
{"id":"az802-q-187","domain":"Manage storage and file services","text":"Which FSRM feature provides reports about storage usage and file types?","options":["Hyper-V Replica","Storage reports","AD Recycle Bin","DNS scavenging"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"گزارش‌های ذخیره‌سازی FSRM اطلاعاتی را درباره فایل‌ها، مالکان، فایل‌های تکراری، سهمیه‌ها (Quotas) و الگوهای استفاده خلاصه می‌کنند.","en":"FSRM storage reports summarize files, owners, duplicates, quotas, and usage patterns.","de":"Die richtige Antwort ist „Storage reports“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام قابلیت FSRM گزارش‌هایی درباره میزان استفاده از فضای ذخیره‌سازی و انواع فایل‌ها ارائه می‌دهد؟","optionsFa":["Hyper-V Replica","Storage reports (گزارش‌های ذخیره‌سازی)","AD Recycle Bin","DNS scavenging"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/fsrm/fsrm-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage file-server resource manager and deduplication","objectiveId":"storage-fsrm","topic":"FSRM reports","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/fsrm/fsrm-overview"],"keyPoints":["FSRM storage reports summarise files, owners, duplicates, quotas, and usage patterns for chosen paths.","Reports can be run on demand or on a schedule and saved in several formats.","They are the auditing tool for understanding where storage is being consumed."],"whyOthers":["Hyper-V Replica replicates virtual machines and does not produce storage reports.","","AD Recycle Bin recovers deleted directory objects.","DNS scavenging removes stale DNS records."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 with FSRM installed. Running reports requires the Windows Search and File Server Resource Manager services to be healthy."},
{"id":"az802-q-188","domain":"Manage storage and file services","text":"What does data deduplication do?","options":["Store repeated data patterns once while presenting the same logical files","Delete duplicate user accounts","Remove duplicate DNS records only","Clone a VM into memory"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"قابلیت حذف داده‌های تکراری با شناسایی و ذخیره‌سازی کارآمدِ بخش‌های (Chunks) تکراری، میزان مصرف فضای ذخیره‌سازی را کاهش می‌دهد.","en":"Deduplication reduces storage consumption by identifying and storing repeated chunks efficiently.","de":"Die richtige Antwort ist „Store repeated data patterns once while presenting the same logical files“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"قابلیت حذف داده‌های تکراری (Data Deduplication) چه کاری انجام می‌دهد؟","optionsFa":["ذخیره الگوهای داده‌ای تکراری تنها برای یک بار، در حالی که همان فایل‌های منطقی (Logical Files) نمایش داده می‌شوند","حذف حساب‌های کاربری تکراری","حذف تنها رکوردهای تکراری DNS","ایجاد یک کپی (Clone) از ماشین مجازی در حافظه"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/data-deduplication/overview","https://learn.microsoft.com/en-us/windows-server/storage/data-deduplication/understand"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage file-server resource manager and deduplication","objectiveId":"storage-fsrm","topic":"Data deduplication","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/data-deduplication/overview","https://learn.microsoft.com/en-us/windows-server/storage/data-deduplication/understand"],"keyPoints":["Data deduplication finds repeated patterns in data and stores a single copy while presenting the same logical files.","Clients and applications continue to see the files as normal; the savings happen under the file system.","It is applied per volume and is most effective where files share a lot of common data."],"whyOthers":["","It does not delete duplicate user accounts; that is a directory operation.","It does not target DNS records specifically.","It does not clone a virtual machine into memory."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Deduplication is not supported for the operating system volume, and it requires planning for the optimization schedule and the volume's free space."},
{"id":"az802-q-189","domain":"Manage storage and file services","text":"Which workload should be evaluated carefully before enabling deduplication?","options":["A normal archive share","A supported backup repository","A supported general-purpose file share","A workload with unsupported or latency-sensitive files"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"سازگاری و عملکرد به نوع بار کاری، الگوی فایل و موارد استفاده‌ی پشتیبانی‌شده برای حذف داده‌های تکراری بستگی دارد.","en":"Compatibility and performance depend on workload type, file pattern, and supported deduplication usage.","de":"Die richtige Antwort ist „A workload with unsupported or latency-sensitive files“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"پیش از فعال‌سازی قابلیت حذف داده‌های تکراری (Deduplication)، کدام بار کاری (Workload) باید به‌دقت ارزیابی شود؟","optionsFa":["یک اشتراک‌گذاری (Share) معمولی برای آرشیو","یک مخزن پشتیبان‌گیری (Backup repository) پشتیبانی‌شده","یک اشتراک‌گذاری فایل با کاربرد عمومی و پشتیبانی‌شده","باری کاری شامل فایل‌های پشتیبانی‌نشده یا فایل‌های حساس به تأخیر (Latency-sensitive)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/data-deduplication/overview","https://learn.microsoft.com/en-us/windows-server/storage/data-deduplication/understand"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage file-server resource manager and deduplication","objectiveId":"storage-fsrm","topic":"Data deduplication","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/data-deduplication/overview","https://learn.microsoft.com/en-us/windows-server/storage/data-deduplication/understand"],"keyPoints":["Deduplication should be evaluated per workload because compatibility and performance depend on the file types and access pattern.","Latency-sensitive and certain database or virtual machine files are not supported workloads.","Supported file shares and backup repositories are the typical, safe use cases."],"whyOthers":["A normal archive share is a well-suited workload for deduplication.","A supported backup repository is a documented and common use case.","A supported general-purpose file share is also a documented use case.",""],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Deduplication estimates savings before it is enabled so the benefit can be assessed against the extra processing."},
{"id":"az802-q-190","domain":"Manage storage and file services","text":"What is Storage Spaces used for?","options":["Provide DNS recursion","Run DHCP failover","Pool physical disks and create virtual disks with resiliency layouts","Manage AD trusts"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"قابلیت Storage Spaces دیسک‌های فیزیکی را در قالب مجموعه‌ها (Pools) و دیسک‌های مجازی انتزاع می‌کند و گزینه‌هایی مانند Mirror و Parity را ارائه می‌دهد.","en":"Storage Spaces abstracts physical disks into pools and virtual disks with options such as mirror and parity.","de":"Die richtige Antwort ist „Pool physical disks and create virtual disks with resiliency layouts“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کاربرد Storage Spaces چیست؟","optionsFa":["فراهم کردن قابلیت بازگشتی (Recursion) در DNS","اجرای قابلیت Failover برای DHCP","ایجاد مجموعه‌ای (Pool) از دیسک‌های فیزیکی و ساخت دیسک‌های مجازی با طرح‌بندی‌های دارای قابلیت تاب‌آوری (Resiliency)","مدیریت روابط اعتماد (Trusts) در Active Directory"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/storage-spaces/overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure Storage Spaces and Storage Spaces Direct","objectiveId":"storage-spaces","topic":"Storage Spaces","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/storage-spaces/overview"],"keyPoints":["Storage Spaces pools physical disks into a storage pool and then creates virtual disks from it.","Each virtual disk can use a layout such as simple, mirror, or parity to trade capacity against resiliency.","It abstracts the physical media so volumes can span disks and survive failures."],"whyOthers":["Storage Spaces does not provide DNS recursion; that is a DNS server function.","It does not run DHCP failover; that is a DHCP feature.","","It does not manage AD trusts."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Supported disks are added to a pool and left out of traditional volumes, so the disks must be dedicated to Storage Spaces."},
{"id":"az802-q-191","domain":"Manage storage and file services","text":"Which Storage Spaces layout generally provides redundancy by keeping multiple copies of data?","options":["Cache-only","Mirror","Simple","Temporary"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"فضاهای Mirror نسخه‌های افزونه (Redundant) را ذخیره می‌کنند و معمولاً عملکرد نوشتن بهتری نسبت به حالت Parity ارائه می‌دهند.","en":"Mirrored spaces store redundant copies and typically provide better write performance than parity.","de":"Die richtige Antwort ist „Mirror“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام طرح‌بندی (Layout) در Storage Spaces معمولاً با نگهداری چندین نسخه از داده‌ها، افزونگی (Redundancy) ایجاد می‌کند؟","optionsFa":["Cache-only (فقط کش)","Mirror (آینه‌ای)","Simple (ساده)","Temporary (موقت)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/storage-spaces/overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure Storage Spaces and Storage Spaces Direct","objectiveId":"storage-spaces","topic":"Storage Spaces","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/storage-spaces/overview"],"keyPoints":["A mirror layout keeps multiple copies of the data, so a disk failure does not lose the data.","Mirroring typically provides better write performance than parity.","The cost is that usable capacity is reduced because copies are stored."],"whyOthers":["Cache-only is not a resiliency layout.","","A simple layout has no redundancy, so a single disk failure can lose the data.","Temporary is not a Storage Spaces resiliency layout."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. A two-way mirror requires at least two disks, and a three-way mirror trades more capacity for greater fault tolerance."},
{"id":"az802-q-192","domain":"Manage storage and file services","text":"Which layout generally trades write performance for efficient capacity through calculated parity?","options":["Parity","Simple","Mirror only","Boot"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"فضاهای مبتنی بر پاریتی (Parity spaces) از اطلاعات پاریتی برای ایجاد تاب‌آوری (resiliency) با ظرفیت قابل‌استفاده‌ی بیشتر نسبت به روش آینه‌سازی کامل (full mirroring) استفاده می‌کنند، اما عملیات نوشتن در آن‌ها می‌تواند پیچیده‌تر باشد.","en":"Parity spaces use parity information to provide resiliency with better usable capacity than full mirroring, but writes can be more complex.","de":"Die richtige Antwort ist „Parity“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام چیدمان (Layout) معمولاً برای دستیابی به ظرفیت کارآمد از طریق «پاریتی» (Parity) محاسبه‌شده، عملکرد نوشتن را فدا می‌کند؟","optionsFa":["Parity (پاریتی)","Simple (ساده)","Mirror only (فقط آینه‌ای)","Boot (بوت)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/storage-spaces/overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure Storage Spaces and Storage Spaces Direct","objectiveId":"storage-spaces","topic":"Storage Spaces","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/storage-spaces/overview"],"keyPoints":["A parity layout stores parity information so data can be rebuilt if a disk fails.","It provides better usable capacity than mirroring but writes involve parity calculation, which can reduce write performance.","Parity is a good fit for sequential and archive workloads rather than write-heavy random workloads."],"whyOthers":["","A simple layout provides no redundancy at all.","A mirror layout keeps full copies and therefore uses more capacity than parity.","Boot is not a Storage Spaces resiliency layout."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Single parity tolerates one disk failure while dual parity tolerates two, and both require enough disks to reconstruct the data."},
{"id":"az802-q-193","domain":"Manage storage and file services","text":"What does Storage Spaces Direct (S2D) provide?","options":["A DNS namespace","A DHCP relay","A local user database","Software-defined storage across disks in multiple cluster nodes"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"قابلیت S2D درایوهای محلی سرورهای مختلف را تجمیع کرده و به یک فضای ذخیره‌سازی کلاسترشده تبدیل می‌کند که توسط ویندوز سرور مدیریت می‌شود.","en":"S2D aggregates local drives across servers into clustered storage managed by Windows Server.","de":"Die richtige Antwort ist „Software-defined storage across disks in multiple cluster nodes“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"قابلیت Storage Spaces Direct (S2D) چه چیزی را فراهم می‌کند؟","optionsFa":["یک فضای نام DNS","یک رله DHCP","یک پایگاه داده کاربران محلی","فضای ذخیره‌سازی نرم‌افزار-محور (Software-defined storage) در دیسک‌های موجود در گره‌های (nodes) متعدد کلاستر"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/storage-spaces/storage-spaces-direct-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure Storage Spaces and Storage Spaces Direct","objectiveId":"storage-spaces","topic":"Storage Spaces Direct","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/storage-spaces/storage-spaces-direct-overview"],"keyPoints":["Storage Spaces Direct aggregates the local drives of multiple cluster nodes into software-defined storage.","It enables hyper-converged and converged designs without shared storage hardware.","Volumes are then created with resiliency across the nodes rather than within a single server."],"whyOthers":["S2D does not provide a DNS namespace.","It does not provide a DHCP relay.","It does not provide a local user database.",""],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 Datacenter. S2D requires a failover cluster of supported servers with compatible, dedicated disks."},
{"id":"az802-q-194","domain":"Manage storage and file services","text":"Which prerequisite is central to an S2D cluster?","options":["One disk in one server","A disabled firewall","Supported servers, compatible disks, and validated cluster networking","A public DNS server only"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"فناوری S2D به سخت‌افزار پشتیبانی‌شده و ارتباطات سریع و قابل‌اطمینانِ درون‌کلاستری (east-west) وابسته است.","en":"S2D relies on supported hardware and fast, reliable east-west cluster communication.","de":"Die richtige Antwort ist „Supported servers, compatible disks, and validated cluster networking“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام پیش‌نیاز برای یک کلاستر S2D حیاتی است؟","optionsFa":["یک دیسک در یک سرور","فایروال غیرفعال","سرورهای پشتیبانی‌شده، دیسک‌های سازگار و شبکه کلاسترِ تأییدشده (معتبرسازی‌شده)","فقط یک سرور DNS عمومی"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/storage-spaces/storage-spaces-direct-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure Storage Spaces and Storage Spaces Direct","objectiveId":"storage-spaces","topic":"Storage Spaces Direct","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/storage-spaces/storage-spaces-direct-overview"],"keyPoints":["S2D requires supported servers, compatible disks, and validated cluster networking.","The east-west traffic between nodes carries the storage replication, so fast, low-latency networking is essential.","Hardware must be validated because unsupported components cause cluster and storage failures."],"whyOthers":["One disk in one server cannot provide storage across nodes.","Disabling the firewall is not a requirement and would weaken the cluster.","","A public DNS server is not the central prerequisite for S2D; cluster networking and disks are."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 Datacenter. The Cluster Validation Wizard should pass with no storage warnings before S2D is enabled."},
{"id":"az802-q-195","domain":"Manage storage and file services","text":"What is Storage Replica designed to provide?","options":["User-profile redirection","Synchronous or asynchronous replication of volumes between servers or clusters","DNS record replication","DHCP scope balancing"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"قابلیت Storage Replica از بازیابی پس از فاجعه (Disaster Recovery) و انتقال سرویس (Failover) برنامه‌ریزی‌شده برای داده‌های حجم در سطح بلوک (Block-level) پشتیبانی می‌کند.","en":"Storage Replica supports disaster recovery and planned failover for block-level volume data.","de":"Die richtige Antwort ist „Synchronous or asynchronous replication of volumes between servers or clusters“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"هدف از طراحی Storage Replica چیست؟","optionsFa":["تغییر مسیر (Redirection) پروفایل کاربر","تکثیر (Replication) همگام یا ناهمگامِ حجم‌ها (Volumes) بین سرورها یا کلاسترها","تکثیر رکوردهای DNS","متعادل‌سازی محدوده (Scope) در DHCP"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/storage-replica/storage-replica-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure storage replication, QoS, and iSCSI","objectiveId":"storage-block","topic":"Storage Replica","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/storage-replica/storage-replica-overview"],"keyPoints":["Storage Replica replicates volumes at the block level between servers or clusters.","It supports both synchronous and asynchronous replication.","It is used for disaster recovery and planned failover of whole volumes."],"whyOthers":["User-profile redirection is a file-access configuration and is not block replication.","","Storage Replica does not replicate DNS records.","It does not balance DHCP scopes."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 Datacenter. Storage Replica requires Windows Server Datacenter edition and a log volume plus a data volume on each side."},
{"id":"az802-q-196","domain":"Manage storage and file services","text":"What is the key trade-off of synchronous Storage Replica?","options":["It requires low-latency connectivity because writes are acknowledged after both copies are updated","It never consumes bandwidth","It works only with public DNS","It cannot fail over"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"تکثیر همگام، اهداف نقطه بازیابی (RPO) را بهبود می‌بخشد اما باعث افزایش تأخیر و نیازهای شبکه می‌شود.","en":"Synchronous replication improves recovery point objectives but adds latency and network requirements.","de":"Die richtige Antwort ist „It requires low-latency connectivity because writes are acknowledged after both copies are updated“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"چالش یا موازنه اصلی (Trade-off) در حالت همگامِ Storage Replica چیست؟","optionsFa":["به اتصال با تأخیر کم (Low-latency) نیاز دارد، زیرا تأیید عملیات نوشتن پس از به‌روزرسانی هر دو نسخه صادر می‌شود","هرگز پهنای باند مصرف نمی‌کند","فقط با DNS عمومی کار می‌کند","قابلیت Failover ندارد"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/storage-replica/storage-replica-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure storage replication, QoS, and iSCSI","objectiveId":"storage-block","topic":"Storage Replica","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/storage-replica/storage-replica-overview"],"keyPoints":["In synchronous replication, a write is acknowledged only after both copies are updated.","That gives an aggressive recovery point objective, effectively no data loss on a clean failover.","The trade-off is that latency between the sites directly affects write performance, so it needs a low-latency link."],"whyOthers":["","Synchronous replication consumes bandwidth because every write is copied to the second site.","It does not depend on public DNS.","It absolutely supports failover; that is its purpose."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 Datacenter. Asynchronous replication is used when the link latency is too high for synchronous acknowledgement."},
{"id":"az802-q-197","domain":"Manage storage and file services","text":"What is SMB Direct?","options":["SMB over public DNS","A file-screening rule","A DHCP extension","SMB using RDMA-capable network adapters for low-latency, low-CPU data transfer"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"قابلیت SMB Direct از RDMA برای کاهش سربار پردازنده و بهبود نرخ انتقال داده (Throughput) در بارهای کاریِ پشتیبانی‌شده استفاده می‌کند.","en":"SMB Direct uses RDMA to reduce CPU overhead and improve throughput for supported workloads.","de":"Die richtige Antwort ist „SMB using RDMA-capable network adapters for low-latency, low-CPU data transfer“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"SMB Direct چیست؟","optionsFa":["پروتکل SMB بر بستر DNS عمومی","یک قانون غربالگری فایل (File-screening rule)","یک افزونه DHCP","استفاده از SMB با آداپتورهای شبکه دارای قابلیت RDMA برای انتقال داده با تأخیر کم و بار پردازشی (CPU) ناچیز"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/file-server/smb-direct","https://learn.microsoft.com/en-us/windows-server/storage/file-server/smb-security"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure storage replication, QoS, and iSCSI","objectiveId":"storage-block","topic":"SMB Direct","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/file-server/smb-direct","https://learn.microsoft.com/en-us/windows-server/storage/file-server/smb-security"],"keyPoints":["SMB Direct uses RDMA-capable network adapters to transfer SMB data with low latency and low CPU overhead.","The network adapter performs the data movement, which frees the processor for other work.","It is used for high-throughput workloads such as file servers, Hyper-V storage, and Storage Spaces Direct."],"whyOthers":["SMB over public DNS is not a supported transport concept.","A file-screening rule is an FSRM policy, not a transport.","A DHCP extension concerns addressing and is unrelated.",""],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. SMB Direct requires RDMA-capable adapters (RoCE or iWARP) with matching configuration, and it works best on dedicated storage networks."},
{"id":"az802-q-198","domain":"Manage storage and file services","text":"What is Storage Quality of Service (QoS) used for?","options":["Control DNS TTL","Control DHCP reservations","Control or monitor storage IOPS and bandwidth for virtual disks","Control password complexity"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"قابلیت QoS در فضای ذخیره‌سازی کمک می‌کند تا از مصرف نامتناسب منابع عملکردی توسط بارهای کاریِ «همسایه پرسر‌وصدا» (noisy-neighbor) جلوگیری شود.","en":"Storage QoS helps prevent noisy-neighbor workloads from consuming disproportionate storage performance.","de":"Die richtige Antwort ist „Control or monitor storage IOPS and bandwidth for virtual disks“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کاربرد «کیفیت خدمات (QoS) در فضای ذخیره‌سازی» چیست؟","optionsFa":["کنترل TTL در DNS","کنترل رزروهای DHCP","کنترل یا نظارت بر IOPS و پهنای باند فضای ذخیره‌سازی برای دیسک‌های مجازی","کنترل پیچیدگی رمز عبور"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/storage-qos/storage-qos-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure storage replication, QoS, and iSCSI","objectiveId":"storage-block","topic":"Storage QoS","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/storage-qos/storage-qos-overview"],"keyPoints":["Storage Quality of Service controls or monitors the IOPS and bandwidth a virtual disk may consume.","It prevents a single virtual machine from monopolising shared storage performance.","It is configured on the Hyper-V virtual disk and enforced against the volume that hosts it."],"whyOthers":["DNS TTL is a caching setting and is not controlled by Storage QoS.","DHCP reservations assign addresses and are unrelated.","","Password complexity is a security policy setting and is not storage performance."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 with Hyper-V. Policies can be aggregated from all virtual disks on a volume, and a maximum value of zero means no limit in some configurations."},
{"id":"az802-q-199","domain":"Manage storage and file services","text":"What is iSCSI?","options":["A file-screening template","A protocol that carries SCSI storage commands over IP networks","A DNS signing algorithm","A user-account type"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"پروتکل iSCSI امکان دسترسی به فضای ذخیره‌سازی بلوکی (Block Storage) را از طریق شبکه اترنت و با استفاده از Initiatorها و Targetها فراهم می‌کند.","en":"iSCSI enables block storage access over Ethernet using initiators and targets.","de":"Die richtige Antwort ist „A protocol that carries SCSI storage commands over IP networks“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"پروتکل iSCSI چیست؟","optionsFa":["یک قالب (Template) برای غربالگری فایل‌ها","پروتکلی که دستورات ذخیره‌سازی SCSI را از طریق شبکه‌های IP منتقل می‌کند","یک الگوریتم امضای DNS","نوعی حساب کاربری"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/iscsi/iscsi-target-server"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure storage replication, QoS, and iSCSI","objectiveId":"storage-block","topic":"iSCSI","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/iscsi/iscsi-target-server"],"keyPoints":["iSCSI carries SCSI storage commands over an IP network.","It lets a server use block storage that is presented across Ethernet rather than through direct-attached disks.","The initiator is the client side and the target is the server side that presents the storage."],"whyOthers":["A file-screening template is an FSRM policy and is not a storage protocol.","","A DNS signing algorithm relates to DNSSEC and not to block storage.","A user-account type is a directory concept and is unrelated to iSCSI."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. The iSCSI Target Server role service can present storage, and the iSCSI initiator connects a client to a target."},
{"id":"az802-q-200","domain":"Manage storage and file services","text":"Which iSCSI component initiates a connection to a storage target?","options":["iSCSI initiator","iSCSI namespace","iSCSI resolver","iSCSI DHCP scope"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"مؤلفه Initiator همان بخش سمت کلاینت است که به LUNهای ارائه‌شده توسط Target متصل می‌شود.","en":"The initiator is the client-side component that connects to the target’s presented LUNs.","de":"Die richtige Antwort ist „iSCSI initiator“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام مؤلفه iSCSI، اتصال به یک Target ذخیره‌سازی را آغاز می‌کند؟","optionsFa":["Initiator در iSCSI","فضای نام (Namespace) در iSCSI","Resolver در iSCSI","محدوده (Scope) DHCP در iSCSI"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/iscsi/iscsi-target-server"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure storage replication, QoS, and iSCSI","objectiveId":"storage-block","topic":"iSCSI","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/iscsi/iscsi-target-server"],"keyPoints":["The iSCSI initiator is the client-side component that connects to a target.","It discovers targets, logs on to them, and presents the remote LUNs to the operating system as disks.","Windows includes the Microsoft iSCSI Initiator, which is managed from the control panel or with PowerShell."],"whyOthers":["","An iSCSI namespace is not a component in the initiator/target model.","An iSCSI resolver is not a defined iSCSI component; DNS resolves the target's name.","An iSCSI DHCP scope is not a defined concept; DHCP assigns addresses, not storage."],"commandPath":[{"label":"List discovered iSCSI targets","command":"Get-IscsiTarget"},{"label":"Connect the initiator to a target","command":"Connect-IscsiTarget -NodeAddress iqn.1991-05.com.microsoft:srv01-target"}],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Multipath I/O can be added so that multiple network paths to the same target improve availability."},
{"id":"az802-q-201","domain":"Manage storage and file services","text":"Which iSCSI practice improves security?","options":["Expose the target to every network","Use anonymous access","Disable initiator authentication","Use CHAP, dedicated networks, and access restrictions where appropriate"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"ترافیک iSCSI و دسترسی به فضای ذخیره‌سازی باید ایزوله شده و دارای احراز هویت باشند تا دسترسی غیرمجاز کاهش یابد.","en":"iSCSI traffic and storage access should be isolated and authenticated to reduce unauthorized access.","de":"Die richtige Antwort ist „Use CHAP, dedicated networks, and access restrictions where appropriate“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام‌یک از روش‌های iSCSI باعث افزایش امنیت می‌شود؟","optionsFa":["در دسترس قرار دادن Target برای تمام شبکه‌ها","استفاده از دسترسی ناشناس (Anonymous access)","غیرفعال کردن احراز هویت Initiator","استفاده از CHAP، شبکه‌های اختصاصی و محدودیت‌های دسترسی در موارد مناسب"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/iscsi/iscsi-target-server","https://learn.microsoft.com/en-us/windows-server/storage/file-server/smb-security"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure storage replication, QoS, and iSCSI","objectiveId":"storage-block","topic":"iSCSI","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/iscsi/iscsi-target-server","https://learn.microsoft.com/en-us/windows-server/storage/file-server/smb-security"],"keyPoints":["iSCSI access should be restricted to dedicated storage networks where possible.","CHAP authentication can require the initiator to prove its identity to the target.","Target access lists limit which initiators may connect to a target or LUN."],"whyOthers":["Exposing the target to every network increases the attack surface instead of improving security.","Anonymous access removes authentication and is not a security improvement.","Disabling initiator authentication weakens access control.",""],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. CHAP alone is modest protection, which is why network isolation and access lists are used alongside it."},
{"id":"az802-q-202","domain":"Manage storage and file services","text":"What is Azure Files?","options":["An AD schema partition","A local DNS cache","Managed cloud file shares accessible through SMB or other supported protocols","A virtual CPU scheduler"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"سرویس Azure Files اشتراک‌گذاری فایل مدیریت‌شده را بدون نیاز به سرور فایلِ تحت مدیریت مشتری، فراهم می‌کند.","en":"Azure Files provides managed file shares without requiring a customer-managed file server.","de":"Die richtige Antwort ist „Managed cloud file shares accessible through SMB or other supported protocols“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"سرویس Azure Files چیست؟","optionsFa":["یک پارتیشن طرح‌واره (Schema partition) در AD","یک کش محلی DNS","اشتراک‌گذاری فایل ابری مدیریت‌شده که از طریق SMB یا سایر پروتکل‌های پشتیبانی‌شده قابل دسترسی است","یک زمان‌بند (Scheduler) پردازنده مجازی"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/storage/files/storage-files-introduction"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage Azure file services","objectiveId":"storage-azure","topic":"Azure Files","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/azure/storage/files/storage-files-introduction"],"keyPoints":["Azure Files provides managed cloud file shares accessible through SMB and other supported protocols.","Shares are hosted in a storage account and do not require a customer-managed file server.","They can be mounted from Windows, Linux, and macOS clients."],"whyOthers":["An AD schema partition is a directory partition and is not a file share.","A local DNS cache is a resolver store and is unrelated.","","A virtual CPU scheduler is a compute concept and not a file service."],"requirements":"Applies to the Azure Files service. Several performance tiers exist, and the tier chosen affects the available capacity, throughput, and cost."},
{"id":"az802-q-203","domain":"Manage storage and file services","text":"Which authentication method can provide identity-based access to Azure file shares?","options":["DHCP reservations","Microsoft Entra identity-based authentication with appropriate domain integration","Anonymous FTP only","DNSSEC"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"دسترسی SMB مبتنی بر هویت می‌تواند به جای تکیه صرف بر کلیدهای ذخیره‌سازی، از هویت‌های دایرکتوری و ACLها استفاده کند.","en":"Identity-based SMB access can use directory identities and ACLs instead of relying only on storage keys.","de":"Die richtige Antwort ist „Microsoft Entra identity-based authentication with appropriate domain integration“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام روش احراز هویت می‌تواند دسترسی مبتنی بر هویت (identity-based access) به اشتراک‌گذاری‌های فایل Azure (Azure file shares) را فراهم کند؟","optionsFa":["رزروهای DHCP","احراز هویت مبتنی بر هویت Microsoft Entra با یکپارچه‌سازی مناسب دامنه (domain integration)","فقط FTP ناشناس (Anonymous FTP)","DNSSEC"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/storage/files/storage-files-introduction","https://learn.microsoft.com/en-us/azure/storage/file-sync/file-sync-introduction"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage Azure file services","objectiveId":"storage-azure","topic":"Azure Files","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/azure/storage/files/storage-files-introduction","https://learn.microsoft.com/en-us/azure/storage/file-sync/file-sync-introduction"],"keyPoints":["Identity-based access to Azure file shares can use directory identities and ACLs instead of storage account keys.","It integrates with an on-premises domain or Microsoft Entra Domain Services for authentication.","This lets permissions be managed like a normal file share rather than through a shared key."],"whyOthers":["DHCP reservations assign IP addresses and are not an authentication method for file shares.","","Anonymous FTP is an unauthenticated file-transfer method and is not identity-based access.","DNSSEC signs DNS data and has nothing to do with file-share identity."],"requirements":"Applies to Azure Files. Identity-based access requires the storage account to be domain-joined or integrated with a supported directory service, and the client must be able to reach that directory."},
{"id":"az802-q-204","domain":"Manage storage and file services","text":"What is the purpose of an Azure Files share access key?","options":["Authenticate access to the storage account or share when key-based access is used","Sign DNS records","Create an AD trust","Encrypt the client’s boot volume"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"کلیدهای ذخیره‌سازی دسترسی گسترده‌ای را فراهم می‌کنند، بنابراین باید محافظت و به‌طور دوره‌ای تعویض (rotate) شوند؛ دسترسی مبتنی بر هویت اغلب دارای جزئیات دقیق‌تر و محدودتر (granular) است.","en":"Storage keys grant broad access, so they must be protected and rotated; identity-based access is often more granular.","de":"Die richtige Antwort ist „Authenticate access to the storage account or share when key-based access is used“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"هدف از کلید دسترسی به اشتراک‌گذاری Azure Files چیست؟","optionsFa":["احراز هویت دسترسی به حساب ذخیره‌سازی (storage account) یا اشتراک‌گذاری، هنگام استفاده از دسترسی مبتنی بر کلید","امضای رکوردهای DNS","ایجاد یک رابطه اعتماد (trust) در AD","رمزگذاری درایو بوت کلاینت"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/storage/files/storage-files-introduction"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage Azure file services","objectiveId":"storage-azure","topic":"Azure Files","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/storage/files/storage-files-introduction"],"keyPoints":["A share access key, derived from the storage account keys, authenticates access when key-based access is used.","Storage account keys grant broad access to the account, so they must be protected and rotated.","Identity-based access is often preferred because it provides per-user authorization with ACLs."],"whyOthers":["","A share access key does not sign DNS records; DNSSEC does that.","It does not create an AD trust.","It does not encrypt the client's boot volume; that is BitLocker's role."],"requirements":"Applies to Azure Files. Storage account keys can be regenerated, and doing so invalidates clients and services that still use the old key."},
{"id":"az802-q-205","domain":"Manage storage and file services","text":"What does Azure File Sync provide?","options":["VM CPU scaling","DNS failover","AD schema replication","Caching and synchronization between Windows file servers and Azure file shares"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"سرویس Azure File Sync می‌تواند ضمن نگهداری یک کش محلی روی سرور، نسخه اصلی و معتبر اشتراک‌گذاری فایل را در Azure ذخیره کند.","en":"Azure File Sync can keep a local server cache while storing the authoritative file share in Azure.","de":"Die richtige Antwort ist „Caching and synchronization between Windows file servers and Azure file shares“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"سرویس Azure File Sync چه قابلیتی را ارائه می‌دهد؟","optionsFa":["مقیاس‌پذیری CPU ماشین مجازی (VM)","تغییر مسیر خودکار (Failover) در DNS","هم‌رسانی (Replication) طرح‌واره (Schema) سرویس AD","کش‌کردن و همگام‌سازی بین سرورهای فایل ویندوز و اشتراک‌گذاری‌های فایل Azure"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/storage/file-sync/file-sync-introduction","https://learn.microsoft.com/en-us/azure/storage/file-sync/file-sync-cloud-tiering-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage Azure file services","objectiveId":"storage-azure","topic":"Azure File Sync","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/storage/file-sync/file-sync-introduction","https://learn.microsoft.com/en-us/azure/storage/file-sync/file-sync-cloud-tiering-overview"],"keyPoints":["Azure File Sync synchronises a Windows file server with an Azure file share.","The cloud share can hold the authoritative copy while the local server keeps a cache for fast access.","It supports multiple servers syncing the same share, which enables distributed access."],"whyOthers":["Azure File Sync does not scale virtual machine CPU.","It does not provide DNS failover.","It does not replicate the AD schema.",""],"requirements":"Applies to Azure File Sync. It requires the Storage Sync Service and a registered Windows Server with the Azure File Sync agent."},
{"id":"az802-q-206","domain":"Manage storage and file services","text":"What is cloud tiering in Azure File Sync?","options":["Encrypt DNS responses","Convert NTFS to FAT","Keep frequently accessed files locally while tiering less-used content to Azure","Duplicate every file on every server"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"قابلیت Cloud Tiering ضمن حفظ دسترسی شفاف (بدون تغییر در نحوه دسترسی کاربر) به فایل‌های منتقل‌شده به فضای ابری، ظرفیت ذخیره‌سازی محلی را بهینه می‌کند.","en":"Cloud tiering optimizes local capacity while preserving transparent access to cloud-tiered files.","de":"Die richtige Antwort ist „Keep frequently accessed files locally while tiering less-used content to Azure“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"مفهوم Cloud Tiering (لایه‌بندی ابری) در Azure File Sync چیست؟","optionsFa":["رمزنگاری پاسخ‌های DNS","تبدیل NTFS به FAT","نگهداری فایل‌های پرکاربرد در محل (به‌صورت محلی) و انتقال محتوای کم‌کاربرد به لایه ابری Azure","ایجاد نسخه تکراری از هر فایل روی تمام سرورها"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/storage/file-sync/file-sync-cloud-tiering-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage Azure file services","objectiveId":"storage-azure","topic":"Azure File Sync","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/storage/file-sync/file-sync-cloud-tiering-overview"],"keyPoints":["Cloud tiering keeps frequently accessed files locally while moving less-used data to the Azure file share.","Tiered files still appear in the local file system and open transparently when needed.","It lets a smaller local volume serve a larger cloud share."],"whyOthers":["Cloud tiering does not encrypt DNS responses.","It does not convert NTFS to FAT.","","It does not duplicate every file on every server."],"requirements":"Applies to Azure File Sync. Policies control how much free space to keep and after how long to tier files, and recall of tiered data depends on connectivity to the cloud share."},
{"id":"az802-q-207","domain":"Manage storage and file services","text":"A synced file server shows persistent sync errors. What should be reviewed first?","options":["DHCP option 003 only","Server endpoint health, sync group status, agent logs, and network connectivity","FSMO roles only","VM checkpoint settings"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"عیب‌یابی Azure File Sync با بررسی نقطه پایانی، وضعیت سرویس، لاگ‌ها و مسیر اتصال آغاز می‌شود.","en":"Azure File Sync diagnostics start with the endpoint, service state, logs, and connectivity path.","de":"Die richtige Antwort ist „Server endpoint health, sync group status, agent logs, and network connectivity“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"یک سرور فایلِ همگام‌سازی‌شده (synced file server) خطاهای همگام‌سازی مداومی را نشان می‌دهد. ابتدا چه چیزی باید بررسی شود؟","optionsFa":["فقط گزینه 003 در DHCP","سلامت نقطه پایانی (endpoint) سرور، وضعیت گروه همگام‌سازی، لاگ‌های عامل (agent) و اتصال شبکه","فقط نقش‌های FSMO","تنظیمات چک‌پوینت ماشین مجازی (VM)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/storage/file-sync/file-sync-introduction","https://learn.microsoft.com/en-us/azure/storage/file-sync/file-sync-cloud-tiering-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage Azure file services","objectiveId":"storage-azure","topic":"Azure File Sync","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/azure/storage/file-sync/file-sync-introduction","https://learn.microsoft.com/en-us/azure/storage/file-sync/file-sync-cloud-tiering-overview"],"keyPoints":["Sync diagnostics start with the health of the server endpoint and the sync group.","The sync agent's state and its logs usually identify the reason for persistent sync errors.","Network connectivity to the Azure file share and the Storage Sync Service must also be verified."],"whyOthers":["DHCP option 003 is the default gateway and is not the first check for sync health.","","FSMO roles concern directory operations and not file sync.","Virtual machine checkpoints capture state and are unrelated to Azure File Sync."],"requirements":"Applies to Azure File Sync. A storage account used with File Sync must not have a firewall that blocks the agent, and the agent must be kept current."},
{"id":"az802-q-208","domain":"Manage storage and file services","text":"What is BitLocker designed to protect?","options":["Data at rest on supported drives","DNS queries in transit","DHCP lease negotiation","AD replication topology"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"ابزار BitLocker حجم‌ها (volumes) را رمزنگاری می‌کند تا دسترسی آفلاین به رسانه فیزیکی منجر به افشای داده‌ها نشود.","en":"BitLocker encrypts volumes so offline access to the physical media does not reveal the data.","de":"Die richtige Antwort ist „Data at rest on supported drives“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"هدف BitLocker محافظت از چیست؟","optionsFa":["داده‌های ساکن (at rest) روی درایوهای پشتیبانی‌شده","کوئری‌های DNS در حال انتقال","مذاکره اجاره (lease) در DHCP","توپولوژی هم‌تکثیرسازی (replication) در AD"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows/security/operating-system-security/data-protection/bitlocker/"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage volume encryption with BitLocker","objectiveId":"storage-bitlocker","topic":"BitLocker","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows/security/operating-system-security/data-protection/bitlocker/"],"keyPoints":["BitLocker encrypts volumes so data at rest cannot be read if the drive is removed or the machine is stolen.","It can be used on operating system volumes, data volumes, and removable drives.","It is different from SMB encryption, which protects data in transit."],"whyOthers":["","BitLocker does not protect DNS queries in transit.","It does not take part in DHCP lease negotiation.","It does not affect AD replication topology."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Deployment requires a supported TPM or a startup key configuration, and network unlock can be used for cluster or remote scenarios."},
{"id":"az802-q-209","domain":"Manage storage and file services","text":"Which component can protect a BitLocker OS volume’s key material using hardware-backed measurement?","options":["DHCP relay","DNS forwarder","SMB redirector","TPM"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"ماژول پلتفرم قابل‌اعتماد (TPM) می‌تواند در پیکربندی‌های پشتیبانی‌شده BitLocker، از کلیدها محافظت کرده و سنجش‌های فرآیند بوت را اعتبارسنجی کند.","en":"A Trusted Platform Module can protect keys and validate boot measurements for supported BitLocker configurations.","de":"Die richtige Antwort ist „TPM“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام مؤلفه می‌تواند با استفاده از سنجش مبتنی بر سخت‌افزار (hardware-backed measurement)، از داده‌های کلید (key material) مربوط به حجم سیستم‌عاملِ محافظت‌شده با BitLocker محافظت کند؟","optionsFa":["DHCP relay","DNS forwarder","SMB redirector","TPM"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows/security/operating-system-security/data-protection/bitlocker/","https://learn.microsoft.com/en-us/windows/security/operating-system-security/data-protection/bitlocker/bitlocker-recovery-guide-plan"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage volume encryption with BitLocker","objectiveId":"storage-bitlocker","topic":"BitLocker","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows/security/operating-system-security/data-protection/bitlocker/","https://learn.microsoft.com/en-us/windows/security/operating-system-security/data-protection/bitlocker/bitlocker-recovery-guide-plan"],"keyPoints":["A Trusted Platform Module (TPM) can store BitLocker key material protected by hardware and validate boot measurements.","It provides a seamless unlock experience when the boot environment is unchanged.","A change that alters the measured boot state can force recovery, which is why recovery information must be escrowed."],"whyOthers":["A DHCP relay forwards DHCP traffic and does not protect keys.","A DNS forwarder sends DNS queries to another resolver and is unrelated.","The SMB redirector accesses file shares and does not protect BitLocker keys.",""],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. A TPM 1.2 or 2.0 module is required for TPM protector modes, and the platform firmware must be trusted-boot capable where required."},
{"id":"az802-q-210","domain":"Manage storage and file services","text":"Why should a BitLocker recovery key be escrowed in a controlled location?","options":["To expand a VHDX","To authorize DHCP","To recover access if normal unlock protectors are unavailable","To make DNS queries faster"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"اطلاعات بازیابی پس از تغییرات سخت‌افزاری، فریم‌ور، بوت یا سیاست‌هایی که مانع از بازگشایی قفل به روش معمول می‌شوند، حیاتی است.","en":"Recovery information is essential after hardware, firmware, boot, or policy changes that prevent normal unlock.","de":"Die richtige Antwort ist „To recover access if normal unlock protectors are unavailable“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"چرا باید کلید بازیابی BitLocker در مکانی کنترل‌شده نگهداری (امانت‌سپاری) شود؟","optionsFa":["برای گسترش دادن یک VHDX","برای مجاز کردن (Authorize) سرویس DHCP","برای بازیابی دسترسی در صورتی که روش‌های معمول بازگشایی قفل در دسترس نباشند","برای افزایش سرعت پرس‌وجوهای (Queries) DNS"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows/security/operating-system-security/data-protection/bitlocker/bitlocker-recovery-guide-plan","https://learn.microsoft.com/en-us/windows/security/operating-system-security/data-protection/bitlocker/"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage volume encryption with BitLocker","objectiveId":"storage-bitlocker","topic":"BitLocker","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows/security/operating-system-security/data-protection/bitlocker/bitlocker-recovery-guide-plan","https://learn.microsoft.com/en-us/windows/security/operating-system-security/data-protection/bitlocker/"],"keyPoints":["A recovery key restores access when the normal unlock protectors are unavailable.","Common triggers include firmware changes, boot configuration changes, and a TPM that cannot verify the boot state.","The key must be stored in a controlled, access-audited location so it is available when needed but not exposed."],"whyOthers":["A BitLocker recovery key does not expand a VHDX.","It does not authorise DHCP.","","It does not make DNS queries faster."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Recovery keys can be escrowed in Active Directory, Microsoft Entra ID, or another managed store, and escrow should be verified before encryption is relied upon."},
{"id":"az802-q-211","domain":"Manage storage and file services","text":"A volume is full even though users see few files. What should be checked?","options":["VM display resolution","Shadow copies, deduplication state, hidden files, quotas, and application data","The forest trust direction only","DNSSEC keys only"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"مجموع فایل‌های قابل مشاهده، همیشه شامل Snapshotها، داده‌های مخفی، متادیتا یا فایل‌های مدیریت‌شده توسط برنامه‌ها نمی‌شود.","en":"Visible file totals do not always account for snapshots, hidden data, metadata, or application-managed files.","de":"Die richtige Antwort ist „Shadow copies, deduplication state, hidden files, quotas, and application data“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"یک Volume (پارتیشن/حجم) پر شده است، با اینکه کاربران فایل‌های کمی در آن می‌بینند. چه مواردی باید بررسی شوند؟","optionsFa":["وضوح تصویر (Resolution) ماشین مجازی (VM)","نسخه‌های Shadow (Shadow copies)، وضعیت Deduplication (حذف داده‌های تکراری)، فایل‌های مخفی، سهمیه‌ها (Quotas) و داده‌های برنامه","فقط جهتِ اعتماد (Trust) بین Forestها","فقط کلیدهای DNSSEC"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/storage/get-volume","https://learn.microsoft.com/en-us/windows-server/storage/fsrm/fsrm-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage volumes and disks","objectiveId":"storage-volumes","topic":"Volume troubleshooting","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/storage/get-volume","https://learn.microsoft.com/en-us/windows-server/storage/fsrm/fsrm-overview"],"keyPoints":["A full volume can be consumed by data that is not visible in the file listing, such as shadow copies and deduplication metadata.","Hidden files, hidden system folders, quota-managed folders, and application data also account for space.","The investigation should therefore cover shadow copies, deduplication state, hidden files, quotas, and application data."],"whyOthers":["Virtual machine display resolution has no effect on volume usage.","","The forest trust direction concerns authentication between domains and not storage.","DNSSEC keys are DNS signing material and do not consume volume space as hidden data."],"commandPath":[{"label":"Show volume size and free space","command":"Get-Volume"},{"label":"List shadow copies on a volume","command":"vssadmin list shadowstorage"},{"label":"Show deduplication status and savings","command":"Get-DedupStatus"}],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Shadow copy storage is a frequent cause, because snapshots consume space that does not appear as files in Explorer."},
{"id":"az802-q-212","domain":"Manage storage and file services","text":"What does a volume mount point provide?","options":["Access to a volume through an empty folder path instead of a drive letter","A DNS alias","A DHCP reservation","A VM checkpoint"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"نقاط اتصال (Mount points) به سازماندهی Volumeهای متعدد بدون مصرف حروف درایو اضافی کمک می‌کنند.","en":"Mount points help organize many volumes without consuming additional drive letters.","de":"Die richtige Antwort ist „Access to a volume through an empty folder path instead of a drive letter“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"نقطه اتصال Volume (یا Mount point) چه امکانی را فراهم می‌کند؟","optionsFa":["دسترسی به یک Volume از طریق مسیر یک پوشه خالی، به جای استفاده از حرف درایو (Drive letter)","یک نام مستعار (Alias) در DNS","یک رزرو آدرس در DHCP","یک Checkpoint برای ماشین مجازی (VM)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/storage/get-volume"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage volumes and disks","objectiveId":"storage-volumes","topic":"Volume mount points","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/storage/get-volume"],"keyPoints":["A mount point makes a volume reachable through an empty folder path on another volume.","It allows many volumes to be organised under one path without consuming drive letters.","It is useful when a server hosts many data volumes or when the path structure should stay consistent."],"whyOthers":["","A DNS alias is a name-resolution record and is not a volume mount point.","A DHCP reservation assigns an address and is unrelated.","A virtual machine checkpoint captures state and is not a mount point."],"commandPath":[{"label":"Add a mount point to a volume","command":"Get-Volume -DriveLetter D | Add-PartitionAccessPath -AccessPath 'C:\\Data\\VolumeD'"}],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. The mount folder must be empty and located on an NTFS volume, and the mounted volume also needs a file system of its own."},
{"id":"az802-q-213","domain":"Manage storage and file services","text":"Which PowerShell cmdlet displays basic volume information?","options":["Get-ADForest","Get-DnsServerResourceRecord","Get-GPResultantSetOfPolicy","Get-Volume"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"دستور Get-Volume اطلاعاتی نظیر سیستم فایل، وضعیت سلامت، اندازه، حرف درایو و سایر ویژگی‌های مرتبط با Volume را گزارش می‌دهد.","en":"Get-Volume reports file system, health, size, drive letter, and related volume properties.","de":"Die richtige Antwort ist „Get-Volume“; sie passt zum Bereich Manage storage and file services und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام دستور (Cmdlet) در PowerShell اطلاعات پایه Volume را نمایش می‌دهد؟","optionsFa":["Get-ADForest","Get-DnsServerResourceRecord","Get-GPResultantSetOfPolicy","Get-Volume"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/storage/get-volume"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage volumes and disks","objectiveId":"storage-volumes","topic":"Volume management","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/storage/get-volume"],"keyPoints":["Get-Volume reports the file system, health status, size, free space, drive letter, and related properties.","It is the quickest way to inspect volumes on a server from PowerShell.","It can be filtered to find volumes by drive letter, file-system label, or health state."],"whyOthers":["Get-ADForest reports forest-level Active Directory settings and does not list volumes.","Get-DnsServerResourceRecord lists DNS records and is unrelated.","Get-GPResultantSetOfPolicy reports applied Group Policy settings.",""],"commandPath":[{"label":"List all volumes","command":"Get-Volume"},{"label":"Show volumes that are not healthy","command":"Get-Volume | Where-Object HealthStatus -ne 'Healthy'"}],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. The Storage module also provides Get-Disk and Get-Partition, which are used together with Get-Volume when investigating a volume problem."},
{"id":"az802-q-214","domain":"Secure Windows Server infrastructure","text":"What is the main purpose of Windows Defender Firewall with Advanced Security?","options":["Replicate AD objects","Manage VHDX files","Filter inbound and outbound traffic using stateful rules and profiles","Allocate DHCP addresses"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"این فایروال سیاست‌های ترافیکی مبتنی بر میزبان (Host-based) را اعمال می‌کند و می‌تواند از پروفایل‌های Domain، Private و Public استفاده نماید.","en":"The firewall enforces host-based traffic policy and can use domain, private, and public profiles.","de":"Die richtige Antwort ist „Filter inbound and outbound traffic using stateful rules and profiles“; sie passt zum Bereich Secure Windows Server infrastructure und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"هدف اصلی Windows Defender Firewall with Advanced Security چیست؟","optionsFa":["تکثیر (Replicate) اشیاء AD","مدیریت فایل‌های VHDX","فیلتر کردن ترافیک ورودی و خروجی با استفاده از قوانین و پروفایل‌های مبتنی بر وضعیت (Stateful)","تخصیص آدرس‌های DHCP"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows/security/operating-system-security/network-security/windows-firewall/","https://learn.microsoft.com/en-us/windows/security/operating-system-security/network-security/windows-firewall/rules"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure Windows Defender Firewall and IPsec","objectiveId":"sec-firewall","topic":"Windows Defender Firewall","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows/security/operating-system-security/network-security/windows-firewall/","https://learn.microsoft.com/en-us/windows/security/operating-system-security/network-security/windows-firewall/rules"],"keyPoints":["Windows Defender Firewall with Advanced Security enforces host-based traffic policy with stateful rules.","Rules apply per network profile: Domain, Private, and Public.","It supports both inbound and outbound rules and integrates with IPsec connection security rules."],"whyOthers":["Replicating AD objects is a directory service task and is not a firewall function.","Managing VHDX files is a storage operation and is unrelated to the firewall.","","Allocating DHCP addresses is a network service task, not a host firewall function."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Rules can be deployed locally or centrally through Group Policy, and each profile applies based on how the network is identified."},
{"id":"az802-q-215","domain":"Secure Windows Server infrastructure","text":"A server’s network profile is Public instead of Domain. What is a likely effect?","options":["The VM loses its VHDX","Domain-profile firewall rules may not apply","The server automatically becomes an RODC","NTFS ACLs are removed"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"قوانین فایروال مختص هر پروفایل هستند؛ بنابراین تشخیص نادرست نوع شبکه می‌تواند مانع از عبور ترافیک مدیریتیِ ضروری شود.","en":"Firewall rules are profile-specific, so incorrect network identification can block required management traffic.","de":"Die richtige Antwort ist „Domain-profile firewall rules may not apply“; sie passt zum Bereich Secure Windows Server infrastructure und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"پروفایل شبکه یک سرور به جای Domain، روی حالت Public تنظیم شده است. پیامد احتمالی آن چیست؟","optionsFa":["ماشین مجازی (VM) فایل VHDX خود را از دست می‌دهد","ممکن است قوانین فایروالِ مربوط به پروفایل Domain اعمال نشوند","سرور به‌طور خودکار به یک RODC تبدیل می‌شود","لیست‌های کنترل دسترسی (ACL) سیستم فایل NTFS حذف می‌شوند"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows/security/operating-system-security/network-security/windows-firewall/","https://learn.microsoft.com/en-us/windows/security/operating-system-security/network-security/windows-firewall/rules"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure Windows Defender Firewall and IPsec","objectiveId":"sec-firewall","topic":"Firewall profiles","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows/security/operating-system-security/network-security/windows-firewall/","https://learn.microsoft.com/en-us/windows/security/operating-system-security/network-security/windows-firewall/rules"],"keyPoints":["A server identifies each network as Domain, Private, or Public and applies the rules for that profile.","If a domain server is treated as Public, the Domain-profile rules do not apply and required management traffic can be blocked.","The fix is usually to correct the network location detection so the Domain profile is used again."],"whyOthers":["A firewall profile change does not remove a virtual machine's VHDX.","","Network profile detection has no relationship to the RODC role.","NTFS ACLs are file-system permissions and are not changed by a firewall profile."],"commandPath":[{"label":"Show the network profile in use","command":"Get-NetConnectionProfile"},{"label":"Show the active firewall profiles","command":"Get-NetFirewallProfile | Select-Object Name, Enabled"}],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Domain identification depends on reaching a domain controller, so a broken network path can itself cause a server to fall back to a different profile."},
{"id":"az802-q-216","domain":"Secure Windows Server infrastructure","text":"What is a connection security rule used for?","options":["Specify authentication and encryption requirements for IPsec traffic","Create a DHCP reservation","Assign a drive letter","Configure a DFS namespace"],"correct":0,"source":"https://learn.microsoft.com/en-us/windows/security/operating-system-security/network-security/windows-firewall/connection-security-rules","rationale":{"fa":"قوانین امنیت اتصال، نحوه احراز هویت میزبان‌ها و محافظت از اتصالات شبکه منتخب را تعیین می‌کنند.","en":"Connection security rules define how hosts authenticate and protect selected network connections.","de":"Die richtige Antwort ist „Specify authentication and encryption requirements for IPsec traffic“; sie passt zum Bereich Secure Windows Server infrastructure und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کاربرد قانون امنیت اتصال (Connection Security Rule) چیست؟","optionsFa":["تعیین الزامات احراز هویت و رمزنگاری برای ترافیک IPsec","ایجاد یک رزرویشن (Reservation) در DHCP","اختصاص یک حرف درایو (Drive Letter)","پیکربندی یک فضای نام (Namespace) در DFS"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows/security/operating-system-security/network-security/windows-firewall/rules","https://learn.microsoft.com/en-us/windows/security/operating-system-security/network-security/windows-firewall/configure-with-command-line"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure Windows Defender Firewall and IPsec","objectiveId":"sec-firewall","topic":"Connection security rules","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows/security/operating-system-security/network-security/windows-firewall/rules","https://learn.microsoft.com/en-us/windows/security/operating-system-security/network-security/windows-firewall/configure-with-command-line"],"keyPoints":["Connection security rules specify how two hosts authenticate and protect traffic with IPsec.","They define the authentication requirements and whether the connection must be encrypted or only integrity-protected.","They work alongside firewall rules, which decide whether traffic is allowed."],"whyOthers":["","Creating a DHCP reservation is an addressing task and is not a connection security rule.","Assigning a drive letter is a storage configuration and is unrelated.","Configuring a DFS namespace is a file-access task and is not IPsec policy."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Connection security rules can require authentication with Kerberos, a certificate, or another method, and they are commonly deployed by Group Policy."},
{"id":"az802-q-217","domain":"Secure Windows Server infrastructure","text":"What is domain isolation intended to accomplish?","options":["Isolate a DNS zone from all clients","Prevent all server-to-server communication","Replace Group Policy","Require authenticated or authorized domain traffic between managed hosts"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"ایزوله‌سازی دامین (Domain isolation) از فایروال و سیاست IPsec برای محدود کردن ارتباطات به سیستم‌های مورد اعتماد و احراز هویت‌شده استفاده می‌کند.","en":"Domain isolation uses firewall and IPsec policy to limit communication to trusted, authenticated systems.","de":"Die richtige Antwort ist „Require authenticated or authorized domain traffic between managed hosts“; sie passt zum Bereich Secure Windows Server infrastructure und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"هدف از پیاده‌سازی «ایزوله‌سازی دامنه» (Domain Isolation) چیست؟","optionsFa":["ایزوله کردن یک ناحیه (Zone) DNS از تمام کلاینت‌ها","جلوگیری از تمام ارتباطات بین سرورها","جایگزینی Group Policy","الزام به احراز هویت یا مجوزدار بودن ترافیک دامین بین میزبان‌های مدیریت‌شده"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-server-2012-r2-and-2012/jj721516(v=ws.11)","https://learn.microsoft.com/en-us/windows/security/operating-system-security/network-security/windows-firewall/rules"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure Windows Defender Firewall and IPsec","objectiveId":"sec-firewall","topic":"Domain isolation","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-server-2012-r2-and-2012/jj721516(v=ws.11)","https://learn.microsoft.com/en-us/windows/security/operating-system-security/network-security/windows-firewall/rules"],"keyPoints":["Domain isolation requires unsolicited inbound traffic to be authenticated before it is accepted.","It uses firewall and IPsec connection security rules so only trusted, authenticated hosts can communicate.","It reduces the ability of an unmanaged or compromised device to reach managed servers."],"whyOthers":["Domain isolation does not isolate a DNS zone from clients.","It does not prevent all server-to-server communication; authenticated servers can still communicate.","It does not replace Group Policy; it is deployed through it.",""],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. A typical deployment keeps some traffic exempt, such as domain controller authentication and DHCP, so it is planned carefully before rollout."},
{"id":"az802-q-218","domain":"Secure Windows Server infrastructure","text":"What is Windows Defender Credential Guard designed to protect?","options":["VHDX capacity","DNS TTL values","Secrets such as NTLM hashes and Kerberos credentials from credential theft","DHCP scopes"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"قابلیت Credential Guard از امنیت مبتنی بر مجازی‌سازی برای ایزوله کردن داده‌های حساس احراز هویت استفاده می‌کند.","en":"Credential Guard uses virtualization-based security to isolate sensitive authentication material.","de":"Die richtige Antwort ist „Secrets such as NTLM hashes and Kerberos credentials from credential theft“; sie passt zum Bereich Secure Windows Server infrastructure und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"قابلیت Windows Defender Credential Guard برای محافظت از چه چیزی طراحی شده است؟","optionsFa":["ظرفیت VHDX","مقادیر TTL در DNS","اطلاعات حساس (Secrets) مانند هش‌های NTLM و اعتبارنامه‌های Kerberos در برابر سرقت اعتبارنامه","دامنه‌های (Scopes) سرویس DHCP"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows/security/identity-protection/credential-guard/","https://learn.microsoft.com/en-us/windows-server/security/credentials-protection-and-management/protected-users-security-group"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage credential protection","objectiveId":"sec-credentials","topic":"Credential Guard","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows/security/identity-protection/credential-guard/","https://learn.microsoft.com/en-us/windows-server/security/credentials-protection-and-management/protected-users-security-group"],"keyPoints":["Credential Guard uses virtualization-based security to isolate secrets such as NTLM password hashes and Kerberos tickets.","Even an administrator who compromises the normal operating system cannot easily read the isolated material.","It targets credential theft techniques such as credential dumping."],"whyOthers":["Credential Guard does not manage VHDX capacity.","It does not set DNS TTL values.","","It does not configure DHCP scopes."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Credential Guard requires supported hardware and firmware and is enabled through policy, and it can affect compatibility with some legacy authentication."},
{"id":"az802-q-219","domain":"Secure Windows Server infrastructure","text":"What is Windows Defender Application Control intended to control?","options":["Which disk receives a drive letter","Which code and applications are trusted to run","Which DHCP clients receive addresses","Which DNS server is authoritative"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Application Control از سیاست های یکپارچگی کد برای محدود کردن اجرا به نرم افزارهای قابل اعتماد استفاده می کند.","en":"Application Control uses code integrity policies to restrict execution to trusted software.","de":"Die richtige Antwort ist „Which code and applications are trusted to run“; sie passt zum Bereich Secure Windows Server infrastructure und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کنترل برنامه Windows Defender در نظر گرفته شده برای کنترل چیست؟","optionsFa":["کدام دیسک یک حرف درایو دریافت می کند","اجرای کدام کد و برنامه های کاربردی قابل اعتماد است","کدام کلاینت های DHCP آدرس ها را دریافت می کنند","کدام سرور DNS معتبر است"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows/security/application-security/application-control/app-control-for-business/appcontrol"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure threat protection features","objectiveId":"sec-threat-protection","topic":"Application control","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows/security/application-security/application-control/app-control-for-business/appcontrol"],"keyPoints":["Windows Defender Application Control restricts execution to code that the organization trusts.","It uses code integrity policies to define which binaries and scripts may run.","It is a strong control against malware and unapproved software on servers."],"whyOthers":["It does not assign drive letters; that is a storage task.","","It does not control which DHCP clients receive addresses.","It does not decide which DNS server is authoritative."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Policies can start in audit mode so that untrusted binaries are logged before enforcement is enabled."},
{"id":"az802-q-220","domain":"Secure Windows Server infrastructure","text":"What is Exploit Protection used for?","options":["Configure mitigations for exploit techniques at system or application scope","Replicate VMs","Create user accounts","Manage SMB shares"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"قابلیت Exploit Protection در صورت پشتیبانی، کنترل‌هایی مانند DEP، ASLR و سایر اقدامات کاهشی را اعمال می‌کند.","en":"Exploit Protection applies controls such as DEP, ASLR, and other mitigations where supported.","de":"Die richtige Antwort ist „Configure mitigations for exploit techniques at system or application scope“; sie passt zum Bereich Secure Windows Server infrastructure und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"Exploit Protection (محافظت در برابر اکسپلویت) چه کاربردی دارد؟","optionsFa":["پیکربندی اقدامات کاهشی (mitigations) برای تکنیک‌های اکسپلویت در سطح سیستم یا برنامه","تکثیر (Replicate) ماشین‌های مجازی (VMs)","ایجاد حساب‌های کاربری","مدیریت اشتراک‌گذاری‌های SMB"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/defender-endpoint/exploit-protection"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure threat protection features","objectiveId":"sec-threat-protection","topic":"Exploit Protection","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/defender-endpoint/exploit-protection"],"keyPoints":["Exploit Protection configures system-wide or per-application mitigations against exploitation techniques.","It includes controls such as data execution prevention, address space layout randomisation, and control flow protection.","Mitigations can be set broadly or tuned for a specific application."],"whyOthers":["","Exploit Protection does not replicate virtual machines.","It does not create user accounts.","It does not manage SMB shares."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Some mitigations can affect compatibility for older applications, so settings can be exported, tested, and applied per application."},
{"id":"az802-q-221","domain":"Secure Windows Server infrastructure","text":"What does Microsoft Defender SmartScreen help detect?","options":["AD replication latency","Disk parity errors only","DHCP starvation only","Suspicious or malicious files, apps, and websites"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"قابلیت SmartScreen از اطلاعات مربوط به اعتبار (reputation) و سیگنال‌های مرتبط برای هشدار درباره محتوای بالقوه ناامن استفاده می‌کند.","en":"SmartScreen uses reputation and related signals to warn about potentially unsafe content.","de":"Die richtige Antwort ist „Suspicious or malicious files, apps, and websites“; sie passt zum Bereich Secure Windows Server infrastructure und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"Microsoft Defender SmartScreen به شناسایی چه مواردی کمک می‌کند؟","optionsFa":["تأخیر در تکثیر (replication) سرویس AD","فقط خطاهای پریتی (parity) دیسک","فقط کمبود منابع DHCP (DHCP starvation)","فایل‌ها، برنامه‌ها و وب‌سایت‌های مشکوک یا مخرب"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows/security/operating-system-security/virus-and-threat-protection/microsoft-defender-smartscreen/"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure threat protection features","objectiveId":"sec-threat-protection","topic":"SmartScreen","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows/security/operating-system-security/virus-and-threat-protection/microsoft-defender-smartscreen/"],"keyPoints":["Microsoft Defender SmartScreen uses reputation and related signals to warn about untrusted files, apps, and websites.","It helps block or warn about content that is unknown or known to be malicious.","It complements, but does not replace, endpoint protection."],"whyOthers":["SmartScreen does not monitor AD replication latency.","It does not check disk parity errors.","It does not detect DHCP starvation.",""],"requirements":"Applies to supported Windows Server and client releases. SmartScreen relies on reputation services, so it needs network access to those services to provide the best protection."},
{"id":"az802-q-222","domain":"Secure Windows Server infrastructure","text":"Which security baseline practice is most appropriate before broad deployment?","options":["Disable auditing to reduce noise","Grant users local administrator rights","Test baseline settings against applications and administrative workflows","Apply every setting without testing"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"تنظیمات پایه امنیت را بهبود می‌بخشند اما ممکن است بر سازگاری تأثیر بگذارند؛ بنابراین انجام آزمایش‌های مرحله‌بندی‌شده و مدیریت استثناها ضروری است.","en":"Baselines improve security but can affect compatibility, so staged testing and exception management are necessary.","de":"Die richtige Antwort ist „Test baseline settings against applications and administrative workflows“; sie passt zum Bereich Secure Windows Server infrastructure und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام اقدام در خصوص «خط‌مشی امنیتی پایه» (security baseline) پیش از استقرار گسترده، مناسب‌تر است؟","optionsFa":["غیرفعال کردن قابلیت Auditing (حسابرسی) برای کاهش نویز (داده‌های اضافی)","اعطای دسترسی مدیر محلی (local administrator) به کاربران","آزمایش تنظیمات پایه در کنار برنامه‌ها و گردش‌کارهای مدیریتی","اعمال تمام تنظیمات بدون انجام آزمایش"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows/security/operating-system-security/device-management/windows-security-configuration-framework/windows-security-baselines"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Harden Windows Server with security baselines","objectiveId":"sec-baselines","topic":"Security baselines","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows/security/operating-system-security/device-management/windows-security-configuration-framework/windows-security-baselines"],"keyPoints":["A baseline changes many settings at once, so it can affect application and administrative workflows.","Testing against representative workloads before broad deployment prevents unexpected outages.","Where a setting must differ, a documented exception is safer than abandoning the baseline."],"whyOthers":["Disabling auditing to reduce noise removes the evidence needed for investigations.","Granting users local administrator rights weakens the security posture.","","Applying every setting without testing ignores compatibility risks that a baseline introduces."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Baselines are provided as Group Policy objects or configuration packages and are best deployed in a ring-based rollout."},
{"id":"az802-q-223","domain":"Secure Windows Server infrastructure","text":"What is Windows LAPS designed to manage?","options":["Create storage pools","Rotate and back up unique local administrator passwords","Rotate DNS records","Manage Hyper-V checkpoints"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"ابزار LAPS خطر ناشی از استفاده از اعتبارنامه‌های مشترک یا ثابت برای حساب مدیر محلی را کاهش می‌دهد.","en":"LAPS reduces the risk of shared or static local administrator credentials.","de":"Die richtige Antwort ist „Rotate and back up unique local administrator passwords“; sie passt zum Bereich Secure Windows Server infrastructure und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"Windows LAPS برای مدیریت چه چیزی طراحی شده است؟","optionsFa":["ایجاد استخرهای ذخیره‌سازی (Storage Pools)","تغییر دوره‌ای (Rotate) و پشتیبان‌گیری از رمزهای عبور منحصربه‌فرد مدیر محلی (Local Administrator)","تغییر دوره‌ای رکوردهای DNS","مدیریت نقاط بازرسی (Checkpoints) در Hyper-V"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/laps/laps-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Implement least privilege and privileged access","objectiveId":"sec-privileged-access","topic":"Windows LAPS","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/laps/laps-overview"],"keyPoints":["Windows LAPS manages unique local administrator passwords on managed devices and servers.","Passwords are rotated on a policy schedule and backed up to a chosen directory store.","It removes the need to share a single local administrator password across many machines."],"whyOthers":["LAPS does not create storage pools.","","It does not rotate DNS records.","It does not manage Hyper-V checkpoints."],"commandPath":[{"label":"Read the current local administrator password for a device","command":"Get-LapsADPassword -Identity SRV01 -AsPlainText"}],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 and to supported client releases. LAPS can back up passwords to Active Directory or to Microsoft Entra ID depending on the configuration."},
{"id":"az802-q-224","domain":"Secure Windows Server infrastructure","text":"Why is a unique local administrator password safer than one shared across all servers?","options":["Compromise of one machine does not automatically provide the same credential for others","It eliminates the need for MFA","It disables logging","It makes domain admin unnecessary in every case"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"رمزهای عبور منحصربه‌فرد، حرکت جانبی (lateral movement) ناشی از استفاده مجدد از رمز عبور را کاهش می‌دهند.","en":"Unique passwords reduce lateral movement through password reuse.","de":"Die richtige Antwort ist „Compromise of one machine does not automatically provide the same credential for others“; sie passt zum Bereich Secure Windows Server infrastructure und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"چرا رمز عبور منحصربه‌فرد برای مدیر محلی (Local Administrator) امن‌تر از رمز عبوری است که بین تمام سرورها مشترک است؟","optionsFa":["به خطر افتادن یک ماشین، به‌طور خودکار همان اعتبارنامه (credential) را برای سایر ماشین‌ها فراهم نمی‌کند","نیاز به احراز هویت چندعاملی (MFA) را از بین می‌برد","ثبت وقایع (logging) را غیرفعال می‌کند","در همه موارد، نیاز به مدیر دامنه (Domain Admin) را منتفی می‌کند"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/laps/laps-overview","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/implementing-least-privilege-administrative-models"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Implement least privilege and privileged access","objectiveId":"sec-privileged-access","topic":"Local administrator passwords","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/laps/laps-overview","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/implementing-least-privilege-administrative-models"],"keyPoints":["A unique password on each server means compromising one machine does not grant the same credential on others.","Reused local administrator passwords are a classic lateral-movement path.","Uniqueness limits the blast radius without requiring more privileged accounts."],"whyOthers":["","Unique passwords do not remove the need for multi-factor authentication where it is available.","They do not disable logging; auditing remains important.","They do reduce the need for broad administrative rights, but they do not make domain-level administration unnecessary in every case."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Unique local passwords work alongside other controls such as tiering and just-in-time access rather than replacing them."},
{"id":"az802-q-225","domain":"Secure Windows Server infrastructure","text":"What does Microsoft Defender for Servers provide?","options":["DHCP failover","AD schema management","DFS namespace referrals","Security posture and threat-protection capabilities for supported servers"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"سرویس Defender for Servers، توصیه‌های امنیتی سرور، حفاظت و قابلیت‌های امنیتی ابری مرتبط را یکپارچه می‌کند.","en":"Defender for Servers integrates server security recommendations, protection, and related cloud security capabilities.","de":"Die richtige Antwort ist „Security posture and threat-protection capabilities for supported servers“; sie passt zum Bereich Secure Windows Server infrastructure und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"سرویس Microsoft Defender for Servers چه امکاناتی ارائه می‌دهد؟","optionsFa":["قابلیت Failover برای DHCP","مدیریت طرح‌واره (schema) سرویس AD","ارجاعات فضای نام (namespace referrals) در DFS","وضعیت امنیتی و قابلیت‌های حفاظت در برابر تهدیدات برای سرورهای پشتیبانی‌شده"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/defender-for-cloud/defender-for-servers-introduction"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure threat protection features","objectiveId":"sec-threat-protection","topic":"Microsoft Defender for Servers","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/defender-for-cloud/defender-for-servers-introduction"],"keyPoints":["Microsoft Defender for Servers provides security posture and threat protection for supported servers.","It covers Azure virtual machines and Azure Arc-enabled servers.","It integrates with other Defender for Cloud capabilities, such as just-in-time access and vulnerability assessment."],"whyOthers":["It does not provide DHCP failover.","It does not manage the AD schema.","It does not provide DFS namespace referrals.",""],"requirements":"Applies to Microsoft Defender for Cloud. Onboarding hybrid servers requires Azure Arc, and the plan selected determines which protection features are enabled."},
{"id":"az802-q-226","domain":"Secure Windows Server infrastructure","text":"What is the principle of least privilege?","options":["Allow all inbound traffic","Use one password everywhere","Give identities only the access required for their tasks","Give all administrators Domain Admins"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"اصل حداقل امتیاز، میزان خسارت ناشی از اشتباهات، حساب‌های کاربریِ به خطر افتاده و مجوزهای بیش‌ازحد را محدود می‌کند.","en":"Least privilege limits damage from mistakes, compromised accounts, and excessive permissions.","de":"Die richtige Antwort ist „Give identities only the access required for their tasks“; sie passt zum Bereich Secure Windows Server infrastructure und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"اصل «حداقل امتیاز» (Least Privilege) چیست؟","optionsFa":["مجاز دانستن تمام ترافیک ورودی","استفاده از یک رمز عبور واحد در همه جا","اعطای دسترسی به هویت‌ها (کاربران/سرویس‌ها) تنها در حدِ مورد نیاز برای انجام وظایفشان","اعطای نقش Domain Admins به تمام مدیران سیستم"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/implementing-least-privilege-administrative-models","https://learn.microsoft.com/en-us/security/privileged-access-workstations/overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Implement least privilege and privileged access","objectiveId":"sec-privileged-access","topic":"Least privilege","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/implementing-least-privilege-administrative-models","https://learn.microsoft.com/en-us/security/privileged-access-workstations/overview"],"keyPoints":["Least privilege means each identity receives only the access it needs to perform its task.","It limits the damage from mistakes, compromised accounts, and misuse.","It also reduces lateral movement, because one compromised account does not open everything."],"whyOthers":["Allowing all inbound traffic removes network restrictions and is not least privilege.","Using one password everywhere increases the impact of a single compromise.","","Giving all administrators Domain Admins membership is the opposite of least privilege."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Least privilege is implemented with scoped group membership, delegation, just-in-time access, and separated administrative accounts."},
{"id":"az802-q-227","domain":"Secure Windows Server infrastructure","text":"Which account is most appropriate for routine help-desk password resets?","options":["Built-in Guest","A delegated help-desk group with reset-password rights on selected OUs","Enterprise Admin","Schema Admin"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"تفویض اختیارِ محدود (Scoped delegation) امکان انجام این وظیفه را بدون اعطای اختیارات مدیریتی در سطح کل Forest فراهم می‌کند.","en":"Scoped delegation meets the task without granting forest-wide administrative power.","de":"Die richtige Antwort ist „A delegated help-desk group with reset-password rights on selected OUs“; sie passt zum Bereich Secure Windows Server infrastructure und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام حساب کاربری برای انجام امور معمولِ بازنشانی رمز عبور توسط واحد پشتیبانی (Help-desk) مناسب‌تر است؟","optionsFa":["حساب کاربری پیش‌فرض Guest","گروهی از کارکنان پشتیبانی که برای بازنشانی رمز عبور در واحدهای سازمانی (OU) منتخب، تفویض اختیار شده‌اند","Enterprise Admin","Schema Admin"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/implementing-least-privilege-administrative-models","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/delegation-control-wizard"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Implement least privilege and privileged access","objectiveId":"sec-privileged-access","topic":"Delegated administration","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/implementing-least-privilege-administrative-models","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/delegation-control-wizard"],"keyPoints":["A delegated help-desk group with reset-password rights on selected OUs gives exactly the task and no more.","Scoped delegation meets the operation without granting forest-wide power.","It also keeps the action auditable, because the group and its scope are explicit."],"whyOthers":["The built-in Guest account is disabled by default and unsuitable for administrative work.","","Enterprise Admin grants forest-wide control, far beyond password resets.","Schema Admin can change the forest schema and is far more privileged than the task requires."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Delegation is granted on the OU, and an object moved out of that OU loses the delegated rights."},
{"id":"az802-q-228","domain":"Secure Windows Server infrastructure","text":"What is the purpose of protected users in AD DS?","options":["Apply stronger authentication protections and restrict legacy credential behavior","Allow anonymous access","Disable password policy","Make users local administrators"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"عضویت در گروه کاربران محافظت‌شده، میزان قرار گرفتن در معرض چندین خطرِ سرقت اعتبارنامه و روش‌های احراز هویت قدیمی را کاهش می‌دهد.","en":"Protected Users membership reduces exposure to several credential-theft and legacy-authentication risks.","de":"Die richtige Antwort ist „Apply stronger authentication protections and restrict legacy credential behavior“; sie passt zum Bereich Secure Windows Server infrastructure und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"هدف از گروه «کاربران محافظت‌شده» (Protected Users) در AD DS چیست؟","optionsFa":["اعمال محافظت‌های احراز هویت قوی‌تر و محدود کردن رفتار مربوط به اعتبارنامه‌های (credentials) قدیمی","امکان دسترسی ناشناس (Anonymous access)","غیرفعال کردن سیاست رمز عبور","تبدیل کاربران به مدیران محلی (Local Administrators)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/security/credentials-protection-and-management/protected-users-security-group","https://learn.microsoft.com/en-us/windows/security/identity-protection/credential-guard/"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage credential protection","objectiveId":"sec-credentials","topic":"Protected Users","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/security/credentials-protection-and-management/protected-users-security-group","https://learn.microsoft.com/en-us/windows/security/identity-protection/credential-guard/"],"keyPoints":["The Protected Users group applies stronger protections that cannot be configured for individual accounts.","Members cannot use NTLM, digest, or CredSSP authentication and cannot be delegated.","Kerberos ticket lifetimes are shortened, which reduces exposure of cached credentials."],"whyOthers":["","Protected Users does not allow anonymous access.","It does not disable password policy; members are still subject to it.","It does not make users local administrators."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Membership can break applications that depend on NTLM or delegation, so it should be tested before adding high-value accounts."},
{"id":"az802-q-229","domain":"Secure Windows Server infrastructure","text":"What is Microsoft Entra Password Protection for AD DS designed to prevent?","options":["Unauthorized DNS delegation","VHDX fragmentation","DHCP scope overlap","Use of known weak or banned passwords in on-premises domain accounts"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"این قابلیت محافظتی، ارزیابی رمزهای عبور ممنوعه را از طریق مؤلفه‌های مورد نیاز خود به AD DS نیز تعمیم می‌دهد.","en":"The protection extends banned-password evaluation to AD DS through its required components.","de":"Die richtige Antwort ist „Use of known weak or banned passwords in on-premises domain accounts“; sie passt zum Bereich Secure Windows Server infrastructure und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"قابلیت Microsoft Entra Password Protection برای AD DS به منظور جلوگیری از چه چیزی طراحی شده است؟","optionsFa":["تفویض (delegation) غیرمجاز DNS","تکه‌تکه شدن (fragmentation) فایل‌های VHDX","هم‌پوشانی دامنه‌های DHCP (DHCP scopes)","استفاده از رمزهای عبور ضعیفِ شناخته‌شده یا ممنوعه در حساب‌های دامنه محلی (on-premises)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/entra/identity/authentication/concept-password-ban-bad-on-premises","https://learn.microsoft.com/en-us/windows-server/security/credentials-protection-and-management/protected-users-security-group"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage credential protection","objectiveId":"sec-credentials","topic":"Password protection","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/entra/identity/authentication/concept-password-ban-bad-on-premises","https://learn.microsoft.com/en-us/windows-server/security/credentials-protection-and-management/protected-users-security-group"],"keyPoints":["Microsoft Entra Password Protection extends banned-password evaluation to on-premises Active Directory.","It uses a global banned-password list plus optional custom lists.","It blocks known weak passwords at the point of change, which raises the baseline for the whole domain."],"whyOthers":["It does not prevent unauthorized DNS delegation.","It has nothing to do with VHDX fragmentation.","It does not address DHCP scope overlap.",""],"requirements":"Applies to AD DS on Windows Server 2025, 2022, 2019, and 2016 and to Microsoft Entra ID. On-premises deployment requires a proxy and a domain controller agent component."},
{"id":"az802-q-230","domain":"Secure Windows Server infrastructure","text":"Which action helps harden a domain controller?","options":["Permit anonymous SMB","Use the same local administrator password everywhere","Minimize installed roles, restrict interactive logon, patch it, and monitor privileged activity","Install unrelated desktop applications"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"کنترل‌کننده‌های دامنه، سیستم‌های هویت‌سنجی بسیار حیاتی هستند و باید سطح حمله (attack surface) کوچک و به‌شدت کنترل‌شده‌ای داشته باشند.","en":"Domain controllers are high-value identity systems and should have a small, tightly controlled attack surface.","de":"Die richtige Antwort ist „Minimize installed roles, restrict interactive logon, patch it, and monitor privileged activity“; sie passt zum Bereich Secure Windows Server infrastructure und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام اقدام به ایمن‌سازی (hardening) یک کنترل‌کننده دامنه (Domain Controller) کمک می‌کند؟","optionsFa":["مجاز کردن دسترسی ناشناس SMB","استفاده از یک رمز عبور یکسان برای مدیر محلی در همه جا","به حداقل رساندن نقش‌های نصب‌شده، محدود کردن ورود تعاملی (interactive logon)، اعمال وصله‌های امنیتی و نظارت بر فعالیت‌های دارای امتیاز (privileged activity)","نصب برنامه‌های دسکتاپ غیرمرتبط"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/best-practices-for-securing-active-directory","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/tier-model"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Harden Windows Server with security baselines","objectiveId":"sec-baselines","topic":"Domain controller hardening","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/best-practices-for-securing-active-directory","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/tier-model"],"keyPoints":["Minimise the roles installed on a domain controller so its attack surface stays small.","Restrict interactive logon so that only trusted administrators can sign in on it.","Keep it patched and monitor privileged activity, because a compromised controller compromises the identity system."],"whyOthers":["Permitting anonymous SMB exposes directory information and is not a hardening measure.","Reusing the same local administrator password everywhere enables lateral movement.","","Installing unrelated desktop applications increases the attack surface on a high-value server."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Domain controllers should also avoid running other roles where possible, and their administration should follow the tier model."},
{"id":"az802-q-231","domain":"Secure Windows Server infrastructure","text":"Which group should generally be protected most carefully because it has broad domain control?","options":["Everyone","Domain Admins","Domain Users","Authenticated Users"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"عضویت در گروه مدیران دامنه (Domain Admins) کنترل گسترده‌ای را فراهم می‌کند؛ بنابراین تعداد اعضای آن باید به حداقل برسد، فعالیت‌هایشان تحت نظارت باشد و در صورت امکان، دسترسی آن‌ها محدود به بازه زمانی مشخصی گردد.","en":"Domain Admin membership grants extensive control and should be minimized, monitored, and time-bound where possible.","de":"Die richtige Antwort ist „Domain Admins“; sie passt zum Bereich Secure Windows Server infrastructure und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام گروه به دلیل داشتن کنترل گسترده بر دامنه، عموماً باید با بیشترین دقت محافظت شود؟","optionsFa":["همه افراد (Everyone)","مدیران دامنه (Domain Admins)","کاربران دامنه (Domain Users)","کاربران احراز هویت‌شده (Authenticated Users)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/implementing-least-privilege-administrative-models","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/best-practices-for-securing-active-directory"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Implement least privilege and privileged access","objectiveId":"sec-privileged-access","topic":"Privileged groups","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/implementing-least-privilege-administrative-models","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/best-practices-for-securing-active-directory"],"keyPoints":["Domain Admins grants extensive control over the domain and its data.","Membership should be minimal, monitored, and time-bound where the design allows.","Protecting the accounts that hold this power protects the whole domain."],"whyOthers":["Everyone is a broad default group for basic access and does not confer domain control.","","Domain Users is the default group for ordinary user accounts and holds no administrative power.","Authenticated Users covers all authenticated identities and does not grant domain administration."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Equivalent caution applies to Enterprise Admins, Schema Admins, and Administrators in the forest root domain."},
{"id":"az802-q-232","domain":"Secure Windows Server infrastructure","text":"What is an authentication policy silo used for?","options":["Restrict which accounts can authenticate to which computers and under what policy","Store user home directories","Configure DNS forwarding","Balance DHCP leases"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"سیلوهای سیاست احراز هویت کمک می‌کنند تا استفاده از حساب‌های دارای امتیاز (Privileged Accounts) به میزبان‌های تأییدشده محدود شود.","en":"Authentication policy silos help limit privileged account use to approved hosts.","de":"Die richtige Antwort ist „Restrict which accounts can authenticate to which computers and under what policy“; sie passt zum Bereich Secure Windows Server infrastructure und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کاربرد «سیلوی سیاست احراز هویت» (Authentication Policy Silo) چیست؟","optionsFa":["محدود کردن اینکه کدام حساب‌های کاربری می‌توانند در کدام رایانه‌ها و تحت چه سیاستی احراز هویت کنند","ذخیره‌سازی دایرکتوری‌های خانگی (Home Directories) کاربران","پیکربندی ارسال (Forwarding) در DNS","متعادل‌سازی اجاره‌های (Leases) DHCP"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/security/credentials-protection-and-management/authentication-policies-and-authentication-policy-silos","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/tier-model"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Implement least privilege and privileged access","objectiveId":"sec-privileged-access","topic":"Authentication policy silos","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/security/credentials-protection-and-management/authentication-policies-and-authentication-policy-silos","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/tier-model"],"keyPoints":["An authentication policy silo restricts which accounts can authenticate on which computers.","It can also apply a stricter authentication policy to those accounts.","It is used to confine privileged accounts to approved administrative hosts."],"whyOthers":["","A silo does not store user home directories.","It does not configure DNS forwarding.","It does not balance DHCP leases."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 with the required domain functional level. Silo membership must be populated deliberately, because a misconfigured silo can block legitimate sign-in."},
{"id":"az802-q-233","domain":"Secure Windows Server infrastructure","text":"What is NTLM auditing used for?","options":["Check disk fragmentation","Test DHCP reservations","Monitor VM memory","Identify systems and applications still using NTLM before restricting it"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"حسابرسی، وابستگی‌ها را آشکار می‌سازد تا مدیران بتوانند روش‌های احراز هویت قدیمی (Legacy) را با ایمنی کامل تغییر داده یا اصلاح کنند.","en":"Auditing reveals dependencies so administrators can migrate or remediate legacy authentication safely.","de":"Die richtige Antwort ist „Identify systems and applications still using NTLM before restricting it“; sie passt zum Bereich Secure Windows Server infrastructure und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کاربرد قابلیت حسابرسی (Auditing) برای NTLM چیست؟","optionsFa":["بررسی تکه‌تکه شدن (Fragmentation) دیسک","آزمایش رزروهای DHCP","نظارت بر حافظه ماشین مجازی (VM)","شناسایی سیستم‌ها و برنامه‌هایی که پیش از اعمال محدودیت بر NTLM، همچنان از آن استفاده می‌کنند"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/security/kerberos/ntlm-overview","https://learn.microsoft.com/en-us/windows-server/security/kerberos/kerberos-authentication-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage credential protection","objectiveId":"sec-credentials","topic":"NTLM auditing","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/security/kerberos/ntlm-overview","https://learn.microsoft.com/en-us/windows-server/security/kerberos/kerberos-authentication-overview"],"keyPoints":["NTLM auditing identifies which systems and applications still rely on NTLM.","The result is used to remediate or migrate those dependencies before NTLM is restricted.","Auditing first avoids breaking authentication when restrictions are applied."],"whyOthers":["NTLM auditing does not check disk fragmentation.","It does not test DHCP reservations.","It does not monitor virtual machine memory.",""],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Audit events are collected in the Windows event logs and can be centralised for analysis before any blocking policy is enabled."},
{"id":"az802-q-234","domain":"Secure Windows Server infrastructure","text":"What is a common security improvement over unrestricted NTLM?","options":["Share one service account","Disable all auditing","Prefer Kerberos for domain authentication and remove unnecessary NTLM dependencies","Enable anonymous authentication"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"پروتکل Kerberos احراز هویت قوی‌تری را که با دامنه یکپارچه شده است فراهم می‌کند و از سناریوهای احراز هویت متقابل (Mutual Authentication) پشتیبانی می‌نماید.","en":"Kerberos provides stronger domain-integrated authentication and supports mutual authentication scenarios.","de":"Die richtige Antwort ist „Prefer Kerberos for domain authentication and remove unnecessary NTLM dependencies“; sie passt zum Bereich Secure Windows Server infrastructure und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"یک بهبود امنیتی رایج نسبت به حالت NTLM بدون محدودیت چیست؟","optionsFa":["استفاده مشترک از یک حساب سرویس (Service Account)","غیرفعال کردن تمام قابلیت‌های حسابرسی (Auditing)","اولویت دادن به Kerberos برای احراز هویت در دامنه و حذف وابستگی‌های غیرضروری به NTLM","فعال‌سازی احراز هویت ناشناس (Anonymous Authentication)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/security/kerberos/kerberos-authentication-overview","https://learn.microsoft.com/en-us/windows-server/security/kerberos/ntlm-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage credential protection","objectiveId":"sec-credentials","topic":"Authentication protocols","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/security/kerberos/kerberos-authentication-overview","https://learn.microsoft.com/en-us/windows-server/security/kerberos/ntlm-overview"],"keyPoints":["Kerberos is the preferred domain authentication protocol and supports mutual authentication.","Removing unnecessary NTLM dependencies reduces exposure to relay and credential-theft techniques.","The migration should be driven by audit data so nothing legitimate breaks."],"whyOthers":["Sharing one service account across many services increases the impact of any compromise.","Disabling all auditing removes the evidence needed to verify the change.","","Enabling anonymous authentication weakens security instead of improving it."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. NTLM cannot always be removed completely, so the goal is to eliminate unnecessary use and harden what remains."},
{"id":"az802-q-235","domain":"Secure Windows Server infrastructure","text":"Which control protects a data volume if a stolen disk is attached to another machine?","options":["Group Policy loopback","BitLocker","DHCP failover","DNSSEC"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"بیت‌لاکر (BitLocker) داده‌های ساکن (Data at rest) را رمزنگاری می‌کند و از دسترسی آفلاین به دیسک بدون وجود مکانیزم محافظتی (protector) لازم، جلوگیری می‌نماید.","en":"BitLocker encrypts data at rest and prevents offline disk access without the required protector.","de":"Die richtige Antwort ist „BitLocker“; sie passt zum Bereich Secure Windows Server infrastructure und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام مکانیزم کنترلی در صورتی که دیسکِ سرقت‌شده به دستگاه دیگری متصل شود، از حجم داده (Data Volume) محافظت می‌کند؟","optionsFa":["Group Policy loopback","BitLocker","DHCP failover","DNSSEC"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows/security/operating-system-security/data-protection/bitlocker/","https://learn.microsoft.com/en-us/windows-server/storage/file-server/smb-secure-traffic"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage credential protection","objectiveId":"sec-credentials","topic":"Data-at-rest protection","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows/security/operating-system-security/data-protection/bitlocker/","https://learn.microsoft.com/en-us/windows-server/storage/file-server/smb-secure-traffic"],"keyPoints":["BitLocker encrypts volume data so a disk moved to another machine cannot be read without a protector.","It addresses the stolen-disk threat directly.","It complements network protections such as SMB encryption, which secures data in transit."],"whyOthers":["Group Policy loopback affects user policy application and does not encrypt data.","","DHCP failover provides address-service redundancy and does not encrypt volumes.","DNSSEC signs DNS data and does not protect stored files."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Recovery information must be escrowed so that a legitimate recovery is still possible after hardware or firmware changes."},
{"id":"az802-q-236","domain":"Secure Windows Server infrastructure","text":"What is the purpose of auditing object access on a file server?","options":["Record selected access attempts to files and folders","Give users access automatically","Replicate the share","Increase disk capacity"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"حسابرسی دسترسی به اشیاء، از فرآیندهای تحقیقاتی و رعایت الزامات (Compliance) پشتیبانی می‌کند، اما باید محدوده‌ی آن به درستی تعیین شود تا از ایجاد حجم بیش‌ازحدِ داده‌های غیرضروری (Noise) جلوگیری گردد.","en":"Object-access auditing supports investigations and compliance, but it should be scoped to avoid excessive noise.","de":"Die richtige Antwort ist „Record selected access attempts to files and folders“; sie passt zum Bereich Secure Windows Server infrastructure und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"هدف از حسابرسی (Auditing) دسترسی به اشیاء (Object Access) در یک فایل‌سرور چیست؟","optionsFa":["ثبت تلاش‌های منتخب برای دسترسی به فایل‌ها و پوشه‌ها","اعطای خودکار دسترسی به کاربران","تکثیر (Replicate) منبع اشتراک‌گذاری‌شده (Share)","افزایش ظرفیت دیسک"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows/security/threat-protection/auditing/advanced-security-audit-policy-settings","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/best-practices-for-securing-active-directory"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Audit and monitor security events","objectiveId":"sec-audit","topic":"Object access auditing","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows/security/threat-protection/auditing/advanced-security-audit-policy-settings","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/best-practices-for-securing-active-directory"],"keyPoints":["Object-access auditing records selected successful or failed access attempts on files and folders.","It requires both an audit policy and a system access control list entry on the object.","It should be scoped to high-value data to keep the log volume manageable."],"whyOthers":["","Auditing does not grant access; permissions do.","It does not replicate a share; DFS Replication does that.","It does not increase disk capacity."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Advanced audit policy allows the specific subcategories to be selected rather than enabling whole categories."},
{"id":"az802-q-237","domain":"Secure Windows Server infrastructure","text":"Which audit policy is most relevant when investigating repeated account lockouts?","options":["Audit printer color settings","Audit disk defragmentation only","Audit DNS TTL only","Audit user account management and authentication-related events"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"گزارش های احراز هویت و مدیریت حساب می توانند منبع و زمان بندی قفل ها را شناسایی کنند.","en":"Authentication and account-management logs can identify the source and timing of lockouts.","de":"Die richtige Antwort ist „Audit user account management and authentication-related events“; sie passt zum Bereich Secure Windows Server infrastructure und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام خط مشی حسابرسی هنگام بررسی قفل مکرر حساب مرتبط است؟","optionsFa":["تنظیمات رنگ چاپگر را بررسی کنید","فقط یکپارچه سازی دیسک حسابرسی","فقط TTL DNS را حسابرسی کنید","حسابرسی مدیریت حساب کاربری و رویدادهای مرتبط با احراز هویت"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows/security/threat-protection/auditing/advanced-security-audit-policy-settings","https://learn.microsoft.com/en-us/windows-server/security/kerberos/kerberos-authentication-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Audit and monitor security events","objectiveId":"sec-audit","topic":"Audit policy","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows/security/threat-protection/auditing/advanced-security-audit-policy-settings","https://learn.microsoft.com/en-us/windows-server/security/kerberos/kerberos-authentication-overview"],"keyPoints":["Account lockouts are investigated with account-management and authentication-related audit events.","These events show the account, the time, and often the source system involved.","Combining the events from domain controllers gives a clearer picture than reviewing one server."],"whyOthers":["Printer colour settings are unrelated to account lockouts.","Disk defragmentation events do not reveal lockout sources.","DNS TTL values are unrelated to authentication failures.",""],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Centralised collection of security events is important, because a lockout may be generated on a controller that did not originate it."},
{"id":"az802-q-238","domain":"Secure Windows Server infrastructure","text":"Why should SMBv1 normally be disabled when no legacy dependency exists?","options":["It provides DNSSEC","It enables BitLocker","It has an older security design and increases attack surface","It is required for modern SMB encryption"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"حذف پروتکل های قدیمی استفاده نشده، قرار گرفتن در معرض کلاس های شناخته شده حملات و پیکربندی نادرست را کاهش می دهد.","en":"Removing unused legacy protocols reduces exposure to known classes of attacks and misconfiguration.","de":"Die richtige Antwort ist „It has an older security design and increases attack surface“; sie passt zum Bereich Secure Windows Server infrastructure und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"چرا باید SMBv1 معمولاً غیرفعال شود در حالی که هیچ وابستگی قدیمی وجود ندارد؟","optionsFa":["DNSSEC را ارائه می دهد","BitLocker را فعال می کند","طراحی امنیتی قدیمی تری دارد و سطح حمله را افزایش می دهد.","برای رمزگذاری مدرن SMB مورد نیاز است"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/file-server/troubleshoot/detect-enable-and-disable-smbv1-v2-v3","https://learn.microsoft.com/en-us/windows-server/storage/file-server/smb-secure-traffic"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Harden Windows Server with security baselines","objectiveId":"sec-baselines","topic":"Legacy protocol removal","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/file-server/troubleshoot/detect-enable-and-disable-smbv1-v2-v3","https://learn.microsoft.com/en-us/windows-server/storage/file-server/smb-secure-traffic"],"keyPoints":["SMBv1 uses an older design with weaker protections than later SMB versions.","Leaving it enabled increases the attack surface for known exploitation techniques.","It should be removed once no legacy dependency remains, and the removal should be verified."],"whyOthers":["SMBv1 does not provide DNSSEC; that is a DNS feature.","It does not enable BitLocker.","","It is not required for modern SMB encryption; newer SMB versions provide that."],"commandPath":[{"label":"Check whether SMBv1 is enabled","command":"Get-SmbServerConfiguration | Select-Object EnableSMB1Protocol"},{"label":"Disable SMBv1 on the server","command":"Set-SmbServerConfiguration -EnableSMB1Protocol $false -Force"}],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. SMBv1 is not installed by default on current releases, but it can still be present after an upgrade from an older release."},
{"id":"az802-q-239","domain":"Secure Windows Server infrastructure","text":"What is the purpose of Microsoft Defender for Identity?","options":["Resize Azure VMs","Detect identity-related threats and suspicious activity in AD DS environments","Manage file quotas","Provide DHCP leases"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Defender for Identity سیگنال های هویت و فعالیت دایرکتوری را برای شناسایی رفتار مشکوک تجزیه و تحلیل می کند.","en":"Defender for Identity analyzes identity signals and directory activity to identify suspicious behavior.","de":"Die richtige Antwort ist „Detect identity-related threats and suspicious activity in AD DS environments“; sie passt zum Bereich Secure Windows Server infrastructure und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"هدف Microsoft Defender برای Identity چیست؟","optionsFa":["تغییر اندازه ماشین های مجازی Azure","شناسایی تهدیدهای مرتبط با هویت و فعالیت های مشکوک در محیط های AD DS","سهمیه های فایل را مدیریت کنید","اجاره نامه های DHCP را ارائه دهید"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/defender-for-identity/what-is"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Manage identity threats with Defender for Identity","objectiveId":"sec-identity-threat","topic":"Microsoft Defender for Identity","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/defender-for-identity/what-is"],"keyPoints":["Microsoft Defender for Identity detects identity-related threats and suspicious activity in Active Directory environments.","It analyses directory and authentication signals to identify techniques such as reconnaissance and credential abuse.","It helps surface attacks that are otherwise hard to see in individual event logs."],"whyOthers":["It does not resize Azure virtual machines.","","It does not manage file quotas.","It does not provide DHCP leases."],"requirements":"Applies to Microsoft Defender for Identity. A sensor is deployed to monitor domain controller traffic, and monitored domains are configured in the portal."},
{"id":"az802-q-240","domain":"Secure Windows Server infrastructure","text":"Which practice best protects privileged credentials?","options":["Use separate administrative accounts, MFA where available, and privileged-access workstations","Use a single daily account for all tasks","Store passwords in scripts","Allow interactive logon from every workstation"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"جداسازی و کنترل های قوی تر این احتمال را کاهش می دهد که مرور معمولی یا بدافزار اعتبارنامه های ممتاز را به خطر بیندازد.","en":"Separation and stronger controls reduce the chance that routine browsing or malware compromises privileged credentials.","de":"Die richtige Antwort ist „Use separate administrative accounts, MFA where available, and privileged-access workstations“; sie passt zum Bereich Secure Windows Server infrastructure und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام عمل به بهترین وجه از اعتبارنامه های ممتاز محافظت می کند؟","optionsFa":["از حساب های اداری جداگانه، MFA در صورت وجود و ایستگاه های کاری با دسترسی ممتاز استفاده کنید","برای همه کارها از یک حساب روزانه استفاده کنید","رمزهای عبور را در اسکریپت ها ذخیره کنید","اجازه ورود به سیستم تعاملی از هر ایستگاه کاری"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/security/privileged-access-workstations/overview","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/implementing-least-privilege-administrative-models"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Implement least privilege and privileged access","objectiveId":"sec-privileged-access","topic":"Privileged access","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/security/privileged-access-workstations/overview","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/implementing-least-privilege-administrative-models"],"keyPoints":["Administrative accounts should be separate from everyday user accounts.","Multi-factor authentication and hardened administrative workstations reduce the chance that routine activity compromises privileged credentials.","The goal is to keep privileged credentials away from browsing, email, and general workstation risk."],"whyOthers":["","Using a single account for all tasks exposes privileged credentials to routine risk.","Storing passwords in scripts leaves secrets readable by anyone with access to the file.","Allowing interactive logon from every workstation widens the paths an attacker can use."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Tiered administration and privileged-access workstations are the practical implementations of these practices."},
{"id":"az802-q-241","domain":"Secure Windows Server infrastructure","text":"What is a security option that can reduce anonymous enumeration of domain information?","options":["Enable anonymous SMB","Allow null sessions everywhere","Disable all domain auditing","Restrict anonymous access to directory and SAM information"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"محدود کردن استخراج ناشناس، افشای اطلاعاتی را که می‌تواند به انجام حملات کمک کند، کاهش می‌دهد.","en":"Limiting anonymous enumeration reduces information disclosure that can aid attacks.","de":"Die richtige Antwort ist „Restrict anonymous access to directory and SAM information“; sie passt zum Bereich Secure Windows Server infrastructure und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام گزینه امنیتی می‌تواند استخراج (enumeration) ناشناس اطلاعات دامنه را کاهش دهد؟","optionsFa":["فعال‌سازی SMB ناشناس","مجاز کردن نشست‌های Null (بدون احراز هویت) در همه جا","غیرفعال کردن تمام قابلیت‌های حسابرسی (auditing) دامنه","محدود کردن دسترسی ناشناس به اطلاعات دایرکتوری و SAM"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows/security/threat-protection/security-policy-settings/network-access-restrict-anonymous-access-to-named-pipes-and-shares","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/best-practices-for-securing-active-directory"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Harden Windows Server with security baselines","objectiveId":"sec-baselines","topic":"Information disclosure","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows/security/threat-protection/security-policy-settings/network-access-restrict-anonymous-access-to-named-pipes-and-shares","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/best-practices-for-securing-active-directory"],"keyPoints":["Restricting anonymous access to directory and SAM information reduces information disclosure.","Attackers often map users, groups, and shares before attempting an attack.","Reducing that reconnaissance data makes later stages of an attack harder."],"whyOthers":["Enabling anonymous SMB increases disclosure rather than reducing it.","Allowing null sessions everywhere is the classic exposure that this control removes.","Disabling all domain auditing removes visibility into activity.",""],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. The relevant settings are found under security options for network access and for restricting anonymous access."},
{"id":"az802-q-242","domain":"Secure Windows Server infrastructure","text":"Which practice is safest for service-account credentials?","options":["Never rotate the password","Grant the account Domain Admins","Use managed service accounts where supported and avoid embedding secrets in scripts","Put the password in a shared text file"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"هویت‌ها و حساب‌های مدیریت‌شده، نیاز به مدیریت دستی اطلاعات حساس را کاهش داده و از اعمال سطوح دسترسی کنترل‌شده پشتیبانی می‌کنند.","en":"Managed identities and accounts reduce secret handling and support controlled privilege.","de":"Die richtige Antwort ist „Use managed service accounts where supported and avoid embedding secrets in scripts“; sie passt zum Bereich Secure Windows Server infrastructure und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام روش برای مدیریت اعتبارنامه‌های (credentials) حساب‌های سرویس ایمن‌ترین است؟","optionsFa":["هرگز رمز عبور را تغییر ندهید (Rotate نکنید)","حساب کاربری را در گروه Domain Admins قرار دهید","در صورت پشتیبانی، از حساب‌های سرویس مدیریت‌شده (Managed Service Accounts) استفاده کنید و از قرار دادن اطلاعات حساس (مانند رمز عبور) درون اسکریپت‌ها خودداری کنید","رمز عبور را در یک فایل متنی مشترک قرار دهید"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/security/group-managed-service-accounts/group-managed-service-accounts-overview","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/implementing-least-privilege-administrative-models"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Implement least privilege and privileged access","objectiveId":"sec-privileged-access","topic":"Service-account security","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/security/group-managed-service-accounts/group-managed-service-accounts-overview","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/implementing-least-privilege-administrative-models"],"keyPoints":["Managed service accounts rotate their own passwords, so no one has to store or share a secret.","Avoiding embedded secrets removes a common way credentials leak through scripts and configuration files.","Where a managed account cannot be used, the credential should still be protected and rotated."],"whyOthers":["Never rotating a password leaves a long-lived secret exposed indefinitely.","Granting a service account Domain Admins gives far more privilege than the service needs.","","Putting the password in a shared text file exposes it to anyone who can read the file."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. A gMSA requires the KDS root key, and an sMSA is limited to a single host."},
{"id":"az802-q-243","domain":"Secure Windows Server infrastructure","text":"What is a Windows Server security baseline?","options":["A VM disk type","A recommended set of security configuration settings","A backup image","A DHCP scope"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"خط‌مشی‌های پایه، نقطه شروعی یکپارچه برای مقاوم‌سازی (Hardening) سیستم فراهم می‌کنند و پس از انجام آزمایش‌ها، قابل انطباق و تغییر هستند.","en":"Baselines provide a consistent starting point for hardening and can be adapted after testing.","de":"Die richtige Antwort ist „A recommended set of security configuration settings“; sie passt zum Bereich Secure Windows Server infrastructure und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"«خط‌مشی پایه امنیتی» (Security Baseline) در ویندوز سرور چیست؟","optionsFa":["نوعی دیسک ماشین مجازی (VM)","مجموعه‌ای توصیه‌شده از تنظیمات پیکربندی امنیتی","یک ایمیج پشتیبان (Backup image)","یک محدوده (Scope) در DHCP"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows/security/operating-system-security/device-management/windows-security-configuration-framework/windows-security-baselines"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Harden Windows Server with security baselines","objectiveId":"sec-baselines","topic":"Security baselines","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows/security/operating-system-security/device-management/windows-security-configuration-framework/windows-security-baselines"],"keyPoints":["A security baseline is a recommended set of security configuration settings for a Windows release.","It gives a consistent starting point for hardening rather than configuring each server by hand.","Baselines can be adapted after testing so that required workloads still function."],"whyOthers":["A virtual machine disk type is a storage choice and is not a baseline.","","A backup image is a recovery artefact, not a security configuration.","A DHCP scope defines addresses and is unrelated to baselines."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Baselines are version-specific and are distributed as Group Policy objects or configuration packages."},
{"id":"az802-q-244","domain":"Secure Windows Server infrastructure","text":"What is the best response when a security baseline breaks a required application?","options":["Document and approve a narrowly scoped exception while preserving other protections","Remove the entire baseline everywhere","Disable auditing on all servers","Grant the application full administrator rights"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"اعمال استثناهای مبتنی بر مدیریت ریسک، ایمن‌تر از کنار گذاشتن کلیِ کنترل‌های امنیتی است.","en":"Risk-managed exceptions are safer than abandoning security controls globally.","de":"Die richtige Antwort ist „Document and approve a narrowly scoped exception while preserving other protections“; sie passt zum Bereich Secure Windows Server infrastructure und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"بهترین واکنش در زمانی که یک «خط‌مشی پایه امنیتی» (Security Baseline) باعث اختلال در عملکرد یک برنامه کاربردیِ ضروری می‌شود، چیست؟","optionsFa":["ثبت و تصویب یک استثنا با دامنه محدود، ضمن حفظ سایر تدابیر حفاظتی","حذف کامل خط‌مشی پایه از تمام بخش‌ها","غیرفعال کردن قابلیت حسابرسی (Auditing) در تمام سرورها","اعطای دسترسی کامل مدیریتی (Administrator) به برنامه کاربردی"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/intune/device-security/security-baselines/configure-baselines","https://learn.microsoft.com/en-us/windows/security/operating-system-security/device-management/windows-security-configuration-framework/windows-security-baselines"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Harden Windows Server with security baselines","objectiveId":"sec-baselines","topic":"Baseline exceptions","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/intune/device-security/security-baselines/configure-baselines","https://learn.microsoft.com/en-us/windows/security/operating-system-security/device-management/windows-security-configuration-framework/windows-security-baselines"],"keyPoints":["A narrowly scoped, documented exception preserves risk management without discarding the whole baseline.","The exception should name the setting, the scope, the reason, and its review date.","Removing the entire baseline everywhere would expose every other system to unnecessary risk."],"whyOthers":["","Removing the entire baseline everywhere trades a small compatibility issue for a large security regression.","Disabling auditing on all servers removes the evidence needed for investigations.","Granting the application full administrator rights is a broader change than the baseline setting that caused the problem."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Exceptions are normally tracked in a change or risk register, with an owner and a review date."},
{"id":"az802-q-245","domain":"Secure Windows Server infrastructure","text":"Which firewall rule design is most secure?","options":["Allow Any/Any inbound","Disable the firewall on domain networks","Allow all management ports permanently","Explicitly allow required traffic from approved sources and deny unnecessary traffic"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"قوانین دقیق و مستند، سطح حمله را کاهش داده و در عین حال عملکرد سرویس‌های ضروری را حفظ می‌کنند.","en":"Narrow, documented rules reduce attack surface while preserving required service operation.","de":"Die richtige Antwort ist „Explicitly allow required traffic from approved sources and deny unnecessary traffic“; sie passt zum Bereich Secure Windows Server infrastructure und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام طراحی برای قوانین فایروال امن‌تر است؟","optionsFa":["مجاز کردن تمام ترافیک‌های ورودی (Any/Any)","غیرفعال کردن فایروال در شبکه‌های دامین (Domain networks)","باز گذاشتن دائمی تمام پورت‌های مدیریتی","مجاز کردن صریح ترافیک مورد نیاز از منابع تأییدشده و مسدود کردن ترافیک غیرضروری"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows/security/operating-system-security/network-security/windows-firewall/rules","https://learn.microsoft.com/en-us/windows/security/operating-system-security/network-security/windows-firewall/"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure Windows Defender Firewall and IPsec","objectiveId":"sec-firewall","topic":"Firewall rule design","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows/security/operating-system-security/network-security/windows-firewall/rules","https://learn.microsoft.com/en-us/windows/security/operating-system-security/network-security/windows-firewall/"],"keyPoints":["The most secure rule set explicitly allows only the required traffic from approved sources.","Everything not needed is denied, which keeps the attack surface small.","Rules should be documented so that each allowance has a clear purpose and owner."],"whyOthers":["Allow Any/Any inbound removes the filtering the firewall exists to provide.","Disabling the firewall on domain networks exposes every open port on the system.","Allowing all management ports permanently is broader than the required management traffic.",""],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Rules can be scoped by profile, program, service, local and remote port, and remote address to keep them narrow."},
{"id":"az802-q-246","domain":"Monitor and troubleshoot Windows Server environments","text":"Which tool provides counters for CPU, memory, disk, and network performance?","options":["Active Directory Users and Computers","Hyper-V Replica","Performance Monitor","DNS Manager"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"ابزار Performance Monitor شمارنده‌های عملکرد ویندوز را در طول زمان جمع‌آوری و نمایش می‌دهد.","en":"Performance Monitor collects and displays Windows performance counters over time.","de":"Die richtige Antwort ist „Performance Monitor“; sie passt zum Bereich Monitor and troubleshoot Windows Server environments und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام ابزار شمارنده‌هایی (counters) برای عملکرد پردازنده (CPU)، حافظه، دیسک و شبکه ارائه می‌دهد؟","optionsFa":["Active Directory Users and Computers","Hyper-V Replica","Performance Monitor","DNS Manager"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/perfmon","https://learn.microsoft.com/en-us/troubleshoot/windows-server/performance/troubleshoot-performance-problems-in-windows"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Use performance monitoring tools to establish baselines and detect resource bottlenecks affecting server workloads.","objectiveId":"perfmon-tools","topic":"Performance Monitor","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/perfmon","https://learn.microsoft.com/en-us/troubleshoot/windows-server/performance/troubleshoot-performance-problems-in-windows"],"keyPoints":["Performance Monitor (perfmon) exposes CPU, memory, disk, and network counters for live views and logged collections.","Baselines captured on a healthy server make later deviations meaningful.","PerfMon data complements, not replaces, event-based troubleshooting."],"whyOthers":["Active Directory Users and Computers manages directory objects and has no performance counters.","Hyper-V Replica replicates VMs to a standby host and does not measure resource usage.","","DNS Manager administers zones and records and does not expose system performance counters."]},
{"id":"az802-q-247","domain":"Monitor and troubleshoot Windows Server environments","text":"What is a Data Collector Set used for?","options":["Encrypt a volume","Collect performance counters, event traces, and configuration data according to a schedule","Create an AD group","Create a DHCP scope"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"مجموعه‌های جمع‌آوری داده (Data Collector Sets) از پایش (مانیتورینگ) تکرارپذیر و جمع‌آوری داده‌های مبنا (Baseline) پشتیبانی می‌کنند.","en":"Data Collector Sets support repeatable monitoring and baseline collection.","de":"Die richtige Antwort ist „Collect performance counters, event traces, and configuration data according to a schedule“; sie passt zum Bereich Monitor and troubleshoot Windows Server environments und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کاربرد Data Collector Set چیست؟","optionsFa":["رمزنگاری یک Volume (پارتیشن/درایو)","جمع‌آوری شمارنده‌های عملکرد، ردپای رویدادها (event traces) و داده‌های پیکربندی بر اساس یک زمان‌بندی مشخص","ایجاد یک گروه در Active Directory","ایجاد یک محدوده (Scope) در DHCP"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/perfmon","https://learn.microsoft.com/en-us/windows-server/administration/server-manager/view-and-configure-performance-event-and-service-data"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure Data Collector Sets to capture counters, event trace data, and configuration information on a schedule for later analysis.","objectiveId":"perfmon-tools","topic":"Performance Monitor","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/perfmon","https://learn.microsoft.com/en-us/windows-server/administration/server-manager/view-and-configure-performance-event-and-service-data"],"keyPoints":["A Data Collector Set groups performance counters, event trace providers, and configuration data under one schedule.","Logged data can be reviewed as reports, compared against baselines, or imported into analysis tools.","Built-in sets such as System Diagnostics bundle a useful starter collection."],"whyOthers":["Encryption of volumes is BitLocker or EFS functionality, unrelated to collector sets.","","Membership changes are a task for AD tools and delegation, not performance collection.","DHCP scope creation happens in DHCP administration, which has no collector semantics."]},
{"id":"az802-q-248","domain":"Monitor and troubleshoot Windows Server environments","text":"Which counter is most directly useful when investigating processor saturation?","options":["Processor\\\\% Processor Time","LogicalDisk\\\\% Free Space only","DNS\\\\Recursive Queries","DHCP\\\\Active Leases only"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"این شمارنده نشان می‌دهد چه مقدار از زمان پردازنده در حال مصرف است، هرچند برای شناسایی علت اصلی، به شمارنده‌های سطح پردازش (process-level) نیاز است.","en":"It shows how much processor time is being consumed, though process-level counters are needed to identify the cause.","de":"Die richtige Antwort ist „Processor\\\\% Processor Time“; sie passt zum Bereich Monitor and troubleshoot Windows Server environments und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"textFa":"هنگام بررسی اشباع (سچوریشن) پردازنده، کدام شمارنده (counter) بیشترین کاربرد مستقیم را دارد؟","optionsFa":["Processor\\% Processor Time","LogicalDisk\\% Free Space (فقط فضای آزاد)","DNS\\Recursive Queries","DHCP\\Active Leases (فقط اجاره‌های فعال)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/perfmon","https://learn.microsoft.com/en-us/troubleshoot/windows-server/performance/troubleshoot-performance-problems-in-windows"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Select processor counters such as % Processor Time when diagnosing CPU saturation, then isolate the consuming process.","objectiveId":"perfmon-tools","topic":"Performance Monitor","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/perfmon","https://learn.microsoft.com/en-us/troubleshoot/windows-server/performance/troubleshoot-performance-problems-in-windows"],"keyPoints":["Processor % Processor Time shows overall CPU utilization; values persisting near 100% indicate saturation.","Process object counters identify which process consumes the CPU next.","Use context, workload timing, and sustained values rather than single spikes."],"whyOthers":["","Free space measures capacity, not processor demand, and misses CPU saturation entirely.","DNS recursive query counts measure name-service activity, not processor saturation.","DHCP lease counts describe address allocation, not CPU pressure."]},
{"id":"az802-q-249","domain":"Monitor and troubleshoot Windows Server environments","text":"Which counters are useful for detecting disk latency?","options":["DNS query count only","User logon count only","DHCP scope utilization only","Average Disk sec/Read and Average Disk sec/Write"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"این شمارنده‌ها زمان پاسخ‌دهی فضای ذخیره‌سازی را نشان می‌دهند و باید با طول صف و حجم کاری (workload) سنجیده و مقایسه شوند.","en":"These counters indicate storage response time and should be correlated with queue length and workload.","de":"Die richtige Antwort ist „Average Disk sec/Read and Average Disk sec/Write“; sie passt zum Bereich Monitor and troubleshoot Windows Server environments und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام شمارنده‌ها برای تشخیص تأخیر (latency) دیسک مفید هستند؟","optionsFa":["فقط تعداد پرس‌وجوهای DNS","فقط تعداد ورود کاربران به سیستم (logon)","فقط میزان استفاده از محدوده (scope) DHCP","Average Disk sec/Read و Average Disk sec/Write"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/perfmon","https://learn.microsoft.com/en-us/troubleshoot/windows-server/performance/troubleshoot-performance-problems-in-windows"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Use Average Disk sec/Read and Average Disk sec/Write to detect storage latency and correlate it with queue depth and workload.","objectiveId":"perfmon-tools","topic":"Performance Monitor","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/perfmon","https://learn.microsoft.com/en-us/troubleshoot/windows-server/performance/troubleshoot-performance-problems-in-windows"],"keyPoints":["Average Disk sec/Read and sec/Write approximate storage response time in seconds.","Current Queue Length plus latency distinguishes a busy but healthy disk from a saturated one.","Interpret values against the storage type; SSD and NVMe targets tolerate far less latency than spinning disks."],"whyOthers":["DNS query counts never describe disk response time.","User logon counts measure authentication volume, not storage latency.","DHCP scope utilization tracks address pools, unrelated to disk latency.",""]},
{"id":"az802-q-250","domain":"Monitor and troubleshoot Windows Server environments","text":"What does System Insights provide?","options":["A DHCP relay","A file-system format","Local predictive analytics for selected Windows Server capacity and health signals","A replacement for Active Directory"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"قابلیت System Insights از تحلیل‌های محلی برای پیش‌بینی روند ظرفیت یا سلامت استفاده می‌کند، بدون اینکه نیازی به خروج تمام داده‌ها از سرور باشد.","en":"System Insights uses local analytics to help predict capacity or health trends without requiring all data to leave the server.","de":"Die richtige Antwort ist „Local predictive analytics for selected Windows Server capacity and health signals“; sie passt zum Bereich Monitor and troubleshoot Windows Server environments und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"textFa":"System Insights چه قابلیتی را ارائه می‌دهد؟","optionsFa":["یک DHCP relay","یک فرمت سیستم فایل","تحلیل‌های پیش‌بینانه محلی برای شاخص‌های منتخب ظرفیت و سلامت ویندوز سرور","جایگزینی برای Active Directory"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/manage/system-insights/overview","https://learn.microsoft.com/en-us/windows-server/manage/system-insights/managing-capabilities"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Describe System Insights as local predictive analytics for Windows Server capacity and health signals.","objectiveId":"system-insights","topic":"System Insights","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/manage/system-insights/overview","https://learn.microsoft.com/en-us/windows-server/manage/system-insights/managing-capabilities"],"keyPoints":["System Insights runs analytics locally on Windows Server 2019+ and forecasts disk, volume, CPU, and networking trends.","Default capabilities raise warnings; administrators can configure thresholds or add custom capabilities.","Data stays on the server, so predictions work without sending telemetry off-box."],"whyOthers":["DHCP relay is a network forwarding role with no analytics function.","ReFS is a resilient file-system format, not a prediction engine.","","System Insights supplements Active Directory rather than replacing any directory service."]},
{"id":"az802-q-251","domain":"Monitor and troubleshoot Windows Server environments","text":"Which log commonly contains service, driver, and system startup errors?","options":["Clipboard history","System event log","DNS zone file only","DHCP lease file only"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"لاگ System رویدادهای سیستم‌عامل و سرویس‌های مربوط به اجزای اصلی را ثبت می‌کند.","en":"The System log records operating-system and service events from core components.","de":"Die richtige Antwort ist „System event log“; sie passt zum Bereich Monitor and troubleshoot Windows Server environments und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام لاگ (Log) معمولاً حاوی خطاهای مربوط به سرویس‌ها، درایورها و راه‌اندازی سیستم است؟","optionsFa":["تاریخچه کلیپ‌بورد (Clipboard history)","لاگ رویدادهای سیستم (System event log)","فقط فایل ناحیه (Zone file) مربوط به DNS","فقط فایل اجاره (Lease file) مربوط به DHCP"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/server-manager/view-and-configure-performance-event-and-service-data","https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.diagnostics/get-winevent"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Use the System event log to investigate service, driver, and startup events.","objectiveId":"event-logs","topic":"Event logs","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/server-manager/view-and-configure-performance-event-and-service-data","https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.diagnostics/get-winevent"],"keyPoints":["The System log captures events from the operating system and its services, including service control manager errors and driver failures.","Filtering System log events by provider and level shortens diagnosis dramatically.","Retain and clear logs deliberately; deleting them destroys evidence."],"whyOthers":["Clipboard history is unrelated to service and driver events.","","DNS zone files hold resource records, not OS service events.","DHCP lease files record address assignments, not driver failures."]},
{"id":"az802-q-252","domain":"Monitor and troubleshoot Windows Server environments","text":"Which log commonly contains application crashes?","options":["Application event log","Security descriptor database only","SYSVOL only","DHCP relay log only"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"برنامه‌ها و اجزای مرتبط با آن‌ها، خطاها و هشدارها را در لاگ Application ثبت می‌کنند.","en":"Applications and application-related components write failures and warnings to the Application log.","de":"Die richtige Antwort ist „Application event log“; sie passt zum Bereich Monitor and troubleshoot Windows Server environments und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام لاگ معمولاً حاوی اطلاعات مربوط به کرش کردن (از کار افتادن ناگهانی) برنامه‌هاست؟","optionsFa":["لاگ رویدادهای برنامه (Application event log)","فقط پایگاه داده توصیف‌گر امنیتی (Security descriptor database)","فقط SYSVOL","فقط لاگ DHCP relay"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/server-manager/view-and-configure-performance-event-and-service-data","https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.diagnostics/get-winevent"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Use the Application event log to investigate application crashes and application-written events.","objectiveId":"event-logs","topic":"Event logs","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/server-manager/view-and-configure-performance-event-and-service-data","https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.diagnostics/get-winevent"],"keyPoints":["Applications and application components write errors and warnings to the Application log.","Crash events frequently name the faulting module, aiding rapid triage.","Pair Application events with reliability and crash dump data for deeper analysis."],"whyOthers":["","The security descriptor database is not an applications log and holds no crash records.","SYSVOL holds policy and scripts for the domain, not application crashes.","DHCP relay logs cover relay delivery only."]},
{"id":"az802-q-253","domain":"Monitor and troubleshoot Windows Server environments","text":"What does the Security event log record?","options":["Every DNS response by default","VM checkpoints only","Disk partition layouts only","Audited security events such as logons and object access"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"لاگ‌های امنیتی به سیاست نظارت (Audit Policy) وابسته‌اند و نقشی محوری در بررسی‌های مربوط به احراز هویت و دسترسی ایفا می‌کنند.","en":"Security logs depend on audit policy and are central to authentication and access investigations.","de":"Die richtige Antwort ist „Audited security events such as logons and object access“; sie passt zum Bereich Monitor and troubleshoot Windows Server environments und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"textFa":"لاگ رویدادهای امنیتی (Security event log) چه مواردی را ثبت می‌کند؟","optionsFa":["تمام پاسخ‌های DNS به صورت پیش‌فرض","فقط نقاط بازگشت (Checkpoint) ماشین مجازی","فقط چیدمان پارتیشن‌های دیسک","رویدادهای امنیتیِ تحت نظارت (Audit)، مانند ورود به سیستم و دسترسی به اشیاء"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/advanced-audit-policy-configuration","https://learn.microsoft.com/en-us/windows-server/administration/server-manager/view-and-configure-performance-event-and-service-data"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Describe the Security event log as the record of audited security events governed by audit policy.","objectiveId":"event-logs","topic":"Event logs","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/advanced-audit-policy-configuration","https://learn.microsoft.com/en-us/windows-server/administration/server-manager/view-and-configure-performance-event-and-service-data"],"keyPoints":["Security log content is controlled by advanced audit policy, covering logons, object access, policy changes, and directory events.","Absence of events often means no audit subcategory is enabled, not that nothing happened.","Security logs anchor investigations of authentication and access problems."],"whyOthers":["DNS responses are not audited security events by default.","VM checkpoints live in Hyper-V storage, never in the Security log.","Disk partition layouts are storage configuration, not audited events.",""]},
{"id":"az802-q-254","domain":"Monitor and troubleshoot Windows Server environments","text":"An alert should fire when free disk space drops below 15%. What should be configured?","options":["A fine-grained password policy","A DFS referral","A threshold rule based on a disk-space metric or performance counter","A DNS conditional forwarder"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"هشدارهای ظرفیت باید معیار مربوطه را اندازه‌گیری کنند و شامل یک بازه زمانی ارزیابی مناسب باشند تا از هشدارهای کاذبِ ناشی از نوسانات لحظه‌ای (Transient noise) جلوگیری شود.","en":"Capacity alerts should measure the relevant metric and include a useful evaluation window to avoid transient noise.","de":"Die richtige Antwort ist „A threshold rule based on a disk-space metric or performance counter“; sie passt zum Bereich Monitor and troubleshoot Windows Server environments und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"textFa":"در صورتی که فضای خالی دیسک به کمتر از ۱۵ درصد کاهش یابد، باید یک هشدار (Alert) صادر شود. چه چیزی باید پیکربندی شود؟","optionsFa":["یک سیاست رمز عبور با جزئیات دقیق (Fine-grained password policy)","یک ارجاع DFS (DFS referral)","یک قانون آستانه (Threshold rule) مبتنی بر معیار فضای دیسک یا شمارنده عملکرد (Performance counter)","یک فورواردر شرطی DNS (DNS conditional forwarder)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-monitor/data-collection/data-collection-rule-overview","https://learn.microsoft.com/en-us/windows-server/manage/system-insights/managing-capabilities"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Configure threshold-based alerting on free-space metrics with appropriate evaluation windows.","objectiveId":"alerts","topic":"Monitoring alerts","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-monitor/data-collection/data-collection-rule-overview","https://learn.microsoft.com/en-us/windows-server/manage/system-insights/managing-capabilities"],"keyPoints":["Alert rules evaluate a metric or counter against thresholds over a window to reduce false positives.","Local managers can raise warnings too; System Insights provides capacity forecasts with customizable thresholds.","Route alert notifications through the platform so the right team sees them."],"whyOthers":["Fine-grained password policies govern authentication strength and never alert on disk space.","DFS referrals direct clients to namespace targets and have no alerting behavior.","","Conditional forwarders route DNS queries for specific zones, unrelated to capacity thresholds."]},
{"id":"az802-q-255","domain":"Monitor and troubleshoot Windows Server environments","text":"Which Azure Monitor object defines what data an agent collects?","options":["Storage account key","Data collection rule","Availability set","Network security group"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"قوانین جمع‌آوری داده (DCRها) منابع داده، تبدیل‌ها (در صورت پشتیبانی) و مقاصد داده را مشخص می‌کنند.","en":"DCRs specify data sources, transformations where supported, and destinations.","de":"Die richtige Antwort ist „Data collection rule“; sie passt zum Bereich Monitor and troubleshoot Windows Server environments und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام شیء (Object) در Azure Monitor تعیین می‌کند که یک عامل (Agent) چه داده‌هایی را جمع‌آوری کند؟","optionsFa":["کلید حساب ذخیره‌سازی (Storage account key)","قانون جمع‌آوری داده (Data collection rule)","مجموعه در دسترس‌پذیری (Availability set)","گروه امنیت شبکه (Network security group)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-monitor/data-collection/data-collection-rule-overview","https://learn.microsoft.com/en-us/azure/azure-monitor/agents/azure-monitor-agent-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Explain that Azure Monitor data collection rules define which data sources an agent collects and where they go.","objectiveId":"azure-monitor-dcr","topic":"Azure Monitor","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-monitor/data-collection/data-collection-rule-overview","https://learn.microsoft.com/en-us/azure/azure-monitor/agents/azure-monitor-agent-overview"],"keyPoints":["A data collection rule (DCR) specifies data sources, transformations where supported, and destinations.","DCRs are associated with specific machines, enabling per-server collection choices.","The Azure Monitor Agent consumes DCR configuration locally."],"whyOthers":["Storage account keys authorize blob access and define no collection behavior.","","Availability sets spread VM instances across fault and update domains, unrelated to collection.","Network security groups filter network traffic and are unrelated to telemetry collection."]},
{"id":"az802-q-256","domain":"Monitor and troubleshoot Windows Server environments","text":"What is VM Insights primarily used for?","options":["Monitor performance and dependencies of supported Azure virtual machines","Manage AD FSMO roles","Create SMB shares","Configure DHCP failover"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"ابزار VM Insights نماهایی از عملکرد و تلمتری (داده‌های سنجش از راه دور) مرتبط با ماشین‌های مجازی Azure را ارائه می‌دهد.","en":"VM Insights provides performance views and related telemetry for Azure VMs.","de":"Die richtige Antwort ist „Monitor performance and dependencies of supported Azure virtual machines“; sie passt zum Bereich Monitor and troubleshoot Windows Server environments und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کاربرد اصلی VM Insights چیست؟","optionsFa":["نظارت بر عملکرد و وابستگی‌های ماشین‌های مجازی پشتیبانی‌شده در Azure","مدیریت نقش‌های FSMO در Active Directory","ایجاد اشتراک‌های SMB","پیکربندی قابلیت Failover برای DHCP"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-monitor/vm/vminsights-overview","https://learn.microsoft.com/en-us/azure/azure-monitor/vm/vminsights-performance"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Describe VM Insights as performance and dependency monitoring for supported Azure virtual machines.","objectiveId":"vm-insights","topic":"VM Insights","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-monitor/vm/vminsights-overview","https://learn.microsoft.com/en-us/azure/azure-monitor/vm/vminsights-performance"],"keyPoints":["VM Insights charts guest performance counters and maps process and dependency topology.","Enabling it deploys the monitoring agents and builds a workspace-backed data pipeline.","Performance views support trends over hours or days to catch slow degradation."],"whyOthers":["","FSMO role management is an AD DS activity, unrelated to guest telemetry.","SMB share configuration is a file-server function, not dependency mapping.","DHCP failover is an address-allocation resiliency feature, not a monitoring tool."]},
{"id":"az802-q-257","domain":"Monitor and troubleshoot Windows Server environments","text":"A server’s CPU is high but users report no slowdown. What is the best next step?","options":["Reboot immediately without collecting data","Delete all event logs","Disable monitoring","Identify the consuming process and correlate with workload and duration"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"یک شمارنده (Counter) به تنهایی علت مشکل را مشخص نمی‌کند؛ بلکه اطلاعات مربوط به پردازش، زمان‌بندی و زمینه (Context) برنامه نیز مورد نیاز است.","en":"A counter alone does not identify cause; process, timing, and application context are needed.","de":"Die richtige Antwort ist „Identify the consuming process and correlate with workload and duration“; sie passt zum Bereich Monitor and troubleshoot Windows Server environments und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"textFa":"میزان مصرف CPU یک سرور بالاست، اما کاربران هیچ‌گونه کندی سرعتی را گزارش نمی‌کنند. بهترین اقدام بعدی چیست؟","optionsFa":["راه‌اندازی مجدد (Reboot) فوری بدون جمع‌آوری داده","حذف تمام لاگ‌های رویداد (Event logs)","غیرفعال کردن نظارت (Monitoring)","شناسایی پردازش مصرف‌کننده منابع و تطبیق آن با بار کاری و مدت زمان اجرا"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/performance/troubleshoot-performance-problems-in-windows","https://learn.microsoft.com/en-us/troubleshoot/windows-server/performance/troubleshoot-high-cpu-usage-guidance"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Correlate CPU counters with process identity, workload context, and duration before acting.","objectiveId":"perfmon-baseline","topic":"Performance troubleshooting","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/performance/troubleshoot-performance-problems-in-windows","https://learn.microsoft.com/en-us/troubleshoot/windows-server/performance/troubleshoot-high-cpu-usage-guidance"],"keyPoints":["Identify the consuming process, then correlate with workload timing, expected peaks, and duration.","Sustained high CPU with user impact differs from a short scheduled burst.","Compare against a baseline to decide whether the value is abnormal."],"whyOthers":["Rebooting without collecting data destroys evidence and delays root-cause identification.","Deleting logs removes the records needed to confirm the cause.","Disabling monitoring hides the symptom and guarantees recurrence.",""]},
{"id":"az802-q-258","domain":"Monitor and troubleshoot Windows Server environments","text":"A user cannot reach a server by name but can reach it by IP. Which layer should be tested first?","options":["BitLocker","VM memory","Name resolution","NTFS permissions"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"برقراری موفقیت‌آمیز اتصال از طریق IP و عدم موفقیت در اتصال با نام، نشان‌دهنده مشکل در تنظیمات DNS، فایل hosts، پسوند (suffix) یا resolver است.","en":"Successful IP connectivity with name failure points toward DNS, hosts-file, suffix, or resolver configuration.","de":"Die richtige Antwort ist „Name resolution“; sie passt zum Bereich Monitor and troubleshoot Windows Server environments und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کاربری نمی‌تواند از طریق نام به سروری متصل شود، اما امکان اتصال با استفاده از آدرس IP وجود دارد. کدام لایه باید ابتدا بررسی شود؟","optionsFa":["BitLocker","حافظه ماشین مجازی (VM)","وضوح نام (Name resolution)","مجوزهای NTFS"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/dnsclient/resolve-dnsname","https://learn.microsoft.com/en-us/windows-server/networking/dns/dns-architecture"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Test name resolution first when an IP-reachable host cannot be reached by name.","objectiveId":"dns-troubleshooting","topic":"DNS troubleshooting","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/dnsclient/resolve-dnsname","https://learn.microsoft.com/en-us/windows-server/networking/dns/dns-architecture"],"keyPoints":["IP success with name failure points to resolver config, hosts entries, suffix search, or DNS records.","Resolve-DnsName reveals which server answered and what record it returned.","Confirm the client is querying the intended DNS server before changing records."],"whyOthers":["BitLocker protects volumes and has nothing to do with hostname resolution.","VM memory pressure would degrade IP communication too, not just names.","","NTFS permissions block resource access after connection, not name lookup."]},
{"id":"az802-q-259","domain":"Monitor and troubleshoot Windows Server environments","text":"Which command resolves a DNS name using PowerShell?","options":["Get-WinEvent only","Resolve-DnsName","Get-Volume","Test-ComputerSecureChannel"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"دستور Resolve-DnsName از DNS پرس‌وجو کرده و جزئیات رکورد را که برای عیب‌یابی مفید است، بازمی‌گرداند.","en":"Resolve-DnsName queries DNS and returns record details useful for troubleshooting.","de":"Die richtige Antwort ist „Resolve-DnsName“; sie passt zum Bereich Monitor and troubleshoot Windows Server environments und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام دستور در PowerShell برای تبدیل (حل) نام DNS استفاده می‌شود؟","optionsFa":["فقط Get-WinEvent","Resolve-DnsName","Get-Volume","Test-ComputerSecureChannel"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/dnsclient/resolve-dnsname","https://learn.microsoft.com/en-us/windows-server/networking/dns/zone-types"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Resolve DNS names from PowerShell with Resolve-DnsName as part of name-resolution triage.","objectiveId":"dns-troubleshooting","topic":"DNS tools","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/dnsclient/resolve-dnsname","https://learn.microsoft.com/en-us/windows-server/networking/dns/zone-types"],"keyPoints":["Resolve-DnsName queries DNS directly and shows the record type, data, and answering server.","It supports switching servers, cache views, and specific record types for focused checks.","It complements Test-NetConnection, which also reports name resolution plus TCP reachability."],"whyOthers":["Get-WinEvent reads event logs and does not resolve names.","","Get-Volume reports volume health and space, unrelated to DNS.","Test-ComputerSecureChannel validates machine-account trust, not DNS resolution."]},
{"id":"az802-q-260","domain":"Monitor and troubleshoot Windows Server environments","text":"A domain-joined server’s clock is several minutes behind. Why is this important?","options":["Kerberos authentication has a limited time-skew tolerance","NTFS permissions depend on time zones only","DHCP stops assigning addresses","VHDX files become read-only"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"اختلاف زمانی قابل‌توجه می‌تواند منجر به رد شدن تیکت‌های Kerberos شود.","en":"Significant clock skew can cause Kerberos tickets to be rejected.","de":"Die richtige Antwort ist „Kerberos authentication has a limited time-skew tolerance“; sie passt zum Bereich Monitor and troubleshoot Windows Server environments und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"textFa":"ساعت سروری که به دامین (Domain) متصل است، چند دقیقه عقب‌تر است. چرا این موضوع اهمیت دارد؟","optionsFa":["احراز هویت Kerberos تحمل محدودی برای اختلاف زمانی (time-skew) دارد","مجوزهای NTFS تنها به مناطق زمانی (time zones) وابسته‌اند","سرویس DHCP تخصیص آدرس‌ها را متوقف می‌کند","فایل‌های VHDX به حالت فقط‌خواندنی (read-only) درمی‌آیند"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/windows-time-service/how-the-windows-time-service-works","https://learn.microsoft.com/en-us/windows-server/networking/windows-time-service/windows-time-service-top"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Explain that Kerberos authentication tolerates limited clock skew, so significant time drift breaks domain logon.","objectiveId":"time-sync-kerberos","topic":"Time synchronization","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/windows-time-service/how-the-windows-time-service-works","https://learn.microsoft.com/en-us/windows-server/networking/windows-time-service/windows-time-service-top"],"keyPoints":["Kerberos tickets are stamped with time and rejected beyond the policy skew threshold (default five minutes).","Clock problems typically appear as pre-authentication failures and intermittent authentication errors.","Verify time service health before changing authentication settings."],"whyOthers":["","NTFS permissions are evaluated against security tokens, not time zones.","DHCP serving is independent of Kerberos skew tolerance.","VHDX files remain writable regardless of clock drift."]},
{"id":"az802-q-261","domain":"Monitor and troubleshoot Windows Server environments","text":"Which Windows service manages time synchronization?","options":["DFS Replication","Server","Workstation only","Windows Time (W32Time)"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"سرویس W32Time زمان سیستم را با استفاده از دامین پیکربندی‌شده یا منابع زمانی خارجی همگام‌سازی می‌کند.","en":"W32Time synchronizes system time using configured domain or external time sources.","de":"Die richtige Antwort ist „Windows Time (W32Time)“; sie passt zum Bereich Monitor and troubleshoot Windows Server environments und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام سرویس ویندوز وظیفه مدیریت همگام‌سازی زمان را بر عهده دارد؟","optionsFa":["DFS Replication","Server","Workstation (فقط ایستگاه کاری)","Windows Time (W32Time)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/windows-time-service/windows-time-service-top","https://learn.microsoft.com/en-us/windows-server/networking/windows-time-service/how-the-windows-time-service-works"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Identify W32Time as the Windows service responsible for time synchronization.","objectiveId":"time-sync-kerberos","topic":"Time synchronization","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/windows-time-service/windows-time-service-top","https://learn.microsoft.com/en-us/windows-server/networking/windows-time-service/how-the-windows-time-service-works"],"keyPoints":["W32Time synchronizes clocks from domain or manual sources using NTP.","Domain members chain from the PDC Emulator hierarchy by default.","Stopping or misconfiguring W32Time is a common cause of authentication drift."],"whyOthers":["DFS Replication synchronizes SYSVOL and replicated folders, not clocks.","The Server service hosts shares, unrelated to time.","The Workstation service handles redirector duties and does not manage time sources.",""]},
{"id":"az802-q-262","domain":"Monitor and troubleshoot Windows Server environments","text":"Which domain computer normally acts as the authoritative time source for the forest?","options":["The DHCP server","The file server with the largest disk","The forest-root PDC Emulator","Any random member server"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"نقش PDC Emulator در ریشه فارست معمولاً طوری پیکربندی می‌شود که زمان را از یک منبع خارجی قابل‌اعتماد همگام‌سازی کند و سایر اعضای دامین نیز از این سلسله‌مراتب پیروی می‌کنند.","en":"The forest-root PDC Emulator is normally configured to synchronize from a reliable external source, with domain members following the hierarchy.","de":"Die richtige Antwort ist „The forest-root PDC Emulator“; sie passt zum Bereich Monitor and troubleshoot Windows Server environments und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام کامپیوتر در دامین معمولاً به عنوان منبع زمانی معتبر (authoritative) برای کل فارست (forest) عمل می‌کند؟","optionsFa":["سرور DHCP","فایل‌سروری که بزرگترین دیسک را دارد","نقش PDC Emulator در ریشه فارست (forest-root)","هر سرور عضوی به صورت تصادفی"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/configure-authoritative-time-server","https://learn.microsoft.com/en-us/windows-server/networking/windows-time-service/how-the-windows-time-service-works"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Recognize the forest-root PDC Emulator as the authoritative time source for the domain hierarchy.","objectiveId":"time-sync-kerberos","topic":"Time synchronization","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/configure-authoritative-time-server","https://learn.microsoft.com/en-us/windows-server/networking/windows-time-service/how-the-windows-time-service-works"],"keyPoints":["The forest-root PDC Emulator is the top of the domain time hierarchy and should synchronize from reliable external NTP.","Other DCs and members derive time from the hierarchy beneath it.","Configuring authoritative time sources is a deliberate, documented step."],"whyOthers":["DHCP servers lease addresses and are not time authorities.","Disk size has no role in time hierarchy placement.","","Member servers sync from the hierarchy; promoting an arbitrary one breaks the chain."]},
{"id":"az802-q-263","domain":"Monitor and troubleshoot Windows Server environments","text":"Windows Update fails repeatedly. What should be reviewed first?","options":["VM checkpoint age only","Update error codes, Windows Update logs, service state, disk space, and connectivity","AD schema ownership only","DFS namespace targets only"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"این بررسی‌ها مشکلات مربوط به سرویس، کش (حافظه پنهان)، ظرفیت، شبکه و بسته (Package) را از یکدیگر متمایز می‌کنند.","en":"These checks distinguish service, cache, capacity, network, and package problems.","de":"Die richtige Antwort ist „Update error codes, Windows Update logs, service state, disk space, and connectivity“; sie passt zum Bereich Monitor and troubleshoot Windows Server environments und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"textFa":"عملیات Windows Update مکرراً با شکست مواجه می‌شود. ابتدا چه مواردی باید بررسی شوند؟","optionsFa":["فقط قدمت (سن) چک‌پوینت ماشین مجازی (VM)","کدهای خطای به‌روزرسانی، لاگ‌های Windows Update، وضعیت سرویس، فضای دیسک و وضعیت اتصال","فقط مالکیت طرح‌واره (Schema) سرویس AD","فقط اهداف (Targets) فضای نام DFS"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows/deployment/update/windows-update-logs","https://learn.microsoft.com/en-us/powershell/module/windowsupdate/get-windowsupdatelog"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Review update error codes, Windows Update logs, service state, disk space, and connectivity when updates fail repeatedly.","objectiveId":"windows-update-troubleshooting","topic":"Windows Update","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows/deployment/update/windows-update-logs","https://learn.microsoft.com/en-us/powershell/module/windowsupdate/get-windowsupdatelog"],"keyPoints":["Modern update logging uses ETL traces; Get-WindowsUpdateLog converts them into a readable WindowsUpdate.log.","Error codes plus service state separate service failures from payload, cache, and network causes.","Disk space and connectivity failures routinely masquerade as update errors."],"whyOthers":["Checkpoint age is a Hyper-V concern, not an update-service diagnostic.","","Schema ownership affects directory changes only, not update servicing.","Namespace targets govern referrals and do not explain update failures."]},
{"id":"az802-q-264","domain":"Monitor and troubleshoot Windows Server environments","text":"A server fails to boot after a driver update. Which recovery option is most appropriate first?","options":["Safe Mode or a suitable recovery environment to remove or roll back the driver","Delete the AD database","Change the DNS zone type","Increase the DHCP scope"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"عملیات بازیابی بوت باید تغییرات اخیر را هدف قرار دهد و در عین حال داده‌ها و پیکربندی را حفظ کند.","en":"Boot recovery should target the recent change while preserving data and configuration.","de":"Die richtige Antwort ist „Safe Mode or a suitable recovery environment to remove or roll back the driver“; sie passt zum Bereich Monitor and troubleshoot Windows Server environments und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"textFa":"سروری پس از به‌روزرسانی درایور، دیگر بوت نمی‌شود. کدام گزینه بازیابی برای شروع کار مناسب‌تر است؟","optionsFa":["استفاده از Safe Mode یا یک محیط بازیابی مناسب برای حذف یا بازگردانی (Roll back) درایور","حذف پایگاه داده AD","تغییر نوع ناحیه (Zone) در DNS","افزایش محدوده (Scope) در DHCP"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/performance/not-boot-in-normal-mode-driver-issue","https://learn.microsoft.com/en-us/troubleshoot/windows-server/performance/use-winre-to-troubleshoot-startup-issue"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Recover a failed boot after a driver change with Safe Mode or a recovery environment before destructive options.","objectiveId":"boot-recovery","topic":"Boot troubleshooting","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/performance/not-boot-in-normal-mode-driver-issue","https://learn.microsoft.com/en-us/troubleshoot/windows-server/performance/use-winre-to-troubleshoot-startup-issue"],"keyPoints":["Safe Mode and Windows RE let you remove or roll back the offending driver while preserving data.","Boot-recovery actions should target the most recent change first.","Confirm backups before aggressive recovery steps."],"whyOthers":["","Deleting the AD database is destructive and unrelated to a driver boot failure.","Zone type is a DNS design choice, irrelevant to boot configuration.","DHCP scopes govern address allocation, nothing about booting."]},
{"id":"az802-q-265","domain":"Monitor and troubleshoot Windows Server environments","text":"Which tool helps inspect boot configuration data from a recovery environment?","options":["nslookup","dfsutil","Get-DhcpServerv4Scope","BCDEdit"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"ابزار BCDEdit در صورت استفاده صحیح، امکان بررسی و تغییر داده‌های پیکربندی بوت را فراهم می‌کند.","en":"BCDEdit can inspect and modify Boot Configuration Data when used carefully.","de":"Die richtige Antwort ist „BCDEdit“; sie passt zum Bereich Monitor and troubleshoot Windows Server environments und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام ابزار به بررسی داده‌های پیکربندی بوت (Boot Configuration Data) از طریق محیط بازیابی کمک می‌کند؟","optionsFa":["nslookup","dfsutil","Get-DhcpServerv4Scope","BCDEdit"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/bcdedit","https://learn.microsoft.com/en-us/windows-server/get-started/upgrade-in-place"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Inspect and modify Boot Configuration Data with BCDEdit from recovery environments.","objectiveId":"boot-recovery","topic":"Boot troubleshooting","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/bcdedit","https://learn.microsoft.com/en-us/windows-server/get-started/upgrade-in-place"],"keyPoints":["BCDEdit views and edits boot configuration entries, including safe-mode and recovery settings.","Always export the BCD store before edits so you can restore it.","Wrong BCD edits can make a system unbootable; verify each change carefully."],"whyOthers":["nslookup resolves DNS names and never touches boot data.","dfsutil manages namespaces and roots, unrelated to boot entries.","DHCP scope cmdlets configure address pools, not boot configuration.",""]},
{"id":"az802-q-266","domain":"Monitor and troubleshoot Windows Server environments","text":"A VM responds slowly after a storage migration. What should be correlated?","options":["Password length only","AD site names only","Guest disk latency, host storage latency, queue depth, and VM storage configuration","DNS TTL only"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"بررسی و تطبیق داده‌ها به صورت سرتاسری (End-to-end)، فشار کاری ماشین مجازی مهمان را از گلوگاه‌های میزبان یا پلتفرم ذخیره‌سازی متمایز می‌کند.","en":"End-to-end correlation distinguishes guest workload pressure from host or storage-platform bottlenecks.","de":"Die richtige Antwort ist „Guest disk latency, host storage latency, queue depth, and VM storage configuration“; sie passt zum Bereich Monitor and troubleshoot Windows Server environments und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"textFa":"یک ماشین مجازی (VM) پس از انتقال فضای ذخیره‌سازی (Storage Migration)، کند عمل می‌کند. چه مواردی باید با یکدیگر سنجیده و مقایسه (Correlation) شوند؟","optionsFa":["فقط طول رمز عبور","فقط نام‌های سایت AD","تأخیر (Latency) دیسک مهمان (Guest)، تأخیر فضای ذخیره‌سازی میزبان (Host)، عمق صف (Queue Depth) و پیکربندی فضای ذخیره‌سازی ماشین مجازی","فقط مقدار TTL در DNS"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/performance/troubleshoot-performance-problems-in-windows","https://learn.microsoft.com/en-us/windows-server/storage/storage-spaces/troubleshooting-storage-spaces"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Correlate guest disk latency, host storage latency, queue depth, and VM storage configuration after a storage migration.","objectiveId":"storage-performance","topic":"Storage performance","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/performance/troubleshoot-performance-problems-in-windows","https://learn.microsoft.com/en-us/windows-server/storage/storage-spaces/troubleshooting-storage-spaces"],"keyPoints":["Combine guest-visible latency counters with host-level storage counters to locate the bottleneck.","Queue depth reflects outstanding I/O and helps separate latency pressure from workload bursts.","Review VM storage configuration (VHDX placement, cache, per-host paths) after any migration."],"whyOthers":["Password length is irrelevant to I/O performance.","AD site names describe replication topology, not storage latency.","","DNS TTL controls record caching, unrelated to VM storage."]},
{"id":"az802-q-267","domain":"Monitor and troubleshoot Windows Server environments","text":"A Windows service is stopped after reboot. Which evidence is most useful?","options":["User profile wallpaper","Service configuration, dependencies, startup type, and System event log","DNSSEC chain only","DHCP reservations only"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"این منابع مشخص می‌کنند که آیا سرویس دچار خطا شده، با تأخیر مواجه شده، فاقد وابستگی بوده یا عمداً طوری پیکربندی شده که اجرا نشود.","en":"These sources identify whether the service failed, was delayed, lacked a dependency, or was intentionally configured not to start.","de":"Die richtige Antwort ist „Service configuration, dependencies, startup type, and System event log“; sie passt zum Bereich Monitor and troubleshoot Windows Server environments und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"textFa":"یک سرویس ویندوز پس از راه‌اندازی مجدد (Reboot) متوقف می‌شود. کدام مدرک یا اطلاعات بیشترین کاربرد را دارد؟","optionsFa":["تصویر پس‌زمینه (Wallpaper) پروفایل کاربر","پیکربندی سرویس، وابستگی‌ها، نوع شروع (Startup type) و لاگ رویدادهای سیستم (System event log)","فقط زنجیره DNSSEC","فقط رزروهای DHCP"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/server-manager/view-and-configure-performance-event-and-service-data","https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.diagnostics/get-winevent"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Investigate a stopped service using service configuration, dependencies, startup type, and System event log evidence.","objectiveId":"service-troubleshooting","topic":"Service troubleshooting","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/server-manager/view-and-configure-performance-event-and-service-data","https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.diagnostics/get-winevent"],"keyPoints":["Startup type, dependencies, and logon account all determine whether a service starts.","System log events record failure, delay, and dependency reasons.","Differentiate intentional configuration, delayed start, and failure causes."],"whyOthers":["Desktop wallpaper is cosmetic and carries no diagnostics.","","DNSSEC chain health does not stop local services.","DHCP reservations never affect service startup."]},
{"id":"az802-q-268","domain":"Monitor and troubleshoot Windows Server environments","text":"Which command displays recent Windows events from PowerShell?","options":["Get-WinEvent","Get-ADReplicationSite","Get-Volume","Get-VMSwitch only"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"دستور Get-WinEvent از لاگ‌های رویداد پرس‌وجو (Query) می‌کند و از قابلیت فیلتر کردن برای بررسی‌های تکرارپذیر پشتیبانی می‌نماید.","en":"Get-WinEvent queries event logs and supports filtering for repeatable investigation.","de":"Die richtige Antwort ist „Get-WinEvent“; sie passt zum Bereich Monitor and troubleshoot Windows Server environments und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام دستور رویدادهای اخیر ویندوز را در PowerShell نمایش می‌دهد؟","optionsFa":["Get-WinEvent","Get-ADReplicationSite","Get-Volume","فقط Get-VMSwitch"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.diagnostics/get-winevent","https://learn.microsoft.com/en-us/windows-server/administration/server-manager/view-and-configure-performance-event-and-service-data"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Query recent Windows events with Get-WinEvent, including filtered queries across logs.","objectiveId":"event-logs","topic":"Event logs","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.diagnostics/get-winevent","https://learn.microsoft.com/en-us/windows-server/administration/server-manager/view-and-configure-performance-event-and-service-data"],"keyPoints":["Get-WinEvent supports log paths, provider filters, severity filters, and scripted repeat queries.","FilterHashtable queries are efficient and reproducible for investigation.","It complements Event Viewer for exploratory review of logs."],"whyOthers":["","Get-ADReplicationSite manages replication-site objects, not event logs.","Get-Volume reports storage health, not log events.","Get-VMSwitch manages Hyper-V virtual switch objects; it never reads events."]},
{"id":"az802-q-269","domain":"Monitor and troubleshoot Windows Server environments","text":"AD replication fails between two domain controllers. Which tool should be used first for detailed partner status?","options":["robocopy","diskpart","mstsc","repadmin"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"ابزار repadmin اطلاعاتی نظیر شرکای همگام‌سازی، کدهای خطا، شناسه‌های فراخوانی (invocation IDs) و زمان آخرین همگام‌سازی موفق را نمایش می‌دهد.","en":"repadmin shows replication partners, error codes, invocation IDs, and last-successful replication.","de":"Die richtige Antwort ist „repadmin“; sie passt zum Bereich Monitor and troubleshoot Windows Server environments und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"textFa":"عملیات همگام‌سازی (Replication) سرویس دایرکتوری اکتیو دایرکتوری (AD) بین دو کنترلر دامنه با شکست مواجه می‌شود. برای دریافت جزئیات وضعیت شرکای همگام‌سازی، ابتدا باید از کدام ابزار استفاده کرد؟","optionsFa":["robocopy","diskpart","mstsc","repadmin"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/troubleshoot/troubleshooting-active-directory-replication-problems","https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/diagnose-replication-failures"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Use repadmin as the first tool for detailed AD replication partner status.","objectiveId":"ad-replication-troubleshooting","topic":"AD replication","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/troubleshoot/troubleshooting-active-directory-replication-problems","https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/diagnose-replication-failures"],"keyPoints":["repadmin /replsummary and /showrepl reveal partner state, error codes, and last-success times.","Error codes and invocation IDs map to specific known remedies.","Confirm DNS and RPC connectivity before deeper replication repairs."],"whyOthers":["robocopy copies files and folders, not directory replication metadata.","diskpart manages disks and partitions, unrelated to AD replication.","mstsc starts Remote Desktop sessions, not replication diagnostics.",""]},
{"id":"az802-q-270","domain":"Monitor and troubleshoot Windows Server environments","text":"Which condition commonly causes AD replication failures?","options":["A full printer queue only","A disabled screen saver","DNS resolution, RPC/firewall, time, or topology problems","A missing desktop shortcut"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"عملکرد صحیح همگام‌سازی AD به مواردی همچون کشف (Discovery) صحیح، اتصال، احراز هویت و توپولوژی شبکه وابسته است.","en":"AD replication depends on correct discovery, connectivity, authentication, and topology.","de":"Die richtige Antwort ist „DNS resolution, RPC/firewall, time, or topology problems“; sie passt zum Bereich Monitor and troubleshoot Windows Server environments und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام عامل معمولاً باعث بروز مشکل در همگام‌سازی AD می‌شود؟","optionsFa":["فقط پر بودن صف چاپگر","غیرفعال بودن محافظ صفحه نمایش (Screen saver)","مشکلات مربوط به ترجمه نام DNS، ارتباطات RPC/فایروال، زمان (Time) یا توپولوژی شبکه","نبود میانبر (Shortcut) روی دسکتاپ"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/diagnose-replication-failures","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/dns-and-ad-ds"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Recognize DNS, RPC/firewall, time, and topology problems as common causes of AD replication failures.","objectiveId":"ad-replication-troubleshooting","topic":"AD replication","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/diagnose-replication-failures","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/dns-and-ad-ds"],"keyPoints":["DC discovery failures via DNS commonly surface as replication failures.","Blocked RPC traffic, excessive clock skew, and broken site-link design all contribute.","repadmin and Directory Service log events localize causes."],"whyOthers":["A full printer queue is a local spooler issue, unrelated to replication.","Screen savers have no network role in replication.","","Desktop shortcuts are shell items, not replication factors."]},
{"id":"az802-q-271","domain":"Monitor and troubleshoot Windows Server environments","text":"SYSVOL is not shared on a domain controller. What should be checked?","options":["The public DNS root","DFSR state, event logs, and whether initial synchronization completed","The DHCP reservation for a printer","The VM display adapter"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"در دسترس بودن SYSVOL به صحتِ مقداردهی اولیه (Initialization) و همگام‌سازی DFSR بستگی دارد.","en":"SYSVOL availability depends on healthy DFSR initialization and replication.","de":"Die richtige Antwort ist „DFSR state, event logs, and whether initial synchronization completed“; sie passt zum Bereich Monitor and troubleshoot Windows Server environments und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"textFa":"پوشه SYSVOL در یک کنترلر دامنه به اشتراک گذاشته نشده است. چه مواردی باید بررسی شوند؟","optionsFa":["ریشه (Root) عمومی DNS","وضعیت DFSR، لاگ‌های رویداد (Event logs) و اینکه آیا همگام‌سازی اولیه تکمیل شده است یا خیر","رزرو آدرس DHCP برای چاپگر","آداپتور نمایشگر ماشین مجازی (VM)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/dcdiag","https://learn.microsoft.com/en-us/windows-server/storage/dfs-replication/dfsr-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Check DFSR state, event logs, and initial synchronization when SYSVOL is not shared.","objectiveId":"dfsr-sysvol","topic":"SYSVOL replication","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/dcdiag","https://learn.microsoft.com/en-us/windows-server/storage/dfs-replication/dfsr-overview"],"keyPoints":["SYSVOL availability depends on DFSR reaching a healthy, initialized state on each DC.","DFSR events and diagnostics reveal membership, initial sync, and error states.","Do not rebuild SYSVOL without understanding member state first."],"whyOthers":["The public DNS root has no bearing on local SYSVOL shares.","","DHCP reservations for printers are unrelated to SYSVOL.","VM display adapters do not control folder sharing."]},
{"id":"az802-q-272","domain":"Monitor and troubleshoot Windows Server environments","text":"A user can log on locally but not to the domain. What should be checked first?","options":["DNS, time, secure channel, and domain-controller reachability","File deduplication only","GPU partitioning","FSRM file screens"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"این موارد برای یافتن کنترلر و اعتبارسنجی احراز هویت دامین حیاتی هستند.","en":"These dependencies are central to locating a controller and validating domain authentication.","de":"Die richtige Antwort ist „DNS, time, secure channel, and domain-controller reachability“; sie passt zum Bereich Monitor and troubleshoot Windows Server environments und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کاربر می‌تواند به‌صورت محلی (Local) وارد سیستم شود اما امکان ورود به دامین (Domain) را ندارد. ابتدا چه مواردی باید بررسی شوند؟","optionsFa":["DNS، زمان (Time)، کانال امن (Secure Channel) و قابلیت دسترسی به دامین کنترلر (Domain Controller)","فقط حذف داده‌های تکراری فایل (File Deduplication)","پارتیشن‌بندی GPU","قابلیت File Screens در FSRM"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.management/test-computersecurechannel","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/dns-and-ad-ds"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Check DNS, time, secure channel, and domain-controller reachability when local logon works but domain logon fails.","objectiveId":"secure-channel-troubleshooting","topic":"Authentication troubleshooting","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.management/test-computersecurechannel","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/dns-and-ad-ds"],"keyPoints":["Domain logon needs DC discovery (DNS), time tolerance, a valid machine-account trust, and network path.","Test-ComputerSecureChannel and nltest quickly expose trust problems.","Local logon success narrows the issue to domain dependencies, not credentials alone."],"whyOthers":["","Deduplication governs file storage, unrelated to authentication.","GPU partitioning is a virtualization feature, not a logon factor.","FSRM file screens regulate file types, not logon ability."]},
{"id":"az802-q-273","domain":"Monitor and troubleshoot Windows Server environments","text":"A user receives “access denied” to a share. What should be calculated?","options":["DNS TTL only","CPU frequency only","DHCP lease age only","Effective share and NTFS permissions for the user’s token"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"دسترسی شبکه تحت تأثیر هر دو نوع مجوز Share و NTFS قرار دارد؛ این شامل عضویت در گروه‌ها و قوانین منع دسترسی (Deny) نیز می‌شود.","en":"Network access is constrained by both share and NTFS permissions, including group membership and denies.","de":"Die richtige Antwort ist „Effective share and NTFS permissions for the user’s token“; sie passt zum Bereich Monitor and troubleshoot Windows Server environments und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کاربر هنگام دسترسی به یک پوشه اشتراکی (Share) با خطای «Access Denied» (عدم دسترسی) مواجه می‌شود. چه چیزی باید محاسبه یا بررسی شود؟","optionsFa":["فقط DNS TTL","فقط فرکانس CPU","فقط عمر اجاره (Lease Age) در DHCP","مجوزهای مؤثر (Effective Permissions) مربوط به Share و NTFS برای توکن کاربر"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/file-server/ntfs-overview","https://learn.microsoft.com/en-us/windows/win32/secauthz/access-control-lists"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Evaluate effective share and NTFS permissions against the user's security-token groups when access is denied to a share.","objectiveId":"effective-access","topic":"Permissions troubleshooting","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/file-server/ntfs-overview","https://learn.microsoft.com/en-us/windows/win32/secauthz/access-control-lists"],"keyPoints":["Access requires passing both the share layer and NTFS for the groups in the user's token, including deny entries.","Effective access tools compute the intersection instead of manual guessing.","Group membership and deny ACEs often explain surprising denials."],"whyOthers":["DNS TTL affects record lifetime only.","CPU frequency has nothing to do with file authorization.","DHCP lease age never modifies access checks.",""]},
{"id":"az802-q-274","domain":"Monitor and troubleshoot Windows Server environments","text":"A disk is offline in Disk Management after being presented to a server. What should be checked?","options":["DNS scavenging","Hyper-V Replica test mode","Disk signature or GUID conflicts, SAN policy, and whether the disk is safe to bring online","The domain password policy"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"آنلاین کردن نادرست یک دیسک تکراری یا مشترک (shared) می‌تواند منجر به خرابی داده‌ها یا ایجاد تداخل در هویت (identity conflicts) شود.","en":"Bringing a duplicate or shared disk online incorrectly can corrupt data or create identity conflicts.","de":"Die richtige Antwort ist „Disk signature or GUID conflicts, SAN policy, and whether the disk is safe to bring online“; sie passt zum Bereich Monitor and troubleshoot Windows Server environments und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"textFa":"پس از معرفی یک دیسک به سرور، وضعیت آن در بخش Disk Management به صورت آفلاین (Offline) نمایش داده می‌شود. چه مواردی باید بررسی شوند؟","optionsFa":["پاکسازی (Scavenging) رکوردهای DNS","حالت تست (Test mode) در Hyper-V Replica","تداخل در امضای دیسک (Disk signature) یا GUID، سیاست SAN و ایمن بودنِ آنلاین کردن دیسک","سیاست رمز عبور دامنه (Domain password policy)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/backup-and-storage/troubleshoot-disk-management","https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/diskpart"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Check disk signature conflicts, SAN policy, and shared-bus safety before bringing an offline disk online.","objectiveId":"disk-offline","topic":"Disk troubleshooting","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/backup-and-storage/troubleshoot-disk-management","https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/diskpart"],"keyPoints":["Presented disks can arrive offline due to signature collision, SAN policy, or read-only status.","Bringing the wrong disk online can corrupt data, especially on shared or replicated LUNs.","Confirm disk identity uniqueness before online and format decisions."],"whyOthers":["DNS scavenging cleans stale records, not offline disks.","Hyper-V Replica test mode provisions its own copies and never touches host disks.","","Password policy has no effect on disk state."]},
{"id":"az802-q-275","domain":"Monitor and troubleshoot Windows Server environments","text":"What does chkdsk primarily diagnose or repair?","options":["DHCP lease replication","File-system integrity and certain logical disk errors","DNS recursion","AD trust direction"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"ابزار chkdsk فراداده‌های (metadata) سیستم فایل را بررسی کرده و با استفاده از گزینه‌های مناسب، سکتورهای معیوب (bad sectors) را اسکن می‌کند؛ در استفاده از آن برای ولوم‌های عملیاتی (production volumes) دقت کنید.","en":"chkdsk checks file-system metadata and, with appropriate options, scans for bad sectors; use it carefully on production volumes.","de":"Die richtige Antwort ist „File-system integrity and certain logical disk errors“; sie passt zum Bereich Monitor and troubleshoot Windows Server environments und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"textFa":"ابزار chkdsk عمدتاً چه مواردی را عیب‌یابی یا تعمیر می‌کند؟","optionsFa":["تکثیر (Replication) اجاره‌نامه‌های DHCP","یکپارچگی سیستم فایل و برخی خطاهای منطقی دیسک","بازگشتی (Recursion) در DNS","جهت اعتماد (Trust direction) در Active Directory"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/chkdsk","https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/diskpart"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Use chkdsk to check file-system metadata and, with appropriate flags, scan for bad sectors.","objectiveId":"chkdsk","topic":"Disk troubleshooting","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/chkdsk","https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/diskpart"],"keyPoints":["chkdsk validates file-system metadata and can repair certain logical errors.","With /r it scans for bad sectors, which on large volumes takes significant time.","Run chkdsk deliberately on production volumes and schedule around operations."],"whyOthers":["DHCP lease replication is not a file-system concept.","","DNS recursion is a resolver behavior, not disk maintenance.","Trust direction is an AD concept, unrelated to chkdsk."]},
{"id":"az802-q-276","domain":"Monitor and troubleshoot Windows Server environments","text":"A storage pool shows a degraded virtual disk. What is the safest response?","options":["Review health and physical-disk status, replace failed media, and follow resiliency repair guidance","Delete the pool immediately","Format every disk","Disable monitoring"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"عملیات تعمیر تاب‌آوری باید داده‌ها را حفظ کرده و از فرآیند بازیابیِ پشتیبانی‌شده توسط چیدمان (layout) پیروی کند.","en":"Resiliency repairs should preserve data and follow the layout’s supported recovery process.","de":"Die richtige Antwort ist „Review health and physical-disk status, replace failed media, and follow resiliency repair guidance“; sie passt zum Bereich Monitor and troubleshoot Windows Server environments und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"textFa":"یک استخر ذخیره‌سازی (storage pool) وضعیت یک دیسک مجازی را به صورت Degraded (دارای نقص عملکرد) نشان می‌دهد. ایمن‌ترین اقدام چیست؟","optionsFa":["وضعیت سلامت و دیسک‌های فیزیکی را بررسی کنید، رسانه‌های معیوب را جایگزین نمایید و دستورالعمل‌های مربوط به تعمیر و بازیابی قابلیت تاب‌آوری (resiliency) را دنبال کنید.","بلافاصله استخر (pool) را حذف کنید.","تمام دیسک‌ها را فرمت کنید.","قابلیت پایش (monitoring) را غیرفعال کنید."],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/storage-spaces/troubleshooting-storage-spaces","https://learn.microsoft.com/en-us/powershell/module/storage/get-physicaldisk"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Follow supported resiliency repair steps (health review, disk replacement, rebuild) for degraded Storage Spaces virtual disks.","objectiveId":"storage-spaces-health","topic":"Storage Spaces","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/storage-spaces/troubleshooting-storage-spaces","https://learn.microsoft.com/en-us/powershell/module/storage/get-physicaldisk"],"keyPoints":["Get-PhysicalDisk, Get-VirtualDisk, and health status identify which physical disk degraded the space.","Replace failed media and allow resiliency to rebuild rather than deleting the pool.","Verify rebuild completion and healthy status after replacement."],"whyOthers":["","Deleting the pool destroys all virtual disks on it, a catastrophic shortcut.","Formatting every disk erases data needlessly and does not address the failure.","Disabling monitoring removes the tooling that detects degradation."]},
{"id":"az802-q-277","domain":"Monitor and troubleshoot Windows Server environments","text":"An Azure Arc extension fails on one server but succeeds elsewhere. What should be compared?","options":["User desktop themes","AD group scope only","DNS TTL only","Operating system support, agent version, permissions, connectivity, and extension logs"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"بروز خطا در یک میزبان (host) خاص، معمولاً نشان‌دهنده تفاوت در پیش‌نیازها، نسخه نرم‌افزار، هویت (identity) یا وضعیت اتصال محلی است.","en":"A host-specific failure usually indicates a prerequisite, version, identity, or local connectivity difference.","de":"Die richtige Antwort ist „Operating system support, agent version, permissions, connectivity, and extension logs“; sie passt zum Bereich Monitor and troubleshoot Windows Server environments und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"textFa":"اجرای یک افزونه (extension) مربوط به Azure Arc روی یک سرور با شکست مواجه می‌شود اما در سرورهای دیگر موفقیت‌آمیز است. چه مواردی باید مقایسه شوند؟","optionsFa":["تم‌های دسکتاپ کاربر","فقط محدوده (scope) گروه AD","فقط مقدار TTL در DNS","پشتیبانی سیستم‌عامل، نسخه عامل (agent)، مجوزها، وضعیت اتصال و لاگ‌های افزونه"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-arc/servers/troubleshoot-vm-extensions","https://learn.microsoft.com/en-us/azure/azure-arc/servers/troubleshoot-agent-onboard"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Compare OS support, agent version, permissions, connectivity, and extension logs when an Arc extension fails on one server.","objectiveId":"arc-troubleshooting","topic":"Azure Arc troubleshooting","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-arc/servers/troubleshoot-vm-extensions","https://learn.microsoft.com/en-us/azure/azure-arc/servers/troubleshoot-agent-onboard"],"keyPoints":["Host-specific failures usually mean a prerequisite, version, identity, or connectivity difference.","Extension logs and Connected Machine agent state localize extension and platform causes.","Verify endpoint and proxy connectivity for the affected server."],"whyOthers":["Desktop themes are client-shell cosmetics, unrelated to extension success.","AD group scope alone would not explain a server-local failure pattern.","DNS TTL does not change extension download or install behavior.",""]},
{"id":"az802-q-278","domain":"Monitor and troubleshoot Windows Server environments","text":"Which troubleshooting practice reduces the risk of masking the original problem?","options":["Delete logs before review","Change several unrelated settings simultaneously","Capture evidence and make one controlled change at a time","Reboot all systems repeatedly"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"ثبت شواهد و اعمال تغییرات کنترل‌شده، رابطه علت و معلولی را حفظ کرده و نتایج را قابل تکرار می‌سازند.","en":"Evidence and controlled changes preserve causality and make results reproducible.","de":"Die richtige Antwort ist „Capture evidence and make one controlled change at a time“; sie passt zum Bereich Monitor and troubleshoot Windows Server environments und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام روش عیب‌یابی، خطر پنهان ماندن (یا پوشانده شدن) مشکل اصلی را کاهش می‌دهد؟","optionsFa":["حذف لاگ‌ها (گزارش‌های رویداد) پیش از بررسی","تغییر هم‌زمان چندین تنظیمات نامرتبط","ثبت شواهد و اعمال یک تغییر کنترل‌شده در هر مرحله","راه‌اندازی مجدد (Reboot) مکرر تمام سیستم‌ها"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/networking/troubleshoot-dhcp-guidance","https://learn.microsoft.com/en-us/troubleshoot/windows-server/performance/troubleshoot-high-cpu-usage-guidance"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Capture evidence and change one variable at a time to preserve causality during troubleshooting.","objectiveId":"troubleshooting-methodology","topic":"Troubleshooting methodology","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/networking/troubleshoot-dhcp-guidance","https://learn.microsoft.com/en-us/troubleshoot/windows-server/performance/troubleshoot-high-cpu-usage-guidance"],"keyPoints":["Evidence-first workflows keep logs intact and maintain reproducibility.","One variable at a time makes cause and effect separable.","Document each change so rollback remains possible."],"whyOthers":["Deleting logs destroys the evidence trail needed for diagnosis.","Bundled changes confuse cause with effect and cannot be reproduced.","","Reboot loops waste time and can worsen the problem."]},
{"id":"az802-q-279","domain":"Monitor and troubleshoot Windows Server environments","text":"What is a useful first step when troubleshooting an intermittent issue?","options":["Rebuild the forest","Establish timestamps, affected scope, recurrence pattern, and correlated logs","Assume the newest server is at fault","Disable all security controls"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"خرابی‌های متناوب نیازمند بررسی همبستگی در طول زمان، سیستم‌ها و وابستگی‌ها هستند.","en":"Intermittent failures require correlation across time, systems, and dependencies.","de":"Die richtige Antwort ist „Establish timestamps, affected scope, recurrence pattern, and correlated logs“; sie passt zum Bereich Monitor and troubleshoot Windows Server environments und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"textFa":"اولین گام مفید هنگام عیب‌یابی یک مشکل متناوب (غیردائمی) چیست؟","optionsFa":["بازسازی فارست (Forest)","تعیین برچسب‌های زمانی، دامنه تأثیر، الگوی تکرار و لاگ‌های مرتبط","فرض بر اینکه جدیدترین سرور مقصر است","غیرفعال کردن تمام کنترل‌های امنیتی"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/networking/troubleshoot-dhcp-guidance","https://learn.microsoft.com/en-us/troubleshoot/windows-server/performance/troubleshoot-performance-problems-in-windows"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Frame intermittent failures around timestamps, affected scope, recurrence pattern, and correlated logs.","objectiveId":"troubleshooting-methodology","topic":"Troubleshooting methodology","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/networking/troubleshoot-dhcp-guidance","https://learn.microsoft.com/en-us/troubleshoot/windows-server/performance/troubleshoot-performance-problems-in-windows"],"keyPoints":["Intermittent problems need correlation across time, systems, and dependencies.","Establish affected scope and recurrence before hunting root cause.","Use event timestamps and monitoring to anchor the failure window."],"whyOthers":["Rebuilding a forest is a catastrophic last-resort recovery, not an opening move.","","Assigning blame by machine age ignores evidence and wastes effort.","Disabling security controls to simplify testing creates a second, worse problem."]},
{"id":"az802-q-280","domain":"Monitor and troubleshoot Windows Server environments","text":"A performance alert fires once for five seconds and then clears. What should determine whether to act?","options":["Threshold duration, recurrence, workload impact, and corroborating metrics","The alert name alone","The server’s computer-account password","The DNS zone serial only"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"کیفیت هشدار به زمینه (Context) بستگی دارد؛ افزایش‌های ناگهانی و کوتاه‌مدت ممکن است نیازی به مداخله نداشته باشند.","en":"Alert quality depends on context; transient spikes may not justify intervention.","de":"Die richtige Antwort ist „Threshold duration, recurrence, workload impact, and corroborating metrics“; sie passt zum Bereich Monitor and troubleshoot Windows Server environments und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"textFa":"یک هشدار عملکرد (Performance alert) به مدت پنج ثانیه فعال شده و سپس برطرف می‌شود. چه عواملی باید تصمیم‌گیری برای اقدام را تعیین کنند؟","optionsFa":["مدت زمان آستانه، تکرار، تأثیر بر بار کاری و معیارهای تأییدکننده","صرفاً نام هشدار","رمز عبور حساب کامپیوتری سرور","فقط شماره سریال ناحیه DNS"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-monitor/data-collection/data-collection-rule-overview","https://learn.microsoft.com/en-us/azure/azure-monitor/overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Judge alerts by threshold duration, recurrence, workload impact, and corroboration, not by a lone incident.","objectiveId":"alerts","topic":"Monitoring alerts","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-monitor/data-collection/data-collection-rule-overview","https://learn.microsoft.com/en-us/azure/azure-monitor/overview"],"keyPoints":["Alert quality is a design property: which threshold, over which window, with which recurrence.","Short-lived single incidents may reflect transient spikes; corroborate before acting.","Tune thresholds with operational data to balance noise and missed events."],"whyOthers":["","The alert name alone never carries enough context to decide.","Computer-account passwords are authentication state, unrelated to alert triage.","DNS zone serials track zone changes, not alert validity."]},
{"id":"az802-q-281","domain":"Backup, recovery, high availability, and migration crossover","text":"What does a recovery point objective (RPO) describe?","options":["The time required to restore service","The number of domain controllers","The size of a backup disk","The maximum acceptable amount of data loss measured in time"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"مقدار RPO معادل ۱۵ دقیقه بدین معناست که سازمان پس از وقوع یک حادثه، حداکثر حدود ۱۵ دقیقه از تغییرات ازدست‌رفته را می‌پذیرد.","en":"An RPO of 15 minutes means the organization accepts at most roughly 15 minutes of lost changes after an incident.","de":"Die richtige Antwort ist „The maximum acceptable amount of data loss measured in time“; sie passt zum Bereich Backup, recovery, high availability, and migration crossover und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"dr","reviewStatus":"technical-approved","isOriginal":true,"textFa":"«هدف نقطه بازیابی» (RPO) چه چیزی را توصیف می‌کند؟","optionsFa":["زمان مورد نیاز برای بازیابی سرویس","تعداد کنترل‌کننده‌های دامنه (Domain Controllers)","حجم دیسک پشتیبان‌گیری","حداکثر میزان قابل‌قبول از دست رفتن داده‌ها بر حسب زمان"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/site-recovery/site-recovery-overview","https://learn.microsoft.com/en-us/azure/well-architected/reliability/disaster-recovery"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Define the recovery point objective as the maximum acceptable data-loss window measured in time.","objectiveId":"recovery-objectives","topic":"Recovery objectives","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/azure/site-recovery/site-recovery-overview","https://learn.microsoft.com/en-us/azure/well-architected/reliability/disaster-recovery"],"keyPoints":["RPO bounds how much data change the business can afford to lose after an incident.","RPO is set per workload and directly shapes replication and backup frequency.","An RPO of 15 minutes means at most roughly 15 minutes of lost changes."],"whyOthers":["Restoring service within a deadline is RTO, a different objective.","Domain-controller counts have no relationship to data-loss tolerance.","Backup disk size is capacity planning, not a time-based loss bound.",""]},
{"id":"az802-q-282","domain":"Backup, recovery, high availability, and migration crossover","text":"What does a recovery time objective (RTO) describe?","options":["The password age","The DNS cache duration","The target time to restore a service after disruption","The maximum file size"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"شاخص RTO سرعت بازیابی را می‌سنجد، در حالی که RPO میزان قابل‌تحمل از دست رفتن داده‌ها را اندازه‌گیری می‌کند.","en":"RTO measures restoration speed, while RPO measures tolerable data loss.","de":"Die richtige Antwort ist „The target time to restore a service after disruption“; sie passt zum Bereich Backup, recovery, high availability, and migration crossover und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"dr","reviewStatus":"technical-approved","isOriginal":true,"textFa":"«هدف زمان بازیابی» (RTO) چه چیزی را توصیف می‌کند؟","optionsFa":["عمر رمز عبور","مدت زمان کش (حافظه پنهان) DNS","زمان هدف برای بازیابی یک سرویس پس از بروز اختلال","حداکثر اندازه فایل"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/site-recovery/site-recovery-overview","https://learn.microsoft.com/en-us/azure/well-architected/reliability/disaster-recovery"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Define the recovery time objective as the target time to restore service after disruption.","objectiveId":"recovery-objectives","topic":"Recovery objectives","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/azure/site-recovery/site-recovery-overview","https://learn.microsoft.com/en-us/azure/well-architected/reliability/disaster-recovery"],"keyPoints":["RTO bounds how quickly service must be back after an incident.","RTO drives stand-up runbooks, automation, and failover design.","RPO and RTO together define the overall continuity requirement."],"whyOthers":["Password age describes account-lifecycle policy, unrelated to service restoration.","DNS caching duration controls record refresh, not recovery timing.","","Maximum file size is a storage limit, not a recovery objective."]},
{"id":"az802-q-283","domain":"Backup, recovery, high availability, and migration crossover","text":"Which backup type normally captures changes since the last full backup?","options":["Mirror-only checkpoint","Differential","Incremental","Synthetic delete"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"پشتیبان‌گیری تفاضلی (Differential)، تغییراتِ پس از آخرین پشتیبان‌گیری کامل را جمع‌آوری و ذخیره می‌کند.","en":"A differential backup accumulates changes since the last full backup.","de":"Die richtige Antwort ist „Differential“; sie passt zum Bereich Backup, recovery, high availability, and migration crossover und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"dr","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام نوع پشتیبان‌گیری معمولاً تغییراتِ پس از آخرین پشتیبان‌گیری کامل را ثبت می‌کند؟","optionsFa":["نقطه بازرسی (Checkpoint) صرفاً آینه‌ای (Mirror-only)","تفاضلی (Differential)","افزایشی (Incremental)","حذف مصنوعی (Synthetic delete)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/wbadmin-start-backup","https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-server-backup-command-reference"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Explain that differential backups capture all changes since the last full backup.","objectiveId":"backup-types","topic":"Backup types","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/wbadmin-start-backup","https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-server-backup-command-reference"],"keyPoints":["Differential backups grow until the next full backup resets the delta base.","Restore needs the last full plus the latest differential.","Compared with incrementals, differentials trade more storage and copy time for simpler restores."],"whyOthers":["Mirror-only checkpoints are Hyper-V state capture, not a backup type.","","Incremental backups capture changes since the previous backup of any type, not since the full.","Synthetic delete is not a recognized backup taxonomy term."]},
{"id":"az802-q-284","domain":"Backup, recovery, high availability, and migration crossover","text":"Which backup type normally captures changes since the most recent backup of any type?","options":["Incremental","Differential","Full only","Replica metadata"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"ایجاد پشتیبان‌های افزایشی (Incremental) سریع‌تر است و حجم کمتری دارند، اما فرآیند بازیابی معمولاً به آخرین نسخه کامل و تک‌تک نسخه‌های افزایشیِ مورد نیاز وابسته است.","en":"Incrementals are smaller and faster to create, but a restore generally needs the last full and each required incremental.","de":"Die richtige Antwort ist „Incremental“; sie passt zum Bereich Backup, recovery, high availability, and migration crossover und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"dr","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام نوع پشتیبان‌گیری معمولاً تغییراتِ پس از جدیدترین پشتیبان‌گیری (از هر نوعی که باشد) را ثبت می‌کند؟","optionsFa":["افزایشی (Incremental)","تفاضلی (Differential)","فقط کامل (Full only)","فراداده‌های (Metadata) نسخه کپی (Replica)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/wbadmin-start-backup","https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-server-backup-command-reference"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Explain that incremental backups capture changes since the previous backup of any type.","objectiveId":"backup-types","topic":"Backup types","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/wbadmin-start-backup","https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-server-backup-command-reference"],"keyPoints":["Incrementals are the smallest and fastest daily runs but chain restore steps.","Restore requires the last full plus each needed incremental in order.","Any single damaged increment can break the whole restore chain."],"whyOthers":["","Differential backups always delta from the last full backup, not from yesterday's media.","A full-only scheme re-copies everything daily, the opposite of incremental efficiency.","Replica metadata describes replication state, not backup deltas."]},
{"id":"az802-q-285","domain":"Backup, recovery, high availability, and migration crossover","text":"Why should backups be tested with actual restore exercises?","options":["Testing makes every backup full","Testing removes the need for monitoring","Testing disables encryption","A successful backup job does not prove that data can be recovered within requirements"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"آزمایش‌های بازیابی، یکپارچگی، رویه‌ها، مجوزها، وابستگی‌ها و زمان بازیابی را تایید و ارزیابی می‌کنند.","en":"Restore tests validate integrity, procedures, permissions, dependencies, and recovery time.","de":"Die richtige Antwort ist „A successful backup job does not prove that data can be recovered within requirements“; sie passt zum Bereich Backup, recovery, high availability, and migration crossover und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"dr","reviewStatus":"technical-approved","isOriginal":true,"textFa":"چرا باید پشتیبان‌ها را با تمرین‌های واقعیِ بازیابی آزمایش کرد؟","optionsFa":["آزمایش باعث می‌شود هر نسخه پشتیبان به یک نسخه کامل (Full Backup) تبدیل شود","آزمایش نیاز به نظارت (مانیتورینگ) را از بین می‌برد","آزمایش قابلیت رمزگذاری را غیرفعال می‌کند","موفقیت‌آمیز بودن عملیات پشتیبان‌گیری، تضمین‌کننده امکان بازیابی داده‌ها در چارچوب الزامات تعیین‌شده نیست"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/wbadmin-start-recovery","https://learn.microsoft.com/en-us/azure/backup/backup-architecture"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Prove recoverability with actual restore exercises, not just successful backup jobs.","objectiveId":"restore-testing","topic":"Backup testing","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/wbadmin-start-recovery","https://learn.microsoft.com/en-us/azure/backup/backup-architecture"],"keyPoints":["A completed backup job proves capture, not that a restore meets RTO or data requirements.","Restore tests validate media integrity, procedures, permissions, and application dependencies.","Schedule drills and track their duration against RTO."],"whyOthers":["Test frequency does not change the size classification of backups.","Restore testing and monitoring answer different questions; neither replaces the other.","Encryption state is independent of whether restores are exercised.",""]},
{"id":"az802-q-286","domain":"Backup, recovery, high availability, and migration crossover","text":"Which backup design best addresses ransomware resilience?","options":["Use one shared administrator account","Disable backup alerts","Keep protected, access-controlled, tested copies including an isolated or immutable copy","Store the only backup on the production server"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"جداسازی و تغییرناپذیری (Immutability)، احتمال رمزگذاری یا حذف تمامی نسخه‌های بازیابی توسط مهاجم را کاهش می‌دهند.","en":"Separation and immutability reduce the chance that an attacker can encrypt or delete every recovery copy.","de":"Die richtige Antwort ist „Keep protected, access-controlled, tested copies including an isolated or immutable copy“; sie passt zum Bereich Backup, recovery, high availability, and migration crossover und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"dr","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام طرح پشتیبان‌گیری، بهترین راهکار برای ایجاد تاب‌آوری در برابر باج‌افزار است؟","optionsFa":["استفاده از یک حساب کاربری مدیریتی مشترک","غیرفعال کردن هشدارهای مربوط به پشتیبان‌گیری","نگهداری نسخه‌های محافظت‌شده، آزمایش‌شده و دارای کنترل دسترسی، از جمله یک نسخه ایزوله یا تغییرناپذیر (Immutable)","ذخیره تنها نسخه پشتیبان موجود بر روی سرور عملیاتی (Production Server)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/backup/backup-architecture","https://learn.microsoft.com/en-us/azure/well-architected/reliability/disaster-recovery"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Design backups with protected, access-controlled, tested copies including isolated or immutable storage.","objectiveId":"ransomware-resilience","topic":"Backup design","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/backup/backup-architecture","https://learn.microsoft.com/en-us/azure/well-architected/reliability/disaster-recovery"],"keyPoints":["Keep at least one copy an attacker cannot reach or overwrite: isolated or immutable.","Restrict access to backup administration with privileged accounts and separate credentials.","Regularly test restores so the defense is proven, not assumed."],"whyOthers":["One shared administrator account is an easy single point of compromise.","Disabling alerts hides the biggest signal that an attack is underway.","","Storing the only backup on the production server defeats the purpose entirely."]},
{"id":"az802-q-287","domain":"Backup, recovery, high availability, and migration crossover","text":"What is the purpose of a system state backup on a domain controller?","options":["Save a VM screenshot","Capture critical components such as AD DS and SYSVOL for supported recovery","Back up only user documents","Copy DHCP leases only"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"وضعیت سیستم (System State) برای سناریوهای بازیابی سرویس دایرکتوری و سیستم‌عامل مرتبط استفاده می‌شود.","en":"System state is used for directory-service and related operating-system recovery scenarios.","de":"Die richtige Antwort ist „Capture critical components such as AD DS and SYSVOL for supported recovery“; sie passt zum Bereich Backup, recovery, high availability, and migration crossover und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"dr","reviewStatus":"technical-approved","isOriginal":true,"textFa":"هدف از تهیه نسخه پشتیبان از وضعیت سیستم (System State) در یک کنترل‌کننده دامنه (Domain Controller) چیست؟","optionsFa":["ذخیره اسکرین‌شات ماشین مجازی (VM)","ثبت و ذخیره مؤلفه‌های حیاتی مانند AD DS و SYSVOL برای امکان‌پذیر ساختن بازیابی","تهیه نسخه پشتیبان تنها از اسناد کاربران","کپی کردن تنها اجاره‌نامه‌های (leases) DHCP"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/wbadmin-start-systemstatebackup","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/forest-recovery-guide/ad-forest-recovery-procedures"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Use system state backups to capture critical AD DS, registry, and boot components of a domain controller.","objectiveId":"system-state-backup","topic":"System state","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/wbadmin-start-systemstatebackup","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/forest-recovery-guide/ad-forest-recovery-procedures"],"keyPoints":["System state includes AD DS, SYSVOL, registry, boot files, COM+ class registry, and certificates.","It supports nonauthoritative restores of directory components without full-volume recovery.","wbadmin start systemstatebackup -backupTarget:... runs an ad-hoc system-state capture."],"whyOthers":["Screenshots are not a recoverable OS state.","","User folders live in volume backups, not in the state database.","DHCP lease data is its own targeted backup, not part of system state."]},
{"id":"az802-q-288","domain":"Backup, recovery, high availability, and migration crossover","text":"When is Directory Services Restore Mode (DSRM) used?","options":["To start a domain controller in a special mode for directory database recovery","To configure a DHCP scope","To join a VM to a cluster","To sign DNS records"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"حالت DSRM یک محیط بازیابی آفلاین برای عملیات پایگاه داده AD DS فراهم می‌کند.","en":"DSRM provides an offline recovery environment for AD DS database operations.","de":"Die richtige Antwort ist „To start a domain controller in a special mode for directory database recovery“; sie passt zum Bereich Backup, recovery, high availability, and migration crossover und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"dr","reviewStatus":"technical-approved","isOriginal":true,"textFa":"حالت بازیابی سرویس‌های دایرکتوری (DSRM) چه زمانی استفاده می‌شود؟","optionsFa":["برای راه‌اندازی کنترل‌کننده دامنه در حالتی خاص جهت بازیابی پایگاه داده دایرکتوری","برای پیکربندی یک محدوده (Scope) در DHCP","برای افزودن یک ماشین مجازی به کلاستر","برای امضای رکوردهای DNS"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/forest-recovery-guide/ad-forest-recovery-procedures","https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-server-2012-r2-and-2012/cc732211(v=ws.11)"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Recognize DSRM as the offline recovery environment for the AD DS database.","objectiveId":"dsrm","topic":"DSRM","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/forest-recovery-guide/ad-forest-recovery-procedures","https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-server-2012-r2-and-2012/cc732211(v=ws.11)"],"keyPoints":["DSRM boots a DC with directory services stopped so ntdsutil and restore tools can act offline.","The DSRM Administrator password is distinct from domain credentials and must be recorded securely.","Recovery mode selection happens through boot options or WBC/VM configuration."],"whyOthers":["","DHCP configuration happens online with the DHCP console or PowerShell.","Cluster joining is a generic HA action with no directory-recovery semantics.","DNSSEC signing operates on zones online, unrelated to DSRM."]},
{"id":"az802-q-289","domain":"Backup, recovery, high availability, and migration crossover","text":"What is the difference between a nonauthoritative and authoritative restore of AD DS?","options":["Nonauthoritative changes the schema; authoritative changes DNS","They are identical","Authoritative restores only a printer","Nonauthoritative receives updates from partners; authoritative marks restored data to replicate outward"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"انتخاب این گزینه به این بستگی دارد که آیا نسخه بازیابی‌شده باید به منبعی برای سایر کنترل‌کننده‌های دامنه تبدیل شود یا خیر.","en":"The choice depends on whether the restored copy should become the source for other domain controllers.","de":"Die richtige Antwort ist „Nonauthoritative receives updates from partners; authoritative marks restored data to replicate outward“; sie passt zum Bereich Backup, recovery, high availability, and migration crossover und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"dr","reviewStatus":"technical-approved","isOriginal":true,"textFa":"تفاوت بین بازیابی غیرمعتبر (Nonauthoritative) و معتبر (Authoritative) در AD DS چیست؟","optionsFa":["بازیابی غیرمعتبر طرح‌واره (Schema) را تغییر می‌دهد؛ بازیابی معتبر DNS را تغییر می‌دهد","آن‌ها یکسان هستند","بازیابی معتبر تنها یک چاپگر را بازیابی می‌کند","بازیابی غیرمعتبر به‌روزرسانی‌ها را از شرکا (partners) دریافت می‌کند؛ علامت‌گذاری به عنوان «معتبر» (Authoritative) باعث می‌شود داده‌های بازیابی‌شده به سایر کنترل‌کننده‌های دامنه تکثیر شوند."],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/forest-recovery-guide/ad-forest-recovery-procedures","https://learn.microsoft.com/en-us/troubleshoot/windows-server/group-policy/force-authoritative-non-authoritative-synchronization"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Distinguish nonauthoritative restore (receive updates from partners) from authoritative restore (replicate restored data outward).","objectiveId":"authoritative-restore","topic":"AD restore modes","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/forest-recovery-guide/ad-forest-recovery-procedures","https://learn.microsoft.com/en-us/troubleshoot/windows-server/group-policy/force-authoritative-non-authoritative-synchronization"],"keyPoints":["Nonauthoritative restore pulls newer state from replication partners; it is the default correction path.","Authoritative restore pushes selected data (for example deleted OUs) out to partners.","Choose by deciding whether the restored copy is the source of truth, not just recovery mechanics."],"whyOthers":["Schema and DNS roles are independent; the restore modes are not about them.","The two modes are operationally very different, not identical.","Printer restoration is an ordinary workload restore, not an AD concept.",""]},
{"id":"az802-q-290","domain":"Backup, recovery, high availability, and migration crossover","text":"What is the purpose of an authoritative SYSVOL restore?","options":["Convert SYSVOL to a DNS zone","Create a new forest automatically","Make the restored SYSVOL data the version replicated to other domain controllers","Delete all Group Policies"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"بازیابی معتبر SYSVOL زمانی استفاده می‌شود که نسخه بازیابی‌شده‌ی انتخاب‌شده باید داده‌ها را مجدداً در دامنه توزیع (و جایگزین داده‌های موجود) کند.","en":"Authoritative SYSVOL recovery is used when the selected restored copy must repopulate the domain.","de":"Die richtige Antwort ist „Make the restored SYSVOL data the version replicated to other domain controllers“; sie passt zum Bereich Backup, recovery, high availability, and migration crossover und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"dr","reviewStatus":"technical-approved","isOriginal":true,"textFa":"هدف از بازیابی معتبر (Authoritative) برای SYSVOL چیست؟","optionsFa":["تبدیل SYSVOL به یک ناحیه (Zone) DNS","ایجاد خودکار یک Forest جدید","تبدیل داده‌های بازیابی‌شده SYSVOL به نسخه‌ای که قرار است در سایر کنترل‌کننده‌های دامنه تکثیر شود","حذف تمام سیاست‌های گروهی (Group Policies)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/forest-recovery-guide/ad-forest-recovery-procedures","https://learn.microsoft.com/en-us/troubleshoot/windows-server/group-policy/force-authoritative-non-authoritative-synchronization"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Use authoritative SYSVOL restore when the restored copy must repopulate policy and scripts to other DCs.","objectiveId":"authoritative-restore","topic":"SYSVOL restore","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/forest-recovery-guide/ad-forest-recovery-procedures","https://learn.microsoft.com/en-us/troubleshoot/windows-server/group-policy/force-authoritative-non-authoritative-synchronization"],"keyPoints":["Authoritative SYSVOL restore marks the restored content as the domain's copy to replicate outward.","Use the msDFSR-Options attribute (or BurFlags D2) to force authoritative SYSVOL sync.","For forest recovery, perform authoritative SYSVOL on the first reinstated DC only."],"whyOthers":["SYSVOL holds policy and scripts; DNS zone data lives elsewhere.","SYSVOL restore never creates a forest automatically.","","Removing Group Policy objects is a separate administrative task, not SYSVOL restore semantics."]},
{"id":"az802-q-291","domain":"Backup, recovery, high availability, and migration crossover","text":"What is the main benefit of a failover cluster?","options":["Eliminate the need for patching","Continue a clustered workload on another node after a node or service failure","Provide public DNS recursion","Replace all backups"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"کلاسترینگ با هماهنگ‌سازی مالکیت و انتقال وظایف (failover) نقش‌های پشتیبانی‌شده، دسترس‌پذیری را بهبود می‌بخشد.","en":"Clustering improves availability by coordinating ownership and failover of supported roles.","de":"Die richtige Antwort ist „Continue a clustered workload on another node after a node or service failure“; sie passt zum Bereich Backup, recovery, high availability, and migration crossover und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"ha","reviewStatus":"technical-approved","isOriginal":true,"textFa":"مزیت اصلی کلاستر Failover (تغییر مسیر خودکار در صورت خرابی) چیست؟","optionsFa":["حذف نیاز به اعمال وصله‌های نرم‌افزاری (patching)","ادامه اجرای بار کاری (workload) کلاستر روی نودی دیگر پس از خرابی یک نود یا سرویس","فراهم کردن قابلیت بازگشتی (recursion) در DNS عمومی","جایگزینی تمام نسخه‌های پشتیبان (بک‌آپ‌ها)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/failover-clustering/failover-clustering-overview","https://learn.microsoft.com/en-us/windows-server/failover-clustering/deploy-quorum-witness"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Explain that failover clustering continues supported workloads on another node after failure.","objectiveId":"failover-clustering","topic":"Failover clustering","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/failover-clustering/failover-clustering-overview","https://learn.microsoft.com/en-us/windows-server/failover-clustering/deploy-quorum-witness"],"keyPoints":["Clustered roles fail over to surviving nodes with limited or no downtime for supported roles.","Instructions live in the cluster database and are kept consistent by quorum.","Failover clustering is distinct from replication or backup as an availability mechanism."],"whyOthers":["Clustering does not remove the need for patching; rolling upgrades coordinate but do not eliminate it.","","DNS recursion is a resolver concern with no clustering tie.","Backups remain mandatory; HA is not a substitute for restore capability."]},
{"id":"az802-q-292","domain":"Backup, recovery, high availability, and migration crossover","text":"Which quorum concept helps prevent split-brain in a failover cluster?","options":["The cluster requires sufficient votes or a quorum model to operate","Every node must run DHCP","DNS must return two IP addresses","Each VM must have a checkpoint"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"مفهوم Quorum از اجرای مستقل یک بار کاریِ کلاسترِ یکسان توسط پارتیشن‌های رقیب جلوگیری می‌کند.","en":"Quorum prevents competing partitions from independently running the same clustered workload.","de":"Die richtige Antwort ist „The cluster requires sufficient votes or a quorum model to operate“; sie passt zum Bereich Backup, recovery, high availability, and migration crossover und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"ha","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام مفهوم Quorum (حد نصاب) به جلوگیری از پدیده «مغز دوپاره» (split-brain) در کلاستر Failover کمک می‌کند؟","optionsFa":["کلاستر برای عملکرد صحیح به آرای کافی یا یک مدل Quorum نیاز دارد","هر نود باید سرویس DHCP را اجرا کند","DNS باید دو آدرس IP برگرداند","هر ماشین مجازی (VM) باید دارای یک Checkpoint باشد"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/failover-clustering/deploy-quorum-witness","https://learn.microsoft.com/en-us/windows-server/failover-clustering/what-is-quorum-witness"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Prevent split-brain by requiring sufficient quorum votes or a proper quorum model.","objectiveId":"failover-clustering","topic":"Quorum","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/failover-clustering/deploy-quorum-witness","https://learn.microsoft.com/en-us/windows-server/failover-clustering/what-is-quorum-witness"],"keyPoints":["Quorum defines how many votes are required to keep operating, preventing partitions from acting independently.","Convert a lost vote into a witness (disk, file share, or cloud) to keep quorum reachable.","A cluster without sufficient votes goes offline to protect consistency."],"whyOthers":["","Every node running DHCP is a service distribution choice, not a quorum mechanism.","Returning multiple addresses from DNS can add ambiguity, not cluster-safe decisions.","VM checkpoints are point-in-time virtualization state, not cluster voting."]},
{"id":"az802-q-293","domain":"Backup, recovery, high availability, and migration crossover","text":"What is a witness used for in a failover cluster?","options":["Store user passwords","Allocate VM memory","Encrypt SMB shares","Provide an additional vote or tie-breaking resource"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"یک Witness مبتنی بر اشتراک فایل (file-share) یا فضای ابری (cloud) می‌تواند به حفظ تصمیم‌گیری صحیح در مورد Quorum در توپولوژی‌های خاص کمک کند.","en":"A file-share or cloud witness can help maintain an appropriate quorum decision in specific topologies.","de":"Die richtige Antwort ist „Provide an additional vote or tie-breaking resource“; sie passt zum Bereich Backup, recovery, high availability, and migration crossover und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"ha","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کاربرد Witness (شاهد) در کلاستر Failover چیست؟","optionsFa":["ذخیره‌سازی رمزهای عبور کاربران","تخصیص حافظه به ماشین مجازی (VM)","رمزنگاری اشتراک‌های SMB","فراهم کردن یک رأی اضافی یا منبعی برای تعیین تکلیف در شرایط تساوی آرا"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/failover-clustering/what-is-quorum-witness","https://learn.microsoft.com/en-us/windows-server/failover-clustering/deploy-quorum-witness"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Use a witness as an additional tie-break vote in quorum decisions.","objectiveId":"failover-clustering","topic":"Quorum","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/failover-clustering/what-is-quorum-witness","https://learn.microsoft.com/en-us/windows-server/failover-clustering/deploy-quorum-witness"],"keyPoints":["Witnesses add a tie-breaking vote: file-share witness or cloud witness are common for two-node clusters.","Choose witness type based on topology; they help maintain quorum, not participate in workload.","A witness stores only minimal cluster information, never user data."],"whyOthers":["Witnesses never store passwords; storing secrets there would be unsafe.","VM memory allocation is a resource-setting concern, not a quorum artifact.","Encrypting shares is an SMB protocol-level function, not witness behavior.",""]},
{"id":"az802-q-294","domain":"Backup, recovery, high availability, and migration crossover","text":"What is the purpose of a planned maintenance failover?","options":["Restore a deleted user","Disable monitoring","Move a workload deliberately to another node before maintenance","Delete the cluster database"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"تغییر مسیر برنامه‌ریزی‌شده، اختلال را کاهش می‌دهد و به مدیران امکان می‌دهد تا گره مقصد را اعتبارسنجی کنند.","en":"Planned failover reduces disruption and allows administrators to validate the receiving node.","de":"Die richtige Antwort ist „Move a workload deliberately to another node before maintenance“; sie passt zum Bereich Backup, recovery, high availability, and migration crossover und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"ha","reviewStatus":"technical-approved","isOriginal":true,"textFa":"هدف از «تغییر مسیر (Failover) ناشی از تعمیر و نگهداری برنامه‌ریزی‌شده» چیست؟","optionsFa":["بازیابی یک کاربر حذف‌شده","غیرفعال کردن پایش (Monitoring)","انتقال عمدی یک بار کاری (Workload) به گره‌ای دیگر پیش از انجام تعمیر و نگهداری","حذف پایگاه داده کلاستر"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/failover-clustering/failover-clustering-overview","https://learn.microsoft.com/en-us/windows-server/failover-clustering/deploy-quorum-witness"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Use planned maintenance failover to move workloads deliberately to another node.","objectiveId":"failover-clustering","topic":"Planned failover","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/failover-clustering/failover-clustering-overview","https://learn.microsoft.com/en-us/windows-server/failover-clustering/deploy-quorum-witness"],"keyPoints":["Planned failovers drain roles to another node before maintenance, minimizing disruption.","Use it to validate every node's ability to host roles before unscheduled failovers.","Coordinate cluster patching through planned failover and rolling upgrades."],"whyOthers":["Deleted user objects are not recovered by cluster moves; restore them from backups or the Recycle Bin.","Disabling monitoring is unrelated and increases operational risk.","","Deleting the cluster database destroys configuration, an anti-pattern during maintenance."]},
{"id":"az802-q-295","domain":"Backup, recovery, high availability, and migration crossover","text":"What does an in-place Windows Server upgrade do?","options":["Convert an RODC to DNS","Upgrade the operating system on the existing installation while retaining supported roles and settings","Create a new forest automatically","Replace a file server with Azure Files"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"ارتقاهای درجا می‌توانند حجم کارِ مهاجرت را کاهش دهند، اما نیازمند بررسی سازگاری، تهیه نسخه پشتیبان و برنامه‌ریزی برای بازگشت به وضعیت قبل (Rollback) هستند.","en":"In-place upgrades can reduce migration effort but require compatibility checks, backups, and rollback planning.","de":"Die richtige Antwort ist „Upgrade the operating system on the existing installation while retaining supported roles and settings“; sie passt zum Bereich Backup, recovery, high availability, and migration crossover und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"ارتقای درجا (In-place upgrade) در ویندوز سرور چه کاری انجام می‌دهد؟","optionsFa":["تبدیل یک RODC به DNS","ارتقای سیستم‌عاملِ نصب‌شده‌ی فعلی با حفظ نقش‌ها و تنظیماتِ پشتیبانی‌شده","ایجاد خودکار یک Forest جدید","جایگزینی فایل‌سرور با Azure Files"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/get-started/upgrade-in-place","https://learn.microsoft.com/en-us/windows-server/get-started/install-upgrade-migrate"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Describe in-place upgrade as upgrading the existing OS installation while retaining supported roles and settings.","objectiveId":"in-place-upgrade","topic":"OS upgrade","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/get-started/upgrade-in-place","https://learn.microsoft.com/en-us/windows-server/get-started/install-upgrade-migrate"],"keyPoints":["In-place upgrade keeps hardware, roles, and settings while moving to a newer release.","Validate compatibility, confirm working backups, and plan rollback before starting.","Some roles or applications require dedicated migration steps instead of in-place upgrade."],"whyOthers":["Converting an RODC to DNS is not a real upgrade path.","","Creating a new forest automatically is not part of any upgrade operation.","Replacing a file server with Azure Files is a service migration, not an OS upgrade."]},
{"id":"az802-q-296","domain":"Backup, recovery, high availability, and migration crossover","text":"When is a side-by-side migration preferable to an in-place upgrade?","options":["When you need a rollback path, hardware refresh, or clean configuration on a new server","When no new server can be provisioned","When the application is unsupported","When backups are unavailable"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"استفاده از یک مقصد موازی (Parallel target)، امکان انجام آزمایش‌های مرحله‌بندی‌شده و انتقال کنترل‌شده (Cutover) را فراهم می‌کند.","en":"A parallel target allows staged testing and a controlled cutover.","de":"Die richtige Antwort ist „When you need a rollback path, hardware refresh, or clean configuration on a new server“; sie passt zum Bereich Backup, recovery, high availability, and migration crossover und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"چه زمانی مهاجرت به روش «Side-by-side» (موازی) بر ارتقای درجا ترجیح داده می‌شود؟","optionsFa":["زمانی که به مسیر بازگشت (Rollback)، نوسازی سخت‌افزار یا پیکربندی تمیز و جدید روی سروری تازه نیاز دارید","زمانی که امکان آماده‌سازی (Provisioning) سرور جدید وجود ندارد","زمانی که برنامه کاربردی (Application) پشتیبانی نمی‌شود","زمانی که نسخه پشتیبان در دسترس نیست"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/get-started/install-upgrade-migrate","https://learn.microsoft.com/en-us/azure/migrate/migrate-services-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Prefer side-by-side migration when you need a rollback path, hardware refresh, or a clean configuration on a new server.","objectiveId":"side-by-side-migration","topic":"Migration paths","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/get-started/install-upgrade-migrate","https://learn.microsoft.com/en-us/azure/migrate/migrate-services-overview"],"keyPoints":["A parallel target server allows staged migration, testing, and controlled cutover.","Hardware refresh and redesign usually choose this path instead of in-place upgrade.","Decommission the old server only after validation completes."],"whyOthers":["","When no new server can be provisioned, side-by-side is exactly the path that cannot run.","Unsupported applications need remediation regardless of migration approach.","Unavailable backups block every safe path rather than selecting one."]},
{"id":"az802-q-297","domain":"Backup, recovery, high availability, and migration crossover","text":"Which tool is designed to migrate AD DS objects between domains or forests?","options":["Disk Cleanup","DNS Manager only","Hyper-V Replica","Active Directory Migration Tool (ADMT)"],"correct":3,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"ابزار ADMT از مهاجرت کاربران، گروه‌ها، رایانه‌ها و سناریوهای مرتبط با ترجمه امنیتی پشتیبانی می‌کند.","en":"ADMT supports migration of users, groups, computers, and related security translation scenarios.","de":"Die richtige Antwort ist „Active Directory Migration Tool (ADMT)“; sie passt zum Bereich Backup, recovery, high availability, and migration crossover und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام ابزار برای انتقال اشیاء AD DS بین دامین‌ها یا فارست‌ها (Forests) طراحی شده است؟","optionsFa":["پاک‌سازی دیسک (Disk Cleanup)","فقط مدیریت DNS (DNS Manager)","قابلیت Hyper-V Replica","ابزار مهاجرت اکتیو دایرکتوری (ADMT)"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/support-policy-and-known-issues-for-admt","https://learn.microsoft.com/en-us/windows/win32/ad/using-dsaddsidhistory"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Use Active Directory Migration Tool (ADMT) to migrate AD DS objects between domains or forests.","objectiveId":"admt","topic":"ADMT","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/support-policy-and-known-issues-for-admt","https://learn.microsoft.com/en-us/windows/win32/ad/using-dsaddsidhistory"],"keyPoints":["ADMT migrates users, groups, and computers, supporting security translation scenarios.","Trusts between source and target domains are a prerequisite for object migration.","Plan password migration and SID history usage for phased restructuring."],"whyOthers":["Disk Cleanup removes unneeded files; it never migrates directory objects.","DNS Manager manages name records, not users, groups, or computers.","Hyper-V Replica replicates whole VMs and cannot migrate AD objects.",""]},
{"id":"az802-q-298","domain":"Backup, recovery, high availability, and migration crossover","text":"What is security translation used for during a file-server migration?","options":["Convert VHDX to VHD","Translate DHCP options","Update ACL references so migrated accounts retain access to resources","Translate DNS names into IP addresses"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"ترجمه امنیتی، شناسه‌های امنیتی (SID) قدیمی را به هویت‌های جدید در منابع منتقل‌شده نگاشت می‌کند.","en":"Security translation maps old security identifiers to new identities on migrated resources.","de":"Die richtige Antwort ist „Update ACL references so migrated accounts retain access to resources“; sie passt zum Bereich Backup, recovery, high availability, and migration crossover und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"ترجمه امنیتی در حین مهاجرت سرور فایل (File Server) چه کاربردی دارد؟","optionsFa":["تبدیل VHDX به VHD","ترجمه گزینه‌های DHCP","به‌روزرسانی ارجاعات ACL به‌طوری که حساب‌های منتقل‌شده دسترسی خود را به منابع حفظ کنند","ترجمه نام‌های DNS به آدرس‌های IP"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows/win32/ad/using-dsaddsidhistory","https://learn.microsoft.com/en-us/windows/win32/secauthz/access-control-lists"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Apply security translation during a file-server migration so migrated accounts retain access to resources.","objectiveId":"admt","topic":"ADMT","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows/win32/ad/using-dsaddsidhistory","https://learn.microsoft.com/en-us/windows/win32/secauthz/access-control-lists"],"keyPoints":["ACLs grant access through SIDs; SID history keeps original SIDs valid in the token during migration.","Security translation rewrites resource ACLs to reference the new domain's SIDs.","Run translation after confirming group memberships so no access is lost at cutover."],"whyOthers":["Converting VHDX to VHD is a disk-image conversion, unrelated to access control.","DHCP option translation adjusts network settings, not permissions.","","Resolving DNS names into IPs is name resolution, not identity migration."]},
{"id":"az802-q-299","domain":"Backup, recovery, high availability, and migration crossover","text":"What should be assessed before migrating an IIS workload to Azure?","options":["Only the DNS TTL","Dependencies, runtime compatibility, data stores, authentication, networking, and performance requirements","Only the server’s hostname","Only the number of local users"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"موفقیت در انتقال به معماری کامل برنامه بستگی دارد، نه صرفاً کپی کردن فایل‌های وب.","en":"Migration success depends on the full application architecture, not just copying the web files.","de":"Die richtige Antwort ist „Dependencies, runtime compatibility, data stores, authentication, networking, and performance requirements“; sie passt zum Bereich Backup, recovery, high availability, and migration crossover und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"پیش از انتقال یک بار کاری (workload) مبتنی بر IIS به Azure، چه مواردی باید ارزیابی شوند؟","optionsFa":["فقط مقدار TTL در DNS","وابستگی‌ها، سازگاری زمان اجرا (runtime)، مخازن داده، احراز هویت، شبکه و الزامات عملکردی","فقط نام میزبان (hostname) سرور","فقط تعداد کاربران محلی"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/migrate/migrate-services-overview","https://learn.microsoft.com/en-us/azure/migrate/concepts-assessment-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Assess dependencies, runtime compatibility, data stores, authentication, networking, and performance requirements before migrating an IIS workload to Azure.","objectiveId":"app-assessment","topic":"Workload assessment","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/migrate/migrate-services-overview","https://learn.microsoft.com/en-us/azure/migrate/concepts-assessment-overview"],"keyPoints":["Map application dependencies first; a web server is never only web files.","Confirm runtime and database compatibility along with authentication design.","Network and performance requirements drive sizing and connectivity decisions."],"whyOthers":["DNS TTL is a single record lifetime setting, not a migration assessment.","","The server hostname carries over trivially and proves nothing about readiness.","Local user counts reveal nothing about application dependencies."]},
{"id":"az802-q-300","domain":"Backup, recovery, high availability, and migration crossover","text":"What is the strongest final step after implementing a recovery or migration plan?","options":["Run a documented test, validate business functionality, monitor the result, and update the runbook","Delete the source immediately without validation","Disable alerts to avoid noise","Assume a successful copy means the service is ready"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"اعتبارسنجی عملیاتی ثابت می‌کند که وابستگی‌ها، مجوزها، عملکرد و اهداف بازیابی در عمل به درستی کار می‌کنند.","en":"Operational validation proves that dependencies, permissions, performance, and recovery objectives work in practice.","de":"Die richtige Antwort ist „Run a documented test, validate business functionality, monitor the result, and update the runbook“; sie passt zum Bereich Backup, recovery, high availability, and migration crossover und zum beschriebenen Szenario. Die technischen Details stehen in der englischen Begründung darunter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"textFa":"مؤثرترین گام نهایی پس از اجرای طرح بازیابی یا مهاجرت چیست؟","optionsFa":["انجام یک آزمون مستند، تأیید عملکرد تجاری، پایش نتایج و به‌روزرسانی دفترچه راهنمای عملیاتی (Runbook)","حذف فوری منبع (Source) بدون انجام اعتبارسنجی","غیرفعال کردن هشدارها برای جلوگیری از ایجاد نویز (هشدارهای کاذب یا غیرضروری)","فرض بر اینکه کپی‌برداری موفق به معنای آماده بودن سرویس است"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/well-architected/reliability/disaster-recovery","https://learn.microsoft.com/en-us/azure/migrate/migrate-services-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:09:01.491Z"},"objective":"Finish recovery or migration work with documented tests, business validation, monitoring, and runbook updates.","objectiveId":"runbook-validation","topic":"Operational validation","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/well-architected/reliability/disaster-recovery","https://learn.microsoft.com/en-us/azure/migrate/migrate-services-overview"],"keyPoints":["Validated behavior, not a completed copy, is what makes a service ready.","Runbooks must reflect the current tested environment so future recovery repeats success.","Monitor recovered or migrated services and close gaps found during validation."],"whyOthers":["","Deleting the source before validation creates an unrecoverable failure mode.","Disabling alerts removes the signal needed to catch post-cutover problems.","Assuming a successful copy means readiness ignores real functional proof."]},
{"id":"az802-q-301","domain":"Deploy and manage AD DS","text":"An RODC authenticates a user but refuses to cache the user's password. What controls that behaviour?","options":["The RODC's Password Replication Policy","The forest functional level","The Global Catalog read-only attribute","The DNS SRV record priority"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"An RODC caches a credential only when the account is permitted by its Password Replication Policy, which is evaluated against the Allowed and Denied RODC Password Replication Groups.","en":"An RODC caches a credential only when the account is permitted by its Password Replication Policy, which is evaluated against the Allowed and Denied RODC Password Replication Groups.","de":"An RODC caches a credential only when the account is permitted by its Password Replication Policy, which is evaluated against the Allowed and Denied RODC Password Replication Groups."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/activedirectory/add-addomaincontrollerpasswordreplicationpolicy?view=windowsserver2025-ps","https://learn.microsoft.com/en-us/powershell/module/activedirectory/get-addomaincontrollerpasswordreplicationpolicyusage?view=windowsserver2025-ps"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"AD operations: Microsoft source and technical answer review; other audit flags retained from prior review","reviewedAt":"2026-10-09T00:00:00.000Z"},"objective":"Deploy Read-Only Domain Controllers (RODCs)","objectiveId":"adds-rodc","topic":"RODC credential caching","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/activedirectory/add-addomaincontrollerpasswordreplicationpolicy?view=windowsserver2025-ps","https://learn.microsoft.com/en-us/powershell/module/activedirectory/get-addomaincontrollerpasswordreplicationpolicyusage?view=windowsserver2025-ps"],"keyPoints":["An RODC can forward uncached authentication to a reachable writable DC.","The effective per-RODC PRP decides cache eligibility through allowed/denied accounts and groups; the default Allowed RODC Password Replication Group is not the only way to allow an account.","Deny overrides allow. Actual cache contents are separate from eligibility and can be inspected with RevealedAccounts."],"whyOthers":["","The forest functional level determines which features exist across the forest and has no per-account caching decision.","A global catalog is read-only and holds no credentials, so it cannot influence what an RODC caches.","SRV record priority helps a client find a domain controller and says nothing about caching a password locally."],"requirements":"Windows Server 2025. Accounts/groups can be added directly to this RODC's allowed list. Membership in the domain-wide Allowed RODC Password Replication Group is not mandatory. Preserve denials for privileged identities and verify the effective PRP.","translations":"runtime-google"},
{"id":"az802-q-302","domain":"Deploy and manage AD DS","text":"Which ordinary AD DS operation cannot originate on a read-only domain controller?","options":["Authenticate an allowed user using an already cached credential","Answer a query from its local directory replica","Accept a client's originating directory update as a writable DC","Receive inbound directory replication from a writable DC"],"correct":2,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"en":"An RODC receives inbound replication but does not accept originating directory updates or provide ordinary outbound directory replication. Client writes require a writable DC.","fa":"RODC تکثیر ورودی را دریافت می‌کند، اما تغییر اولیهٔ Directory را نمی‌پذیرد و تکثیر خروجی معمول انجام نمی‌دهد؛ نوشتن Client به DC قابل‌نوشتن نیاز دارد.","de":"Ein RODC empfängt eingehende Replikation, nimmt aber keine ursprünglichen Verzeichnisänderungen entgegen. Client-Schreibzugriffe benötigen einen beschreibbaren DC."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/identity/replication-error-8453","https://learn.microsoft.com/en-us/openspecs/windows_protocols/ms-lsad/31ca2a31-0be4-4773-bcef-05ad6cd3ccfb"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"AD operations: Microsoft source and technical answer review; other audit flags retained from prior review","reviewedAt":"2026-10-09T00:00:00.000Z"},"objective":"Deploy Read-Only Domain Controllers (RODCs)","objectiveId":"adds-rodc","topic":"RODC capabilities","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/identity/replication-error-8453","https://learn.microsoft.com/en-us/openspecs/windows_protocols/ms-lsad/31ca2a31-0be4-4773-bcef-05ad6cd3ccfb"],"keyPoints":["Read-only prevents originating directory writes, not incoming replication updates.","An RODC receives its directory replica from writable partners.","It can answer queries and authenticate eligible cached credentials, or forward authentication when connectivity allows."],"whyOthers":["Cached authentication is a supported RODC function.","Directory queries can be answered from its read-only replica.","","Inbound replication is supported and is how the RODC receives directory changes."],"requirements":"Windows Server 2025 RODCs. Distinguish replicated incoming updates from client-originated writes; read-only is not a prohibition on replication into the RODC.","translations":"runtime-google","textFa":"کدام عملیات معمول AD DS نمی‌تواند روی Domain Controller فقط‌خواندنی ایجاد شود؟","optionsFa":["احراز هویت کاربر مجاز با اعتبارنامهٔ از قبل ذخیره‌شده","پاسخ به جست‌وجو از نسخهٔ محلی Directory","پذیرش تغییر اولیهٔ Directory از Client مانند DC قابل‌نوشتن","دریافت تکثیر ورودی Directory از DC قابل‌نوشتن"]},
{"id":"az802-q-303","domain":"Deploy and manage AD DS","text":"During a WAN outage, which configuration controls which approved branch users' passwords may be cached for local RODC authentication?","options":["The Password Replication Policy of the specific RODC","A separate forest functional level for each branch site","The number of Global Catalog servers alone","The DNS suffix alone"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"en":"PRP controls which credentials the specific RODC may cache. Offline local authentication also requires the approved credentials to have actually been cached before the outage; otherwise a reachable writable DC is needed.","fa":"PRP مشخص می‌کند همان RODC کدام اعتبارنامه‌ها را می‌تواند ذخیره کند؛ احراز هویت محلی هنگام قطع ارتباط، به ذخیرهٔ واقعی آن‌ها پیش از قطعی نیز نیاز دارد.","de":"Die PRP bestimmt, welche Kennwörter dieser RODC speichern darf. Für lokale Anmeldung während des WAN-Ausfalls müssen die erlaubten Kennwörter vorher tatsächlich gespeichert sein."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/activedirectory/add-addomaincontrollerpasswordreplicationpolicy?view=windowsserver2025-ps","https://learn.microsoft.com/en-us/powershell/module/activedirectory/get-addomaincontrollerpasswordreplicationpolicyusage?view=windowsserver2025-ps"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"AD operations: Microsoft source and technical answer review; other audit flags retained from prior review","reviewedAt":"2026-10-09T00:00:00.000Z"},"objective":"Manage account security on an RODC","objectiveId":"adds-rodc-account-security","topic":"Password Replication Policy","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/activedirectory/add-addomaincontrollerpasswordreplicationpolicy?view=windowsserver2025-ps","https://learn.microsoft.com/en-us/powershell/module/activedirectory/get-addomaincontrollerpasswordreplicationpolicyusage?view=windowsserver2025-ps"],"keyPoints":["PRP is specific to each RODC and controls cache eligibility.","Denied entries override allowed entries.","Eligibility alone does not populate the cache; inspect revealed accounts or prepopulate approved credentials before an outage. Forwarded authentication needs a reachable writable DC."],"whyOthers":["","A site does not have its own forest functional level, and functional level does not choose the permitted cache accounts.","Global Catalog placement alone does not configure Password Replication Policy.","A DNS suffix does not specify which credentials can be cached."],"requirements":"Windows Server 2025. Interpret this as credential-cache eligibility, not proof of cache contents or a general rule that every authentication through an RODC must be local.","translations":"runtime-google","textFa":"هنگام قطع WAN، کدام تنظیم تعیین می‌کند رمز عبور کدام کاربران مجاز شعبه می‌تواند برای احراز هویت محلی در RODC ذخیره شود؟","optionsFa":["Password Replication Policy همان RODC","Forest Functional Level جداگانه برای هر Site شعبه","فقط تعداد سرورهای Global Catalog","فقط DNS Suffix"]},
{"id":"az802-q-304","domain":"Deploy and manage AD DS","text":"Which tool creates a delegated task so a support team can reset passwords in one OU only?","options":["The Delegation Control Wizard in Active Directory Users and Computers","The Active Directory Module for Windows PowerShell ADMT workflow","The Directory Services Restore Mode console","The Sites and Services MMC node"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"The Delegation Control Wizard creates task-based delegation by granting a user permission to perform a fixed task on a set of objects.","en":"The Delegation Control Wizard creates task-based delegation by granting a user permission to perform a fixed task on a set of objects.","de":"The Delegation Control Wizard creates task-based delegation by granting a user permission to perform a fixed task on a set of objects."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/delegation-control-wizard"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"AD operations: Microsoft source and technical answer review; other audit flags retained from prior review","reviewedAt":"2026-10-09T00:00:00.000Z"},"objective":"Delegate administration of AD DS objects","objectiveId":"adds-delegation","topic":"Delegation","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/delegation-control-wizard"],"keyPoints":["The Delegation of Control Wizard in ADUC grants selected tasks on the chosen container's eligible objects.","A custom task can specify object types and individual permissions; object-specific delegation does not inherently grant full control.","A help-desk security group can receive password reset rights without domain-wide administration."],"whyOthers":["","Active Directory Migration Tool moves objects between domains and forests; it does not delegate tasks inside one domain.","Directory Services Restore Mode is the offline recovery environment for the directory database, not a delegation tool.","Sites and Services manages replication topology and site links, and holds no permission-delegation function."],"requirements":"Windows Server 2025. The administrator running the wizard needs permission to delegate the selected rights. Review read/list access and the delegated ACLs; delegation is not a requirement to join Domain Admins.","translations":"runtime-google"},
{"id":"az802-q-305","domain":"Deploy and manage AD DS","text":"A help-desk delegate can reset passwords in a target OU but cannot see the user objects. What is missing?","options":["Read permission on the delegated objects","The Schema Master role","Write permission on the domain root","Membership of the Domain Admins group"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Reset password permission alone is not enough: without read access the delegate cannot list or select the accounts, so the task cannot be performed on a chosen user.","en":"Reset password permission alone is not enough: without read access the delegate cannot list or select the accounts, so the task cannot be performed on a chosen user.","de":"Reset password permission alone is not enough: without read access the delegate cannot list or select the accounts, so the task cannot be performed on a chosen user."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/delegating-administration-by-using-ou-objects","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/delegation-control-wizard"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Delegate administration of AD DS objects","objectiveId":"adds-delegation","topic":"Delegation prerequisites","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/delegating-administration-by-using-ou-objects","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/delegation-control-wizard"],"keyPoints":["Reset password is a control-access right, so it must be granted together with read access on the same objects.","Granting read on the OU lets the delegate enumerate the accounts the reset task can then be applied to.","Neither a forest-wide role nor domain-wide administrative membership is needed for a scoped help-desk delegation."],"whyOthers":["","The Schema Master governs schema changes and is unrelated to delegating password resets.","Write permission on the domain root would grant far more than a help desk needs and is not required to reset a password.","Domain Admins membership is exactly the over-privilege this delegation is designed to avoid."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Least-privilege delegation should be scoped to the OU that owns the accounts, and reviewed periodically.","translations":"runtime-google"},
{"id":"az802-q-306","domain":"Deploy and manage AD DS","text":"Which value identifies a user or group uniquely across every domain in a forest and beyond?","options":["The security identifier (SID)","The sAMAccountName attribute","The display name","The primary group attribute"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"en":"Windows uses SIDs to identify security principals in authorization. Renaming preserves a SID; moving a user to another domain generates a new SID.","fa":"ویندوز برای شناسایی موجودیت‌های امنیتی در کنترل دسترسی از SID استفاده می‌کند. تغییر نام SID را حفظ می‌کند؛ انتقال کاربر به دامین دیگر SID جدیدی ایجاد می‌کند.","de":"Windows identifiziert Sicherheitsprinzipale bei der Zugriffsprüfung anhand von SIDs. Eine Umbenennung behält die SID bei; ein domänenübergreifender Benutzerumzug erzeugt eine neue SID."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-security-identifiers","https://learn.microsoft.com/en-us/windows/win32/ad/naming-properties"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"Official Microsoft technical and guide review for Windows Server 2025; prior originality, translation and distractor audit statuses retained","reviewedAt":"2026-10-09T19:11:36.000Z"},"objective":"Create and manage AD DS security principals","objectiveId":"adds-security-principals","topic":"Security identifiers","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-security-identifiers","https://learn.microsoft.com/en-us/windows/win32/ad/naming-properties"],"keyPoints":["A SID uniquely identifies a security principal for Windows authorization; resource ACLs and access tokens use SIDs.","A same-domain rename preserves the SID. A cross-domain user move creates a new objectSid; the prior SID can be retained in sIDHistory.","The same directory object's objectGUID stays stable throughout its lifetime, including rename or move. sAMAccountName is a mutable logon name unique within a domain."],"whyOthers":["","sAMAccountName is a legacy logon name unique within a domain; it is mutable and is not the SID used for authorization.","Display name is a human-readable label, not a unique Windows security-principal identifier.","The primary group attribute identifies a group relationship, not the principal's own unique SID."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Reading a SID for an account requires the ActiveDirectory PowerShell module or the dsget utility.","translations":"runtime-google"},
{"id":"az802-q-307","domain":"Deploy and manage AD DS","text":"Why must the sAMAccountName be unique within a domain?","options":["Legacy authentication and management tools resolve accounts by that name","It is written into every access token issued by the domain","It determines which domain controller holds the PDC Emulator role","It is the only attribute that can hold a group membership"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"sAMAccountName is the legacy Windows account name. Tools such as net use and older administration utilities resolve an account by that name within a domain, so it must be unique there.","en":"sAMAccountName is the legacy Windows account name. Tools such as net use and older administration utilities resolve an account by that name within a domain, so it must be unique there.","de":"sAMAccountName is the legacy Windows account name. Tools such as net use and older administration utilities resolve an account by that name within a domain, so it must be unique there."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-security-groups","https://learn.microsoft.com/en-us/training/modules/understand-active-directory-database/"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Create and manage AD DS security principals","objectiveId":"adds-security-principals","topic":"Account naming","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-security-groups","https://learn.microsoft.com/en-us/training/modules/understand-active-directory-database/"],"keyPoints":["sAMAccountName is the pre-Active Directory account name that many legacy tools still use to address an account.","Uniqueness is required per domain, not per forest, so the same name can exist in two different domains.","It is not used for access checks: those always compare the SID in the access token."],"whyOthers":["","Access tokens carry SIDs, never sAMAccountName, so renaming an account does not invalidate existing permissions.","The PDC Emulator is a single role holder per domain and is not influenced by account names.","Group membership is expressed with member DNs and group SIDs, not by sAMAccountName values."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016. Where sAMAccountName is not generated from the naming attribute, the value must still be unique and within the supported length.","translations":"runtime-google"},
{"id":"az802-q-308","domain":"Deploy and manage AD DS","text":"Which account is outside AD DS fine-grained password policy scope?","options":["A local account on a member server","A domain user in a targeted global security group","A domain user with a directly assigned PSO","A targeted domain user whose password changed recently"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"en":"FGPP applies to domain user objects and global security groups. A member server's local account is governed by local account policy, not an AD DS PSO.","fa":"FGPP به اشیای کاربر دامنه و گروه‌های امنیتی Global اعمال می‌شود؛ حساب محلی Member Server از سیاست حساب محلی پیروی می‌کند، نه PSO دامنه.","de":"FGPP gilt für Domänenbenutzer und globale Sicherheitsgruppen. Ein lokales Konto auf einem Mitgliedsserver unterliegt der lokalen Kontorichtlinie."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/get-started/adac/fine-grained-password-policies","https://learn.microsoft.com/en-us/openspecs/windows_protocols/ms-adts/ad735d45-ba6a-42fc-a41c-e91ced8e72d9"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"AD operations: Microsoft source and technical answer review; other audit flags retained from prior review","reviewedAt":"2026-10-09T00:00:00.000Z"},"objective":"Configure and manage fine-grained password policies","objectiveId":"adds-fgpp","topic":"Fine-grained password policies","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/get-started/adac/fine-grained-password-policies","https://learn.microsoft.com/en-us/openspecs/windows_protocols/ms-adts/ad735d45-ba6a-42fc-a41c-e91ced8e72d9"],"keyPoints":["PSOs apply to domain users or global security groups, not local accounts, OUs or computer objects.","Direct user assignments take priority over group-derived PSOs in resultant-PSO selection.","View resultant password settings or Get-ADUserResultantPasswordPolicy checks a domain user's effective PSO; GPO Enforced/link order is not the PSO mechanism."],"whyOthers":["","A domain user in a targeted global security group is a supported FGPP subject.","Direct PSO assignment to a domain user is supported.","Recent password change does not remove a domain user from FGPP scope."],"requirements":"Windows Server 2025. Use ADAC/ActiveDirectory tools with domain users/global security groups. Current GUI guidance assumes domain functional level Windows Server 2012 or later.","translations":"runtime-google","textFa":"کدام حساب خارج از محدودهٔ Fine-Grained Password Policy در AD DS است؟","optionsFa":["حساب محلی روی Member Server","کاربر دامنه عضو گروه امنیتی Global هدف","کاربر دامنه با PSO مستقیماً تخصیص‌یافته","کاربر دامنهٔ هدف که اخیراً رمز خود را تغییر داده است"],"commandPath":[{"label":"Read the domain user's effective PSO","command":"Get-ADUserResultantPasswordPolicy -Identity test1"}]},
{"id":"az802-q-309","domain":"Deploy and manage AD DS","text":"Two PSOs apply directly to the same domain user and have equal precedence values. Which one is selected as the resultant PSO?","options":["Neither, because equal precedence is invalid in AD DS","The PSO with the smaller objectGUID","The PSO with the larger minimum password length","The PSO with an Enforced GPO link"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"en":"The resultant-PSO algorithm sorts the applicable set by precedence and breaks ties with smaller objectGUID values. Direct user PSOs are considered before group-derived PSOs; GPO link order and Enforced do not resolve PSO ties.","fa":"الگوریتم PSO نهایی ابتدا بر اساس Precedence و در تساوی با objectGUID کوچک‌تر انتخاب می‌کند؛ PSO مستقیم کاربر بر PSO گروه اولویت دارد و Link Order یا Enforced دخیل نیست.","de":"Der Algorithmus sortiert die zutreffenden PSOs nach Precedence und löst Gleichstände mit der kleineren objectGUID. Direkte Benutzerzuweisungen werden vor Gruppenzuweisungen berücksichtigt."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/openspecs/windows_protocols/ms-adts/ad735d45-ba6a-42fc-a41c-e91ced8e72d9","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/get-started/adac/fine-grained-password-policies"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"AD operations: Microsoft source and technical answer review; other audit flags retained from prior review","reviewedAt":"2026-10-09T00:00:00.000Z"},"objective":"Configure and manage fine-grained password policies","objectiveId":"adds-fgpp","topic":"Fine-grained password policies","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/openspecs/windows_protocols/ms-adts/ad735d45-ba6a-42fc-a41c-e91ced8e72d9","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/get-started/adac/fine-grained-password-policies"],"keyPoints":["Direct user assignments form the applicable set first; only if none exist are group-derived PSOs considered.","Within that set, the smallest numeric precedence wins; equal values use the smaller objectGUID.","PSOs do not use GPO Enforced or link-order conflict rules. Prefer distinct precedence values for predictable administration."],"whyOthers":["AD's resultant-PSO algorithm explicitly handles ties; distinct values are an administrative recommendation.","","Minimum password length is a policy setting, not the tie-breaker.","GPO Enforced links do not resolve PSO assignment conflicts."],"requirements":"Windows Server 2025. This scenario compares two PSOs in the same direct-user assignment set, avoiding ambiguity about direct-user versus group priority. Read the computed resultant PSO rather than inferring it from link order.","commandPath":[{"label":"Read PSO precedence and identity","command":"Get-ADFineGrainedPasswordPolicy -Filter * | Select-Object Name,Precedence,ObjectGUID"},{"label":"Read the selected PSO for the user","command":"Get-ADUserResultantPasswordPolicy -Identity test1"}],"translations":"runtime-google","textFa":"دو PSO مستقیماً به یک کاربر دامنه اعمال شده‌اند و Precedence یکسان دارند. کدام‌یک به‌عنوان PSO نهایی انتخاب می‌شود؟","optionsFa":["هیچ‌کدام، چون Precedence یکسان در AD DS نامعتبر است","PSO با objectGUID کوچک‌تر","PSO با حداقل طول رمز بزرگ‌تر","PSO با پیوند GPO از نوع Enforced"]},
{"id":"az802-q-310","domain":"Deploy and manage AD DS","text":"Why is forest-wide universal group information in a global catalog useful during logon?","options":["The authenticating domain controller can obtain universal group memberships that span the forest","Universal groups replicate only to global catalogs and never to their own domain controllers","The Infrastructure Master exclusively stores universal group memberships","A normal domain controller cannot read universal groups in its own domain"],"correct":0,"source":"https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/planning-global-catalog-server-placement","rationale":{"en":"A GC lets the authenticating DC obtain universal group membership spanning the forest. The GC includes partial replicas of other domains; owning-domain DCs still hold their own universal group objects and memberships.","fa":"GC به کنترل‌کنندهٔ احراز هویت امکان دریافت عضویت گروه‌های Universal در سراسر جنگل را می‌دهد. GC نسخهٔ جزئی دامنه‌های دیگر را دارد؛ کنترل‌کننده‌های دامنهٔ مالک نیز اشیا و عضویت گروه‌های خود را نگه می‌دارند.","de":"Ein GC liefert dem authentifizierenden DC universelle Gruppenmitgliedschaften aus dem Forest. Andere Domänen liegen dort als Teilreplikate vor; die DCs der besitzenden Domäne halten ihre eigenen Gruppen und Mitgliedschaften weiterhin."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/planning-global-catalog-server-placement","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/get-started/replication/active-directory-replication-concepts"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"Microsoft source and answer verification; original originality, translation and distractor audit flags preserved","reviewedAt":"2026-10-09T19:09:53Z"},"objective":"Manage the Active Directory global catalog","objectiveId":"adds-global-catalog","topic":"Global catalog contents","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/planning-global-catalog-server-placement","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/get-started/replication/active-directory-replication-concepts"],"keyPoints":["Universal group membership can span domains in a forest.","The authenticating DC uses GC information or an available UGMC cache.","GCs do not automatically hold all application-directory partitions."],"whyOthers":["","Universal group objects also replicate to DCs in the group's own domain.","The Infrastructure Master is not the forest-wide membership lookup service.","A normal DC can read groups and membership in its own domain."],"requirements":"Windows Server 2025 AD DS. The DC, rather than the signing-in client, performs the group lookup needed for token construction. UGMC can reduce repeated remote GC access.","translations":"runtime-google","textFa":"چرا اطلاعات عضویت گروه‌های Universal سراسر جنگل در GC هنگام ورود مفید است؟","optionsFa":["کنترل‌کنندهٔ احراز هویت می‌تواند عضویت گروه‌های Universal سراسر جنگل را دریافت کند","گروه‌های Universal فقط به GC و هرگز به کنترل‌کننده‌های دامنهٔ خود تکثیر نمی‌شوند","فقط Infrastructure Master عضویت گروه‌های Universal را نگه می‌دارد","کنترل‌کنندهٔ عادی نمی‌تواند گروه‌های Universal دامنهٔ خودش را بخواند"]},
{"id":"az802-q-311","domain":"Deploy and manage AD DS","text":"Why might an administrator place a global catalog in a remote site in a multidomain forest?","options":["A global catalog is read-only, so it can only serve clients in its own site","To reduce WAN dependence for GC-dependent searches and multidomain logons","A domain can hold only one global catalog across the whole forest","Global catalog placement is decided by the Forest Functional Level"],"correct":1,"source":"https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/planning-global-catalog-server-placement","rationale":{"en":"A local GC improves forest-wide search and multidomain logon performance when WAN access is slow or unreliable. UGMC can be an alternative for membership lookups, so a GC is not mandatory in every site.","fa":"GC محلی در شرایط WAN کند یا نامطمئن، جست‌وجوی جنگل و ورود چنددامنه‌ای را بهبود می‌دهد. UGMC می‌تواند جایگزینی برای جست‌وجوی عضویت باشد؛ پس وجود GC در هر سایت الزامی نیست.","de":"Ein lokaler GC verbessert forestweite Suchen und multidomänige Anmeldungen bei langsamen oder unzuverlässigen WAN-Verbindungen. UGMC kann Mitgliedschaftsabfragen abdecken; deshalb ist ein GC nicht in jedem Site zwingend erforderlich."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/planning-global-catalog-server-placement","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/get-started/replication/active-directory-replication-concepts","https://learn.microsoft.com/en-us/powershell/module/activedirectory/get-adforest?view=windowsserver2025-ps"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"Microsoft source and answer verification; original originality, translation and distractor audit flags preserved","reviewedAt":"2026-10-09T19:09:53Z"},"objective":"Manage the Active Directory global catalog","objectiveId":"adds-global-catalog","topic":"Global catalog placement","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/planning-global-catalog-server-placement","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/get-started/replication/active-directory-replication-concepts","https://learn.microsoft.com/en-us/powershell/module/activedirectory/get-adforest?view=windowsserver2025-ps"],"keyPoints":["Only designated GC servers provide GC query service.","A local GC reduces dependence on the WAN for GC-dependent operations.","UGMC caches membership information but does not serve GC searches."],"whyOthers":["A GC can answer queries from other sites when reachable.","","A forest can contain many GC servers.","Functional level does not automatically place GCs in sites."],"requirements":"Windows Server 2025 AD DS. Choose placement based on application needs, users, bandwidth and resilience. UGMC needs initial lookup and cache refresh from a reachable GC.","commandPath":[{"label":"List designated GC servers","command":"Get-ADForest | Select-Object -ExpandProperty GlobalCatalogs"},{"label":"Inspect a known DC","command":"Get-ADDomainController -Identity DC01 | Select-Object HostName,Site,IsGlobalCatalog"}],"translations":"runtime-google","textFa":"چرا مدیر ممکن است در یک سایت دورافتادهٔ جنگل چنددامنه‌ای GC قرار دهد؟","optionsFa":["چون GC فقط‌خواندنی است، فقط به کلاینت‌های سایت خودش خدمت می‌دهد","برای کاهش وابستگی به WAN در جست‌وجوهای وابسته به GC و ورود چنددامنه‌ای","یک دامنه در کل جنگل فقط می‌تواند یک GC داشته باشد","محل GC توسط Forest Functional Level تعیین می‌شود"]},
{"id":"az802-q-312","domain":"Deploy and manage AD DS","text":"An administrator plans to enable AD Recycle Bin. Which functional-level setting supplies its forest-wide prerequisite?","options":["Only the domain functional level of the root domain","The operating system version of domain-joined workstations","The forest functional level","The site-link replication schedule"],"correct":2,"source":"https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/get-started/adac/advanced-ad-ds-management-using-active-directory-administrative-center--level-200-","rationale":{"en":"AD Recycle Bin is a forest-wide optional feature whose minimum forest functional level is Windows Server 2008 R2. Meeting the level does not enable it automatically, and enabling it is irreversible.","fa":"سطل بازیافت AD قابلیتی اختیاری در سطح جنگل است که حداقل سطح عملکردی Windows Server 2008 R2 را نیاز دارد. رسیدن به این سطح آن را خودکار فعال نمی‌کند و فعال‌سازی برگشت‌ناپذیر است.","de":"Der AD-Papierkorb ist ein optionales forestweites Feature mit mindestens Windows-Server-2008-R2-Forest-Ebene. Die Ebene aktiviert es nicht automatisch; das Einschalten ist irreversibel."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/get-started/adac/advanced-ad-ds-management-using-active-directory-administrative-center--level-200-","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/active-directory-functional-levels","https://learn.microsoft.com/en-us/powershell/module/activedirectory/get-adoptionalfeature?view=windowsserver2025-ps"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"Microsoft source and answer verification; original originality, translation and distractor audit flags preserved","reviewedAt":"2026-10-09T19:09:53Z"},"objective":"Manage AD DS functional levels","objectiveId":"adds-functional-levels","topic":"Forest functional level","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/get-started/adac/advanced-ad-ds-management-using-active-directory-administrative-center--level-200-","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/active-directory-functional-levels","https://learn.microsoft.com/en-us/powershell/module/activedirectory/get-adoptionalfeature?view=windowsserver2025-ps"],"keyPoints":["AD Recycle Bin is controlled at forest scope.","The minimum feature requirement is the Windows Server 2008 R2 forest functional level.","A level change and enabling the optional feature are separate actions."],"whyOthers":["Domain level alone is not the feature's forest-wide prerequisite.","Client OS version is not the feature scope.","","A site-link schedule controls replication timing, not Recycle Bin eligibility."],"requirements":"Windows Server 2025 AD DS. Existing 2025 DCs require at least the 2016 functional level, which exceeds this feature's historical minimum. Enabling AD Recycle Bin requires Enterprise Admin permissions and cannot be undone.","commandPath":[{"label":"Inspect feature state without enabling it","command":"Get-ADOptionalFeature -Filter 'Name -eq \"Recycle Bin Feature\"' | Select-Object Name,RequiredForestMode,EnabledScopes"},{"label":"Read current forest mode","command":"Get-ADForest | Select-Object Name,ForestMode"}],"translations":"runtime-google","textFa":"مدیر قصد دارد سطل بازیافت AD را فعال کند. کدام تنظیم سطح عملکردی پیش‌نیاز آن را در کل جنگل تعیین می‌کند؟","optionsFa":["فقط سطح عملکردی دامنهٔ ریشه","نسخهٔ سیستم‌عامل ایستگاه‌های کاری عضو دامنه","سطح عملکردی جنگل","زمان‌بندی تکثیر پیوند سایت"]},
{"id":"az802-q-313","domain":"Deploy and manage AD DS","text":"A domain feature is unavailable and its documentation says it requires a minimum domain functional level. What does the functional level represent?","options":["It determines which domain capabilities are available and which Windows Server versions may run on the domain controllers","It decides which Windows Server versions may run on workstations and member servers","It selects the domain controller that holds the PDC Emulator role","It controls which applications can connect to the domain"],"correct":0,"source":"https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/active-directory-functional-levels","rationale":{"en":"Functional level determines AD DS capabilities and DC operating-system compatibility. It does not choose the PDC role holder or restrict workstation operating systems. Supported lowering is conditional on enabled features and version compatibility.","fa":"سطح عملکردی قابلیت‌های AD DS و سازگاری سیستم‌عامل کنترل‌کننده‌ها را تعیین می‌کند؛ دارندهٔ PDC یا سیستم‌عامل کلاینت‌ها را انتخاب نمی‌کند. پایین‌آوردن سطح به سازگاری نسخه و ویژگی‌های فعال وابسته است.","de":"Die Funktionsebene bestimmt AD-DS-Fähigkeiten und die Betriebssystemkompatibilität der DCs. Sie wählt weder den PDC-Inhaber noch Client-Betriebssysteme aus. Ein Absenken unterliegt Funktions- und Versionsbedingungen."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/active-directory-functional-levels","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/raise-domain-forest-functional-levels","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/lower-domain-forest-functional-levels"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"Microsoft source and answer verification; original originality, translation and distractor audit flags preserved","reviewedAt":"2026-10-09T19:09:53Z"},"objective":"Manage AD DS functional levels","objectiveId":"adds-functional-levels","topic":"Domain functional level","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/active-directory-functional-levels","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/raise-domain-forest-functional-levels","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/lower-domain-forest-functional-levels"],"keyPoints":["A minimum level in feature documentation identifies required AD DS capabilities.","The level constrains supported DC versions, not workstation or member-server versions.","Use Set-ADDomainMode for a domain-level change; supported rollback is conditional."],"whyOthers":["","Workstation and member-server OS compatibility is not determined by this level.","The PDC role holder is selected independently through FSMO role management.","The level is not a general application connection allowlist."],"requirements":"Windows Server 2025 DCs require at least the 2016 functional level. Documented lowering requires supported target levels, no incompatible enabled features and a target domain mode not below the forest mode.","commandPath":[{"label":"Read domain mode","command":"Get-ADDomain | Select-Object Name,DomainMode"},{"label":"Example authorized lab level change","command":"Set-ADDomainMode -Identity corp.contoso.com -DomainMode Windows2016Domain"}],"translations":"runtime-google"},
{"id":"az802-q-314","domain":"Deploy and manage AD DS","text":"Which backup captures the AD DS database and other system-state components needed for supported domain-controller directory recovery?","options":["A system state backup","A file share backup of a documents folder","A Storage Spaces pool image","A Storage Replica primary-only snapshot"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"en":"A system-state backup includes AD DS and other critical system-state components. It supports directory recovery in a supported restore plan; it is not by itself a bare-metal backup for rebuilding a lost operating system or replacing failed disks.","fa":"پشتیبان System State شامل AD DS و اجزای مهم وضعیت سیستم است؛ برای بازیابی Directory در برنامهٔ پشتیبانی‌شده کاربرد دارد، اما به‌تنهایی پشتیبان Bare-Metal برای بازسازی سیستم‌عامل یا دیسک ازدست‌رفته نیست.","de":"Eine System-State-Sicherung enthält AD DS und weitere kritische Systemkomponenten. Sie ersetzt keine Bare-Metal-Sicherung für den Wiederaufbau eines verlorenen Betriebssystems."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/forest-recovery-guide/ad-forest-recovery-backing-up-system-state","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/forest-recovery-guide/ad-forest-recovery-perform-initial-recovery"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"AD operations: Microsoft source and technical answer review; other audit flags retained from prior review","reviewedAt":"2026-10-09T00:00:00.000Z"},"objective":"Manage AD DS backup, restore, and recovery","objectiveId":"adds-recovery","topic":"Directory backups","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/forest-recovery-guide/ad-forest-recovery-backing-up-system-state","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/forest-recovery-guide/ad-forest-recovery-perform-initial-recovery"],"keyPoints":["System state includes AD DS, SYSVOL, registry and other role-dependent system components.","A documents-folder backup does not capture the required AD DS system state.","For lost operating-system/disk recovery, plan an appropriate full-server/bare-metal recovery as well; test the supported restore path."],"whyOthers":["","A documents folder backup contains user files only and no directory state at all.","A Storage Spaces image protects the underlying storage pool, not the directory database that lives on it.","A Storage Replica snapshot protects replicated volumes and says nothing about restoring a domain controller's identity state."],"requirements":"Windows Server 2025. Secure backups separately from the controller and test recovery. Do not assume a system-state-only backup supports restoring to a newly reinstalled or different server installation. Use a supported same-server/full-server recovery plan and DSRM credentials.","commandPath":[{"label":"LAB BACKUP WRITE: use a dedicated, verified backup volume","command":"wbadmin start systemstatebackup -backupTarget:F:\\"},{"label":"Read available backup versions","command":"wbadmin get versions"}],"translations":"runtime-google","textFa":"کدام پشتیبان، پایگاه دادهٔ AD DS و سایر اجزای System State موردنیاز برای بازیابی پشتیبانی‌شدهٔ Directory روی Domain Controller را ذخیره می‌کند؟","optionsFa":["پشتیبان System State","پشتیبان اشتراک فایل از پوشهٔ اسناد","تصویر یک Pool در Storage Spaces","Snapshot فقط از سمت Primary در Storage Replica"]},
{"id":"az802-q-315","domain":"Deploy and manage AD DS","text":"Viewed from the resource forest, which one-way trust permits users in the account forest to authenticate to its resources?","options":["Selective authentication without a trust","Transitivity without a direction","An outgoing trust from the resource forest to the account forest","A firewall rule without a trust"],"correct":2,"source":"https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/netdom-trust","rationale":{"en":"Viewed from the resource forest, an outgoing trust means it trusts identities from the account forest. The account forest sees the same relationship as incoming. Authentication follows toward resources, with authorization checked separately.","fa":"از دید جنگل منابع، اعتماد خروجی یعنی هویت‌های جنگل حساب‌ها مورد اعتمادند. جنگل حساب‌ها همین رابطه را ورودی می‌بیند. احراز هویت به‌سوی منابع انجام می‌شود و مجوز دسترسی جداگانه بررسی می‌شود.","de":"Aus Sicht des Ressourcen-Forests vertraut ein ausgehender Trust den Identitäten des Konten-Forests. Dort erscheint dieselbe Beziehung als eingehend. Die Ressourcenberechtigung wird separat geprüft."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/netdom-trust","https://learn.microsoft.com/en-us/powershell/module/activedirectory/get-adtrust?view=windowsserver2025-ps"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"Microsoft source and answer verification; original originality, translation and distractor audit flags preserved","reviewedAt":"2026-10-09T19:09:53Z"},"objective":"Create and manage Active Directory trusts","objectiveId":"adds-trusts","topic":"Forest trusts","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/netdom-trust","https://learn.microsoft.com/en-us/powershell/module/activedirectory/get-adtrust?view=windowsserver2025-ps"],"keyPoints":["Trust direction is relative to the side from which it is viewed.","The resource forest is trusting; the account forest is trusted.","Selective authentication and resource ACLs control additional access conditions; they do not reverse the direction."],"whyOthers":["Selective authentication adds target approval; it does not specify trust direction.","Transitivity specifies scope, not the required one-way direction.","","A firewall does not determine the trust's authentication direction."],"requirements":"Windows Server 2025 AD DS. Record Source and Target when interpreting Direction. Selective authentication must also approve target computers when enabled.","commandPath":[{"label":"Read trust direction from the current domain","command":"Get-ADTrust -Filter * | Select-Object Source,Target,Direction,ForestTransitive,SelectiveAuthentication"}],"translations":"runtime-google","textFa":"از دید جنگل منابع، کدام اعتماد یک‌طرفه به کاربران جنگل حساب‌ها اجازه می‌دهد برای منابع آن احراز هویت شوند؟","optionsFa":["احراز هویت انتخابی بدون اعتماد","انتقال‌پذیری بدون جهت","اعتماد خروجی از جنگل منابع به جنگل حساب‌ها","قانون فایروال بدون اعتماد"]},
{"id":"az802-q-316","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"A web application keeps its database on-premises while its front end moves to Azure. What makes this arrangement hybrid rather than a cloud-only design?","options":["On-premises and cloud services are designed and operated as one environment","All servers are moved into the cloud before workloads are managed","The cloud is used only as an off-site backup target for on-premises servers","Hybrid means every workload runs on virtual machines only"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"The application deliberately spans both locations, so the two sides are operated as one environment and the traffic between them has to be designed, secured, and monitored.","en":"The application deliberately spans both locations, so the two sides are operated as one environment and the traffic between them has to be designed, secured, and monitored.","de":"The application deliberately spans both locations, so the two sides are operated as one environment and the traffic between them has to be designed, secured, and monitored."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-arc/servers/overview","https://learn.microsoft.com/en-us/windows-server/manage/windows-admin-center/understand/what-is"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Manage hybrid workloads and connectivity","objectiveId":"hybrid-workloads","topic":"Hybrid definition","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-arc/servers/overview","https://learn.microsoft.com/en-us/windows-server/manage/windows-admin-center/understand/what-is"],"keyPoints":["A split design is hybrid because parts of the application remain on-premises while other parts run in Azure.","The connection between the database and the front end becomes part of the application path, so latency, name resolution, and authentication have to be planned for it.","Identity and management must be unified across the two sides, which is why Azure Arc and Entra-based authentication appear in hybrid designs."],"whyOthers":["","A cloud-only design would have no component still running on-premises, so the split placement is what makes this hybrid.","Using the cloud only as a backup target is a narrow protection arrangement and does not describe an application whose two halves are both serving traffic.","Running every workload on virtual machines describes virtualisation, which says nothing about whether the workload runs on-premises or in the cloud."],"requirements":"Applies to Windows Server 2025, 2022, 2019, and 2016 and the Azure services used alongside them. A supported hybrid design needs licensing, identity, and connectivity to be validated before it is relied on.","translations":"runtime-google"},
{"id":"az802-q-317","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"An RDS deployment is reachable directly from the internet. Which control reduces that exposure?","options":["Publish the farm through RD Gateway and restrict which sources may connect","Assign each user a local administrator account on the session hosts","Increase the Remote Desktop session timeout","Disable Network Level Authentication on the host"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"RD Gateway is the supported way to publish Remote Desktop Services to clients that are not on the internal network, and it can restrict which sources may connect.","en":"RD Gateway is the supported way to publish Remote Desktop Services to clients that are not on the internal network, and it can restrict which sources may connect.","de":"RD Gateway is the supported way to publish Remote Desktop Services to clients that are not on the internal network, and it can restrict which sources may connect."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/remote/remote-desktop-services/remote-desktop-gateway-role","https://learn.microsoft.com/en-us/windows-server/remote/remote-desktop-services/rds-roles"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Manage remote access with SSH and Remote Desktop Services","objectiveId":"hybrid-remote-access","topic":"Secure remote access","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/remote/remote-desktop-services/remote-desktop-gateway-role","https://learn.microsoft.com/en-us/windows-server/remote/remote-desktop-services/rds-roles"],"keyPoints":["RD Gateway sits between external clients and the session hosts, so the hosts do not need direct internet exposure.","RD Gateway can be configured to permit only named source addresses or the domain, which narrows who may attempt a connection.","Strong authentication on the gateway protects the published resource; the session hosts themselves stay on the internal network."],"whyOthers":["","Giving every user local administrator rights increases the impact of any compromise rather than reducing exposure.","A longer session timeout is a convenience setting and has no effect on network reachability.","Disabling Network Level Authentication weakens the authentication requirement instead of restricting reachability."],"requirements":"Applies to Remote Desktop Services on Windows Server 2016 and later. The gateway needs a public address, a certificate trusted by clients, and firewall rules limited to the published ports.","commandPath":[{"label":"Inspect the configured RD Gateway roles and listeners","command":"Get-RDGatewayServer -ConnectionURL https://gw.contoso.com | Format-List *"}],"translations":"runtime-google"},
{"id":"az802-q-318","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"Which Azure service gives browser-based RDP to virtual machines without a public IP address on each VM?","options":["Azure Bastion","Azure Load Balancer","Azure Firewall","Azure Virtual Network Gateway"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Azure Bastion provides RDP and SSH through the Azure portal over the Azure network, so the target VM needs no public IP address or exposed RDP port.","en":"Azure Bastion provides RDP and SSH through the Azure portal over the Azure network, so the target VM needs no public IP address or exposed RDP port.","de":"Azure Bastion provides RDP and SSH through the Azure portal over the Azure network, so the target VM needs no public IP address or exposed RDP port."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/bastion/bastion-overview","https://learn.microsoft.com/en-us/azure/bastion/bastion-connect-vm-rdp-windows"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Manage remote access with SSH and Remote Desktop Services","objectiveId":"hybrid-remote-access","topic":"Browser-based connectivity","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/bastion/bastion-overview","https://learn.microsoft.com/en-us/azure/bastion/bastion-connect-vm-rdp-windows"],"keyPoints":["Azure Bastion provisions a managed host that brokers RDP and SSH sessions into the virtual network.","The target VM keeps no public IP and no open RDP port, which removes that Internet-facing attack surface.","Because access arrives over the Azure fabric, the design avoids inbound port exposure on the machine itself."],"whyOthers":["","A load balancer distributes traffic across instances but still requires the target to be reachable, so it does not remove RDP exposure.","Azure Firewall filters traffic between networks and does not broker interactive sessions to a VM.","A virtual network gateway connects networks, typically for site-to-site or point-to-site VPN, and does not provide an RDP session broker."],"requirements":"Available for virtual networks in supported regions. The subnet hosting the Bastion host must be dedicated, and the target VM must be addressable inside that network.","commandPath":[{"label":"List the Bastion hosts in the subscription","command":"az network bastion list --output table"}],"translations":"runtime-google"},
{"id":"az802-q-319","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"Which Azure Policy object groups related policy definitions so they can be assigned together?","options":["An initiative","A diagnostic setting","A resource group deployment","A management group subscription registration"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"An initiative is a collection of related policy definitions that are assigned as one unit, which is how a standard such as a security baseline is rolled out.","en":"An initiative is a collection of related policy definitions that are assigned as one unit, which is how a standard such as a security baseline is rolled out.","de":"An initiative is a collection of related policy definitions that are assigned as one unit, which is how a standard such as a security baseline is rolled out."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/governance/policy/overview","https://learn.microsoft.com/en-us/azure/governance/policy/concepts/initiative-definition-structure"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Centrally manage hybrid resources with Azure Policy","objectiveId":"hybrid-policy","topic":"Azure Policy","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/governance/policy/overview","https://learn.microsoft.com/en-us/azure/governance/policy/concepts/initiative-definition-structure"],"keyPoints":["A policy definition expresses one rule and its effect.","An initiative groups related definitions into a single object with parameters, so a set of controls is assigned in one action.","Assignment scope decides where the initiative applies, and exemptions document deliberate deviations."],"whyOthers":["","A diagnostic setting configures which telemetry a resource sends; it does not group policy definitions.","A deployment template creates resources and has no bearing on policy grouping.","A management group organises subscriptions for cross-subscription governance and is not a grouping of policy rules."],"requirements":"Applies to Azure Policy in subscriptions and management groups. Exemptions should be recorded with a reason and an expiry so deviations stay auditable.","translations":"runtime-google"},
{"id":"az802-q-320","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"A runbook must change resources in Azure. What should it authenticate with?","options":["A managed identity with a narrowly scoped role assignment","A shared administrator password stored in the runbook","A service principal password embedded in a runbook parameter","A personal account with contributor rights on the subscription"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"A managed identity is created by Azure for the resource itself, so there is no credential to store, rotate, or leak when the runbook changes resources.","en":"A managed identity is created by Azure for the resource itself, so there is no credential to store, rotate, or leak when the runbook changes resources.","de":"A managed identity is created by Azure for the resource itself, so there is no credential to store, rotate, or leak when the runbook changes resources."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/entra/identity/managed-identities-azure-resources/overview","https://learn.microsoft.com/en-us/azure/automation/overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Automate administration with runbooks and managed identities","objectiveId":"hybrid-automation","topic":"Automation identity","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/entra/identity/managed-identities-azure-resources/overview","https://learn.microsoft.com/en-us/azure/automation/overview"],"keyPoints":["A system-assigned managed identity belongs to a single Azure resource and needs no stored secret.","A user-assigned managed identity can be shared by several resources and has its own lifecycle and role assignments.","Least privilege means assigning the identity only the specific actions the runbook performs, so a compromise of the runbook has bounded impact."],"whyOthers":["","A password stored in a runbook is a secret at rest in the repository, which is exactly the exposure to avoid.","A service principal password has the same at-rest problem, and its secret still has to be rotated by hand.","A personal account cannot be audited or removed without affecting the person, and grants far more rights than the runbook needs."],"requirements":"Applies to Azure Automation runbooks and any Azure-hosted automation. The identity needs role assignments created for the specific resource operations the runbook performs.","translations":"runtime-google"},
{"id":"az802-q-321","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"Which rule component decides what an Azure Monitor Agent collects and where that data is sent?","options":["A data collection rule","An availability zone","A network security group","A virtual network gateway connection"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"A data collection rule is the place where data sources, transformations, and destinations are declared, and the agent acts on it.","en":"A data collection rule is the place where data sources, transformations, and destinations are declared, and the agent acts on it.","de":"A data collection rule is the place where data sources, transformations, and destinations are declared, and the agent acts on it."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-monitor/data-collection/data-collection-rule-overview","https://learn.microsoft.com/en-us/azure/azure-monitor/agents/azure-monitor-agent-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Monitor hybrid servers with Azure Monitor","objectiveId":"hybrid-monitoring","topic":"Hybrid telemetry","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-monitor/data-collection/data-collection-rule-overview","https://learn.microsoft.com/en-us/azure/azure-monitor/agents/azure-monitor-agent-overview"],"keyPoints":["A data collection rule lists the data sources to collect, the transformations to apply, and one or more destinations.","Associating the rule with one or more machines is what activates collection for those servers.","Because the rule is a separate object, the same agent can be steered differently for different machines without reinstalling it."],"whyOthers":["","An availability zone spreads compute across physical locations and has no telemetry routing function.","A network security group filters traffic between resources and does not describe collected data.","A virtual network gateway connects networks and is unrelated to how telemetry is collected or routed."],"requirements":"Applies to Azure Monitor Agent on Azure virtual machines, Azure Arc-enabled servers, and on-premises machines. Destination workspaces must be reachable from the machine.","commandPath":[{"label":"List the data collection rules in a resource group","command":"az monitor am collection rule list --resource-group rg-prod --output table"}],"translations":"runtime-google"},
{"id":"az802-q-322","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"Which Azure Update Manager feature reports which updates each machine is missing?","options":["Periodic assessment","Automatic VM Guest patching","Maintenance control","Hotpatching"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Periodic assessment refreshes the inventory of pending updates per machine, which is what makes compliance reporting and targeted deployment possible.","en":"Periodic assessment refreshes the inventory of pending updates per machine, which is what makes compliance reporting and targeted deployment possible.","de":"Periodic assessment refreshes the inventory of pending updates per machine, which is what makes compliance reporting and targeted deployment possible."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/update-manager/overview","https://learn.microsoft.com/en-us/azure/update-manager/scheduled-patching"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Manage updates for hybrid servers","objectiveId":"hybrid-updates","topic":"Update compliance","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/update-manager/overview","https://learn.microsoft.com/en-us/azure/update-manager/scheduled-patching"],"keyPoints":["Periodic assessment populates the machine inventory that shows pending updates and their state.","Without an assessment, the service cannot list which updates apply to which machine, so the inventory is a prerequisite for reporting.","The assessment can be enabled per machine or pushed with Azure Policy at scale."],"whyOthers":["","Automatic VM Guest patching installs updates on a cadence without waiting for a deployment; it does not produce a compliance inventory.","Maintenance control governs platform updates on the host, which is a separate mechanism from guest machine updates.","Hotpatching applies selected updates without a reboot and is an installation feature rather than an inventory feature."],"requirements":"Applies to Azure virtual machines and Arc-enabled servers. Assessment requires the agent path to be configured and the workspace to be reachable.","translations":"runtime-google"},
{"id":"az802-q-323","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"What is the primary interface Windows Admin Center provides for managing servers?","options":["A browser-based management console","A command prompt that runs only on the local host","A read-only reporting portal","An Azure Policy assignment interface"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Windows Admin Center is a browser-based management console for Windows Server, usable from the local gateway or in Azure.","en":"Windows Admin Center is a browser-based management console for Windows Server, usable from the local gateway or in Azure.","de":"Windows Admin Center is a browser-based management console for Windows Server, usable from the local gateway or in Azure."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/manage/windows-admin-center/understand/what-is","https://learn.microsoft.com/en-us/windows-server/manage/windows-admin-center/plan/installation-options"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Manage Windows Server by using Windows Admin Center","objectiveId":"hybrid-windows-admin-center","topic":"Windows Admin Center","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/manage/windows-admin-center/understand/what-is","https://learn.microsoft.com/en-us/windows-server/manage/windows-admin-center/plan/installation-options"],"keyPoints":["Windows Admin Center can run as an on-premises gateway or as an Azure extension in the portal.","It offers a common set of management tools across supported Windows Server versions without installing each role's separate console everywhere.","Access is protected by the same identity and conditional access controls as the environment hosting it."],"whyOthers":["","A local-only command prompt is not a browser console and offers none of the cross-server views that define the product.","The console manages live servers, so calling it read-only understates what it does.","Azure Policy assignment happens in the Azure portal; Windows Admin Center is not a policy interface."],"requirements":"Applies to Windows Admin Center on Windows Server 2016 and later, in either gateway or Azure-hosted mode. Secure access with HTTPS and a certificate clients trust.","translations":"runtime-google"},
{"id":"az802-q-324","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"Which transport does PowerShell Remoting use between a Windows server and a remote managed host?","options":["WS-Management over HTTP or HTTPS with Kerberos authentication","Server Message Block shares mapped as drives","Remote Registry over named pipes","Telnet with a shared administrator password"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"PowerShell Remoting runs over WinRM, which speaks WS-Management and authenticates with Kerberos when the connection is configured for it.","en":"PowerShell Remoting runs over WinRM, which speaks WS-Management and authenticates with Kerberos when the connection is configured for it.","de":"PowerShell Remoting runs over WinRM, which speaks WS-Management and authenticates with Kerberos when the connection is configured for it."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/powershell/scripting/learn/ps101/08-powershell-remoting?view=powershell-7.6","https://learn.microsoft.com/en-us/powershell/scripting/security/remoting/winrm-security?view=powershell-7.6"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Manage servers remotely with PowerShell remoting","objectiveId":"hybrid-remoting","topic":"Remote management transport","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/powershell/scripting/learn/ps101/08-powershell-remoting?view=powershell-7.6","https://learn.microsoft.com/en-us/powershell/scripting/security/remoting/winrm-security?view=powershell-7.6"],"keyPoints":["WinRM is the Windows implementation of WS-Management and carries the remoting session traffic.","Kerberos is used when both sides can resolve the target by name and the credentials are domain credentials, which is the secure default.","Testing the configuration with Test-WSMan is the standard first step before diagnosing a remoting failure."],"whyOthers":["","SMB shares carry files, not remoting sessions, and mapping a drive is unrelated to PowerShell Remoting.","Remote Registry is a legacy registry-edit mechanism and is not the transport PowerShell Remoting uses.","Telnet is an unencrypted protocol and is not used for PowerShell Remoting at all."],"requirements":"The management service must be running and the listener must allow the connecting identity. Prefer HTTPS for remoting across untrusted networks.","commandPath":[{"label":"Test that WinRM is configured and reachable on a host","command":"Test-WSMan -ComputerName srv01.contoso.com"},{"label":"Enter a PowerShell Remoting session interactively","command":"Enter-PSSession -ComputerName srv01.contoso.com -Credential (Get-Credential)"}],"translations":"runtime-google"},
{"id":"az802-q-325","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"A remoting session reaches Server B successfully, but a command on B that reads a share on Server C returns access denied. What is the likely cause?","options":["The second network hop needs the credential delegated, which Kerberos does not do by default","Server C has no DNS record pointing at Server B","The WS-Management listener on B has stopped","PowerShell Remoting requires the SameSubnet parameter for all connections"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"The intermediate server does not hold the user's credentials, so accessing a second network resource fails unless delegation is configured or CredSSP is used.","en":"The intermediate server does not hold the user's credentials, so accessing a second network resource fails unless delegation is configured or CredSSP is used.","de":"The intermediate server does not hold the user's credentials, so accessing a second network resource fails unless delegation is configured or CredSSP is used."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/powershell/scripting/security/remoting/ps-remoting-second-hop?view=powershell-7.6","https://learn.microsoft.com/en-us/powershell/scripting/security/remoting/winrm-security?view=powershell-7.6"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Manage servers remotely with PowerShell remoting","objectiveId":"hybrid-remoting","topic":"Second hop","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/powershell/scripting/security/remoting/ps-remoting-second-hop?view=powershell-7.6","https://learn.microsoft.com/en-us/powershell/scripting/security/remoting/winrm-security?view=powershell-7.6"],"keyPoints":["Kerberos does not forward the user's ticket to a second server by default, which is the double-hop restriction.","Constrained delegation, resource-based constrained delegation, CredSSP, or virtual accounts are the supported ways to make the second hop work.","CredSSP is easy to configure but delegates credentials to the intermediate server, so it should be limited to hosts that need it."],"whyOthers":["","Server B already has no credentials for the second hop, so a DNS record on C is not the blocker.","A stopped listener would break the first connection to B as well, and the session succeeded.","SameSubnet has nothing to do with delegation; it only prevents a remoting session from crossing subnet boundaries."],"requirements":"Prefer constrained delegation over CredSSP where possible, because CredSSP makes the intermediate server responsible for a forwarded credential.","commandPath":[{"label":"Create a constrained delegation entry for the service account","command":"Set-ADServiceAccount -Identity svc-admin -PrincipalsAllowedToDelegateToAccounts 'HTTP/srv03.contoso.com'"},{"label":"Test the second hop from inside an existing session","command":"Invoke-Command -ComputerName srv03.contoso.com -ScriptBlock { Get-Service -Name Spooler }"}],"translations":"runtime-google"},
{"id":"az802-q-326","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"What makes an Azure Automation runbook useful for an operations team beyond simply running the script?","options":["It records runs and outputs, so the outcome of each execution can be audited afterwards","It runs only on a schedule and cannot be started on demand","It stores the runbook source outside version control","It removes the need for any monitoring after the change"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Automation records every run with its inputs, output, and job history, which is what makes an administrative change auditable and repeatable.","en":"Automation records every run with its inputs, output, and job history, which is what makes an administrative change auditable and repeatable.","de":"Automation records every run with its inputs, output, and job history, which is what makes an administrative change auditable and repeatable."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/automation/overview","https://learn.microsoft.com/en-us/entra/identity/managed-identities-azure-resources/overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Automate administration with runbooks and managed identities","objectiveId":"hybrid-automation","topic":"Runbooks","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/automation/overview","https://learn.microsoft.com/en-us/entra/identity/managed-identities-azure-resources/overview"],"keyPoints":["Job history shows the schedule or trigger, the runbook, the status, and the error output for each execution.","Runbooks can be triggered on a schedule, on a webhook, or manually, so they are not limited to one mode.","Idempotent runbooks can be re-run safely after a failure, which matters for recovery procedures."],"whyOthers":["","Runbooks can be started on demand or from a webhook, so on-demand execution is a supported mode.","Source belongs in version control; storing it outside that would make changes harder to review.","A successful script does not remove the need for monitoring, because a change can succeed and still cause a later problem."],"requirements":"Runbooks need an identity with only the permissions they use, and their output should be retained long enough to support an audit.","translations":"runtime-google"},
{"id":"az802-q-327","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"Why is key-based OpenSSH authentication preferred over allowing password logon to Windows Server?","options":["A key cannot be guessed or reused across servers the way a password can","Keys do not require the OpenSSH Server feature to be installed","Keys allow the account to be shared between several administrators","Keys remove the need for any account lockout policy"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Public-key authentication proves possession of a private key rather than a reusable secret, so a leaked host key set cannot be replayed against another server.","en":"Public-key authentication proves possession of a private key rather than a reusable secret, so a leaked host key set cannot be replayed against another server.","de":"Public-key authentication proves possession of a private key rather than a reusable secret, so a leaked host key set cannot be replayed against another server."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/openssh/openssh-overview","https://learn.microsoft.com/en-us/windows-server/administration/openssh/openssh_keymanagement"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Manage remote access with SSH and Remote Desktop Services","objectiveId":"hybrid-remote-access","topic":"OpenSSH","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/openssh/openssh-overview","https://learn.microsoft.com/en-us/windows-server/administration/openssh/openssh_keymanagement"],"keyPoints":["Public-key authentication transfers only the public key to the server, and the private key never leaves the client.","The server stores the public key per user, so access can be revoked by removing that key for that account.","Password logon stays available for recovery, so disabling it is a control rather than an absolute requirement."],"whyOthers":["","Key authentication still needs the OpenSSH Server capability installed and the service running.","Keys belong to an individual account, so sharing one defeats the accountability that they are chosen to improve.","Account lockout policy is unrelated to the authentication method; it protects the account in both cases."],"requirements":"Applies to Windows Server 2019 and later with the OpenSSH Server capability. Keep administrative shell access as a separate controlled path in case key authentication fails.","commandPath":[{"label":"List the authorized public keys for a user","command":"Get-Content C:\\ProgramData\\ssh\\administrators_authorized_keys"},{"label":"Check the state of the OpenSSH service","command":"Get-Service sshd | Select-Object Status, StartType"}],"translations":"runtime-google"},
{"id":"az802-q-328","domain":"Manage Windows Server instances and workloads in a hybrid environment","text":"Which factor most often breaks an otherwise correct hybrid management design?","options":["The on-premises server cannot resolve or reach the Azure endpoints the management path depends on","The workload runs on a physical server instead of a virtual machine","The subscription uses a management group hierarchy","Azure Policy is assigned at the subscription rather than resource group level"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Hybrid management depends on outbound connectivity and name resolution from the server to Azure endpoints, and both are commonly missing or filtered in an otherwise sound design.","en":"Hybrid management depends on outbound connectivity and name resolution from the server to Azure endpoints, and both are commonly missing or filtered in an otherwise sound design.","de":"Hybrid management depends on outbound connectivity and name resolution from the server to Azure endpoints, and both are commonly missing or filtered in an otherwise sound design."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-arc/servers/network-requirements","https://learn.microsoft.com/en-us/azure/azure-arc/servers/agent-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Manage hybrid workloads and connectivity","objectiveId":"hybrid-workloads","topic":"Hybrid connectivity","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-arc/servers/network-requirements","https://learn.microsoft.com/en-us/azure/azure-arc/servers/agent-overview"],"keyPoints":["The agent initiates outbound connections to Azure, so the firewall and proxy configuration on the server decides whether onboarding succeeds.","Name resolution for the required endpoints must work from the server, which is a separate requirement from general internet access.","Where a proxy is required, its authentication must be configured or the agent cannot connect and the machine stays offline in Azure."],"whyOthers":["","Physical versus virtual placement has no bearing on whether the management path can reach Azure endpoints.","A management group hierarchy is an organisational choice and does not affect connectivity from a server.","Assignment scope in Azure Policy is unrelated to whether the server can reach the service endpoints."],"requirements":"Applies to Azure Arc-enabled servers and Azure-hosted management. Document the required outbound endpoints and the proxy configuration as part of the rollout plan.","translations":"runtime-google"},
{"id":"az802-q-329","domain":"Manage virtual machines","text":"A lab needs virtual machines that can reach each other but must not reach any physical network. Which switch type is correct?","options":["Internal","External","Private","A Hyper-V network bridge"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"An internal switch connects virtual machines to each other and to the host's virtual adapter, without binding to a physical network adapter.","en":"An internal switch connects virtual machines to each other and to the host's virtual adapter, without binding to a physical network adapter.","de":"An internal switch connects virtual machines to each other and to the host's virtual adapter, without binding to a physical network adapter."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/get-started/create-a-virtual-switch-for-hyper-v-virtual-machines"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Configure virtual machine networking","objectiveId":"vm-networking","topic":"Virtual switch types","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/get-started/create-a-virtual-switch-for-hyper-v-virtual-machines"],"keyPoints":["An internal switch serves virtual machines and the host, with no uplink to a physical adapter.","An external switch is bound to a physical adapter and therefore reaches the physical network.","A private switch serves only the attached virtual machines, with no host adapter, which is why an isolated lab normally uses internal instead."],"whyOthers":["","An external switch is bound to a physical adapter, so the lab traffic could leave the host.","A private switch excludes the host from the switch, which prevents management from the host and is not what an isolated lab normally needs.","A network bridge joins an external switch to a physical adapter, which is the opposite of isolation."],"requirements":"Applies to Hyper-V on supported Windows Server versions. The switch type is chosen when the switch is created and can be changed afterwards in Switch Manager.","translations":"runtime-google"},
{"id":"az802-q-330","domain":"Manage virtual machines","text":"Which Hyper-V feature lets the host see that a guest is running and lets the guest request a controlled shutdown?","options":["Hyper-V Integration Services","Discrete Device Assignment","Nested virtualization","Storage Spaces Direct"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Integration Services provide the heartbeat, time synchronisation, shutdown, and data exchange between the Hyper-V host and a supported guest.","en":"Integration Services provide the heartbeat, time synchronisation, shutdown, and data exchange between the Hyper-V host and a supported guest.","de":"Integration Services provide the heartbeat, time synchronisation, shutdown, and data exchange between the Hyper-V host and a supported guest."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/manage/manage-hyper-v-integration-services"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Manage virtual machine compute and integration services","objectiveId":"vm-compute","topic":"Integration services","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/manage/manage-hyper-v-integration-services"],"keyPoints":["The heartbeat lets the host report the guest's running state rather than treating it as unreachable.","Integration Services allow a graceful shutdown request so the guest can close applications and flush data.","Time synchronisation from the host keeps guest time aligned, which matters for domain-joined workloads and authentication."],"whyOthers":["","Discrete Device Assignment passes a physical device such as a GPU straight through to a guest and provides no host-guest service channel.","Nested virtualization lets a guest run its own hypervisor; it is unrelated to integration services.","Storage Spaces Direct pools local storage for cluster use and is not a host-guest integration feature."],"requirements":"Integration Services are available in supported guests. Older integration components should be updated, and guests without integration services remain usable but lose time sync and graceful shutdown.","commandPath":[{"label":"List the integration services and their state for a VM","command":"Get-VMIntegrationService -Name AppV -VMName srv01"}],"translations":"runtime-google"},
{"id":"az802-q-331","domain":"Manage virtual machines","text":"Replication across a limited WAN link is pushing the link to saturation during working hours. Which change should be evaluated first?","options":["Enable compression or lengthen the replication interval, after checking the available network capacity","Enable synchronous replication so every write is acknowledged by the replica","Disable replication during business hours to protect application latency","Attach the replica's disks to the primary host so they share one storage path"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Replication is asynchronous, so the way to protect a constrained link is to reduce the traffic it carries: compression, a longer interval, or fewer replicated disks.","en":"Replication is asynchronous, so the way to protect a constrained link is to reduce the traffic it carries: compression, a longer interval, or fewer replicated disks.","de":"Replication is asynchronous, so the way to protect a constrained link is to reduce the traffic it carries: compression, a longer interval, or fewer replicated disks."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/replication-overview","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/manage/set-up-hyper-v-replica"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Configure high availability and replication for virtual machines","objectiveId":"vm-ha-replication","topic":"Hyper-V Replica","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/replication-overview","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/manage/set-up-hyper-v-replica"],"keyPoints":["Replication is asynchronous, so the primary accepts writes without waiting for the replica, and the link is protected by controlling the traffic volume rather than by blocking writes.","Compression reduces bandwidth usage, and a longer replication interval reduces how often traffic is sent.","Sizing should account for the available network capacity, and disks whose data is not needed after failover can be excluded to conserve bandwidth."],"whyOthers":["","Synchronous replication would put the primary's write latency at the mercy of the link, which is exactly what asynchronous replication avoids.","Disabling replication during business hours stops the copy from advancing during the busiest period, which lengthens the recovery point window.","Attaching the replica's disks to the primary would break the replicated pair and risk two hosts writing the same disk."],"requirements":"Replication traffic must be allowed between the hosts. Compression and replication interval are configured per replication relationship, and the choice should be validated against measured capacity rather than assumed.","commandPath":[{"label":"List the replication relationships for the host","command":"Get-VMReplication"},{"label":"Show the current replication state of a virtual machine","command":"Get-VMReplication -VMName app01 | Select-Object State, Health, LastReplicationTime"}],"translations":"runtime-google"},
{"id":"az802-q-332","domain":"Manage virtual machines","text":"Which operation proves that a replicated virtual machine can start without affecting the production source?","options":["Test failover","Planned failover","Repurposing the source virtual machine","A checkpoint consolidation on the replica"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Test failover starts the replica copy at the secondary site to verify it can run, while leaving the production virtual machine untouched.","en":"Test failover starts the replica copy at the secondary site to verify it can run, while leaving the production virtual machine untouched.","de":"Test failover starts the replica copy at the secondary site to verify it can run, while leaving the production virtual machine untouched."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/replication-failover","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/manage/set-up-hyper-v-replica"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Configure high availability and replication for virtual machines","objectiveId":"vm-ha-replication","topic":"Replica validation","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/replication-failover","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/manage/set-up-hyper-v-replica"],"keyPoints":["Test failover starts the replica on the secondary host so its operability can be checked without touching the primary.","Planned failover is used to move production deliberately, usually during a planned outage.","An unplanned failover is used when the primary is gone and the replica must be promoted to production."],"whyOthers":["","Planned failover is an orderly move of production traffic and is a heavier action than the verification this scenario needs.","Repurposing the source discards the production copy and is never a verification step.","Checkpoint consolidation reclaims differencing disk space and says nothing about whether the replica can boot."],"requirements":"The replica must be present and healthy before a test failover, and test failovers should be repeated on a schedule so the copy is known to be usable.","commandPath":[{"label":"Start a test failover on the replica host","command":"Start-VMFailoverTester -VMName app01 -TestFailover"},{"label":"List replication points before testing","command":"Get-VMReplicationPoint -VMName app01"}],"translations":"runtime-google"},
{"id":"az802-q-333","domain":"Manage virtual machines","text":"A healthy virtual machine should be moved deliberately to its replica. Which operation is appropriate?","options":["Planned failover","Test failover","Unplanned failover","A live storage migration"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Planned failover is the orderly role reversal used when the source is still healthy and the replica should take over.","en":"Planned failover is the orderly role reversal used when the source is still healthy and the replica should take over.","de":"Planned failover is the orderly role reversal used when the source is still healthy and the replica should take over."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/replication-failover","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/replication-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Configure high availability and replication for virtual machines","objectiveId":"vm-ha-replication","topic":"Planned failover","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/replication-failover","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/replication-overview"],"keyPoints":["Planned failover transfers the replication role so the replica becomes authoritative while the source is still available.","The replication point is selected so the replica starts with the least data loss the business can accept.","Live migration moves a guest between cluster nodes and does not change which copy is authoritative."],"whyOthers":["","Test failover verifies the replica can start and is not the mechanism for deliberately moving production.","Unplanned failover is for when the source is already lost, so it loses data and is not an orderly move.","Live storage migration moves virtual disks between storage, not the virtual machine between replicated hosts."],"requirements":"The source and replica must be able to communicate, and a replication point close to the failover moment limits the data loss window.","commandPath":[{"label":"Start a planned failover on the replica host","command":"Start-VMFailover -ComputerName replica01 -VMName app01 -Action PlannedFailover"}],"translations":"runtime-google"},
{"id":"az802-q-334","domain":"Manage virtual machines","text":"Which Hyper-V feature passes a physical PCIe device, such as a GPU, directly to a virtual machine?","options":["Discrete Device Assignment","Storage Spaces Direct","A network bridge","Live migration"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Discrete Device Assignment maps the whole physical device into the guest's input/output address space, which is how a GPU is shared out to a virtual machine.","en":"Discrete Device Assignment maps the whole physical device into the guest's input/output address space, which is how a GPU is shared out to a virtual machine.","de":"Discrete Device Assignment maps the whole physical device into the guest's input/output address space, which is how a GPU is shared out to a virtual machine."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/plan/plan-for-deploying-devices-using-discrete-device-assignment","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/gpu-partitioning"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Configure virtual machine networking","objectiveId":"vm-networking","topic":"Device assignment","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/plan/plan-for-deploying-devices-using-discrete-device-assignment","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/gpu-partitioning"],"keyPoints":["The device is unmapped from the host and remapped into the guest's PCI address space.","It is used where a workload needs pass-through access, for example GPU acceleration or a host bus adapter.","Only one virtual machine can hold an assigned device at a time, which limits how many such workloads a host can run."],"whyOthers":["","Storage Spaces Direct pools local storage for cluster use and does not pass a device into a guest.","A network bridge connects a virtual switch to a physical adapter and concerns networking rather than device mapping.","Live migration moves a running guest between cluster nodes and does not change which machine owns a device."],"requirements":"The device must be supported for assignment and must not be in use by the host. GPU partitioning is the alternative when several guests must share one GPU.","commandPath":[{"label":"List discrete devices currently assigned to virtual machines","command":"Get-VMDiscreteDevice"}],"translations":"runtime-google"},
{"id":"az802-q-335","domain":"Manage virtual machines","text":"Which checkpoint type is normally safer for a production application workload where the guest supports it?","options":["Production checkpoint","Standard checkpoint","Differencing disk","A virtual machine snapshot taken while the guest is running"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"A production checkpoint uses the guest's own backup-aware infrastructure to capture application-consistent state, which is safer than a host-level freeze.","en":"A production checkpoint uses the guest's own backup-aware infrastructure to capture application-consistent state, which is safer than a host-level freeze.","de":"A production checkpoint uses the guest's own backup-aware infrastructure to capture application-consistent state, which is safer than a host-level freeze."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/manage/choose-between-standard-or-production-checkpoints-in-hyper-v","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/checkpoints"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Manage virtual machine storage and checkpoints","objectiveId":"vm-storage-checkpoints","topic":"Checkpoint types","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/manage/choose-between-standard-or-production-checkpoints-in-hyper-v","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/checkpoints"],"keyPoints":["A production checkpoint coordinates with the guest, for example through the Volume Shadow Copy Service, so memory and application state are captured consistently.","A standard checkpoint freezes the guest and captures memory and disk state from outside, which is less safe for applications that keep state in memory.","Production checkpoints require integration components in the guest, so an unsupported guest falls back to the standard behaviour."],"whyOthers":["","A standard checkpoint captures the guest from outside the operating system, so application-consistent state is not guaranteed.","A differencing disk describes how a virtual hard disk is layered; it is not a checkpoint type.","A snapshot taken from the host while the guest runs is the host-level behaviour that production checkpoints are designed to replace."],"requirements":"Production checkpoints need the guest integration components and are not supported on some configurations. Standard checkpoints also create memory state, so long-lived checkpoints consume storage.","commandPath":[{"label":"Set the checkpoint type and review the space threshold","command":"Set-VM -Name app01 -CheckpointType ProductionStandard -AutomaticCheckpointsEnabled $true"}],"translations":"runtime-google"},
{"id":"az802-q-336","domain":"Manage virtual machines","text":"Which Hyper-V feature lets an administrator run PowerShell in a supported Windows guest even when the guest has no network connectivity?","options":["PowerShell Direct","SSH Direct","Remote Desktop Services","A virtual network adapter with a host-only switch"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"PowerShell Direct runs over the Hyper-V integration channel, so it reaches a supported Windows guest without relying on the guest's network stack.","en":"PowerShell Direct runs over the Hyper-V integration channel, so it reaches a supported Windows guest without relying on the guest's network stack.","de":"PowerShell Direct runs over the Hyper-V integration channel, so it reaches a supported Windows guest without relying on the guest's network stack."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/powershell-direct"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Manage virtual machine compute and integration services","objectiveId":"vm-compute","topic":"Guest management","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/powershell-direct"],"keyPoints":["It uses the Hyper-V integration services rather than TCP, so no IP address, DNS, or firewall configuration is needed.","It requires a supported Windows guest that has the integration components running.","A Linux guest is managed with SSH Direct instead, which does depend on the guest's network configuration."],"whyOthers":["","SSH Direct manages a Linux guest over SSH and therefore still depends on the guest's network configuration.","Remote Desktop Services needs a working network path and a session host, so it cannot reach an unconnected guest.","A host-only switch still requires a working network stack in the guest, which is exactly what is unavailable in this scenario."],"requirements":"Applies to supported Windows guests with integration services installed. The connecting account must be an administrator inside the guest.","commandPath":[{"label":"Run a PowerShell Direct command in a guest","command":"Invoke-Command -VMName srv01 -ScriptBlock { Get-Service -Name Spooler }"}],"translations":"runtime-google"},
{"id":"az802-q-337","domain":"Manage virtual machines","text":"What does nested virtualization allow a Hyper-V virtual machine to do?","options":["Run its own hypervisor and create virtual machines","Attach a second physical GPU to the guest","Persist a virtual machine across host reboots","Replicate a virtual machine to a second site"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Nested virtualization exposes the virtualization extensions to the guest, so the guest can act as a hypervisor hosting its own virtual machines.","en":"Nested virtualization exposes the virtualization extensions to the guest, so the guest can act as a hypervisor hosting its own virtual machines.","de":"Nested virtualization exposes the virtualization extensions to the guest, so the guest can act as a hypervisor hosting its own virtual machines."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/virtualization/hyper-v-on-windows/user-guide/nested-virtualization"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Manage virtual machine compute and integration services","objectiveId":"vm-compute","topic":"Nested virtualization","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/virtualization/hyper-v-on-windows/user-guide/nested-virtualization"],"keyPoints":["The outer hypervisor provides the virtualization extensions to the inner guest.","It is used for development and test labs where virtual machines must host virtual machines.","It has hardware and feature requirements, and nested workloads have their own performance cost."],"whyOthers":["","Attaching a second GPU is device assignment or GPU partitioning, which is a separate feature.","Persisting a virtual machine across host reboots is about how the guest is configured and stored, not about running a hypervisor.","Replication to a second site is Hyper-V Replica, which is unrelated to nesting."],"requirements":"Supported on recent generations of hardware with a supported guest and a compatible host. Nested workloads should be sized with the extra overhead in mind.","commandPath":[{"label":"Check whether nested virtualization is exposed on a VM","command":"Get-VMProcessor -VMName lab01 | Select-Object ExposeVirtualizationExtensions"}],"translations":"runtime-google"},
{"id":"az802-q-338","domain":"Manage virtual machines","text":"Which Azure capability spreads virtual machines across separate physical fault domains in one region?","options":["An availability set","An availability zone","A virtual network gateway","A load balancer rule"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"An availability set places virtual machines across fault domains and update domains in a single datacenter, so a single failure does not take the whole application down.","en":"An availability set places virtual machines across fault domains and update domains in a single datacenter, so a single failure does not take the whole application down.","de":"An availability set places virtual machines across fault domains and update domains in a single datacenter, so a single failure does not take the whole application down."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/virtual-machines/availability-set-overview","https://learn.microsoft.com/en-us/azure/reliability/availability-zones-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Manage virtual machines in Azure","objectiveId":"vm-azure","topic":"Availability","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/virtual-machines/availability-set-overview","https://learn.microsoft.com/en-us/azure/reliability/availability-zones-overview"],"keyPoints":["An availability set spreads virtual machines across fault domains and update domains inside one datacenter.","Update domains allow a platform maintenance event to be rolled through the set rather than affecting every machine at once.","A zone-spanning deployment or availability zones cover region-wide outages, which a single availability set does not."],"whyOthers":["","Availability zones spread workloads across separate datacenters in a region, which protects against a datacenter-level failure rather than an in-datacenter one.","A virtual network gateway connects networks and has no placement effect on virtual machines.","A load balancer rule distributes connections across healthy instances but places no fault-domain constraint on them."],"requirements":"All virtual machines in an availability set must be in one region and one virtual network. Pair it with zone redundancy or availability zones for region-wide resilience.","commandPath":[{"label":"Show the fault and update domains of an availability set","command":"az vm availability-set show -g rg-prod -n avset-web --output table"}],"translations":"runtime-google"},
{"id":"az802-q-339","domain":"Manage virtual machines","text":"Which Azure service runs a group of virtual machines that scale out and in automatically as demand changes?","options":["A virtual machine scale set","An availability set","A managed disk","A network security group"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"A virtual machine scale set keeps a uniform set of virtual machines and adjusts the instance count through scaling rules as load changes.","en":"A virtual machine scale set keeps a uniform set of virtual machines and adjusts the instance count through scaling rules as load changes.","de":"A virtual machine scale set keeps a uniform set of virtual machines and adjusts the instance count through scaling rules as load changes."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/virtual-machine-scale-sets/overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Manage virtual machines in Azure","objectiveId":"vm-azure","topic":"Scale-out","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/virtual-machine-scale-sets/overview"],"keyPoints":["A scale set applies one configuration and OS image across its instances, so they stay consistent as capacity changes.","Scaling rules add or remove instances based on a metric such as CPU percentage or a schedule.","Scale-in removes instances only while they are healthy, so availability settings remain in force."],"whyOthers":["","An availability set spreads a fixed number of virtual machines across fault domains but does not change the instance count automatically.","A managed disk is storage attached to a virtual machine and has no scaling function.","A network security group filters traffic to and from network interfaces and does not create or remove virtual machines."],"requirements":"Scaling rules need a defined metric or schedule and a defined minimum and maximum instance count. Uniform orchestration is the default for a scale set.","commandPath":[{"label":"Show the scaling settings of a scale set","command":"az vmss scale show -g rg-prod -n vmss-web --output table"}],"translations":"runtime-google"},
{"id":"az802-q-340","domain":"Manage virtual machines","text":"Which Azure Defender feature opens a short-lived, approved connection to a virtual machine through the portal without exposing a public IP address?","options":["Just-in-time VM access","Just-in-time network access on an application gateway","Azure Bastion host scaling","A private endpoint for the management plane"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Just-in-time VM access requests a time-boxed connection to the virtual machine and removes the inbound rule afterwards, so standing access is not left behind.","en":"Just-in-time VM access requests a time-boxed connection to the virtual machine and removes the inbound rule afterwards, so standing access is not left behind.","de":"Just-in-time VM access requests a time-boxed connection to the virtual machine and removes the inbound rule afterwards, so standing access is not left behind."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/defender-for-cloud/just-in-time-access-overview","https://learn.microsoft.com/en-us/azure/defender-for-cloud/defender-for-servers-introduction"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Manage virtual machines in Azure","objectiveId":"vm-azure","topic":"Privileged access","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/defender-for-cloud/just-in-time-access-overview","https://learn.microsoft.com/en-us/azure/defender-for-cloud/defender-for-servers-introduction"],"keyPoints":["Just-in-time access replaces permanent inbound allow rules with a time-limited request that is reviewed and then expires.","The connection is initiated from the Azure environment, so the virtual machine needs no public IP address.","Requested connections and their activity appear in activity logs, which supports an access audit."],"whyOthers":["","Just-in-time network access on Application Gateway protects inbound traffic to an application endpoint and is not a management connection to the machine itself.","Bastion scaling changes how many Bastion hosts exist to handle sessions, and does not control who may connect to a machine.","A private endpoint places a service interface inside the virtual network and has no time-boxed approval step."],"requirements":"Requires Microsoft Defender for Servers on the subscription and a supported network configuration. Policy should limit which principals may request access.","commandPath":[{"label":"List the just-in-time access configuration on a virtual machine","command":"az vm show -g rg-prod -n vm01 --query networkProfile.networkSecurityGroup"}],"translations":"runtime-google"},
{"id":"az802-q-341","domain":"Manage virtual machines","text":"Which virtual hard disk format supports larger capacity and resiliency features that VHD does not?","options":["VHDX","VHD","ISO","A differencing VHD"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"VHDX added a new header and alignment that allow much larger disks and features such as online resizing, while VHD is limited to 2 TB and cannot be resized online.","en":"VHDX added a new header and alignment that allow much larger disks and features such as online resizing, while VHD is limited to 2 TB and cannot be resized online.","de":"VHDX added a new header and alignment that allow much larger disks and features such as online resizing, while VHD is limited to 2 TB and cannot be resized online."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/openspecs/windows_protocols/ms-vhdx/83f6b700-6216-40f0-aa99-9fcb421206e2","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/features-terminology"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Manage virtual machine storage and checkpoints","objectiveId":"vm-storage-checkpoints","topic":"Virtual hard disk formats","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/openspecs/windows_protocols/ms-vhdx/83f6b700-6216-40f0-aa99-9fcb421206e2","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/features-terminology"],"keyPoints":["VHDX supports disks larger than 2 TB and can be resized while the virtual machine is running.","VHDX has better resiliency mechanisms, including protection against corruption from an unexpected power loss.","The VHD format remains for compatibility with older systems that cannot use VHDX."],"whyOthers":["","VHD is limited to 2 TB and cannot be resized while attached, which is why VHDX is preferred on current systems.","An ISO is an optical-disc image used to install or boot an operating system, not a writable virtual disk.","A differencing VHD describes a layering relationship to a parent disk and is not itself a file format with these capabilities."],"requirements":"Guests running an operating system older than Windows Server 2012 cannot use VHDX, so the format must match the oldest guest in the estate.","commandPath":[{"label":"Convert an existing VHD to the VHDX format","command":"Convert-VHD -Path C:\\disks\\app.vhd -DestinationPath C:\\disks\\app.vhdx"},{"label":"Show the virtual hard disks attached to a VM","command":"Get-VMHardDiskDrive -VMName app01"}],"translations":"runtime-google"},
{"id":"az802-q-342","domain":"Implement and manage on-premises and hybrid networking","text":"Which DNS zone type stores its records in Active Directory and replicates them through AD DS replication?","options":["An Active Directory-integrated zone","A primary zone stored in a file","A secondary zone","A stub zone"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"An Active Directory-integrated zone stores its records in the directory, so the same replication and multi-master behaviour applies to DNS data as to directory data.","en":"An Active Directory-integrated zone stores its records in the directory, so the same replication and multi-master behaviour applies to DNS data as to directory data.","de":"An Active Directory-integrated zone stores its records in the directory, so the same replication and multi-master behaviour applies to DNS data as to directory data."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/dns/zone-types","https://learn.microsoft.com/en-us/windows-server/networking/dns/manage-dns-zones"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Implement and manage DNS for Windows Server","objectiveId":"net-dns","topic":"DNS zones","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/dns/zone-types","https://learn.microsoft.com/en-us/windows-server/networking/dns/manage-dns-zones"],"keyPoints":["AD-integrated zones are stored as dnsNode objects in the directory rather than in a zone file.","Because the data lives in AD DS, several domain controllers can accept updates to the same zone without the single-owner problem of a file-backed primary zone.","AD-integrated zones also benefit from the directory's backup, and replication follows the site topology."],"whyOthers":["","A file-backed primary zone is stored on one server and copied by zone transfer, which is the behaviour AD integration is meant to remove.","A secondary zone also relies on zone transfer from a primary and holds a read-only copy.","A stub zone holds only the records needed to redirect queries for a delegated child zone, not the zone's authoritative data."],"requirements":"AD-integrated zones are the recommended type in an environment with AD DS. Existing file-backed zones can be converted to AD-integrated once the servers are ready.","commandPath":[{"label":"List the DNS zones and their type","command":"Get-DnsServerZone | Select-Object Name, ZoneType"}],"translations":"runtime-google"},
{"id":"az802-q-343","domain":"Implement and manage on-premises and hybrid networking","text":"An internal DNS server must resolve public internet names. Which configuration should it use?","options":["A forwarder list pointing at the organisation's approved recursive resolvers","A root hints file copied onto every internal server","An external DNS zone mirroring the root servers","A stub zone for com"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Forwarders delegate non-authoritative queries to approved resolvers, which keeps internal DNS authoritative for internal names and avoids the internal servers performing root queries themselves.","en":"Forwarders delegate non-authoritative queries to approved resolvers, which keeps internal DNS authoritative for internal names and avoids the internal servers performing root queries themselves.","de":"Forwarders delegate non-authoritative queries to approved resolvers, which keeps internal DNS authoritative for internal names and avoids the internal servers performing root queries themselves."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/dns/forwarding","https://learn.microsoft.com/en-us/troubleshoot/windows-server/networking/best-practices-for-dns-client-settings"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Implement and manage DNS for Windows Server","objectiveId":"net-dns","topic":"Forwarders","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/dns/forwarding","https://learn.microsoft.com/en-us/troubleshoot/windows-server/networking/best-practices-for-dns-client-settings"],"keyPoints":["A forwarder forwards queries it cannot answer authoritatively to another DNS server.","Forwarders centralise external resolution, which means internal servers make no outbound root queries and recursion is controlled in one place.","Pointing internal DNS at an ISP or public resolver directly leaks internal names and gives up control, so an approved internal resolver list is preferred."],"whyOthers":["","Root hints let a server find the root servers, which is how a recursive resolver bootstraps; it is not the mechanism for delegating external lookups to an approved resolver.","Mirroring the root zone onto internal servers is not a supported design and provides no benefit for resolving public names.","A stub zone only redirects queries for a delegated child namespace and says nothing about resolving public names."],"requirements":"Forwarders need a reachable, recursive resolver. Validate the change with Resolve-DnsName against the internal server, and check for leaked queries to the ISP if forwarders are removed.","commandPath":[{"label":"Show the forwarders configured on a DNS server","command":"Get-DnsServerForwarder -ComputerName dns01"},{"label":"Test resolution through the internal server","command":"Resolve-DnsName -Name learn.microsoft.com -Server dns01"}],"translations":"runtime-google"},
{"id":"az802-q-344","domain":"Implement and manage on-premises and hybrid networking","text":"A DHCP scope has no addresses left to hand out even though many clients still hold valid leases. What should be checked first?","options":["The scope's address pool, exclusions, reservations, and lease duration","The DNS zone file for the subnet","The site's AD DS site link cost","The client DNS suffix on each workstation"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Scope exhaustion is decided by the pool arithmetic: how many addresses exist, how many are excluded or reserved, and how long leases hold them.","en":"Scope exhaustion is decided by the pool arithmetic: how many addresses exist, how many are excluded or reserved, and how long leases hold them.","de":"Scope exhaustion is decided by the pool arithmetic: how many addresses exist, how many are excluded or reserved, and how long leases hold them."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/technologies/dhcp/dhcp-top","https://learn.microsoft.com/en-us/troubleshoot/windows-server/networking/troubleshooting-guide-dhcp-authorization-failures"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Implement and manage DHCP for Windows Server","objectiveId":"net-dhcp","topic":"DHCP scopes","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/technologies/dhcp/dhcp-top","https://learn.microsoft.com/en-us/troubleshoot/windows-server/networking/troubleshooting-guide-dhcp-authorization-failures"],"keyPoints":["The effective available count is the address range minus exclusions and reservations.","Long lease durations reduce recycling, so an exhausted pool with valid leases often means the range is too small for the lease time.","Split-scope or DHCP failover is used to keep service available when one server must carry the load."],"whyOthers":["","The DNS zone holds names, not addresses, and does not determine whether the DHCP pool is exhausted.","Site link cost influences AD DS replication, not DHCP address allocation.","A client DNS suffix has no effect on the pool of addresses available for lease."],"requirements":"Lease duration should match how quickly the client population changes. Watch for the scope falling below a useful percentage of free addresses.","commandPath":[{"label":"Show the scope statistics including remaining free addresses","command":"Get-DhcpServerv4ScopeStatistics -ScopeId 10.10.10.0"},{"label":"List the reservations that are outside the dynamic range","command":"Get-DhcpServerv4Reservation -ScopeId 10.10.10.0"}],"translations":"runtime-google"},
{"id":"az802-q-345","domain":"Implement and manage on-premises and hybrid networking","text":"DHCP clients on a remote subnet receive no addresses from the central DHCP server. What is missing?","options":["A DHCP relay agent on the router for that subnet","A DNS zone delegation for the remote subnet","A static route for UDP port 67 in both directions","A secondary DNS server on the remote subnet"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"DHCP broadcast does not cross routers, so a relay agent on the router forwards the client's request as unicast to the DHCP server.","en":"DHCP broadcast does not cross routers, so a relay agent on the router forwards the client's request as unicast to the DHCP server.","de":"DHCP broadcast does not cross routers, so a relay agent on the router forwards the client's request as unicast to the DHCP server."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/technologies/dhcp/quickstart-install-configure-dhcp-server","https://learn.microsoft.com/en-us/troubleshoot/windows-server/networking/troubleshoot-dhcp-guidance"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Implement and manage DHCP for Windows Server","objectiveId":"net-dhcp","topic":"Relay agents","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/technologies/dhcp/quickstart-install-configure-dhcp-server","https://learn.microsoft.com/en-us/troubleshoot/windows-server/networking/troubleshoot-dhcp-guidance"],"keyPoints":["Clients broadcast DHCPDISCOVER, and a router does not forward that broadcast by default.","The relay agent on the interface for the subnet sets the giaddr field and relays the exchange to the DHCP server.","After the lease is granted, the client needs a route back to the relay agent's address, which is normally handled by the default gateway."],"whyOthers":["","A DNS zone delegation controls name lookups for the subnet and has no part in address assignment.","The route for the relay's address back to the client is needed, but a specific static route on UDP port 67 is not what delivers the lease.","An additional DNS server does not influence the DHCP exchange at all."],"requirements":"The relay agent must be installed on the router interface for the subnet and be able to reach the DHCP server. UDP ports 67 and 68 must be allowed between them.","commandPath":[{"label":"List the IPv4 scopes the server serves","command":"Get-DhcpServerv4Scope"},{"label":"Show the address the client received and its gateway","command":"Get-DhcpServerv4Lease -ScopeId 10.10.10.0 -IPAddress 10.10.10.55"}],"translations":"runtime-google"},
{"id":"az802-q-346","domain":"Implement and manage on-premises and hybrid networking","text":"A host is reachable by IP address but not by name. Which step confirms whether name resolution is the actual cause?","options":["Resolve the name with Resolve-DnsName or nslookup and compare the result with the expected address","Check the host's ARP cache","Reinstall the DNS Server role on the host","Add a static route for the DNS server"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Querying the name directly and comparing the answer with the known address is what separates a name-resolution problem from a connectivity problem.","en":"Querying the name directly and comparing the answer with the known address is what separates a name-resolution problem from a connectivity problem.","de":"Querying the name directly and comparing the answer with the known address is what separates a name-resolution problem from a connectivity problem."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/dnsclient/resolve-dnsname","https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/nslookup"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Implement and manage DNS for Windows Server","objectiveId":"net-dns","topic":"Name resolution","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/dnsclient/resolve-dnsname","https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/nslookup"],"keyPoints":["A failed name query with a correct IP answer points at DNS rather than at routing or the service itself.","A successful name query with a failed connection points at the service, port, or firewall instead.","Testing from the client with the configured DNS server set explicitly removes the local cache from the picture."],"whyOthers":["","The ARP cache maps a resolved address to a MAC address on the local segment and is not consulted before the name is resolved.","Reinstalling DNS on the client is destructive and would not be attempted before proving name resolution is the cause.","A route for the DNS server addresses connectivity to the resolver, but the first step is to see what the resolver answers."],"requirements":"Include the fully qualified name in the test, since a short name may resolve through search suffixes and give a misleading result.","commandPath":[{"label":"Query a name against a specific DNS server","command":"Resolve-DnsName -Name srv01.contoso.com -Server dns01 -Type A"},{"label":"Check the same name against every configured DNS server","command":"Resolve-DnsName -Name srv01.contoso.com"}],"translations":"runtime-google"},
{"id":"az802-q-347","domain":"Implement and manage on-premises and hybrid networking","text":"After enabling DNS scavenging, a static record that must not be deleted is at risk. What protects it?","options":["The record's timestamp is reset by refreshing it, or the record is excluded from scavenging by policy","Creating a second A record with the same name","Setting the zone to primary rather than AD-integrated","Removing the record's start-of-authority record"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Scavenging removes records whose timestamp has not been refreshed, so a record survives when it is refreshed or when the zone's scavenging policy excludes it.","en":"Scavenging removes records whose timestamp has not been refreshed, so a record survives when it is refreshed or when the zone's scavenging policy excludes it.","de":"Scavenging removes records whose timestamp has not been refreshed, so a record survives when it is refreshed or when the zone's scavenging policy excludes it."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/networking/troubleshoot-dns-scavenging-issues","https://learn.microsoft.com/en-us/windows-server/networking/dns/dns-top"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Implement and manage DNS for Windows Server","objectiveId":"net-dns","topic":"Scavenging","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/networking/troubleshoot-dns-scavenging-issues","https://learn.microsoft.com/en-us/windows-server/networking/dns/dns-top"],"keyPoints":["A record is deleted only when its timestamp is older than the scavenging threshold and no-refresh intervals have elapsed.","Servers, domain controllers, and other services refresh their own records, which is why they usually survive.","A hand-created record that is never refreshed will age out, so it needs a refresh schedule or a policy exclusion."],"whyOthers":["","A duplicate A record with the same name cannot be created in the same zone and would not protect anything.","Zone type has no bearing on whether an individual record is scavenged.","The start-of-authority record marks the zone apex and is not a mechanism for protecting individual records."],"requirements":"Scavenging must be enabled on the zone, and the no-refresh interval should exceed the refresh interval so a healthy record is never considered stale.","commandPath":[{"label":"Show the scavenging settings on a zone","command":"Get-DnsServerScavenging -Name contoso.com"},{"label":"Set the no-refresh interval to fourteen days","command":"Set-DnsServerScavenging -Name contoso.com -NoRefreshInterval 14.0:00:00"}],"translations":"runtime-google"},
{"id":"az802-q-348","domain":"Implement and manage on-premises and hybrid networking","text":"What does signing a DNS zone with DNSSEC provide?","options":["Cryptographic validation that the DNS answers were issued by the zone's authorised signer","Encryption of the DNS traffic between the resolver and the client","Automatic failover to a secondary DNS server","A larger DNS cache on the resolver"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"DNSSEC signs the zone's records so a validator can detect a forged or tampered answer. It authenticates data rather than encrypting the query path.","en":"DNSSEC signs the zone's records so a validator can detect a forged or tampered answer. It authenticates data rather than encrypting the query path.","de":"DNSSEC signs the zone's records so a validator can detect a forged or tampered answer. It authenticates data rather than encrypting the query path."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/dns/sign-dnssec-zone"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Implement and manage DNS for Windows Server","objectiveId":"net-dns","topic":"DNSSEC","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/dns/sign-dnssec-zone"],"keyPoints":["Records are signed with the zone signing key, producing a signature record set that validators check.","Validation detects an answer that was altered in transit or returned by an unauthorised source.","The trust chain runs from the root through the delegation to the signed zone, which is why the parent delegation must also be updated."],"whyOthers":["","DNSSEC does not encrypt DNS traffic; that would require a transport such as DNS over TLS or DNS over HTTPS.","Failover to a secondary server is a zone-transfer behaviour and is unrelated to signing.","A signature record adds metadata to the zone but does not enlarge the resolver cache."],"requirements":"Signing requires the zone to be signed and the parent delegation updated. Resolvers must be able to validate, and validation failures look like a resolution failure to the client.","commandPath":[{"label":"Sign a zone and publish the key","command":"Add-DnsServerDnssecKey -Name contoso.com -ZoneType Forward"},{"label":"Show the signing status of a zone","command":"Get-DnsServerDnssecStatus -Name contoso.com"}],"translations":"runtime-google"},
{"id":"az802-q-349","domain":"Implement and manage on-premises and hybrid networking","text":"Why is a private DNS zone used when connecting on-premises and Azure networks that resolve the same names?","options":["The same hostname resolves to different addresses in each environment without clients changing configuration","It replaces the need for any on-premises DNS server","It makes internal names resolvable on the public internet","It removes the requirement for a VPN or private link connection"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"A private DNS zone lets one hostname resolve to the on-premises address inside the corporate network and to the Azure address from Azure-connected clients.","en":"A private DNS zone lets one hostname resolve to the on-premises address inside the corporate network and to the Azure address from Azure-connected clients.","de":"A private DNS zone lets one hostname resolve to the on-premises address inside the corporate network and to the Azure address from Azure-connected clients."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/dns/private-dns-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Implement hybrid network connectivity and security","objectiveId":"net-hybrid","topic":"Hybrid DNS","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/dns/private-dns-overview"],"keyPoints":["Hybrid workloads often use the same name in both environments, and each side must reach its own copy of the service.","A private DNS zone provides that split resolution, and on-premises resolvers forward to the Azure private zone so both sides agree.","The design still needs connectivity between the networks and a forwarding arrangement in both directions."],"whyOthers":["","Internal deployments still need an on-premises resolver, which forwards to the Azure private zone rather than disappearing.","Private zones are not resolvable from the public internet; that is what makes them private.","Connectivity between the networks is a prerequisite for using a private zone across a hybrid connection, not something the zone replaces."],"requirements":"The on-premises resolver must forward private-zone queries to the Azure DNS virtual network, and the virtual network link must be attached to the zone.","commandPath":[{"label":"List the virtual network links on a private DNS zone","command":"Get-AzPrivateDnsZone -ResourceGroupName rg-prod | Get-AzPrivateDnsVirtualNetworkLink"}],"translations":"runtime-google"},
{"id":"az802-q-350","domain":"Implement and manage on-premises and hybrid networking","text":"An application on an Azure virtual machine cannot reach a database on port 1433. What should be checked?","options":["The network security group rules and their priority on the interface","The availability set the virtual machine belongs to","The managed disk caching policy","The virtual machine scale set upgrade policy"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Network security group rules are evaluated in priority order, and a higher-priority deny or a missing allow rule is what normally blocks the flow.","en":"Network security group rules are evaluated in priority order, and a higher-priority deny or a missing allow rule is what normally blocks the flow.","de":"Network security group rules are evaluated in priority order, and a higher-priority deny or a missing allow rule is what normally blocks the flow."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Implement hybrid network connectivity and security","objectiveId":"net-hybrid","topic":"Network security groups","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview"],"keyPoints":["Rules are processed in ascending priority number, so a broad deny placed above the allow silently blocks the flow.","Rule direction and source or destination prefix matter as much as the port, because a rule can allow the wrong prefix.","Effective rules can be reviewed rather than inferred from the individual rules, which shows the combined decision."],"whyOthers":["","An availability set spreads virtual machines across fault domains and does not filter traffic.","Managed disk caching affects disk performance, not whether a TCP connection can be established.","A scale set upgrade policy governs how instances are updated, not reachability between them."],"requirements":"Default rules already deny most inbound traffic from the internet, so an explicit allow is required for any inbound path. Rule priority gaps are a common cause.","commandPath":[{"label":"List the rules on a network security group","command":"Get-AzNetworkSecurityRule -NetworkSecurityGroupId (Get-AzNetworkSecurityGroup -Name nsg-app).Id | Sort-Object Priority"},{"label":"Show the effective rule set for an interface","command":"Get-AzNetworkInterfaceSecurityRuleConfig -NetworkInterfaceName nic-app01"}],"translations":"runtime-google"},
{"id":"az802-q-351","domain":"Implement and manage on-premises and hybrid networking","text":"Which protocol and port should be allowed for a client to manage a server over HTTPS through a secure gateway?","options":["TCP 443","TCP 80","TCP 3389","UDP 53"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"HTTPS uses TCP port 443. Exposing only that port to the required sources keeps the management path encrypted without opening a remote administration port.","en":"HTTPS uses TCP port 443. Exposing only that port to the required sources keeps the management path encrypted without opening a remote administration port.","de":"HTTPS uses TCP port 443. Exposing only that port to the required sources keeps the management path encrypted without opening a remote administration port."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/nettcpip/test-netconnection","https://learn.microsoft.com/en-us/windows-server/networking/technologies/hpn/hpn-software-hardware-features"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Implement hybrid network connectivity and security","objectiveId":"net-hybrid","topic":"Secure access","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/nettcpip/test-netconnection","https://learn.microsoft.com/en-us/windows-server/networking/technologies/hpn/hpn-software-hardware-features"],"keyPoints":["TCP 443 is the standard HTTPS port, so restricting it to approved source addresses narrows the exposed surface.","TCP 80 is unencrypted and should only be used for a redirect to HTTPS where a service requires it.","Opening 3389 to the internet publishes remote administration directly and is exactly what a gateway is meant to avoid."],"whyOthers":["","TCP 80 is plain HTTP, which exposes management traffic and its credentials in clear text.","TCP 3389 is Remote Desktop; opening it to the internet removes the benefit of using a gateway at all.","UDP 53 is DNS and has nothing to do with a management session over HTTPS."],"requirements":"Scope rules to the required source ranges and protocols, and confirm the gateway certificate is trusted by the client before relying on the path.","commandPath":[{"label":"Test reachability of the management endpoint from the client","command":"Test-NetConnection -ComputerName gw.contoso.com -Port 443"}],"translations":"runtime-google"},
{"id":"az802-q-352","domain":"Implement and manage on-premises and hybrid networking","text":"A client can ping the destination IP address but cannot reach the application port. What does that combination indicate?","options":["Routing and basic connectivity work, so the problem is at the service, port, or firewall","The client has no IP configuration at all","Name resolution is the only cause","The destination is in a different subnet and unreachable"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"A successful ping proves the network path and IP configuration are usable, which narrows the fault to the listening service, the port, or a filter.","en":"A successful ping proves the network path and IP configuration are usable, which narrows the fault to the listening service, the port, or a filter.","de":"A successful ping proves the network path and IP configuration are usable, which narrows the fault to the listening service, the port, or a filter."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/nettcpip/test-netconnection","https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/tracert"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Troubleshoot name resolution and network connectivity","objectiveId":"net-troubleshoot","topic":"Path testing","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/nettcpip/test-netconnection","https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/tracert"],"keyPoints":["Ping reaching the host rules out routing and address configuration as the cause.","Test the specific port next, since ICMP success says nothing about whether that port is listening or permitted.","Compare the results from inside and outside the segment to decide whether the block is local or on the path."],"whyOthers":["","The client clearly has working IP configuration, because it sent and received a ping reply from the destination.","Name resolution was bypassed entirely by using the IP address, so it cannot be the remaining cause.","The destination answered the ping, which proves the segments are connected."],"requirements":"Some firewalls drop ICMP, so a failed ping alone is not proof of a routing problem. Confirm with a port test before concluding anything.","commandPath":[{"label":"Test whether a specific TCP port is reachable","command":"Test-NetConnection -ComputerName srv01.contoso.com -Port 443"},{"label":"Show the route the traffic would take","command":"Test-NetConnection -ComputerName srv01.contoso.com -DiagnoseRouting -InformationLevel Detailed"}],"translations":"runtime-google"},
{"id":"az802-q-353","domain":"Implement and manage on-premises and hybrid networking","text":"Which tool shows which MAC address a local IP address currently resolves to on the segment?","options":["arp","tracert","route print","netsh interface ip show dns"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"The ARP cache maps local IPv4 addresses to MAC addresses, and the arp command displays and manages that mapping.","en":"The ARP cache maps local IPv4 addresses to MAC addresses, and the arp command displays and manages that mapping.","de":"The ARP cache maps local IPv4 addresses to MAC addresses, and the arp command displays and manages that mapping."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/arp"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Troubleshoot name resolution and network connectivity","objectiveId":"net-troubleshoot","topic":"ARP and local addressing","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/arp"],"keyPoints":["A ping populates the ARP cache, so the cache is inspected after a successful local exchange.","A stale or wrong MAC address in the cache explains a failure where the IP address itself is correct.","Flushing the cache and re-pinging is a quick way to confirm whether a cached entry is the problem."],"whyOthers":["","tracert shows the routers a packet passes through and does not show MAC address mappings.","route print displays the routing table, which is about next-hop selection rather than local address resolution.","netsh interface ip show dns displays the DNS configuration, which has nothing to do with MAC addresses."],"requirements":"ARP applies to IPv4 on the local segment. IPv6 uses the neighbour discovery protocol instead, so this command is not the equivalent tool there.","commandPath":[{"label":"Show the ARP cache entries","command":"arp -a"},{"label":"Flush the ARP cache on a Windows host","command":"netsh interface ip flush"}],"translations":"runtime-google"},
{"id":"az802-q-354","domain":"Implement and manage on-premises and hybrid networking","text":"Which command shows the effective IP configuration, including the gateway and the DNS servers actually in use on a Windows server?","options":["ipconfig /all","route print","nslookup","arp -a"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"ipconfig /all reports the addresses, prefix, gateway, and the DNS server list in effect, which is the starting point for any name or reachability fault.","en":"ipconfig /all reports the addresses, prefix, gateway, and the DNS server list in effect, which is the starting point for any name or reachability fault.","de":"ipconfig /all reports the addresses, prefix, gateway, and the DNS server list in effect, which is the starting point for any name or reachability fault."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/ipconfig"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Troubleshoot name resolution and network connectivity","objectiveId":"net-troubleshoot","topic":"Local addressing","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/ipconfig"],"keyPoints":["It distinguishes a DHCP-assigned configuration from a static one, which matters when a setting seems not to have taken effect.","It shows the DNS servers in the server's own effective list, including any interface-specific ordering.","A mismatched gateway or an unexpected DNS server is often visible here before any deeper test is needed."],"whyOthers":["","route print shows the routing table rather than the interface configuration a client needs first.","nslookup queries a name and answers a resolution question, which is useful after the configuration has been confirmed.","arp -a shows local address-to-hardware mappings, which is a narrower view than the full configuration."],"requirements":"On a server with multiple network interfaces, check the interface that carries the traffic in question rather than assuming a single adapter.","commandPath":[{"label":"Show the full IP configuration","command":"ipconfig /all"},{"label":"Release and renew the DHCP lease","command":"ipconfig /release && ipconfig /renew"}],"translations":"runtime-google"},
{"id":"az802-q-355","domain":"Manage storage and file services","text":"A user is denied access to a folder despite being added to a group that has explicit Allow access on both the share and the folder. What else must be checked?","options":["Every group in the user's token, since an explicit Deny in any of them overrides the Allow","Whether the share is configured as a DFS namespace","The server's time synchronisation configuration","The size of the NTFS cluster on the volume"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"An access token accumulates every group the user belongs to, and an explicit Deny for the same right anywhere in that list takes precedence over an Allow.","en":"An access token accumulates every group the user belongs to, and an explicit Deny for the same right anywhere in that list takes precedence over an Allow.","de":"An access token accumulates every group the user belongs to, and an explicit Deny for the same right anywhere in that list takes precedence over an Allow."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/file-server/ntfs-overview","https://learn.microsoft.com/en-us/windows/win32/secauthz/how-dacls-control-access-to-an-object"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Configure file systems and NTFS permissions","objectiveId":"storage-file-systems","topic":"Permission evaluation","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/file-server/ntfs-overview","https://learn.microsoft.com/en-us/windows/win32/secauthz/how-dacls-control-access-to-an-object"],"keyPoints":["Windows evaluates access control entries in a canonical order, and explicit denies are processed before explicit allows.","The user's token includes group memberships from the domain, from the local server, and from any trusted source, so a deny can come from an unrelated group.","Effective Access in the NTFS permissions dialog and the Access-Based Enumeration report show the combined result rather than a single entry."],"whyOthers":["","DFS namespaces change the path a user browses but do not change how access control entries are evaluated.","Time synchronisation affects authentication and Kerberos tickets, not the precedence of an existing access control entry.","Cluster size affects allocation and storage behaviour and has no bearing on permission evaluation."],"requirements":"Both share permissions and NTFS permissions apply; for SMB access the more restrictive of the two results is what the user gets.","commandPath":[{"label":"Show the effective permissions for a user on a folder","command":"icacls D:\\Reports /grant"},{"label":"Read a user's security token group membership","command":"whoami /groups"}],"translations":"runtime-google"},
{"id":"az802-q-356","domain":"Manage storage and file services","text":"A user copies a file into a folder on the same volume and the copy is readable only by the user. Why?","options":["A copy creates a new file, so it inherits the destination folder's permissions rather than keeping the source ACL","A copy always strips the owner and sets the creator as owner only for folders","Files copied within a volume always become encrypted with the destination volume's key","The security descriptor is not copied unless the volume is NTFS"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Copying creates a new file, and that new file takes inheritable permissions from the destination folder, so the destination ACL decides who can read it.","en":"Copying creates a new file, and that new file takes inheritable permissions from the destination folder, so the destination ACL decides who can read it.","de":"Copying creates a new file, and that new file takes inheritable permissions from the destination folder, so the destination ACL decides who can read it."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/icacls","https://learn.microsoft.com/en-us/windows-server/storage/file-server/ntfs-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Configure file systems and NTFS permissions","objectiveId":"storage-file-systems","topic":"Permissions on copy","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/icacls","https://learn.microsoft.com/en-us/windows-server/storage/file-server/ntfs-overview"],"keyPoints":["A copy is a create operation at the destination, so it inherits from the destination container.","Moving a file within the same volume keeps the same file, so it retains its own ACL and can be denied at the destination.","Understanding the copy-versus-move difference explains many reports of permissions changing unexpectedly."],"whyOthers":["","Owner behaviour is not what limits reading to the copying user here; the inherited access control entries are.","Copying does not automatically encrypt the new file with a different key.","The security descriptor is copied with the file in a copy operation; the difference comes from inheritance at the destination, not from the file system type."],"requirements":"Use the same volume when the intent is to preserve permissions, and review the destination folder's inheritable entries before bulk copies.","commandPath":[{"label":"Show the access control list on a folder","command":"icacls D:\\Reports"},{"label":"Copy a file and retain its original permissions","command":"icacls D:\\source.doc /save D:\\acl.txt /restore D:\\source.doc"}],"translations":"runtime-google"},
{"id":"az802-q-357","domain":"Manage storage and file services","text":"Why is SMB1 disabled by default on current Windows Server versions?","options":["Its design predates modern security, and it lacks effective protections against man-in-the-middle attacks","It cannot be used with file shares larger than 2 TB","It does not support the SMB signing protocol","It is licensed separately from later SMB versions"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"SMB1 was designed without modern security protections and is exposed to interception and downgrade attacks, which is why it is disabled by default.","en":"SMB1 was designed without modern security protections and is exposed to interception and downgrade attacks, which is why it is disabled by default.","de":"SMB1 was designed without modern security protections and is exposed to interception and downgrade attacks, which is why it is disabled by default."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/file-server/troubleshoot/detect-enable-and-disable-smbv1-v2-v3","https://learn.microsoft.com/en-us/windows-server/storage/file-server/smb-security"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Configure and manage file shares and SMB","objectiveId":"storage-shares","topic":"SMB security","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/file-server/troubleshoot/detect-enable-and-disable-smbv1-v2-v3","https://learn.microsoft.com/en-us/windows-server/storage/file-server/smb-security"],"keyPoints":["SMB1 has no effective signing requirement, so an attacker on the path can observe or modify the exchange.","Modern Windows Server versions disable SMB1 unless an application explicitly requires it.","Where an old device still needs SMB1, isolate it rather than re-enabling the protocol broadly."],"whyOthers":["","SMB1 has no file size limit of that kind; the constraint described does not describe SMB1.","SMB1 predates mandatory signing, which is part of why it is insecure rather than unsupported in this way.","SMB1 ships with the operating system and needs no separate licence."],"requirements":"Check for legacy dependencies before removing the last SMB1 client or server, and prefer network isolation over leaving the protocol enabled.","commandPath":[{"label":"Show whether SMB1 is enabled on the server","command":"Get-SmbServerConfiguration | Select-Object EnableSMB1Protocol, EnableSMB2Protocol"}],"translations":"runtime-google"},
{"id":"az802-q-358","domain":"Manage storage and file services","text":"Which change most improves confidentiality for SMB file shares on a converged or higher-latency network?","options":["Enable SMB encryption so file contents are not carried in clear text on the wire","Increase the SMB keepalive interval","Switch the share to SMB1","Disable SMB signing on the file servers"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"SMB encryption encrypts the data in the SMB session, so on a shared or high-latency network the file contents are not readable on the path.","en":"SMB encryption encrypts the data in the SMB session, so on a shared or high-latency network the file contents are not readable on the path.","de":"SMB encryption encrypts the data in the SMB session, so on a shared or high-latency network the file contents are not readable on the path."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/file-server/smb-secure-traffic","https://learn.microsoft.com/en-us/windows-server/storage/file-server/smb-over-quic"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Configure and manage file shares and SMB","objectiveId":"storage-shares","topic":"SMB transport","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/file-server/smb-secure-traffic","https://learn.microsoft.com/en-us/windows-server/storage/file-server/smb-over-quic"],"keyPoints":["SMB encryption is negotiated per share, so it can be enabled only where the network path warrants it.","Encryption costs some throughput, so it is usually applied selectively rather than everywhere.","Signing proves the server's identity and protects integrity, but without encryption the contents are still readable on the path."],"whyOthers":["","A longer keepalive interval reduces how often the session is checked; it does not hide the file contents.","SMB1 is the older, less secure protocol and would move the share in the wrong direction.","Disabling signing removes integrity protection and would make interception easier, not harder."],"requirements":"All clients must support SMB 3.x for encryption. Shares that need it should be marked encrypted and verified with the Get-SmbShare output.","commandPath":[{"label":"Show which shares have encryption enabled","command":"Get-SmbShare | Select-Object Name, EncryptData"},{"label":"Require encryption on a single share","command":"Set-SmbShare -Name Confidential -EncryptData $true"}],"translations":"runtime-google"},
{"id":"az802-q-359","domain":"Manage storage and file services","text":"Which requirement does SMB Direct depend on for its performance benefit?","options":["RDMA-capable network adapters on both ends and a converged or dedicated network","A second physical network interface on the file server only","Storage Spaces Direct on the same host","A DFS namespace that points at the share"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"SMB Direct uses RDMA-capable adapters to move data with very low CPU involvement, which requires the adapters on both ends and a network that supports it.","en":"SMB Direct uses RDMA-capable adapters to move data with very low CPU involvement, which requires the adapters on both ends and a network that supports it.","de":"SMB Direct uses RDMA-capable adapters to move data with very low CPU involvement, which requires the adapters on both ends and a network that supports it."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/file-server/smb-direct","https://learn.microsoft.com/en-us/windows-server/storage/file-server/smb-over-quic"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Configure and manage file shares and SMB","objectiveId":"storage-shares","topic":"SMB Direct","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/file-server/smb-direct","https://learn.microsoft.com/en-us/windows-server/storage/file-server/smb-over-quic"],"keyPoints":["RDMA lets the adapter transfer data directly between NICs with far less CPU involvement than a conventional socket path.","Both the client and the server need RDMA-capable adapters, and they must be on a converged or dedicated network segment.","The result is high throughput with low CPU and low latency, which suits large file sets."],"whyOthers":["","A second interface on the server alone does not provide the RDMA capability that SMB Direct relies on.","Storage Spaces Direct concerns local storage for clustering and is unrelated to network transport.","A DFS namespace changes how a share is presented, not how the data is transported."],"requirements":"Requires SMB Direct-compatible RDMA adapters, typically with an underlying lossless network such as RDMA over Converged Ethernet or InfiniBand.","commandPath":[{"label":"Confirm SMB Direct is enabled on the file server","command":"Get-SmbServerConfiguration | Select-Object EnableRDMA"},{"label":"Show RDMA-capable network adapters","command":"Get-NetAdapter | Where-Object NdisPhysicalMedium -eq 132"}],"translations":"runtime-google"},
{"id":"az802-q-360","domain":"Manage storage and file services","text":"What does a DFS namespace provide to a user?","options":["A single logical path that combines shared folders from multiple servers","A replica of the file contents between two namespace servers","A quota that applies to every shared folder it lists","A backup of the namespace configuration to a separate server"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"A DFS namespace maps one path to targets on multiple servers, so users see one logical location while the underlying folders stay where they are.","en":"A DFS namespace maps one path to targets on multiple servers, so users see one logical location while the underlying folders stay where they are.","de":"A DFS namespace maps one path to targets on multiple servers, so users see one logical location while the underlying folders stay where they are."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/dfs-namespaces/dfs-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Configure DFS namespaces and replication","objectiveId":"storage-dfs","topic":"DFS namespaces","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/dfs-namespaces/dfs-overview"],"keyPoints":["Namespace targets are the real shared folders, and the namespace is the map that clients use instead of the server paths.","Because the path is stable, shared folders can be moved to another server without changing how users reach them.","Site awareness in a namespace lets a client reach the closest copy rather than crossing the WAN."],"whyOthers":["","Content replication between namespace servers is DFS Replication, which is a separate feature.","Quotas are a File Server Resource Manager feature and are not provided by the namespace.","Namespace configuration backup is an administrative task and is not what the namespace itself supplies."],"requirements":"A namespace server is itself a file server. Clients access the namespace path, so permissions on the namespace share must be compatible with those on the targets.","commandPath":[{"label":"List the DFS namespaces and their targets","command":"Get-DfsNamespace | Get-DfsTarget -TargetType Folder | Select-Object Path, TargetPath"}],"translations":"runtime-google"},
{"id":"az802-q-361","domain":"Manage storage and file services","text":"DFS Replication between two branch offices runs across an expensive WAN link and keeps falling behind. Which control helps most?","options":["A replication schedule that keeps replication within the link's available hours and bandwidth limits","Raising the priority of the DFS Replication service","Converting both file servers to Storage Spaces Direct","Enabling continuous replication on both servers"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Replication bandwidth limits and schedules bound how much traffic is attempted, so scheduling into the link's cheap hours keeps replication from saturating the WAN.","en":"Replication bandwidth limits and schedules bound how much traffic is attempted, so scheduling into the link's cheap hours keeps replication from saturating the WAN.","de":"Replication bandwidth limits and schedules bound how much traffic is attempted, so scheduling into the link's cheap hours keeps replication from saturating the WAN."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/dfs-replication/dfsr-faq","https://learn.microsoft.com/en-us/windows-server/storage/dfs-replication/dfs-replication-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Configure DFS namespaces and replication","objectiveId":"storage-dfs","topic":"DFS Replication scheduling","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/dfs-replication/dfsr-faq","https://learn.microsoft.com/en-us/windows-server/storage/dfs-replication/dfs-replication-overview"],"keyPoints":["Bandwidth limits throttle replication so it never consumes the whole link, which protects latency for users.","A schedule confines replication to agreed hours, which is the usual arrangement on a metered or contended WAN.","Stale thresholds and minimum file sizes further reduce the traffic attempted, which helps when many small files change."],"whyOthers":["","Service priority affects local resource contention and has no effect on how much traffic crosses the WAN.","Storage Spaces Direct pools local storage and is unrelated to replication between file servers.","Continuous replication removes the scheduling control entirely, so it would make the contention worse rather than better."],"requirements":"Schedules must account for the maximum bandwidth available in that window. Monitor the replication backlog so a falling-behind condition is visible before users notice.","commandPath":[{"label":"Show replication status and backlog for a replication group","command":"Get-DfsReplicatedFolder | Get-DfsReplicatedFolderInfo | Select-Object ReplicationGroupName, ReplicationState"},{"label":"Show the bandwidth limits configured for a replication group","command":"Set-DfsReplicationGroup -TargetName \\Corp\\HR -BandwidthLimit (New-DfsReplicationBandwidthLimit -BytesPerSecond 20971520)"}],"translations":"runtime-google"},
{"id":"az802-q-362","domain":"Manage storage and file services","text":"What does a File Server Resource Manager quota limit?","options":["The disk space a user or volume may consume, enforced independently of NTFS permissions","The number of file system objects on a volume","The number of users who may connect to a file share","The rate at which a server writes to its storage"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"A quota caps the space a principal or volume can use. It is enforced independently of the ACLs that decide who may read and write a folder.","en":"A quota caps the space a principal or volume can use. It is enforced independently of the ACLs that decide who may read and write a folder.","de":"A quota caps the space a principal or volume can use. It is enforced independently of the ACLs that decide who may read and write a folder."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/fsrm/fsrm-overview","https://learn.microsoft.com/en-us/powershell/module/storage/get-volume"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Manage file-server resource manager and deduplication","objectiveId":"storage-fsrm","topic":"Quotas","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/fsrm/fsrm-overview","https://learn.microsoft.com/en-us/powershell/module/storage/get-volume"],"keyPoints":["Quota targets can be users, groups, or volumes, and each target has a hard limit.","Because quota is not an access control entry, a user with full permission can still be stopped by the quota.","Quota usage is reported separately from permissions, so a write failure may be a quota rather than an ACL."],"whyOthers":["","The number of objects is a count limit, not what a storage quota expresses.","Quota has no role in limiting how many users may connect to a share.","Quota limits space consumed, not write throughput."],"requirements":"Quota must be installed on the volume, and NTFS is required where volume quotas are used. Soft notification thresholds are useful for alerting before the hard limit is hit.","commandPath":[{"label":"List the quotas configured on a server","command":"Get-FsrmQuota -Volume C: | Select-Object Path, Limit, Usage"}],"translations":"runtime-google"},
{"id":"az802-q-363","domain":"Manage storage and file services","text":"Which File Server Resource Manager report shows which file types are consuming the most space on a volume?","options":["Files by File Group","Files by Size on Disk","Storage Reports for Quota","Duplicate File Detection"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Files by File Group reports usage grouped by the file groups defined for screening, which reveals which categories of content dominate a volume.","en":"Files by File Group reports usage grouped by the file groups defined for screening, which reveals which categories of content dominate a volume.","de":"Files by File Group reports usage grouped by the file groups defined for screening, which reveals which categories of content dominate a volume."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/fsrm/storage-reports-management","https://learn.microsoft.com/en-us/windows-server/storage/fsrm/fsrm-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Manage file-server resource manager and deduplication","objectiveId":"storage-fsrm","topic":"Reporting","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/fsrm/storage-reports-management","https://learn.microsoft.com/en-us/windows-server/storage/fsrm/fsrm-overview"],"keyPoints":["Reports run on demand or on a schedule and can be emailed or written to a folder.","Files by File Group is the natural companion to file screening, because file groups define the categories both features use.","Large Files and Largest Directories reports answer different questions about space consumption."],"whyOthers":["","Files by Size on Disk reports on the largest files, which answers a different question about what fills a volume.","Storage Reports for Quota reports quota usage per quota target rather than usage by file category.","Duplicate File Detection finds repeated content and does not summarise usage by type."],"requirements":"Reports need storage reports to be enabled and scheduled to run. Large volumes may need the report scope limited to keep the scan off peak hours.","commandPath":[{"label":"Start a report that lists storage usage by file group","command":"Get-FsrmStorageReport -InputFormat XML -Path C:\\Reports\\filegroups.xml"}],"translations":"runtime-google"},
{"id":"az802-q-364","domain":"Manage storage and file services","text":"A BitLocker-protected server must be recovered after its volume fails. Where should the recovery key have been stored?","options":["In Active Directory or in a separate, access-controlled location such as a key escrow system","On the encrypted volume itself","In the System event log on the same server","In the host's local Administrators group description"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"The recovery key must live outside the encrypted volume, and escrowing it to a protected location such as Active Directory is what makes recovery possible after a disk failure.","en":"The recovery key must live outside the encrypted volume, and escrowing it to a protected location such as Active Directory is what makes recovery possible after a disk failure.","de":"The recovery key must live outside the encrypted volume, and escrowing it to a protected location such as Active Directory is what makes recovery possible after a disk failure."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows/security/operating-system-security/data-protection/bitlocker/bitlocker-recovery-guide-plan","https://learn.microsoft.com/en-us/windows/security/operating-system-security/data-protection/bitlocker/"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Manage volume encryption with BitLocker","objectiveId":"storage-bitlocker","topic":"Recovery keys","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows/security/operating-system-security/data-protection/bitlocker/bitlocker-recovery-guide-plan","https://learn.microsoft.com/en-us/windows/security/operating-system-security/data-protection/bitlocker/"],"keyPoints":["The recovery key is generated when the volume is encrypted and must be escrowed or recorded.","Escrowing to a computer object in Active Directory or to a key management service keeps it recoverable without storing it on the encrypted disk.","A volume protected by the TPM still needs the recovery key for situations where the TPM state cannot be released."],"whyOthers":["","A key stored on the encrypted volume is unavailable when the volume cannot be read, which defeats the purpose.","The System event log lives on the same operating system and does not survive a failure of the protected volume.","A group description field is not a secret store and offers no controlled recovery path."],"requirements":"Escrow requires appropriate permissions in the domain. The recovery key must also be protected with the same care as other privileged credentials.","commandPath":[{"label":"Show the volume protection status and escrowed key status","command":"Get-BitLockerVolume | Select-Object MountPoint, VolumeStatus, ProtectionStatus, KeyEscrowed"},{"label":"Escrow the recovery key to Active Directory","command":"Add-BitLockerKeyEscrow -CimSession (Get-CimSession -ComputerName srv01)"}],"translations":"runtime-google"},
{"id":"az802-q-365","domain":"Manage storage and file services","text":"Which side of an iSCSI connection terminates and presents LUNs to initiators?","options":["The iSCSI target","The iSCSI initiator","The Storage Spaces pool","The ReFS volume on the array"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"The target owns the storage and exposes logical units, while the initiator connects to the target and mounts those logical units as local storage.","en":"The target owns the storage and exposes logical units, while the initiator connects to the target and mounts those logical units as local storage.","de":"The target owns the storage and exposes logical units, while the initiator connects to the target and mounts those logical units as local storage."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/iscsi/iscsi-target-server"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Configure storage replication, QoS, and iSCSI","objectiveId":"storage-block","topic":"iSCSI","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/iscsi/iscsi-target-server"],"keyPoints":["The target presents one or more LUNs, each with its own access control list.","The initiator is the host that connects to the target and connects the LUN as a volume.","Target access control is enforced per initiator IQN or per address, which is what restricts who may connect."],"whyOthers":["","The initiator is the connecting host and consumes the logical units rather than providing them.","Storage Spaces pools local disks on one host and is a different storage abstraction.","A ReFS volume is a file system on a volume and has no role in deciding which side presents LUNs."],"requirements":"The target requires CHAP for authentication on supported configurations. iSCSI traffic should be isolated from general network traffic where possible.","commandPath":[{"label":"List the iSCSI targets on the array","command":"Get-IscsiTarget | Select-Object TargetFriendlyName, IsReadOnly"},{"label":"Show the connected iSCSI sessions on the initiator","command":"Get-IscsiSession"}],"translations":"runtime-google"},
{"id":"az802-q-366","domain":"Manage storage and file services","text":"What does Storage Replica provide between two volumes?","options":["Block-level replication of a volume to another volume for disaster recovery","File-level deduplication between two file servers","A clustered file system that spans two locations synchronously","A copy of a volume to tape for archival"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Storage Replica replicates blocks from a source volume to a destination volume, which can be on the same host or across hosts, in synchronous or asynchronous mode.","en":"Storage Replica replicates blocks from a source volume to a destination volume, which can be on the same host or across hosts, in synchronous or asynchronous mode.","de":"Storage Replica replicates blocks from a source volume to a destination volume, which can be on the same host or across hosts, in synchronous or asynchronous mode."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/storage-replica/storage-replica-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Configure storage replication, QoS, and iSCSI","objectiveId":"storage-block","topic":"Storage Replica","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/storage/storage-replica/storage-replica-overview"],"keyPoints":["Replication is at the block level, so the destination mirrors the source volume rather than a file selection.","Synchronous mode requires the destination to acknowledge writes, which protects data but adds latency.","Asynchronous mode accepts the loss of recent writes on a failure, in exchange for avoiding the latency of synchronous replication."],"whyOthers":["","Deduplication reduces space within a set of files and does not replicate a volume between machines.","Storage Replica is not a clustered file system; the replication relationship is configured independently of any cluster.","Archival to tape is a backup function and does not use Storage Replica."],"requirements":"Source and destination volumes must be on supported media with matching or compatible configurations. File-level data such as permissions and alternate data streams is replicated separately where relevant.","commandPath":[{"label":"Show the Storage Replica groups and their health","command":"Get-SRGroup | Select-Object Name, ReplicationState, HealthStatus"},{"label":"Show the per-volume replication status","command":"Get-SRVolume | Select-Object Name, ReplicationState, HealthStatus"}],"translations":"runtime-google"},
{"id":"az802-q-367","domain":"Manage storage and file services","text":"Which access method allows users to keep existing permissions and identities when accessing an Azure file share?","options":["Identity-based authentication using Microsoft Entra ID","The storage account access key","A read-only public blob container","An anonymous SMB share"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Identity-based authentication maps directory and file permissions to directory principals, so existing access models continue to work.","en":"Identity-based authentication maps directory and file permissions to directory principals, so existing access models continue to work.","de":"Identity-based authentication maps directory and file permissions to directory principals, so existing access models continue to work."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/storage/files/storage-files-introduction"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Manage Azure file services","objectiveId":"storage-azure","topic":"Azure Files","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/storage/files/storage-files-introduction"],"keyPoints":["Identity-based access uses SMB with Microsoft Entra authentication and supports access control lists on directories and files.","Users then authorise with the identity they already have rather than with a shared key.","Storage account keys grant broad access to the account, so they are a coarser control that is harder to attribute."],"whyOthers":["","An access key grants broad account-level access and gives no per-user attribution, which is the coarser alternative.","A public container is for blob data and is not an SMB file share with NTFS-style permissions.","An anonymous share would expose file contents to unauthenticated users, which is not a supported pattern for a file share."],"requirements":"Identity-based access needs Microsoft Entra domain services or a hybrid identity setup so that directory principals can be resolved.","commandPath":[{"label":"Show the identity configuration of an Azure file share","command":"az storage share-rm show -g rg-prod -n share1 --query identityBasedAuthentication"}],"translations":"runtime-google"},
{"id":"az802-q-368","domain":"Secure Windows Server infrastructure","text":"Why does Windows Defender Firewall keep separate profile settings for domain, private, and public networks?","options":["A server needs different trust levels on different networks, so each profile can carry its own rule set","Only one profile can be active per server, and the others are placeholders","The private profile is for servers that are not domain joined","The profiles exist so that rules can be applied per user account"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"The profile reflects the trust of the network the server is attached to, so the same server can enforce different rules on a managed domain network than on an untrusted one.","en":"The profile reflects the trust of the network the server is attached to, so the same server can enforce different rules on a managed domain network than on an untrusted one.","de":"The profile reflects the trust of the network the server is attached to, so the same server can enforce different rules on a managed domain network than on an untrusted one."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows/security/operating-system-security/network-security/windows-firewall/","https://learn.microsoft.com/en-us/windows/security/operating-system-security/network-security/windows-firewall/rules"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Configure Windows Defender Firewall and IPsec","objectiveId":"sec-firewall","topic":"Firewall profiles","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows/security/operating-system-security/network-security/windows-firewall/","https://learn.microsoft.com/en-us/windows/security/operating-system-security/network-security/windows-firewall/rules"],"keyPoints":["The domain profile is applied when the server is domain joined on a managed network.","The private profile applies to trusted networks that are not domain joined, and the public profile is the most restrictive default.","Rules created against a profile only apply while that profile is active, which is why a rule can appear not to take effect after a network change."],"whyOthers":["","Only one profile is active at a time, but the others are real configurations rather than placeholders.","The private profile is for trusted non-domain networks, not for servers that are not domain joined in general.","Windows Firewall rules are not applied per user account; they apply to profiles, programs, ports, and addresses."],"requirements":"Confirm which profile is active before concluding a rule is broken. Group Policy for Windows Firewall can override local settings, which is another reason a local rule may appear ineffective.","commandPath":[{"label":"Show the active profile and firewall state","command":"Get-NetFirewallProfile | Select-Object Name, Enabled, DefaultInboundAction"},{"label":"Show the current network profile","command":"Get-NetConnectionProfile | Select-Object Name, InterfaceAlias, NetworkCategory"}],"translations":"runtime-google"},
{"id":"az802-q-369","domain":"Secure Windows Server infrastructure","text":"Which combination keeps a management port exposed to as little as possible?","options":["Restrict the inbound rule to the required remote addresses and the required profile","Allow the port from any remote address on all profiles","Create one rule per server with the same broad source range","Disable the firewall profile and rely on the edge firewall"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"An inbound rule should name the specific source addresses that need it, and the profile it applies to, so the exposure is bounded on both dimensions.","en":"An inbound rule should name the specific source addresses that need it, and the profile it applies to, so the exposure is bounded on both dimensions.","de":"An inbound rule should name the specific source addresses that need it, and the profile it applies to, so the exposure is bounded on both dimensions."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows/security/operating-system-security/network-security/windows-firewall/rules","https://learn.microsoft.com/en-us/windows/security/operating-system-security/network-security/windows-firewall/configure-with-command-line"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Configure Windows Defender Firewall and IPsec","objectiveId":"sec-firewall","topic":"Firewall scope","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows/security/operating-system-security/network-security/windows-firewall/rules","https://learn.microsoft.com/en-us/windows/security/operating-system-security/network-security/windows-firewall/configure-with-command-line"],"keyPoints":["Scope is set by remote address, local address, port, and profile, and each narrows the exposure.","A rule created in the public profile only applies when that profile is active, which limits the risk of a broad rule.","Group Policy firewall settings take precedence over local settings, so the effective configuration must be reviewed rather than assumed."],"whyOthers":["","Allowing any source on all profiles publishes the port to every network the server ever joins.","Repeating the same broad rule per server widens exposure rather than narrowing it and multiplies the maintenance.","Disabling the firewall leaves the host with no host-level filtering, which is not an acceptable substitute for an edge firewall."],"requirements":"Review effective rules with Get-NetFirewallRule rather than only the local ones, because policy may define the real configuration.","commandPath":[{"label":"Show the inbound allow rules and their remote addresses","command":"Get-NetFirewallRule -Direction Inbound -Enabled True | Get-NetFirewallPortFilter | Select-Object Protocol, LocalPort"}],"translations":"runtime-google"},
{"id":"az802-q-370","domain":"Secure Windows Server infrastructure","text":"What is the effect of adding a user to the Protected Users group on a domain controller?","options":["The user's authentication is restricted to Kerberos and NTLM is refused, which blocks NTLM relay-style attacks","The user can only sign in through a smart card","The user's password must include a symbol","The user is prevented from using PowerShell Remoting"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Protected Users requires Kerberos for authentication and refuses NTLM, which removes the weaker protocol that relay attacks depend on.","en":"Protected Users requires Kerberos for authentication and refuses NTLM, which removes the weaker protocol that relay attacks depend on.","de":"Protected Users requires Kerberos for authentication and refuses NTLM, which removes the weaker protocol that relay attacks depend on."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/security/credentials-protection-and-management/protected-users-security-group","https://learn.microsoft.com/en-us/windows-server/security/credentials-protection-and-management/authentication-policies-and-authentication-policy-silos"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Manage credential protection","objectiveId":"sec-credentials","topic":"Credential protection","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/security/credentials-protection-and-management/protected-users-security-group","https://learn.microsoft.com/en-us/windows-server/security/credentials-protection-and-management/authentication-policies-and-authentication-policy-silos"],"keyPoints":["NTLM is refused for members of Protected Users, so authentication must complete with Kerberos.","The restriction is applied by domain controllers through authentication policy, so it applies wherever the account is used.","It is intended for privileged accounts that should never fall back to NTLM."],"whyOthers":["","Smart card requirement is a separate control and is not what Protected Users enforces.","Password composition is governed by password policy, not by group membership.","PowerShell Remoting still works over Kerberos; the restriction concerns the authentication protocol, not remote management."],"requirements":"Clients must be able to authenticate with Kerberos, so the account's SPN registration and time must be correct, or the restriction will cause a logon failure rather than a security gain.","commandPath":[{"label":"List the members of the Protected Users group","command":"Get-ADGroupMember -Identity 'CN=Protected Users,CN=Users,DC=contoso,DC=com'"},{"label":"Show the authentication policy silo settings","command":"Get-ADAuthenticationPolicySilo -Identity silo1 | Select-Object Name, AuthenticationPolicy"}],"translations":"runtime-google"},
{"id":"az802-q-371","domain":"Secure Windows Server infrastructure","text":"Which approach best follows the tier model for an administrator who routinely works on member servers?","options":["Keep a separate privileged identity for the administrative task instead of using a day-to-day account","Use one account for both daily work and administration to keep the sign-in simple","Grant the day-to-day account local administrator rights on member servers","Store the privileged password in a file on the member server"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"The tier model keeps the identities that administer infrastructure separate from the identities people use daily, so a compromise of one does not yield the other.","en":"The tier model keeps the identities that administer infrastructure separate from the identities people use daily, so a compromise of one does not yield the other.","de":"The tier model keeps the identities that administer infrastructure separate from the identities people use daily, so a compromise of one does not yield the other."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/tier-model","https://learn.microsoft.com/en-us/security/privileged-access-workstations/overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Manage credential protection","objectiveId":"sec-credentials","topic":"Privileged accounts","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/tier-model","https://learn.microsoft.com/en-us/security/privileged-access-workstations/overview"],"keyPoints":["Tier 0 identities administer the forest and domain controllers; tier 1 identities administer servers and applications; user identities work with business applications.","Separating the tiers limits how far a single compromised credential can reach.","Privileged administrative workstations make it harder to use an administrative identity for ordinary browsing or mail."],"whyOthers":["","Using one identity for daily work and administration removes the separation that makes the tier model effective.","Granting the daily account local administrator rights gives day-to-day activity the same reach as an administrative one.","A password stored in a file on the managed server is exposed to anyone who can read it there."],"requirements":"Tiering depends on logging on to tier 0 systems only from privileged administrative workstations, otherwise the separation is nominal.","commandPath":[{"label":"Read the tier assignments from the Tier Model Documentation workbook","command":"Get-ADGroup -Identity 'Tier 0 Admins' | Get-ADGroupMember"}],"translations":"runtime-google"},
{"id":"az802-q-372","domain":"Secure Windows Server infrastructure","text":"Why is Windows LAPS preferable to a shared local administrator password on domain-joined servers?","options":["It manages and backs up a unique local administrator password for each device, so a captured credential does not reuse elsewhere","It stores the password in the local registry for faster authentication","It disables the local administrator account entirely","It allows all domain administrators to sign in without a password"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Local administrator accounts often share the same password across many devices, so Windows LAPS closes that gap by rotating each device's password, storing it securely, and letting authorised administrators retrieve it when needed.","en":"Local administrator accounts often share the same password across many devices, so Windows LAPS closes that gap by rotating each device's password, storing it securely, and letting authorised administrators retrieve it when needed.","de":"Local administrator accounts often share the same password across many devices, so Windows LAPS closes that gap by rotating each device's password, storing it securely, and letting authorised administrators retrieve it when needed."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/laps/laps-overview","https://learn.microsoft.com/en-us/windows-server/security/credentials-protection-and-management/protected-users-security-group"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Manage credential protection","objectiveId":"sec-credentials","topic":"Local administrator password","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/laps/laps-overview","https://learn.microsoft.com/en-us/windows-server/security/credentials-protection-and-management/protected-users-security-group"],"keyPoints":["Local administrator accounts often share the same password across many devices, which lets bad actors move laterally, so Windows LAPS closes that gap.","It rotates each device's local administrator password, stores it securely, and lets authorised administrators retrieve it to sign in to or recover a device.","It can also manage the Directory Services Restore Mode account password on a Windows Server Active Directory domain controller."],"whyOthers":["","The managed password is stored centrally rather than in the local registry, which is one of the reasons it is not readable by anyone who reaches the machine.","Windows LAPS manages the password of the local administrator account rather than disabling it.","No account is allowed to authenticate without a password; LAPS strengthens authentication rather than removing it."],"requirements":"Windows LAPS is available on supported Windows and Windows Server versions and differs from the legacy Microsoft LAPS product in where the password is stored and how it is managed.","commandPath":[{"label":"Reset a device's managed local administrator password","command":"Reset-LapsPassword -ComputerName srv01"},{"label":"Show the LAPS policy in force","command":"Get-LapsPolicy | Select-Object AdministratorPasswordExpirationPolicyEnabled"}],"translations":"runtime-google"},
{"id":"az802-q-373","domain":"Secure Windows Server infrastructure","text":"How does application control differ from relying on antivirus alone to decide what may run on a server?","options":["It changes Windows so code runs only if policy says so, rather than running unless antivirus predicts it is bad","It scans files for known virus signatures at higher speed","It encrypts the files that antivirus would have quarantined","It restricts which users may download files from the internet"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Application control changes Windows from a place where all code runs unless an antivirus solution confidently predicts it is bad, to one where code runs only if policy says so.","en":"Application control changes Windows from a place where all code runs unless an antivirus solution confidently predicts it is bad, to one where code runs only if policy says so.","de":"Application control changes Windows from a place where all code runs unless an antivirus solution confidently predicts it is bad, to one where code runs only if policy says so."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows/security/application-security/application-control/app-control-for-business/appcontrol"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Configure threat protection features","objectiveId":"sec-threat-protection","topic":"Application control","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows/security/application-security/application-control/app-control-for-business/appcontrol"],"keyPoints":["When a user runs a process, that process has the same access to data as the user, so relying only on antivirus gives inadequate defence against new attacks.","Application control inverts that default: code runs only if the policy says so, so unknown and unapproved code has no path to execute.","Policies can be deployed in an audit-only mode first, which measures what would have been blocked before enforcement begins."],"whyOthers":["","Signature scanning at higher speed is still a detection model, which is what application control replaces rather than accelerates.","Application control does not encrypt files; BitLocker covers encryption at rest.","Restricting downloads is a browser or network control and is not what an application control policy expresses."],"requirements":"Some capabilities are available only on specific Windows versions, so a rollout should be checked against feature availability before it is enforced.","commandPath":[{"label":"Show the current AppLocker policy mode","command":"Get-AppLockerPolicy -Effective | Select-Object Name, IsEnforced, Mode"}],"translations":"runtime-google"},
{"id":"az802-q-374","domain":"Secure Windows Server infrastructure","text":"What is the effect of enabling a system mitigation such as block low integrity image loads or force randomization for Windows images?","options":["It makes specific exploitation techniques fail even when an attacker has run code on the host","It scans files for known virus signatures","It restricts which users may sign in to the server","It encrypts memory pages at rest on disk"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"System mitigations change the process environment so that particular exploit techniques no longer work, which is defence in depth after code execution has already occurred.","en":"System mitigations change the process environment so that particular exploit techniques no longer work, which is defence in depth after code execution has already occurred.","de":"System mitigations change the process environment so that particular exploit techniques no longer work, which is defence in depth after code execution has already occurred."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/defender-endpoint/exploit-protection"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Configure threat protection features","objectiveId":"sec-threat-protection","topic":"Exploit protection","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/defender-endpoint/exploit-protection"],"keyPoints":["Mitigations are configured per process, so they can be applied broadly with audit mode or to specific applications.","They target techniques such as untrusted image loads, code injection, and predictable layout rather than detecting malware.","Some mitigations require compatible hardware such as Control Flow Guard and can affect legacy applications."],"whyOthers":["","Signature scanning for viruses is antivirus behaviour, which is a different control.","Restricting who may sign in is an authentication or access control measure, not an exploit mitigation.","Memory encryption at rest is handled by BitLocker and is unrelated to how code is prevented from exploiting the process environment."],"requirements":"Deploy in audit mode first to discover applications that depend on a disabled technique, since an incompatible mitigation can stop a workload.","commandPath":[{"label":"Show the exploit protection configuration on a server","command":"Get-ProcessMitigation -System"}],"translations":"runtime-google"},
{"id":"az802-q-375","domain":"Secure Windows Server infrastructure","text":"Which Microsoft Defender capability blocks a user from downloading a file that is poorly reputed, without waiting for it to be scanned?","options":["Microsoft Defender SmartScreen download reputation","Windows Defender Antivirus real-time protection","Credential Guard","LAPS password rotation"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"SmartScreen evaluates download and application reputation, and download reputation blocks a known-bad download before it is saved.","en":"SmartScreen evaluates download and application reputation, and download reputation blocks a known-bad download before it is saved.","de":"SmartScreen evaluates download and application reputation, and download reputation blocks a known-bad download before it is saved."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows/security/operating-system-security/virus-and-threat-protection/microsoft-defender-smartscreen/"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Configure threat protection features","objectiveId":"sec-threat-protection","topic":"Browser reputation","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows/security/operating-system-security/virus-and-threat-protection/microsoft-defender-smartscreen/"],"keyPoints":["SmartScreen uses reputation data for downloads, applications, and files that are opened.","The check happens before the file runs, so a download from a low-reputation source can be stopped immediately.","It complements antivirus, which inspects files that are already present."],"whyOthers":["","Antivirus scans files after they are present; SmartScreen reputation can stop the download first.","Credential Guard protects credentials in memory and has nothing to do with downloads.","LAPS manages local administrator password uniqueness and rotation, not downloads."],"requirements":"SmartScreen settings can be enforced through Group Policy so servers do not rely on user opt-in. Reputation lookups require the machine to be able to reach the service.","commandPath":[{"label":"Show the SmartScreen policy settings applied to the server","command":"Get-ItemProperty 'HKLM:\\SOFTWARE\\Policies\\Microsoft\\Microsoft Defender\\SmartScreen' | Select-Object *"}],"translations":"runtime-google"},
{"id":"az802-q-376","domain":"Secure Windows Server infrastructure","text":"What signal does Microsoft Defender for Identity use that other security tools on a server usually cannot see?","options":["Directory and authentication activity such as suspicious credential access or lateral movement across the domain","Local CPU utilisation on the domain controller","Antivirus scan results from a member server","The contents of the local registry hive"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Defender for Identity monitors Active Directory for attacks that use legitimate directory protocols, which is where identity-based attacks operate.","en":"Defender for Identity monitors Active Directory for attacks that use legitimate directory protocols, which is where identity-based attacks operate.","de":"Defender for Identity monitors Active Directory for attacks that use legitimate directory protocols, which is where identity-based attacks operate."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/defender-for-identity/what-is","https://learn.microsoft.com/en-us/azure/defender-for-cloud/defender-for-servers-introduction"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Manage identity threats with Defender for Identity","objectiveId":"sec-identity-threat","topic":"Identity threat detection","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/defender-for-identity/what-is","https://learn.microsoft.com/en-us/azure/defender-for-cloud/defender-for-servers-introduction"],"keyPoints":["It evaluates authentication and directory activity, such as unusual protocol use, reconnaissance queries, and password attacks.","That activity is spread across many servers, so it is visible to a service that sees the directory rather than to a host-based agent alone.","Detection results can feed automated response so a compromised session can be ended quickly."],"whyOthers":["","Local CPU utilisation is a host performance signal and says nothing about identity attacks.","Antivirus results describe one host, while identity attacks are defined by their use of directory services across the estate.","The local registry is a configuration store and does not record authentication behaviour."],"requirements":"Defender for Identity requires access to the directory's security events and a connection to its cloud service. It complements rather than replaces on-host protection.","commandPath":[{"label":"Confirm the on-premises requirements are met for the sensor","command":"Get-MdiDiag | Select-Object Test, Result"}],"translations":"runtime-google"},
{"id":"az802-q-377","domain":"Secure Windows Server infrastructure","text":"An investigation needs to know which accounts and groups changed. Which audit policy subcategory must be enabled on the domain controllers?","options":["Audit User Account Management and the related account management subcategories","Audit Detailed File Share only","Audit Other System Events","Audit Application Generated only"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Account management auditing is what records user, computer, and group changes. File share and system auditing do not record directory object changes.","en":"Account management auditing is what records user, computer, and group changes. File share and system auditing do not record directory object changes.","de":"Account management auditing is what records user, computer, and group changes. File share and system auditing do not record directory object changes."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/advanced-audit-policy-configuration","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/audit-policy-recommendations"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Audit and monitor security events","objectiveId":"sec-audit","topic":"Audit scope","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/advanced-audit-policy-configuration","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/audit-policy-recommendations"],"keyPoints":["The account management category covers user account management, computer account management, and security group management.","Without those subcategories enabled, the Security log will not contain the directory changes the investigation needs.","Advanced audit policies give finer control than the legacy basic policy, so the two should not be mixed."],"whyOthers":["","Detailed File Share auditing records access to shared folders and contains no user or group creation data.","Other System Events records security-relevant system actions and does not record directory object changes.","Application Generated events record actions taken by applications rather than changes to directory accounts and groups."],"requirements":"Audit policy is set through Group Policy on the domain controllers. Enable Force audit policy subcategory settings to override category-level settings, and verify the subcategory state on the controller itself.","commandPath":[{"label":"Show the effective system audit policy","command":"auditpol /get /category:* /r"},{"label":"Enable account management auditing","command":"auditpol /set /category:\"Account Management\" /success:enable /failure:enable"}],"translations":"runtime-google"},
{"id":"az802-q-378","domain":"Secure Windows Server infrastructure","text":"Which capability protects credentials stored in memory so they cannot be extracted even if code runs in the server's session?","options":["Credential Guard","Windows Defender Firewall","LAPS","Storage Replica"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Credential Guard uses virtualization-based security so that secrets are isolated into a separate compartment that ordinary code in the session cannot read.","en":"Credential Guard uses virtualization-based security so that secrets are isolated into a separate compartment that ordinary code in the session cannot read.","de":"Credential Guard uses virtualization-based security so that secrets are isolated into a separate compartment that ordinary code in the session cannot read."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows/security/identity-protection/credential-guard/","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/best-practices-for-securing-active-directory"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Harden Windows Server with security baselines","objectiveId":"sec-baselines","topic":"Exploit protection","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows/security/identity-protection/credential-guard/","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/best-practices-for-securing-active-directory"],"keyPoints":["Credential Guard relies on virtualization-based security, so the secrets exist in a protected compartment rather than in ordinary process memory.","With the hardware present and the feature enabled, credential theft techniques find nothing usable.","It is configured through Group Policy together with virtualization-based security, so both must be in place."],"whyOthers":["","Windows Defender Firewall filters network traffic and has no effect on credential theft from process memory.","LAPS makes local administrator passwords unique per machine, which limits reuse but does not protect credentials while in use.","Storage Replica replicates volumes and has no relationship to credential protection in memory."],"requirements":"Requires a compatible processor with virtualization-based security, firmware support, and UEFI with the required secure boot configuration. Without the hardware the policy cannot deliver the protection.","commandPath":[{"label":"Confirm Credential Guard is running on the server","command":"Get-CimInstance -ClassName Win32_DeviceGuard -Namespace root\\Microsoft\\Windows\\DeviceGuard | Select-Object SecurityServicesConfigured, SecurityServicesRunning"}],"translations":"runtime-google"},
{"id":"az802-q-379","domain":"Secure Windows Server infrastructure","text":"An audit finds that a domain controller is reachable for administrative sign-in from ordinary workstations. Which control addresses this directly?","options":["Restrict the servers that may be used for privileged logon, for example with a Tier 0 admin group scoped to those servers","Enable audit policy for account management","Raise the domain functional level","Enable Storage Replica on the domain controller"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Limiting privileged logon to designated administrative systems reduces the number of machines where a privileged credential can be typed.","en":"Limiting privileged logon to designated administrative systems reduces the number of machines where a privileged credential can be typed.","de":"Limiting privileged logon to designated administrative systems reduces the number of machines where a privileged credential can be typed."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/tier-model","https://learn.microsoft.com/en-us/security/privileged-access-workstations/overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Harden Windows Server with security baselines","objectiveId":"sec-baselines","topic":"Restricting privileged sign-in","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/tier-model","https://learn.microsoft.com/en-us/security/privileged-access-workstations/overview"],"keyPoints":["Group Policy can define which machines members of a privileged group are permitted to log on to.","Combining that with a privileged administrative workstation means privileged credentials are only used where administration happens.","The restriction must include the local administrators group on those servers, since local rights still grant significant control."],"whyOthers":["","Account management auditing records what changed; it does not change where a privileged sign-in may occur.","The domain functional level enables features and does not restrict interactive logon to specific computers.","Storage Replica concerns volume replication and has no effect on administrative logon paths."],"requirements":"Interactive logon rights must be applied through Group Policy to the domain controllers and to privileged workstations. Verify the effective policy with the Resultant Set of Policy rather than assuming the local setting applies.","commandPath":[{"label":"List the members of the Tier 0 administrative group","command":"Get-ADGroup -Identity 'Tier 0 Admins' | Get-ADGroupMember | Select-Object Name"},{"label":"Show the effective interactive logon rights for a computer","command":"gpresult /r /scope:computer"}],"translations":"runtime-google"},
{"id":"az802-q-380","domain":"Secure Windows Server infrastructure","text":"What does Microsoft Entra Password Protection add that a password length rule alone does not?","options":["It blocks known weak passwords and their variants, and additional weak terms specific to the organisation","It requires every user to change the password on every sign-in","It prevents users from writing the password down","It encrypts the password in the directory"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Microsoft Entra Password Protection detects and blocks known weak passwords and their variants, and can also block additional weak terms that are specific to the organisation, which a length rule cannot do.","en":"Microsoft Entra Password Protection detects and blocks known weak passwords and their variants, and can also block additional weak terms that are specific to the organisation, which a length rule cannot do.","de":"Microsoft Entra Password Protection detects and blocks known weak passwords and their variants, and can also block additional weak terms that are specific to the organisation, which a length rule cannot do."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/entra/identity/authentication/concept-password-ban-bad-on-premises"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Harden Windows Server with security baselines","objectiveId":"sec-baselines","topic":"Password policy","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/entra/identity/authentication/concept-password-ban-bad-on-premises"],"keyPoints":["It detects and blocks known weak passwords and their variants, using the global and custom banned password lists stored in Microsoft Entra ID.","The same checks that apply to cloud-based changes are performed for on-premises password changes and resets against AD DS domain controllers.","Its design principles include that domain controllers never communicate directly with the internet and no new network ports are opened on them."],"whyOthers":["","How often a password must change is governed by maximum password age, which is a separate setting.","Preventing password reuse or recording is a separate control and is not what the banned password lists do.","Passwords are stored as a one-way hash, so banned lists have nothing to do with encryption of the password."],"requirements":"For on-premises AD DS the service runs on the domain controllers, and the policy is enforced only where the domain controller agent is installed, which allows incremental deployment.","commandPath":[{"label":"Read the current password protection policy","command":"Get-MsolPasswordPolicy -Domain contoso.com | Select-Object PasswordProtectionPolicy"}],"translations":"runtime-google"},
{"id":"az802-q-381","domain":"Monitor and troubleshoot Windows Server environments","text":"A server shows high processor time for two minutes each morning. What does a baseline make possible that a single reading cannot?","options":["It shows whether that level is normal for this server's normal workload","It identifies the exact line of code responsible for the load","It prevents the processor from reaching that level again","It proves the workload is not misconfigured"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"A baseline records how the server behaves under its normal workload, so a later reading can be judged against what is expected rather than against an absolute number.","en":"A baseline records how the server behaves under its normal workload, so a later reading can be judged against what is expected rather than against an absolute number.","de":"A baseline records how the server behaves under its normal workload, so a later reading can be judged against what is expected rather than against an absolute number."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/performance/troubleshoot-performance-problems-in-windows","https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/perfmon"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Correlate CPU counters with process identity, workload context, and duration before acting.","objectiveId":"perfmon-baseline","topic":"Performance counters","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/performance/troubleshoot-performance-problems-in-windows","https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/perfmon"],"keyPoints":["Counters such as processor time are meaningful only in context: the same value can be normal for a busy server and abnormal for an idle one.","A baseline captured during normal operation is the reference used to decide whether a new reading is an anomaly.","The workload in effect during the reading must be identified, otherwise a counter cannot be attributed to a process."],"whyOthers":["","Counters show resource utilisation, not source code, so a baseline never identifies the responsible line of code.","Measurement does not change system behaviour; a baseline cannot prevent the processor load from recurring.","A baseline indicates normal versus abnormal, but it does not judge whether the workload itself is designed correctly."],"requirements":"Collect the baseline during representative load and for a long enough period to include the workload's cycle. Store it so it can be compared against later captures.","commandPath":[{"label":"Capture a processor counter sample for one minute","command":"typeperf \"\\Processor(_Total)\\% Processor Time\" -si 5 -sc 12 -f C:\\perf\\baseline.blg"}],"translations":"runtime-google"},
{"id":"az802-q-382","domain":"Monitor and troubleshoot Windows Server environments","text":"After migrating a file server to new storage, users report slow file opens. Which combination is needed before blaming the new array?","options":["Guest-side latency, host-side latency, queue depth, and the virtual machine's storage configuration","Only the total size of the new array","Only the file server's CPU utilisation","The new array's warranty terms"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"A storage fault shows up as latency and queueing, and the same slowness can originate in the guest, the host, or the virtual machine's virtual disk configuration.","en":"A storage fault shows up as latency and queueing, and the same slowness can originate in the guest, the host, or the virtual machine's virtual disk configuration.","de":"A storage fault shows up as latency and queueing, and the same slowness can originate in the guest, the host, or the virtual machine's virtual disk configuration."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/performance/troubleshoot-performance-problems-in-windows","https://learn.microsoft.com/en-us/windows-server/storage/storage-spaces/troubleshooting-storage-spaces"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Correlate guest disk latency, host storage latency, queue depth, and VM storage configuration after a storage migration.","objectiveId":"storage-performance","topic":"Latency correlation","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/performance/troubleshoot-performance-problems-in-windows","https://learn.microsoft.com/en-us/windows-server/storage/storage-spaces/troubleshooting-storage-spaces"],"keyPoints":["Average disk seconds per read and per write describe latency, which is what applications actually wait on.","Queue depth shows whether requests are backing up behind the device rather than simply taking longer.","In a virtualised server the virtual disk configuration can add a layer between the guest and the array, so it must be part of the picture."],"whyOthers":["","Array capacity affects how full the device is but does not measure the latency the guest is experiencing.","CPU utilisation is not a storage metric and would not explain slow file opens by itself.","Warranty terms have no bearing on measured performance."],"requirements":"Capture latency and queue counters during the same window as the user complaint, and compare them against the pre-migration baseline for the same workload.","commandPath":[{"label":"Read the physical disk latency and queue counters","command":"Get-Counter '\\PhysicalDisk(*)\\Avg. Disk sec/Read','\\PhysicalDisk(*)\\Avg. Disk sec/Write','\\PhysicalDisk(*)\\Current Disk Queue Length'"}],"translations":"runtime-google"},
{"id":"az802-q-383","domain":"Monitor and troubleshoot Windows Server environments","text":"A Windows service will not start and reports that a dependent service is required. What should be done first?","options":["Identify the services it depends on and confirm each is running, then start them in order","Reinstall the service's package from a fresh source","Restart the server and wait for the service to start automatically","Grant the service account full control over the entire operating system"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Service start order follows declared dependencies, so a dependency that is stopped or failed will block the service that needs it.","en":"Service start order follows declared dependencies, so a dependency that is stopped or failed will block the service that needs it.","de":"Service start order follows declared dependencies, so a dependency that is stopped or failed will block the service that needs it."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/sc-config","https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.diagnostics/get-winevent"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Investigate a stopped service using service configuration, dependencies, startup type, and System event log evidence.","objectiveId":"service-troubleshooting","topic":"Service dependencies","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/sc-config","https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.diagnostics/get-winevent"],"keyPoints":["Each service declares what it depends on and what depends on it, and the service control manager starts them in that declared order.","A stopped dependency is the most common cause of a dependent-service error, so it has to be resolved before the start is retried.","The System event log records the failure, which is how the dependency that blocked the start is identified."],"whyOthers":["","Reinstalling the package does not address a stopped dependency, which is a runtime state rather than a missing file.","Restarting the server may mask the symptom without identifying the stopped dependency, and the problem would return.","Granting the service account full control over the entire operating system does not start a dependency and violates least privilege."],"requirements":"Check the System event log for the dependent service entry, which usually names the dependency that failed to start.","commandPath":[{"label":"Show a service and the services it depends on","command":"Get-Service -Name Spooler | Select-Object -ExpandProperty ServicesDependedOn"},{"label":"Read the service control manager entries for a service","command":"Get-WinEvent -FilterHashtable @{LogName='System'; ProviderName='Service Control Manager'} -MaxEvents 40 | Where-Object Message -match 'Spooler'"}],"translations":"runtime-google"},
{"id":"az802-q-384","domain":"Monitor and troubleshoot Windows Server environments","text":"What distinguishes System Insights from a conventional performance counter dashboard?","options":["It forecasts future capacity and health locally and raises warnings from those predictions","It records every disk sector read for later analysis","It replaces the need for event log auditing","It streams all server data to an external telemetry service"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"System Insights runs predictive analytics on the server itself and raises configurable warnings when a forecast crosses a threshold.","en":"System Insights runs predictive analytics on the server itself and raises configurable warnings when a forecast crosses a threshold.","de":"System Insights runs predictive analytics on the server itself and raises configurable warnings when a forecast crosses a threshold."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/manage/system-insights/overview","https://learn.microsoft.com/en-us/windows-server/manage/system-insights/managing-capabilities"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Describe System Insights as local predictive analytics for Windows Server capacity and health signals.","objectiveId":"system-insights","topic":"Predictive analytics","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/manage/system-insights/overview","https://learn.microsoft.com/en-us/windows-server/manage/system-insights/managing-capabilities"],"keyPoints":["Capabilities such as storage prediction, memory prediction, system diagnostics, and networking forecast a likely future condition.","Each capability has thresholds that raise a warning when the forecast predicts a problem, rather than waiting for one to occur.","The service runs locally on the server and does not depend on an external analytics platform."],"whyOthers":["","System Insights does not record raw disk reads; it uses the platform's own performance data.","Event log auditing remains necessary and is not replaced by a predictive service.","The analysis runs on the server itself, so no external telemetry destination is required."],"requirements":"Applies to Windows Server 2016 and later. Capabilities are enabled and their thresholds configured per server, so the defaults may not match the environment.","commandPath":[{"label":"Show the System Insights capabilities and their state","command":"Get-InsightsCapability | Select-Object Name, Enabled"},{"label":"Show the current forecasts raised on the server","command":"Get-InsightsStatus"}],"translations":"runtime-google"},
{"id":"az802-q-385","domain":"Monitor and troubleshoot Windows Server environments","text":"A disk alert fires every time free space dips below 15 percent for a few seconds. What reduces the noise without hiding a real problem?","options":["Evaluate the threshold over a window so a brief dip must persist before the alert fires","Raise the threshold to 50 percent so it fires less often","Delete the alert after the first notification","Disable the metric that the alert evaluates"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"An evaluation window means the condition must hold for a period before the rule fires, which distinguishes a sustained problem from a momentary reading.","en":"An evaluation window means the condition must hold for a period before the rule fires, which distinguishes a sustained problem from a momentary reading.","de":"An evaluation window means the condition must hold for a period before the rule fires, which distinguishes a sustained problem from a momentary reading."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-monitor/alerts/alerts-overview","https://learn.microsoft.com/en-us/azure/azure-monitor/overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Judge alerts by threshold duration, recurrence, workload impact, and corroboration, not by a lone incident.","objectiveId":"alerts","topic":"Alert design","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-monitor/alerts/alerts-overview","https://learn.microsoft.com/en-us/azure/azure-monitor/overview"],"keyPoints":["An evaluation window aggregates the metric over time and only fires when the breach persists.","Raising a threshold reduces sensitivity and can miss a genuine problem, so it is not the same fix.","Alerts should be routed through action groups so the responsible team is notified and the firing is auditable."],"whyOthers":["","Raising the threshold to 50 percent would still fire on the same transient dip and would alarm on normal operation.","Deleting the rule after it fires removes the detection entirely, which loses a genuine early warning.","Disabling the metric removes the input the alert depends on, so no problem would be detected at all."],"requirements":"Alerts should carry an action group and be reviewed periodically against the environment's actual limits. A threshold with no window is usually the cause of recurring false alarms.","commandPath":[{"label":"Show the metric alert rules and their evaluation windows","command":"az monitor metrics alert list -g rg-prod --output table"}],"translations":"runtime-google"},
{"id":"az802-q-386","domain":"Monitor and troubleshoot Windows Server environments","text":"What does VM Insights add for a supported Azure virtual machine?","options":["Performance views together with a dependency map of the components the machine talks to","A replacement for the operating system update service","A local file server for the virtual machine","A virtual network firewall rule set"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"VM Insights combines performance analysis with dependency monitoring, which shows the outbound connections a machine makes to other components.","en":"VM Insights combines performance analysis with dependency monitoring, which shows the outbound connections a machine makes to other components.","de":"VM Insights combines performance analysis with dependency monitoring, which shows the outbound connections a machine makes to other components."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-monitor/vm/vminsights-overview","https://learn.microsoft.com/en-us/azure/azure-monitor/vm/vminsights-performance"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Describe VM Insights as performance and dependency monitoring for supported Azure virtual machines.","objectiveId":"vm-insights","topic":"Dependency monitoring","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/azure-monitor/vm/vminsights-overview","https://learn.microsoft.com/en-us/azure/azure-monitor/vm/vminsights-performance"],"keyPoints":["It presents standard performance views for the virtual machine alongside a map of its dependencies.","The dependency view is what makes a downstream problem visible, because it shows which component is being contacted.","It works with supported Azure virtual machines and depends on the agent reporting to the configured workspace."],"whyOthers":["","It does not replace the update service; patching remains the responsibility of the update tooling.","It provides monitoring, not a file service on the machine.","It does not configure firewall rules, which remain part of the network design."],"requirements":"Requires the Azure Monitor agent with the dependency component enabled and the machine associated with the workspace that stores the data.","commandPath":[{"label":"Show which virtual machines report to a Log Analytics workspace","command":"az monitor log-analytics workspace show -g rg-prod -n law-prod --query features"}],"translations":"runtime-google"},
{"id":"az802-q-387","domain":"Monitor and troubleshoot Windows Server environments","text":"SYSVOL is not shared on one domain controller. Which check is the right first step?","options":["Review DFSR state and its event log for membership and initial synchronisation problems on that controller","Delete and recreate the SYSVOL folder from a template","Reinstall the domain controller role on the machine immediately","Give every user modify rights on the SYSVOL share"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"SYSVOL is replicated by DFSR, so its state, membership, and event log are the evidence needed before any destructive action.","en":"SYSVOL is replicated by DFSR, so its state, membership, and event log are the evidence needed before any destructive action.","de":"SYSVOL is replicated by DFSR, so its state, membership, and event log are the evidence needed before any destructive action."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/dcdiag","https://learn.microsoft.com/en-us/windows-server/storage/dfs-replication/dfsr-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Check DFSR state, event logs, and initial synchronization when SYSVOL is not shared.","objectiveId":"dfsr-sysvol","topic":"SYSVOL","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/dcdiag","https://learn.microsoft.com/en-us/windows-server/storage/dfs-replication/dfsr-overview"],"keyPoints":["DFSR replicates SYSVOL on a modern domain, so a missing share points at the DFSR service or its replication state.","The DFSR event log records initial synchronisation and membership errors, which are the usual causes of a failed share.","Rebuilding SYSVOL without understanding the member state can destroy data other controllers are relying on."],"whyOthers":["","Deleting and recreating SYSVOL is destructive and is only a last step after the replication state is understood.","Reinstalling the role does not address a replication or initial synchronisation problem and risks further damage.","Broadening permissions does not create a share and weakens security without fixing the cause."],"requirements":"Check the Distributed File System Replication service state, the SYSVOL and NETLOGON share definitions, and the DFSR event log before acting.","commandPath":[{"label":"Show the DFSR service state on the controller","command":"Get-Service -Name DFSR | Select-Object Status, StartType"},{"label":"Read the DFSR event log for synchronisation errors","command":"Get-WinEvent -LogName 'Microsoft-Windows-DistributedFileSystem-Client/Operational' -MaxEvents 50"}],"translations":"runtime-google"},
{"id":"az802-q-388","domain":"Monitor and troubleshoot Windows Server environments","text":"A computer can sign in locally but not with domain credentials, and it reports that its trust relationship is broken. What should be checked?","options":["Name resolution and time to a domain controller, then test the machine's secure channel","The client's local firewall profile settings","The size of the local page file","The computer's display adapter driver version"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"The machine authenticates to a domain controller over a secure channel, so DNS, time, and reachability to a domain controller are what decide whether that channel stays healthy.","en":"The machine authenticates to a domain controller over a secure channel, so DNS, time, and reachability to a domain controller are what decide whether that channel stays healthy.","de":"The machine authenticates to a domain controller over a secure channel, so DNS, time, and reachability to a domain controller are what decide whether that channel stays healthy."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.management/test-computersecurechannel","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/dns-and-ad-ds"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Check DNS, time, secure channel, and domain-controller reachability when local logon works but domain logon fails.","objectiveId":"secure-channel-troubleshooting","topic":"Secure channel","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.management/test-computersecurechannel","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/dns-and-ad-ds"],"keyPoints":["The secure channel is the machine's authenticated connection to a domain controller for the computer account.","A machine that cannot resolve a domain controller, or whose clock is far from the domain's, will fail domain authentication while local logon still works.","The secure channel can be tested directly, and repaired with domain credentials once the underlying cause is fixed."],"whyOthers":["","The local firewall profile is worth checking for connectivity, but it does not explain a broken trust relationship specifically.","Page file size affects commit limits and has no relationship to the secure channel.","A display driver has no bearing on domain authentication."],"requirements":"Repairing the secure channel requires a domain credential with rights over the computer account. Repeated manual repairs usually mean the underlying DNS or time fault is still present.","commandPath":[{"label":"Test whether the machine's secure channel to the domain is healthy","command":"Test-ComputerSecureChannel"},{"label":"Repair the secure channel with a domain credential","command":"Test-ComputerSecureChannel -Repair -Credential (Get-Credential)"}],"translations":"runtime-google"},
{"id":"az802-q-389","domain":"Monitor and troubleshoot Windows Server environments","text":"Which command reports the replication partners, their status, and the number of failed replication attempts between domain controllers?","options":["repadmin /replsummary","netdom query fsmo","dcdiag /test:servers","auditpol /get /category:*"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"repadmin reports the partner view of replication, which names each partner, its status, and how many failures have occurred.","en":"repadmin reports the partner view of replication, which names each partner, its status, and how many failures have occurred.","de":"repadmin reports the partner view of replication, which names each partner, its status, and how many failures have occurred."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/troubleshoot/troubleshooting-active-directory-replication-problems","https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/diagnose-replication-failures"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Recognize DNS, RPC/firewall, time, and topology problems as common causes of AD replication failures.","objectiveId":"ad-replication-troubleshooting","topic":"Replication status","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/troubleshoot/troubleshooting-active-directory-replication-problems","https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/diagnose-replication-failures"],"keyPoints":["repadmin showrepl shows the partners and the last successful replication attempt from the perspective of one controller.","A repeating failure count points at a persistent fault such as name resolution, connectivity, or time.","Replication errors are also written to the Directory Service log, which gives the specific error code."],"whyOthers":["","netdom query fsmo reports who holds the FSMO roles and says nothing about replication status.","dcdiag runs tests against a controller's overall health, which is broader and slower than the partner view.","auditpol reports audit policy settings and is unrelated to replication."],"requirements":"The account running repadmin needs replication rights, typically on a domain controller. Combine the partner view with the Directory Service log rather than relying on it alone.","commandPath":[{"label":"Show replication partners and failure counts","command":"repadmin /replsummary"},{"label":"Show the replication view for one domain controller","command":"repadmin /showrepl dc01"}],"translations":"runtime-google"},
{"id":"az802-q-390","domain":"Monitor and troubleshoot Windows Server environments","text":"A server repeatedly fails to install updates with error 0x80070005 (E_ACCESSDENIED). What does that error indicate?","options":["The update process cannot access required files, folders, or registry entries, which is usually a permissions problem","The disk is full of unallocated space","The server's clock is out by exactly one hour","The update catalogue has no package for this build"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"E_ACCESSDENIED means the update process cannot access the files, folders, or registry entries it needs, which typically indicates a permissions problem affecting the component store, the SoftwareDistribution folder, or related system resources.","en":"E_ACCESSDENIED means the update process cannot access the files, folders, or registry entries it needs, which typically indicates a permissions problem affecting the component store, the SoftwareDistribution folder, or related system resources.","de":"E_ACCESSDENIED means the update process cannot access the files, folders, or registry entries it needs, which typically indicates a permissions problem affecting the component store, the SoftwareDistribution folder, or related system resources."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-client/installing-updates-features-roles/troubleshoot-windows-update-error-0x80070005","https://learn.microsoft.com/en-us/powershell/module/windowsupdate/get-windowsupdatelog"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Review update error codes, Windows Update logs, service state, disk space, and connectivity when updates fail repeatedly.","objectiveId":"windows-update-troubleshooting","topic":"Update failures","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-client/installing-updates-features-roles/troubleshoot-windows-update-error-0x80070005","https://learn.microsoft.com/en-us/powershell/module/windowsupdate/get-windowsupdatelog"],"keyPoints":["The documented causes include the TrustedInstaller service account lacking permissions on the WinSxS or SoftwareDistribution folders.","Permissions on the registry subkey for component based servicing may be wrong, or Group Policy may have restricted write access to system directories.","A third-party antivirus or security tool that has locked update-related files or folders is also a documented cause."],"whyOthers":["","Insufficient disk space is reported with a different error code, so it does not explain an access-denied result.","Time skew affects installation in some scenarios but is reported with different codes and is not an access-denied result.","A missing package is reported as an update-not-available error rather than access denied."],"requirements":"Back up the operating system disk before starting. The documented resolution resets the permissions on the component store and SoftwareDistribution, restores TrustedInstaller ownership, and then repairs the component store and system files.","commandPath":[{"label":"Generate the merged Windows Update log for diagnosis","command":"Get-WindowsUpdateLog"},{"label":"Reset permissions on the update cache folder","command":"icacls \"%windir%\\SoftwareDistribution\" /reset /t /c /q"}],"translations":"runtime-google"},
{"id":"az802-q-391","domain":"Monitor and troubleshoot Windows Server environments","text":"Why does large clock drift between a domain controller and a client break Kerberos authentication?","options":["Kerberos tickets carry a validity window, so a skewed clock makes a ticket appear expired or not yet valid","Kerberos sends the clock reading as the client's SID","The KDC refuses any client whose processor is throttled","Kerberos requires all hosts to share a MAC address"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Kerberos tolerates only limited skew, because the ticket's issued and expiry times are checked against the validating host's clock.","en":"Kerberos tolerates only limited skew, because the ticket's issued and expiry times are checked against the validating host's clock.","de":"Kerberos tolerates only limited skew, because the ticket's issued and expiry times are checked against the validating host's clock."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/windows-time-service/how-the-windows-time-service-works","https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/configure-authoritative-time-server"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Recognize the forest-root PDC Emulator as the authoritative time source for the domain hierarchy.","objectiveId":"time-sync-kerberos","topic":"Time","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/networking/windows-time-service/how-the-windows-time-service-works","https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/configure-authoritative-time-server"],"keyPoints":["A service ticket carries a limited lifetime and a start time, and a skewed clock falls outside that window.","That produces an authentication failure that looks like a credential problem but is really a time problem.","Time should flow from an authoritative source to member servers and clients, which is why the forest root domain PDC Emulator is the default time root."],"whyOthers":["","The clock reading is not encoded as a SID; the SID identifies the account independently of time.","Processor throttling is unrelated to authentication and does not affect Kerberos validity.","Kerberos has no MAC address requirement; that belongs to lower-level protocols."],"requirements":"Confirm the time source with w32tm /query /source. Large skew often results from a misconfigured hierarchy rather than a fault on the client itself.","commandPath":[{"label":"Show the time source the server is synchronised from","command":"w32tm /query /source"},{"label":"Check the time service status on the server","command":"Get-Service -Name w32time | Select-Object Status, StartType"}],"translations":"runtime-google"},
{"id":"az802-q-392","domain":"Monitor and troubleshoot Windows Server environments","text":"Which event log should be read to establish which service, driver, or startup action failed on a server?","options":["The System log","The Application log","The Security log","A custom application log"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"The System log records service control manager, driver, and startup events, which is where a boot or service fault is recorded.","en":"The System log records service control manager, driver, and startup events, which is where a boot or service fault is recorded.","de":"The System log records service control manager, driver, and startup events, which is where a boot or service fault is recorded."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.diagnostics/get-winevent","https://learn.microsoft.com/en-us/windows-server/administration/server-manager/view-and-configure-performance-event-and-service-data"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Resolve DNS names from PowerShell with Resolve-DnsName as part of name-resolution triage.","objectiveId":"dns-troubleshooting","topic":"Event logs","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.diagnostics/get-winevent","https://learn.microsoft.com/en-us/windows-server/administration/server-manager/view-and-configure-performance-event-and-service-data"],"keyPoints":["The System log covers the operating system itself: services, drivers, disk, and startup components.","The Application log records events from applications rather than from the platform.","Filtering the System log by source and by time window around the failure turns it into a usable timeline."],"whyOthers":["","The Application log holds events raised by applications, so a driver or service fault will not be there.","The Security log records auditing of access and authentication, not service or driver state.","A custom application log contains only what that application chose to write, so it cannot describe a platform fault."],"requirements":"Log retention must cover the period in question. Export or forward logs to a central store, because a cleared local log cannot be recovered later.","commandPath":[{"label":"Read the most recent System log events","command":"Get-WinEvent -LogName System -MaxEvents 50"},{"label":"Read System events from one source around a failure","command":"Get-WinEvent -FilterHashtable @{LogName='System'; ProviderName='Service Control Manager'; StartTime=(Get-Date).AddHours(-1)}"}],"translations":"runtime-google"},
{"id":"az802-q-393","domain":"Monitor and troubleshoot Windows Server environments","text":"A disk is offline and will not come online on a host that shares a bus with another system. What must be resolved first?","options":["A disk signature or GUID conflict, and the shared-bus safety of bringing it online at all","The volume's cluster size","The server's DNS suffix","The date format configured on the server"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"On a shared bus, a duplicate signature or a missing unique identifier can mount the wrong disk, so the identifier and the bus ownership must be settled first.","en":"On a shared bus, a duplicate signature or a missing unique identifier can mount the wrong disk, so the identifier and the bus ownership must be settled first.","de":"On a shared bus, a duplicate signature or a missing unique identifier can mount the wrong disk, so the identifier and the bus ownership must be settled first."},"skillId":"monitoring","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/backup-and-storage/troubleshoot-disk-management","https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/diskpart"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Check disk signature conflicts, SAN policy, and shared-bus safety before bringing an offline disk online.","objectiveId":"disk-offline","topic":"Disk state","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/troubleshoot/windows-server/backup-and-storage/troubleshoot-disk-management","https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/diskpart"],"keyPoints":["A signature collision means two disks look like the same device to the storage subsystem, which risks writing to the wrong one.","SAN policy determines whether disks on a shared bus are brought online automatically or left offline until an administrator intervenes.","Verify the disk's identifier and only then bring it online, on the correct host."],"whyOthers":["","Cluster size is a formatting choice and does not determine whether a disk can come online.","The DNS suffix is unrelated to disk identification or bus safety.","Date format is a display preference with no bearing on storage identifiers."],"requirements":"Before any operation, confirm which host physically owns the storage and that the disk's identifier matches the intended device.","commandPath":[{"label":"List the disks with their unique identifiers and state","command":"Get-Disk | Select-Object Number, FriendlyName, UniqueId, OperationalStatus, IsOffline"},{"label":"Inspect the SAN policy on the host","command":"Get-StorageSubsystem | Get-StorageFirmwareCapability -PhysicalDisk"}],"translations":"runtime-google"},
{"id":"az802-q-394","domain":"Backup, recovery, high availability, and migration crossover","text":"A backup job reports success every night for six months. Why is that still not evidence that the data can be recovered?","options":["Job success records that the data was written, not that it can be read back and used","Because the schedule is set to run too often","Because a successful job always overwrites the previous backup","Because file servers cannot be restored from backup"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"A completed job only proves that data was captured. Recoverability is proven by restoring the data and using it.","en":"A completed job only proves that data was captured. Recoverability is proven by restoring the data and using it.","de":"A completed job only proves that data was captured. Recoverability is proven by restoring the data and using it."},"skillId":"dr","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/wbadmin-start-recovery","https://learn.microsoft.com/en-us/azure/backup/backup-architecture"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Prove recoverability with actual restore exercises, not just successful backup jobs.","objectiveId":"restore-testing","topic":"Restore validation","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/wbadmin-start-recovery","https://learn.microsoft.com/en-us/azure/backup/backup-architecture"],"keyPoints":["A backup that was never restored may be incomplete, corrupt, or unusable for a reason that only appears during recovery.","Restore testing should cover the application, not just the files, because an application may need a consistent restore point.","The test should be scheduled and its result recorded, otherwise it becomes a one-off exercise that drifts out of date."],"whyOthers":["","Frequency has nothing to do with whether the captured data is usable.","Rotation policy is a capacity concern and does not determine recoverability.","File servers are routinely restored from backup, so there is no such limitation."],"requirements":"Run restores at the agreed recovery point and recovery time intervals, on infrastructure representative of production, and record the outcome.","commandPath":[{"label":"List the available backup versions","command":"wbadmin get versions"},{"label":"Start a recovery of a specific backup","command":"wbadmin start recovery -backupTarget:F: -version:10/07/2026-03:00 -item:F:\\Data"}],"translations":"runtime-google"},
{"id":"az802-q-395","domain":"Backup, recovery, high availability, and migration crossover","text":"Ransomware reached a file server and encrypted the backups stored on the same network share. Which control would have prevented that outcome?","options":["Keeping at least one backup copy in isolated or immutable storage that the compromised credentials cannot reach","Increasing the backup frequency so more copies exist","Encrypting the source files with a key stored on the file server","Adding a second file server on the same subnet"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Immutable or isolated storage cannot be modified by an attacker who holds the credentials used against the rest of the estate.","en":"Immutable or isolated storage cannot be modified by an attacker who holds the credentials used against the rest of the estate.","de":"Immutable or isolated storage cannot be modified by an attacker who holds the credentials used against the rest of the estate."},"skillId":"dr","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/backup/backup-architecture","https://learn.microsoft.com/en-us/azure/well-architected/reliability/disaster-recovery"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Design backups with protected, access-controlled, tested copies including isolated or immutable storage.","objectiveId":"ransomware-resilience","topic":"Immutable backups","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/azure/backup/backup-architecture","https://learn.microsoft.com/en-us/azure/well-architected/reliability/disaster-recovery"],"keyPoints":["Ransomware targets reachable backups as well as production data, so copies reachable with the same credentials are at risk.","Immutable storage prevents deletion or overwrite within its retention window, and isolated storage removes the path to it entirely.","Backup administration should also use separate privileged identities so compromising a server does not extend to the backup system."],"whyOthers":["","More frequent backups on the same reachable storage do not help, because the attacker can encrypt those copies too.","A key stored on the file server is available to the attacker, so encryption there offers no protection.","A second server on the same subnet is reachable with the same credentials and adds no isolation."],"requirements":"Immutability should be configured with a retention period long enough that a clean copy survives the time it takes to detect and respond to an incident.","commandPath":[{"label":"List the recovery vaults in the subscription","command":"az recovery services vault list -o table"},{"label":"Show the immutability settings on a storage account","command":"az storage account show -g rg-backup -n stvault1 --query immutabilityPolicy"}],"translations":"runtime-google"},
{"id":"az802-q-396","domain":"Backup, recovery, high availability, and migration crossover","text":"Which environment is required to repair the AD DS database file on a domain controller?","options":["Directory Services Restore Mode","Windows Recovery Environment only","A second domain controller with a writable copy","Safe Mode with networking"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"DSRM is the offline environment for the directory database, because the directory service must not be running while the database files are repaired.","en":"DSRM is the offline environment for the directory database, because the directory service must not be running while the database files are repaired.","de":"DSRM is the offline environment for the directory database, because the directory service must not be running while the database files are repaired."},"skillId":"dr","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/forest-recovery-guide/ad-forest-recovery-procedures","https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/wbadmin-start-systemstatebackup"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Recognize DSRM as the offline recovery environment for the AD DS database.","objectiveId":"dsrm","topic":"Offline recovery","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/forest-recovery-guide/ad-forest-recovery-procedures","https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/wbadmin-start-systemstatebackup"],"keyPoints":["DSRM is entered by restarting into Directory Services Restore Mode, where the AD DS service does not start.","The ntds.dit database can then be restored or repaired without the service holding the files open.","After the repair, the controller is restarted normally and replication resumes."],"whyOthers":["","Windows Recovery Environment is used for boot and file-level recovery and is not the environment for repairing the directory database.","A writable domain controller is not required, since the whole point of DSRM is to work without the directory service running.","Safe Mode with networking still loads the directory service stack and is not the supported environment for a database repair."],"requirements":"A current system state backup of the domain controller is required. Verify the backup is present before starting, since a repair without a good backup risks losing the directory.","commandPath":[{"label":"Verify the system state backups available before starting","command":"wbadmin get versions -backupTarget:F:"},{"label":"Enter Directory Services Restore Mode from the boot menu","command":"bcdedit /set {current} safeboot dsrm"}],"translations":"runtime-google"},
{"id":"az802-q-397","domain":"Backup, recovery, high availability, and migration crossover","text":"What distinguishes an in-place upgrade from a clean installation on new hardware?","options":["It upgrades the existing installation in place and retains roles, settings, and applications","It removes the existing installation before installing the new version","It installs the new version to a new server and leaves the old one running","It reinstalls every application from source on the same hardware"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"An in-place upgrade keeps the same installation and upgrades it, so server roles, configuration, and installed applications carry forward.","en":"An in-place upgrade keeps the same installation and upgrades it, so server roles, configuration, and installed applications carry forward.","de":"An in-place upgrade keeps the same installation and upgrades it, so server roles, configuration, and installed applications carry forward."},"skillId":"dr","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/get-started/upgrade-in-place","https://learn.microsoft.com/en-us/windows-server/get-started/install-upgrade-migrate"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Describe in-place upgrade as upgrading the existing OS installation while retaining supported roles and settings.","objectiveId":"in-place-upgrade","topic":"Upgrade paths","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/get-started/upgrade-in-place","https://learn.microsoft.com/en-us/windows-server/get-started/install-upgrade-migrate"],"keyPoints":["The operating system is upgraded where it already lives, so identity, roles, and configuration are preserved.","A clean install replaces the installation, and a side-by-side migration moves the workload to new hardware instead.","Only certain upgrade paths are supported, and the source version constrains the destination version."],"whyOthers":["","Removing the existing installation first is the opposite of an in-place upgrade; that is a clean installation.","Installing on a new server while the old one runs is a side-by-side migration, not an in-place upgrade.","Reinstalling applications from source describes a clean deployment rather than an upgrade of the existing one."],"requirements":"The source must be on a supported upgrade path. Applications and roles must be supported at the destination version, and a full backup plus a rollback plan is required first.","commandPath":[{"label":"Check whether the server qualifies for an in-place upgrade","command":"Get-WindowsUpgradeLog"},{"label":"Start the upgrade setup process","command":"setup.exe /auto upgrade"}],"translations":"runtime-google"},
{"id":"az802-q-398","domain":"Backup, recovery, high availability, and migration crossover","text":"A migration must be abandoned without losing the old server for a week. Which approach supports that?","options":["Build the new environment side by side and cut over only after it is validated","Perform an in-place upgrade on the existing server","Migrate the data in place and repair the old configuration afterwards","Delete the old server as soon as the new one is built"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"A side-by-side approach keeps the old environment intact until the new one is proven, so the migration can be reversed without a rebuild.","en":"A side-by-side approach keeps the old environment intact until the new one is proven, so the migration can be reversed without a rebuild.","de":"A side-by-side approach keeps the old environment intact until the new one is proven, so the migration can be reversed without a rebuild."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/windows-server/get-started/install-upgrade-migrate","https://learn.microsoft.com/en-us/azure/migrate/migrate-services-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Prefer side-by-side migration when you need a rollback path, hardware refresh, or a clean configuration on a new server.","objectiveId":"side-by-side-migration","topic":"Migration strategy","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/windows-server/get-started/install-upgrade-migrate","https://learn.microsoft.com/en-us/azure/migrate/migrate-services-overview"],"keyPoints":["Side-by-side migration is preferred when a rollback path, a hardware refresh, or a clean configuration is needed.","The old environment stays available, so a failed cutover means reverting to it rather than reconstructing it.","It suits refresh scenarios where the target hardware should be configured cleanly rather than inheriting old state."],"whyOthers":["","An in-place upgrade commits the existing server to the new version and cannot be reversed without restoring from backup.","Repairing the old configuration afterwards implies the old environment has already been altered, so it is no longer a clean rollback path.","Deleting the old server removes the only rollback path and should be a separate decision after validation."],"requirements":"Keep the old environment read-only or isolated where possible so the two do not serve the same clients simultaneously. Plan the cutover window and the data synchronisation step before starting.","commandPath":[{"label":"Assess a workload before planning the migration","command":"az migration assessment create -g rg-prod -n assess-web --assessment-properties \"{}\" -r \"\" -s /subscriptions/00000000-0000-0000-0000-000000000000"}],"translations":"runtime-google"},
{"id":"az802-q-399","domain":"Backup, recovery, high availability, and migration crossover","text":"Before migrating an IIS workload to Azure Migrate, what does the pre-migration assessment establish?","options":["The workload's discovered dependencies and configuration, so compatibility and sizing can be judged before the move","The subscription's monthly billing total","The names of the administrators who will have access","The colour theme of the current web pages"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"An assessment evaluates the discovered workload and produces performance-based and as-is recommendations, so dependencies and configuration are known before the move rather than after it fails.","en":"An assessment evaluates the discovered workload and produces performance-based and as-is recommendations, so dependencies and configuration are known before the move rather than after it fails.","de":"An assessment evaluates the discovered workload and produces performance-based and as-is recommendations, so dependencies and configuration are known before the move rather than after it fails."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/migrate/concepts-assessment-overview","https://learn.microsoft.com/en-us/azure/migrate/migrate-services-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Assess dependencies, runtime compatibility, data stores, authentication, networking, and performance requirements before migrating an IIS workload to Azure.","objectiveId":"app-assessment","topic":"Migration assessment","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/azure/migrate/concepts-assessment-overview","https://learn.microsoft.com/en-us/azure/migrate/migrate-services-overview"],"keyPoints":["An assessment evaluates workloads hosted on-premises or in another cloud and produces performance-based and as-is recommendations for moving to Azure.","Discovery must come first: the workload has to be discovered and available in the inventory before an assessment can be created.","The recommended discovery source is the Azure Migrate appliance, which provides an in-depth view of the machines and a regular flow of configuration and performance data."],"whyOthers":["","Billing has no bearing on whether the workload will function correctly after the move.","Naming the administrators is an access concern and does not reveal technical incompatibilities in the workload.","A visual theme is a cosmetic attribute and is irrelevant to migration success."],"requirements":"For appliance-based discovery, the appliances must be in a connected state with performance data flowing. Assessment data must be kept current, because the source environment changes over time.","commandPath":[{"label":"List the assessments in the resource group","command":"az migration assessment list -g rg-prod -o table"}],"translations":"runtime-google"},
{"id":"az802-q-400","domain":"Backup, recovery, high availability, and migration crossover","text":"What should be updated after a recovery or migration is delivered so the work can be repeated safely?","options":["The runbook and the documented tests, together with the monitoring that was added to confirm the change worked","Only the project schedule, so the timeline matches the delivery date","The firewall rules, by removing every rule that was added during testing","The server's product key, so it can be re-registered"],"correct":0,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"The runbook records what was done and the tests record what was verified, so the next occurrence of the same problem can be handled from evidence rather than from memory.","en":"The runbook records what was done and the tests record what was verified, so the next occurrence of the same problem can be handled from evidence rather than from memory.","de":"The runbook records what was done and the tests record what was verified, so the next occurrence of the same problem can be handled from evidence rather than from memory."},"skillId":"migration","reviewStatus":"technical-approved","isOriginal":true,"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/well-architected/reliability/disaster-recovery","https://learn.microsoft.com/en-us/azure/migrate/migrate-services-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-07T08:43:01.606Z"},"objective":"Finish recovery or migration work with documented tests, business validation, monitoring, and runbook updates.","objectiveId":"runbook-validation","topic":"Handover","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/well-architected/reliability/disaster-recovery","https://learn.microsoft.com/en-us/azure/migrate/migrate-services-overview"],"keyPoints":["The runbook should record the steps, the decisions, and the points where the work could fail.","Documented tests are what let a later responder confirm the recovery worked rather than assume it.","Monitoring added during the work is the evidence that the change held in production afterwards."],"whyOthers":["","A schedule records when work happened, not how to repeat it safely.","Removing every rule added during testing would remove controls that are needed in production.","A product key is unrelated to repeating a recovery or migration safely."],"requirements":"Update the runbook as the work proceeds rather than afterwards, so the record reflects what actually happened. Include the observed timings, because recovery time depends on them.","commandPath":[{"label":"Verify the recovered volume is healthy after the restore","command":"Get-Volume -DriveLetter D | Select-Object DriveLetter, HealthStatus, OperationalStatus"}],"translations":"runtime-google"},
{"id":"az802-q-401","domain":"Implement and manage on-premises and hybrid networking","text":"A company has an on-premises VPN device and an Azure VNet. It needs an encrypted site-to-site connection over the public internet so all approved branch resources can use private IP addresses. Which design is appropriate?","options":["A point-to-site VPN from every user computer","A site-to-site VPN with an Azure VPN Gateway, Local Network Gateway, and Connection","An ExpressRoute circuit without a virtual network gateway","A public IP address on every Azure virtual machine"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"برای اتصال دائمی شبکهٔ on-premises به VNet از طریق اینترنت، Site-to-Site VPN با تونل IPsec/IKE و سه جزء Azure یعنی VPN Gateway، Local Network Gateway و Connection استفاده می‌شود.","en":"A site-to-site VPN uses an Azure VPN Gateway, a Local Network Gateway that represents the on-premises device and prefixes, and a Connection that establishes the IPsec/IKE tunnel.","de":"Für eine dauerhafte Verbindung zwischen dem lokalen Netzwerk und einem Azure-VNet wird eine Site-to-Site-VPN-Verbindung verwendet. Sie besteht aus Azure VPN Gateway, Local Network Gateway und Connection und nutzt einen verschlüsselten IPsec/IKE-Tunnel."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"یک شرکت دستگاه VPN در شبکهٔ on-premises و یک VNet در Azure دارد. شرکت به اتصال رمزنگاری‌شدهٔ Site-to-Site از طریق اینترنت عمومی نیاز دارد تا منابع مجاز شعبه از Private IP استفاده کنند. کدام طراحی مناسب است؟","optionsFa":["VPN از نوع Point-to-Site از رایانهٔ تک‌تک کاربران","VPN از نوع Site-to-Site همراه با Azure VPN Gateway، Local Network Gateway و Connection","یک مدار ExpressRoute بدون Virtual Network Gateway","اختصاص Public IP به تک‌تک ماشین‌های مجازی Azure"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/vpn-gateway/vpn-gateway-about-vpngateways","https://learn.microsoft.com/en-us/azure/networking/design-guide/hybrid-connectivity"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-08T00:00:00.000Z"},"objective":"Implement hybrid network connectivity and security","objectiveId":"net-hybrid","topic":"Azure hybrid connectivity scenarios","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/vpn-gateway/vpn-gateway-about-vpngateways","https://learn.microsoft.com/en-us/azure/networking/design-guide/hybrid-connectivity"],"keyPoints":["Site-to-site connects an on-premises VPN device to an Azure VPN Gateway.","The Local Network Gateway stores the on-premises public endpoint and address prefixes.","The Connection resource joins both gateways and carries the shared key and IPsec/IKE settings."],"whyOthers":["Point-to-site is for individual client devices, not for connecting an entire branch network.","","ExpressRoute is a different private connectivity service and still requires an ExpressRoute gateway and circuit configuration.","Public IPs would expose the virtual machines and would not create a private routed hybrid network."],"requirements":"Use non-overlapping address spaces and a compatible on-premises VPN device. The tunnel encrypts traffic over the public internet; it does not make every Azure resource public.","commandPath":[{"label":"Inspect the Windows route table after the tunnel is available","command":"route print"},{"label":"Test a private Azure endpoint from a Windows server","command":"Test-NetConnection -ComputerName 10.20.1.10 -Port 443 -InformationLevel Detailed"}],"translations":"runtime-google"},
{"id":"az802-q-402","domain":"Implement and manage on-premises and hybrid networking","text":"A site-to-site VPN tunnel reports Connected, but an on-premises host in 10.40.0.0/16 cannot reach an Azure VM. The Azure VNet was also created with 10.40.0.0/16. What should be fixed first?","options":["Add a public IP address to the Azure VM","Renumber one side so the on-premises and Azure address spaces do not overlap","Flush the Windows DNS cache","Increase the VPN Gateway SKU"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"حتی اگر تونل VPN برقرار باشد، هم‌پوشانی Address Spaceها باعث می‌شود مسیرها مبهم شوند. ابتدا باید یکی از شبکه‌ها به محدوده‌ای غیرهم‌پوشان تغییر کند.","en":"A VPN tunnel can be up while overlapping prefixes make routing ambiguous. Renumber one network so the on-premises and Azure address spaces are distinct before troubleshooting higher layers.","de":"Ein Tunnel kann als verbunden angezeigt werden, obwohl überlappende Präfixe das Routing verhindern. Zuerst muss eine Seite in einen nicht überlappenden Adressbereich umnummeriert werden."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"تونل Site-to-Site وضعیت Connected دارد، اما میزبان on-premises در شبکهٔ 10.40.0.0/16 نمی‌تواند به VM در Azure برسد. VNet در Azure نیز با 10.40.0.0/16 ساخته شده است. ابتدا چه چیزی باید اصلاح شود؟","optionsFa":["اختصاص Public IP به VM در Azure","تغییر شمارهٔ یکی از شبکه‌ها تا Address Spaceهای on-premises و Azure هم‌پوشانی نداشته باشند","پاک‌کردن DNS Cache ویندوز","افزایش SKU مربوط به VPN Gateway"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/networking/design-guide/hybrid-connectivity","https://learn.microsoft.com/en-us/azure/virtual-network/concepts-and-best-practices"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-08T00:00:00.000Z"},"objective":"Implement hybrid network connectivity and security","objectiveId":"net-hybrid","topic":"Azure hybrid connectivity scenarios","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/azure/networking/design-guide/hybrid-connectivity","https://learn.microsoft.com/en-us/azure/virtual-network/concepts-and-best-practices"],"keyPoints":["Overlapping prefixes prevent reliable route selection across a hybrid connection.","A connected VPN status only proves that the tunnel negotiation succeeded.","Address planning must be corrected before DNS, firewall, or VM settings can be trusted."],"whyOthers":["A public IP bypasses the intended private design and does not solve ambiguous routes.","","DNS affects name resolution, not the overlapping network prefixes that determine the route.","A larger gateway can improve capacity but cannot make overlapping address spaces routable."],"requirements":"Choose replacement prefixes that do not overlap with any connected branch, VNet, peered VNet, or future reserved range. Update route advertisements and DNS records after renumbering.","commandPath":[{"label":"Display the effective local routes","command":"Get-NetRoute | Sort-Object DestinationPrefix"},{"label":"Check the Azure VNet and subnet prefixes","command":"az network vnet show --name hub-vnet --resource-group rg-network --query addressSpace.addressPrefixes"}],"translations":"runtime-google"},
{"id":"az802-q-403","domain":"Implement and manage on-premises and hybrid networking","text":"A financial application needs predictable low latency, high bandwidth, and a private path from its datacenter to Azure. Compliance does not allow production traffic to traverse the public internet. Which connectivity choice best fits?","options":["A point-to-site VPN for each application server","An Azure ExpressRoute circuit with private peering and an ExpressRoute gateway","A basic public endpoint with a restrictive password","A site-to-site VPN used without encryption"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"ExpressRoute اتصال خصوصی از طریق Provider فراهم می‌کند و ترافیک را از اینترنت عمومی عبور نمی‌دهد؛ برای latency قابل‌پیش‌بینی و حجم بالا مناسب است.","en":"ExpressRoute provides a private provider connection to Azure. It is the appropriate choice when predictable latency, high bandwidth, and avoiding the public internet are requirements.","de":"ExpressRoute stellt über einen Connectivity Provider eine private Verbindung zu Azure bereit. Daher passt es zu Anforderungen wie niedriger, vorhersehbarer Latenz, hoher Bandbreite und keinem öffentlichen Internetpfad."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"یک برنامهٔ مالی به Latency قابل‌پیش‌بینی، Bandwidth بالا و مسیر خصوصی از Datacenter به Azure نیاز دارد. قوانین Compliance اجازه نمی‌دهند ترافیک Production از اینترنت عمومی عبور کند. کدام گزینه مناسب‌تر است؟","optionsFa":["VPN از نوع Point-to-Site برای هر Application Server","مدار Azure ExpressRoute همراه با Private Peering و ExpressRoute Gateway","Public Endpoint ساده با Password محدودکننده","Site-to-Site VPN بدون رمزنگاری"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/expressroute/expressroute-introduction","https://learn.microsoft.com/en-us/azure/networking/design-guide/hybrid-connectivity"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-08T00:00:00.000Z"},"objective":"Implement hybrid network connectivity and security","objectiveId":"net-hybrid","topic":"Azure hybrid connectivity scenarios","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/expressroute/expressroute-introduction","https://learn.microsoft.com/en-us/azure/networking/design-guide/hybrid-connectivity"],"keyPoints":["ExpressRoute uses a private connection through a connectivity provider.","Traffic does not traverse the public internet, unlike a normal site-to-site VPN.","An ExpressRoute gateway connects the circuit to the target Azure VNet."],"whyOthers":["Point-to-site is intended for individual clients and is not a datacenter connectivity design.","","A public endpoint violates the private-path requirement and adds internet exposure.","A site-to-site VPN is encrypted, so the option is technically invalid and still uses the public internet."],"requirements":"ExpressRoute requires provider planning, circuit provisioning, peering, an ExpressRoute gateway, and compatible route exchange. It usually takes longer and costs more than VPN Gateway.","commandPath":[{"label":"List the ExpressRoute circuits in a subscription","command":"az network express-route list --query '[].{name:name,serviceProvider:serviceProviderProperties.serviceProviderName}'"}],"translations":"runtime-google"},
{"id":"az802-q-404","domain":"Implement and manage on-premises and hybrid networking","text":"An ExpressRoute circuit has been provisioned by a connectivity provider. Which set of components is required to connect that circuit to an Azure VNet and exchange routes with the datacenter?","options":["Only a public IP on the Azure VM","An ExpressRoute gateway, a VNet connection, private peering, and route exchange such as BGP","A point-to-site client profile on every server","A DNS forwarder without any network gateway"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"مدار به‌تنهایی VNet را متصل نمی‌کند. باید ExpressRoute Gateway و Connection در Azure تنظیم شوند و Private Peering و Route Exchange مانند BGP مسیرهای دو طرف را منتشر کنند.","en":"The circuit is only the provider path. The Azure VNet still needs an ExpressRoute gateway and connection, while private peering and route exchange such as BGP advertise prefixes between the datacenter and Azure.","de":"Das Circuit allein verbindet das VNet noch nicht. Benötigt werden ein ExpressRoute Gateway und eine VNet-Verbindung; über Private Peering und beispielsweise BGP werden die Präfixe zwischen Rechenzentrum und Azure ausgetauscht."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"یک مدار ExpressRoute توسط Provider فراهم شده است. برای اتصال مدار به یک VNet در Azure و تبادل Route با Datacenter، کدام مجموعه لازم است؟","optionsFa":["فقط یک Public IP روی VM در Azure","ExpressRoute Gateway، یک VNet Connection، Private Peering و Route Exchange مانند BGP","Client Profile از نوع Point-to-Site روی هر Server","Forwarder مربوط به DNS بدون هیچ Network Gateway"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/architecture/reference-architectures/hybrid-networking/expressroute-private-peering-connectivity","https://learn.microsoft.com/en-us/azure/expressroute/expressroute-introduction"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-08T00:00:00.000Z"},"objective":"Implement hybrid network connectivity and security","objectiveId":"net-hybrid","topic":"Azure hybrid connectivity scenarios","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/azure/architecture/reference-architectures/hybrid-networking/expressroute-private-peering-connectivity","https://learn.microsoft.com/en-us/azure/expressroute/expressroute-introduction"],"keyPoints":["The ExpressRoute circuit represents the provider path into Microsoft networking.","The ExpressRoute gateway connects the circuit to an Azure VNet.","Private peering and BGP route exchange allow on-premises and Azure prefixes to be learned."],"whyOthers":["A public IP does not create a private circuit-to-VNet path.","","Point-to-site is a client VPN model and is not how a datacenter advertises its prefixes through ExpressRoute.","DNS forwarding can resolve names but cannot replace the network gateway and route exchange."],"requirements":"The architecture must include a provider circuit, the correct Azure gateway SKU, private peering, and non-overlapping prefixes. BGP configuration must match the on-premises router and the ExpressRoute peering settings.","commandPath":[{"label":"Show ExpressRoute peerings","command":"az network express-route peering list --resource-group rg-network --circuit-name er-prod"},{"label":"Show the VNet gateway connections","command":"az network vpn-connection list --resource-group rg-network --query '[].{name:name,status:connectionStatus}'"}],"translations":"runtime-google"},
{"id":"az802-q-405","domain":"Implement and manage on-premises and hybrid networking","text":"A company keeps AD DS and a file server on-premises at 192.168.10.0/24 while an application tier runs in an Azure VNet at 10.20.0.0/16. Users need private access, internal name resolution, and firewall-controlled traffic during migration. Which design is the best starting point?","options":["Give every Azure VM a public IP and publish the file server to the internet","Use a site-to-site VPN or ExpressRoute with non-overlapping prefixes, private DNS forwarding, and narrowly scoped security rules","Use point-to-site VPN only on the administrator’s laptop","Move AD DS to a public subnet and disable the firewall for testing"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"یک طراحی Hybrid کامل فقط تونل را ایجاد نمی‌کند؛ مسیر خصوصی، Prefixهای بدون هم‌پوشانی، Name Resolution داخلی و Ruleهای محدود Firewall/NSG را کنار هم قرار می‌دهد.","en":"A complete hybrid design combines private connectivity, non-overlapping prefixes, internal DNS resolution, and least-privilege security rules. VPN Gateway or ExpressRoute can provide the network path depending on the requirements.","de":"Ein vollständiges hybrides Design kombiniert private Konnektivität, nicht überlappende Präfixe, interne DNS-Auflösung und restriktive Firewall- beziehungsweise NSG-Regeln. Je nach Anforderungen kann der Pfad über VPN Gateway oder ExpressRoute laufen."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"شرکت AD DS و File Server را در on-premises و شبکهٔ 192.168.10.0/24 نگه می‌دارد و Application Tier در VNet به آدرس 10.20.0.0/16 اجرا می‌شود. کاربران هنگام Migration به دسترسی خصوصی، Name Resolution داخلی و ترافیک کنترل‌شده با Firewall نیاز دارند. بهترین طراحی اولیه چیست؟","optionsFa":["اختصاص Public IP به همهٔ VMهای Azure و انتشار File Server در اینترنت","استفاده از Site-to-Site VPN یا ExpressRoute همراه با Prefixهای بدون هم‌پوشانی، Private DNS Forwarding و Ruleهای امنیتی محدود","استفاده فقط از Point-to-Site VPN روی Laptop مدیر","انتقال AD DS به Public Subnet و خاموش‌کردن Firewall برای تست"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/networking/design-guide/hybrid-connectivity","https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-overview","https://learn.microsoft.com/en-us/azure/dns/private-dns-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-08T00:00:00.000Z"},"objective":"Implement hybrid network connectivity and security","objectiveId":"net-hybrid","topic":"Azure hybrid connectivity scenarios","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/azure/networking/design-guide/hybrid-connectivity","https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-overview","https://learn.microsoft.com/en-us/azure/dns/private-dns-overview"],"keyPoints":["Private connectivity can be delivered by site-to-site VPN or ExpressRoute.","The two sides must use non-overlapping address spaces for routing to work reliably.","DNS forwarding or linked private zones are required for internal names.","Firewall and NSG rules should allow only the required management and application flows."],"whyOthers":["Public IPs expose the workload and do not provide private name resolution or a controlled hybrid path.","","Point-to-site is for individual clients and does not connect the whole application and directory environment.","Disabling the firewall and exposing AD DS violates the security requirement and is not a migration design."],"requirements":"Choose VPN Gateway for a faster, lower-cost encrypted internet path or ExpressRoute for a provider-based private path. Document required DNS zones, routes, ports, and rollback evidence before changing production.","commandPath":[{"label":"Verify the Windows server's gateway and DNS servers","command":"Get-NetIPConfiguration"},{"label":"Test the private application port","command":"Test-NetConnection -ComputerName app01.contoso.com -Port 443 -InformationLevel Detailed"}],"translations":"runtime-google"},
{"id":"az802-q-406","domain":"Implement and manage on-premises and hybrid networking","text":"The VPN tunnel is up and an Azure VM can reach an on-premises file server by IP address, but fileserver.corp.example cannot be resolved. Which check should come first?","options":["Replace the VPN Gateway with ExpressRoute immediately","Verify the DNS forwarder or private DNS zone used by the Azure VNet","Add a second public IP to the file server","Increase the VM disk size"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"وقتی اتصال با IP برقرار است، Routing و تونل تا حد زیادی کار می‌کنند؛ شکست فقط در نام، ابتدا به DNS Forwarder یا Private DNS Zone مربوط به VNet اشاره دارد.","en":"IP connectivity proves that the tunnel and route are usable. A name-only failure should first be investigated in the DNS forwarder, conditional forwarding, or private DNS zone used by the VNet.","de":"Wenn die Verbindung per IP funktioniert, sind Tunnel und Routing grundsätzlich erreichbar. Ein Fehler nur bei der Namensauflösung weist zuerst auf DNS-Forwarder, Conditional Forwarding oder eine private DNS-Zone des VNets hin."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"تونل VPN برقرار است و VM در Azure می‌تواند با IP به File Server on-premises برسد، اما نام fileserver.corp.example Resolve نمی‌شود. ابتدا کدام بررسی انجام شود؟","optionsFa":["تعویض فوری VPN Gateway با ExpressRoute","بررسی DNS Forwarder یا Private DNS Zone مورد استفادهٔ VNet در Azure","اختصاص Public IP دوم به File Server","افزایش اندازهٔ Disk مربوط به VM"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/dns/private-dns-overview","https://learn.microsoft.com/en-us/azure/networking/design-guide/hybrid-connectivity"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-08T00:00:00.000Z"},"objective":"Implement hybrid network connectivity and security","objectiveId":"net-hybrid","topic":"Azure hybrid connectivity scenarios","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/dns/private-dns-overview","https://learn.microsoft.com/en-us/azure/networking/design-guide/hybrid-connectivity"],"keyPoints":["Successful IP connectivity separates routing problems from name-resolution problems.","A private DNS zone can resolve internal names inside linked VNets.","A DNS forwarder or conditional forwarder can send the on-premises namespace to the authoritative internal DNS server."],"whyOthers":["Changing connectivity is unnecessary until DNS and the existing route are shown to be the cause.","","A public IP is not required when the private route already works.","Disk capacity has no effect on DNS name resolution."],"requirements":"Check the VNet DNS settings, linked private zone, conditional forwarder, and the authoritative on-premises DNS server. Use nslookup or Resolve-DnsName from the affected VM.","commandPath":[{"label":"Query the internal name from PowerShell","command":"Resolve-DnsName fileserver.corp.example"},{"label":"Test the internal DNS server directly","command":"Resolve-DnsName fileserver.corp.example -Server 192.168.10.10"}],"translations":"runtime-google"},
{"id":"az802-q-407","domain":"Implement and manage on-premises and hybrid networking","text":"The on-premises network uses 10.0.0.0/16 and a new Azure VNet is planned with the same prefix. The VNet must connect through VPN Gateway and later be peered to another VNet. What is the correct planning action?","options":["Keep both prefixes because VPN encryption removes overlap","Choose a unique Azure address space that does not overlap with on-premises, peered VNets, or planned ranges","Use only public addresses in the Azure VNet","Solve the overlap by changing the DNS suffix"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"برای VPN و VNet Peering باید تمام Prefixهای متصل یکتا باشند. یک Address Space غیرهم‌پوشان برای Azure قبل از ایجاد Gateway و Peer انتخاب کنید.","en":"Hybrid routing and VNet peering require unique prefixes. Select an Azure address space that does not overlap with on-premises, existing peered VNets, or ranges reserved for future sites.","de":"Für hybrides Routing und VNet-Peering müssen die Präfixe eindeutig sein. Der Azure-Adressraum darf sich weder mit dem lokalen Netzwerk noch mit bereits verbundenen oder geplanten VNets überschneiden."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"شبکهٔ on-premises از 10.0.0.0/16 استفاده می‌کند و VNet جدید Azure نیز با همین Prefix برنامه‌ریزی شده است. VNet باید از طریق VPN Gateway متصل و بعداً با VNet دیگری Peer شود. اقدام درست در طراحی چیست؟","optionsFa":["هر دو Prefix را نگه دارید، چون رمزنگاری VPN هم‌پوشانی را حذف می‌کند","Address Space یکتایی برای Azure انتخاب کنید که با on-premises، VNetهای Peerشده یا محدوده‌های آینده هم‌پوشانی نداشته باشد","فقط از آدرس‌های Public در VNet استفاده کنید","با تغییر DNS Suffix هم‌پوشانی را حل کنید"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/networking/design-guide/hybrid-connectivity","https://learn.microsoft.com/en-us/azure/virtual-network/concepts-and-best-practices"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-08T00:00:00.000Z"},"objective":"Implement hybrid network connectivity and security","objectiveId":"net-hybrid","topic":"Azure hybrid connectivity scenarios","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/networking/design-guide/hybrid-connectivity","https://learn.microsoft.com/en-us/azure/virtual-network/concepts-and-best-practices"],"keyPoints":["Overlapping prefixes make it impossible to select a single unambiguous route.","The plan must consider on-premises, peered VNets, branches, and future expansion.","Changing DNS names does not change IP routing or address overlap."],"whyOthers":["Encryption protects traffic but does not make two identical network prefixes distinguishable.","","Public addresses are not required and would weaken the private design.","A DNS suffix affects names, not the network prefixes used for routing."],"requirements":"Document the address inventory before creating a gateway or peering. Reserve ranges for management, GatewaySubnet, application tiers, and future sites without overlap.","commandPath":[{"label":"Inspect the VNet address space","command":"az network vnet show --name hub-vnet --resource-group rg-network --query '{addressSpace:addressSpace.addressPrefixes,subnets:subnets[].addressPrefix}'"}],"translations":"runtime-google"},
{"id":"az802-q-408","domain":"Implement and manage on-premises and hybrid networking","text":"A hub VNet uses 10.20.0.0/16, an application subnet uses 10.20.1.0/24, and on-premises uses 172.16.0.0/16. Which additional plan best supports a future VPN or ExpressRoute gateway?","options":["Place the gateway inside the application subnet and reuse its addresses","Reserve a separate GatewaySubnet, keep all prefixes non-overlapping, and publish the routes for each subnet","Use the same 10.20.1.0/24 range at the branch to simplify DNS","Put all VMs and gateways in one /32 subnet"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"Gateway باید در GatewaySubnet جدا قرار گیرد و Subnetهای Application و on-premises نباید هم‌پوشانی داشته باشند. Routeهای هر Prefix نیز باید قابل انتشار و بررسی باشند.","en":"A hybrid VNet should reserve a dedicated GatewaySubnet, keep application and on-premises prefixes distinct, and make the route for every subnet explicit and verifiable.","de":"Ein hybrides VNet sollte ein eigenes GatewaySubnet reservieren, die Präfixe von Anwendung und lokalem Netzwerk getrennt halten und für jedes Subnetz nachvollziehbare Routen bereitstellen."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"یک Hub VNet از 10.20.0.0/16، یک Application Subnet از 10.20.1.0/24 و شبکهٔ on-premises از 172.16.0.0/16 استفاده می‌کند. کدام برنامه‌ریزی اضافی از Gateway آیندهٔ VPN یا ExpressRoute پشتیبانی می‌کند؟","optionsFa":["Gateway را داخل Application Subnet قرار دهید و آدرس‌های آن را دوباره استفاده کنید","یک GatewaySubnet جدا رزرو کنید، همهٔ Prefixها را بدون هم‌پوشانی نگه دارید و Route هر Subnet را منتشر کنید","همان محدودهٔ 10.20.1.0/24 را در شعبه استفاده کنید تا DNS ساده‌تر شود","همهٔ VMها و Gatewayها را در یک Subnet از نوع /32 قرار دهید"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/networking/design-guide/hybrid-connectivity","https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-overview"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-08T00:00:00.000Z"},"objective":"Implement hybrid network connectivity and security","objectiveId":"net-hybrid","topic":"Azure hybrid connectivity scenarios","difficulty":"hard","sourceRefs":["https://learn.microsoft.com/en-us/azure/networking/design-guide/hybrid-connectivity","https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-overview"],"keyPoints":["Gateway resources require a dedicated GatewaySubnet in the VNet design.","Application and on-premises prefixes must not overlap.","A written route and subnet inventory makes troubleshooting and future peering safer."],"whyOthers":["The gateway should not share the application subnet; mixing roles complicates routing and deployment requirements.","","Reusing an application prefix at a branch creates an overlap instead of simplifying DNS.","A /32 is a host route, not a usable shared subnet for a gateway and multiple virtual machines."],"requirements":"Choose subnet sizes based on the gateway SKU, coexistence requirements, and future growth. Do not rely on an address range that is already used by any connected network.","commandPath":[{"label":"List subnet prefixes in the VNet","command":"az network vnet subnet list --vnet-name hub-vnet --resource-group rg-network --query '[].{name:name,prefix:addressPrefix}'"}],"translations":"runtime-google"},
{"id":"az802-q-409","domain":"Implement and manage on-premises and hybrid networking","text":"Which statement correctly compares an on-premises physical network with an Azure virtual network?","options":["Azure administrators must manage the physical cables and Microsoft datacenter switches","A physical network uses cables, switches, and routers; an Azure VNet provides logical address spaces, subnets, routes, and security controls over Microsoft-managed infrastructure","An Azure VNet is only a DNS zone and cannot route traffic","Physical and virtual networks use identical management commands and failure domains"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"شبکهٔ فیزیکی تجهیزات و کابل‌های واقعی دارد؛ VNet یک شبکهٔ منطقی با Address Space، Subnet، Route و کنترل‌های امنیتی است و زیرساخت فیزیکی Azure را Microsoft مدیریت می‌کند.","en":"A physical network is made of cables and appliances such as switches and routers. An Azure VNet is a logical software-defined network whose address spaces, subnets, routes, and security controls run on Microsoft-managed infrastructure.","de":"Ein physisches Netzwerk besteht aus Kabeln und Geräten wie Switches und Routern. Ein Azure-VNet ist ein logisch softwaredefiniertes Netzwerk mit Adressräumen, Subnetzen, Routen und Sicherheitskontrollen auf von Microsoft verwalteter Infrastruktur."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"کدام عبارت شبکهٔ فیزیکی on-premises را با Azure Virtual Network مقایسه می‌کند؟","optionsFa":["مدیر Azure باید کابل‌های فیزیکی و Switchهای Datacenter مایکروسافت را مدیریت کند","شبکهٔ فیزیکی از Cable، Switch و Router استفاده می‌کند؛ Azure VNet روی زیرساخت مدیریت‌شدهٔ Microsoft، Address Space، Subnet، Route و کنترل امنیتی منطقی فراهم می‌کند","Azure VNet فقط یک DNS Zone است و نمی‌تواند ترافیک را Route کند","شبکهٔ فیزیکی و مجازی دقیقاً از Command و Failure Domain یکسان استفاده می‌کنند"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-overview","https://learn.microsoft.com/en-us/azure/virtual-network/concepts-and-best-practices"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-08T00:00:00.000Z"},"objective":"Implement hybrid network connectivity and security","objectiveId":"net-hybrid","topic":"Azure hybrid connectivity scenarios","difficulty":"easy","sourceRefs":["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-overview","https://learn.microsoft.com/en-us/azure/virtual-network/concepts-and-best-practices"],"keyPoints":["A physical network is operated through tangible links and network appliances.","An Azure VNet is software-defined and contains logical address spaces and subnets.","Azure manages the underlying datacenter infrastructure while the customer manages the virtual network configuration."],"whyOthers":["Customers do not operate the cables or Microsoft datacenter switching fabric.","","A VNet includes routing and traffic filtering capabilities in addition to private name-resolution integrations.","The commands, abstractions, and failure domains are not identical between physical and virtual networks."],"requirements":"The VNet still needs correct address planning, routes, NSGs, and gateway configuration. Abstracting the physical layer does not remove the need to troubleshoot the logical network.","commandPath":[{"label":"Inspect VNet address spaces and subnets","command":"az network vnet show --name app-vnet --resource-group rg-network --query '{spaces:addressSpace.addressPrefixes,subnets:subnets[].name}'"}],"translations":"runtime-google"},
{"id":"az802-q-410","domain":"Implement and manage on-premises and hybrid networking","text":"An Azure VM is attached to the correct VNet but cannot reach a VM in another subnet. There is no physical cable to replace. Which evidence should be checked first?","options":["The datacenter switch model and cable length","The effective routes and Network Security Group rules for the VM network interface and subnet","The monitor resolution of the administrator’s laptop","The DNS suffix only, even though the test uses an IP address"],"correct":1,"source":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-802","rationale":{"fa":"در VNet، مشکل بین Subnetها معمولاً با Effective Routes، User-Defined Route و NSG بررسی می‌شود. لایهٔ فیزیکی توسط Azure مدیریت می‌شود و برای تست با IP، DNS اولویت ندارد.","en":"In a VNet, inspect effective routes, user-defined routes, and NSG rules for the NIC and subnet. Azure manages the physical fabric, and DNS is not the first suspect when the test already uses an IP address.","de":"In einem VNet sollten zuerst effektive Routen, benutzerdefinierte Routentabellen und NSG-Regeln der Netzwerkkarte und des Subnetzes geprüft werden. Die physische Fabric verwaltet Azure; bei einem Test per IP ist DNS nicht die erste Vermutung."},"skillId":"security","reviewStatus":"technical-approved","isOriginal":true,"textFa":"یک VM در Azure به VNet درست متصل است، اما نمی‌تواند به VMای در Subnet دیگر برسد. کابل فیزیکی برای تعویض وجود ندارد. ابتدا کدام شواهد بررسی شود؟","optionsFa":["مدل Switch دیتاسنتر و طول Cable","Effective Routes و Ruleهای Network Security Group برای Network Interface و Subnet مربوط به VM","رزولوشن مانیتور Laptop مدیر","فقط DNS Suffix، حتی اگر تست با IP انجام شده باشد"],"audit":{"sourceRefs":["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-overview","https://learn.microsoft.com/en-us/azure/virtual-network/concepts-and-best-practices"],"sourceVerified":true,"answerVerified":true,"originalityVerified":true,"translationVerified":true,"distractorsReviewed":true,"reviewer":"source-relevance + distractor alignment checks","reviewedAt":"2026-10-08T00:00:00.000Z"},"objective":"Implement hybrid network connectivity and security","objectiveId":"net-hybrid","topic":"Azure hybrid connectivity scenarios","difficulty":"medium","sourceRefs":["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-overview","https://learn.microsoft.com/en-us/azure/virtual-network/concepts-and-best-practices"],"keyPoints":["Azure VNet troubleshooting is based on logical routes, subnet configuration, and security rules.","Effective routes show the combined system, custom, and propagated routes for the NIC.","An IP-based test bypasses DNS, so DNS is not the first check for this symptom."],"whyOthers":["The physical fabric is Microsoft-managed and is not diagnosed by replacing a customer switch cable.","","Screen resolution cannot affect packet routing.","DNS matters for names, but the test already targets an IP address."],"requirements":"Collect effective routes and NSG flow evidence before changing a route or security rule. Confirm the VM NIC, subnet, route table, and both directions of the required flow.","commandPath":[{"label":"Show the VM NIC effective routes","command":"az network nic show-effective-route-table --name vm01Nic --resource-group rg-network"},{"label":"Show effective NSG rules","command":"az network nic list-effective-nsg --name vm01Nic --resource-group rg-network"}],"translations":"runtime-google"},
 ];

/**
 * The authored AZ-802 bank. The fields used today are required; the enrichment
 * fields are optional so the bank can be completed domain by domain without
 * changing a single question ID, progress row, or audit manifest entry.
 */
export type Question = {
  id: string;
  domain: string;
  text: string;
  options: string[];
  correct: number;
  source: string;
  rationale: { fa: string; en: string; de: string };
  skillId: string;
  reviewStatus: string;
  isOriginal: boolean;
  /** Stored Persian text. Optional because questions marked
   * translations: "runtime-google" take their display translation from the site's
   * existing Google Translate flow rather than a stored field. */
  textFa?: string;
  /** Stored Persian options, aligned with `options`. Same runtime-translation
   * caveat as `textFa`. */
  optionsFa?: string[];
  audit: {
    sourceRefs: string[];
    sourceVerified: boolean;
    answerVerified: boolean;
    originalityVerified: boolean;
    translationVerified: boolean;
    distractorsReviewed: boolean;
    reviewer: string | null;
    reviewedAt: string | null;
  };
  /** Verbatim bullet from the official AZ-802 study guide that this item assesses. */
  objective?: string;
  /** Stable local slug for grouping and filters; not an official Microsoft objective number. */
  objectiveId?: string;
  /** Short topic label used by the domain -> topic -> question tree. */
  topic?: string;
  /** One of "easy", "medium", "hard". The bank is authored one JSON object per
   * line, so array-literal widening prevents a compile-time union here; both
   * scripts/validate-question-bank.mjs and scripts/validate-az802-coverage.mjs
   * enforce the allowed values. */
  difficulty?: string;
  /** Page-specific Microsoft Learn references that prove the answer. */
  sourceRefs?: string[];
  /** Scenario facts that determine the correct answer. */
  keyPoints?: string[];
  /** Index-aligned reasoning for every option; empty string at the correct index. */
  whyOthers?: string[];
  /** Windows Server version, prerequisites, or effective limits that change the answer. */
  requirements?: string;
  /** A real command or settings path; only where it genuinely clarifies the answer. */
  commandPath?: { label: string; command: string }[];
  /** Set to "runtime-google" when display translations come from the site's
   * existing Google Translate flow instead of stored Persian fields. Widened to
   * string for the same array-literal reason as difficulty; the validators
   * accept only the documented value. */
  translations?: string;
};

export const questions: Question[] = questionBank;

// Keep the first hybrid DNS distractor explicitly tied to its option text so
// the automated distractor audit can verify the per-option explanation.
const hybridDnsQuestion = questions.find((question) => question.id === "az802-q-406");
if (hybridDnsQuestion?.whyOthers) {
  hybridDnsQuestion.whyOthers[0] =
    "Replacing the VPN Gateway with ExpressRoute does not fix a name-only failure; verify the existing DNS path before changing connectivity.";
}





